# ---- UI display language (Qt Linguist, Raspberry-style) ----------------------
# Chosen in the menu bar (Language ▸ English / 简体中文 / 日本語), stored in
# ~/.broccoli_lang as 'system' / 'en' / 'zh_CN' / 'ja_JP', applied on restart.
# This is INDEPENDENT of Settings → Languages (the chat/content language list —
# model-generated dialog CONTENT keeps following that preference). The approval
# dialogs' chrome (titles / labels / buttons) follows THIS setting too, via
# ui_text()'s BROCCOLI_UI_TEXT_LANGUAGE_KEY (user decision 2026-07-24).
# Translations ship as i18n/broccoli_<lang>.qm.
BROCCOLI_LANG_PREF_FILE = os.path.expanduser('~/.broccoli_lang')
BROCCOLI_UI_LANGUAGES = [('en', 'English'), ('zh_CN', '简体中文'), ('ja_JP', '日本語')]


def read_ui_language_setting() -> str:
    try:
        if os.path.exists(BROCCOLI_LANG_PREF_FILE):
            value = open(BROCCOLI_LANG_PREF_FILE, 'r', encoding='utf-8').read().strip()
            if value in {'system', 'en', 'zh_CN', 'ja_JP'}:
                return value
    except Exception:
        pass
    return 'en'


def write_ui_language_setting(code: str) -> None:
    try:
        with open(BROCCOLI_LANG_PREF_FILE, 'w', encoding='utf-8') as handle:
            handle.write(str(code))
    except Exception:
        logging.exception('Failed to save UI language preference.')


def _broccoli_i18n_dirs() -> list:
    candidates = []
    if getattr(sys, 'frozen', False):
        meipass = getattr(sys, '_MEIPASS', '')
        if meipass:
            candidates.append(os.path.join(meipass, 'i18n'))
    candidates.append(os.path.join(os.path.dirname(os.path.abspath(__file__)), 'i18n'))
    candidates.append(os.path.join(BUNDLED_RESOURCES_DIR, 'i18n'))
    candidates.append(os.path.join(BROCCOLI_USER_RESOURCES_DIR, 'i18n'))
    return candidates


_BROCCOLI_TRANSLATORS = []  # keep references alive; Qt does not own them


def load_translation(qt_app, lang: str = None) -> None:
    if lang in (None, '', 'system'):
        lang = QLocale.system().name()  # e.g. 'zh_CN'
    lang = str(lang)
    if lang == 'en' or lang.startswith('en_'):
        return  # English is the source language; nothing to install
    qt_translator = QTranslator(qt_app)
    qt_translations_path = QLibraryInfo.path(QLibraryInfo.LibraryPath.TranslationsPath)
    if qt_translator.load('qt_' + lang, qt_translations_path):
        qt_app.installTranslator(qt_translator)
        _BROCCOLI_TRANSLATORS.append(qt_translator)
    app_translator = QTranslator(qt_app)
    for folder in _broccoli_i18n_dirs():
        qm_path = os.path.join(folder, 'broccoli_%s.qm' % lang)
        if os.path.exists(qm_path) and app_translator.load(qm_path):
            qt_app.installTranslator(app_translator)
            _BROCCOLI_TRANSLATORS.append(app_translator)
            break


BROCCOLI_UI_LANGUAGE = read_ui_language_setting()
load_translation(app, BROCCOLI_UI_LANGUAGE)


def broccoli_html_lang() -> str:
    """lang attribute for app-generated pages, matching the UI language in use.
    It decides Japanese vs Chinese glyph shapes for the same characters."""
    lang = BROCCOLI_UI_LANGUAGE
    if lang in (None, '', 'system'):
        lang = QLocale.system().name()
    lang = str(lang)
    if lang.startswith('zh'):
        return 'zh-CN'
    if lang.startswith('ja'):
        return 'ja'
    return 'en'


def _tr(text: str) -> str:
    """Translate a UI string via the installed Qt translator (context 'Broccoli').

    Used for BOTH the visible label and any `==` comparison against a dialog's
    returned button text, so both sides always resolve to the same translation."""
    return QCoreApplication.translate('Broccoli', text)


# Words a user may reply to a Claude Code / Codex approval or stall prompt with.
# The prompts are translated, and every reply word a translation asks for must be
# in these sets, in every UI language: anything not recognised as a denial counts
# as approval, so a Japanese "いいえ" missing here would approve the tool.
TERMINAL_REPLY_INTERRUPT_WORDS = frozenset({
    'interrupt', 'esc', 'escape', 'abort',
    '中断', '打断', '停止', '中止',
    'ストップ', '止めて', 'とめて',
})
