def _coerce_feature_flag_value(value, default: bool = False) -> bool:
    if isinstance(value, bool):
        return value
    if value is None:
        return bool(default)
    return str(value).strip().lower() in {'1', 'true', 'yes', 'on'}


def default_icloud_feature_flags() -> dict:
    return {name: bool(default) for name, _symbol, default, _label, _tooltip in ICLOUD_FEATURE_FLAG_SPECS}


def normalize_icloud_feature_flags(value) -> dict:
    raw = value if isinstance(value, dict) else {}
    return {
        name: _coerce_feature_flag_value(raw.get(name), default)
        for name, _symbol, default, _label, _tooltip in ICLOUD_FEATURE_FLAG_SPECS
    }


ICLOUD_FEATURE_FLAG_DEFAULTS_REV = 2
# rev 2 (user decision): the six remote features ship ON by default. Stores
# saved before rev 2 hold False that came from the OLD defaults, not from a
# choice — flip exactly these six once; a post-upgrade uncheck sticks because
# the stored rev is then already current. High-privilege approval never flips.
_ICLOUD_FLAGS_REV2_ON = (
    'BROCCOLI_M3_TRANSPORT', 'BROCCOLI_M4A_MOVE_SEND', 'BROCCOLI_M4B_MIGRATION',
    'BROCCOLI_M5_REMOTE_LIFECYCLE', 'BROCCOLI_M6_NOTES_SHORTCUTS', 'BROCCOLI_M7_UNIFIED_HISTORY',
)


def apply_icloud_flag_defaults_rev(flags: dict, stored_rev) -> dict:
    try:
        rev = int(stored_rev or 0)
    except Exception:
        rev = 0
    if rev >= ICLOUD_FEATURE_FLAG_DEFAULTS_REV:
        return flags
    for name in _ICLOUD_FLAGS_REV2_ON:
        flags[name] = True
    return flags


def _read_persisted_icloud_feature_flags() -> dict:
    # Feature constants are resolved during module import, before the regular
    # settings helpers are declared. Read only this narrow globals field here;
    # normal Settings I/O continues to use load_settings_store/save_settings_store.
    path = os.path.join(BROCCOLI_APP_DATA_DIR, 'settings_profiles.json')
    try:
        with open(path, 'r', encoding='utf-8') as handle:
            payload = json.load(handle)
        globals_store = payload.get('globals') if isinstance(payload, dict) else {}
        raw = globals_store.get('icloud_feature_flags') if isinstance(globals_store, dict) else {}
        rev = globals_store.get('icloud_flags_defaults_rev') if isinstance(globals_store, dict) else 0
        return apply_icloud_flag_defaults_rev(normalize_icloud_feature_flags(raw), rev)
    except Exception:
        return {}


_PERSISTED_ICLOUD_FEATURE_FLAGS = _read_persisted_icloud_feature_flags()


def _broccoli_feature_flag(name: str, default: bool = True) -> bool:
    # Explicit environment values remain the highest-priority test/deployment
    # override. Otherwise the visible Settings checkbox is authoritative.
    if name in os.environ:
        return _coerce_feature_flag_value(os.environ.get(name), default)
    if name in _PERSISTED_ICLOUD_FEATURE_FLAGS:
        return _coerce_feature_flag_value(_PERSISTED_ICLOUD_FEATURE_FLAGS.get(name), default)
    return bool(default)


# M1a stays split into independently reversible pieces. They can now be managed
# in Settings > General page 3; environment variables remain emergency/test
# overrides and do not get rewritten by the UI.
# Resolved from ICLOUD_FEATURE_FLAG_SPECS — the spec table is the single source
# of truth for names, symbols AND defaults (a previous hand-written copy of the
# fifteen assignments silently kept stale defaults when the spec changed).
# The assignments below stay explicit (not a globals() loop) so static analysis
# in the IDE can see every symbol; the env name and default still come from the
# spec row, and the check that follows fails loudly if a spec row has no line.
def _icloud_flag_by_symbol(symbol: str) -> bool:
    for name, spec_symbol, default, _label, _tooltip in ICLOUD_FEATURE_FLAG_SPECS:
        if spec_symbol == symbol:
            return _broccoli_feature_flag(name, default)
    raise KeyError(f'{symbol} is not declared in ICLOUD_FEATURE_FLAG_SPECS')


