def reload_icloud_feature_flags_from_settings() -> dict:
    global _PERSISTED_ICLOUD_FEATURE_FLAGS
    _PERSISTED_ICLOUD_FEATURE_FLAGS = _read_persisted_icloud_feature_flags()
    effective = {}
    for name, symbol, default, _label, _tooltip in ICLOUD_FEATURE_FLAG_SPECS:
        value = _broccoli_feature_flag(name, default)
        globals()[symbol] = value
        effective[name] = value
    return effective


BROCCOLI_LOCAL_USER_ID = str(os.environ.get('BROCCOLI_LOCAL_USER_ID', 'local-owner') or 'local-owner').strip()
BROCCOLI_LOCAL_MEMBER_ID = str(os.environ.get('BROCCOLI_LOCAL_MEMBER_ID', BROCCOLI_LOCAL_USER_ID) or BROCCOLI_LOCAL_USER_ID).strip()
BROCCOLI_DEVICE_IDENTITY_PATH = os.path.join(BROCCOLI_APP_DATA_DIR, 'device_identity.json')


def broccoli_host_fingerprint() -> str:
    """Short hash of this Mac's hardware UUID (gethostuuid); '' when unavailable."""
    try:
        import ctypes
        libc = ctypes.CDLL('/usr/lib/libSystem.B.dylib')
        buffer = ctypes.create_string_buffer(16)
        wait = (ctypes.c_long * 2)(1, 0)  # struct timespec: 1 s, 0 ns
        if libc.gethostuuid(buffer, wait) != 0:
            return ''
        return hashlib.sha256(buffer.raw).hexdigest()[:16]
    except Exception:
        return ''


def resolve_broccoli_local_device_id(identity_path: str | None = None,
                                     *,
                                     nodename: str | None = None,
                                     host_fingerprint: str | None = None) -> str:
    """Stable id of this Mac in the iCloud protocol (its inbox, the conversations it
    owns, its canonical folders).

    It used to be the live host name, which macOS changes on a name clash ("…-2")
    and on some networks; each change orphaned this Mac's inbox and everything it
    owned. The id is now fixed once and stored:
    - first run: the current host name, so existing data keeps matching;
    - a stored file from another Mac (app data copied over, hardware differs): a
      new id made distinct by this Mac's hardware fingerprint.
    BROCCOLI_LOCAL_DEVICE_ID still overrides it (tests, deployments).
    """
    override = str(os.environ.get('BROCCOLI_LOCAL_DEVICE_ID', '') or '').strip()
    if override:
        return override
    path = str(identity_path or BROCCOLI_DEVICE_IDENTITY_PATH)
    if nodename is None:
        nodename = str(getattr(os.uname(), 'nodename', '') or '')
    nodename = str(nodename or '').strip() or 'local-device'
    fingerprint = broccoli_host_fingerprint() if host_fingerprint is None else str(host_fingerprint or '')
    try:
        with open(path, 'r', encoding='utf-8') as handle:
            stored = json.load(handle)
    except Exception:
        stored = {}
    stored = stored if isinstance(stored, dict) else {}
    stored_id = str(stored.get('device_id', '') or '').strip()
    stored_fingerprint = str(stored.get('host_fingerprint', '') or '')
    if stored_id and (not stored_fingerprint or not fingerprint or stored_fingerprint == fingerprint):
        if fingerprint and not stored_fingerprint:
            stored['host_fingerprint'] = fingerprint
        else:
            return stored_id
        device_id = stored_id
    elif stored_id:
        suffix = fingerprint[:8] if fingerprint else uuid.uuid4().hex[:8]
        device_id = f'{nodename}-{suffix}'
        stored = {'copied_from_device_id': stored_id}
    else:
        device_id = nodename
        stored = {}
    stored.update({
        'device_id': device_id,
        'host_fingerprint': fingerprint,
        'updated_at': datetime.datetime.now().isoformat(timespec='seconds'),
    })
    stored.setdefault('created_at', stored['updated_at'])
    try:
        os.makedirs(os.path.dirname(path), exist_ok=True)
        temporary = f'{path}.tmp-{os.getpid()}'
        with open(temporary, 'w', encoding='utf-8') as handle:
            json.dump(stored, handle, ensure_ascii=False, indent=2)
        os.replace(temporary, path)
    except Exception:
        logging.exception('Could not store the device identity; using it for this run only.')
    return device_id


def broccoli_local_device_display_name() -> str:
    """Human name shown in other devices' pickers (System Settings > Computer Name)."""
    name = ''
    try:
        name = subprocess.run(
            ['/usr/sbin/scutil', '--get', 'ComputerName'],
            capture_output=True, text=True, timeout=2,
        ).stdout.strip()
    except Exception:
        name = ''
    if not name:
        name = str(getattr(os.uname(), 'nodename', '') or '').strip()
        if name.endswith('.local'):
            name = name[:-len('.local')]
    return name or BROCCOLI_LOCAL_DEVICE_ID


BROCCOLI_LOCAL_HOST_FINGERPRINT = broccoli_host_fingerprint()
BROCCOLI_LOCAL_DEVICE_ID = resolve_broccoli_local_device_id(host_fingerprint=BROCCOLI_LOCAL_HOST_FINGERPRINT)


