def _task_store_json_safe(value):
    """Return a stable JSON-compatible snapshot without retaining live Qt objects."""
    if value is None or isinstance(value, (str, int, float, bool)):
        return value
    if isinstance(value, dict):
        return {
            str(key): _task_store_json_safe(item)
            for key, item in value.items()
            if str(key) not in {
                'event', 'thread', 'signals', 'preflight_thread', 'chat_thread',
                'browser_use_thread', 'computer_use_thread', 'external_terminal_thread',
                'editor', 'panel', 'dialog',
            }
        }
    if isinstance(value, (list, tuple, set)):
        return [_task_store_json_safe(item) for item in value]
    if isinstance(value, Path):
        return str(value)
    return repr(value)


def _task_store_json(value) -> str:
    return json.dumps(_task_store_json_safe(value), ensure_ascii=False, sort_keys=True)


class ShadowTaskStore:
    """M1b record-only SQLite ledger.

    The live Agent machinery remains the sole scheduler. This store observes its
    durable identities and checkpoints so later milestones can recover them,
    but none of these rows are read back into execution in M1b.
    """

    TERMINAL_STATES = {
        'completed', 'finished', 'failed', 'cancelled', 'rejected',
        'needs_reconciliation', 'stopped',
    }

    def __init__(self, path: str):
        self.path = os.path.abspath(os.path.expanduser(str(path or '')))
        if not self.path:
            raise ValueError('ShadowTaskStore requires a database path.')
        self._lock = threading.RLock()
        os.makedirs(os.path.dirname(self.path), exist_ok=True)
        self._connection = sqlite3.connect(
            self.path,
            timeout=5.0,
            check_same_thread=False,
            isolation_level=None,
        )
        self._connection.row_factory = sqlite3.Row
        with self._lock:
            self._connection.execute('PRAGMA journal_mode=WAL')
            self._connection.execute('PRAGMA synchronous=FULL')
            self._connection.execute('PRAGMA foreign_keys=ON')
            self._connection.execute('PRAGMA busy_timeout=5000')
            self._create_schema()

    def _create_schema(self):
        self._connection.executescript(
            """
            CREATE TABLE IF NOT EXISTS tasks (
                task_id TEXT PRIMARY KEY,
                conversation_id TEXT NOT NULL DEFAULT '',
                conversation_path TEXT NOT NULL DEFAULT '',
                state TEXT NOT NULL DEFAULT 'running',
                source TEXT NOT NULL DEFAULT 'local',
                user_id TEXT NOT NULL DEFAULT '',
                member_id TEXT NOT NULL DEFAULT '',
                origin_device_id TEXT NOT NULL DEFAULT '',
                envelope_json TEXT NOT NULL DEFAULT '{}',
                created_at TEXT NOT NULL,
                updated_at TEXT NOT NULL
            );
            CREATE TABLE IF NOT EXISTS attempts (
                attempt_id TEXT PRIMARY KEY,
                task_id TEXT NOT NULL,
                run_id TEXT NOT NULL UNIQUE,
                phase TEXT NOT NULL DEFAULT '',
                state TEXT NOT NULL DEFAULT 'running',
                checkpoint_json TEXT NOT NULL DEFAULT '{}',
                created_at TEXT NOT NULL,
                updated_at TEXT NOT NULL,
                UNIQUE(task_id, attempt_id),
                FOREIGN KEY(task_id) REFERENCES tasks(task_id) ON DELETE CASCADE
            );
            CREATE INDEX IF NOT EXISTS attempts_task_id_idx ON attempts(task_id);
            CREATE INDEX IF NOT EXISTS attempts_state_idx ON attempts(state);
            CREATE TABLE IF NOT EXISTS events (
                event_id TEXT PRIMARY KEY,
                task_id TEXT NOT NULL,
                attempt_id TEXT NOT NULL DEFAULT '',
                event_type TEXT NOT NULL,
                producer_id TEXT NOT NULL,
                producer_seq TEXT NOT NULL,
                payload_json TEXT NOT NULL DEFAULT '{}',
                created_at TEXT NOT NULL,
                UNIQUE(producer_id, producer_seq),
                FOREIGN KEY(task_id) REFERENCES tasks(task_id) ON DELETE CASCADE
            );
            CREATE INDEX IF NOT EXISTS events_task_id_idx ON events(task_id);
            CREATE TABLE IF NOT EXISTS approvals (
                action_id TEXT PRIMARY KEY,
                task_id TEXT NOT NULL DEFAULT '',
                attempt_id TEXT NOT NULL DEFAULT '',
                approval_kind TEXT NOT NULL DEFAULT '',
                state TEXT NOT NULL DEFAULT 'pending',
                payload_json TEXT NOT NULL DEFAULT '{}',
                created_at TEXT NOT NULL,
                updated_at TEXT NOT NULL
            );
            CREATE TABLE IF NOT EXISTS outbox (
                outbox_id TEXT PRIMARY KEY,
                event_id TEXT NOT NULL DEFAULT '',
                state TEXT NOT NULL DEFAULT 'pending',
                payload_json TEXT NOT NULL DEFAULT '{}',
                retry_count INTEGER NOT NULL DEFAULT 0,
                next_retry_at TEXT NOT NULL DEFAULT '',
                created_at TEXT NOT NULL,
                updated_at TEXT NOT NULL
            );
            CREATE TABLE IF NOT EXISTS queue_items (
                queue_id TEXT PRIMARY KEY,
                conversation_id TEXT NOT NULL DEFAULT '',
                task_id TEXT NOT NULL DEFAULT '',
                state TEXT NOT NULL DEFAULT 'waiting',
                position INTEGER NOT NULL DEFAULT 0,
                payload_json TEXT NOT NULL DEFAULT '{}',
                created_at TEXT NOT NULL,
                updated_at TEXT NOT NULL
            );
            CREATE INDEX IF NOT EXISTS queue_conversation_idx
                ON queue_items(conversation_id, position);
            CREATE TABLE IF NOT EXISTS plan_events (
                event_id TEXT PRIMARY KEY,
                run_id TEXT NOT NULL DEFAULT '',
                task_id TEXT NOT NULL DEFAULT '',
                state TEXT NOT NULL DEFAULT 'running',
                payload_json TEXT NOT NULL DEFAULT '{}',
                created_at TEXT NOT NULL,
                updated_at TEXT NOT NULL
            );
            """
        )

    def _transaction(self, callback):
        with self._lock:
            self._connection.execute('BEGIN IMMEDIATE')
            try:
                result = callback(self._connection)
                self._connection.execute('COMMIT')
                return result
            except Exception:
                self._connection.execute('ROLLBACK')
                raise

    def observe_run(self, run: dict) -> tuple[str, str]:
        if not isinstance(run, dict):
            raise TypeError('observe_run requires a run dictionary.')
        config = run.get('config') if isinstance(run.get('config'), dict) else {}
        run_id = str(run.get('run_id', '') or config.get('run_id', '') or '').strip()
        if not run_id:
            raise ValueError('Observed run requires run_id.')
        now = datetime.datetime.now().isoformat(timespec='milliseconds')
        with self._lock:
            previous = self._connection.execute(
                'SELECT task_id, attempt_id FROM attempts WHERE run_id = ?',
                (run_id,),
            ).fetchone()
        task_id = str(
            run.get('task_id', '') or config.get('task_id', '') or
            ((previous['task_id'] if previous is not None else '') or '') or
            new_broccoli_uuid('task-')
        )
        attempt_id = str(
            run.get('attempt_id', '') or config.get('attempt_id', '') or
            ((previous['attempt_id'] if previous is not None else '') or '') or
            new_broccoli_uuid('attempt-')
        )
        run['task_id'] = task_id
        run['attempt_id'] = attempt_id
        config['task_id'] = task_id
        config['attempt_id'] = attempt_id
        run['config'] = config
        path = str(run.get('conversation_path', '') or config.get('conversation_path', '') or '')
        conversation_id = str(
            run.get('conversation_id', '') or config.get('conversation_id', '') or
            (os.path.splitext(os.path.basename(path))[0] if path else '')
        )
        state = str(run.get('status', '') or 'running')
        phase = str(run.get('phase', '') or 'chat')
        source = str(config.get('queued_source', '') or config.get('source', '') or 'local')
        created_at = str(run.get('started_at', '') or now)
        envelope = {
            'question_text': str(run.get('question_text', '') or config.get('question_text', '') or ''),
            'config': config,
        }
        checkpoint = {
            'status_lines': list(run.get('status_lines') or []),
            'progress_lines': list(run.get('progress_lines') or []),
            'answer': str(run.get('answer', '') or ''),
        }

        def write(conn):
            conn.execute(
                """INSERT INTO tasks(
                       task_id, conversation_id, conversation_path, state, source,
                       user_id, member_id, origin_device_id, envelope_json, created_at, updated_at
                   ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                   ON CONFLICT(task_id) DO UPDATE SET
                       conversation_id=excluded.conversation_id,
                       conversation_path=excluded.conversation_path,
                       state=excluded.state,
                       source=excluded.source,
                       user_id=excluded.user_id,
                       member_id=excluded.member_id,
                       origin_device_id=excluded.origin_device_id,
                       envelope_json=excluded.envelope_json,
                       updated_at=excluded.updated_at""",
                (
                    task_id, conversation_id, path, state, source,
                    str(config.get('user_id', '') or ''),
                    str(config.get('member_id', '') or ''),
                    str(config.get('origin_device_id', '') or ''),
                    _task_store_json(envelope), created_at, now,
                ),
            )
            conn.execute(
                """INSERT INTO attempts(
                       attempt_id, task_id, run_id, phase, state, checkpoint_json, created_at, updated_at
                   ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
                   ON CONFLICT(attempt_id) DO UPDATE SET
                       task_id=excluded.task_id,
                       run_id=excluded.run_id,
                       phase=excluded.phase,
                       state=excluded.state,
                       checkpoint_json=excluded.checkpoint_json,
                       updated_at=excluded.updated_at""",
                (attempt_id, task_id, run_id, phase, state, _task_store_json(checkpoint), created_at, now),
            )
        self._transaction(write)
        return task_id, attempt_id

    def update_run(self, run: dict):
        return self.observe_run(run)

    def persist_queue(self, conversation_id: str, items: list[dict]):
        conversation_id = str(conversation_id or '').strip()
        now = datetime.datetime.now().isoformat(timespec='milliseconds')
        normalized = [dict(item) for item in (items or []) if isinstance(item, dict)]

        def write(conn):
            keep = []
            for position, item in enumerate(normalized, start=1):
                queue_id = str(item.get('id', '') or item.get('queue_id', '') or new_broccoli_uuid('queue-'))
                item['id'] = queue_id
                keep.append(queue_id)
                conn.execute(
                    """INSERT INTO queue_items(
                           queue_id, conversation_id, task_id, state, position,
                           payload_json, created_at, updated_at
                       ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
                       ON CONFLICT(queue_id) DO UPDATE SET
                           conversation_id=excluded.conversation_id,
                           task_id=excluded.task_id,
                           state=excluded.state,
                           position=excluded.position,
                           payload_json=excluded.payload_json,
                           updated_at=excluded.updated_at""",
                    (
                        queue_id, conversation_id, str(item.get('task_id', '') or ''),
                        str(item.get('status', '') or item.get('state', '') or 'waiting'),
                        position, _task_store_json(item),
                        str(item.get('created_at', '') or now), now,
                    ),
                )
            if keep:
                placeholders = ','.join('?' for _ in keep)
                conn.execute(
                    f'DELETE FROM queue_items WHERE conversation_id = ? AND queue_id NOT IN ({placeholders})',
                    [conversation_id, *keep],
                )
            else:
                conn.execute('DELETE FROM queue_items WHERE conversation_id = ?', (conversation_id,))
        self._transaction(write)

    def load_queue(self, conversation_id: str) -> list[dict]:
        with self._lock:
            rows = self._connection.execute(
                'SELECT payload_json FROM queue_items WHERE conversation_id = ? ORDER BY position',
                (str(conversation_id or ''),),
            ).fetchall()
        return [json.loads(row['payload_json']) for row in rows]

    def persist_plan_event(self, event: dict):
        if not isinstance(event, dict):
            return
        event_id = str(event.get('event_id', '') or '').strip()
        if not event_id:
            return
        now = datetime.datetime.now().isoformat(timespec='milliseconds')
        with self._lock:
            attempt = self._connection.execute(
                'SELECT task_id FROM attempts WHERE run_id = ?',
                (str(event.get('run_id', '') or ''),),
            ).fetchone()
        task_id = str(event.get('task_id', '') or ((attempt['task_id'] if attempt else '') or ''))

        def write(conn):
            conn.execute(
                """INSERT INTO plan_events(
                       event_id, run_id, task_id, state, payload_json, created_at, updated_at
                   ) VALUES (?, ?, ?, ?, ?, ?, ?)
                   ON CONFLICT(event_id) DO UPDATE SET
                       run_id=excluded.run_id,
                       task_id=excluded.task_id,
                       state=excluded.state,
                       payload_json=excluded.payload_json,
                       updated_at=excluded.updated_at""",
                (
                    event_id, str(event.get('run_id', '') or ''), task_id,
                    str(event.get('status', '') or 'running'), _task_store_json(event),
                    str(event.get('created_at', '') or now), now,
                ),
            )
        self._transaction(write)

    def persist_approval(self, approval: dict):
        if not isinstance(approval, dict):
            return
        action_id = str(
            approval.get('action_id', '') or approval.get('id', '') or
            approval.get('permission_key', '') or new_broccoli_uuid('action-')
        )
        approval['action_id'] = action_id
        now = datetime.datetime.now().isoformat(timespec='milliseconds')

        def write(conn):
            conn.execute(
                """INSERT INTO approvals(
                       action_id, task_id, attempt_id, approval_kind, state,
                       payload_json, created_at, updated_at
                   ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
                   ON CONFLICT(action_id) DO UPDATE SET
                       task_id=excluded.task_id,
                       attempt_id=excluded.attempt_id,
                       approval_kind=excluded.approval_kind,
                       state=excluded.state,
                       payload_json=excluded.payload_json,
                       updated_at=excluded.updated_at""",
                (
                    action_id, str(approval.get('task_id', '') or ''),
                    str(approval.get('attempt_id', '') or ''),
                    str(approval.get('approval_kind', '') or approval.get('kind', '') or ''),
                    str(approval.get('state', '') or approval.get('decision', '') or 'pending'),
                    _task_store_json(approval), str(approval.get('created_at', '') or now), now,
                ),
            )
        self._transaction(write)
        return action_id

    def append_event(self, event: dict) -> bool:
        if not isinstance(event, dict):
            return False
        now = datetime.datetime.now().isoformat(timespec='milliseconds')
        producer_id = str(event.get('producer_id', '') or 'local')
        producer_seq = str(event.get('producer_seq', '') or event.get('event_id', '') or new_broccoli_uuid())
        event_id = str(event.get('event_id', '') or new_broccoli_uuid('event-'))
        with self._lock:
            cursor = self._connection.execute(
                """INSERT OR IGNORE INTO events(
                       event_id, task_id, attempt_id, event_type, producer_id,
                       producer_seq, payload_json, created_at
                   ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)""",
                (
                    event_id, str(event.get('task_id', '') or ''),
                    str(event.get('attempt_id', '') or ''),
                    str(event.get('event_type', '') or event.get('type', '') or 'event'),
                    producer_id, producer_seq, _task_store_json(event), now,
                ),
            )
            return bool(cursor.rowcount)

    def enqueue_outbox(self, item: dict) -> str:
        item = dict(item or {})
        outbox_id = str(item.get('outbox_id', '') or new_broccoli_uuid('outbox-'))
        now = datetime.datetime.now().isoformat(timespec='milliseconds')
        with self._lock:
            self._connection.execute(
                """INSERT INTO outbox(
                       outbox_id, event_id, state, payload_json, retry_count,
                       next_retry_at, created_at, updated_at
                   ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
                   ON CONFLICT(outbox_id) DO UPDATE SET
                       state=excluded.state,
                       payload_json=excluded.payload_json,
                       retry_count=excluded.retry_count,
                       next_retry_at=excluded.next_retry_at,
                       updated_at=excluded.updated_at""",
                (
                    outbox_id, str(item.get('event_id', '') or ''),
                    str(item.get('state', '') or 'pending'), _task_store_json(item),
                    int(item.get('retry_count', 0) or 0), str(item.get('next_retry_at', '') or ''),
                    str(item.get('created_at', '') or now), now,
                ),
            )
        return outbox_id

    def register_remote_attempt(self, request: dict) -> tuple[bool, dict]:
        """Idempotently project one received TaskRequest into Task/Attempt rows."""
        request = dict(request or {})
        task_id = str(request.get('task_id', '') or '').strip()
        attempt_id = str(request.get('attempt_id', '') or '').strip()
        if not task_id or not attempt_id:
            raise ValueError('Remote TaskRequest requires task_id and attempt_id.')
        with self._lock:
            existed = self._connection.execute(
                'SELECT 1 FROM attempts WHERE attempt_id = ?',
                (attempt_id,),
            ).fetchone() is not None
        run_id = str(request.get('run_id', '') or f'remote-{attempt_id}')
        run = {
            'run_id': run_id,
            'task_id': task_id,
            'attempt_id': attempt_id,
            'conversation_id': str(request.get('conversation_id', '') or ''),
            'conversation_path': '',
            'phase': 'received',
            'status': 'received',
            'question_text': str(request.get('question', '') or ''),
            'started_at': str(request.get('created_at', '') or datetime.datetime.now().isoformat(timespec='seconds')),
            'config': {
                **request,
                'run_id': run_id,
                'task_id': task_id,
                'attempt_id': attempt_id,
                'source': 'remote',
            },
        }
        if existed:
            # The request file stays in the inbox and is seen on every scan.
            # Projecting it again reset finished attempts to 'received', so queued
            # work never saw its dependency finish and late cancels looked live.
            return False, run
        self.observe_run(run)
        return True, run

    def attempt_exists(self, attempt_id: str) -> bool:
        with self._lock:
            return self._connection.execute(
                'SELECT 1 FROM attempts WHERE attempt_id = ?',
                (str(attempt_id or ''),),
            ).fetchone() is not None

    def outbox_items(self, state: str = '') -> list[dict]:
        query = 'SELECT * FROM outbox'
        params = []
        if str(state or '').strip():
            query += ' WHERE state = ?'
            params.append(str(state or '').strip())
        query += ' ORDER BY created_at'
        with self._lock:
            rows = self._connection.execute(query, params).fetchall()
        return [dict(row) for row in rows]

    def attempt_record(self, attempt_id: str) -> dict | None:
        with self._lock:
            row = self._connection.execute(
                """SELECT a.*, t.conversation_id, t.conversation_path, t.envelope_json
                   FROM attempts a JOIN tasks t ON t.task_id = a.task_id
                   WHERE a.attempt_id = ?""",
                (str(attempt_id or ''),),
            ).fetchone()
        if row is None:
            return None
        result = dict(row)
        for key in ('checkpoint_json', 'envelope_json'):
            try:
                result[key[:-5]] = json.loads(result.get(key, '') or '{}')
            except Exception:
                result[key[:-5]] = {}
        return result

    def update_attempt_state(self, attempt_id: str, state: str, checkpoint_updates: dict | None = None) -> bool:
        current = self.attempt_record(attempt_id)
        if current is None:
            return False
        checkpoint = current.get('checkpoint') if isinstance(current.get('checkpoint'), dict) else {}
        checkpoint = dict(checkpoint)
        checkpoint.update(_task_store_json_safe(dict(checkpoint_updates or {})))
        now = datetime.datetime.now().isoformat(timespec='milliseconds')

        def write(conn):
            conn.execute(
                'UPDATE attempts SET state = ?, checkpoint_json = ?, updated_at = ? WHERE attempt_id = ?',
                (str(state or ''), _task_store_json(checkpoint), now, str(attempt_id or '')),
            )
            conn.execute(
                'UPDATE tasks SET state = ?, updated_at = ? WHERE task_id = ?',
                (str(state or ''), now, str(current.get('task_id', '') or '')),
            )
        self._transaction(write)
        return True

    def task_state(self, task_id: str) -> str:
        with self._lock:
            row = self._connection.execute(
                'SELECT state FROM tasks WHERE task_id = ?',
                (str(task_id or ''),),
            ).fetchone()
        return str(row['state'] if row is not None else '')

    def recover_incomplete_attempts(self) -> list[dict]:
        terminals = sorted(self.TERMINAL_STATES)
        placeholders = ','.join('?' for _ in terminals)
        with self._lock:
            rows = self._connection.execute(
                f"""SELECT a.*, t.conversation_id, t.conversation_path
                    FROM attempts a JOIN tasks t ON t.task_id = a.task_id
                    WHERE a.state NOT IN ({placeholders}) ORDER BY a.created_at""",
                terminals,
            ).fetchall()
        return [dict(row) for row in rows]

    def count(self, table: str) -> int:
        allowed = {'tasks', 'attempts', 'events', 'approvals', 'outbox', 'queue_items', 'plan_events'}
        if table not in allowed:
            raise ValueError('Unsupported Task Store table.')
        with self._lock:
            return int(self._connection.execute(f'SELECT COUNT(*) FROM {table}').fetchone()[0])

    def close(self):
        with self._lock:
            if self._connection is not None:
                self._connection.close()
                self._connection = None


def get_shadow_task_store(path: str | None = None) -> ShadowTaskStore | None:
    """Lazily create the M1b ledger; disabled means literally no filesystem I/O."""
    global _SHADOW_TASK_STORE
    if not ICLOUD_M1B_SHADOW_TASK_STORE_ENABLED:
        return None
    requested = os.path.abspath(os.path.expanduser(str(path or SHADOW_TASK_STORE_PATH)))
    with _SHADOW_TASK_STORE_LOCK:
        if _SHADOW_TASK_STORE is not None and _SHADOW_TASK_STORE.path != requested:
            _SHADOW_TASK_STORE.close()
            _SHADOW_TASK_STORE = None
        if _SHADOW_TASK_STORE is None:
            _SHADOW_TASK_STORE = ShadowTaskStore(requested)
        return _SHADOW_TASK_STORE


def reset_shadow_task_store_for_tests():
    global _SHADOW_TASK_STORE
    with _SHADOW_TASK_STORE_LOCK:
        if _SHADOW_TASK_STORE is not None:
            _SHADOW_TASK_STORE.close()
        _SHADOW_TASK_STORE = None


def _shadow_store_call(method: str, *args, **kwargs):
    if not ICLOUD_M1B_SHADOW_TASK_STORE_ENABLED:
        return None
    try:
        store = get_shadow_task_store()
        callback = getattr(store, method) if store is not None else None
        return callback(*args, **kwargs) if callable(callback) else None
    except Exception:
        logging.exception('M1b shadow Task Store observation failed: %s', method)
        return None


# ── 每 run 事件日志（方案3：影子模式，只写不读）──────────────────────
# 借鉴 DeepSeek Harness 的会话账本思想：每个 agent run 一个只追加的 JSONL
# 文件（~/BroccoliAppPath/AgentRunEvents/<run_id>.jsonl），记录 run 生命周期、
# planner 输入输出、每步 start/result、审批和最终回答阶段的工具调用。
# 现阶段是纯影子账本：任何写失败都被吞掉，绝不影响 run 本身；也没有读取方。
# 之后的录制回放、诊断、iCloud 远程同步在它之上再建。
# 事件封套：{"seq", "time"(epoch 毫秒), "pid", "run_id", "type", "data"}。
# seq 是"每进程 × 每 run"的单调序号；同一 run 跨进程续写时 seq 会重新从 1
# 开始，用 (pid, seq, time) 联合排序即可重建全序。
AGENT_RUN_EVENT_LOG_DIRNAME = 'AgentRunEvents'
AGENT_RUN_EVENT_LOG_KEEP_FILES = 200
AGENT_RUN_EVENT_LOG_MAX_TOTAL_BYTES = 200 * 1024 * 1024
AGENT_RUN_EVENT_LOG_FILE_CAP = 20 * 1024 * 1024
AGENT_RUN_EVENT_STRING_CAP = 4000
AGENT_RUN_EVENT_CONTAINER_CAP = 60
AGENT_RUN_EVENT_DEPTH_CAP = 6
_AGENT_RUN_EVENT_LOCK = threading.RLock()
_AGENT_RUN_EVENT_SEQ = {}
_AGENT_RUN_EVENT_CAPPED = set()


def agent_run_event_log_enabled() -> bool:
    try:
        store = load_settings_store()
        return bool(store.get('globals', {}).get('agent_run_event_log_enabled', True))
    except Exception:
        return True


def agent_run_event_log_root() -> str:
    return os.path.join(BROCCOLI_APP_DATA_DIR, AGENT_RUN_EVENT_LOG_DIRNAME)


def agent_run_event_log_path(run_id: str) -> str:
    slug = re.sub(r'[^a-zA-Z0-9_-]+', '-', str(run_id or '')).strip('-')[:80]
    return os.path.join(agent_run_event_log_root(), f'{slug}.jsonl')


def _agent_run_event_json_safe(value, depth: int = 0):
    """截断式 JSON 安全化：字符串封顶、容器限长限深、其余转 str。
    审批载荷可能带整份编辑器文件文本，全靠这里兜住体积。"""
    if depth >= AGENT_RUN_EVENT_DEPTH_CAP:
        return '<depth capped>'
    if value is None or isinstance(value, (bool, int, float)):
        return value
    if isinstance(value, str):
        if len(value) > AGENT_RUN_EVENT_STRING_CAP:
            return value[:AGENT_RUN_EVENT_STRING_CAP] + f'…[truncated {len(value) - AGENT_RUN_EVENT_STRING_CAP} chars]'
        return value
    if isinstance(value, bytes):
        return f'<{len(value)} bytes>'
    if isinstance(value, dict):
        safe = {}
        for index, (key, item) in enumerate(value.items()):
            if index >= AGENT_RUN_EVENT_CONTAINER_CAP:
                safe['…'] = f'<{len(value) - AGENT_RUN_EVENT_CONTAINER_CAP} more keys truncated>'
                break
            safe[str(key)] = _agent_run_event_json_safe(item, depth + 1)
        return safe
    if isinstance(value, (list, tuple, set, frozenset)):
        items = list(value)
        safe_items = [
            _agent_run_event_json_safe(item, depth + 1)
            for item in items[:AGENT_RUN_EVENT_CONTAINER_CAP]
        ]
        if len(items) > AGENT_RUN_EVENT_CONTAINER_CAP:
            safe_items.append(f'<{len(items) - AGENT_RUN_EVENT_CONTAINER_CAP} more items truncated>')
        return safe_items
    return str(value)


def prune_agent_run_event_logs() -> None:
    """新 run 建档时触发：按文件数和总字节数上限删最旧的日志文件。"""
    try:
        root = agent_run_event_log_root()
        entries = []
        for name in os.listdir(root):
            if not name.endswith('.jsonl'):
                continue
            path = os.path.join(root, name)
            try:
                stat = os.stat(path)
            except OSError:
                continue
            entries.append((stat.st_mtime, stat.st_size, path))
        entries.sort(reverse=True)
        total = 0
        for index, (_mtime, size, path) in enumerate(entries):
            total += size
            if index >= AGENT_RUN_EVENT_LOG_KEEP_FILES or total > AGENT_RUN_EVENT_LOG_MAX_TOTAL_BYTES:
                try:
                    os.unlink(path)
                except OSError:
                    pass
    except Exception:
        pass


def append_agent_run_event(run_id: str, event_type: str, data: dict | None = None) -> None:
    """影子追加一条 run 事件。任何失败静默吞掉——账本绝不反噬 run。"""
    run_id = str(run_id or '').strip()
    if not run_id or not agent_run_event_log_enabled():
        return
    try:
        path = agent_run_event_log_path(run_id)
        with _AGENT_RUN_EVENT_LOCK:
            if path in _AGENT_RUN_EVENT_CAPPED:
                return
            is_new_file = not os.path.exists(path)
            if not is_new_file:
                try:
                    if os.path.getsize(path) >= AGENT_RUN_EVENT_LOG_FILE_CAP:
                        _AGENT_RUN_EVENT_CAPPED.add(path)
                        cap_marker = json.dumps({
                            'seq': _AGENT_RUN_EVENT_SEQ.get(run_id, 0) + 1,
                            'time': int(time.time() * 1000),
                            'pid': os.getpid(),
                            'run_id': run_id,
                            'type': 'log/truncated',
                            'data': {'reason': f'file cap {AGENT_RUN_EVENT_LOG_FILE_CAP} bytes reached'},
                        }, ensure_ascii=False)
                        with open(path, 'a', encoding='utf-8') as handle:
                            handle.write(cap_marker + '\n')
                        return
                except OSError:
                    pass
            seq = _AGENT_RUN_EVENT_SEQ.get(run_id, 0) + 1
            _AGENT_RUN_EVENT_SEQ[run_id] = seq
            envelope = {
                'seq': seq,
                'time': int(time.time() * 1000),
                'pid': os.getpid(),
                'run_id': run_id,
                'type': str(event_type or 'event'),
                'data': _agent_run_event_json_safe(data if isinstance(data, dict) else {}),
            }
            line = json.dumps(envelope, ensure_ascii=False, default=str)
            os.makedirs(agent_run_event_log_root(), exist_ok=True)
            with open(path, 'a', encoding='utf-8') as handle:
                handle.write(line + '\n')
        if is_new_file:
            prune_agent_run_event_logs()
    except Exception:
        pass


def _append_run_lifecycle_event(run: dict, event_type: str) -> None:
    if not isinstance(run, dict):
        return
    config = run.get('config') if isinstance(run.get('config'), dict) else {}
    status_lines = run.get('status_lines') or []
    append_agent_run_event(str(run.get('run_id', '') or ''), event_type, {
        'phase': run.get('phase', ''),
        'status': run.get('status', ''),
        'conversation_path': run.get('conversation_path', ''),
        'parent_run_id': run.get('parent_run_id', ''),
        'question_text': str(run.get('question_text', '') or config.get('question_text', '') or config.get('task', '') or ''),
        'answer': str(run.get('answer', '') or ''),
        'last_status_line': str(status_lines[-1]) if status_lines else '',
    })


# ── 每 run 共享预算（方案5：守卫集中化）──────────────────────────
# 四套重试/切换机制里，模型失败切换（步骤级 run_model_failover + 最终答复
# _maybe_failover_client）与档位兜底（run_profile_fallback）此前各管各的、
# 上限只受候选名单长度约束，跨机制可能相乘。这里给每个 run 一份共享预算：
# 超限的切换直接放弃（回到"无候选可用"的原失败路径），并写
# guard/budget_denied 事件到 run 事件日志。复审动态插步已有自己的显式上限
# （SPECIALIZED_DYNAMIC_STEP_MAX_ADDITIONS），不在这里重复设限。
AGENT_RUN_BUDGET_DEFAULTS = {
    'model_failovers': 8,
    'profile_fallbacks': 8,
}
_AGENT_RUN_BUDGET_LOCK = threading.RLock()
_AGENT_RUN_BUDGETS = {}
_AGENT_RUN_BUDGET_MAX_RUNS = 500


def agent_run_budget_consume(run_id: str, kind: str) -> bool:
    """消耗一次预算；超限返回 False 并记 guard/budget_denied 事件。
    run_id 为空（无 run 上下文的独立调用）不设限；未登记的 kind 只计数
    不设限。"""
    run_id = str(run_id or '').strip()
    if not run_id:
        return True
    cap = AGENT_RUN_BUDGET_DEFAULTS.get(kind)
    with _AGENT_RUN_BUDGET_LOCK:
        counts = _AGENT_RUN_BUDGETS.get(run_id)
        if counts is None:
            while len(_AGENT_RUN_BUDGETS) >= _AGENT_RUN_BUDGET_MAX_RUNS:
                _AGENT_RUN_BUDGETS.pop(next(iter(_AGENT_RUN_BUDGETS)))
            counts = _AGENT_RUN_BUDGETS[run_id] = {}
        used = int(counts.get(kind, 0))
        denied = cap is not None and used >= cap
        if not denied:
            counts[kind] = used + 1
    if denied:
        append_agent_run_event(run_id, 'guard/budget_denied', {'kind': kind, 'used': used, 'cap': cap})
        return False
    return True


