_PLAN_EVENT_PERSISTED_SIGNATURES = {}   # event id -> signature of the last persisted snapshot
_PLAN_EVENT_PERSISTED_MAX = 500
_PLAN_EVENT_PERSIST_LOCK = threading.Lock()


def _durable_plan_event(event: dict) -> dict:
    """The plan without its live display fields (live_tail / live_chars / live_probe: the
    streaming tail shown in the plan panel). They change on every streamed chunk, and
    persisting them rewrote the whole plan dozens of times a second — one run filled its
    20 MB event log in two minutes, after which nothing more was recorded."""
    durable = dict(event)
    steps = event.get('steps')
    if isinstance(steps, list):
        durable['steps'] = [
            {key: value for key, value in step.items() if not str(key).startswith('live_')}
            if isinstance(step, dict) else step
            for step in steps
        ]
    return durable


def _shadow_persist_plan_event(event: dict):
    if not isinstance(event, dict):
        return _shadow_store_call('persist_plan_event', event)
    durable = _durable_plan_event(event)
    # Only real changes: updated_at moves on every panel refresh.
    try:
        signature = json.dumps({k: v for k, v in durable.items() if k != 'updated_at'},
                               sort_keys=True, ensure_ascii=False, default=str)
    except Exception:
        signature = None
    key = str(durable.get('event_id', '') or durable.get('run_id', '') or '')
    if signature is not None and key:
        with _PLAN_EVENT_PERSIST_LOCK:
            if _PLAN_EVENT_PERSISTED_SIGNATURES.get(key) == signature:
                return None
            _PLAN_EVENT_PERSISTED_SIGNATURES.pop(key, None)
            _PLAN_EVENT_PERSISTED_SIGNATURES[key] = signature
            while len(_PLAN_EVENT_PERSISTED_SIGNATURES) > _PLAN_EVENT_PERSISTED_MAX:
                _PLAN_EVENT_PERSISTED_SIGNATURES.pop(next(iter(_PLAN_EVENT_PERSISTED_SIGNATURES)))
    append_agent_run_event(str(durable.get('run_id', '') or ''), 'plan/event', durable)
    return _shadow_store_call('persist_plan_event', durable)


def _shadow_persist_approval(approval: dict):
    return _shadow_store_call('persist_approval', approval)


def _shadow_persist_approval_request(request: dict, approval_kind: str, state: str, run: dict | None = None):
    if not isinstance(request, dict):
        return None
    action_id = str(request.get('action_id', '') or request.get('id', '') or '').strip()
    if not action_id:
        action_id = new_broccoli_uuid('action-')
        request['action_id'] = action_id
    payload = dict(request)
    payload.update({
        'action_id': action_id,
        'approval_kind': str(approval_kind or ''),
        'state': str(state or 'pending'),
    })
    if isinstance(run, dict):
        payload['task_id'] = str(run.get('task_id', '') or '')
        payload['attempt_id'] = str(run.get('attempt_id', '') or '')
        payload['run_id'] = str(run.get('run_id', '') or payload.get('run_id', '') or '')
    append_agent_run_event(
        str(payload.get('run_id', '') or ''), f"approval/{payload['state']}", payload
    )
    return _shadow_persist_approval(payload)


def serialize_editor_edit_proposal(proposal: dict, action_id: str = '', run: dict | None = None) -> dict:
    """Persistable editor approval contract; deliberately contains no Qt/store objects."""
    proposal = proposal if isinstance(proposal, dict) else {}
    current_text = str(proposal.get('current_text', '') or '')
    proposed_text = str(proposal.get('proposed_text', '') or '')
    record = proposal.get('record') if isinstance(proposal.get('record'), dict) else {}
    return {
        'action_id': str(action_id or new_broccoli_uuid('editor-action-')),
        'approval_kind': 'editor_edit',
        'path': str(proposal.get('path', '') or ''),
        'file_hash': hashlib.sha256(current_text.encode('utf-8')).hexdigest(),
        'current_text': current_text,
        'proposed_text': proposed_text,
        'summary': str(proposal.get('summary', '') or ''),
        'record': _task_store_json_safe(record),
        'dirty': bool(proposal.get('dirty', False)),
        'run_id': str((run or {}).get('run_id', '') or record.get('_origin_run_id', '') or ''),
        'task_id': str((run or {}).get('task_id', '') or ''),
        'attempt_id': str((run or {}).get('attempt_id', '') or ''),
        'created_at': datetime.datetime.now().isoformat(timespec='milliseconds'),
    }


class UnifiedTaskFinalizer:
    """Single idempotent release gate for every local task/attempt terminal path."""

    STATE_MAP = {
        'finished': 'completed',
        'complete': 'completed',
        'completed': 'completed',
        'failed': 'failed',
        'stopped': 'cancelled',
        'cancelled': 'cancelled',
        'deleted': 'cancelled',
        'rejected': 'rejected',
        'needs_login': 'failed',
        'needs_reconciliation': 'needs_reconciliation',
    }

    def __init__(self, owner):
        self.owner = owner

    def finalize(self, run: dict, terminal_state: str = '', reason: str = '') -> dict:
        if not isinstance(run, dict):
            return {'status': 'ignored', 'reason': 'missing_run'}
        if run.get('_unified_finalized'):
            return {
                'status': 'duplicate',
                'completion_event_id': str(run.get('completion_event_id', '') or ''),
            }
        requested = str(terminal_state or run.get('status', '') or 'finished').strip()
        pending = run.get('pending_local_actions')
        if isinstance(pending, dict) and pending:
            run['_pending_terminal_state'] = requested
            run['status'] = 'waiting_local_action'
            run['task_state'] = 'waiting_local_action'
            run['pause_kind'] = 'waiting_local_action'
            run['updated_at'] = datetime.datetime.now().isoformat(timespec='seconds')
            _shadow_update_run(run)
            try:
                self.owner._show_agent_conversation_badge(
                    str(run.get('conversation_path', '') or ''),
                    status='waiting_local_action',
                )
                self.owner._refresh_agent_send_button_state()
            except Exception:
                pass
            return {
                'status': 'blocked',
                'task_state': 'waiting_local_action',
                'pending_action_ids': sorted(str(key) for key in pending),
            }

        task_state = self.STATE_MAP.get(requested, requested or 'completed')
        completion_event_id = str(run.get('completion_event_id', '') or new_broccoli_uuid('completion-'))
        run['completion_event_id'] = completion_event_id
        run['task_state'] = task_state
        run['status'] = requested
        run['pause_kind'] = ''
        run['_unified_finalized'] = True
        run['finalized_at'] = datetime.datetime.now().isoformat(timespec='milliseconds')
        if reason:
            run['finalize_reason'] = str(reason)
        _shadow_update_run(run)
        _shadow_store_call('append_event', {
            'event_id': completion_event_id,
            'task_id': str(run.get('task_id', '') or ''),
            'attempt_id': str(run.get('attempt_id', '') or ''),
            'event_type': 'attempt_terminal',
            'producer_id': BROCCOLI_LOCAL_DEVICE_ID,
            'producer_seq': completion_event_id,
            'state': task_state,
            'reason': str(reason or ''),
        })
        try:
            self.owner._publish_remote_run_terminal(run, task_state)
        except Exception:
            logging.exception('Failed to publish remote terminal revision.')
        if ICLOUD_M6_NOTES_SHORTCUTS_ENABLED:
            try:
                self.owner._enqueue_apple_notes_mirror_for_run(run, task_state)
            except Exception:
                # Notes is a detached mirror. It can never rewrite a completed task.
                logging.exception('Failed to enqueue Apple Notes mirror job.')
        if bool(run.get('_child_attempt', False)):
            run_id = str(run.get('run_id', '') or '')
            if run_id and getattr(self.owner, '_agent_runs_by_id', {}).get(run_id) is run:
                self.owner._agent_runs_by_id.pop(run_id, None)
            return {'status': 'finalized', 'task_state': task_state, 'completion_event_id': completion_event_id}
        self.owner._forget_agent_run_legacy(run)
        released = getattr(self.owner, 'icloud_remote_queue_check', None)
        if released is not None:
            # Queued (thread-safe) so remote turns that waited for this
            # conversation start on the GUI thread.
            try:
                released.emit(str(run.get('conversation_path', '') or ''))
            except Exception:
                logging.exception('Could not release waiting remote turns.')
        followup = run.pop('_finalizer_followup', None)
        if isinstance(followup, dict):
            QTimer.singleShot(
                0,
                lambda path=str(followup.get('path', '') or ''), supplements=list(followup.get('supplements') or []):
                    self.owner._run_agent_followups_after_finish(path, supplements),
            )
        return {'status': 'finalized', 'task_state': task_state, 'completion_event_id': completion_event_id}


def _agent_render_perf_log(event: str, **fields) -> None:
    """Low-overhead opt-in timing log for the Agent display/save pipeline."""
    if not AGENT_RENDER_PERF_ENABLED:
        return
    ordered = ' '.join(f'{key}={fields[key]}' for key in sorted(fields))
    line = f'[PERF] {event}' + (f' {ordered}' if ordered else '')
    print(line, flush=True)
    try:
        ensure_dir = os.path.dirname(AGENT_RENDER_PERF_LOG_PATH)
        if ensure_dir:
            os.makedirs(ensure_dir, exist_ok=True)
        with _AGENT_RENDER_PERF_LOCK:
            with open(AGENT_RENDER_PERF_LOG_PATH, 'a', encoding='utf-8') as handle:
                handle.write(line + '\n')
    except Exception:
        pass
