def _conversation_tree_component(value: str, fallback: str) -> str:
    cleaned = re.sub(r'[^a-zA-Z0-9._-]+', '-', str(value or '').strip()).strip('-._')
    return cleaned or str(fallback)


class ConversationPathResolver:
    """conversation_id is authoritative; absolute paths are rebuildable cache hints."""

    SCHEMA_VERSION = 1

    def __init__(self, index_path: str, tree_root: str):
        self.index_path = os.path.abspath(os.path.expanduser(str(index_path or '')))
        self.tree_root = os.path.abspath(os.path.expanduser(str(tree_root or '')))
        self._lock = threading.RLock()
        self._data = self._load()

    def _load(self) -> dict:
        try:
            with open(self.index_path, 'r', encoding='utf-8') as handle:
                payload = json.load(handle)
            if not isinstance(payload, dict):
                raise ValueError('resolver index is not an object')
        except Exception:
            payload = {}
        conversations = payload.get('conversations') if isinstance(payload.get('conversations'), dict) else {}
        aliases = payload.get('aliases') if isinstance(payload.get('aliases'), dict) else {}
        return {
            'schema_version': self.SCHEMA_VERSION,
            'conversations': conversations,
            'aliases': aliases,
        }

    def _persist(self):
        os.makedirs(os.path.dirname(self.index_path), exist_ok=True)
        _write_json_atomic(self.index_path, self._data, indent=2)

    def register(self, conversation_id: str, path: str, record: dict | None = None) -> dict:
        conversation_id = str(conversation_id or '').strip()
        path = os.path.abspath(os.path.expanduser(str(path or ''))) if str(path or '').strip() else ''
        if not conversation_id or not path:
            return {}
        record = record if isinstance(record, dict) else {}
        identity = record.get('identity') if isinstance(record.get('identity'), dict) else {}
        extensions = record.get('extensions') if isinstance(record.get('extensions'), dict) else {}
        if not identity and isinstance(extensions.get('identity'), dict):
            identity = extensions.get('identity') or {}
        owner_user_id = str(identity.get('owner_user_id', '') or identity.get('user_id', '') or BROCCOLI_LOCAL_USER_ID)
        device_id = str(identity.get('owner_device_id', '') or identity.get('device_id', '') or BROCCOLI_LOCAL_DEVICE_ID)
        origin_user_id = str(identity.get('origin_user_id', '') or identity.get('user_id', '') or BROCCOLI_LOCAL_USER_ID)
        try:
            route_epoch = max(0, int(record.get('route_epoch', identity.get('route_epoch', 0)) or 0))
        except (TypeError, ValueError):
            route_epoch = 0
        now = datetime.datetime.now().isoformat(timespec='milliseconds')
        with self._lock:
            previous = self._data['conversations'].get(conversation_id)
            previous = previous if isinstance(previous, dict) else {}
            previous_path = str(previous.get('path_cache', '') or '')
            metadata = dict(previous)
            metadata.update({
                'conversation_id': conversation_id,
                'path_cache': path,
                'owner_user_id': owner_user_id,
                'device_id': device_id,
                'origin_user_id': origin_user_id,
                'route_epoch': route_epoch,
                'title': str(record.get('title', '') or previous.get('title', '') or ''),
                'revision': int(record.get('revision', previous.get('revision', 0)) or 0),
                'deleted': False,
                'updated_at': now,
            })
            self._data['conversations'][conversation_id] = metadata
            self._data['aliases'][path] = conversation_id
            if previous_path:
                self._data['aliases'][previous_path] = conversation_id
            self._persist()
            return copy.deepcopy(metadata)

    def resolve(self, reference: str, *, include_deleted: bool = False) -> str:
        reference = str(reference or '').strip()
        if not reference:
            return ''
        expanded = os.path.abspath(os.path.expanduser(reference)) if os.path.isabs(os.path.expanduser(reference)) else ''
        with self._lock:
            conversation_id = reference if reference in self._data['conversations'] else ''
            if not conversation_id and expanded:
                conversation_id = str(self._data['aliases'].get(expanded, '') or '')
            metadata = self._data['conversations'].get(conversation_id)
            if isinstance(metadata, dict):
                if bool(metadata.get('deleted', False)) and not include_deleted:
                    return ''
                return str(metadata.get('path_cache', '') or expanded or reference)
        if expanded:
            return expanded
        return reference

    def conversation_id_for_path(self, path: str, *, inspect_file: bool = True) -> str:
        path = os.path.abspath(os.path.expanduser(str(path or ''))) if str(path or '').strip() else ''
        if not path:
            return ''
        with self._lock:
            conversation_id = str(self._data['aliases'].get(path, '') or '')
            if conversation_id:
                return conversation_id
        if inspect_file and os.path.isfile(path):
            try:
                with open(path, 'r', encoding='utf-8') as handle:
                    payload = json.load(handle)
                conversation_id = str((payload or {}).get('id', '') or '').strip()
            except Exception:
                conversation_id = ''
            if conversation_id:
                self.register(conversation_id, path, payload)
                return conversation_id
        return Path(path).stem.split('_', 1)[0]

    def metadata(self, conversation_id: str) -> dict:
        with self._lock:
            value = self._data['conversations'].get(str(conversation_id or '').strip())
            return copy.deepcopy(value) if isinstance(value, dict) else {}

    def rename_metadata(self, conversation_id: str, title: str):
        conversation_id = str(conversation_id or '').strip()
        with self._lock:
            metadata = self._data['conversations'].get(conversation_id)
            if not isinstance(metadata, dict):
                return False
            metadata['title'] = str(title or '')
            metadata['updated_at'] = datetime.datetime.now().isoformat(timespec='milliseconds')
            self._persist()
        return True

    def mark_deleted(self, conversation_id: str, path_cache: str = ''):
        conversation_id = str(conversation_id or '').strip()
        if not conversation_id:
            return False
        with self._lock:
            metadata = self._data['conversations'].get(conversation_id)
            if not isinstance(metadata, dict):
                metadata = {'conversation_id': conversation_id}
                self._data['conversations'][conversation_id] = metadata
            if path_cache:
                metadata['path_cache'] = os.path.abspath(os.path.expanduser(str(path_cache)))
                self._data['aliases'][metadata['path_cache']] = conversation_id
            metadata['deleted'] = True
            metadata['deleted_at'] = datetime.datetime.now().isoformat(timespec='milliseconds')
            metadata['updated_at'] = metadata['deleted_at']
            self._persist()
        return True

    def tree_directory(self, conversation_id: str, metadata: dict | None = None) -> str:
        data = metadata if isinstance(metadata, dict) else self.metadata(conversation_id)
        return os.path.join(
            self.tree_root,
            'canonical',
            _conversation_tree_component(data.get('owner_user_id', ''), 'owner'),
            _conversation_tree_component(data.get('device_id', ''), 'device'),
            _conversation_tree_component(data.get('origin_user_id', ''), 'origin'),
            _conversation_tree_component(conversation_id, 'conversation'),
        )

    def all_current_paths(self) -> list[str]:
        with self._lock:
            return [
                str(metadata.get('path_cache', '') or '')
                for metadata in self._data['conversations'].values()
                if isinstance(metadata, dict) and not metadata.get('deleted') and metadata.get('path_cache')
            ]


class LocalConversationTreeStorage:
    """M2 local cache implementation of the fixed L1/L2/L3 canonical tree."""

    def __init__(self, resolver: ConversationPathResolver):
        self.resolver = resolver

    def current_path(self, reference: str) -> str:
        return self.resolver.resolve(reference)

    def register(self, record: dict, path: str) -> dict:
        return self.resolver.register(str((record or {}).get('id', '') or ''), path, record)

    def canonical_directory(self, conversation_id: str) -> str:
        return self.resolver.tree_directory(conversation_id)


def get_conversation_path_resolver(index_path: str | None = None,
                                   tree_root: str | None = None) -> ConversationPathResolver | None:
    global _CONVERSATION_RESOLVER
    if not ICLOUD_M2_CONVERSATION_RESOLVER_ENABLED:
        return None
    requested_index = os.path.abspath(os.path.expanduser(str(index_path or CONVERSATION_RESOLVER_INDEX_PATH)))
    requested_root = os.path.abspath(os.path.expanduser(str(tree_root or LOCAL_CONVERSATION_TREE_ROOT)))
    with _CONVERSATION_RESOLVER_LOCK:
        if (
            _CONVERSATION_RESOLVER is None
            or _CONVERSATION_RESOLVER.index_path != requested_index
            or _CONVERSATION_RESOLVER.tree_root != requested_root
        ):
            _CONVERSATION_RESOLVER = ConversationPathResolver(requested_index, requested_root)
        return _CONVERSATION_RESOLVER


def reset_conversation_path_resolver_for_tests():
    global _CONVERSATION_RESOLVER
    with _CONVERSATION_RESOLVER_LOCK:
        _CONVERSATION_RESOLVER = None


def resolve_conversation_path(reference: str) -> str:
    if not ICLOUD_M2_CONVERSATION_RESOLVER_ENABLED:
        return str(reference or '').strip()
    resolver = get_conversation_path_resolver()
    return resolver.resolve(reference) if resolver is not None else str(reference or '').strip()


def conversation_id_for_reference(reference: str) -> str:
    reference = str(reference or '').strip()
    if not reference:
        return ''
    if not ICLOUD_M2_CONVERSATION_RESOLVER_ENABLED:
        return Path(reference).stem.split('_', 1)[0]
    resolver = get_conversation_path_resolver()
    if resolver is None:
        return Path(reference).stem.split('_', 1)[0]
    resolved = resolver.resolve(reference, include_deleted=True)
    return resolver.conversation_id_for_path(resolved, inspect_file=True)


def conversation_sidecar_reference(path: str) -> str:
    path = str(path or '').strip()
    if not ICLOUD_M2_CONVERSATION_RESOLVER_ENABLED:
        return path
    return conversation_id_for_reference(path) or path


def resolve_conversation_sidecar_reference(reference: str) -> str:
    reference = str(reference or '').strip()
    if not ICLOUD_M2_CONVERSATION_RESOLVER_ENABLED:
        return reference
    resolved = resolve_conversation_path(reference)
    return resolved if resolved and os.path.exists(resolved) else ''


DEFAULT_BROCCOLI_ICLOUD_ROOT = os.path.join(
    str(Path.home()),
    'Library', 'Mobile Documents', 'com~apple~CloudDocs', 'Broccoli',
)
BROCCOLI_ICLOUD_ROOT = os.path.abspath(os.path.expanduser(
    str(os.environ.get('BROCCOLI_ICLOUD_ROOT', DEFAULT_BROCCOLI_ICLOUD_ROOT) or DEFAULT_BROCCOLI_ICLOUD_ROOT)
))
ICLOUD_PROTOCOL_VERSION = 1


class ICloudUserError(RuntimeError):
    """A remote-task problem meant for the user.

    It carries a code and parameters instead of a finished sentence. The text is
    translated when it is shown, on the device showing it, so a reason that comes
    from another Mac (sent as its code) still reads in this Mac's language.
    """

    def __init__(self, code: str, **params):
        self.code = str(code or '')
        self.params = dict(params)
        super().__init__(self.code)

    def __str__(self) -> str:
        return icloud_message(self.code, **self.params)


class ICloudUserValueError(ICloudUserError, ValueError):
    """The same, where callers expect a ValueError (bad input)."""


class _ICloudFormatDefaults(dict):
    def __missing__(self, key):
        return '{' + key + '}'


def _icloud_format(template: str, params: dict) -> str:
    try:
        return template.format_map(_ICloudFormatDefaults(params))
    except Exception:
        return template


def icloud_status_label(status: str) -> str:
    """Remote task status shown on the status card."""
    status = str(status or '')
    labels = {
        'publishing': _tr('Moving request…'),
        'waiting_ack': _tr('Waiting for target device…'),
        'executing': _tr('Running remotely…'),
        'syncing_answer': _tr('Syncing answer…'),
        'completed': _tr('Remote answer synced'),
        'queued': _tr('Queued on the target device; it runs after the current task there…'),
        'cancel_requested': _tr('Cancellation requested; waiting for target confirmation…'),
        'cancelled': _tr('Remote task cancelled'),
        'needs_reconciliation': _tr('Remote task needs reconciliation'),
        'failed': _tr('Remote task failed'),
    }
    return labels.get(status) or status.replace('_', ' ').capitalize()


def icloud_availability_label(availability: str) -> str:
    """Device state shown next to a device in the Move to picker."""
    availability = str(availability or '')
    labels = {
        'online': _tr('online'),
        'offline': _tr('offline'),
        'unresponsive': _tr('not responding'),
        'draining': _tr('shutting down'),
        'busy': _tr('busy'),
    }
    return labels.get(availability, availability)


def icloud_blocker_text(blocker: str) -> str:
    blockers = {
        'active_attempt': _tr('active attempt'),
        'pending_approval': _tr('pending approval'),
        'editor_dirty': _tr('dirty editor buffer'),
    }
    return blockers.get(str(blocker or ''), str(blocker or ''))


def icloud_message(code: str, **params) -> str:
    """User-facing text for an iCloud remote-task code, in this Mac's language.

    Unknown codes fall back to params['detail'] or the code itself, so text from
    an older build (a finished English sentence) is still shown as it came.
    """
    code = str(code or '')
    params = dict(params)
    if code == 'migration_busy':
        params['blockers'] = ', '.join(icloud_blocker_text(item) for item in (params.get('blockers') or []))
    templates = {
        # sending from here
        'transport_disabled': _tr('iCloud remote tasks are turned off.'),
        'prompt_required': _tr('Type a question or add an attachment first.'),
        'remote_tasks_off_on_device': _tr('Remote tasks are turned off on {device}.'),
        'no_owner_device': _tr('This conversation has no owner device to continue on.'),
        'owned_here': _tr('This Mac owns the conversation; it runs here.'),
        'attachment_unreadable': _tr('An attachment could not be read: {name}'),
        'cloud_write_failed': _tr('Could not write to iCloud Drive: {detail}'),
        # waiting for the answer
        'target_rejected': _tr('{device} refused the task.'),
        'no_failure_details': _tr('{device} reported a failure without details.'),
        'ack_timeout': _tr('{device} did not pick up the request within {minutes} minutes (asleep, offline, '
                           'or iCloud is not syncing). The request has expired and will not run later.'),
        'target_quit': _tr('{device} quit while running this task.'),
        'lost_contact': _tr('Lost contact with {device}: no response for {minutes} minutes. If it finishes later, '
                            'the answer will appear in History.'),
        'cancel_requested_waiting': _tr('Cancellation requested; waiting for {device} to confirm.'),
        # reported by the device that ran (or refused) the task
        'request_expired': _tr('The request expired before {device} picked it up.'),
        'interrupted_by_restart': _tr('Interrupted: Broccoli on {device} quit or restarted before the task finished.'),
        'unsupported_task': _tr('{device} does not support this kind of task.'),
        'invalid_new_conversation': _tr('{device} refused a malformed new-conversation request.'),
        'conversation_not_on_device': _tr('The conversation is not available on {device}.'),
        'not_owner_anymore': _tr('{device} no longer owns the conversation; it moved to another device.'),
        'executor_not_ready': _tr('Remote tasks are not ready on {device} yet; try again in a moment.'),
        # device picker and status card notes
        'unresponsive_note': _tr('No response for {minutes} min. A request will wait up to {limit} min, then expire.'),
        'default_profile_note': _tr('Default Profile will be used'),
        'default_profile_running': _tr('Default Profile is running on the target device.'),
        'stale_copy_note': _tr('The copy here was not the newest; the device answered on its latest version.'),
        'queued_here_note': _tr('{count} more queued here; they are sent after this answer.'),
        # moving conversations
        'migration_busy': _tr('Migration blocked by {blockers}.'),
        'asset_missing': _tr('A file of this conversation is missing: {name}'),
        'migration_source_missing': _tr('The conversation to move could not be found.'),
        'not_owner': _tr('Only the device that owns this conversation can move it.'),
        'invalid_target': _tr('Choose another device as the destination.'),
        'conversation_conflict': _tr('Another move of this conversation is already in progress.'),
        'save_timeout': _tr('Saving the conversation took too long; try the move again.'),
        'source_changed_during_move': _tr('The conversation changed after the move started; cancel it and try again.'),
        'move_state_damaged': _tr('The saved state of this move is damaged; cancel it and try again.'),
        'already_owned_here': _tr('This Mac already owns the conversation.'),
        'already_there': _tr('The conversation already lives on that device.'),
        'conversation_frozen': _tr('This conversation is being moved to another device; changes wait until the move finishes.'),
    }
    template = templates.get(code)
    if template is None:
        return str(params.get('detail') or code)
    if not str(params.get('device', '') or '').strip():
        params['device'] = _tr('The target device')
    return _icloud_format(template, params)


def icloud_reason_text(reason: str, params: dict | None = None) -> str:
    """Why another device rejected or declined a move, as a short phrase."""
    reason = str(reason or '')
    reasons = {
        'asset_timeout': _tr('its files did not finish syncing in time'),
        'asset_verification_failed': _tr('a file arrived damaged'),
        'conversation_conflict': _tr('another move of this conversation is in progress'),
        'canonical_id_mismatch': _tr('the move data did not match'),
        'manifest_hash_mismatch': _tr('the move data did not match'),
        'invalid_manifest_item': _tr('the move data did not match'),
        'base_revision_mismatch': _tr('the conversation changed during the move'),
        'source_changed_during_move': _tr('the conversation changed during the move'),
        'not_found': _tr('it does not have this conversation'),
        'migration_source_missing': _tr('it does not have this conversation'),
        'not_owner': _tr('it no longer owns this conversation'),
        'invalid_target': _tr('the destination is not valid'),
        'already_there': _tr('the destination is not valid'),
        'expired': _tr('the request expired'),
        'asset_missing': _tr('a file of the conversation is missing there'),
        'save_timeout': _tr('saving took too long there'),
        'cloud_write_failed': _tr('it could not write to iCloud Drive'),
        'move_state_damaged': _tr('its saved move state is damaged'),
        'declined': _tr('it declined'),
        'rejected': _tr('it declined'),
    }
    if reason in reasons:
        return reasons[reason]
    message = icloud_message(reason, **dict(params or {}))
    return message if message != reason else reason



def cloud_payload_hash(payload: dict) -> str:
    clean = {
        str(key): value
        for key, value in (payload or {}).items()
        if str(key) != 'content_hash'
    }
    encoded = json.dumps(_task_store_json_safe(clean), ensure_ascii=False, sort_keys=True, separators=(',', ':')).encode('utf-8')
    return hashlib.sha256(encoded).hexdigest()


def seal_cloud_payload(payload: dict) -> dict:
    sealed = copy.deepcopy(payload if isinstance(payload, dict) else {})
    sealed['content_hash'] = cloud_payload_hash(sealed)
    return sealed


def verify_cloud_payload(payload: dict) -> bool:
    if not isinstance(payload, dict):
        return False
    expected = str(payload.get('content_hash', '') or '').strip()
    return bool(expected) and expected == cloud_payload_hash(payload)


class ICloudFileMaterializer:
    CURRENT_STATES = {'CURRENT', 'DOWNLOADED'}

    def status(self, path: str) -> str:
        raise NotImplementedError

    def request_download(self, path: str) -> bool:
        raise NotImplementedError

    def ensure_current(self, path: str, timeout: float = 30.0) -> bool:
        deadline = time.monotonic() + max(0.0, float(timeout))
        while time.monotonic() <= deadline:
            state = str(self.status(path) or 'UNKNOWN').upper()
            if state in self.CURRENT_STATES:
                return True
            if state in {'MISSING', 'UNKNOWN', 'ERROR'}:
                return False
            if state == 'NOT_DOWNLOADED' and not self.request_download(path):
                return False
            time.sleep(0.25)
        return False


class NSURLICloudFileMaterializer(ICloudFileMaterializer):
    """macOS materializer. Every status/download call constructs a fresh NSURL."""

    def __init__(self):
        self._foundation = None
        try:
            from Foundation import (  # type: ignore
                NSURL, NSFileManager,
                NSURLUbiquitousItemDownloadingStatusKey,
                NSURLUbiquitousItemDownloadingStatusCurrent,
                NSURLUbiquitousItemDownloadingStatusDownloaded,
                NSURLUbiquitousItemDownloadingStatusNotDownloaded,
            )
            self._foundation = {
                'NSURL': NSURL,
                'NSFileManager': NSFileManager,
                'key': NSURLUbiquitousItemDownloadingStatusKey,
                'current': NSURLUbiquitousItemDownloadingStatusCurrent,
                'downloaded': NSURLUbiquitousItemDownloadingStatusDownloaded,
                'not_downloaded': NSURLUbiquitousItemDownloadingStatusNotDownloaded,
            }
        except Exception:
            self._foundation = None

    def status(self, path: str) -> str:
        path = os.path.abspath(os.path.expanduser(str(path or '')))
        if not os.path.exists(path):
            return 'MISSING'
        if self._foundation is None:
            return 'CURRENT'
        # IMPORTANT: NSURL resource values are cached per instance. Never lift this
        # URL out of the method or reuse it across polls.
        url = self._foundation['NSURL'].fileURLWithPath_(path)
        try:
            url.removeAllCachedResourceValues()
            ok, value, _error = url.getResourceValue_forKey_error_(None, self._foundation['key'], None)
        except Exception:
            return 'UNKNOWN'
        if not ok or value is None:
            # A normal local file in an injected non-iCloud root is already readable.
            return 'CURRENT'
        if value == self._foundation['current']:
            return 'CURRENT'
        if value == self._foundation['downloaded']:
            return 'DOWNLOADED'
        if value == self._foundation['not_downloaded']:
            return 'NOT_DOWNLOADED'
        return 'UNKNOWN'

    def request_download(self, path: str) -> bool:
        if self._foundation is None:
            return os.path.exists(path)
        # Fresh NSURL here too; reusing the status URL would retain stale resources.
        url = self._foundation['NSURL'].fileURLWithPath_(
            os.path.abspath(os.path.expanduser(str(path or '')))
        )
        try:
            ok, _error = self._foundation['NSFileManager'].defaultManager().startDownloadingUbiquitousItemAtURL_error_(url, None)
            return bool(ok)
        except Exception:
            return False


class FakeICloudFileMaterializer(ICloudFileMaterializer):
    """Deterministic dataless/CURRENT simulator for offscreen suites."""

    def __init__(self, states: dict | None = None, *, auto_materialize: bool = True):
        self.states = {
            os.path.abspath(str(path)): str(state).upper()
            for path, state in (states or {}).items()
        }
        self.auto_materialize = bool(auto_materialize)
        self.status_calls = []
        self.download_requests = []

    def set_state(self, path: str, state: str):
        self.states[os.path.abspath(str(path))] = str(state or '').upper()

    def status(self, path: str) -> str:
        path = os.path.abspath(str(path))
        self.status_calls.append(path)
        if path in self.states:
            return self.states[path]
        return 'CURRENT' if os.path.exists(path) else 'MISSING'

    def request_download(self, path: str) -> bool:
        path = os.path.abspath(str(path))
        self.download_requests.append(path)
        if self.auto_materialize and self.states.get(path) == 'NOT_DOWNLOADED':
            self.states[path] = 'CURRENT'
        return path in self.states or os.path.exists(path)


class CloudTreeBackend:
    """Filesystem-only iCloud tree backend with injected root and materializer."""

    def __init__(self, root: str, materializer: ICloudFileMaterializer | None = None):
        self.root = os.path.abspath(os.path.expanduser(str(root or '')))
        if not self.root:
            raise ValueError('Cloud root is required.')
        self.materializer = materializer or NSURLICloudFileMaterializer()

    def path(self, *parts: str) -> str:
        candidate = os.path.abspath(os.path.join(self.root, *(str(part) for part in parts)))
        if os.path.commonpath([self.root, candidate]) != self.root:
            raise ValueError('Cloud path escapes injected root.')
        return candidate

    def ensure_layout(self):
        for parts in (
            ('canonical',), ('control', 'devices'), ('control', 'members'),
            ('control', 'inbox'), ('control', 'acks'), ('control', 'diagnostics'),
            ('control', 'migrations'),
            ('notes-jobs',),
        ):
            os.makedirs(self.path(*parts), exist_ok=True)

    def publish_json(self, directory: str, filename: str, payload: dict) -> str:
        os.makedirs(directory, exist_ok=True)
        destination = os.path.abspath(os.path.join(directory, os.path.basename(str(filename))))
        if os.path.commonpath([self.root, destination]) != self.root:
            raise ValueError('Publish target escapes cloud root.')
        encoded = json.dumps(payload, ensure_ascii=False, sort_keys=True, separators=(',', ':')).encode('utf-8')
        if os.path.exists(destination):
            with open(destination, 'rb') as handle:
                if handle.read() == encoded:
                    return destination
            raise FileExistsError('Immutable cloud filename already contains different bytes: ' + destination)
        temporary = destination + '.tmp-' + new_broccoli_uuid()
        try:
            with open(temporary, 'wb') as handle:
                handle.write(encoded)
                handle.flush()
                os.fsync(handle.fileno())
            os.replace(temporary, destination)
        finally:
            if os.path.exists(temporary):
                try:
                    os.remove(temporary)
                except OSError:
                    pass
        return destination

    def publish_file(self, directory: str, filename: str, source_path: str, expected_hash: str = '') -> str:
        """Atomically publish one immutable asset without ever reusing a mutable cloud path."""
        source_path = os.path.abspath(os.path.expanduser(str(source_path or '')))
        if not os.path.isfile(source_path):
            raise FileNotFoundError(source_path)
        digest = hashlib.sha256(Path(source_path).read_bytes()).hexdigest()
        if expected_hash and digest != str(expected_hash):
            raise ValueError('Asset hash changed before cloud publish.')
        os.makedirs(directory, exist_ok=True)
        destination = os.path.abspath(os.path.join(directory, os.path.basename(str(filename))))
        if os.path.commonpath([self.root, destination]) != self.root:
            raise ValueError('Publish target escapes cloud root.')
        if os.path.exists(destination):
            if hashlib.sha256(Path(destination).read_bytes()).hexdigest() == digest:
                return destination
            raise FileExistsError('Immutable cloud asset already contains different bytes: ' + destination)
        temporary = destination + '.tmp-' + new_broccoli_uuid()
        try:
            shutil.copy2(source_path, temporary)
            with open(temporary, 'rb') as handle:
                os.fsync(handle.fileno())
            os.replace(temporary, destination)
        finally:
            if os.path.exists(temporary):
                try:
                    os.remove(temporary)
                except OSError:
                    pass
        return destination

    def read_json(self, path: str, timeout: float = 30.0) -> dict | None:
        path = os.path.abspath(str(path or ''))
        if os.path.commonpath([self.root, path]) != self.root:
            return None
        if not self.materializer.ensure_current(path, timeout=timeout):
            return None
        try:
            with open(path, 'r', encoding='utf-8') as handle:
                payload = json.load(handle)
            return payload if isinstance(payload, dict) else None
        except Exception:
            return None

    def materialize_asset(self, path: str, cache_dir: str, expected_hash: str = '', timeout: float = 30.0) -> str:
        path = os.path.abspath(str(path or ''))
        if os.path.commonpath([self.root, path]) != self.root:
            return ''
        if not self.materializer.ensure_current(path, timeout=timeout):
            return ''
        try:
            digest = hashlib.sha256(Path(path).read_bytes()).hexdigest()
        except Exception:
            return ''
        if expected_hash and digest != str(expected_hash):
            return ''
        os.makedirs(cache_dir, exist_ok=True)
        destination = os.path.join(cache_dir, digest + Path(path).suffix)
        temporary = destination + '.tmp-' + new_broccoli_uuid()
        try:
            shutil.copy2(path, temporary)
            os.replace(temporary, destination)
        finally:
            if os.path.exists(temporary):
                try:
                    os.remove(temporary)
                except OSError:
                    pass
        return destination


def _cloud_file_component(value: str, fallback: str = 'item') -> str:
    return _conversation_tree_component(value, fallback)


class CloudDeviceRegistry:
    # Registration snapshots this device keeps for itself; older ones are deleted
    # so the heartbeat does not pile up files. Three keeps online/draining/offline.
    KEEP_OWN_SNAPSHOTS = 3

    def __init__(self, backend: CloudTreeBackend, device_id: str, owner_user_id: str):
        self.backend = backend
        self.device_id = _cloud_file_component(device_id, 'device')
        self.owner_user_id = _cloud_file_component(owner_user_id, 'owner')

    def _prune_own(self, directory: str, prefix: str):
        # time_ns has 19 digits; requiring 16+ keeps "Mac-mini" from matching
        # the files of a device called "Mac-mini-2".
        pattern = re.compile(r'^' + re.escape(prefix) + r'-(\d{16,})-.+\.json$')
        own = []
        for path in Path(directory).glob('*.json'):
            match = pattern.match(path.name)
            if match:
                own.append((int(match.group(1)), path))
        own.sort()
        for _sequence, path in own[:-self.KEEP_OWN_SNAPSHOTS]:
            try:
                path.unlink()
            except OSError:
                pass

    def publish(self, availability: str, **fields) -> str:
        sequence = f'{time.time_ns()}-{new_broccoli_uuid()}'
        payload = seal_cloud_payload({
            'schema_version': ICLOUD_PROTOCOL_VERSION,
            'record_type': 'device',
            'device_id': self.device_id,
            'owner_user_id': self.owner_user_id,
            'display_name': str(fields.pop('display_name', '') or self.device_id),
            'availability': str(availability or 'offline'),
            'accept_remote_tasks': bool(fields.pop('accept_remote_tasks', True)),
            'last_seen': datetime.datetime.now().isoformat(timespec='microseconds'),
            # Clock-zone independent time of this snapshot; other devices use it to
            # tell a live device from one that crashed while marked online.
            'heartbeat_epoch': time.time(),
            **_task_store_json_safe(fields),
        })
        filename = f'{self.device_id}-{sequence}.json'
        path = self.backend.publish_json(self.backend.path('control', 'devices'), filename, payload)
        member_payload = seal_cloud_payload({
            'schema_version': ICLOUD_PROTOCOL_VERSION,
            'record_type': 'member_device',
            'user_id': self.owner_user_id,
            'device_id': self.device_id,
            'availability': str(availability or 'offline'),
            'last_seen': payload['last_seen'],
        })
        self.backend.publish_json(
            self.backend.path('control', 'members'),
            f'{self.owner_user_id}-{self.device_id}-{sequence}.json',
            member_payload,
        )
        self._prune_own(self.backend.path('control', 'devices'), self.device_id)
        self._prune_own(self.backend.path('control', 'members'), f'{self.owner_user_id}-{self.device_id}')
        return path

    def list_latest(self) -> dict[str, dict]:
        latest = {}
        for path in sorted(Path(self.backend.path('control', 'devices')).glob('*.json')):
            payload = self.backend.read_json(str(path), timeout=0.5)
            if not verify_cloud_payload(payload):
                continue
            device_id = str(payload.get('device_id', '') or '')
            previous = latest.get(device_id)
            if previous is None or self._snapshot_order(payload) > self._snapshot_order(previous):
                latest[device_id] = payload
        return latest

    def other_hardware_with_same_id(self, own_fingerprint: str) -> set:
        """Fingerprints of other Macs that publish snapshots under this device id."""
        if not own_fingerprint:
            return set()
        pattern = re.compile(r'^' + re.escape(self.device_id) + r'-(\d{16,})-.+\.json$')
        found = set()
        for path in Path(self.backend.path('control', 'devices')).glob('*.json'):
            if not pattern.match(path.name):
                continue
            payload = self.backend.read_json(str(path), timeout=0.5)
            other = str((payload or {}).get('host_fingerprint', '') or '')
            if verify_cloud_payload(payload) and other and other != own_fingerprint:
                found.add(other)
        return found

    @staticmethod
    def _snapshot_order(payload: dict) -> tuple:
        # Prefer the epoch; last_seen is local wall-clock text (kept for old builds).
        try:
            epoch = float(payload.get('heartbeat_epoch', 0) or 0)
        except (TypeError, ValueError):
            epoch = 0.0
        return epoch, str(payload.get('last_seen', '') or '')


def cloud_canonical_record(record: dict) -> dict:
    """Strip device-local/secret state before a revision enters the shared tree."""
    forbidden = {
        'path', 'retrieval', 'rendered_markdown', 'display', 'search_blob',
        'external_sessions', '_retrieval_loaded', '_legacy_retrieval_present',
    }
    def scrub_local_paths(value):
        if isinstance(value, dict):
            cleaned = {}
            for key, item in value.items():
                key_text = str(key or '')
                if key_text in {'source_path', 'local_path', 'stored_path', 'transcript_path', 'backup_path', 'output_path', 'file_path'}:
                    continue
                if key_text == 'path' and isinstance(item, str) and os.path.isabs(os.path.expanduser(item)):
                    continue
                cleaned[key_text] = scrub_local_paths(item)
            return cleaned
        if isinstance(value, list):
            return [scrub_local_paths(item) for item in value]
        return copy.deepcopy(value)

    payload = {
        str(key): copy.deepcopy(value)
        for key, value in (record or {}).items()
        if str(key) not in forbidden and not str(key).startswith('_')
    }
    # Branch nodes carry per-device UI state (checkbox state, cached preview
    # text). It must not enter the shared tree or the content hash: records
    # published before those fields existed would otherwise permanently rank as
    # 'conflict' against the same content published after.
    branches = payload.get('branches') if isinstance(payload.get('branches'), dict) else None
    if branches is not None:
        def strip_branch_ui(node):
            if not isinstance(node, dict):
                return None
            return {
                'id': str(node.get('id', '') or ''),
                'message_index': node.get('message_index', -1),
                'children': [child for child in (strip_branch_ui(c) for c in node.get('children', []) or []) if child],
            }
        payload['branches'] = {
            'roots': [node for node in (strip_branch_ui(r) for r in branches.get('roots', []) or []) if node],
            'active_node_id': str(branches.get('active_node_id', '') or ''),
            'append_as_child': bool(branches.get('append_as_child', False)),
        }
    extensions = payload.get('extensions') if isinstance(payload.get('extensions'), dict) else {}
    extensions = {
        str(key): value
        for key, value in extensions.items()
        if str(key) not in forbidden and not str(key).startswith('_')
    }
    payload['extensions'] = extensions
    return scrub_local_paths(payload)


class ICloudTaskTransport:
    """Polling + multi-trigger iCloud transport. It never uses network APIs."""

    RESCAN_TRIGGERS = {'startup', 'periodic', 'file_event', 'foreground', 'network', 'wake', 'manual'}
    # A fresh 'online' snapshot this often while running; senders treat a device
    # whose newest snapshot is much older than this as unresponsive.
    HEARTBEAT_SECONDS = 120
    # Accept a request this long past its expires_at_epoch (clock skew between Macs).
    EXPIRY_GRACE_SECONDS = 60
    # Store files whose leftover remote attempts were already closed in this process.
    _INTERRUPTED_REPORTED_STORES: set = set()

    def __init__(self,
                 *,
                 cloud_root: str | None = None,
                 device_id: str = '',
                 owner_user_id: str = '',
                 materializer: ICloudFileMaterializer | None = None,
                 task_store: ShadowTaskStore | None = None,
                 task_handler=None,
                 control_handler=None,
                 task_gate=None,
                 registration_fields: dict | None = None,
                 poll_interval: float = 2.0,
                 enabled: bool | None = None):
        self.enabled = ICLOUD_M3_TRANSPORT_ENABLED if enabled is None else bool(enabled)
        self.backend = CloudTreeBackend(cloud_root or BROCCOLI_ICLOUD_ROOT, materializer)
        self.device_id = _cloud_file_component(device_id or BROCCOLI_LOCAL_DEVICE_ID, 'device')
        self.owner_user_id = _cloud_file_component(owner_user_id or BROCCOLI_LOCAL_USER_ID, 'owner')
        self.registry = CloudDeviceRegistry(self.backend, self.device_id, self.owner_user_id)
        self.task_store = task_store
        self.task_handler = task_handler
        self.control_handler = control_handler
        self.task_gate = task_gate
        self.registration_fields = dict(registration_fields or {})
        self.poll_interval = max(0.1, float(poll_interval))
        self.accepting = False
        self._stop_event = threading.Event()
        self._thread = None
        self.scan_reasons = []
        self.local_asset_cache = os.path.join(BROCCOLI_APP_DATA_DIR, 'RemoteAssetCache')
        self._last_heartbeat = 0.0
        # Callables run after each periodic scan on the poll thread (timeouts etc.).
        self.maintenance_handlers = []

    def _store(self) -> ShadowTaskStore | None:
        return self.task_store or get_shadow_task_store()

    def start(self, *, background: bool = True) -> bool:
        if not self.enabled:
            return False
        self.backend.ensure_layout()
        os.makedirs(self.backend.path('control', 'inbox', self.device_id), exist_ok=True)
        os.makedirs(self.backend.path('control', 'acks', self.device_id), exist_ok=True)
        self.accepting = True
        self._stop_event.clear()
        # Checked before publishing: publishing prunes this id's older snapshots,
        # which would also remove the other Mac's evidence.
        own_fingerprint = str(self.registration_fields.get('host_fingerprint', '') or '')
        clashes = self.registry.other_hardware_with_same_id(own_fingerprint)
        self.registry.publish('online', accept_remote_tasks=True, **self.registration_fields)
        self._last_heartbeat = time.monotonic()
        if clashes:
            logging.warning(
                'Another Mac publishes the same iCloud device id %r (hardware %s); tasks and '
                'ownership for this id will be mixed up. Delete device_identity.json on one of them.',
                self.device_id, ', '.join(sorted(clashes)),
            )
        try:
            self.report_interrupted_remote_attempts()
        except Exception:
            logging.exception('Reporting interrupted remote attempts failed.')
        try:
            self.trigger_rescan('startup')
        except Exception:
            # Same as the periodic scan: a bad file must not keep the poll thread
            # from starting.
            logging.exception('iCloud startup scan failed.')
        if background and (self._thread is None or not self._thread.is_alive()):
            self._thread = threading.Thread(target=self._poll_loop, name='broccoli-icloud-poll', daemon=True)
            self._thread.start()
        return True

    def _poll_loop(self):
        while not self._stop_event.wait(self.poll_interval):
            # One unreadable or conflicting file must not end the loop: a dead
            # poll thread silently stops this device from taking any task.
            try:
                self.trigger_rescan('periodic')
            except Exception:
                logging.exception('iCloud inbox scan failed.')
            self.run_maintenance()

    def run_maintenance(self):
        if not (self.enabled and self.accepting):
            return
        try:
            self.maybe_publish_heartbeat()
        except Exception:
            logging.exception('iCloud heartbeat failed.')
        for handler in list(self.maintenance_handlers):
            try:
                handler()
            except Exception:
                logging.exception('iCloud maintenance handler failed.')

    def maybe_publish_heartbeat(self, now: float | None = None) -> bool:
        now = time.monotonic() if now is None else float(now)
        if now - self._last_heartbeat < self.HEARTBEAT_SECONDS:
            return False
        self.registry.publish('online', accept_remote_tasks=True, **self.registration_fields)
        self._last_heartbeat = now
        return True

    def _terminal_event_for_request(self, request: dict, state: str, error: str,
                                    error_code: str = '', error_params: dict | None = None) -> str:
        conversation = {
            'id': str(request.get('conversation_id', '') or ''),
            'route_epoch': int(request.get('route_epoch', 0) or 0),
            'identity': {
                'owner_user_id': str(request.get('owner_user_id', '') or BROCCOLI_LOCAL_USER_ID),
                'owner_device_id': self.device_id,
                'origin_user_id': str(request.get('origin_user_id', '') or request.get('user_id', '') or BROCCOLI_LOCAL_USER_ID),
            },
        }
        attempt_id = str(request.get('attempt_id', '') or '')
        try:
            return self.publish_event(conversation, {
                'event_type': 'attempt_terminal',
                'task_id': str(request.get('task_id', '') or ''),
                'attempt_id': attempt_id,
                'state': str(state or 'failed'),
                'error': str(error or ''),
                # The sender shows this code in its own language; 'error' is for
                # older builds.
                'error_code': str(error_code or ''),
                'error_params': _task_store_json_safe(dict(error_params or {})),
                'producer_seq': 'run-terminal-' + _cloud_file_component(attempt_id, 'attempt'),
            })
        except FileExistsError:
            return ''

    def publish_attempt_status(self, request: dict, state: str, **fields) -> str:
        """Progress of an accepted attempt ('queued' behind a running task, then
        'running'), so the sender can show where it stands."""
        conversation = {
            'id': str(request.get('conversation_id', '') or ''),
            'route_epoch': int(request.get('route_epoch', 0) or 0),
            'identity': {
                'owner_user_id': str(request.get('owner_user_id', '') or BROCCOLI_LOCAL_USER_ID),
                'owner_device_id': self.device_id,
                'origin_user_id': str(request.get('origin_user_id', '') or request.get('user_id', '') or BROCCOLI_LOCAL_USER_ID),
            },
        }
        attempt_id = _cloud_file_component(request.get('attempt_id', ''), 'attempt')
        try:
            return self.publish_event(conversation, {
                'event_type': 'attempt_status',
                'task_id': str(request.get('task_id', '') or ''),
                'attempt_id': str(request.get('attempt_id', '') or ''),
                'state': str(state or ''),
                'producer_seq': f'status-{attempt_id}-{_cloud_file_component(state, "state")}',
                **_task_store_json_safe(fields),
            })
        except FileExistsError:
            return ''

    def report_interrupted_remote_attempts(self) -> list[dict]:
        """Close remote attempts a quit or crash cut off, and tell their senders.

        Runs once per task store per process, when nothing has started yet, so an
        unfinished remote attempt cannot still be running. Nothing resumes it, and
        without this the sender (whose device heartbeat looks fine again) waits forever.
        """
        store = self._store()
        if store is None:
            return []
        store_key = os.path.abspath(str(getattr(store, 'path', '') or id(store)))
        if store_key in self._INTERRUPTED_REPORTED_STORES:
            return []
        self._INTERRUPTED_REPORTED_STORES.add(store_key)
        device_name = str(self.registration_fields.get('display_name', '') or self.device_id)
        reported = []
        for row in store.recover_incomplete_attempts():
            # The incomplete-attempt query has no envelope; the full record does.
            record = store.attempt_record(str(row.get('attempt_id', '') or '')) or {}
            envelope = record.get('envelope') if isinstance(record.get('envelope'), dict) else {}
            config = envelope.get('config') if isinstance(envelope.get('config'), dict) else {}
            request = config.get('remote_request') if isinstance(config.get('remote_request'), dict) else None
            if request is None and str(config.get('source', '') or '') == 'remote':
                request = config
            if not isinstance(request, dict) or _cloud_file_component(request.get('executor_id', ''), 'device') != self.device_id:
                continue
            attempt_id = str(row.get('attempt_id', '') or '')
            reason = icloud_message('interrupted_by_restart', device=device_name)
            store.update_attempt_state(attempt_id, 'failed', {'interrupted': True, 'reason': reason})
            self._terminal_event_for_request(
                dict(request, attempt_id=attempt_id), 'failed', reason, error_code='interrupted_by_restart',
            )
            reported.append({'task_id': str(request.get('task_id', '') or ''), 'attempt_id': attempt_id})
        return reported

    def trigger_rescan(self, reason: str = 'manual') -> list[dict]:
        reason = str(reason or 'manual')
        if reason not in self.RESCAN_TRIGGERS:
            reason = 'manual'
        self.scan_reasons.append(reason)
        return self.process_inbox() if self.enabled and self.accepting else []

    def _validate_task_request(self, request: dict) -> bool:
        required = {
            'task_id', 'attempt_id', 'conversation_id', 'user_id', 'member_id',
            'origin_user_id', 'source_device_id', 'executor_id', 'owner_device_id',
            'logical_agent_id', 'route_epoch', 'base_revision', 'question', 'created_at',
        }
        return verify_cloud_payload(request) and required.issubset(request) and str(request.get('executor_id', '')) == self.device_id

    def _materialize_assets(self, request: dict) -> list[str] | None:
        local_paths = []
        for asset in request.get('asset_manifest') or []:
            if not isinstance(asset, dict):
                return None
            relative = str(asset.get('cloud_path', '') or asset.get('path', '') or '').strip()
            if not relative:
                return None
            try:
                cloud_path = self.backend.path(*Path(relative).parts)
            except Exception:
                return None
            local = self.backend.materialize_asset(
                cloud_path,
                self.local_asset_cache,
                expected_hash=str(asset.get('sha256', '') or asset.get('asset_id', '') or ''),
                timeout=float(asset.get('timeout', 0.5) or 0.5),
            )
            if not local:
                return None
            local_paths.append(local)
        return local_paths

    def process_inbox(self) -> list[dict]:
        if not self.enabled or not self.accepting:
            return []
        inbox = Path(self.backend.path('control', 'inbox', self.device_id))
        results = []
        store = self._store()
        if store is None:
            return results
        for path in sorted(inbox.glob('*.json')):
            request = self.backend.read_json(str(path), timeout=0.5)
            record_type = str((request or {}).get('record_type', '') or '')
            if (
                verify_cloud_payload(request)
                and record_type in {
                    'MigrationPrepare', 'MigrationReady', 'MigrationCommit', 'MigrationReject', 'MigrationCancel',
                    'MigrationRequest', 'MigrationRequestDeclined', 'TaskControl',
                }
                and str(request.get('executor_id', '') or '') == self.device_id
            ):
                if callable(self.control_handler):
                    try:
                        value = self.control_handler(request)
                        results.append(value if isinstance(value, dict) else {'record_type': record_type})
                    except Exception as exc:
                        results.append({'record_type': record_type, 'error': str(exc)})
                continue
            if not self._validate_task_request(request):
                continue
            if callable(self.task_gate):
                gate = self.task_gate(request)
                if isinstance(gate, dict) and not bool(gate.get('allow', True)):
                    results.append(gate)
                    continue
            try:
                expires_at = float(request.get('expires_at_epoch', 0) or 0)
            except (TypeError, ValueError):
                expires_at = 0.0
            if expires_at and time.time() > expires_at + self.EXPIRY_GRACE_SECONDS:
                # The sender has already given up on this request (it times out at
                # the same moment); running it now would surprise the user.
                created, _run = store.register_remote_attempt(request)
                if created:
                    store.update_attempt_state(str(request['attempt_id']), 'rejected', {'reject_reason': 'expired'})
                    self._publish_ack(request, {
                        'accepted': False,
                        'error': icloud_message('request_expired', device=self.device_id),
                        'error_code': 'request_expired',
                    })
                results.append({'task_id': request['task_id'], 'attempt_id': request['attempt_id'], 'expired': True})
                continue
            local_assets = self._materialize_assets(request)
            if local_assets is None:
                continue
            created, run = store.register_remote_attempt(request)
            if not created:
                results.append({'task_id': request['task_id'], 'attempt_id': request['attempt_id'], 'duplicate': True})
                continue
            handler_result = {}
            try:
                if callable(self.task_handler):
                    value = self.task_handler(dict(request, local_asset_paths=local_assets), run)
                    handler_result = value if isinstance(value, dict) else {}
            except Exception as exc:
                run['status'] = 'failed'
                run['finalize_reason'] = str(exc)
                store.update_run(run)
                handler_result = {
                    'accepted': False,
                    'error': str(exc),
                    'error_code': str(getattr(exc, 'code', '') or '') if isinstance(exc, ICloudUserError) else '',
                    'error_params': dict(getattr(exc, 'params', {}) or {}) if isinstance(exc, ICloudUserError) else {},
                }
            ack = self._publish_ack(request, handler_result)
            results.append({'task_id': request['task_id'], 'attempt_id': request['attempt_id'], 'duplicate': False, 'ack': ack})
        return results

    def _publish_ack(self, request: dict, handler_result: dict) -> dict:
        ack = seal_cloud_payload({
            'schema_version': ICLOUD_PROTOCOL_VERSION,
            'record_type': 'TaskAcknowledgement',
            'task_id': request['task_id'],
            'attempt_id': request['attempt_id'],
            'executor_id': self.device_id,
            'accepted_route_epoch': request.get('route_epoch', 0),
            'resolved_agent_profile_id': str(handler_result.get('resolved_agent_profile_id', '') or ''),
            'profile_fallback': bool(handler_result.get('profile_fallback', False)),
            'capability_snapshot_hash': str(handler_result.get('capability_snapshot_hash', '') or ''),
            'accepted': bool(handler_result.get('accepted', True)),
            # The sender shows error_code (+ params) in its own language; 'error'
            # is the text for older builds and for free-form failures.
            'error': str(handler_result.get('error', '') or ''),
            'error_code': str(handler_result.get('error_code', '') or ''),
            'error_params': _task_store_json_safe(dict(handler_result.get('error_params') or {})),
            'base_revision_stale': bool(handler_result.get('base_revision_stale', False)),
            'acknowledged_at': datetime.datetime.now().isoformat(timespec='milliseconds'),
        })
        ack_name = f'{self.device_id}-{_cloud_file_component(request["attempt_id"], "attempt")}-ack.json'
        try:
            self.backend.publish_json(
                self.backend.path('control', 'acks', _cloud_file_component(request.get('source_device_id', ''), 'source')),
                ack_name,
                ack,
            )
        except FileExistsError:
            # An ack for this attempt is already out (e.g. the local task store was
            # reset); the first one stands.
            logging.warning('Ack for attempt %s already published.', request.get('attempt_id'))
        return ack

    def submit_task(self, request: dict, producer_seq: str = '') -> str:
        if not self.enabled:
            raise ICloudUserError('transport_disabled')
        self.backend.ensure_layout()
        request = dict(request or {})
        request.setdefault('schema_version', ICLOUD_PROTOCOL_VERSION)
        request.setdefault('record_type', 'TaskRequest')
        request.setdefault('producer_id', self.device_id)
        request.setdefault('producer_seq', str(producer_seq or time.time_ns()))
        sealed = seal_cloud_payload(request)
        executor_id = _cloud_file_component(sealed.get('executor_id', ''), 'device')
        filename = '{}-{}-TaskRequest.json'.format(
            _cloud_file_component(sealed.get('producer_id', ''), 'producer'),
            _cloud_file_component(sealed.get('producer_seq', ''), 'seq'),
        )
        outbox_id = f"outbox-{sealed.get('task_id', '')}-{sealed.get('attempt_id', '')}-{sealed.get('producer_seq', '')}"
        store = self._store()
        if store is not None:
            store.enqueue_outbox({
                'outbox_id': outbox_id,
                'event_id': str(sealed.get('task_id', '') or ''),
                'state': 'pending',
                'payload': sealed,
            })
        destination = self.backend.publish_json(
            self.backend.path('control', 'inbox', executor_id), filename, sealed,
        )
        if store is not None:
            store.enqueue_outbox({
                'outbox_id': outbox_id,
                'event_id': str(sealed.get('task_id', '') or ''),
                'state': 'sent',
                'payload': sealed,
            })
        return destination

    def read_acknowledgements(self) -> list[dict]:
        if not self.enabled:
            return []
        directory = Path(self.backend.path('control', 'acks', self.device_id))
        if not directory.exists():
            return []
        acknowledgements = []
        seen = set()
        for path in sorted(directory.glob('*.json')):
            payload = self.backend.read_json(str(path), timeout=0.5)
            if not verify_cloud_payload(payload):
                continue
            identity = (str(payload.get('task_id', '') or ''), str(payload.get('attempt_id', '') or ''))
            if not all(identity) or identity in seen or str(payload.get('executor_id', '') or '') == self.device_id:
                continue
            seen.add(identity)
            acknowledgements.append(payload)
        return acknowledgements

    def publish_event(self, conversation: dict, event: dict) -> str:
        event = dict(event or {})
        event.setdefault('schema_version', ICLOUD_PROTOCOL_VERSION)
        event.setdefault('event_id', new_broccoli_uuid('event-'))
        event.setdefault('producer_id', self.device_id)
        event.setdefault('producer_seq', str(time.time_ns()))
        event.setdefault('created_at', datetime.datetime.now().isoformat(timespec='milliseconds'))
        event.setdefault('route_epoch', int(conversation.get('route_epoch', 0) or 0))
        sealed = seal_cloud_payload(event)
        identity = conversation.get('identity') if isinstance(conversation.get('identity'), dict) else local_conversation_identity()
        directory = self.backend.path(
            'canonical',
            _cloud_file_component(identity.get('owner_user_id', '') or identity.get('user_id', ''), 'owner'),
            _cloud_file_component(identity.get('owner_device_id', '') or self.device_id, 'device'),
            _cloud_file_component(identity.get('origin_user_id', '') or identity.get('user_id', ''), 'origin'),
            _cloud_file_component(conversation.get('id', ''), 'conversation'),
            'events',
        )
        filename = '{}-{}-{}.json'.format(
            _cloud_file_component(sealed.get('producer_id', ''), 'producer'),
            _cloud_file_component(sealed.get('producer_seq', ''), 'seq'),
            _cloud_file_component(sealed.get('event_type', ''), 'event'),
        )
        return self.backend.publish_json(directory, filename, sealed)

    def read_events(self, conversation: dict) -> list[dict]:
        identity = conversation.get('identity') if isinstance(conversation.get('identity'), dict) else local_conversation_identity()
        directory = Path(self.backend.path(
            'canonical',
            _cloud_file_component(identity.get('owner_user_id', '') or identity.get('user_id', ''), 'owner'),
            _cloud_file_component(identity.get('owner_device_id', '') or self.device_id, 'device'),
            _cloud_file_component(identity.get('origin_user_id', '') or identity.get('user_id', ''), 'origin'),
            _cloud_file_component(conversation.get('id', ''), 'conversation'),
            'events',
        ))
        deduped = {}
        for path in sorted(directory.glob('*.json')) if directory.exists() else []:
            payload = self.backend.read_json(str(path), timeout=0.5)
            if not verify_cloud_payload(payload):
                continue
            key = (str(payload.get('producer_id', '') or ''), str(payload.get('producer_seq', '') or ''))
            deduped.setdefault(key, payload)
        return sorted(
            deduped.values(),
            key=lambda item: (str(item.get('created_at', '') or ''), str(item.get('producer_id', '') or ''), str(item.get('producer_seq', '') or '')),
        )

    def publish_revision(self, record: dict) -> str:
        record = cloud_canonical_record(record)
        identity = record.get('identity') if isinstance(record.get('identity'), dict) else local_conversation_identity()
        owner_user = _cloud_file_component(identity.get('owner_user_id', '') or identity.get('user_id', ''), 'owner')
        owner_device = _cloud_file_component(identity.get('owner_device_id', '') or self.device_id, 'device')
        origin_user = _cloud_file_component(identity.get('origin_user_id', '') or identity.get('user_id', ''), 'origin')
        conversation_id = _cloud_file_component(record.get('id', ''), 'conversation')
        route_epoch = int(record.get('route_epoch', 0) or 0)
        revision = int(record.get('revision', 0) or 0)
        sealed = seal_cloud_payload(record)
        return self.backend.publish_json(
            self.backend.path('canonical', owner_user, owner_device, origin_user, conversation_id, 'revisions'),
            f'{route_epoch}-{revision}-{owner_device}.json',
            sealed,
        )

    def shutdown(self):
        if not self.enabled:
            return
        self.accepting = False
        self.registry.publish('draining', accept_remote_tasks=False)
        self._stop_event.set()
        thread = self._thread
        if thread is not None and thread.is_alive() and thread is not threading.current_thread():
            thread.join(timeout=max(1.0, self.poll_interval * 2))
        self.registry.publish('offline', accept_remote_tasks=False)


def cloud_device_logical_agent_profile(device: dict, logical_agent_id: str) -> str:
    """Resolve only the target device's advertised logical-agent mapping."""
    device = device if isinstance(device, dict) else {}
    capabilities = device.get('execution_capabilities') if isinstance(device.get('execution_capabilities'), dict) else {}
    for container in (capabilities, device):
        for key in ('logical_agent_profiles', 'logical_agent_mapping', 'agent_profiles'):
            mapping = container.get(key) if isinstance(container.get(key), dict) else {}
            value = str(mapping.get(str(logical_agent_id or ''), '') or '').strip()
            if value:
                return value
    return ''


def conversation_owned_elsewhere(record: dict, device_id: str | None = None) -> str:
    """Owner device id when `record` belongs to a device other than `device_id`
    (default: this Mac), else ''. Conversations without an owner are local."""
    record = record if isinstance(record, dict) else {}
    identity = record.get('identity') if isinstance(record.get('identity'), dict) else {}
    if not identity:
        extensions = record.get('extensions') if isinstance(record.get('extensions'), dict) else {}
        identity = extensions.get('identity') if isinstance(extensions.get('identity'), dict) else {}
    owner = str(identity.get('owner_device_id', '') or '').strip()
    local = BROCCOLI_LOCAL_DEVICE_ID if device_id is None else device_id
    if not owner or _cloud_file_component(owner, 'device') == _cloud_file_component(local, 'device'):
        return ''
    return owner


def install_conversation_mirror(path: str, payload: dict) -> dict | None:
    """Write this device's read-only copy of a conversation another device owns.

    Goes around write_conversation_record on purpose (it refuses writes to
    conversations owned elsewhere) and drops the cached copy so the next load
    reads the new file.
    """
    payload = {
        str(key): copy.deepcopy(value)
        for key, value in (payload or {}).items()
        if str(key) not in {'content_hash', 'path'} and not str(key).startswith('_')
    }
    path = os.path.abspath(os.path.expanduser(str(path or '')))
    ensure_broccoli_data_dir()
    os.makedirs(os.path.dirname(path), exist_ok=True)
    _write_json_atomic(path, payload, indent=None)
    with _CONVERSATION_RECORD_CACHE_LOCK:
        _CONVERSATION_RECORD_CACHE.pop(path, None)
        _CONVERSATION_RECORD_CACHE_META.pop(path, None)
        _CONVERSATION_RECORD_GENERATION.pop(path, None)
        _CONVERSATION_LAZY_RETRIEVAL.pop(path, None)
    resolver = get_conversation_path_resolver()
    if resolver is not None:
        resolver.register(str(payload.get('id', '') or ''), path, payload)
    record = load_conversation_record(path, include_retrieval=False)
    if isinstance(record, dict):
        try:
            _update_conversation_history_index(record)
        except Exception:
            logging.exception('History index update for a conversation copy failed.')
    return record


class RemoteNewConversationService:
    """M4a Move & Send state machine for a conversation that is born on its executor."""

    # Status wording lives in icloud_status_label() (translated when shown).

    # The target must acknowledge within this time; the request carries the same
    # deadline (expires_at_epoch) so a late target refuses it instead of running it.
    ACK_TIMEOUT_SECONDS = 15 * 60
    # A device whose newest snapshot is older than this counts as unresponsive
    # (it publishes one every ICloudTaskTransport.HEARTBEAT_SECONDS).
    DEVICE_STALE_SECONDS = 10 * 60
    DEVICE_CACHE_SECONDS = 30
    QUIT_GRACE_SECONDS = 120

    def __init__(self, transport: ICloudTaskTransport):
        self.transport = transport
        self.pending: dict[str, dict] = {}
        self._device_cache = {'at': 0.0, 'devices': {}}

    @staticmethod
    def _heartbeat_age(device: dict, now: float) -> float | None:
        try:
            beat = float(device.get('heartbeat_epoch', 0) or 0)
        except (TypeError, ValueError):
            beat = 0.0
        return max(0.0, now - beat) if beat else None

    def device_options(self, logical_agent_id: str = 'main-agent') -> list[dict]:
        options = []
        now = time.time()
        for device_id, device in sorted(self.transport.registry.list_latest().items()):
            if device_id == self.transport.device_id:
                continue
            mapped = cloud_device_logical_agent_profile(device, logical_agent_id)
            accepts = bool(device.get('accept_remote_tasks', False))
            availability = str(device.get('availability', '') or 'offline')
            age = self._heartbeat_age(device, now)
            availability_note = ''
            if availability == 'online' and age is not None and age > self.DEVICE_STALE_SECONDS:
                # Marked online but silent: crashed, asleep, or iCloud is not syncing.
                # Still selectable (the request waits up to ACK_TIMEOUT_SECONDS).
                availability = 'unresponsive'
                availability_note = icloud_message(
                    'unresponsive_note', minutes=int(age // 60), limit=int(self.ACK_TIMEOUT_SECONDS // 60))
            options.append({
                'device_id': device_id,
                'display_name': str(device.get('display_name', '') or device_id),
                'owner_user_id': str(device.get('owner_user_id', '') or BROCCOLI_LOCAL_USER_ID),
                'availability': availability,
                'availability_note': availability_note,
                'last_seen_seconds': age,
                'queue_depth': int(device.get('queue_depth', 0) or 0),
                'selectable': accepts,
                'unavailable_reason': '' if accepts else icloud_message(
                    'remote_tasks_off_on_device', device=str(device.get('display_name', '') or device_id)),
                'resolved_agent_profile_id': mapped,
                'profile_fallback': not bool(mapped),
                'profile_note': '' if mapped else icloud_message('default_profile_note'),
                'raw': device,
            })
        return options

    def _publish_assets(self, request: dict, paths: list[str]) -> list[dict]:
        manifests = []
        owner_user = _cloud_file_component(request.get('owner_user_id', ''), 'owner')
        executor = _cloud_file_component(request.get('executor_id', ''), 'device')
        origin = _cloud_file_component(request.get('origin_user_id', ''), 'origin')
        conversation_id = _cloud_file_component(request.get('conversation_id', ''), 'conversation')
        directory = self.transport.backend.path(
            'canonical', owner_user, executor, origin, conversation_id, 'assets',
        )
        for source in paths or []:
            source = os.path.abspath(os.path.expanduser(str(source or '')))
            try:
                digest = hashlib.sha256(Path(source).read_bytes()).hexdigest()
            except OSError as exc:
                raise ICloudUserError('attachment_unreadable', name=os.path.basename(source)) from exc
            published = self.transport.backend.publish_file(directory, digest, source, expected_hash=digest)
            manifests.append({
                'asset_id': digest,
                'sha256': digest,
                'name': os.path.basename(source),
                'size': os.path.getsize(source),
                'cloud_path': os.path.relpath(published, self.transport.backend.root),
            })
        return manifests

    def send(self,
             question: str,
             target: dict,
             *,
             logical_agent_id: str = 'main-agent',
             attachment_paths: list[str] | None = None,
             project_workspace_id: str = '',
             execution_preferences: dict | None = None,
             required_capabilities: list[str] | None = None) -> dict:
        question = str(question or '')
        target = target if isinstance(target, dict) else {}
        if not self.transport.enabled:
            raise ICloudUserError('transport_disabled')
        if not question.strip() and not attachment_paths:
            raise ICloudUserValueError('prompt_required')
        if not bool(target.get('selectable', target.get('accept_remote_tasks', False))):
            raise ICloudUserError(
                'remote_tasks_off_on_device',
                device=str(target.get('display_name', '') or target.get('device_id', '') or ''),
            )
        now = datetime.datetime.now().isoformat(timespec='milliseconds')
        conversation_id = new_broccoli_uuid()
        task_id = new_broccoli_uuid('task-')
        attempt_id = new_broccoli_uuid('attempt-')
        owner_user_id = str(target.get('owner_user_id', '') or BROCCOLI_LOCAL_USER_ID)
        mapped_profile = str(
            target.get('resolved_agent_profile_id', '')
            or cloud_device_logical_agent_profile(target.get('raw', target), logical_agent_id)
            or ''
        )
        request = {
            'schema_version': ICLOUD_PROTOCOL_VERSION,
            'record_type': 'TaskRequest',
            'task_kind': 'new_conversation',
            'task_id': task_id,
            'attempt_id': attempt_id,
            'turn_id': new_broccoli_uuid('turn-'),
            'conversation_id': conversation_id,
            'space_id': '',
            'project_workspace_id': str(project_workspace_id or ''),
            'user_id': BROCCOLI_LOCAL_USER_ID,
            'member_id': BROCCOLI_LOCAL_MEMBER_ID,
            'origin_user_id': BROCCOLI_LOCAL_USER_ID,
            'source_device_id': self.transport.device_id,
            'executor_id': str(target.get('device_id', '') or ''),
            'owner_device_id': str(target.get('device_id', '') or ''),
            'owner_user_id': owner_user_id,
            'logical_agent_id': str(logical_agent_id or 'main-agent'),
            'agent_profile_id': mapped_profile,
            'route_epoch': 0,
            'base_revision': 0,
            'question': question,
            'asset_manifest': [],
            'execution_preferences': dict(execution_preferences or {}),
            'required_capabilities': list(required_capabilities or []),
            'created_at': now,
            'expires_at_epoch': round(time.time() + self.ACK_TIMEOUT_SECONDS, 3),
        }
        return self._submit(request, target, attachment_paths, task_kind='new_conversation')

    def _submit(self, request: dict, target: dict, attachment_paths: list[str] | None, **state_fields) -> dict:
        state = {
            'task_id': request['task_id'],
            'attempt_id': request['attempt_id'],
            'conversation_id': request['conversation_id'],
            'status': 'publishing',
            'request': request,
            'target': dict(target),
            'prompt_cleared': False,
            'created_at': request['created_at'],
            'created_epoch': time.time(),
            'ack_deadline_epoch': request['expires_at_epoch'],
            **state_fields,
        }
        self.pending[request['task_id']] = state
        try:
            request['asset_manifest'] = self._publish_assets(request, list(attachment_paths or []))
            destination = self.transport.submit_task(request)
        except ICloudUserError as exc:
            state['status'] = 'failed'
            state['error'] = str(exc)
            raise
        except Exception as exc:
            # Disk / iCloud Drive errors: a translated lead-in, the system detail as is.
            wrapped = ICloudUserError('cloud_write_failed', detail=str(exc))
            state['status'] = 'failed'
            state['error'] = str(wrapped)
            raise wrapped from exc
        state['request'] = request
        state['destination'] = destination
        state['status'] = 'waiting_ack'
        return state

    def send_continue(self,
                      question: str,
                      record: dict,
                      target: dict,
                      *,
                      attachment_paths: list[str] | None = None,
                      execution_preferences: dict | None = None,
                      display_path: str = '') -> dict:
        """Ask the device that owns `record` to run one more turn of it.

        Only the owner writes a conversation, so a turn sent from here runs there;
        the answer comes back as a new revision and replaces the local copy at
        `display_path`.
        """
        question = str(question or '')
        record = record if isinstance(record, dict) else {}
        target = target if isinstance(target, dict) else {}
        if not self.transport.enabled:
            raise ICloudUserError('transport_disabled')
        if not question.strip() and not attachment_paths:
            raise ICloudUserValueError('prompt_required')
        identity = record.get('identity') if isinstance(record.get('identity'), dict) else {}
        owner_device_id = str(identity.get('owner_device_id', '') or target.get('device_id', '') or '')
        conversation_id = str(record.get('id', '') or '')
        if not owner_device_id or not conversation_id:
            raise ICloudUserValueError('no_owner_device')
        if _cloud_file_component(owner_device_id, 'device') == self.transport.device_id:
            raise ICloudUserValueError('owned_here')
        now = datetime.datetime.now().isoformat(timespec='milliseconds')
        request = {
            'schema_version': ICLOUD_PROTOCOL_VERSION,
            'record_type': 'TaskRequest',
            'task_kind': 'continue_conversation',
            'task_id': new_broccoli_uuid('task-'),
            'attempt_id': new_broccoli_uuid('attempt-'),
            'turn_id': new_broccoli_uuid('turn-'),
            'conversation_id': conversation_id,
            'conversation_title': str(record.get('title', '') or ''),
            'space_id': '',
            'project_workspace_id': '',
            'user_id': BROCCOLI_LOCAL_USER_ID,
            'member_id': BROCCOLI_LOCAL_MEMBER_ID,
            'origin_user_id': str(identity.get('origin_user_id', '') or identity.get('user_id', '') or BROCCOLI_LOCAL_USER_ID),
            'source_device_id': self.transport.device_id,
            'executor_id': owner_device_id,
            'owner_device_id': owner_device_id,
            'owner_user_id': str(identity.get('owner_user_id', '') or identity.get('user_id', '') or BROCCOLI_LOCAL_USER_ID),
            'logical_agent_id': str(record.get('logical_agent_id', '') or 'main-agent'),
            'agent_profile_id': '',
            'route_epoch': int(record.get('route_epoch', 0) or 0),
            'base_revision': int(record.get('revision', 0) or 0),
            'question': question,
            'asset_manifest': [],
            'execution_preferences': dict(execution_preferences or {}),
            'required_capabilities': ['chat'],
            'created_at': now,
            'expires_at_epoch': round(time.time() + self.ACK_TIMEOUT_SECONDS, 3),
        }
        target = dict(target, device_id=str(target.get('device_id', '') or owner_device_id))
        return self._submit(
            request, target, attachment_paths,
            task_kind='continue_conversation', display_path=str(display_path or ''),
        )

    def status_card(self, task_id: str) -> dict:
        state = self.pending.get(str(task_id or ''), {})
        status = str(state.get('status', '') or 'failed')
        target = state.get('target') if isinstance(state.get('target'), dict) else {}
        return {
            'task_id': str(state.get('task_id', '') or ''),
            'conversation_id': str(state.get('conversation_id', '') or ''),
            'status': status,
            'label': icloud_status_label(status),
            'device_name': str(target.get('display_name', '') or target.get('device_id', '') or ''),
            'profile_fallback': bool(state.get('profile_fallback', target.get('profile_fallback', False))),
            'resolved_agent_profile_id': str(state.get('resolved_agent_profile_id', '') or ''),
            'error': str(state.get('error', '') or ''),
            'base_revision_stale': bool(state.get('base_revision_stale', False)),
        }

    @staticmethod
    def _target_name(state: dict) -> str:
        target = state.get('target') if isinstance(state.get('target'), dict) else {}
        return str(target.get('display_name', '') or target.get('device_id', '') or '')

    def _remote_error_text(self, state: dict, payload: dict, *, fallback_code: str) -> str:
        """Text for an error another device reported: its code in this Mac's
        language when it sent one, else its own text (free-form failures such as a
        model provider's message), else a generic line."""
        payload = payload if isinstance(payload, dict) else {}
        code = str(payload.get('error_code', '') or '')
        params = payload.get('error_params') if isinstance(payload.get('error_params'), dict) else {}
        device = self._target_name(state)
        if code:
            return icloud_message(code, **dict(params, device=device))
        text = str(payload.get('error', '') or '').strip()
        return text or icloud_message(fallback_code, device=device)

    def apply_ack(self, acknowledgement: dict, clear_callback=None) -> dict | None:
        if not verify_cloud_payload(acknowledgement):
            return None
        state = self.pending.get(str(acknowledgement.get('task_id', '') or ''))
        if not isinstance(state, dict):
            return None
        request = state.get('request') if isinstance(state.get('request'), dict) else {}
        if str(acknowledgement.get('attempt_id', '') or '') != str(state.get('attempt_id', '') or ''):
            return None
        if int(acknowledgement.get('accepted_route_epoch', -1) or 0) != int(request.get('route_epoch', 0) or 0):
            return None
        if str(state.get('status', '') or '') in self.FINISHED_STATUSES:
            # Finished or already timed out here; the ack file is re-read on every
            # poll and must not revive the task.
            return None
        if not bool(acknowledgement.get('accepted', False)):
            state['status'] = 'failed'
            state['error'] = self._remote_error_text(state, acknowledgement, fallback_code='target_rejected')
            return state
        # Only the first reading moves the task on; later re-reads must not undo
        # a Stop (cancel_requested) or restart the lost-contact clock.
        if str(state.get('status', '') or '') in {'publishing', 'waiting_ack'}:
            state['status'] = 'executing'
        state.setdefault('ack_received_epoch', time.time())
        state['acknowledgement'] = copy.deepcopy(acknowledgement)
        # This device's copy was older than the owner's; the owner still ran the
        # turn on its newest version (the status card says so).
        state['base_revision_stale'] = bool(acknowledgement.get('base_revision_stale', False))
        state['profile_fallback'] = bool(acknowledgement.get('profile_fallback', False))
        state['resolved_agent_profile_id'] = str(acknowledgement.get('resolved_agent_profile_id', '') or '')
        if not bool(state.get('prompt_cleared', False)) and callable(clear_callback):
            clear_callback()
            state['prompt_cleared'] = True
        return state

    def poll_acknowledgements(self, clear_callback=None) -> list[dict]:
        updated = []
        for acknowledgement in self.transport.read_acknowledgements():
            state = self.apply_ack(acknowledgement, clear_callback=clear_callback)
            if state is not None:
                updated.append(state)
        return updated

    def accept_remote_request(self,
                              request: dict,
                              run: dict,
                              *,
                              profile_mapping: dict | None = None,
                              default_profile_id: str = '',
                              execution_callback=None) -> dict:
        task_kind = str(request.get('task_kind', '') or '')
        if task_kind not in {'new_conversation', 'continue_conversation'}:
            raise ICloudUserValueError('unsupported_task')
        if task_kind == 'new_conversation' and (
            int(request.get('route_epoch', 0) or 0) != 0 or int(request.get('base_revision', 0) or 0) != 0
        ):
            raise ICloudUserValueError('invalid_new_conversation')
        logical_agent_id = str(request.get('logical_agent_id', '') or 'main-agent')
        mapping = dict(profile_mapping or {})
        resolved_profile = str(mapping.get(logical_agent_id, '') or '').strip()
        profile_fallback = not bool(resolved_profile)
        resolved_profile = resolved_profile or str(default_profile_id or '').strip()
        conversation_id = str(request.get('conversation_id', '') or '')
        base_revision_stale = False
        if task_kind == 'continue_conversation':
            path = resolve_conversation_path(conversation_id)
            record = load_conversation_record(path, include_retrieval=False) if path else None
            if not isinstance(record, dict):
                raise ICloudUserError('conversation_not_on_device')
            identity = record.get('identity') if isinstance(record.get('identity'), dict) else {}
            if _cloud_file_component(identity.get('owner_device_id', '') or self.transport.device_id, 'device') != self.transport.device_id:
                raise ICloudUserValueError('not_owner_anymore')
            # The owner is the only writer, so a new turn simply goes after its
            # newest content. A sender whose copy was older is told (ack flag),
            # not refused: any save here bumps the revision, so an exact match
            # would turn down most follow-ups.
            base_revision_stale = (
                int(request.get('route_epoch', 0) or 0) != int(record.get('route_epoch', 0) or 0)
                or int(request.get('base_revision', 0) or 0) != int(record.get('revision', 0) or 0)
            )
        else:
            title = sanitize_conversation_title(str(request.get('question', '') or _tr('Remote conversation')))
            path = os.path.join(CONVERSATIONS_DIR, f'{conversation_id}_{sanitize_conversation_filename(title)}.json')
            identity = {
                'user_id': str(request.get('owner_user_id', '') or BROCCOLI_LOCAL_USER_ID),
                'member_id': str(request.get('member_id', '') or ''),
                'owner_user_id': str(request.get('owner_user_id', '') or BROCCOLI_LOCAL_USER_ID),
                'owner_device_id': self.transport.device_id,
                'origin_user_id': str(request.get('origin_user_id', '') or request.get('user_id', '') or ''),
                'origin_device_id': str(request.get('source_device_id', '') or ''),
            }
            record = write_conversation_record(path, {
                'id': conversation_id,
                'title': title,
                'messages': [],
                'identity': identity,
                'route_epoch': 0,
                'logical_agent_id': logical_agent_id,
                'created_at': str(request.get('created_at', '') or datetime.datetime.now().isoformat(timespec='seconds')),
                'updated_at': datetime.datetime.now().isoformat(timespec='seconds'),
                'extensions': {
                    'remote_task_id': str(request.get('task_id', '') or ''),
                    'remote_attempt_id': str(request.get('attempt_id', '') or ''),
                    'remote_status': 'executing',
                },
            })
            self.transport.publish_revision(record)
        run['conversation_id'] = conversation_id
        run['conversation_path'] = record['path']
        run['status'] = 'accepted'
        run.setdefault('config', {}).update({
            'conversation_path': record['path'],
            'remote_request': copy.deepcopy(request),
            'resolved_agent_profile_id': resolved_profile,
            'profile_fallback': profile_fallback,
            'task_kind': task_kind,
        })
        result = {}
        if callable(execution_callback):
            value = execution_callback({
                'request': copy.deepcopy(request),
                'run': run,
                'record': record,
                'conversation_path': record['path'],
                'resolved_agent_profile_id': resolved_profile,
                'profile_fallback': profile_fallback,
                'task_kind': task_kind,
            })
            result = value if isinstance(value, dict) else {}
        if isinstance(result.get('messages'), list) or str(result.get('answer', '') or ''):
            messages = list(result.get('messages') or [])
            if not messages:
                messages, _markdown = append_chat_turn([], str(request.get('question', '') or ''), str(result.get('answer', '') or ''))
            record['messages'] = messages
            # Top level too: on save the top-level copy wins over extensions.
            record['remote_status'] = str(result.get('status', '') or 'completed')
            record.setdefault('extensions', {})['remote_status'] = record['remote_status']
            record['updated_at'] = datetime.datetime.now().isoformat(timespec='seconds')
            record = write_conversation_record(record['path'], record)
            self.transport.publish_revision(record)
        store = self.transport._store()
        if store is not None:
            store.update_run(run)
        capability_hash = hashlib.sha256(json.dumps(mapping, sort_keys=True).encode('utf-8')).hexdigest()
        return {
            'accepted': True,
            'resolved_agent_profile_id': resolved_profile,
            'profile_fallback': profile_fallback,
            'capability_snapshot_hash': capability_hash,
            'conversation_path': record['path'],
            'base_revision_stale': base_revision_stale,
        }

    # Terminal states the executor reports for one attempt (attempt_terminal event,
    # or extensions.remote_status on its last revision).
    REMOTE_FAILURE_STATES = {'failed', 'rejected'}
    REMOTE_STOP_STATES = {'cancelled', 'needs_reconciliation'}
    FINISHED_STATUSES = {'completed', 'failed', 'cancelled', 'needs_reconciliation'}

    @staticmethod
    def _conversation_ref(request: dict) -> dict:
        return {
            'id': str(request.get('conversation_id', '') or ''),
            'route_epoch': int(request.get('route_epoch', 0) or 0),
            'identity': {
                'owner_user_id': str(request.get('owner_user_id', '') or BROCCOLI_LOCAL_USER_ID),
                'owner_device_id': str(request.get('owner_device_id', '') or ''),
                'origin_user_id': str(request.get('origin_user_id', '') or BROCCOLI_LOCAL_USER_ID),
            },
        }

    def _latest_revision(self, request: dict) -> dict | None:
        directory = Path(self.transport.backend.path(
            'canonical',
            _cloud_file_component(request.get('owner_user_id', ''), 'owner'),
            _cloud_file_component(request.get('owner_device_id', ''), 'device'),
            _cloud_file_component(request.get('origin_user_id', ''), 'origin'),
            _cloud_file_component(request.get('conversation_id', ''), 'conversation'),
            'revisions',
        ))
        candidates = []
        for path in directory.glob('*.json') if directory.exists() else []:
            payload = self.transport.backend.read_json(str(path), timeout=0.5)
            if verify_cloud_payload(payload):
                candidates.append(payload)
        if not candidates:
            return None
        candidates.sort(key=lambda item: (int(item.get('route_epoch', 0) or 0), int(item.get('revision', 0) or 0)))
        return copy.deepcopy(candidates[-1])

    @staticmethod
    def _revision_attempt_fields(payload: dict) -> tuple[str, str]:
        extensions = payload.get('extensions') if isinstance(payload.get('extensions'), dict) else {}
        attempt = str(extensions.get('remote_attempt_id', '') or payload.get('remote_attempt_id', '') or '')
        status = str(extensions.get('remote_status', '') or payload.get('remote_status', '') or '')
        return attempt, status

    def _revision_has_result(self, payload: dict, state: dict | None = None) -> bool:
        state = state if isinstance(state, dict) else {}
        attempt, remote_status = self._revision_attempt_fields(payload)
        if str(state.get('task_kind', '') or '') == 'continue_conversation':
            # The conversation already holds older answers; only the revision
            # this attempt finished counts.
            return attempt == str(state.get('attempt_id', '') or '') and remote_status == 'completed'
        messages = payload.get('messages') if isinstance(payload.get('messages'), list) else []
        if any(str(item.get('role', '') or '') == 'assistant' for item in messages if isinstance(item, dict)):
            return True
        return remote_status == 'completed'

    @staticmethod
    def _revision_covers_outcome(payload: dict, outcome: dict | None) -> bool:
        """A completed attempt whose own revision was already superseded: any
        revision at or after the one it reported contains its answer."""
        if not isinstance(outcome, dict) or str(outcome.get('state', '') or '') != 'completed':
            return False
        try:
            reported = (int(outcome.get('route_epoch', 0) or 0), int(outcome.get('revision', 0) or 0))
            current = (int(payload.get('route_epoch', 0) or 0), int(payload.get('revision', 0) or 0))
        except (TypeError, ValueError):
            return False
        return reported[1] > 0 and current >= reported

    def _attempt_events(self, task_id: str) -> tuple[dict | None, dict | None]:
        """(terminal outcome, latest progress) the executor published for this attempt."""
        state = self.pending.get(str(task_id or ''))
        if not isinstance(state, dict):
            return None, None
        request = state.get('request') if isinstance(state.get('request'), dict) else {}
        attempt_id = str(request.get('attempt_id', '') or '')
        outcome = None
        progress = None
        for event in self.transport.read_events(self._conversation_ref(request)):
            if str(event.get('attempt_id', '') or '') != attempt_id:
                continue
            event_type = str(event.get('event_type', '') or '')
            if event_type == 'attempt_terminal':
                outcome = {
                    'state': str(event.get('state', '') or ''),
                    'error': str(event.get('error', '') or event.get('message', '') or ''),
                    'error_code': str(event.get('error_code', '') or ''),
                    'error_params': event.get('error_params') if isinstance(event.get('error_params'), dict) else {},
                    'revision': event.get('revision', 0),
                    'route_epoch': event.get('route_epoch', 0),
                }
            elif event_type == 'incident' and outcome is None and str(event.get('incident_type', '') or '') == 'execution_failed':
                # Executors older than the attempt_terminal event reported a failed
                # run only as this incident.
                outcome = {'state': 'failed', 'error': str(event.get('message', '') or '')}
            elif event_type == 'attempt_status':
                progress = {'state': str(event.get('state', '') or ''), 'position': event.get('position', 0)}
        return outcome, progress

    def terminal_outcome(self, task_id: str) -> dict | None:
        """Latest terminal fact the executor published for this attempt, if any."""
        return self._attempt_events(task_id)[0]

    def refresh_remote_state(self, task_id: str) -> dict | None:
        """One poll step after the request left this device.

        Returns the synced result once the answer is in the cloud; otherwise updates
        the pending state (executing / queued / failed / cancelled) and returns
        None. A complete answer wins over a late failure or cancel report.
        """
        state = self.pending.get(str(task_id or ''))
        if not isinstance(state, dict) or str(state.get('status', '') or '') in self.FINISHED_STATUSES:
            return None
        request = state.get('request') if isinstance(state.get('request'), dict) else {}
        latest = self._latest_revision(request)
        outcome, progress = self._attempt_events(task_id)
        if latest is not None and (
            self._revision_has_result(latest, state) or self._revision_covers_outcome(latest, outcome)
        ):
            return self._install_result(state, request, latest)
        if outcome is None and latest is not None:
            attempt, remote_status = self._revision_attempt_fields(latest)
            if attempt in {'', str(state.get('attempt_id', '') or '')} and (
                remote_status in self.REMOTE_FAILURE_STATES | self.REMOTE_STOP_STATES
            ):
                extensions = latest.get('extensions') if isinstance(latest.get('extensions'), dict) else {}
                outcome = {'state': remote_status, 'error': str(extensions.get('remote_error', '') or '')}
        terminal_state = str((outcome or {}).get('state', '') or '')
        status = str(state.get('status', '') or '')
        if terminal_state in self.REMOTE_FAILURE_STATES:
            state['status'] = 'failed'
            state['error'] = self._remote_error_text(state, outcome, fallback_code='no_failure_details')
        elif terminal_state in self.REMOTE_STOP_STATES:
            state['status'] = terminal_state
        elif terminal_state == 'completed':
            pass  # answer revision still syncing
        elif isinstance(progress, dict) and progress.get('state') == 'queued' and status in {'publishing', 'waiting_ack', 'executing'}:
            state['status'] = 'queued'
            state['queue_position'] = progress.get('position', 0)
        elif isinstance(progress, dict) and progress.get('state') == 'running' and status == 'queued':
            state['status'] = 'executing'
        elif (
            latest is not None and status in {'publishing', 'waiting_ack'}
            and str(state.get('task_kind', '') or '') != 'continue_conversation'
        ):
            # A new conversation's first revision means the target picked it up.
            state['status'] = 'executing'
        return None

    def _device_record(self, device_id: str, now: float) -> dict:
        # The poll runs every second on the GUI thread; the registry is re-read
        # at most every DEVICE_CACHE_SECONDS.
        if now - float(self._device_cache.get('at', 0.0) or 0.0) >= self.DEVICE_CACHE_SECONDS:
            self._device_cache = {'at': now, 'devices': self.transport.registry.list_latest()}
        device = (self._device_cache.get('devices') or {}).get(_cloud_file_component(device_id, 'device'))
        return device if isinstance(device, dict) else {}

    def check_timeouts(self, task_id: str, now: float | None = None) -> bool:
        """Fail a waiting task that can no longer finish. True when it just failed.

        - No ack by the request's deadline: the target never picked it up, and it
          refuses the expired request if it shows up later.
        - Acked, then the target quit (newer offline snapshot) or went silent for
          DEVICE_STALE_SECONDS: the run is gone or unreachable.
        """
        state = self.pending.get(str(task_id or ''))
        if not isinstance(state, dict):
            return False
        status = str(state.get('status', '') or '')
        if status in self.FINISHED_STATUSES:
            return False
        now = time.time() if now is None else float(now)
        request = state.get('request') if isinstance(state.get('request'), dict) else {}
        device_name = self._target_name(state)
        if status in {'publishing', 'waiting_ack'}:
            deadline = float(state.get('ack_deadline_epoch', 0) or 0)
            if deadline and now > deadline:
                state['status'] = 'failed'
                state['error'] = icloud_message(
                    'ack_timeout', device=device_name, minutes=int(self.ACK_TIMEOUT_SECONDS // 60))
                return True
            return False
        device = self._device_record(str(request.get('executor_id', '') or ''), now)
        age = self._heartbeat_age(device, now)
        if age is None:
            return False  # target build without heartbeats: nothing reliable to judge by
        beat = now - age
        created = float(state.get('created_epoch', 0) or 0)
        if str(device.get('availability', '') or '') in {'offline', 'draining'} and created and beat >= created:
            # iCloud may deliver the offline snapshot before a just-finished answer;
            # give the answer QUIT_GRACE_SECONDS to arrive (refresh runs first).
            seen = float(state.setdefault('target_quit_seen_epoch', now) or now)
            if now - seen >= self.QUIT_GRACE_SECONDS:
                state['status'] = 'failed'
                state['error'] = icloud_message('target_quit', device=device_name)
                return True
            return False
        acked = float(state.get('ack_received_epoch', 0) or 0) or created
        if age > self.DEVICE_STALE_SECONDS and acked and now - acked > self.DEVICE_STALE_SECONDS:
            state['status'] = 'failed'
            state['error'] = icloud_message('lost_contact', device=device_name, minutes=int(age // 60))
            return True
        return False

    def sync_latest_result(self, task_id: str) -> dict | None:
        state = self.pending.get(str(task_id or ''))
        if not isinstance(state, dict):
            return None
        request = state.get('request') if isinstance(state.get('request'), dict) else {}
        payload = self._latest_revision(request)
        if payload is None:
            return None
        if not self._revision_has_result(payload, state):
            if str(state.get('status', '') or '') in {'publishing', 'waiting_ack'}:
                state['status'] = 'executing'
            return None
        return self._install_result(state, request, payload)

    def _install_result(self, state: dict, request: dict, payload: dict) -> dict:
        payload.pop('content_hash', None)
        local_path = ''
        display_path = os.path.abspath(os.path.expanduser(str(state.get('display_path', '') or ''))) if state.get('display_path') else ''
        conversations_root = os.path.abspath(CONVERSATIONS_DIR)
        if display_path and os.path.commonpath([conversations_root, display_path]) == conversations_root:
            # A follow-up updates the copy the user has open, even if the title
            # (and so the default file name) changed on the owner.
            local_path = display_path
        if not local_path:
            title = sanitize_conversation_title(payload.get('title', '') or _tr('Remote conversation'))
            local_path = os.path.join(
                CONVERSATIONS_DIR,
                f'{request.get("conversation_id", "")}_{sanitize_conversation_filename(title)}.json',
            )
        install_conversation_mirror(local_path, payload)
        state['status'] = 'completed'
        state['local_path'] = local_path
        state['record'] = payload
        return {'path': local_path, 'record': payload, 'state': state}


_ACTIVE_CONVERSATION_MIGRATION_MANAGER = None
# Set to this device's iCloud id once the main window joins the iCloud protocol;
# write_conversation_record then refuses to save conversations owned elsewhere.
_ICLOUD_MIRROR_GUARD_DEVICE_ID = None


class ConversationMigrationManager:
    """Durable M4b prepare/ready/commit ownership transfer protocol."""

    BLOCKING_PHASES = {'prepare_sent', 'ready', 'committing', 'committed_source'}
    PRECOMMIT_PHASES = {'preparing', 'prepare_sent', 'ready'}
    # How long the target waits for staged parts to finish syncing before it
    # rejects the migration (asset_timeout).
    ASSET_WAIT_SECONDS = 30 * 60
    # How long the source keeps a prepare out (conversation frozen) with no ready
    # or reject before cancelling it. Longer than ASSET_WAIT_SECONDS so a slow but
    # live target answers first.
    PREPARE_TIMEOUT_SECONDS = 45 * 60
    # A "move it to me" request waits this long for the owner to become idle.
    REQUEST_TIMEOUT_SECONDS = 60 * 60

    def __init__(self,
                 transport: ICloudTaskTransport,
                 *,
                 local_state_root: str | None = None,
                 local_conversations_dir: str | None = None,
                 eligibility_callback=None):
        self.transport = transport
        self.local_state_root = os.path.abspath(os.path.expanduser(str(
            local_state_root or os.path.join(BROCCOLI_APP_DATA_DIR, 'Migrations')
        )))
        self.local_conversations_dir = os.path.abspath(os.path.expanduser(str(
            local_conversations_dir or CONVERSATIONS_DIR
        )))
        self.eligibility_callback = eligibility_callback
        self._lock = threading.RLock()
        self.states: dict[str, dict] = {}
        # "Please move this conversation to X" requests, kept apart from migration
        # states so they never count as the conversation's migration phase.
        self.request_states: dict[str, dict] = {}
        self._load_states()

    def _load_states(self):
        state_dir = Path(self.local_state_root, 'states')
        if not state_dir.exists():
            return
        for path in state_dir.glob('*.json'):
            try:
                payload = json.loads(path.read_text(encoding='utf-8'))
            except Exception:
                continue
            if isinstance(payload, dict) and payload.get('migration_id'):
                self.states[str(payload['migration_id'])] = payload
        for path in Path(self.local_state_root, 'requests').glob('*.json'):
            try:
                payload = json.loads(path.read_text(encoding='utf-8'))
            except Exception:
                continue
            if isinstance(payload, dict) and payload.get('migration_request_id'):
                self.request_states[str(payload['migration_request_id'])] = payload

    def _save_request_state(self, state: dict) -> dict:
        state = dict(state or {})
        state['updated_at'] = datetime.datetime.now().isoformat(timespec='milliseconds')
        request_id = str(state.get('migration_request_id', '') or '')
        if not request_id:
            raise ValueError('Migration request state requires migration_request_id.')
        os.makedirs(os.path.join(self.local_state_root, 'requests'), exist_ok=True)
        _write_json_atomic(os.path.join(self.local_state_root, 'requests', _cloud_file_component(request_id, 'request') + '.json'), state, indent=2)
        self.request_states[request_id] = state
        return state

    def _save_state(self, state: dict) -> dict:
        state = dict(state or {})
        state['updated_at'] = datetime.datetime.now().isoformat(timespec='milliseconds')
        migration_id = str(state.get('migration_id', '') or '')
        if not migration_id:
            raise ValueError('Migration state requires migration_id.')
        os.makedirs(os.path.join(self.local_state_root, 'states'), exist_ok=True)
        _write_json_atomic(os.path.join(self.local_state_root, 'states', migration_id + '.json'), state, indent=2)
        self.states[migration_id] = state
        return state

    def _state_for_conversation(self, conversation_id: str) -> dict | None:
        candidates = [
            state for state in self.states.values()
            if str(state.get('conversation_id', '') or '') == str(conversation_id or '')
            and str(state.get('phase', '') or '') not in {'cancelled', 'rejected'}
        ]
        candidates.sort(key=lambda item: str(item.get('updated_at', '') or ''))
        return candidates[-1] if candidates else None

    def write_allowed(self, conversation_id: str) -> bool:
        state = self._state_for_conversation(conversation_id)
        if not isinstance(state, dict):
            return True
        if str(state.get('role', '') or '') != 'source':
            return True
        return str(state.get('phase', '') or '') not in self.BLOCKING_PHASES

    def _eligibility(self, conversation_id: str, path: str) -> dict:
        if not callable(self.eligibility_callback):
            return {}
        result = self.eligibility_callback(str(conversation_id or ''), str(path or ''))
        return result if isinstance(result, dict) else {}

    def _assert_eligible(self, conversation_id: str, path: str):
        state = self._eligibility(conversation_id, path)
        blockers = []
        if bool(state.get('active_attempt', False)):
            blockers.append('active_attempt')
        if bool(state.get('pending_approval', False)):
            blockers.append('pending_approval')
        if bool(state.get('editor_dirty', False)):
            blockers.append('editor_dirty')
        # Queue items intentionally do not block: they move with the conversation.
        if blockers:
            raise ICloudUserError('migration_busy', blockers=blockers)

    @staticmethod
    def _paths_from_record(record: dict) -> list[tuple[str, str, str]]:
        found = []
        transfer = record.get('structured_transfer') if isinstance(record.get('structured_transfer'), dict) else {}
        for item in transfer.get('parts') or []:
            if isinstance(item, dict):
                path = str(item.get('path', '') or item.get('stored_path', '') or '')
                if path:
                    found.append((path, 'structured_transfer', str(item.get('name', '') or os.path.basename(path))))
        for item in record.get('terminal_commands') or []:
            if not isinstance(item, dict):
                continue
            for key in ('backup_path', 'output_path', 'transcript_path'):
                path = str(item.get(key, '') or '')
                if path:
                    found.append((path, 'terminal_command', str(item.get('id', '') or os.path.basename(path))))
        for item in record.get('outputs') or []:
            if not isinstance(item, dict):
                continue
            for key in ('path', 'stored_path', 'file_path'):
                path = str(item.get(key, '') or '')
                if path:
                    found.append((path, 'output', str(item.get('title', '') or os.path.basename(path))))
        return found

    def _manifest(self, record: dict, conversation_path: str, extra_parts: list[dict] | None = None) -> list[dict]:
        candidates: list[tuple[str, str, str]] = []
        conversation_id = str(record.get('id', '') or Path(conversation_path).stem.split('_', 1)[0])
        attachment_dir = os.path.join(self.local_conversations_dir, f'{conversation_id}_attachments')
        if os.path.isdir(attachment_dir):
            for path in sorted(Path(attachment_dir).rglob('*')):
                if path.is_file():
                    candidates.append((str(path), 'attachment', os.path.relpath(str(path), attachment_dir)))
        candidates.extend(self._paths_from_record(record))
        for item in extra_parts or []:
            if not isinstance(item, dict):
                continue
            path = str(item.get('path', '') or '')
            if path:
                candidates.append((path, str(item.get('kind', '') or 'transfer_part'), str(item.get('logical_path', '') or os.path.basename(path))))
        entries = []
        seen = set()
        for source, kind, logical_path in candidates:
            source = os.path.abspath(os.path.expanduser(source))
            if not os.path.isfile(source):
                raise ICloudUserError('asset_missing', name=os.path.basename(source))
            digest = hashlib.sha256(Path(source).read_bytes()).hexdigest()
            key = (digest, str(kind), str(logical_path))
            if key in seen:
                continue
            seen.add(key)
            entries.append({
                'asset_id': digest,
                'sha256': digest,
                'size': os.path.getsize(source),
                'kind': str(kind),
                'logical_path': str(logical_path),
                'source_path': source,
            })
        entries.sort(key=lambda item: (item['kind'], item['logical_path'], item['asset_id']))
        return entries

    @staticmethod
    def manifest_hash(manifest: list[dict]) -> str:
        portable = [
            {key: value for key, value in item.items() if key != 'source_path'}
            for item in (manifest or []) if isinstance(item, dict)
        ]
        encoded = json.dumps(portable, ensure_ascii=False, sort_keys=True, separators=(',', ':')).encode('utf-8')
        return hashlib.sha256(encoded).hexdigest()

    def _publish_control(self, payload: dict, target_device_id: str, filename: str) -> str:
        return self.transport.backend.publish_json(
            self.transport.backend.path('control', 'inbox', _cloud_file_component(target_device_id, 'device')),
            filename,
            payload,
        )

    def prepare(self,
                conversation_path: str,
                target: dict,
                *,
                extra_parts: list[dict] | None = None,
                queue_items: list[dict] | None = None) -> dict:
        flush_async_file_writes(timeout=5.0)
        conversation_path = resolve_conversation_path(str(conversation_path or ''))
        record = load_conversation_record(conversation_path, include_retrieval=False)
        if not isinstance(record, dict):
            raise ICloudUserError('migration_source_missing')
        conversation_id = str(record.get('id', '') or '')
        identity = record.get('identity') if isinstance(record.get('identity'), dict) else local_conversation_identity()
        current_owner = str(identity.get('owner_device_id', '') or self.transport.device_id)
        if current_owner != self.transport.device_id:
            raise ICloudUserError('not_owner')
        target_device = str((target or {}).get('device_id', '') or '')
        if not target_device or target_device == self.transport.device_id:
            raise ICloudUserValueError('invalid_target')
        existing = self._state_for_conversation(conversation_id)
        if isinstance(existing, dict) and str(existing.get('phase', '') or '') in self.BLOCKING_PHASES:
            if str(existing.get('target_device_id', '') or '') != target_device:
                raise ICloudUserError('conversation_conflict')
            self.resume(str(existing.get('migration_id', '') or ''))
            return self.states[str(existing['migration_id'])]
        self._assert_eligible(conversation_id, conversation_path)
        migration_id = new_broccoli_uuid('migration-')
        marker = {
            'migration_id': migration_id,
            'phase': 'preparing',
            'target_device_id': target_device,
        }
        # Top level too: on save the top-level copy wins over extensions.
        record['migration'] = marker
        record.setdefault('extensions', {})['migration'] = dict(marker)
        record['_migration_internal_write'] = True
        record = write_conversation_record(conversation_path, record)
        if not flush_async_file_writes(timeout=5.0):
            raise ICloudUserError('save_timeout')
        base_revision = int(record.get('revision', 0) or 0)
        route_epoch = int(record.get('route_epoch', 0) or 0)
        manifest = self._manifest(record, conversation_path, extra_parts=extra_parts)
        staging = self.transport.backend.path('control', 'migrations', migration_id, 'parts')
        portable_manifest = []
        for item in manifest:
            try:
                published = self.transport.backend.publish_file(staging, item['asset_id'], item['source_path'], item['sha256'])
            except Exception as exc:
                raise ICloudUserError('cloud_write_failed', detail=str(exc)) from exc
            portable = {key: value for key, value in item.items() if key != 'source_path'}
            portable['cloud_path'] = os.path.relpath(published, self.transport.backend.root)
            portable_manifest.append(portable)
        manifest_digest = self.manifest_hash(portable_manifest)
        created_at = datetime.datetime.now().isoformat(timespec='milliseconds')
        prepare_payload = seal_cloud_payload({
            'schema_version': ICLOUD_PROTOCOL_VERSION,
            'record_type': 'MigrationPrepare',
            'migration_id': migration_id,
            'conversation_id': conversation_id,
            'source_device_id': self.transport.device_id,
            'executor_id': target_device,
            'source_owner_user_id': str(identity.get('owner_user_id', '') or identity.get('user_id', '') or BROCCOLI_LOCAL_USER_ID),
            'target_owner_user_id': str((target or {}).get('owner_user_id', '') or identity.get('owner_user_id', '') or BROCCOLI_LOCAL_USER_ID),
            'origin_user_id': str(identity.get('origin_user_id', '') or identity.get('user_id', '') or BROCCOLI_LOCAL_USER_ID),
            'route_epoch': route_epoch,
            'base_revision': base_revision,
            'manifest': portable_manifest,
            'manifest_hash': manifest_digest,
            'canonical_record': cloud_canonical_record(record),
            'queue_items': _task_store_json_safe(list(queue_items or [])),
            'created_at': created_at,
        })
        state = self._save_state({
            'migration_id': migration_id,
            'conversation_id': conversation_id,
            'role': 'source',
            'phase': 'prepare_sent',
            'source_device_id': self.transport.device_id,
            'target_device_id': target_device,
            'target_display_name': str((target or {}).get('display_name', '') or target_device),
            'target_owner_user_id': str(prepare_payload.get('target_owner_user_id', '') or ''),
            'conversation_path': conversation_path,
            'base_revision': base_revision,
            'route_epoch': route_epoch,
            'manifest_hash': manifest_digest,
            'prepare_payload': prepare_payload,
            'created_at': created_at,
            'prepare_sent_epoch': time.time(),
        })
        self._publish_control(
            prepare_payload,
            target_device,
            f'{self.transport.device_id}-{migration_id}-MigrationPrepare.json',
        )
        return state

    def _publish_reject(self, prepare: dict, reason: str) -> dict:
        payload = seal_cloud_payload({
            'schema_version': ICLOUD_PROTOCOL_VERSION,
            'record_type': 'MigrationReject',
            'migration_id': str(prepare.get('migration_id', '') or ''),
            'conversation_id': str(prepare.get('conversation_id', '') or ''),
            'source_device_id': self.transport.device_id,
            'executor_id': str(prepare.get('source_device_id', '') or ''),
            'reason': str(reason or 'conversation_conflict'),
            'created_at': datetime.datetime.now().isoformat(timespec='milliseconds'),
        })
        self._publish_control(
            payload,
            str(prepare.get('source_device_id', '') or ''),
            f'{self.transport.device_id}-{prepare.get("migration_id", "")}-MigrationReject.json',
        )
        migration_id = str(prepare.get('migration_id', '') or '')
        if migration_id:
            # The prepare file stays in the inbox and is read again on every poll;
            # remembering the verdict keeps it from being re-judged (and re-sent
            # with different bytes) each time.
            self._save_state({
                'migration_id': migration_id,
                'conversation_id': str(prepare.get('conversation_id', '') or ''),
                'role': 'target',
                'phase': 'rejected',
                'reason': str(reason or 'conversation_conflict'),
                'source_device_id': str(prepare.get('source_device_id', '') or ''),
                'target_device_id': self.transport.device_id,
                'created_at': str(payload.get('created_at', '') or ''),
            })
        return {'record_type': 'MigrationReject', 'reason': reason}

    def _part_pending(self, cloud_path: str) -> bool:
        """True while a staged part has not finished syncing to this device.

        iCloud delivers the small prepare file and the larger parts independently,
        so a part can be missing or still a placeholder when the prepare is read.
        """
        state = str(self.transport.backend.materializer.status(cloud_path) or 'UNKNOWN').upper()
        if state in ICloudFileMaterializer.CURRENT_STATES:
            return False
        if state == 'NOT_DOWNLOADED':
            self.transport.backend.materializer.request_download(cloud_path)
        return True

    def receive_prepare(self, prepare: dict) -> dict:
        if not verify_cloud_payload(prepare) or str(prepare.get('executor_id', '') or '') != self.transport.device_id:
            raise ValueError('Invalid MigrationPrepare.')
        migration_id = str(prepare.get('migration_id', '') or '')
        self._mark_requests_accepted(str(prepare.get('conversation_id', '') or ''), str(prepare.get('source_device_id', '') or ''))
        existing = self.states.get(migration_id)
        if isinstance(existing, dict) and str(existing.get('phase', '') or '') in {'cancelled', 'superseded', 'rejected'}:
            return existing
        if isinstance(existing, dict) and str(existing.get('phase', '') or '') in {'target_ready', 'committed_target'}:
            if str(existing.get('phase')) == 'target_ready':
                self._publish_control(
                    existing['ready_payload'],
                    str(prepare.get('source_device_id', '') or ''),
                    f'{self.transport.device_id}-{migration_id}-MigrationReady.json',
                )
            return existing
        conversation_id = str(prepare.get('conversation_id', '') or '')
        source_device_id = str(prepare.get('source_device_id', '') or '')
        for state in list(self.states.values()):
            if (
                str(state.get('conversation_id', '') or '') != conversation_id
                or str(state.get('migration_id', '') or '') == migration_id
            ):
                continue
            phase = str(state.get('phase', '') or '')
            if (
                phase in {'target_ready', 'waiting_assets'}
                and str(state.get('role', '') or '') == 'target'
                and str(state.get('source_device_id', '') or '') == source_device_id
            ):
                # The source runs one migration per conversation at a time, so a
                # newer prepare from it means it already gave up on the older one
                # (cancelled or rejected). Left in place, that old half-done claim
                # would reject every later attempt as a conflict.
                state['phase'] = 'superseded'
                state['superseded_by'] = migration_id
                self._save_state(state)
                continue
            if phase in {'target_ready', 'committed_target'}:
                return self._publish_reject(prepare, 'conversation_conflict')
        record = prepare.get('canonical_record') if isinstance(prepare.get('canonical_record'), dict) else {}
        if str(record.get('id', '') or '') != conversation_id:
            return self._publish_reject(prepare, 'canonical_id_mismatch')
        if int(record.get('revision', 0) or 0) != int(prepare.get('base_revision', -1) or 0):
            return self._publish_reject(prepare, 'base_revision_mismatch')
        manifest = prepare.get('manifest') if isinstance(prepare.get('manifest'), list) else []
        if self.manifest_hash(manifest) != str(prepare.get('manifest_hash', '') or ''):
            return self._publish_reject(prepare, 'manifest_hash_mismatch')
        incoming = os.path.join(self.local_state_root, 'incoming', migration_id, 'parts')
        local_parts = []
        pending_parts = 0
        for item in manifest:
            if not isinstance(item, dict):
                return self._publish_reject(prepare, 'invalid_manifest_item')
            relative = str(item.get('cloud_path', '') or '')
            try:
                cloud_path = self.transport.backend.path(*Path(relative).parts)
            except Exception:
                return self._publish_reject(prepare, 'invalid_manifest_item')
            if self._part_pending(cloud_path):
                pending_parts += 1
                continue
            local = self.transport.backend.materialize_asset(
                cloud_path,
                incoming,
                expected_hash=str(item.get('sha256', '') or ''),
                timeout=float(item.get('timeout', 0.5) or 0.5),
            )
            # The part is fully synced here, so a wrong hash or size is real damage.
            if not local or os.path.getsize(local) != int(item.get('size', -1) or 0):
                return self._publish_reject(prepare, 'asset_verification_failed')
            local_parts.append(dict(item, local_path=local))
        if pending_parts:
            now = time.time()
            waiting = existing if isinstance(existing, dict) and str(existing.get('phase', '') or '') == 'waiting_assets' else None
            first_seen = float((waiting or {}).get('first_seen_epoch', 0) or 0) or now
            if now - first_seen >= self.ASSET_WAIT_SECONDS:
                return self._publish_reject(prepare, 'asset_timeout')
            if waiting is None:
                self._save_state({
                    'migration_id': migration_id,
                    'conversation_id': conversation_id,
                    'role': 'target',
                    'phase': 'waiting_assets',
                    'source_device_id': source_device_id,
                    'target_device_id': self.transport.device_id,
                    'first_seen_epoch': now,
                    'created_at': datetime.datetime.now().isoformat(timespec='milliseconds'),
                })
            # No verdict yet: the prepare stays in the inbox and is checked again
            # on the next poll, until every part is here or the wait runs out.
            return {
                'record_type': 'MigrationPrepare',
                'migration_id': migration_id,
                'phase': 'waiting_assets',
                'pending_parts': pending_parts,
            }
        created_at = datetime.datetime.now().isoformat(timespec='milliseconds')
        ready_payload = seal_cloud_payload({
            'schema_version': ICLOUD_PROTOCOL_VERSION,
            'record_type': 'MigrationReady',
            'migration_id': migration_id,
            'conversation_id': conversation_id,
            'source_device_id': self.transport.device_id,
            'executor_id': str(prepare.get('source_device_id', '') or ''),
            'target_device_id': self.transport.device_id,
            'route_epoch': int(prepare.get('route_epoch', 0) or 0),
            'base_revision': int(prepare.get('base_revision', 0) or 0),
            'manifest_hash': str(prepare.get('manifest_hash', '') or ''),
            'verified_part_count': len(local_parts),
            'created_at': created_at,
        })
        state = self._save_state({
            'migration_id': migration_id,
            'conversation_id': conversation_id,
            'role': 'target',
            'phase': 'target_ready',
            'source_device_id': str(prepare.get('source_device_id', '') or ''),
            'target_device_id': self.transport.device_id,
            'route_epoch': int(prepare.get('route_epoch', 0) or 0),
            'base_revision': int(prepare.get('base_revision', 0) or 0),
            'manifest_hash': str(prepare.get('manifest_hash', '') or ''),
            'prepare_payload': prepare,
            'ready_payload': ready_payload,
            'local_parts': local_parts,
            'created_at': created_at,
        })
        self._publish_control(
            ready_payload,
            str(prepare.get('source_device_id', '') or ''),
            f'{self.transport.device_id}-{migration_id}-MigrationReady.json',
        )
        return state

    def receive_ready(self, ready: dict) -> dict:
        if not verify_cloud_payload(ready) or str(ready.get('executor_id', '') or '') != self.transport.device_id:
            raise ValueError('Invalid MigrationReady.')
        migration_id = str(ready.get('migration_id', '') or '')
        state = self.states.get(migration_id)
        if not isinstance(state, dict) or str(state.get('role', '') or '') != 'source':
            raise RuntimeError('Unknown source migration.')
        if str(ready.get('source_device_id', '') or '') != str(state.get('target_device_id', '') or ''):
            raise RuntimeError('conversation_conflict: ready came from a different target.')
        if str(ready.get('manifest_hash', '') or '') != str(state.get('manifest_hash', '') or ''):
            raise RuntimeError('MigrationReady manifest does not match prepare.')
        if str(state.get('phase', '') or '') == 'committed_source':
            return state
        if str(state.get('phase', '') or '') in {'cancelled', 'rejected'}:
            return state
        state['phase'] = 'ready'
        state['ready_payload'] = ready
        self._save_state(state)
        return self.commit(migration_id)

    def commit(self, migration_id: str) -> dict:
        state = self.states.get(str(migration_id or ''))
        if not isinstance(state, dict) or str(state.get('role', '') or '') != 'source':
            raise RuntimeError('Unknown source migration.')
        if str(state.get('phase', '') or '') == 'committed_source':
            self._republish_commit(state)
            return state
        if str(state.get('phase', '') or '') not in {'ready', 'committing'}:
            raise RuntimeError('Migration cannot commit before target ready.')
        self._assert_eligible(str(state.get('conversation_id', '') or ''), str(state.get('conversation_path', '') or ''))
        if str(state.get('phase', '') or '') == 'ready':
            record = load_conversation_record(str(state.get('conversation_path', '') or ''), include_retrieval=False)
            if not isinstance(record, dict):
                raise ICloudUserError('migration_source_missing')
            if int(record.get('revision', 0) or 0) != int(state.get('base_revision', 0) or 0):
                raise ICloudUserError('source_changed_during_move')
            identity = record.get('identity') if isinstance(record.get('identity'), dict) else local_conversation_identity()
            old_identity = copy.deepcopy(identity)
            identity['owner_device_id'] = str(state.get('target_device_id', '') or '')
            identity['owner_user_id'] = str(state.get('target_owner_user_id', '') or identity.get('owner_user_id', '') or '')
            identity['user_id'] = str(identity.get('owner_user_id', '') or identity.get('user_id', '') or '')
            record['identity'] = identity
            record['route_epoch'] = int(state.get('route_epoch', 0) or 0) + 1
            marker = {
                'migration_id': str(state.get('migration_id', '') or ''),
                'phase': 'committed',
                'source_device_id': self.transport.device_id,
                'target_device_id': str(state.get('target_device_id', '') or ''),
            }
            record['migration'] = marker
            record.setdefault('extensions', {})['migration'] = dict(marker)
            record['_migration_internal_write'] = True
            record = write_conversation_record(str(state.get('conversation_path', '') or ''), record)
            if not flush_async_file_writes(timeout=5.0):
                raise ICloudUserError('save_timeout')
            commit_payload = seal_cloud_payload({
                'schema_version': ICLOUD_PROTOCOL_VERSION,
                'record_type': 'MigrationCommit',
                'migration_id': str(state.get('migration_id', '') or ''),
                'conversation_id': str(state.get('conversation_id', '') or ''),
                'source_device_id': self.transport.device_id,
                'executor_id': str(state.get('target_device_id', '') or ''),
                'route_epoch': int(record.get('route_epoch', 0) or 0),
                'base_revision': int(state.get('base_revision', 0) or 0),
                'revision': int(record.get('revision', 0) or 0),
                'manifest_hash': str(state.get('manifest_hash', '') or ''),
                'canonical_record': cloud_canonical_record(record),
                'created_at': datetime.datetime.now().isoformat(timespec='milliseconds'),
            })
            state.update({
                'phase': 'committing',
                'old_identity': old_identity,
                'commit_record': record,
                'commit_payload': commit_payload,
                'committed_route_epoch': int(record.get('route_epoch', 0) or 0),
            })
            self._save_state(state)
        self._republish_commit(state)
        record = state.get('commit_record') if isinstance(state.get('commit_record'), dict) else {}
        old_identity = state.get('old_identity') if isinstance(state.get('old_identity'), dict) else {}
        pointer = seal_cloud_payload({
            'schema_version': ICLOUD_PROTOCOL_VERSION,
            'record_type': 'ConversationPointer',
            'conversation_id': str(state.get('conversation_id', '') or ''),
            'migration_id': str(state.get('migration_id', '') or ''),
            'retired': True,
            'route_epoch': int(state.get('committed_route_epoch', 0) or 0),
            'owner_device_id': str(state.get('target_device_id', '') or ''),
            'created_at': str((state.get('commit_payload') or {}).get('created_at', '') or ''),
        })
        old_directory = self.transport.backend.path(
            'canonical',
            _cloud_file_component(old_identity.get('owner_user_id', '') or old_identity.get('user_id', ''), 'owner'),
            _cloud_file_component(old_identity.get('owner_device_id', '') or self.transport.device_id, 'device'),
            _cloud_file_component(old_identity.get('origin_user_id', '') or old_identity.get('user_id', ''), 'origin'),
            _cloud_file_component(state.get('conversation_id', ''), 'conversation'),
        )
        self.transport.backend.publish_json(
            old_directory,
            f'pointer-{state.get("committed_route_epoch", 0)}-{state.get("migration_id", "")}.json',
            pointer,
        )
        state['phase'] = 'committed_source'
        source_path = str(state.get('conversation_path', '') or '')
        retired_dir = os.path.join(self.local_state_root, 'retired')
        os.makedirs(retired_dir, exist_ok=True)
        retired_path = os.path.join(retired_dir, os.path.basename(source_path))
        if source_path and os.path.exists(source_path) and not os.path.exists(retired_path):
            os.replace(source_path, retired_path)
        state['retired_snapshot_path'] = retired_path
        resolver = get_conversation_path_resolver()
        if resolver is not None:
            resolver.mark_deleted(str(state.get('conversation_id', '') or ''), source_path)
        return self._save_state(state)

    def _republish_commit(self, state: dict):
        record = state.get('commit_record') if isinstance(state.get('commit_record'), dict) else {}
        payload = state.get('commit_payload') if isinstance(state.get('commit_payload'), dict) else {}
        if not record or not payload:
            raise ICloudUserError('move_state_damaged')
        self.transport.publish_revision(record)
        self.transport.publish_event(record, {
            'schema_version': ICLOUD_PROTOCOL_VERSION,
            'event_id': str(state.get('migration_id', '') or ''),
            'event_type': 'migration_commit',
            'producer_id': self.transport.device_id,
            'producer_seq': str(state.get('migration_id', '') or ''),
            'conversation_id': str(state.get('conversation_id', '') or ''),
            'route_epoch': int(state.get('committed_route_epoch', 0) or 0),
            'created_at': str(payload.get('created_at', '') or ''),
        })
        self._publish_control(
            payload,
            str(state.get('target_device_id', '') or ''),
            f'{self.transport.device_id}-{state.get("migration_id", "")}-MigrationCommit.json',
        )

    def receive_commit(self, commit: dict) -> dict:
        if not verify_cloud_payload(commit) or str(commit.get('executor_id', '') or '') != self.transport.device_id:
            raise ValueError('Invalid MigrationCommit.')
        migration_id = str(commit.get('migration_id', '') or '')
        state = self.states.get(migration_id)
        if not isinstance(state, dict) or str(state.get('role', '') or '') != 'target':
            raise RuntimeError('Commit arrived without a verified prepare.')
        if str(state.get('phase', '') or '') == 'committed_target':
            return state
        if str(state.get('phase', '') or '') != 'target_ready':
            raise RuntimeError('Target is not ready for commit.')
        if str(commit.get('manifest_hash', '') or '') != str(state.get('manifest_hash', '') or ''):
            raise RuntimeError('Commit manifest changed after ready.')
        expected_epoch = int(state.get('route_epoch', 0) or 0) + 1
        if int(commit.get('route_epoch', 0) or 0) != expected_epoch:
            raise RuntimeError('Commit route_epoch is not the next generation.')
        record = commit.get('canonical_record') if isinstance(commit.get('canonical_record'), dict) else {}
        identity = record.get('identity') if isinstance(record.get('identity'), dict) else {}
        if str(identity.get('owner_device_id', '') or '') != self.transport.device_id:
            raise RuntimeError('Commit does not assign ownership to this target.')
        os.makedirs(self.local_conversations_dir, exist_ok=True)
        title = sanitize_conversation_title(record.get('title', '') or _tr('Migrated conversation'))
        path = os.path.join(
            self.local_conversations_dir,
            f'{state.get("conversation_id", "")}_{sanitize_conversation_filename(title)}.json',
        )
        known = resolve_conversation_path(str(state.get('conversation_id', '') or ''))
        known = os.path.abspath(known) if known and os.path.isabs(known) else ''
        conversations_root = os.path.abspath(self.local_conversations_dir)
        if known and os.path.isfile(known) and os.path.commonpath([conversations_root, known]) == conversations_root:
            # This device already keeps a (read-only) copy of it: take over that
            # file instead of leaving it behind as a stale duplicate.
            path = known
        clean_record = copy.deepcopy(record)
        clean_record.pop('content_hash', None)
        _write_json_atomic(path, clean_record, indent=None)
        with _CONVERSATION_RECORD_CACHE_LOCK:
            _CONVERSATION_RECORD_CACHE.pop(path, None)
            _CONVERSATION_RECORD_CACHE_META.pop(path, None)
            _CONVERSATION_RECORD_GENERATION.pop(path, None)
        attachment_root = os.path.join(self.local_conversations_dir, f'{state.get("conversation_id", "")}_attachments')
        for item in state.get('local_parts') or []:
            if not isinstance(item, dict):
                continue
            kind = str(item.get('kind', '') or 'transfer_part')
            logical = str(item.get('logical_path', '') or item.get('asset_id', '') or 'part')
            safe_parts = [_cloud_file_component(part, 'part') for part in Path(logical).parts]
            if kind == 'attachment':
                destination = os.path.join(attachment_root, *safe_parts)
            else:
                destination = os.path.join(attachment_root, 'migration_parts', _cloud_file_component(kind, 'part'), *safe_parts)
            os.makedirs(os.path.dirname(destination), exist_ok=True)
            if not os.path.exists(destination):
                shutil.copy2(str(item.get('local_path', '') or ''), destination)
            if hashlib.sha256(Path(destination).read_bytes()).hexdigest() != str(item.get('sha256', '') or ''):
                raise RuntimeError('Restored migration asset hash mismatch.')
        resolver = get_conversation_path_resolver()
        if resolver is not None:
            resolver.register(str(state.get('conversation_id', '') or ''), path, clean_record)
        state.update({
            'phase': 'committed_target',
            'conversation_path': path,
            'committed_route_epoch': expected_epoch,
            'commit_payload': commit,
        })
        return self._save_state(state)

    def receive_reject(self, rejection: dict) -> dict:
        if not verify_cloud_payload(rejection) or str(rejection.get('executor_id', '') or '') != self.transport.device_id:
            raise ValueError('Invalid MigrationReject.')
        state = self.states.get(str(rejection.get('migration_id', '') or ''))
        if not isinstance(state, dict) or str(state.get('role', '') or '') != 'source':
            raise RuntimeError('Unknown rejected migration.')
        if str(state.get('phase', '') or '') in {'committing', 'committed_source'}:
            return state
        state['phase'] = 'rejected'
        state['reason'] = str(rejection.get('reason', '') or 'rejected')
        return self._save_state(state)

    def receive_cancel(self, cancellation: dict) -> dict:
        if not verify_cloud_payload(cancellation) or str(cancellation.get('executor_id', '') or '') != self.transport.device_id:
            raise ValueError('Invalid MigrationCancel.')
        migration_id = str(cancellation.get('migration_id', '') or '')
        state = self.states.get(migration_id, {
            'migration_id': migration_id,
            'conversation_id': str(cancellation.get('conversation_id', '') or ''),
            'role': 'target',
            'source_device_id': str(cancellation.get('source_device_id', '') or ''),
            'target_device_id': self.transport.device_id,
            'created_at': str(cancellation.get('created_at', '') or ''),
        })
        if str(state.get('phase', '') or '') == 'committed_target':
            return state
        state['phase'] = 'cancelled'
        return self._save_state(state)

    def handle_control(self, payload: dict) -> dict:
        record_type = str((payload or {}).get('record_type', '') or '')
        if record_type == 'MigrationPrepare':
            return self.receive_prepare(payload)
        if record_type == 'MigrationReady':
            return self.receive_ready(payload)
        if record_type == 'MigrationCommit':
            return self.receive_commit(payload)
        if record_type == 'MigrationReject':
            return self.receive_reject(payload)
        if record_type == 'MigrationCancel':
            return self.receive_cancel(payload)
        if record_type == 'MigrationRequest':
            return self.receive_migration_request(payload)
        if record_type == 'MigrationRequestDeclined':
            return self.receive_migration_request_declined(payload)
        raise ValueError('Unsupported migration control record.')

    # ---- asking the owner to move a conversation (only the owner may migrate) ----
    def request_migration(self, record: dict, target: dict, *, owner_display_name: str = '') -> dict:
        """Ask the device that owns `record` to migrate it to `target` (usually
        this device). The owner starts the normal prepare/ready/commit as soon as
        the conversation is idle there."""
        record = record if isinstance(record, dict) else {}
        target = target if isinstance(target, dict) else {}
        identity = record.get('identity') if isinstance(record.get('identity'), dict) else {}
        owner = _cloud_file_component(identity.get('owner_device_id', '') or '', 'device')
        if not identity.get('owner_device_id') or owner == self.transport.device_id:
            raise ICloudUserValueError('already_owned_here')
        target_device = _cloud_file_component(target.get('device_id', '') or self.transport.device_id, 'device')
        if target_device == owner:
            raise ICloudUserValueError('already_there')
        request_id = new_broccoli_uuid('migration-request-')
        now = time.time()
        created_at = datetime.datetime.now().isoformat(timespec='milliseconds')
        payload = seal_cloud_payload({
            'schema_version': ICLOUD_PROTOCOL_VERSION,
            'record_type': 'MigrationRequest',
            'migration_request_id': request_id,
            'conversation_id': str(record.get('id', '') or ''),
            'source_device_id': self.transport.device_id,
            'executor_id': owner,
            'target_device_id': target_device,
            'target_display_name': str(target.get('display_name', '') or target_device),
            'target_owner_user_id': str(target.get('owner_user_id', '') or identity.get('owner_user_id', '') or BROCCOLI_LOCAL_USER_ID),
            'route_epoch': int(record.get('route_epoch', 0) or 0),
            'created_at': created_at,
            'expires_at_epoch': round(now + self.REQUEST_TIMEOUT_SECONDS, 3),
        })
        try:
            self._publish_control(payload, owner, f'{self.transport.device_id}-{request_id}-MigrationRequest.json')
        except Exception as exc:
            raise ICloudUserError('cloud_write_failed', detail=str(exc)) from exc
        return self._save_request_state({
            'migration_request_id': request_id,
            'conversation_id': str(record.get('id', '') or ''),
            'role': 'requester',
            'phase': 'requested',
            'owner_device_id': owner,
            'owner_display_name': str(owner_display_name or owner),
            'target_device_id': target_device,
            'requested_epoch': now,
            'created_at': created_at,
            'request_payload': payload,
        })

    def _decline_request(self, request: dict, reason: str, reason_params: dict | None = None) -> dict:
        request_id = str(request.get('migration_request_id', '') or '')
        decline = seal_cloud_payload({
            'schema_version': ICLOUD_PROTOCOL_VERSION,
            'record_type': 'MigrationRequestDeclined',
            'migration_request_id': request_id,
            'conversation_id': str(request.get('conversation_id', '') or ''),
            'source_device_id': self.transport.device_id,
            'executor_id': str(request.get('source_device_id', '') or ''),
            # A code (+ params): the requester words it in its own language.
            'reason': str(reason or 'declined'),
            'reason_params': _task_store_json_safe(dict(reason_params or {})),
            'created_at': datetime.datetime.now().isoformat(timespec='milliseconds'),
        })
        self._publish_control(
            decline,
            str(request.get('source_device_id', '') or ''),
            f'{self.transport.device_id}-{request_id}-MigrationRequestDeclined.json',
        )
        return self._save_request_state({
            'migration_request_id': request_id,
            'conversation_id': str(request.get('conversation_id', '') or ''),
            'role': 'owner',
            'phase': 'declined',
            'reason': str(reason or 'declined'),
            'requested_by': str(request.get('source_device_id', '') or ''),
            'created_at': str(decline.get('created_at', '') or ''),
        })

    def receive_migration_request(self, request: dict) -> dict:
        if not verify_cloud_payload(request) or str(request.get('executor_id', '') or '') != self.transport.device_id:
            raise ValueError('Invalid MigrationRequest.')
        request_id = str(request.get('migration_request_id', '') or '')
        existing = self.request_states.get(request_id)
        if isinstance(existing, dict) and str(existing.get('phase', '') or '') in {'handled', 'declined'}:
            return existing
        try:
            expires_at = float(request.get('expires_at_epoch', 0) or 0)
        except (TypeError, ValueError):
            expires_at = 0.0
        if expires_at and time.time() > expires_at:
            return self._decline_request(request, 'expired')
        conversation_id = str(request.get('conversation_id', '') or '')
        path = resolve_conversation_path(conversation_id) if conversation_id else ''
        record = load_conversation_record(path, include_retrieval=False) if path else None
        if not isinstance(record, dict) or str(record.get('id', '') or '') != conversation_id:
            return self._decline_request(request, 'not_found')
        identity = record.get('identity') if isinstance(record.get('identity'), dict) else {}
        if _cloud_file_component(identity.get('owner_device_id', '') or self.transport.device_id, 'device') != self.transport.device_id:
            return self._decline_request(request, 'not_owner')
        target_device = _cloud_file_component(request.get('target_device_id', '') or '', 'device')
        if not request.get('target_device_id') or target_device == self.transport.device_id:
            return self._decline_request(request, 'invalid_target')
        target = {
            'device_id': target_device,
            'owner_user_id': str(request.get('target_owner_user_id', '') or ''),
            'display_name': str(request.get('target_display_name', '') or target_device),
            'selectable': True,
        }
        queue_items = list(self._eligibility(conversation_id, path).get('queue_items') or [])
        try:
            state = self.prepare(path, target, queue_items=queue_items)
        except ICloudUserError as exc:
            if exc.code in {'migration_busy', 'conversation_conflict'}:
                # Busy here (a run, an approval, an unsaved editor) or another
                # migration is out: no verdict yet. The request file stays in the
                # inbox and is checked again on the next poll, until it expires.
                return {
                    'record_type': 'MigrationRequest',
                    'migration_request_id': request_id,
                    'phase': 'request_waiting',
                    'reason': exc.code,
                }
            return self._decline_request(request, exc.code, exc.params)
        except Exception as exc:
            return self._decline_request(request, str(exc) or exc.__class__.__name__)
        return self._save_request_state({
            'migration_request_id': request_id,
            'conversation_id': conversation_id,
            'role': 'owner',
            'phase': 'handled',
            'migration_id': str(state.get('migration_id', '') or ''),
            'requested_by': str(request.get('source_device_id', '') or ''),
            'created_at': datetime.datetime.now().isoformat(timespec='milliseconds'),
        })

    def receive_migration_request_declined(self, decline: dict) -> dict:
        if not verify_cloud_payload(decline) or str(decline.get('executor_id', '') or '') != self.transport.device_id:
            raise ValueError('Invalid MigrationRequestDeclined.')
        request_id = str(decline.get('migration_request_id', '') or '')
        state = self.request_states.get(request_id)
        if not isinstance(state, dict) or str(state.get('role', '') or '') != 'requester':
            raise RuntimeError('Unknown migration request.')
        if str(state.get('phase', '') or '') != 'requested':
            return state
        state['phase'] = 'declined'
        state['reason'] = str(decline.get('reason', '') or 'declined')
        state['reason_params'] = decline.get('reason_params') if isinstance(decline.get('reason_params'), dict) else {}
        return self._save_request_state(state)

    def _mark_requests_accepted(self, conversation_id: str, owner_device_id: str):
        # The owner started the migration we asked for; stop the request clock.
        for state in list(self.request_states.values()):
            if (
                str(state.get('role', '') or '') == 'requester'
                and str(state.get('phase', '') or '') == 'requested'
                and str(state.get('conversation_id', '') or '') == str(conversation_id or '')
                and str(state.get('owner_device_id', '') or '') == str(owner_device_id or '')
            ):
                state['phase'] = 'accepted'
                self._save_request_state(state)

    def cancel(self, migration_id: str) -> bool:
        state = self.states.get(str(migration_id or ''))
        if not isinstance(state, dict) or str(state.get('role', '') or '') != 'source':
            return False
        if str(state.get('phase', '') or '') not in self.PRECOMMIT_PHASES:
            return False
        state['phase'] = 'cancelled'
        self._save_state(state)
        cancellation = seal_cloud_payload({
            'schema_version': ICLOUD_PROTOCOL_VERSION,
            'record_type': 'MigrationCancel',
            'migration_id': str(state.get('migration_id', '') or ''),
            'conversation_id': str(state.get('conversation_id', '') or ''),
            'source_device_id': self.transport.device_id,
            'executor_id': str(state.get('target_device_id', '') or ''),
            'created_at': datetime.datetime.now().isoformat(timespec='milliseconds'),
        })
        self._publish_control(
            cancellation,
            str(state.get('target_device_id', '') or ''),
            f'{self.transport.device_id}-{state.get("migration_id", "")}-MigrationCancel.json',
        )
        path = str(state.get('conversation_path', '') or '')
        record = load_conversation_record(path, include_retrieval=False)
        if isinstance(record, dict):
            migration = (record.get('extensions') or {}).get('migration')
            if isinstance(migration, dict) and str(migration.get('migration_id', '') or '') == str(migration_id or ''):
                record.setdefault('extensions', {}).pop('migration', None)
                # The loaded top-level copy would put the marker back on save.
                record.pop('migration', None)
                record['_migration_internal_write'] = True
                write_conversation_record(path, record)
                flush_async_file_writes(timeout=5.0)
        return True

    def resume(self, migration_id: str) -> dict | None:
        state = self.states.get(str(migration_id or ''))
        if not isinstance(state, dict):
            return None
        phase = str(state.get('phase', '') or '')
        if str(state.get('role', '') or '') == 'source':
            if phase == 'prepare_sent':
                self._publish_control(
                    state['prepare_payload'],
                    str(state.get('target_device_id', '') or ''),
                    f'{self.transport.device_id}-{state.get("migration_id", "")}-MigrationPrepare.json',
                )
            elif phase in {'ready', 'committing', 'committed_source'}:
                return self.commit(str(state.get('migration_id', '') or ''))
        elif phase == 'target_ready':
            self._publish_control(
                state['ready_payload'],
                str(state.get('source_device_id', '') or ''),
                f'{self.transport.device_id}-{state.get("migration_id", "")}-MigrationReady.json',
            )
        return self.states.get(str(migration_id or ''))

    def resume_all(self) -> list[dict]:
        resumed = []
        for migration_id in sorted(self.states):
            state = self.resume(migration_id)
            if isinstance(state, dict):
                resumed.append(state)
        return resumed

    @staticmethod
    def _state_epoch(state: dict, key: str) -> float:
        try:
            value = float(state.get(key, 0) or 0)
        except (TypeError, ValueError):
            value = 0.0
        if value:
            return value
        try:
            # States written before the epoch field: created_at is local wall time.
            return datetime.datetime.fromisoformat(str(state.get('created_at', '') or '')).timestamp()
        except Exception:
            return 0.0

    def expire_stale(self, now: float | None = None) -> list[dict]:
        """Cancel source migrations that got no ready/reject in time.

        The conversation is frozen while a prepare is out; without this, an
        offline or never-answering target kept it read-only indefinitely.
        """
        now = time.time() if now is None else float(now)
        expired = []
        for migration_id, state in list(self.states.items()):
            if str(state.get('role', '') or '') != 'source' or str(state.get('phase', '') or '') != 'prepare_sent':
                continue
            sent_at = self._state_epoch(state, 'prepare_sent_epoch')
            if not sent_at or now - sent_at < self.PREPARE_TIMEOUT_SECONDS:
                continue
            if self.cancel(migration_id):
                cancelled = self.states[migration_id]
                cancelled['reason'] = 'timeout'
                expired.append(self._save_state(cancelled))
        for state in list(self.request_states.values()):
            if str(state.get('role', '') or '') != 'requester' or str(state.get('phase', '') or '') != 'requested':
                continue
            requested_at = self._state_epoch(state, 'requested_epoch')
            if requested_at and now - requested_at >= self.REQUEST_TIMEOUT_SECONDS:
                # The owner refuses it after the same deadline (expires_at_epoch).
                state['phase'] = 'expired'
                expired.append(self._save_request_state(state))
        return expired


def remote_continuation_gate(request: dict, migration_manager) -> dict:
    """Hold a follow-up for a conversation that is still migrating to this device.

    'Move to' with a typed question sends the follow-up right after the source
    commits, and iCloud may deliver it before the commit itself. Until the commit
    lands it waits in the inbox (no verdict) instead of being refused as "not the
    owner". Once expired it is let through, so the expiry check refuses it.
    """
    request = request if isinstance(request, dict) else {}
    if str(request.get('task_kind', '') or '') != 'continue_conversation':
        return {'allow': True}
    if not isinstance(migration_manager, ConversationMigrationManager):
        return {'allow': True}
    try:
        expires_at = float(request.get('expires_at_epoch', 0) or 0)
    except (TypeError, ValueError):
        expires_at = 0.0
    if expires_at and time.time() > expires_at:
        return {'allow': True}
    conversation_id = str(request.get('conversation_id', '') or '')
    for state in migration_manager.states.values():
        if (
            str(state.get('conversation_id', '') or '') == conversation_id
            and str(state.get('role', '') or '') == 'target'
            and str(state.get('phase', '') or '') in {'waiting_assets', 'target_ready'}
        ):
            return {
                'allow': False,
                'status': 'waiting_for_ownership',
                'task_id': str(request.get('task_id', '') or ''),
                'attempt_id': str(request.get('attempt_id', '') or ''),
            }
    return {'allow': True}


def fail_closed_remote_decision(value) -> str:
    """Remote decisions are an exact enum. Unknown text is always reject/hold."""
    decision = str(value or '').strip().lower()
    return decision if decision in {'approve', 'reject', 'retry', 'cancel'} else 'reject'


def terminal_pause_kind(session) -> str:
    """Distinguish a normal question pause from a privileged approval pause."""
    if session is None:
        return ''
    if getattr(session, '_pending_perm', None) is not None or getattr(session, '_pending_approval', None) is not None:
        return 'approval'
    reason = str(getattr(session, 'block_reason', '') or getattr(session, '_block_reason', '') or '').lower()
    if any(token in reason for token in ('approval', 'permission', 'authorize')):
        return 'approval'
    if getattr(session, '_pending_question', None) is not None or 'question' in reason or 'input' in reason:
        return 'question'
    return ''


class RemoteTaskLifecycleManager:
    """M5 immutable lifecycle controls; executor remains the only scheduler."""

    TERMINAL_STATES = {'completed', 'finished', 'failed', 'cancelled', 'rejected', 'needs_reconciliation', 'stopped'}
    INCIDENT_TYPES = {
        'migration_failed', 'executor_offline', 'sync_placeholder', 'capability_missing',
        'conversation_conflict', 'approval_required', 'approval_rejected', 'approval_timeout',
        'execution_failed', 'cancel_requested', 'needs_reconciliation', 'result_sync_failed',
        'notes_failed',
    }
    LOCAL_CONTROL_KEYS = {
        'handled', 'pending_before_task', 'result', 'duplicate', 'new_attempt_id',
    }

    def __init__(self,
                 transport: ICloudTaskTransport,
                 *,
                 local_state_root: str | None = None,
                 cancel_executor_callback=None,
                 supplement_callback=None,
                 queue_callback=None):
        self.transport = transport
        self.local_state_root = os.path.abspath(os.path.expanduser(str(
            local_state_root or os.path.join(BROCCOLI_APP_DATA_DIR, 'RemoteLifecycle')
        )))
        self.cancel_executor_callback = cancel_executor_callback
        self.supplement_callback = supplement_callback
        self.queue_callback = queue_callback
        self._lock = threading.RLock()

    def _store(self) -> ShadowTaskStore | None:
        return self.transport._store()

    def _control_path(self, control_id: str) -> str:
        return os.path.join(self.local_state_root, 'controls', _cloud_file_component(control_id, 'control') + '.json')

    def _load_control(self, control_id: str) -> dict | None:
        try:
            state = json.loads(Path(self._control_path(control_id)).read_text(encoding='utf-8'))
        except Exception:
            return None
        if not isinstance(state, dict):
            return None
        if isinstance(state.get('cloud_payload'), dict):
            return {**copy.deepcopy(state['cloud_payload']), **copy.deepcopy(state.get('local') or {})}
        return state

    def _cloud_control(self, control_id: str) -> dict | None:
        try:
            state = json.loads(Path(self._control_path(control_id)).read_text(encoding='utf-8'))
        except Exception:
            return None
        if isinstance(state, dict) and isinstance(state.get('cloud_payload'), dict):
            return copy.deepcopy(state['cloud_payload'])
        return state if verify_cloud_payload(state) else None

    def _save_control(self, payload: dict) -> dict:
        os.makedirs(os.path.join(self.local_state_root, 'controls'), exist_ok=True)
        control_id = str(payload.get('control_id', '') or '')
        existing_cloud = self._cloud_control(control_id)
        local = {key: copy.deepcopy(payload.get(key)) for key in self.LOCAL_CONTROL_KEYS if key in payload}
        if verify_cloud_payload(payload):
            cloud = {key: copy.deepcopy(value) for key, value in payload.items() if key not in self.LOCAL_CONTROL_KEYS}
        elif isinstance(existing_cloud, dict):
            cloud = existing_cloud
        else:
            candidate = {key: copy.deepcopy(value) for key, value in payload.items() if key not in self.LOCAL_CONTROL_KEYS and key != 'content_hash'}
            cloud = seal_cloud_payload(candidate)
        state = {'cloud_payload': cloud, 'local': local}
        _write_json_atomic(self._control_path(control_id), state, indent=2)
        return {**copy.deepcopy(cloud), **local}

    @staticmethod
    def _control_id(event_type: str, task_id: str, attempt_id: str, suffix: str = '') -> str:
        seed = ':'.join((str(event_type), str(task_id), str(attempt_id), str(suffix)))
        return 'control-' + str(uuid.uuid5(uuid.NAMESPACE_URL, 'broccoli-remote-control:' + seed))

    @staticmethod
    def _conversation_identity(conversation: dict) -> tuple[str, str, str, str]:
        identity = conversation.get('identity') if isinstance(conversation.get('identity'), dict) else {}
        return (
            _cloud_file_component(identity.get('owner_user_id', '') or identity.get('user_id', ''), 'owner'),
            _cloud_file_component(identity.get('owner_device_id', ''), 'device'),
            _cloud_file_component(identity.get('origin_user_id', '') or identity.get('user_id', ''), 'origin'),
            _cloud_file_component(conversation.get('id', '') or conversation.get('conversation_id', ''), 'conversation'),
        )

    def _publish_dual(self,
                      event_type: str,
                      conversation: dict,
                      task_id: str,
                      attempt_id: str,
                      executor_id: str,
                      *,
                      suffix: str = '',
                      fields: dict | None = None) -> dict:
        control_id = self._control_id(event_type, task_id, attempt_id, suffix)
        payload = self._cloud_control(control_id)
        if not isinstance(payload, dict):
            identity = conversation.get('identity') if isinstance(conversation.get('identity'), dict) else {}
            payload = seal_cloud_payload({
                'schema_version': ICLOUD_PROTOCOL_VERSION,
                'record_type': 'TaskControl',
                'control_id': control_id,
                'event_id': control_id,
                'event_type': str(event_type or ''),
                'task_id': str(task_id or ''),
                'attempt_id': str(attempt_id or ''),
                'conversation_id': str(conversation.get('id', '') or conversation.get('conversation_id', '') or ''),
                'source_device_id': self.transport.device_id,
                'executor_id': str(executor_id or ''),
                'producer_id': self.transport.device_id,
                'producer_seq': control_id,
                'route_epoch': int(conversation.get('route_epoch', 0) or 0),
                'owner_user_id': str(identity.get('owner_user_id', '') or identity.get('user_id', '') or BROCCOLI_LOCAL_USER_ID),
                'owner_device_id': str(identity.get('owner_device_id', '') or executor_id or ''),
                'origin_user_id': str(identity.get('origin_user_id', '') or identity.get('user_id', '') or BROCCOLI_LOCAL_USER_ID),
                'created_at': datetime.datetime.now().isoformat(timespec='milliseconds'),
                **_task_store_json_safe(dict(fields or {})),
            })
            self._save_control(payload)
            self._save_control(dict(payload, handled=False))
        owner, device, origin, conversation_id = self._conversation_identity(conversation)
        filename = '{}-{}-{}.json'.format(
            self.transport.device_id,
            _cloud_file_component(control_id, 'control'),
            _cloud_file_component(event_type, 'event'),
        )
        self.transport.backend.publish_json(
            self.transport.backend.path('canonical', owner, device, origin, conversation_id, 'events'),
            filename,
            payload,
        )
        self.transport.backend.publish_json(
            self.transport.backend.path('control', 'inbox', _cloud_file_component(executor_id, 'device')),
            filename,
            payload,
        )
        return payload

    def request_cancel(self, conversation: dict, task_id: str, attempt_id: str, executor_id: str) -> dict:
        store = self._store()
        if store is not None:
            store.update_attempt_state(attempt_id, 'cancel_requested', {'cancel_state': 'requested'})
        payload = self._publish_dual(
            'cancel_requested', conversation, task_id, attempt_id, executor_id,
            fields={'cancel_state': 'requested'},
        )
        return {
            'status': 'cancel_requested',
            'label': icloud_message('cancel_requested_waiting', device=executor_id),
            'payload': payload,
        }

    def _event_conversation(self, payload: dict) -> dict:
        return {
            'id': str(payload.get('conversation_id', '') or ''),
            'route_epoch': int(payload.get('route_epoch', 0) or 0),
            'identity': {
                'owner_user_id': str(payload.get('owner_user_id', '') or BROCCOLI_LOCAL_USER_ID),
                'owner_device_id': str(payload.get('owner_device_id', '') or self.transport.device_id),
                'origin_user_id': str(payload.get('origin_user_id', '') or payload.get('user_id', '') or BROCCOLI_LOCAL_USER_ID),
            },
        }

    def _publish_terminal(self, payload: dict, state: str, **fields) -> str:
        conversation = self._event_conversation(payload)
        return self.transport.publish_event(conversation, {
            'schema_version': ICLOUD_PROTOCOL_VERSION,
            'event_type': 'attempt_terminal',
            'task_id': str(payload.get('task_id', '') or ''),
            'attempt_id': str(payload.get('attempt_id', '') or ''),
            'state': str(state or ''),
            'producer_seq': 'terminal-' + str(payload.get('control_id', '') or payload.get('attempt_id', '') or ''),
            **_task_store_json_safe(fields),
        })

    def handle_cancel(self, payload: dict) -> dict:
        control_id = str(payload.get('control_id', '') or '')
        saved = self._load_control(control_id)
        if isinstance(saved, dict) and bool(saved.get('handled', False)):
            return dict(saved, duplicate=True)
        store = self._store()
        attempt = store.attempt_record(str(payload.get('attempt_id', '') or '')) if store is not None else None
        if not isinstance(attempt, dict):
            marker = dict(payload, handled=False, pending_before_task=True, result='cancel_pending')
            self._save_control(marker)
            return marker
        current = str(attempt.get('state', '') or '')
        if current in self.TERMINAL_STATES:
            result = 'completed_cancel_missed' if current in {'completed', 'finished'} else current
            marker = dict(payload, handled=True, result=result)
            self._save_control(marker)
            return marker
        checkpoint = attempt.get('checkpoint') if isinstance(attempt.get('checkpoint'), dict) else {}
        envelope = attempt.get('envelope') if isinstance(attempt.get('envelope'), dict) else {}
        side_effect_unknown = bool(
            checkpoint.get('side_effect_unknown', False)
            or envelope.get('side_effect_unknown', False)
            or str(checkpoint.get('side_effect_state', '') or '') in {'started', 'unknown'}
        )
        partial = str(checkpoint.get('answer', '') or checkpoint.get('partial_text', '') or '')
        terminal_state = 'needs_reconciliation' if side_effect_unknown else 'cancelled'
        if callable(self.cancel_executor_callback):
            self.cancel_executor_callback(attempt, terminal_state)
        if store is not None:
            store.update_attempt_state(
                str(payload.get('attempt_id', '') or ''),
                terminal_state,
                {
                    'cancel_state': 'confirmed',
                    'partial_artifact': partial,
                    'partial_is_complete_answer': False,
                    'auto_replay_allowed': False if side_effect_unknown else True,
                },
            )
        self._publish_terminal(payload, terminal_state, partial_artifact=partial, partial_is_complete_answer=False)
        marker = dict(payload, handled=True, result=terminal_state)
        self._save_control(marker)
        return marker

    def gate_task(self, request: dict) -> dict:
        cancel_id = self._control_id(
            'cancel_requested', str(request.get('task_id', '') or ''), str(request.get('attempt_id', '') or ''), ''
        )
        cancellation = self._load_control(cancel_id)
        store = self._store()
        if isinstance(cancellation, dict):
            if bool(cancellation.get('handled', False)):
                prior_result = str(cancellation.get('result', '') or 'cancelled')
                if prior_result in {'completed_cancel_missed', 'completed', 'finished'}:
                    return {'allow': True, 'status': prior_result, 'duplicate': True}
                return {
                    'allow': False,
                    'status': prior_result,
                    'cancel_before_arrival': bool(cancellation.get('cancel_before_arrival', True)),
                    'duplicate': True,
                }
            if store is not None and not store.attempt_exists(str(request.get('attempt_id', '') or '')):
                _created, _run = store.register_remote_attempt(request)
                store.update_attempt_state(
                    str(request.get('attempt_id', '') or ''),
                    'cancelled',
                    {'cancel_state': 'confirmed_before_arrival', 'partial_is_complete_answer': False},
                )
            cancellation.update({
                'handled': True,
                'pending_before_task': False,
                'cancel_before_arrival': True,
                'result': 'cancelled',
            })
            self._save_control(cancellation)
            self._publish_terminal(cancellation, 'cancelled', cancel_before_arrival=True)
            return {'allow': False, 'status': 'cancelled', 'cancel_before_arrival': True}
        dependency = str(request.get('depends_on_task_id', '') or '')
        if dependency and store is not None and store.task_state(dependency) not in self.TERMINAL_STATES:
            return {'allow': False, 'status': 'queued', 'depends_on_task_id': dependency}
        return {'allow': True}

    def request_queue(self, request: dict, depends_on_task_id: str) -> dict:
        request = dict(request or {})
        request['task_id'] = str(request.get('task_id', '') or new_broccoli_uuid('task-'))
        request['attempt_id'] = str(request.get('attempt_id', '') or new_broccoli_uuid('attempt-'))
        request['depends_on_task_id'] = str(depends_on_task_id or '')
        request['queue_position'] = int(request.get('queue_position', 1) or 1)
        destination = self.transport.submit_task(request)
        return {
            'status': 'queued',
            'position': request['queue_position'],
            'executor_id': str(request.get('executor_id', '') or ''),
            'request': request,
            'destination': destination,
        }

    def request_supplement(self,
                           conversation: dict,
                           task_id: str,
                           attempt_id: str,
                           executor_id: str,
                           text: str) -> dict:
        return self._publish_dual(
            'supplement', conversation, task_id, attempt_id, executor_id,
            suffix=hashlib.sha256(str(text or '').encode('utf-8')).hexdigest()[:16],
            fields={'text': str(text or '')},
        )

    def handle_supplement(self, payload: dict) -> dict:
        control_id = str(payload.get('control_id', '') or '')
        saved = self._load_control(control_id)
        if isinstance(saved, dict) and bool(saved.get('handled', False)):
            return dict(saved, duplicate=True)
        store = self._store()
        attempt = store.attempt_record(str(payload.get('attempt_id', '') or '')) if store is not None else None
        if isinstance(attempt, dict) and str(attempt.get('state', '') or '') not in self.TERMINAL_STATES:
            new_attempt_id = new_broccoli_uuid('attempt-')
            partial = str((attempt.get('checkpoint') or {}).get('answer', '') or '')
            if store is not None:
                store.update_attempt_state(
                    str(payload.get('attempt_id', '') or ''), 'cancelled',
                    {'partial_artifact': partial, 'partial_is_complete_answer': False, 'superseded_by': new_attempt_id},
                )
            if callable(self.supplement_callback):
                self.supplement_callback(payload, new_attempt_id, False)
            result = dict(payload, handled=True, result='new_attempt', new_attempt_id=new_attempt_id)
        else:
            if callable(self.queue_callback):
                self.queue_callback(payload, True)
            result = dict(payload, handled=True, result='converted_to_queue')
        self._save_control(result)
        return result

    def request_comment(self, conversation: dict, annotation: dict) -> dict:
        annotation = dict(annotation or {})
        annotation_id = str(annotation.get('id', '') or new_agent_annotation_id())
        annotation['id'] = annotation_id
        event = self._publish_dual(
            'annotation_added', conversation, '', '',
            str((conversation.get('identity') or {}).get('owner_device_id', '') or self.transport.device_id),
            suffix=annotation_id,
            fields={'annotation': annotation},
        )
        return event

    def merged_annotations(self, conversation: dict) -> list[dict]:
        merged = {}
        for item in conversation.get('agent_annotations') or []:
            if isinstance(item, dict) and item.get('id'):
                merged[str(item['id'])] = copy.deepcopy(item)
        for event in self.transport.read_events(conversation):
            if str(event.get('event_type', '') or '') != 'annotation_added':
                continue
            item = event.get('annotation') if isinstance(event.get('annotation'), dict) else {}
            if item.get('id'):
                merged.setdefault(str(item['id']), copy.deepcopy(item))
        return list(merged.values())

    def merge_comments_as_owner(self, conversation_path: str) -> dict | None:
        record = load_conversation_record(conversation_path, include_retrieval=False)
        if not isinstance(record, dict):
            return None
        identity = record.get('identity') if isinstance(record.get('identity'), dict) else {}
        if str(identity.get('owner_device_id', '') or self.transport.device_id) != self.transport.device_id:
            return None
        annotations = self.merged_annotations(record)
        if len(annotations) == len(record.get('agent_annotations') or []):
            return record
        record['agent_annotations'] = annotations
        record = write_conversation_record(conversation_path, record)
        self.transport.publish_revision(record)
        return record

    def retry(self, request: dict) -> dict:
        request = dict(request or {})
        store = self._store()
        old = store.attempt_record(str(request.get('attempt_id', '') or '')) if store is not None else None
        checkpoint = old.get('checkpoint') if isinstance(old, dict) and isinstance(old.get('checkpoint'), dict) else {}
        if str((old or {}).get('state', '') or '') == 'needs_reconciliation' or bool(checkpoint.get('side_effect_unknown', False)):
            self.record_incident(request, 'needs_reconciliation', 'Retry blocked because side-effect state is unknown.')
            return {'status': 'needs_reconciliation', 'auto_replayed': False}
        old_attempt = str(request.get('attempt_id', '') or '')
        request['attempt_id'] = new_broccoli_uuid('attempt-')
        request['retry_of_attempt_id'] = old_attempt
        self.transport.submit_task(request)
        return {'status': 'retry_sent', 'task_id': str(request.get('task_id', '') or ''), 'attempt_id': request['attempt_id']}

    def record_incident(self, payload: dict, incident_type: str, message: str) -> dict:
        incident_type = str(incident_type or '')
        if incident_type not in self.INCIDENT_TYPES:
            raise ValueError('Unknown Incident type.')
        incident = {
            'schema_version': ICLOUD_PROTOCOL_VERSION,
            'event_id': new_broccoli_uuid('incident-'),
            'event_type': 'incident',
            'incident_type': incident_type,
            'task_id': str(payload.get('task_id', '') or ''),
            'attempt_id': str(payload.get('attempt_id', '') or ''),
            'message': str(message or ''),
            'created_at': datetime.datetime.now().isoformat(timespec='milliseconds'),
        }
        conversation = self._event_conversation(payload)
        self.transport.publish_event(conversation, incident)
        store = self._store()
        if store is not None:
            store.append_event(incident)
        return incident

    def handle_interaction_response(self, session, response: dict) -> dict:
        pause_kind = terminal_pause_kind(session)
        decision = fail_closed_remote_decision((response or {}).get('decision'))
        if pause_kind != 'question':
            return {
                'accepted': False,
                'decision': 'reject',
                'pause_kind': pause_kind or 'approval',
                'status': 'waiting_local_action',
            }
        if decision not in {'approve', 'reject', 'retry', 'cancel'}:
            decision = 'reject'
        return {'accepted': True, 'decision': decision, 'pause_kind': 'question'}

    def handle_control(self, payload: dict) -> dict:
        if not verify_cloud_payload(payload):
            raise ValueError('Invalid TaskControl hash.')
        event_type = str(payload.get('event_type', '') or '')
        if event_type == 'cancel_requested':
            return self.handle_cancel(payload)
        if event_type == 'supplement':
            return self.handle_supplement(payload)
        if event_type == 'interaction_response':
            return {'status': 'interaction_pending_dispatch', 'payload': payload}
        if event_type in {'annotation_added', 'delete_requested'}:
            return {'status': 'event_recorded', 'payload': payload}
        raise ValueError('Unsupported TaskControl event.')

    def delete_conversation(self, conversation_path: str, task_id: str = '', attempt_id: str = '') -> dict:
        record = load_conversation_record(conversation_path, include_retrieval=False)
        if not isinstance(record, dict):
            return {'status': 'missing'}
        resolver = get_conversation_path_resolver()
        if resolver is not None:
            resolver.mark_deleted(str(record.get('id', '') or ''), conversation_path)
        identity = record.get('identity') if isinstance(record.get('identity'), dict) else {}
        executor = str(identity.get('owner_device_id', '') or self.transport.device_id)
        if task_id and attempt_id:
            self.request_cancel(record, task_id, attempt_id, executor)
        event = self._publish_dual('delete_requested', record, task_id, attempt_id, executor)
        return {'status': 'tombstoned', 'event': event}


def build_selection_ask_prompt(selected_text: str, question: str) -> str:
    """The single user message behind every ask-template action (the deep-dig
    markers on a screenshot AND the PopClip selection popup — they share this).
    FIX-45: the answer must come back in the user's PRIMARY language (Settings →
    Languages, first entry), not in whatever language the quoted text happens to
    be. The instruction goes AFTER the question — the quote block is truncated at
    SELECTION_ASK_QUOTE_LIMIT, so anything placed before it could be cut off, and
    anything folded into selected_text would be quoted as content, not obeyed."""
    quote = str(selected_text or '').strip()
    if len(quote) > SELECTION_ASK_QUOTE_LIMIT:
        quote = quote[:SELECTION_ASK_QUOTE_LIMIT].rstrip() + '\n[...truncated]'
    quoted = '\n'.join('> ' + line for line in quote.splitlines())
    language = preferred_ui_language()
    return (f'{quoted}\n\n{str(question or "").strip()}\n\n'
            f'Answer in {language}.')
