def capability_spec(capability: str) -> dict:
    return SPECIALIZED_CAPABILITY_REGISTRY.get(str(capability or '').strip(), {})


def capability_is_implemented(capability: str) -> bool:
    spec = capability_spec(capability)
    if not spec:
        return True
    return bool(spec.get('implemented', True))


def capability_is_single_surface(capability: str) -> bool:
    return bool(capability_spec(capability).get('single_surface', False))


def planner_capability_list_text() -> str:
    """planner 提示词 "Available capabilities:" 下的 '- 名字' 行。未实现的
    能力在这里隐藏，planner 就排不出它。"""
    return ''.join(
        f'- {key}\n'
        for key, spec in SPECIALIZED_CAPABILITY_REGISTRY.items()
        if spec.get('planner_listed') and spec.get('implemented', True)
    )


def plan_allowed_capabilities() -> set:
    """normalize_planner_plan 的接受集合（宽松超集：宣传从严、校验从宽）。"""
    return {key for key, spec in SPECIALIZED_CAPABILITY_REGISTRY.items() if spec.get('plan_allowed')}


def dynamic_allowed_capabilities() -> set:
    """复审动态插步/重试步的接受集合。"""
    return {key for key, spec in SPECIALIZED_CAPABILITY_REGISTRY.items() if spec.get('dynamic_allowed')}


def dynamic_available_capability_names(include_skill: bool) -> list:
    """复审提示词里向模型宣传的动态步骤可用能力（未实现的隐藏；skill 只在
    有技能目录时列出）。"""
    names = [
        key for key, spec in SPECIALIZED_CAPABILITY_REGISTRY.items()
        if spec.get('dynamic_allowed') and spec.get('implemented', True) and key != 'skill'
    ]
    if include_skill:
        names.append('skill')
    return names


def unimplemented_capability_step_result(capability: str, model_name: str, goal: str, execution_mode: str) -> dict:
    label = specialized_capability_label(capability)
    return {
        'capability': capability,
        'capability_label': label,
        'model_name': model_name,
        'text_output': f'{label} is not wired to a dedicated client endpoint in this build yet.',
        'artifacts': [],
        'metadata': {'goal': goal, 'execution_mode': execution_mode},
    }


