def normalize_agent_plan_step_review_seconds(value) -> int:
    try:
        seconds = int(value)
    except (TypeError, ValueError):
        seconds = AGENT_PLAN_STEP_REVIEW_SECONDS
    return max(AGENT_PLAN_STEP_REVIEW_MIN_SECONDS, min(AGENT_PLAN_STEP_REVIEW_MAX_SECONDS, seconds))


def normalize_agent_parallel_max_workers(value) -> int:
    try:
        workers = int(str(value).strip())
    except (TypeError, ValueError):
        workers = SPECIALIZED_PARALLEL_MAX_WORKERS
    return max(SPECIALIZED_PARALLEL_WORKERS_MIN, min(SPECIALIZED_PARALLEL_WORKERS_MAX, workers))


HISTORY_DISPLAY_LIMIT_MIN = 10
HISTORY_DISPLAY_LIMIT_MAX = 500
# Slider positions above MAX mean "All"; the top notch is MAX + this margin.
HISTORY_DISPLAY_LIMIT_ALL_NOTCH = HISTORY_DISPLAY_LIMIT_MAX + 10


def normalize_history_display_limit(value) -> int:
    """0 = render ALL history rows (default — today's behavior). 10-500 caps the
    rendered rows in the History panel; DISPLAY-only, nothing is deleted and
    search always scans the full record set."""
    try:
        limit = int(str(value).strip())
    except (TypeError, ValueError):
        return 0
    if limit <= 0 or limit > HISTORY_DISPLAY_LIMIT_MAX:
        return 0
    return max(HISTORY_DISPLAY_LIMIT_MIN, limit)


def agent_plan_step_review_seconds() -> int:
    """每步执行前"等待 Plan 编辑"的停顿秒数（用户可在设置里拖滑杆
    调整，5-120，默认 10）。每次读取实时生效，计划运行中改也算数。"""
    try:
        store = load_settings_store()
        return normalize_agent_plan_step_review_seconds(
            store.get('globals', {}).get('agent_plan_step_review_seconds', AGENT_PLAN_STEP_REVIEW_SECONDS)
        )
    except Exception:
        return AGENT_PLAN_STEP_REVIEW_SECONDS
