def normalize_browser_use_history_items(value) -> int:
    try:
        number = int(str(value).strip() or 0)
    except (TypeError, ValueError):
        return DEFAULT_BROWSER_USE_HISTORY_ITEMS
    if number <= 0:
        return 0
    # browser-use 断言 max_history_items 必须 >5，1–5 一律抬到 6。
    return max(6, min(number, MAX_BROWSER_USE_STEPS))


