def load_terminal_favorite_records() -> list[dict]:
    try:
        stat = os.stat(TERMINAL_FAVORITES_PATH)
        signature = (int(stat.st_mtime_ns), int(stat.st_size))
    except OSError:
        signature = None
    with _TERMINAL_FILE_CACHE_LOCK:
        if (
            _TERMINAL_FAVORITES_CACHE.get('records') is not None
            and _TERMINAL_FAVORITES_CACHE.get('signature') == signature
        ):
            return [dict(record) for record in _TERMINAL_FAVORITES_CACHE['records']]
    records = []
    for item in _load_json_list(TERMINAL_FAVORITES_PATH):
        normalized = normalize_terminal_favorite_record(item)
        if normalized is not None:
            records.append(normalized)
    with _TERMINAL_FILE_CACHE_LOCK:
        _TERMINAL_FAVORITES_CACHE['signature'] = signature
        _TERMINAL_FAVORITES_CACHE['records'] = [dict(record) for record in records]
    return [dict(record) for record in records]


def save_terminal_favorite_records(records: list[dict]) -> None:
    normalized = []
    for item in records or []:
        record = normalize_terminal_favorite_record(item)
        if record is not None:
            normalized.append(record)
    _save_json_list(TERMINAL_FAVORITES_PATH, normalized)
    with _TERMINAL_FILE_CACHE_LOCK:
        _TERMINAL_FAVORITES_CACHE['signature'] = None
        _TERMINAL_FAVORITES_CACHE['records'] = None


def upsert_terminal_favorite(command: str, caption: str = '') -> dict | None:
    command = str(command or '').strip()
    if not command:
        return None
    now = datetime.datetime.now().isoformat(timespec='seconds')
    records = load_terminal_favorite_records()
    for index, record in enumerate(records):
        if str(record.get('command', '')).strip() == command:
            updated = dict(record)
            if str(caption or '').strip():
                updated['caption'] = str(caption).strip()
            updated['updated_at'] = now
            normalized = normalize_terminal_favorite_record(updated)
            if normalized is not None:
                records[index] = normalized
                save_terminal_favorite_records(records)
                return normalized
            return None
    record = normalize_terminal_favorite_record(
        {
            'id': f'fav-{int(time.time() * 1000)}',
            'caption': str(caption or '').strip() or _terminal_default_favorite_caption(command),
            'command': command,
            'created_at': now,
            'updated_at': now,
        }
    )
    if record is None:
        return None
    records.append(record)
    save_terminal_favorite_records(records)
    return record


def parse_zsh_history_records(path: str = DEFAULT_ZSH_HISTORY_PATH) -> list[dict]:
    records = []
    path = os.path.abspath(os.path.expanduser(str(path or DEFAULT_ZSH_HISTORY_PATH)))
    try:
        stat = os.stat(path)
        signature = (int(stat.st_mtime_ns), int(stat.st_size))
        with _TERMINAL_FILE_CACHE_LOCK:
            cached = _ZSH_HISTORY_CACHE.get(path)
            if cached is not None and cached.get('signature') == signature:
                return [dict(record) for record in cached.get('records', [])]
        with open(path, 'rb') as handle:
            raw_bytes = handle.read()
    except FileNotFoundError:
        return records
    except Exception:
        return records
    if not raw_bytes:
        return records
    try:
        raw = raw_bytes.decode('utf-8')
    except UnicodeDecodeError:
        raw = raw_bytes.decode('utf-8', errors='replace')
    if not raw:
        return records
    for index, line in enumerate(raw.splitlines(), start=1):
        line = str(line or '').rstrip('\n')
        if not line.strip():
            continue
        command = line
        created_at = ''
        match = re.match(r'^: (\d+):\d+;(.*)$', line)
        if match is not None:
            try:
                created_at = datetime.datetime.fromtimestamp(int(match.group(1))).isoformat(timespec='seconds')
            except Exception:
                created_at = ''
            command = match.group(2)
        command = str(command or '').strip()
        if not command:
            continue
        record = {
            'id': f'zsh-{index}',
            'command': command,
            'output': '',
            'created_at': created_at,
            'mode': 'shell_history',
            'search_blob': '\n'.join(part for part in (command, created_at) if part).lower(),
        }
        records.append(record)
    with _TERMINAL_FILE_CACHE_LOCK:
        _ZSH_HISTORY_CACHE[path] = {
            'signature': signature,
            'records': [dict(record) for record in records],
        }
    return [dict(record) for record in records]


def normalize_endpoint_value(endpoint: str) -> str:
    value = endpoint.strip().rstrip('/')
    for suffix in ('/v1/chat/completions', '/v1/completions', '/v1/embeddings', '/v1'):
        if value.endswith(suffix):
            value = value[:-len(suffix)]
            break
    return value or DEFAULT_ENDPOINT


def is_official_openai_endpoint(endpoint: str) -> bool:
    return normalize_endpoint_value(endpoint) == DEFAULT_ENDPOINT


def is_perplexity_endpoint(endpoint: str) -> bool:
    return 'api.perplexity.ai' in normalize_endpoint_value(str(endpoint or '')).lower()


def extract_perplexity_citation_urls(citations) -> list[str]:
    urls = []
    for item in citations or []:
        url = str(item or '').strip()
        if url and url not in urls:
            urls.append(url)
    return urls


def format_perplexity_citations_block(citations) -> str:
    urls = extract_perplexity_citation_urls(citations)
    if not urls:
        return ''
    return 'Citations:\n' + '\n'.join(f'[{index}] {url}' for index, url in enumerate(urls, start=1))


def is_dark_theme(app_obj) -> bool:
    try:
        if NSUserDefaults is not None:
            defaults = NSUserDefaults.standardUserDefaults()
            style = defaults.stringForKey_("AppleInterfaceStyle")
            return style == "Dark"
        return app_obj.palette().window().color().lightness() < 128
    except Exception:
        return False


def get_accent_color_hex() -> str:
    try:
        if NSColor is None:
            return '#0A84FF'
        accent = NSColor.controlAccentColor()
        rgb = accent.colorUsingColorSpaceName_('NSCalibratedRGBColorSpace')
        if rgb is not None:
            r = int(rgb.redComponent() * 255)
            g = int(rgb.greenComponent() * 255)
            b = int(rgb.blueComponent() * 255)
            return f'#{r:02X}{g:02X}{b:02X}'
    except Exception:
        pass
    return '#0A84FF'


def set_light_palette(app_obj):
    palette = QPalette()
    palette.setColor(QPalette.ColorRole.Window, QColor(255, 255, 255))
    palette.setColor(QPalette.ColorRole.WindowText, QColor(0, 0, 0))
    palette.setColor(QPalette.ColorRole.Base, QColor(255, 255, 255))
    palette.setColor(QPalette.ColorRole.Text, QColor(0, 0, 0))
    palette.setColor(QPalette.ColorRole.Button, QColor(240, 240, 240))
    palette.setColor(QPalette.ColorRole.ButtonText, QColor(0, 0, 0))
    app_obj.setPalette(palette)


def set_dark_palette(app_obj):
    palette = QPalette()
    palette.setColor(QPalette.ColorRole.Window, QColor(30, 30, 30))
    palette.setColor(QPalette.ColorRole.WindowText, QColor(220, 220, 220))
    palette.setColor(QPalette.ColorRole.Base, QColor(42, 42, 42))
    palette.setColor(QPalette.ColorRole.Text, QColor(220, 220, 220))
    palette.setColor(QPalette.ColorRole.Button, QColor(50, 50, 50))
    palette.setColor(QPalette.ColorRole.ButtonText, QColor(220, 220, 220))
    app_obj.setPalette(palette)


