class SettingsPageJumpLabel(QLabel):
    """Pager "N / M ▾" label; a click opens that category's page list. Always as wide as
    the widest "N / M ▾" of its category (digits differ in width, and 9 → 10 adds one), so
    turning pages never moves the ‹ › buttons beside it."""
    clicked = pyqtSignal()

    def __init__(self, text: str = '', parent=None):
        super().__init__(text, parent)
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.setToolTip(_tr('Jump to a page'))
        self.setSizePolicy(QSizePolicy.Policy.Fixed, QSizePolicy.Policy.Preferred)

    def _widest_text_width(self):
        match = re.match(r'\s*\d+\s*/\s*(\d+)', self.text())
        if not match:
            return None
        count = max(1, int(match.group(1)))
        metrics = self.fontMetrics()
        widest = 0
        for number in range(1, count + 1):
            text = f'{number} / {count} ▾'
            widest = max(widest, metrics.horizontalAdvance(text), metrics.boundingRect(text).width())
        return widest

    def sizeHint(self):
        hint = super().sizeHint()
        widest = self._widest_text_width()
        if widest is not None:
            # Measured the same way whatever page is showing (never from the current text).
            margins = self.contentsMargins()
            hint.setWidth(widest + 2 + margins.left() + margins.right() + 2 * self.margin())
        return hint

    def minimumSizeHint(self):
        return self.sizeHint()

    def mousePressEvent(self, event):
        if event.button() == Qt.MouseButton.LeftButton:
            self.clicked.emit()
            event.accept()
            return
        super().mousePressEvent(event)


class SettingsPageScrollArea(QScrollArea):
    """Scroller for one settings page: the page is always exactly as wide as the
    viewport and as tall as the larger of the viewport and the page's MINIMUM
    height for that width. QScrollArea's resizable mode instead grows a page
    with word-wrapping text to its preferred height (Memory endpoints: 648px
    preferred vs 424px needed) and scrolls pages that actually fit."""

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setWidgetResizable(False)
        self.viewport().installEventFilter(self)

    def setWidget(self, widget):
        super().setWidget(widget)
        widget.installEventFilter(self)
        self._fit_page()

    def resizeEvent(self, event):
        super().resizeEvent(event)
        self._fit_page()

    def eventFilter(self, obj, event):
        if event.type() == QEvent.Type.LayoutRequest and obj is self.widget():
            QTimer.singleShot(0, self._fit_page)
        elif event.type() == QEvent.Type.Resize and obj is self.viewport():
            # The vertical scrollbar appearing narrows the viewport without
            # resizing the scroll area itself.
            QTimer.singleShot(0, self._fit_page)
        return super().eventFilter(obj, event)

    def _fit_page(self):
        page = self.widget()
        if page is None:
            return
        width = max(1, self.viewport().width())
        layout = page.layout()
        if layout is not None and layout.hasHeightForWidth():
            needed = layout.minimumHeightForWidth(width)
        else:
            needed = page.minimumSizeHint().height()
        height = max(self.viewport().height(), int(needed))
        if page.width() != width or page.height() != height:
            page.resize(width, height)


