def _settings_transparent_snapshot(widget: QWidget) -> QPixmap:
    """Render a widget and its children onto a transparent pixmap. grab() fills
    the window colour first, which shows as a light block on the dark panel."""
    ratio = max(1.0, float(widget.devicePixelRatioF()))
    pixmap = QPixmap(max(1, int(round(widget.width() * ratio))), max(1, int(round(widget.height() * ratio))))
    pixmap.setDevicePixelRatio(ratio)
    pixmap.fill(Qt.GlobalColor.transparent)
    widget.render(pixmap, QPoint(0, 0), QRegion(), QWidget.RenderFlag.DrawChildren)
    return pixmap


class SettingsPopupCardPainter(QObject):
    """Paints the rounded card behind a translucent completer popup. A list view
    stops painting its stylesheet background and border once its window is
    translucent, so the card is drawn here before the frame/viewport paint."""

    RADIUS = 12.0   # GLASS_LIST_RADIUS: like the system menus and the other lists

    def __init__(self, popup: QWidget, colors, dark_for=None):
        super().__init__(popup)
        self._popup = popup
        self._colors = colors  # callable -> (background, border)
        self._dark_for = dark_for
        popup.installEventFilter(self)

    def eventFilter(self, obj, event):
        if obj is self._popup and event.type() == QEvent.Type.Show and liquid_glass_available():
            # The system menu's glass (regular, untinted) + system shadow, like the other lists.
            dark = bool(self._dark_for()) if callable(self._dark_for) else is_dark_theme(app)
            QTimer.singleShot(0, lambda p=obj, d=dark: apply_window_liquid_glass(
                p, self.RADIUS, 0, dark=True if d else None, keep_shadow=True, menu_look=True))
        if obj is self._popup and event.type() == QEvent.Type.Paint:
            if getattr(obj, '_liquid_glass_active', False):
                return False   # the glass is the card
            background, border = self._colors()
            painter = QPainter(obj)
            painter.setRenderHint(QPainter.RenderHint.Antialiasing, True)
            path = QPainterPath()
            path.addRoundedRect(QRectF(obj.rect()).adjusted(0.5, 0.5, -0.5, -0.5), self.RADIUS, self.RADIUS)
            painter.fillPath(path, QColor(background))
            painter.setPen(QPen(QColor(border), 1))
            painter.drawPath(path)
            painter.end()
        return False


class SettingsSlideOverlay(QWidget):
    """Covers a settings page stack while the outgoing and incoming page
    snapshots slide sideways. The real switch has already happened underneath;
    the overlay paints the panel background so neither page shows through."""

    def __init__(self, parent: QWidget, old_pixmap: QPixmap, new_pixmap: QPixmap,
                 direction: int, background: QColor):
        super().__init__(parent)
        self._old = old_pixmap
        self._new = new_pixmap
        self._direction = 1 if direction >= 0 else -1
        self._background = QColor(background)
        self._progress = 0.0
        self.setGeometry(parent.rect())

    def set_progress(self, value) -> None:
        self._progress = max(0.0, min(1.0, float(value)))
        self.update()

    def paintEvent(self, event):
        painter = QPainter(self)
        painter.fillRect(self.rect(), self._background)
        offset = int(round(self._progress * self.width()))
        # 下一页：旧页向左移出、新页从右推入；上一页反之。
        painter.drawPixmap(-self._direction * offset, 0, self._old)
        painter.drawPixmap(self._direction * (self.width() - offset), 0, self._new)
        painter.end()


