    def _editable_extra_headers(self, record: dict) -> str:
        headers = []
        toolsets = str(record.get('toolsets', '') or '').strip()
        for raw_line in str(record.get('headers', '') or '').splitlines():
            line = raw_line.strip()
            lower = line.lower()
            if not line:
                continue
            if lower.startswith('authorization:') and '<stored token>' in line:
                continue
            if toolsets and lower == f'x-mcp-toolsets: {toolsets}'.lower():
                continue
            if bool(record.get('read_only', True)) and lower == 'x-mcp-readonly: true':
                continue
            headers.append(line)
        return '\n'.join(headers)

    def _accept_if_valid(self):
        if self.endpoint():
            self.accept()

    def endpoint(self) -> str:
        return self.endpoint_input.text().strip()

    def _base_record(self) -> dict:
        endpoint = self.endpoint()
        token = self.token_input.text().strip()
        toolsets = self.toolsets_input.text().strip()
        headers = self.headers_edit.toPlainText().strip()
        if token:
            headers = (headers + '\n' if headers else '') + 'Authorization: Bearer <stored token>'
        if toolsets:
            headers = (headers + '\n' if headers else '') + f'X-MCP-Toolsets: {toolsets}'
        if self.read_only_checkbox.isChecked():
            headers = (headers + '\n' if headers else '') + 'X-MCP-Readonly: true'
        return {
            'id': self._source_id,
            'type': 'mcp_http',
            'name': self.name_input.text().strip() or endpoint.rstrip('/').split('/')[-1] or 'MCP HTTP',
            'endpoint': endpoint,
            'transport': self.transport_combo.currentData() or 'auto',
            'auth_token': token,
            'toolsets': toolsets,
            'headers': headers,
            'enabled': True,
            'auto_context': True,
            'read_only': self.read_only_checkbox.isChecked(),
            'use_in_tool_runtime': True,
            'max_chars': DEFAULT_EXTERNAL_CONTEXT_MAX_CHARS,
        }

    def record(self) -> dict:
        record = self._base_record()
        discovery = self._discovery_result if isinstance(self._discovery_result, dict) else {}
        if discovery:
            if discovery.get('ok'):
                list_fields = {'discovered_tools', 'discovered_resources', 'discovered_prompts'}
                for key in (
                    'mcp_protocol_version',
                    'mcp_server_name',
                    'mcp_server_version',
                    'discovered_at',
                    'discovery_error',
                    'discovered_tools',
                    'discovered_resources',
                    'discovered_prompts',
                ):
                    record[key] = discovery.get(key, [] if key in list_fields else '')
                if discovery.get('mcp_server_name') and record['name'] in {'GitHub', 'MCP HTTP'}:
                    record['name'] = str(discovery.get('mcp_server_name'))
            else:
                record['discovery_error'] = str(discovery.get('discovery_error') or discovery.get('error') or '')
        return record

    def _discover(self):
        if not self.endpoint():
            self.discovery_output.setPlainText(_tr('Discovery failed:\nEndpoint URL is empty.'))
            return
        source = self._base_record()
        self.discover_button.setEnabled(False)
        QApplication.setOverrideCursor(Qt.CursorShape.WaitCursor)
        try:
            try:
                result = discover_mcp_source(source)
            except Exception as exc:
                result = {
                    'ok': False,
                    'discovery_error': str(exc),
                    'discovered_at': datetime.datetime.now().isoformat(timespec='seconds'),
                }
            self._discovery_result = result
            self.discovery_output.setPlainText(format_mcp_discovery_summary(result))
        finally:
            QApplication.restoreOverrideCursor()
            self.discover_button.setEnabled(True)

    def paintEvent(self, event):
        painter = QPainter(self)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)
        dark = is_dark_theme(app)
        panel_rect = QRectF(
            self._panel_margin,
            self._panel_margin,
            self.width() - self._panel_margin * 2,
            self.height() - self._panel_margin * 2,
        )
        bg_path = smooth_round_rect_path(panel_rect, self._panel_radius)
        if not getattr(self, '_liquid_glass_active', False):   # 液态玻璃时由系统玻璃当底
            painter.fillPath(bg_path, QColor('#2D2D2D' if dark else '#FFFFFF'))
            painter.setPen(QPen(QColor('#3A3A3A' if dark else '#ECECEC'), 1))
            painter.drawPath(bg_path)
        painter.end()

    def _apply_theme(self):
        if self._theme_updating:
            return
        self._theme_updating = True
        dark = is_dark_theme(app)
        try:
            self.title_lbl.setStyleSheet(
                f'font-family: "Helvetica Neue", Helvetica, Arial, sans-serif; font-size: 13px; '
                f'font-weight: 600; color: {"#F2F2F7" if dark else "#20242B"};'
            )
            line_style = _settings_lineedit_stylesheet(dark)
            for widget in (self.name_input, self.endpoint_input, self.token_input, self.toolsets_input):
                widget.setStyleSheet(line_style)
            self.headers_edit.setStyleSheet(_settings_textedit_stylesheet(dark))
            self.discovery_output.setStyleSheet(_settings_textedit_stylesheet(dark))
            self.read_only_checkbox.setStyleSheet(
                f'color: {"#F2F2F7" if dark else "#20242B"}; '
                'font-family: "Helvetica Neue", Helvetica, Arial, sans-serif; background: transparent;'
            )
            for label in self.findChildren(QLabel):
                if label is not self.title_lbl:
                    label.setStyleSheet(
                        f'color: {"#F2F2F7" if dark else "#20242B"}; '
                        'font-family: "Helvetica Neue", Helvetica, Arial, sans-serif; font-size: 12px; background: transparent;'
                    )
        finally:
            self._theme_updating = False

    def changeEvent(self, event):
        super().changeEvent(event)
        if self._theme_updating:
            return
        if event.type() in (QEvent.Type.PaletteChange, QEvent.Type.ApplicationPaletteChange):
            self._apply_theme()


