# 成组设置：默认值整组展开，读入时整组归一（组归一函数吃整个 raw globals）。
# computer_use 一组必须在这里：load_settings_store 的结构性透传只认默认键集，
# 漏组会让磁盘上已保存的该组设置在每次读取时被静默丢弃（历史事故）。
GLOBAL_SETTING_GROUP_SPECS = [
    ('default_browser_use_settings', 'normalize_browser_use_settings'),
    ('default_computer_use_settings', 'normalize_computer_use_settings'),
    ('default_background_vision_settings', 'normalize_background_vision_settings'),
]


def _resolve_setting_default(default):
    if isinstance(default, tuple) and len(default) == 2 and default[0] == 'call':
        return globals()[default[1]]()
    if isinstance(default, (list, dict)):
        return copy.deepcopy(default)
    return default


def default_global_settings() -> dict:
    ensure_broccoli_data_dir()
    defaults = {}
    for key, default, _load_rule in GLOBAL_SETTING_SPECS:
        defaults[key] = _resolve_setting_default(default)
    for default_fn_name, _normalize_fn_name in GLOBAL_SETTING_GROUP_SPECS:
        defaults.update(globals()[default_fn_name]())
    return defaults


def _apply_global_setting_load_rules(raw_globals: dict, globals_store: dict) -> None:
    """按声明表把磁盘上的 raw globals 归一进 globals_store（就地更新）。
    调用前 globals_store 已含默认值且默认键集内的磁盘值已结构透传。"""
    for key, _default, rule in GLOBAL_SETTING_SPECS:
        if rule is None:
            continue
        if isinstance(rule, str):
            value = raw_globals.get(key, globals_store[key])
            if rule == 'str':
                globals_store[key] = str(value)
            elif rule == 'str_strip':
                globals_store[key] = str(value).strip()
            elif rule == 'str_strip_none':
                globals_store[key] = str(value or '').strip()
            elif rule == 'bool':
                globals_store[key] = bool(value)
            elif rule == 'int':
                globals_store[key] = int(value)
            else:
                raise ValueError(f'Unknown load rule {rule!r} for global setting {key!r}')
            continue
        kind = rule[0]
        if kind == 'str_or':
            globals_store[key] = str(raw_globals.get(key, globals_store[key])) or rule[1]
        elif kind == 'str_strip_or':
            globals_store[key] = str(raw_globals.get(key, globals_store[key])).strip() or rule[1]
        elif kind == 'fn':
            globals_store[key] = globals()[rule[1]](raw_globals.get(key, globals_store[key]))
        elif kind == 'fn_raw':
            globals_store[key] = globals()[rule[1]](raw_globals.get(key))
        elif kind == 'fn_if_present':
            if key in raw_globals:
                globals_store[key] = globals()[rule[1]](raw_globals.get(key, []))
        elif kind == 'coerce_int':
            globals_store[key] = _coerce_int(
                raw_globals.get(key, globals_store[key]), rule[1], rule[2], rule[3]
            )
        elif kind == 'custom':
            globals_store[key] = globals()[rule[1]](raw_globals, globals_store)
        else:
            raise ValueError(f'Unknown load rule {rule!r} for global setting {key!r}')
    for _default_fn_name, normalize_fn_name in GLOBAL_SETTING_GROUP_SPECS:
        globals_store.update(globals()[normalize_fn_name](raw_globals))


def load_settings_store() -> dict:
    ensure_broccoli_data_dir()
    try:
        stat = os.stat(SETTINGS_PROFILES_PATH)
        signature = (int(stat.st_mtime_ns), int(stat.st_size))
    except OSError:
        signature = None
    with _SETTINGS_STORE_CACHE_LOCK:
        if (
            _SETTINGS_STORE_CACHE.get('store') is not None
            and _SETTINGS_STORE_CACHE.get('signature') == signature
        ):
            return copy.deepcopy(_SETTINGS_STORE_CACHE['store'])
    store = {}
    if os.path.exists(SETTINGS_PROFILES_PATH):
        try:
            with open(SETTINGS_PROFILES_PATH, 'r', encoding='utf-8') as handle:
                loaded = json.load(handle)
            if isinstance(loaded, dict):
                store = loaded
        except Exception:
            store = {}

    raw_profiles = store.get('profiles', [])
    profiles = []
    if isinstance(raw_profiles, list):
        for index, item in enumerate(raw_profiles, start=1):
            if isinstance(item, dict):
                profiles.append(normalize_profile_entry(item, f'Profile {index}'))
    if not profiles:
        profiles = [legacy_profile_snapshot()]

    globals_store = default_global_settings()
    if isinstance(store.get('globals'), dict):
        # 结构性防丢：默认键集内的键先原样透传（磁盘有就拿），声明表的
        # 归一规则再覆盖需要类型安全的键。这样新增 globals 键只要进了
        # GLOBAL_SETTING_SPECS 就同时获得默认值、持久化和归一，不再要求
        # 同步维护多份白名单（custom_services、specialized_profile_candidates、
        # computer_use 组都曾栽在漏列上）。
        for passthrough_key in list(globals_store.keys()):
            if passthrough_key in store['globals']:
                globals_store[passthrough_key] = store['globals'][passthrough_key]
        _apply_global_setting_load_rules(store['globals'], globals_store)

    active_profile = str(store.get('active_profile', profiles[0]['name'])).strip()
    if active_profile not in {profile['name'] for profile in profiles}:
        active_profile = profiles[0]['name']

    normalized_store = {
        'active_profile': active_profile,
        'profiles': profiles,
        'globals': globals_store,
    }
    with _SETTINGS_STORE_CACHE_LOCK:
        _SETTINGS_STORE_CACHE['signature'] = signature
        _SETTINGS_STORE_CACHE['store'] = copy.deepcopy(normalized_store)
    return copy.deepcopy(normalized_store)


# Every write of settings_profiles.json rewrites the WHOLE file, so a writer
# holding an older copy silently undoes whatever was saved after it loaded
# (2026-10: the Settings panel's startup copy wiped the daily rollup's note and
# date on every online-memory sync; a minutes-long LLM rollup could likewise wipe
# online-memory status). Writers that own only a few keys therefore go through
# update_settings_store()/update_settings_globals() — fresh disk copy, own keys
# only, under this lock — and the Settings panel merges its save three-way
# (merge_settings_globals_three_way).
_SETTINGS_STORE_WRITE_LOCK = threading.RLock()


def save_settings_store(store: dict) -> None:
    ensure_broccoli_data_dir()
    # Serialize first: a failing dump must not leave a truncated file behind.
    payload = json.dumps(store, ensure_ascii=False, indent=2)
    with _SETTINGS_STORE_WRITE_LOCK:
        # Atomic replace: a reader never sees a half-written file (a parse
        # failure in load_settings_store falls back to DEFAULT settings, and the
        # next save would make that loss permanent).
        target = os.path.realpath(SETTINGS_PROFILES_PATH)
        tmp_path = f'{target}.{os.getpid()}.{threading.get_ident()}.tmp'
        try:
            with open(tmp_path, 'w', encoding='utf-8') as handle:
                handle.write(payload)
                handle.flush()
                os.fsync(handle.fileno())
            try:
                os.chmod(tmp_path, os.stat(target).st_mode & 0o7777)
            except OSError:
                pass
            os.replace(tmp_path, target)
        finally:
            if os.path.exists(tmp_path):
                try:
                    os.remove(tmp_path)
                except OSError:
                    pass
        with _SETTINGS_STORE_CACHE_LOCK:
            _SETTINGS_STORE_CACHE['signature'] = None
            _SETTINGS_STORE_CACHE['store'] = None


def update_settings_store(mutate) -> dict:
    """Read-modify-write under the write lock: `mutate(store)` gets the CURRENT
    on-disk store (a private normalized copy) and edits only the keys its caller
    owns; every other key stays exactly as the latest writer left it. Returns the
    saved store."""
    with _SETTINGS_STORE_WRITE_LOCK:
        store = load_settings_store()
        store.setdefault('globals', default_global_settings())
        mutate(store)
        save_settings_store(store)
        return store


def update_settings_globals(updates: dict) -> dict:
    """update_settings_store() for writers that own a few globals keys."""
    updates = copy.deepcopy(dict(updates or {}))
    return update_settings_store(lambda store: store['globals'].update(updates))


def merge_settings_globals_three_way(base: dict, mine: dict, theirs: dict) -> dict:
    """Settings-panel save merge. base = the globals the panel loaded, mine = what
    the panel would write now, theirs = what is on disk now. A key the panel
    changed keeps the panel's value; a key it did not change takes the disk value,
    so updates other writers made meanwhile (daily rollup note, online-memory
    status, tray toggles…) are no longer reverted by the panel's stale copy. A key
    the panel dropped stays dropped. memory_items changed on BOTH sides keeps the
    panel's list plus the items other writers added since the panel loaded."""
    base = base if isinstance(base, dict) else {}
    mine = mine if isinstance(mine, dict) else {}
    theirs = theirs if isinstance(theirs, dict) else {}
    merged = {}
    for key in list(mine.keys()) + [k for k in theirs.keys() if k not in mine]:
        if key in mine:
            panel_changed = key not in base or mine[key] != base[key]
            if panel_changed or key not in theirs:
                merged[key] = copy.deepcopy(mine[key])
            else:
                merged[key] = copy.deepcopy(theirs[key])
        elif key not in base:
            merged[key] = copy.deepcopy(theirs[key])
    items_key = 'memory_items'
    if (
        isinstance(mine.get(items_key), list)
        and isinstance(theirs.get(items_key), list)
        and mine.get(items_key) != base.get(items_key)
        and theirs.get(items_key) != base.get(items_key)
    ):
        base_items = base.get(items_key) if isinstance(base.get(items_key), list) else []
        combined = copy.deepcopy(mine[items_key])
        for item in theirs[items_key]:
            if item not in base_items and item not in combined:
                combined.append(copy.deepcopy(item))
        merged[items_key] = combined
    return merged


def agent_cli_auto_start_enabled() -> bool:
    try:
        globals_store = load_settings_store().get('globals', {})
    except Exception:
        globals_store = {}
    return bool(globals_store.get('terminal_auto_start_agent_cli_tabs', True))


def web_auto_open_last_urls_enabled() -> bool:
    try:
        globals_store = load_settings_store().get('globals', {})
    except Exception:
        globals_store = {}
    return bool(globals_store.get('web_auto_open_last_urls', True))


def get_external_strictness_tier(target_kind: str) -> str:
    """The persisted strictness tier for a terminal target kind ('codex'/'claude'),
    falling back to the default. Returns '' for kinds with no tiers."""
    kind = str(target_kind or '').strip().lower()
    if kind == 'claude_tui':
        kind = 'claude'
    if kind not in EXTERNAL_STRICTNESS_TIERS:
        return ''
    prefs = load_settings_store().get('globals', {}).get('external_strictness_tiers', {})
    tier = str(prefs.get(kind, '') or '')
    valid = {t for t, _ in EXTERNAL_STRICTNESS_TIERS[kind]}
    return tier if tier in valid else EXTERNAL_STRICTNESS_DEFAULT.get(kind, 'strict')


def set_external_strictness_tier(target_kind: str, tier: str) -> None:
    """Persist the chosen strictness tier for a terminal target kind."""
    kind = str(target_kind or '').strip().lower()
    if kind == 'claude_tui':
        kind = 'claude'
    valid = {t for t, _ in EXTERNAL_STRICTNESS_TIERS.get(kind, [])}
    if tier not in valid:
        return
    def apply(store):
        tiers = store['globals'].get('external_strictness_tiers')
        if not isinstance(tiers, dict):
            tiers = {}
        tiers[kind] = tier
        store['globals']['external_strictness_tiers'] = tiers
    update_settings_store(apply)


def is_matching_webfetch_filename(name: str) -> bool:
    name = str(name or '').strip()
    return bool(WEBFETCH_STRICT_RE.match(name) or WEBFETCH_LOOSE_RE.match(name))


def normalize_webfetch_page(page: dict, index: int) -> dict | None:
    if not isinstance(page, dict):
        return None
    url = str(page.get('url', '')).strip()
    title = str(page.get('title', '')).strip()
    text = str(page.get('text', '')).strip()
    if not url and not text:
        return None
    display_title = title or url or f'Page {index + 1}'
    page_id = str(page.get('id', '')).strip() or f'page-{index + 1}'
    return {
        'id': page_id,
        'url': url,
        'title': display_title,
        'domain': str(page.get('domain', '')).strip(),
        'captured_at': str(page.get('capturedAt', '')).strip(),
        'text': text,
        'links': page.get('links') if isinstance(page.get('links'), list) else [],
        'meta': page.get('meta') if isinstance(page.get('meta'), dict) else {},
    }


def load_webfetch_export(path: str) -> dict | None:
    if not path or not os.path.exists(path):
        return None
    try:
        with open(path, 'r', encoding='utf-8') as handle:
            data = json.load(handle)
    except Exception:
        return None
    if not isinstance(data, dict):
        return None
    schema = str(data.get('schema', '')).strip()
    if not schema.startswith('broccoli-webfetch'):
        return None
    raw_pages = data.get('pages')
    if not isinstance(raw_pages, list):
        return None
    pages = []
    for index, page in enumerate(raw_pages):
        normalized = normalize_webfetch_page(page, index)
        if normalized:
            pages.append(normalized)
    if not pages:
        return None
    exported_at = str(data.get('exportedAt', '')).strip() or datetime.datetime.now().isoformat(timespec='seconds')
    return {
        'path': path,
        'name': os.path.basename(path),
        'schema': schema,
        'exported_at': exported_at,
        'count': len(pages),
        'pages': pages,
    }


def list_webfetch_exports(folder: str) -> list[dict]:
    folder_path = Path(str(folder or '').strip())
    if not folder_path.exists():
        return []
    results = []
    for file_path in folder_path.glob('Broccoli-WebFetch_*.json'):
        if not is_matching_webfetch_filename(file_path.name):
            continue
        record = load_webfetch_export(str(file_path))
        if record:
            results.append(record)
    results.sort(key=lambda item: item.get('exported_at', ''), reverse=True)
    return results


def import_webfetch_file_to_inbox(source_path: str) -> dict | None:
    if not source_path or not os.path.exists(source_path):
        return None
    source = Path(source_path)
    if not is_matching_webfetch_filename(source.name):
        return None
    record = load_webfetch_export(str(source))
    if record is None:
        return None
    ensure_broccoli_data_dir()
    target = Path(WEBFETCH_INBOX_DIR) / source.name
    if source.resolve() != target.resolve():
        base = source.stem
        suffix = source.suffix
        counter = 2
        while target.exists():
            target = Path(WEBFETCH_INBOX_DIR) / f'{base}-{counter}{suffix}'
            counter += 1
        shutil.move(str(source), str(target))
    return load_webfetch_export(str(target))


def webfetch_documents_from_pages(pages: list[dict]) -> list[dict]:
    documents = []
    for index, page in enumerate(pages or []):
        normalized = normalize_webfetch_page(page, index)
        if normalized is None:
            continue
        text = normalized['text'].strip()
        if not text:
            continue
        header = []
        if normalized['title']:
            header.append(f"Title: {normalized['title']}")
        if normalized['url']:
            header.append(f"URL: {normalized['url']}")
        body = '\n'.join(header + [text]).strip()
        documents.append(
            {
                'name': normalized['title'] or normalized['url'] or f'Page {index + 1}',
                'content': body,
                'page': normalized,
            }
        )
    return documents


def load_webfetch_selection_attachment(path: str) -> dict | None:
    if not path or not os.path.exists(path):
        return None
    try:
        with open(path, 'r', encoding='utf-8') as handle:
            data = json.load(handle)
    except Exception:
        return None
    if not isinstance(data, dict):
        return None
    schema = str(data.get('schema', '')).strip()
    if not schema.startswith('broccoli-webfetch-selection'):
        return None
    raw_pages = data.get('pages')
    if not isinstance(raw_pages, list):
        return None
    pages = []
    for index, page in enumerate(raw_pages):
        normalized = normalize_webfetch_page(page, index)
        if normalized:
            pages.append(normalized)
    if not pages:
        return None
    exported_at = str(data.get('generatedAt', '')).strip() or datetime.datetime.now().isoformat(timespec='seconds')
    return {
        'path': path,
        'name': os.path.basename(path),
        'schema': schema,
        'exported_at': exported_at,
        'count': len(pages),
        'pages': pages,
        'source_path': str(data.get('sourcePath', '')).strip(),
    }


def normalize_webfetch_attachment_record(item: dict) -> dict | None:
    normalized = normalize_attachment_record(item)
    if normalized is None:
        return None
    stored_path = str(normalized.get('stored_path', '')).strip()
    if not stored_path:
        return None
    record = load_webfetch_selection_attachment(stored_path)
    if record is None:
        return None
    return normalized


def collect_webfetch_attachments_from_messages(messages: list[dict]) -> list[dict]:
    collected = []
    seen_paths = set()
    for message in messages or []:
        for attachment in (message.get('attachments') or []):
            normalized = normalize_webfetch_attachment_record(attachment)
            if normalized is None:
                continue
            stored_path = str(normalized.get('stored_path', '')).strip()
            if stored_path in seen_paths:
                continue
            seen_paths.add(stored_path)
            collected.append(normalized)
    return collected


def load_pdf_max_pages() -> int:
    """Return the configured PDF max-pages limit (0 = unlimited)."""
    try:
        store = load_settings_store()
        return int(store['globals'].get('pdf_max_pages', 10))
    except Exception:
        return 10


def sync_profile_to_legacy_files(profile: dict, global_settings: dict) -> None:
    endpoint = normalize_endpoint_value(profile['endpoint'])
    api_key = profile['api_key']
    write_text_file(BasePath + 'api.txt', api_key)
    write_text_file(BasePath + 'api2.txt', api_key)
    write_text_file(BasePath + 'bear.txt', endpoint)
    write_text_file(BasePath + 'third.txt', '0' if is_official_openai_endpoint(endpoint) else '1')
    write_text_file(BasePath + 'which.txt', '0')
    write_text_file(BasePath + 'timeout.txt', profile['timeout'])
    write_text_file(BasePath + 'showref.txt', '1' if profile['show_references'] else '0')
    write_text_file(BasePath + 'history.txt', '1' if profile['remember_history'] else '0')
    write_text_file(BasePath + 'modelnow.txt', profile['model'])
    write_text_file(BasePath + 'wp.txt', '0')
    write_text_file(CUSTOM_PROMPT_PATH, global_settings.get('custom_prompt', ''))
    write_text_file(LANGUAGE_LIST_PATH, global_settings.get('languages', ''))
    write_text_file(MODEL_LIST_PATH, profile['model'] + '\n')
    write_text_file(UI_SHORTCUT_PATH, global_settings.get('ui_shortcut', DEFAULT_UI_SHORTCUT) or DEFAULT_UI_SHORTCUT)


def load_active_settings_profile() -> dict:
    store = load_settings_store()
    active_profile = str(store.get('active_profile', '')).strip()
    for profile in store.get('profiles', []):
        if profile.get('name') == active_profile:
            return profile
    profiles = store.get('profiles', [])
    if profiles:
        return profiles[0]
    return legacy_profile_snapshot()


def load_runtime_openai_client_config() -> tuple[str, str]:
    profile = load_active_settings_profile()
    api_key = str(profile.get('api_key', '')).strip()
    return api_key, profile_runtime_base_url(profile)


def load_language_items() -> list[str]:
    ensure_broccoli_data_dir()
    try:
        raw = Path(LANGUAGE_LIST_PATH).read_text(encoding='utf-8')
        items = [item.strip() for item in raw.splitlines() if item.strip()]
    except Exception:
        items = []
    return items or ['English', '中文', '日本語']


_runtime_translate_target_language = ''


def runtime_translate_target_language() -> str:
    return _runtime_translate_target_language


def remember_runtime_translate_target_language(language: str):
    global _runtime_translate_target_language
    language = str(language or '').strip()
    if language:
        _runtime_translate_target_language = language


def preferred_runtime_translate_target_index(items: list[str]) -> int:
    preferred = runtime_translate_target_language()
    if not preferred:
        return -1
    try:
        return items.index(preferred)
    except ValueError:
        return -1


def build_translation_prompt(prompt_input: str, source_language: str, target_language: str) -> str:
    return (
        'You are a translation engine that can only translate text and cannot interpret it. '
        f'Translate this text from {source_language} to {target_language}. '
        'Don\'t reply any other explanations. Before the translated text starts, write "「「START」」" '
        f'and write "「「END」」" after it ends. Text: {prompt_input}. '
    )


def extract_marked_translation(text: str) -> str:
    content = str(text or '').strip()
    match = re.search(r'「「START」」(?P<body>.*?)「「END」」', content, flags=re.DOTALL)
    if match:
        return match.group('body').strip()
    match = re.search(r'START[」\]）\)]*(?P<body>.*?)「?「?END', content, flags=re.DOTALL | re.IGNORECASE)
    if match:
        return match.group('body').strip()
    return content


def language_alias_key(name: str) -> str:
    text = str(name or '').strip().lower()
    compact = re.sub(r'[\s_\-()（）]+', '', text)
    aliases = {
        'english': {'english', 'en', 'anglais', '英語', '英语', '英文'},
        'chinese': {'chinese', 'zh', '中文', '汉语', '漢語', '简体中文', '繁體中文', 'traditionalchinese', 'simplifiedchinese'},
        'japanese': {'japanese', 'ja', '日本語', '日语', '日文'},
        'korean': {'korean', 'ko', '한국어', '韩语', '韓語', '朝鲜语'},
        'french': {'french', 'fr', 'français', '法语', '法文'},
        'german': {'german', 'de', 'deutsch', '德语', '德文'},
        'spanish': {'spanish', 'es', 'español', '西班牙语', '西语'},
        'italian': {'italian', 'it', 'italiano', '意大利语'},
        'portuguese': {'portuguese', 'pt', 'português', '葡萄牙语'},
        'russian': {'russian', 'ru', 'русский', '俄语', '俄文'},
    }
    for key, values in aliases.items():
        if compact in {re.sub(r'[\s_\-()（）]+', '', value.lower()) for value in values}:
            return key
    return compact


def canonical_language_display(key: str) -> str:
    # review fix (FIX-45): an unknown key used to be shown RAW ('vietnamese',
    # 'latin') — lowercase and out of place next to the user's own spellings
    return {
        'english': 'English',
        'chinese': '中文',
        'japanese': '日本語',
        'korean': '한국어',
        'french': 'Français',
        'german': 'Deutsch',
        'spanish': 'Español',
        'italian': 'Italiano',
        'portuguese': 'Português',
        'russian': 'Русский',
    }.get(str(key or '').strip(), str(key or '').strip().title() or 'English')


def match_configured_language(canonical_key: str, configured_languages: list[str]) -> str:
    for item in configured_languages:
        if language_alias_key(item) == canonical_key:
            return item
    return canonical_language_display(canonical_key)


# ---- FIX-45: ONE definition of "the user's language" -------------------------
# Settings → Languages is an ORDERED list and position IS the preference, so the
# FIRST entry is the user's primary language. Everything that speaks to the user
# in prose — the approval dialogs, the deep-dig answers, the translate target —
# now reads it from here instead of defaulting to English.
def preferred_ui_language() -> str:
    """The first language in Settings → Languages (display spelling)."""
    try:
        items = load_language_items()
        first = str(items[0]).strip() if items else ''
    except Exception:
        first = ''
    return first or 'English'


def preferred_ui_language_key() -> str:
    """The canonical key ('chinese' / 'english' / …) of the primary language."""
    return language_alias_key(preferred_ui_language()) or 'english'


# Static UI chrome for the APPROVAL surfaces. Only the primary language is used;
# anything without a translation falls back to the English source string, so an
# exotic entry in the language list degrades gracefully instead of breaking.
