def _ui_text_language_key() -> str:
    """Map the UI display language (menu bar ▸ Language, ~/.broccoli_lang) onto
    the chrome table's language keys. Resolved ONCE per process — the UI
    language only changes with a restart, exactly like the Qt translator."""
    lang = BROCCOLI_UI_LANGUAGE
    if lang in (None, '', 'system'):
        try:
            lang = QLocale.system().name()
        except Exception:
            lang = 'en'
    lang = str(lang)
    if lang.startswith('zh'):
        return 'chinese'
    if lang.startswith('ja'):
        return 'japanese'
    if lang.startswith('ko'):
        return 'korean'
    return 'english'


BROCCOLI_UI_TEXT_LANGUAGE_KEY = _ui_text_language_key()


def ui_text(key: str, **fmt) -> str:
    """Static approval-dialog CHROME — follows the UI display language.

    User decision 2026-07-24 (supersedes the earlier English lock): the approval
    windows' titles, field labels and Allow/Deny/Approve/Reject buttons follow
    the menu-bar Language setting like the rest of the UI. Model-GENERATED
    content (purpose / expected_result / summary / understanding) still speaks
    the user's PRIMARY language from Settings → Languages via the
    preferred_ui_language() PROMPTS — never through this chrome table.
    Consistency: every caller uses ui_text() for BOTH a button label AND its
    `==` comparison, and BROCCOLI_UI_TEXT_LANGUAGE_KEY is fixed for the process
    lifetime, so both sides always resolve to the same string — no decision can
    fall through to deny. Terminal/editor decisions are bound to
    constants/signals, so their button text is display-only regardless. Entries
    without a translation fall back to the English source text."""
    entry = BROCCOLI_UI_TEXTS.get(str(key), {})
    text = (entry.get(BROCCOLI_UI_TEXT_LANGUAGE_KEY)
            or entry.get('english')
            or str(key))
    if fmt:
        try:
            return text.format(**fmt)
        except Exception:
            return text
    return text


def localize_risk_reason(reason: str) -> str:
    """The command classifier emits stable ENGLISH reason codes (they are matched
    by other code and fed back to the model); only the DISPLAY is localized."""
    text = str(reason or '')
    for prefix, key in (('matches mutating pattern: ', 'reason.mutating'),
                        ('matches dangerous pattern: ', 'reason.dangerous')):
        if text.startswith(prefix):
            return ui_text(key, pattern=text[len(prefix):])
    fixed = {
        'AppleScript may mutate application state': 'reason.applescript',
        'model declared this command as mutating': 'reason.declared_write',
        'model declared this command as dangerous': 'reason.declared_dangerous',
        'model declared unknown risk': 'reason.declared_unknown',
        'empty command': 'reason.empty_command',
    }
    key = fixed.get(text)
    return ui_text(key) if key else text


def detect_selected_text_language(text: str, configured_languages: list[str] | None = None,
                                  strict: bool = False) -> str:
    """Dominant language of a piece of text, spelled the way the user spells it.
    review fix (FIX-45): with strict=True the detector may answer '' = I DON'T
    KNOW. Without it, text with no script signal at all (a table of numbers, code
    punctuation, currency figures) silently comes back as the user's FIRST
    language \u2014 which the screenshot overlay would then assert as the source of a
    capture it never actually read."""
    configured = list(configured_languages or load_language_items())
    sample = str(text or '').strip()
    if not sample:
        return '' if strict else (configured[0] if configured else 'English')
    try:
        from lingua import LanguageDetectorBuilder
        detector = LanguageDetectorBuilder.from_all_languages().build()
        detected = detector.detect_language_of(sample[:8000])
        if detected is not None:
            key = str(getattr(detected, 'name', '') or '').strip().lower()
            if key:
                return match_configured_language(key, configured)
    except Exception:
        pass
    counts = {
        'chinese': len(re.findall(r'[\u4e00-\u9fff]', sample)),
        'japanese': len(re.findall(r'[\u3040-\u30ff]', sample)),
        'korean': len(re.findall(r'[\uac00-\ud7af]', sample)),
        'russian': len(re.findall(r'[\u0400-\u04ff]', sample)),
        'english': len(re.findall(r'[A-Za-z]', sample)),
    }
    key = max(counts, key=counts.get)
    if counts.get(key, 0) <= 0:
        if strict:
            return ''   # no script signal whatsoever \u2014 do not invent one
        key = language_alias_key(configured[0]) if configured else 'english'
    return match_configured_language(key, configured)


def get_profile_from_store_by_name(store: dict, profile_name: str) -> dict | None:
    target = str(profile_name or '').strip()
    if not target:
        return None
    for profile in store.get('profiles', []):
        if profile.get('name') == target:
            return profile
    return None


def browser_use_effective_profile(store: dict) -> dict | None:
    globals_store = store.get('globals', {}) if isinstance(store, dict) else {}
    profile_name = str(globals_store.get('browser_use_profile', '') or '').strip()
    if profile_name:
        profile = get_profile_from_store_by_name(store, profile_name)
        if profile is not None:
            return profile
    return load_active_settings_profile()


def browser_use_profile_runtime_values(profile: dict | None, llm_wrapper: str) -> dict | None:
    """Translate one saved profile into the Browser Use worker's model fields."""
    if not isinstance(profile, dict):
        return None
    api_key = str(profile.get('api_key', '') or '').strip()
    model = str(profile.get('model', '') or '').strip()
    if llm_wrapper == 'openai':
        endpoint = profile_runtime_base_url(profile)
    elif llm_wrapper == 'anthropic':
        endpoint = normalize_endpoint_value(profile.get('endpoint', ''))
    else:
        endpoint = ''
    if not api_key or not model or (llm_wrapper == 'openai' and not endpoint):
        return None
    try:
        timeout = int(profile.get('timeout', 60) or 60)
    except (TypeError, ValueError):
        timeout = 60
    llm_timeout = max(90, timeout)
    return {
        'profile_name': str(profile.get('name', '') or '').strip(),
        'api_key': api_key,
        'endpoint': endpoint,
        'model': model,
        'timeout': timeout,
        'llm_timeout': llm_timeout,
        'step_timeout': llm_timeout + 60,
    }


def browser_use_chrome_executable_exists(path: str) -> bool:
    return bool(str(path or '').strip()) and os.path.exists(str(path).strip())


def computer_use_driver_available(command: str) -> bool:
    # The worker reaches the driver through the CLI (stdio MCP transport), so the
    # CLI executable is the real precondition. CuaDriver.app alone — installed but
    # missing its ~/.local/bin link — cannot run a task; letting it pass here would
    # only defer the same failure into the worker. The caller adds an app-specific
    # hint to the failure text when only the .app is present.
    expanded = os.path.expanduser(str(command or DEFAULT_COMPUTER_USE_DRIVER_COMMAND).strip())
    return bool(os.path.isfile(expanded) and os.access(expanded, os.X_OK))


def _missing_cua_permissions_payload(payload) -> list[str]:
    # cua-driver 0.8.3 payload shape (CLI --json and the check_permissions MCP
    # tool are identical): {"accessibility": bool, "screen_recording": bool, ...}.
    # Only an EXPLICIT false counts as missing — absent/unknown values must not
    # block a task the daemon could still run (it may simply not be up yet).
    if not isinstance(payload, dict):
        return []
    missing = []
    for key, label in (('accessibility', 'Accessibility'), ('screen_recording', 'Screen Recording')):
        if payload.get(key) is False:
            missing.append(label)
    return missing


def computer_use_permissions_missing(command: str) -> list[str]:
    """Best-effort TCC pre-check via `cua-driver permissions status --json`.
    Returns permission names that are EXPLICITLY not granted; [] when everything
    is granted or the state is unknowable (daemon down, parse failure) — the
    worker re-checks authoritatively over MCP once the daemon is running."""
    expanded = os.path.expanduser(str(command or DEFAULT_COMPUTER_USE_DRIVER_COMMAND).strip())
    try:
        probe = subprocess.run(
            [expanded, 'permissions', 'status', '--json'],
            capture_output=True, text=True, timeout=4,
        )
        payload = json.loads(probe.stdout or '{}')
    except Exception:
        return []
    return _missing_cua_permissions_payload(payload)


def browser_use_cdp_available(cdp_url: str, timeout: float = 1.2) -> bool:
    url = str(cdp_url or '').strip().rstrip('/')
    if not url:
        return False
    try:
        response = requests.get(url + '/json/version', timeout=timeout)
        return response.status_code < 400
    except Exception:
        return False


def browser_use_cdp_launch_port(cdp_url: str) -> str:
    parsed = urlparse(str(cdp_url or DEFAULT_BROWSER_USE_CDP_URL).strip())
    if parsed.port:
        return str(parsed.port)
    return '9222'


def browser_use_profile_is_running(user_data_dir: str) -> bool:
    # Chrome 运行期间在 user-data-dir 根目录放置 Singleton* 锁；存在即视为占用。
    base = str(user_data_dir or '').strip()
    if not base:
        return False
    return any(os.path.lexists(os.path.join(base, name)) for name in ('SingletonLock', 'SingletonSocket', 'SingletonCookie'))


def copy_browser_use_login_state(src_user_data_dir: str, dst_user_data_dir: str) -> dict:
    """把主配置档的登录态（cookie 数据库 + 本地存储）复制进并行槽位配置档。

    同一台 Mac 上所有 Chrome 配置档共用钥匙串里的加密密钥，所以 cookie 文件
    可以跨配置档直接复用。尽力而为：源缺失或目标 Chrome 正在运行则跳过（往
    运行中的配置档写文件既不生效也可能损坏），从不抛错。"""
    result = {'copied': [], 'skipped': ''}
    src = str(src_user_data_dir or '').strip()
    dst = str(dst_user_data_dir or '').strip()
    if not src or not dst or not os.path.isdir(os.path.join(src, 'Default')):
        result['skipped'] = 'source profile missing'
        return result
    if browser_use_profile_is_running(dst):
        result['skipped'] = 'target profile is in use'
        return result
    try:
        os.makedirs(os.path.join(dst, 'Default'), exist_ok=True)
        for relative in ('Network/Cookies', 'Network/Cookies-journal', 'Cookies', 'Cookies-journal'):
            source_file = os.path.join(src, 'Default', relative)
            if os.path.isfile(source_file):
                target_file = os.path.join(dst, 'Default', relative)
                os.makedirs(os.path.dirname(target_file), exist_ok=True)
                shutil.copy2(source_file, target_file)
                result['copied'].append(relative)
        for relative in ('Local Storage',):
            source_dir = os.path.join(src, 'Default', relative)
            if os.path.isdir(source_dir):
                target_dir = os.path.join(dst, 'Default', relative)
                shutil.rmtree(target_dir, ignore_errors=True)
                shutil.copytree(source_dir, target_dir, dirs_exist_ok=True)
                result['copied'].append(relative)
    except Exception as exc:
        result['skipped'] = f'copy failed: {exc}'
    return result


# 等调试端口开出的上限。冷启动时长随配置目录大小变化：1.8GB 的托管配置目录
# 在 Chrome 升级后首启实测约 7 秒（2026-10-15），旧的 4 秒上限把正在启动的
# Chrome 判成失败，浏览器步骤直接报"连不上"。端口一通即返回，平时不会多等。
BROWSER_USE_CHROME_LAUNCH_WAIT_SECONDS = 30.0
# 界面线程（设置按钮、🌐 Chrome 菜单）等待时界面不响应，上限单独收紧。
BROWSER_USE_CHROME_LAUNCH_WAIT_SECONDS_GUI = 15.0
# 并行浏览器步骤会在各自线程里同时发现端口不通、各拉一次 Chrome；串行化后
# 后到者先复查端口，直接复用先到者拉起的实例。
_BROWSER_USE_CHROME_LAUNCH_LOCK = threading.Lock()


def launch_browser_use_chrome(chrome_path: str,
                              cdp_url: str,
                              user_data_dir: str,
                              wait_seconds: float = BROWSER_USE_CHROME_LAUNCH_WAIT_SECONDS) -> bool:
    chrome_path = str(chrome_path or '').strip() or DEFAULT_BROWSER_USE_CHROME_EXECUTABLE
    cdp_url = str(cdp_url or '').strip() or DEFAULT_BROWSER_USE_CDP_URL
    user_data_dir = str(user_data_dir or '').strip() or DEFAULT_BROWSER_USE_USER_DATA_DIR
    if not browser_use_chrome_executable_exists(chrome_path):
        return False
    wait_seconds = max(0.5, float(wait_seconds or 0))
    if not _BROWSER_USE_CHROME_LAUNCH_LOCK.acquire(timeout=wait_seconds):
        return browser_use_cdp_available(cdp_url, timeout=0.8)
    try:
        if browser_use_cdp_available(cdp_url, timeout=0.5):
            return True
        port = browser_use_cdp_launch_port(cdp_url)
        os.makedirs(user_data_dir, exist_ok=True)
        chrome_args = [
            f'--remote-debugging-port={port}',
            '--remote-allow-origins=*',
            f'--user-data-dir={user_data_dir}',
            '--new-window',
            'about:blank',
        ]
        try:
            if sys.platform == 'darwin' and chrome_path.endswith('/Contents/MacOS/Google Chrome'):
                command = ['/usr/bin/open', '-na', 'Google Chrome', '--args', *chrome_args]
            else:
                command = [chrome_path, *chrome_args]
            subprocess.Popen(command, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        except Exception:
            return False
        deadline = time.time() + wait_seconds
        while time.time() < deadline:
            if browser_use_cdp_available(cdp_url, timeout=0.5):
                return True
            time.sleep(0.25)
        return browser_use_cdp_available(cdp_url, timeout=0.8)
    finally:
        _BROWSER_USE_CHROME_LAUNCH_LOCK.release()


def launch_browser_use_chrome_with_feedback(parent, raw_settings: dict | None = None) -> bool:
    """Launch the managed Browser Use Chrome from either Settings or Agent UI."""
    if raw_settings is None:
        raw_settings = load_settings_store().get('globals', {})
    settings = normalize_browser_use_settings(raw_settings)
    chrome_path = settings['browser_use_chrome_executable']
    cdp_url = settings['browser_use_cdp_url']
    user_data_dir = settings['browser_use_user_data_dir']
    if not browser_use_chrome_executable_exists(chrome_path):
        show_broccoli_message(
            parent,
            _tr('Google Chrome not found'),
            _tr('Browser Use needs Google Chrome installed. Check the Chrome executable path.'),
        )
        return False
    if browser_use_cdp_available(cdp_url):
        show_broccoli_message(
            parent,
            _tr('Browser Use Chrome'),
            _tr('The fixed Browser Use Chrome instance is already reachable. Open or select the page you want, then run a /browser use task.'),
        )
        return True
    if launch_browser_use_chrome(chrome_path, cdp_url, user_data_dir,
                                 wait_seconds=BROWSER_USE_CHROME_LAUNCH_WAIT_SECONDS_GUI):
        show_broccoli_message(
            parent,
            _tr('Browser Use Chrome launched'),
            _tr('Use this Chrome window to open pages, sign in, and prepare background tabs. When "Open each task in a new Chrome tab/window" is off, Browser Use will continue from this instance.'),
        )
        return True
    show_broccoli_message(
        parent,
        _tr('Browser Use Chrome unavailable'),
        _tr('Broccoli could not launch or connect to the fixed Browser Use Chrome instance. Check the CDP URL port and Chrome profile folder.'),
    )
    return False


def parse_browser_use_slash_command(text: str) -> tuple[bool, str]:
    forced, capability, task = parse_specialized_slash_command(text)
    if forced and capability == BROWSER_USE_CAPABILITY:
        return True, task
    return False, str(text or '').strip()


def parse_specialized_slash_command(text: str) -> tuple[bool, str, str]:
    raw = str(text or '')
    stripped = raw.lstrip()
    lowered = stripped.lower()
    for command, capability, _description in sorted(SPECIALIZED_SLASH_COMMANDS, key=lambda item: len(item[0]), reverse=True):
        command_l = command.lower()
        if lowered == command_l:
            return True, capability, ''
        if lowered.startswith(command_l + ' '):
            return True, capability, stripped[len(command):].strip()
    return False, '', raw.strip()


def match_skill_directive_name(rest: str, skill_names) -> str:
    """`//` 之后那段文本 `rest` 里能匹配到的、最长的一个"已启用 skill 名字"
    （大小写不敏感、要在词边界处结束）。匹配不到就返回 ''——此时这行 `//…`
    当普通文本处理，所以别人粘代码里的 `// 注释` 不会误触发 skill。
    与 `/tool` 命令"最长优先匹配"同一套思路。"""
    low = str(rest or '').lower()
    best = ''
    for name in skill_names or []:
        n = str(name or '').strip()
        if not n:
            continue
        nl = n.lower()
        if (low == nl or low.startswith(nl + ' ') or low.startswith(nl + '\t')) and len(nl) > len(best):
            best = n
    return best


def parse_specialized_slash_segments(text: str, skill_names=None) -> list[dict]:
    """段首斜杠命令的绑定段列表，按出现顺序。

    绑定范围 = 斜杠所在段落：从斜杠命令起，到下一个空行（或下一个斜杠段、
    消息末尾）为止——斜杠任务必须一段内写完，换段后的内容是普通文本，由
    planner 全文语义规划。与输入框指令块高亮（_parse_prompt_directive_blocks）
    的段落边界同语义：高亮显示的范围就是绑定的范围。

    单斜杠 `/tool` 绑定内置能力；双斜杠 `//<已启用 skill 名>` 绑定某个 skill
    （需传入 skill_names 才解析；解析出的段带 skill_name，能力为 'skill'）。"""
    commands = sorted(SPECIALIZED_SLASH_COMMANDS, key=lambda item: len(item[0]), reverse=True)
    segments = []
    cur = None
    for raw_line in str(text or '').splitlines():
        line = raw_line.strip()
        if not line:
            cur = None
            continue
        matched = None          # (capability, task)
        skill_name = ''
        # 双斜杠：`//<skill 名> <任务>` —— 先于单斜杠命令判定。
        if line.startswith('//') and skill_names:
            rest = line[2:]
            name = match_skill_directive_name(rest, skill_names)
            if name:
                skill_name = name
                matched = (SPECIALIZED_SKILL_CAPABILITY, rest[len(name):].strip())
        # 单斜杠内置能力（未被上面识别为 skill 时）。
        if matched is None and line.startswith('/'):
            lowered = line.lower()
            for command, capability, _description in commands:
                command_l = command.lower()
                if lowered == command_l or lowered.startswith(command_l + ' '):
                    matched = (capability, line[len(command):].strip())
                    break
        if matched is not None:
            cur = {'capability': matched[0], 'task_parts': [matched[1]] if matched[1] else []}
            if skill_name:
                cur['skill_name'] = skill_name
            segments.append(cur)
        elif cur is not None:
            cur['task_parts'].append(line)
    for segment in segments:
        segment['task'] = '\n'.join(segment.pop('task_parts')).strip()
    return segments


def apply_slash_bindings_to_plan(plan: dict, slash_segments: list[dict]) -> dict:
    """斜杠绑定的计划兜底：每个绑定段必须在计划里有一个对应能力的步骤。

    planner 漏排时按绑定段的出现顺序补在计划末尾（用户把斜杠任务写在
    消息后段，追加保持任务顺序；不再插到最前）。goal 取绑定段原文。"""
    if not isinstance(plan, dict) or not slash_segments:
        return plan

    def _dedup_key(capability, skill_name):
        # skill 按 (能力, skill_name) 配对去重：`//A` 和 `//B` 是两条独立绑定，
        # 不能被规划器排的某一个 skill 步骤一起顶掉。
        if capability == SPECIALIZED_SKILL_CAPABILITY:
            return (capability, str(skill_name or '').strip().lower())
        return capability

    remaining = {}
    for step in plan.get('steps', []):
        capability = str(step.get('capability', '') or '')
        key = _dedup_key(capability, step.get('skill_name', ''))
        remaining[key] = remaining.get(key, 0) + 1
    bound_any = False
    for segment in slash_segments:
        capability = str(segment.get('capability', '') or '')
        task = str(segment.get('task', '') or '').strip()
        if not capability or not task:
            continue
        skill_name = str(segment.get('skill_name', '') or '').strip()
        if capability == SPECIALIZED_SKILL_CAPABILITY and not skill_name:
            continue   # 未解析出名字的 `//` 段不强制排一个无名 skill 步骤
        bound_any = True
        key = _dedup_key(capability, skill_name)
        if remaining.get(key, 0) > 0:
            remaining[key] -= 1
            continue
        step = {
            'capability': capability,
            'goal': task,
            'depends_on_previous': False,
            'extract': f'{specialized_capability_label(capability)} result',
            'context_policy': 'fresh',
            'context_query': task,
        }
        if skill_name:
            step['skill_name'] = skill_name
        plan.setdefault('steps', []).append(step)
    if bound_any:
        plan['finalize_with_default_chat'] = True
        if not plan.get('finalize_focus'):
            bound_labels = ', '.join(
                specialized_capability_label(str(segment.get('capability', '') or ''))
                for segment in slash_segments
                if str(segment.get('task', '') or '').strip()
            )
            plan['finalize_focus'] = f'summarize the {bound_labels} result and answer the user'
        if not plan.get('reason'):
            plan['reason'] = 'The user explicitly bound sub-tasks to capabilities via slash segments.'
    return plan


def load_embedding_settings_profile() -> dict | None:
    store = load_settings_store()
    profile_name = str(store.get('globals', {}).get('embedding_profile', '')).strip()
    if not profile_name:
        return None
    return get_profile_from_store_by_name(store, profile_name)


def profile_runtime_base_url(profile: dict) -> str:
    endpoint = normalize_endpoint_value(str(profile.get('endpoint', DEFAULT_ENDPOINT)))
    if bool(profile.get('append_v1', True)):
        return endpoint + '/v1'
    return endpoint


def load_embedding_runtime_config() -> dict | None:
    profile = load_embedding_settings_profile()
    if profile is None:
        return None
    api_key = str(profile.get('api_key', '')).strip()
    model = str(profile.get('model', '')).strip()
    if not api_key or not model:
        return None
    try:
        timeout = int(profile.get('timeout', 60) or 60)
    except (TypeError, ValueError):
        timeout = 60
    return {
        'profile': profile,
        'api_key': api_key,
        'endpoint': profile_runtime_base_url(profile),
        'model': model,
        'timeout': timeout,
    }


def probe_embedding_capability(profile: dict | None, force: bool = False) -> tuple[bool, str]:
    if profile is None:
        return False, _tr('No embedding profile selected.')
    endpoint = profile_runtime_base_url(profile)
    api_key = str(profile.get('api_key', '')).strip()
    model = str(profile.get('model', '')).strip()
    timeout = max(5, min(20, int(profile.get('timeout', 60) or 60)))
    if not api_key or not model:
        return False, _tr('Selected profile is missing API key or model.')

    cache_key = (endpoint, model, api_key[:12])
    if not force and cache_key in EMBEDDING_CAPABILITY_CACHE:
        return EMBEDDING_CAPABILITY_CACHE[cache_key]

    try:
        client = create_openai_client(api_key, endpoint, timeout)
        response = client.embeddings.create(model=model, input='Broccoli embedding capability probe')
        ok = bool(getattr(response, 'data', None) and getattr(response.data[0], 'embedding', None))
        result = (ok, _tr('Embedding endpoint is available.') if ok else _tr('Embedding request returned no vector.'))
    except Exception as exc:
        result = (False, _tr('Embedding unavailable: {error}').format(error=str(exc)))

    EMBEDDING_CAPABILITY_CACHE[cache_key] = result
    return result


def serialize_shortcut(flags: int, key_token: str) -> str:
    parts = []
    for modifier in ('ctrl', 'alt', 'shift', 'cmd'):
        if flags & MODIFIER_FLAG_BITS[modifier]:
            parts.append(f'<{modifier}>')
    parts.append(key_token)
    return '+'.join(parts)


def normalize_shortcut_text(shortcut_text: str, default_shortcut: str) -> str:
    text = shortcut_text.strip().lower() if shortcut_text.strip() else default_shortcut
    tokens = [token.strip() for token in text.split('+') if token.strip()]
    flags = 0
    key_token = None

    for token in tokens:
        if token in MODIFIER_ALIASES:
            flags |= MODIFIER_FLAG_BITS[MODIFIER_ALIASES[token]]
            continue

        normalized_token = KEY_TOKEN_ALIASES.get(token, token)
        if len(normalized_token) == 1 and normalized_token in ANSI_KEYCODES:
            key_token = normalized_token
            continue
        if normalized_token in SPECIAL_KEYCODES:
            key_token = normalized_token
            continue
        raise ValueError(_tr('Unsupported shortcut token: {token}').format(token=token))

    if key_token is None:
        raise ValueError(_tr('Shortcut must contain a non-modifier key.'))
    if flags == 0:
        raise ValueError(_tr('Shortcut must include at least one modifier key.'))

    return serialize_shortcut(flags, key_token)


def normalize_optional_shortcut_text(shortcut_text: str) -> str:
    if not str(shortcut_text or '').strip():
        return ''
    return normalize_shortcut_text(str(shortcut_text), str(shortcut_text))


def safe_normalize_optional_shortcut_text(shortcut_text: str) -> str:
    try:
        return normalize_optional_shortcut_text(shortcut_text)
    except ValueError:
        return ''


def build_shortcut_spec(shortcut_text: str, default_shortcut: str) -> dict:
    normalized = normalize_shortcut_text(shortcut_text, default_shortcut)
    tokens = normalized.split('+')
    key_token = tokens[-1]
    flags = 0
    for token in tokens[:-1]:
        flags |= MODIFIER_FLAG_BITS[token.strip('<>')]
    if key_token in ANSI_KEYCODES:
        keycode = ANSI_KEYCODES[key_token]
    else:
        keycode = SPECIAL_KEYCODES[key_token]
    return {
        'normalized': normalized,
        'flags': flags,
        'keycode': keycode,
    }


MARKER_BLOCK_RE = re.compile(r'「「START」」([\s\S]*?)「「END」」')
BROCCOLI_OUTPUT_BLOCK_RE = re.compile(r'<broccoli-output\b([^>]*)>([\s\S]*?)</broccoli-output>', re.IGNORECASE)
BROCCOLI_OUTPUT_ATTR_RE = re.compile(r'([a-zA-Z_][\w-]*)\s*=\s*("([^"]*)"|\'([^\']*)\')')

OUTPUT_CAPTURE_INSTRUCTIONS = """
If this answer produces one final reusable deliverable for the user, append exactly one machine-readable block after the human-readable answer.
Use this exact format:
<broccoli-output type="code|text" title="Short title" filename="optional-name.ext">
final deliverable only
</broccoli-output>
Use type="code" for source code or scripts, and type="text" for a rewritten/transformed final text. Do not put alternatives in this block. If you discuss multiple options in the answer, still choose only the final recommended deliverable for this block. Do not include this block when there is no reusable final deliverable.

If you need to edit a file that is currently open in the Broccoli Editor window, do not assume blind write access. Instead append exactly one editor permission block:
<broccoli-output type="editor_edit">
{"type":"editor_edit","file":"open-file-name.py","mode":"line_replace|find_replace|full","new_content":"entire new file text for full mode","edits":[{"start":40,"end":52,"replace":"new lines for line_replace"}],"summary":"short edit summary","understanding":"one paragraph explaining the affected editor objects","entries":[{"code_name":"symbol","category":"Function","natural_name":"natural name","description":"short description"}],"flow_revision":null}
</broccoli-output>
The file must be one of the open editor files. Choosing a mode: prefer "line_replace" — from the editor Outline pick a 1-based inclusive line range and give its edits as [{"start","end","replace"}] (this never fails on non-unique matches; first read the current text of that range with the broccoli_editor_read tool so your replacement is correct). Use "find_replace" ([{"find","replace"}]) only for a short snippet you have confirmed is unique in the CURRENT text. Use "full" (new_content = the whole file) only for a genuine whole-file rewrite. Never re-read or dump the whole file; read only the range you are changing. Include entries for any natural-name mappings the edit introduces or relies on that are not already confirmed. A confirmed natural name can only be renamed through this permission block; the user decides in the popup.
When the editor context lists "Flows for the edit target" for the file you are editing, you MUST fill flow_revision with the REVISED flow (unless the edit genuinely does not change the flow): {"flow_id":"<the listed flow id>","title":"...","nodes":[{"id":"n1","desc":"...","code_ref":{"symbol":"...","lines":[a,b]}}],"edges":[["n1","n2"]]} — REUSE the listed node ids for unchanged steps so the permission popup can color added/removed/changed steps. flow_revision must be a JSON object, NOT a string. Only keep it null when no flow is listed or the edit truly leaves the flow unchanged.
""".strip()


def normalize_conversation_text(text: str) -> str:
    normalized = text.replace('\r\n', '\n').replace('\r', '\n')
    normalized = re.sub(r'(?m)^([ \t]*)- A:\s*\n+', r'\1- A: ', normalized)
    normalized = re.sub(r'(?m)^([ \t]*)- Q:\s*\n+', r'\1- Q: ', normalized)
    normalized = re.sub(r'(?m)^[ \t]+(?=- [AQ]: )', '', normalized)
    normalized = re.sub(r'(?m)(?:^[ \t]*---[ \t]*\n?){2,}', '---\n', normalized)
    normalized = re.sub(r'(?m)^[ \t]*---[ \t]*\n*(?=- Q: )', '---\n\n', normalized)
    normalized = normalized.rstrip()
    return normalized


def ensure_message_separator(text: str) -> str:
    stripped = text.rstrip()
    if not stripped:
        return ''
    return stripped + '\n\n---\n\n'


def sanitize_custom_prompt_name(name: str, fallback: str = 'Prompt') -> str:
    cleaned = str(name or '').replace('<|', ' ').replace('|><|', ' ').replace('|>', ' ').replace('---', ' ')
    cleaned = re.sub(r'\s+', ' ', cleaned).strip()
    return cleaned or fallback


def parse_custom_prompt_storage(raw_text: str) -> list[dict]:
    records = []
    for index, block in enumerate(str(raw_text or '').split('---'), start=1):
        piece = block.strip()
        if not piece:
            continue
        if '|><|' in piece:
            name_part, body_part = piece.split('|><|', 1)
            name = sanitize_custom_prompt_name(name_part.replace('<|', '').replace('|>', ''), f'Prompt {index}')
            body = body_part
            if body.startswith('<|'):
                body = body[2:]
            if body.endswith('|>'):
                body = body[:-2]
            body = body.strip('\n')
        else:
            name = f'Prompt {index}'
            body = piece
        records.append({'name': name, 'body': body})
    return records


def serialize_custom_prompt_storage(records: list[dict]) -> str:
    blocks = []
    for index, record in enumerate(records or [], start=1):
        if not isinstance(record, dict):
            continue
        name = sanitize_custom_prompt_name(record.get('name', ''), f'Prompt {index}')
        body = str(record.get('body', '') or '').replace('\r\n', '\n').replace('\r', '\n').strip('\n')
        if not name and not body:
            continue
        blocks.append(f'<|{name}|><|{body}|>')
    return '\n---\n'.join(blocks)


def load_custom_prompt_records() -> list[dict]:
    return parse_custom_prompt_storage(read_text_file(CUSTOM_PROMPT_PATH, ''))


def load_custom_prompt_items() -> list[tuple[str, str]]:
    items = []
    for index, record in enumerate(load_custom_prompt_records(), start=1):
        if not isinstance(record, dict):
            continue
        title = sanitize_custom_prompt_name(record.get('name', ''), f'Prompt {index}')
        body = str(record.get('body', '') or '')
        if title or body:
            items.append((title or _tr('Customized prompt'), body))
    return items


def sanitize_skill_name(name: str, fallback: str = 'Skill') -> str:
    cleaned = str(name or '').replace('\n', ' ').replace('\r', ' ').replace('---', ' ')
    cleaned = re.sub(r'\s+', ' ', cleaned).strip()
    return cleaned or fallback


def parse_skill_frontmatter(raw_text: str) -> dict:
    raw = str(raw_text or '').replace('\r\n', '\n').replace('\r', '\n').strip('\ufeff')
    result = {
        'name': '',
        'description': '',
        'body': raw,
        'raw_text': raw,
        'has_frontmatter': False,
    }
    if not raw.lstrip().startswith('---'):
        return result
    stripped = raw.lstrip()
    lines = stripped.split('\n')
    if not lines or lines[0].strip() != '---':
        return result
    end_index = None
    for index in range(1, len(lines)):
        if lines[index].strip() == '---':
            end_index = index
            break
    if end_index is None:
        return result
    meta_lines = lines[1:end_index]
    body = '\n'.join(lines[end_index + 1:]).strip('\n')
    meta = {}
    current_key = ''
    for line in meta_lines:
        if re.match(r'^\s+', line) and current_key:
            meta[current_key] = (meta.get(current_key, '') + ' ' + line.strip()).strip()
            continue
        if ':' not in line:
            current_key = ''
            continue
        key, value = line.split(':', 1)
        key = key.strip().lower()
        if key in {'name', 'description'}:
            meta[key] = value.strip().strip('"').strip("'")
            current_key = key
        else:
            current_key = ''
    result.update(
        {
            'name': sanitize_skill_name(meta.get('name', ''), ''),
            'description': str(meta.get('description', '') or '').strip(),
            'body': body,
            'has_frontmatter': True,
        }
    )
    return result


def normalize_skill_record(record, index: int = 1) -> dict | None:
    if isinstance(record, str):
        raw = record
        enabled = True
    elif isinstance(record, dict):
        raw = str(record.get('raw_text', record.get('content', record.get('body', ''))) or '')
        enabled = bool(record.get('enabled', True))
    else:
        return None
    raw = raw.replace('\r\n', '\n').replace('\r', '\n').strip('\n')
    if not raw:
        raw = DEFAULT_SKILL_TEMPLATE.replace('new-skill', f'new-skill-{index}', 1)
    parsed = parse_skill_frontmatter(raw)
    raw_name = sanitize_skill_name(parsed.get('name', ''), '')
    name = sanitize_skill_name(raw_name, f'Skill {index}')
    description = str(parsed.get('description', '') or '').strip()
    return {
        'name': name,
        'frontmatter_name': raw_name,
        'description': description,
        'body': str(parsed.get('body', '') or ''),
        'raw_text': raw,
        'enabled': enabled,
        'has_frontmatter': bool(parsed.get('has_frontmatter', False)),
    }


def normalize_skill_records(records) -> list[dict]:
    normalized = []
    if isinstance(records, str):
        try:
            decoded = json.loads(records)
            records = decoded if isinstance(decoded, list) else []
        except Exception:
            records = []
    for index, record in enumerate(records or [], start=1):
        normalized_record = normalize_skill_record(record, index)
        if normalized_record is not None:
            normalized.append(normalized_record)
    return normalized


def serialize_skill_records(records, *, validate: bool = False) -> list[dict]:
    serialized = []
    seen_names = set()
    for index, record in enumerate(records or [], start=1):
        normalized = normalize_skill_record(record, index)
        if normalized is None:
            continue
        name = sanitize_skill_name(normalized.get('name', ''), f'Skill {index}')
        description = str(normalized.get('description', '') or '').strip()
        if validate:
            if not normalized.get('has_frontmatter'):
                raise ValueError(_tr('Skill "{name}" must start with frontmatter delimited by ---.').format(name=name))
            if not normalized.get('frontmatter_name'):
                raise ValueError(_tr('Skill {index} is missing name.').format(index=index))
            if not description:
                raise ValueError(_tr('Skill "{name}" is missing description.').format(name=name))
            lowered = name.lower()
            if lowered in seen_names:
                raise ValueError(_tr('Duplicate skill name: {name}').format(name=name))
            seen_names.add(lowered)
        serialized.append(
            {
                'raw_text': str(normalized.get('raw_text', '') or '').strip('\n'),
                'enabled': bool(normalized.get('enabled', True)),
            }
        )
    return serialized


def load_skill_records_from_store(store: dict | None = None, *, enabled_only: bool = False) -> list[dict]:
    if store is None:
        store = load_settings_store()
    globals_store = store.get('globals', {}) if isinstance(store, dict) else {}
    records = normalize_skill_records(globals_store.get('skills', []))
    if enabled_only:
        records = [record for record in records if record.get('enabled', True)]
    return records


def skill_catalog_text(skills: list[dict]) -> str:
    lines = []
    for record in skills or []:
        name = sanitize_skill_name(record.get('name', ''), '')
        description = str(record.get('description', '') or '').strip()
        if not name or not description:
            continue
        lines.append(f'- {name}: {description}')
    text = '\n'.join(lines)
    if len(text) > SKILL_CATALOG_MAX_CHARS:
        text = text[:SKILL_CATALOG_MAX_CHARS].rstrip() + '\n[Skill catalog truncated.]'
    return text


def find_skill_record(skills: list[dict], name: str) -> dict | None:
    target = str(name or '').strip().lower()
    if not target:
        return None
    for record in skills or []:
        if str(record.get('name', '') or '').strip().lower() == target:
            return record
    return None


def skill_step_label(step: dict) -> str:
    if str(step.get('capability', '') or '').strip() == SPECIALIZED_SKILL_CAPABILITY:
        skill_name = str(step.get('skill_name', '') or '').strip()
        return f'skill:{skill_name or "unnamed"}'
    if str(step.get('capability', '') or '').strip() == BROWSER_USE_CAPABILITY:
        return 'browser_use'
    return str(step.get('capability', '') or '').strip()


def extract_code_candidates(text: str) -> list[dict]:
    content = str(text or '')
    candidates = []
    for match in re.finditer(r'```([^\n`]*)\n(.*?)```', content, re.DOTALL | re.IGNORECASE):
        language = normalize_code_runner_language(match.group(1).strip().lower(), '')
        code = match.group(2).strip()
        if not code:
            continue
        if language in CODE_EXECUTION_IGNORE_LANGUAGES:
            continue
        if language:
            candidates.append({'language': language, 'code': code, 'explicit': True})
        elif re.search(r'\b(print|len|import|from|def|for|while|if)\b', code):
            candidates.append({'language': 'python', 'code': code, 'explicit': False})
        elif re.search(r'\b(console\.log|const|let|var|function)\b', code):
            candidates.append({'language': 'node', 'code': code, 'explicit': False})
    if candidates:
        return candidates

    lines = content.replace('\r\n', '\n').replace('\r', '\n').split('\n')
    code_line_re = re.compile(
        r'^\s*(?:'
        r'import\s+\w+|from\s+\w+\s+import\s+|'
        r'[A-Za-z_]\w*\s*=|'
        r'print\s*\(|'
        r'for\s+.+:|while\s+.+:|if\s+.+:|elif\s+.+:|else:|'
        r'def\s+\w+\s*\(|class\s+\w+|#)'
    )
    current = []
    for line in lines + ['']:
        stripped = line.strip()
        if stripped and code_line_re.match(line):
            current.append(line)
            continue
        if stripped == '' and current:
            current.append(line)
            continue
        candidate = '\n'.join(current).strip()
        if candidate and 'print' in candidate and len(candidate.splitlines()) >= 2:
            candidates.append({'language': 'python', 'code': candidate, 'explicit': False})
        current = []
    return candidates


def _limit_code_execution_text(text: str, limit: int = CODE_EXECUTION_MAX_OUTPUT_CHARS) -> str:
    content = str(text or '')
    if len(content) <= limit:
        return content
    return content[:limit].rstrip() + '\n[Code execution output truncated.]'


def run_code_in_worker_thread(language: str,
                              code: str,
                              *,
                              store: dict | None = None,
                              timeout: int | None = None) -> dict:
    if store is None:
        store = load_settings_store()
    globals_store = store.get('globals', {}) if isinstance(store, dict) else {}
    if not bool(globals_store.get('code_execution_enabled', True)):
        return {
            'ok': False,
            'skipped': True,
            'language': normalize_code_runner_language(language, ''),
            'returncode': None,
            'stdout': '',
            'stderr': 'Code execution is disabled in Settings.',
            'timed_out': False,
            'supported_languages': [],
        }
    lang = normalize_code_runner_language(language, '')
    source = str(code or '').strip()
    if not source:
        return {'ok': False, 'skipped': False, 'language': lang, 'returncode': None, 'stdout': '', 'stderr': 'No code was provided.', 'timed_out': False}
    if len(source) > CODE_EXECUTION_MAX_CODE_CHARS:
        return {
            'ok': False,
            'skipped': False,
            'language': lang,
            'returncode': None,
            'stdout': '',
            'stderr': f'Code is too long to execute safely ({len(source)} chars).',
            'timed_out': False,
        }

    runners = load_code_runner_records_from_store(store, enabled_only=True)
    runner = None
    for record in runners:
        if normalize_code_runner_language(record.get('language', ''), '') == lang:
            runner = record
            break
    supported = supported_code_runner_languages(store)
    if runner is None:
        return {
            'ok': False,
            'skipped': True,
            'language': lang,
            'returncode': None,
            'stdout': '',
            'stderr': (
                f'Code execution skipped: language "{lang or "unknown"}" is not configured. '
                + (f'Supported executable languages: {", ".join(supported)}.' if supported else 'No executable languages are available.')
            ),
            'timed_out': False,
            'supported_languages': supported,
        }
    argv = _build_runner_argv(str(runner.get('command', '') or ''), str(runner.get('args', '') or ''), source)
    if not argv:
        return {
            'ok': False,
            'skipped': True,
            'language': lang,
            'returncode': None,
            'stdout': '',
            'stderr': f'Code execution skipped: runner for "{lang}" has no valid executable command.',
            'timed_out': False,
            'supported_languages': supported,
        }
    run_timeout = normalize_code_execution_timeout(timeout or globals_store.get('code_execution_timeout', CODE_EXECUTION_DEFAULT_TIMEOUT_SECONDS))
    result_queue = queue.Queue(maxsize=1)

    def worker_main():
        try:
            completed = subprocess.run(
                argv,
                cwd='/tmp',
                capture_output=True,
                text=True,
                timeout=run_timeout,
            )
            result_queue.put(
                {
                    'ok': completed.returncode == 0,
                    'skipped': False,
                    'language': lang,
                    'returncode': completed.returncode,
                    'stdout': _limit_code_execution_text(completed.stdout),
                    'stderr': _limit_code_execution_text(completed.stderr),
                    'timed_out': False,
                    'supported_languages': supported,
                }
            )
        except subprocess.TimeoutExpired as exc:
            result_queue.put(
                {
                    'ok': False,
                    'skipped': False,
                    'language': lang,
                    'returncode': None,
                    'stdout': _limit_code_execution_text(getattr(exc, 'stdout', '') or ''),
                    'stderr': 'Code execution timed out.',
                    'timed_out': True,
                    'supported_languages': supported,
                }
            )
        except Exception as exc:
            result_queue.put(
                {
                    'ok': False,
                    'skipped': False,
                    'language': lang,
                    'returncode': None,
                    'stdout': '',
                    'stderr': str(exc),
                    'timed_out': False,
                    'supported_languages': supported,
                }
            )

    worker = threading.Thread(target=worker_main, daemon=True)
    worker.start()
    worker.join(max(2, run_timeout + 2))
    if worker.is_alive():
        return {'ok': False, 'skipped': False, 'language': lang, 'returncode': None, 'stdout': '', 'stderr': 'Code runner worker thread timed out.', 'timed_out': True, 'supported_languages': supported}
    try:
        return result_queue.get_nowait()
    except queue.Empty:
        return {'ok': False, 'skipped': False, 'language': lang, 'returncode': None, 'stdout': '', 'stderr': 'Code runner returned no result.', 'timed_out': False, 'supported_languages': supported}


def format_code_execution_feedback(executions: list[dict]) -> str:
    parts = [
        'The app handled the code block below through its configured code runners.',
        'Use stdout/stderr here as the source of truth. If your previous answer claimed different computed values, correct them.',
        'If execution was skipped because the language is unsupported, rewrite equivalent code in the first supported executable language and return one fenced code block.',
        'If the task still needs deterministic verification after revising text, return another fenced code block in a supported language.',
    ]
    for index, execution in enumerate(executions, start=1):
        code = str(execution.get('code', '') or '').strip()
        language = normalize_code_runner_language(execution.get('language', '') or (execution.get('result') or {}).get('language', ''), 'text')
        result = execution.get('result') or {}
        parts.append(
            f'\nExecution {index} language: {language}\n'
            f'Code:\n```{language}\n{code}\n```\n'
            f'Return code: {result.get("returncode")}\n'
            f'Skipped: {bool(result.get("skipped", False))}\n'
            f'Timed out: {bool(result.get("timed_out", False))}\n'
            f'Supported executable languages: {", ".join(result.get("supported_languages", []) or []) or "(none)"}\n'
            f'STDOUT:\n{str(result.get("stdout", "") or "").strip() or "(empty)"}\n'
            f'STDERR:\n{str(result.get("stderr", "") or "").strip() or "(empty)"}'
        )
    return '\n'.join(parts)


def build_question_prefix(existing_output: str, question_display: str) -> str:
    history = normalize_conversation_text(existing_output).rstrip()
    history = re.sub(r'(?:\n\s*---\s*)+\Z', '', history)
    if history:
        history = history + '\n\n---\n\n'
    return history + '- Q: ' + question_display + '\n\n- A: '


def normalize_attachment_record(item: dict) -> dict | None:
    if not isinstance(item, dict):
        return None
    name = str(item.get('name', '')).strip()
    stored_path = str(item.get('stored_path', '')).strip()
    if not name and not stored_path:
        return None
    normalized = {
        'name': name or os.path.basename(stored_path) or 'Attachment',
        'kind': str(item.get('kind', '')).strip() or 'file',
        'send_mode': str(item.get('send_mode', '')).strip() or 'file_direct',
        'use_embedding': bool(item.get('use_embedding', False)),
    }
    for key in ('image_based', 'via_ocr'):
        if bool(item.get(key, False)):
            normalized[key] = True
    for key in ('original_path', 'stored_path', 'stored_rel_path', 'source_path'):
        value = str(item.get(key, '')).strip()
        if value:
            normalized[key] = value
    extracted_text = str(item.get('extracted_text', ''))
    if extracted_text:
        normalized['extracted_text'] = extracted_text
    retrieval_chunks = []
    if isinstance(item.get('retrieval_chunks'), list):
        for chunk in item['retrieval_chunks']:
            if not isinstance(chunk, dict):
                continue
            text = str(chunk.get('text', '')).strip()
            if not text:
                continue
            retrieval_chunks.append(
                {
                    'id': str(chunk.get('id', '')).strip() or f"att-{abs(hash(text))}",
                    'text': text,
                    'display_text': str(chunk.get('display_text', '')).strip() or text,
                    'name': str(chunk.get('name', normalized['name'])).strip() or normalized['name'],
                }
            )
    if retrieval_chunks:
        normalized['retrieval_chunks'] = retrieval_chunks
    return normalized


def attachment_markdown_link(attachment: dict) -> str:
    name = str(attachment.get('name', 'Attachment')).replace(']', '\\]')
    stored_path = str(attachment.get('stored_path', '')).strip()
    if stored_path:
        try:
            uri = Path(stored_path).as_uri()
            return f'[{name}]({uri})'
        except Exception:
            pass
    return name


def attachment_file_uri(attachment: dict) -> str:
    stored_path = str(attachment.get('stored_path', '')).strip()
    if not stored_path:
        return ''
    try:
        return Path(stored_path).as_uri()
    except Exception:
        return ''


def attachment_markdown_block(message: dict) -> str:
    attachments = message.get('attachments') or []
    if not attachments:
        return ''
    lines = ['**Attachments**']
    for attachment in attachments:
        marker = ' [retrieval]' if attachment.get('use_embedding') else ''
        lines.append(f"- {attachment_markdown_link(attachment)}{marker}")
    return '\n'.join(lines)


def attachment_plaintext_block(message: dict,
                               header: str = 'Attachments:',
                               retrieval_label: str = 'retrieval') -> str:
    # header / retrieval_label are DISPLAY overrides (structured-transfer editor);
    # the defaults stay English because this text also feeds memory Q/A + model context.
    attachments = message.get('attachments') or []
    if not attachments:
        return ''
    lines = [header]
    for attachment in attachments:
        name = str(attachment.get('name', 'Attachment'))
        stored_path = str(attachment.get('stored_path', '')).strip()
        suffix = f' [{retrieval_label}]' if attachment.get('use_embedding') else ''
        if stored_path:
            lines.append(f'- {name}{suffix} ({stored_path})')
        else:
            lines.append(f'- {name}{suffix}')
    return '\n'.join(lines)


def _attachment_origin_label(message: dict) -> str:
    # A short tag for WHICH user message an attachment was attached to, so the model can tell
    # multiple attachments apart instead of conflating them.
    origin = str((message or {}).get('content', '') or '').strip().replace('\n', ' ')
    if len(origin) > 60:
        origin = origin[:60].rstrip() + '…'
    return origin


def collect_conversation_attachment_texts(history_messages: list, current_records: list) -> list:
    """Every conversation attachment's stored parsed text, in first-appearance order,
    deduped by the stored file. The text was extracted ONCE when the file was added
    (persist_conversation_attachments) and saved as `extracted_text`; this only READS it,
    never re-parses. Retrieval-mode (use_embedding) attachments are skipped -- those are
    served by the separate retrieval context. Returns a list of (name, text, origin)."""
    seen = set()
    out = []

    def consider(att, origin):
        if not isinstance(att, dict) or att.get('use_embedding'):
            return
        text = str(att.get('extracted_text', '') or '').strip()
        if not text:
            return
        key = str(att.get('stored_path') or att.get('stored_rel_path') or att.get('name') or '').strip()
        if not key or key in seen:
            return
        seen.add(key)
        out.append((str(att.get('name', 'Attachment') or 'Attachment'), text, origin))

    for att in (current_records or []):
        consider(att, '(this turn)')
    for message in (history_messages or []):
        if isinstance(message, dict) and message.get('role') == 'user':
            origin = _attachment_origin_label(message)
            for att in (message.get('attachments') or []):
                consider(att, origin)
    return out


def build_conversation_attachment_carryover_block(history_messages: list, current_records: list) -> str:
    """A single text block with the full parsed text of every (non-retrieval) attachment
    in the conversation, so the model can reference a file in ANY later turn -- not only the
    turn it was added. Each file is tagged with the message it was attached to so the model
    does not confuse different files. Empty string when there is nothing to carry."""
    items = collect_conversation_attachment_texts(history_messages, current_records)
    if not items:
        return ''
    parts = [
        'Attached file content:',
        'The user attached one or more files in this conversation; their full extracted/OCR '
        'text is included below (each parsed once when added). This IS the content of those '
        'files. When the user says "this file / this document / this PDF / this image / this '
        'poster" (or similar), they mean these attached files and the text below is their '
        'content -- answer directly from it. Do NOT say no file was provided, do NOT ask the '
        'user for a file path or filename, and do NOT use any tool (terminal command, file '
        'search, open/read file, etc.) to locate, open, or read these files -- they are already '
        'provided here in full. Each file is tagged with the user message it was attached to; '
        'use the tag to tell files apart and do not mix them up:'
    ]
    for name, text, origin in items:
        if origin == '(this turn)':
            heading = f'[Current turn attachment: {name}]'
        elif origin:
            heading = f'[Earlier attachment: {name} | attached with message: "{origin}"]'
        else:
            heading = f'[Earlier attachment: {name}]'
        parts.append(f'{heading}\n{text}')
    return '\n\n'.join(parts)


# Re-attaching an image-only attachment (poster/screenshot/scanned PDF/image) on demand:
# such files have no parsed text, so the text carry above cannot cover them. When a later
# turn refers to one, we re-encode it from its stored copy and inject it as image(s) for that
# turn only. Render once per file (a PDF -> per-page images is expensive) and reuse.
_CARRY_ATTACHMENT_RENDER_CACHE: dict = {}


def render_stored_attachment_for_injection(stored_path: str):
    key = str(stored_path or '').strip()
    if not key:
        return None
    if key in _CARRY_ATTACHMENT_RENDER_CACHE:
        return _CARRY_ATTACHMENT_RENDER_CACHE[key]
    encoded = None
    try:
        if os.path.exists(key):
            encoded = _encode_attachment_file(key)
    except Exception:
        encoded = None
    _CARRY_ATTACHMENT_RENDER_CACHE[key] = encoded
    return encoded


def conversation_visual_attachments(history_messages: list) -> list:
    """Conversation attachments that are image-based (an image/screenshot, or a PDF with no
    text layer) and so can be re-sent as page image(s) on demand when you need to SEE them --
    even though their OCR'd text is already carried as text. First-appearance order, deduped
    by stored_path. Skips retrieval-mode ones. (The no-text fallback also covers attachments
    saved before add-time OCR existed.)"""
    seen = set()
    out = []
    for message in (history_messages or []):
        if not isinstance(message, dict) or message.get('role') != 'user':
            continue
        for att in (message.get('attachments') or []):
            if not isinstance(att, dict) or att.get('use_embedding'):
                continue
            has_text = bool(str(att.get('extracted_text', '') or '').strip())
            send_mode = str(att.get('send_mode', '') or '').strip().lower()
            is_visual = bool(att.get('image_based')) or (
                send_mode == 'image_direct'
            ) or (
                not has_text and str(att.get('kind', '')).lower() in ('image', 'pdf')
            )
            if not is_visual:
                continue
            stored = str(att.get('stored_path') or '').strip()
            if not stored or stored in seen:
                continue
            seen.add(stored)
            out.append(att)
    return out


_ATTACHMENT_REFERENCE_DOC_WORDS = (
    '海报', '图片', '截图', '图表', '附件', '文档', '文件', '扫描', '照片', '图', 'pdf',
    'poster', 'image', 'screenshot', 'picture', 'photo', 'document', 'attachment', 'file', 'scan',
)


def select_referenced_image_attachment(question_text: str, image_attachments: list):
    """On demand: pick the ONE most relevant image-only attachment the question refers to,
    or None. Prefers an explicit filename mention, else (if the question references a
    document/image at all) the most recently added image attachment."""
    if not image_attachments:
        return None
    q = str(question_text or '')
    ql = q.lower()
    for att in reversed(image_attachments):           # explicit filename / stem -> that file
        name = str(att.get('name', '') or '')
        stem = os.path.splitext(name)[0]
        if (name and name.lower() in ql) or (stem and len(stem) >= 3 and stem.lower() in ql):
            return att
    if any(word in ql for word in _ATTACHMENT_REFERENCE_DOC_WORDS):  # generic ref -> most recent
        return image_attachments[-1]
    return None


def attachment_display_html_block(message: dict) -> str:
    attachments = message.get('attachments') or []
    if not attachments:
        return ''
    rows = ['<div class="attachment-display-block"><div class="attachment-display-title">'
            + html.escape(_tr('Attachments')) + '</div><ul>']
    for attachment in attachments:
        name = str(attachment.get('name', _tr('Attachment'))).strip() or _tr('Attachment')
        stored_path = str(attachment.get('stored_path', '')).strip()
        uri = attachment_file_uri(attachment)
        badge = ('<span class="attachment-badge">' + html.escape(_tr('retrieval')) + '</span>'
                 if attachment.get('use_embedding') else '')
        if uri:
            label = f'<a href="{html.escape(uri, quote=True)}" title="{html.escape(stored_path, quote=True)}">{html.escape(name)}</a>'
        else:
            label = f'<span>{html.escape(name)}</span>'
        rows.append(f'<li>{label}{badge}</li>')
    rows.append('</ul></div>')
    return ''.join(rows)


def render_message_markdown(message: dict) -> str:
    content = str(message.get('content', '')).strip('\n')
    if str(message.get('role', '')).strip().lower() == 'assistant':
        content = strip_structured_outputs_from_display_text(content)
    attachment_block = attachment_markdown_block(message)
    if attachment_block:
        return (content + '\n\n' + attachment_block).strip()
    return content


def render_message_display_markup(message: dict, display_prefix_placeholder: str = '') -> str:
    role = str(message.get('role', '')).strip().lower()
    if role != 'user':
        content = render_message_markdown(message)
        if display_prefix_placeholder:
            content = (display_prefix_placeholder + '\n\n' + content).strip()
        return content
    content = str(message.get('content', '')).strip('\n')
    text_html = f'<div class="user-message-plain">{linkify_plain_text_to_html(content)}</div>' if content else ''
    attachment_html = attachment_display_html_block(message)
    return (text_html + attachment_html).strip()


def render_message_plaintext(message: dict) -> str:
    content = str(message.get('content', '')).strip('\n')
    attachment_block = attachment_plaintext_block(message)
    if attachment_block:
        return (content + '\n\n' + attachment_block).strip()
    return content


def model_profile_label(model: str, profile: str = '') -> str:
    """"model · profile" for answers and steps (a profile named like its model shows once)."""
    model = str(model or '').strip()
    profile = str(profile or '').strip()
    if profile and profile != model:
        return f'{model} · {profile}' if model else profile
    return model


def chat_message_render_hash(message: dict) -> str:
    try:
        payload = {
            'role': str(message.get('role', '') or ''),
            'content': str(message.get('content', '') or ''),
            'timestamp': str(message.get('timestamp', '') or ''),
            'source': str(message.get('source', '') or ''),
            'display_prefix_html': str(message.get('display_prefix_html', '') or ''),
            'model_label': str(message.get('model_label', '') or ''),
            'attachments': message.get('attachments') or [],
        }
        return str(hash(json.dumps(payload, ensure_ascii=False, sort_keys=True)))
    except Exception:
        return str(hash(str(message)))


def chat_message_render_hashes(messages: list[dict]) -> list[str]:
    return [chat_message_render_hash(message) for message in (messages or [])]


def conversation_messages_signature(messages: list[dict]) -> str:
    try:
        normalized = []
        for item in messages or []:
            message = normalize_chat_history_message(item)
            if message:
                normalized.append(message)
        return hashlib.sha256(json.dumps(normalized, ensure_ascii=False, sort_keys=True).encode('utf-8')).hexdigest()
    except Exception:
        return hashlib.sha256(str(messages or []).encode('utf-8', errors='ignore')).hexdigest()


def parse_legacy_chat_history_markdown(markdown_text: str) -> list[dict]:
    text = str(markdown_text or '').replace('\r\n', '\n').replace('\r', '\n')
    if not text.strip():
        return []
    heading_re = re.compile(r'^\s*#{1,6}\s*([QA])(?:\s*[·:\-]\s*(.*?))?\s*$', re.IGNORECASE)
    messages = []
    current = None
    body_lines = []

    def flush_current():
        nonlocal current, body_lines
        if current is None:
            return
        content = '\n'.join(body_lines).strip('\n')
        message = {
            'role': current['role'],
            'content': content,
        }
        if current.get('timestamp'):
            message['timestamp'] = current['timestamp']
        normalized = normalize_chat_history_message(message)
        if normalized:
            messages.append(normalized)
        current = None
        body_lines = []

    for line in text.split('\n'):
        match = heading_re.match(line)
        if match:
            flush_current()
            role = 'user' if match.group(1).upper() == 'Q' else 'assistant'
            timestamp = str(match.group(2) or '').strip()
            current = {'role': role, 'timestamp': timestamp}
            continue
        if current is not None:
            body_lines.append(line)
    flush_current()
    if messages:
        return messages
    return [
        {
            'role': 'assistant',
            'content': text.strip(),
            'timestamp': current_chat_timestamp(),
            'source': 'legacy',
        }
    ]


def normalize_memory_item_record(item) -> dict | None:
    if isinstance(item, dict):
        text = str(item.get('text', '')).strip()
        if not text:
            return None
        return {
            'text': text,
            'created_at': str(item.get('created_at', '')).strip() or datetime.datetime.now().isoformat(timespec='seconds'),
            'kind': str(item.get('kind', '')).strip() or 'manual',
            'source_date': str(item.get('source_date', '')).strip(),
        }
    text = str(item or '').strip()
    if not text:
        return None
    return {
        'text': text,
        'created_at': datetime.datetime.now().isoformat(timespec='seconds'),
        'kind': 'manual',
        'source_date': '',
    }


def normalize_memory_item_records(items) -> list[dict]:
    normalized = []
    if not isinstance(items, list):
        return normalized
    for item in items:
        record = normalize_memory_item_record(item)
        if record:
            normalized.append(record)
    return normalized


def memory_item_display_text(record: dict) -> str:
    text = str(record.get('text', '')).strip()
    if not text:
        return ''
    source_date = str(record.get('source_date', '')).strip()
    if source_date:
        return f'{source_date} · {text}'
    return text


def prune_memory_item_records(items: list[dict], retention_days: int, now: datetime.datetime | None = None) -> list[dict]:
    retention_days = max(1, int(retention_days or 30))
    now = now or datetime.datetime.now()
    kept = []
    for item in normalize_memory_item_records(items):
        created_at = str(item.get('created_at', '')).strip()
        try:
            created_dt = datetime.datetime.fromisoformat(created_at)
        except Exception:
            created_dt = now
        age_days = (now.date() - created_dt.date()).days
        if age_days < retention_days:
            kept.append(item)
    return kept


# ── 从用户对成品的手动修改里学习偏好（2026-10-18）──────────────────────────
# 用户在「Generated outputs」浮窗里改完成品点「完成」后，后台让模型对比改前/改后，
# 把学到的通用偏好追加到永久记忆末尾的一个小节里（不过期、可在 设置→记忆 直接改）。
# 永久记忆平时按与提问的相关性检索，写作偏好通常检索不到，所以这一小节每次都整段带上。
LEARNED_OUTPUT_PREFS_MARK = '## ✎'
LEARNED_OUTPUT_PREFS_MAX_CONTEXT_CHARS = 2000
LEARNED_OUTPUT_PREFS_MAX_NEW_LINES = 3


def learned_output_preferences_header() -> str:
    return LEARNED_OUTPUT_PREFS_MARK + ' ' + _tr('Learned output preferences (from your edits; edit or delete freely)')


def _learned_output_preferences_span(lines: list[str]) -> tuple[int, int]:
    """(header index, end index) of the learned section in memory lines; (-1, -1) if absent.
    The section runs to the next '## ' heading or the end."""
    for index, line in enumerate(lines):
        if line.strip().startswith(LEARNED_OUTPUT_PREFS_MARK):
            end = len(lines)
            for later in range(index + 1, len(lines)):
                if lines[later].strip().startswith('## '):
                    end = later
                    break
            return index, end
    return -1, -1


def split_learned_output_preferences(memory_text: str) -> tuple[str, list[str]]:
    """Permanent memory without the learned section, and the section's non-empty lines."""
    lines = str(memory_text or '').splitlines()
    start, end = _learned_output_preferences_span(lines)
    if start < 0:
        return str(memory_text or ''), []
    section = [line.strip() for line in lines[start + 1:end] if line.strip()]
    rest = '\n'.join(lines[:start] + lines[end:]).strip()
    return rest, section


def append_learned_output_preferences(memory_text: str, new_lines: list[str], day: str) -> str:
    """Append dated preference lines at the END of the learned section (created at the end
    of permanent memory when missing); the rest of the user's memory is left untouched."""
    additions = [f'- {day} · {str(line).strip()}' for line in new_lines if str(line or '').strip()]
    if not additions:
        return str(memory_text or '')
    lines = str(memory_text or '').rstrip().splitlines()
    start, end = _learned_output_preferences_span(lines)
    if start < 0:
        base = '\n'.join(lines).rstrip()
        block = learned_output_preferences_header() + '\n' + '\n'.join(additions)
        return (base + '\n\n' + block) if base else block
    insert_at = end
    while insert_at > start + 1 and not lines[insert_at - 1].strip():
        insert_at -= 1
    lines[insert_at:insert_at] = additions
    return '\n'.join(lines)


def learned_output_preferences_context(section_lines: list[str]) -> str:
    """Always-on prompt block (newest lines kept when it is long)."""
    kept, used = [], 0
    for line in reversed([str(item).strip() for item in section_lines or [] if str(item).strip()]):
        if used + len(line) + 1 > LEARNED_OUTPUT_PREFS_MAX_CONTEXT_CHARS:
            break
        kept.append(line)
        used += len(line) + 1
    if not kept:
        return ''
    return (
        "Learned output preferences (inferred from the user's own edits of earlier generated "
        "outputs; follow them when writing answers and outputs unless the user asks otherwise):\n"
        + '\n'.join(reversed(kept))
    )


def _learned_line_body(line: str) -> str:
    text = re.sub(r'^\s*(?:[-*•·]|\d+[.)、])\s*', '', str(line or '')).strip()
    return re.sub(r'^\d{4}-\d{2}-\d{2}\s*·\s*', '', text).strip()


def build_output_edit_learning_messages(original: str,
                                        edited: str,
                                        *,
                                        question: str = '',
                                        kind: str = 'text',
                                        title: str = '',
                                        existing_lines: list[str] | None = None,
                                        language: str = 'English') -> list[dict]:
    """One USER message (the user's relay endpoint silently drops system-role messages)."""
    original = str(original or '')
    edited = str(edited or '')
    diff = ''.join(difflib.unified_diff(
        original.splitlines(keepends=True), edited.splitlines(keepends=True),
        fromfile='original', tofile='edited', n=2,
    ))
    def clip(text: str, limit: int) -> str:
        return text if len(text) <= limit else text[:limit].rstrip() + '\n…[truncated]'
    known = [_learned_line_body(line) for line in existing_lines or [] if _learned_line_body(line)]
    prompt = (
        'You help Broccoli learn how this user likes generated outputs to be written.\n'
        'The assistant produced the ORIGINAL text below; the user then edited it by hand into the '
        'EDITED text. A unified diff of the edit is included.\n\n'
        'Infer DURABLE preferences that should guide future outputs for this user: tone, length, '
        'structure, formatting, wording habits, things they consistently remove or add. Ignore '
        'one-off content fixes that only make sense for this particular text (a corrected fact, a '
        'name, a date, a typo) unless they reveal a general habit.\n\n'
        'Already learned (do not repeat or rephrase these; only add what is new):\n'
        + ('\n'.join(f'- {line}' for line in known) if known else '(none yet)') + '\n\n'
        + (f'What the user originally asked for:\n{clip(question.strip(), 1500)}\n\n' if question.strip() else '')
        + f'Output kind: {kind or "text"}' + (f' · title: {title}' if title else '') + '\n\n'
        + 'ORIGINAL:\n<<<\n' + clip(original, 6000) + '\n>>>\n\n'
        + 'EDITED:\n<<<\n' + clip(edited, 6000) + '\n>>>\n\n'
        + 'DIFF:\n' + clip(diff, 8000) + '\n\n'
        + f'Reply with at most {LEARNED_OUTPUT_PREFS_MAX_NEW_LINES} lines, each starting with "- ": '
        + f'one short, general, actionable preference per line, written in {language}. '
        + 'If there is nothing general to learn, reply with exactly NONE.'
    )
    return [{'role': 'user', 'content': prompt}]


def parse_learned_preference_reply(reply: str, existing_lines: list[str] | None = None) -> list[str]:
    text = str(reply or '').strip()
    if not text or text.upper().strip(' .。') == 'NONE':
        return []
    known = {_learned_line_body(line).casefold() for line in existing_lines or []}
    found = []
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.upper().strip(' .。') == 'NONE':
            continue
        if not re.match(r'^\s*(?:[-*•·]|\d+[.)、])\s*', line):
            continue
        body = _learned_line_body(line)[:200].strip()
        if not body or body.casefold() in known or body.casefold() in {item.casefold() for item in found}:
            continue
        found.append(body)
        if len(found) >= LEARNED_OUTPUT_PREFS_MAX_NEW_LINES:
            break
    return found


def learn_from_output_edit(original: str,
                           edited: str,
                           *,
                           question: str = '',
                           kind: str = 'text',
                           title: str = '') -> dict:
    """Background worker body: ask the active profile's model what the edit says about the
    user's preferences and append the new ones to permanent memory. Never raises."""
    if str(original or '') == str(edited or ''):
        return {'status': 'nothing', 'lines': []}
    profile = load_active_settings_profile()
    api_key = str(profile.get('api_key', '')).strip()
    endpoint = profile_runtime_base_url(profile)
    model = str(profile.get('model', '')).strip()
    try:
        timeout = int(profile.get('timeout', 60) or 60)
    except (TypeError, ValueError):
        timeout = 60
    if not api_key or not model:
        return {'status': 'no_model', 'lines': []}
    _rest, existing = split_learned_output_preferences(load_settings_store().get('globals', {}).get('memory_text', ''))
    messages = build_output_edit_learning_messages(
        original, edited, question=question, kind=kind, title=title,
        existing_lines=existing, language=preferred_ui_language(),
    )
    try:
        client = create_openai_client(api_key, endpoint, timeout)
        response = create_chat_completion(client, endpoint=endpoint, model=model, messages=messages, stream=False)
        reply = str(response.choices[0].message.content or '')
    except Exception as exc:
        logging.warning('Learning from an output edit failed: %s', exc)
        return {'status': 'error', 'lines': [], 'error': str(exc)[:200]}
    day = datetime.date.today().isoformat()
    added = []

    def apply(store):
        globals_store = store.setdefault('globals', {})
        current = str(globals_store.get('memory_text', '') or '')
        _rest_now, existing_now = split_learned_output_preferences(current)
        # Parse against the CURRENT section (the user may have edited it meanwhile).
        added[:] = parse_learned_preference_reply(reply, existing_now)
        if added:
            globals_store['memory_text'] = append_learned_output_preferences(current, added, day)

    try:
        update_settings_store(apply)
    except Exception as exc:
        logging.warning('Saving learned output preferences failed: %s', exc)
        return {'status': 'error', 'lines': [], 'error': str(exc)[:200]}
    return {'status': 'learned' if added else 'nothing', 'lines': list(added)}


def normalize_chat_history_message(item: dict) -> dict | None:
    if not isinstance(item, dict):
        return None
    role = str(item.get('role', '')).strip().lower()
    if role not in {'user', 'assistant'}:
        return None
    content = str(item.get('content', ''))
    timestamp = str(item.get('timestamp', '')).strip()
    normalized = {'role': role, 'content': content}
    if timestamp:
        normalized['timestamp'] = timestamp
    source = str(item.get('source', '') or '').strip()
    if source:
        normalized['source'] = source[:40]
    display_prefix_html = str(item.get('display_prefix_html', '') or '').strip()
    if display_prefix_html and role == 'assistant':
        normalized['display_prefix_html'] = display_prefix_html
    model_label = str(item.get('model_label', '') or '').strip()
    if model_label and role == 'assistant':
        normalized['model_label'] = model_label[:120]   # "model · profile" that wrote the answer
    if isinstance(item.get('attachments'), list):
        attachments = []
        for attachment in item['attachments']:
            normalized_attachment = normalize_attachment_record(attachment)
            if normalized_attachment:
                attachments.append(normalized_attachment)
        if attachments:
            normalized['attachments'] = attachments
    return normalized


def _planner_compact_text(text: str, limit: int = 1400) -> str:
    content = re.sub(r'\s+', ' ', str(text or '')).strip()
    limit = max(200, int(limit or 1400))
    if len(content) <= limit:
        return content
    head = content[:limit // 2].rstrip()
    tail = content[-(limit - len(head) - 24):].lstrip()
    return f'{head} ... [middle omitted] ... {tail}'


def build_planner_recent_conversation_context(history_messages: list[dict],
                                              *,
                                              max_messages: int = PLANNER_RECENT_CONTEXT_MESSAGES,
                                              max_chars: int = PLANNER_RECENT_CONTEXT_MAX_CHARS) -> str:
    normalized_messages = []
    for item in history_messages or []:
        normalized = normalize_chat_history_message(item)
        if normalized and str(normalized.get('content', '') or '').strip():
            normalized_messages.append(normalized)
    if not normalized_messages:
        return ''
    recent = normalized_messages[-max(1, int(max_messages or PLANNER_RECENT_CONTEXT_MESSAGES)):]
    blocks = []
    remaining = max(1000, int(max_chars or PLANNER_RECENT_CONTEXT_MAX_CHARS))
    for message in recent:
        role = 'User' if str(message.get('role', '') or '') == 'user' else 'Assistant'
        timestamp = str(message.get('timestamp', '') or '').strip()
        label = f'{role} {timestamp}'.strip()
        text = _planner_compact_text(str(message.get('content', '') or ''))
        block = f'{label}: {text}'
        if len(block) > remaining:
            block = block[:remaining].rstrip() + '\n[Planner conversation context truncated.]'
        blocks.append(block)
        remaining -= len(block)
        if remaining <= 0:
            break
    return '\n\n'.join(blocks).strip()


def current_chat_timestamp() -> str:
    # Stamped ONCE at message creation and persisted. Older conversations carry
    # the pre-FIX19 'HH:MM' form — the date was never recorded for them, so the
    # display layer must keep accepting both shapes (it just echoes the string).
    return datetime.datetime.now().strftime('%Y-%m-%d %H:%M')


def format_message_label(role: str, timestamp: str = '') -> str:
    label = 'Q' if role == 'user' else 'A'
    return f'{label} · {timestamp}' if timestamp else label


def load_chat_history_messages() -> list[dict]:
    global _CURRENT_CHAT_HISTORY_MESSAGES
    if _CURRENT_CHAT_HISTORY_MESSAGES is not None:
        return copy.deepcopy(_CURRENT_CHAT_HISTORY_MESSAGES)
    ensure_broccoli_data_dir()
    if not os.path.exists(CHAT_HISTORY_PATH):
        return []
    try:
        with open(CHAT_HISTORY_PATH, 'r', encoding='utf-8') as handle:
            raw_messages = json.load(handle)
    except Exception:
        return []
    if not isinstance(raw_messages, list):
        return []
    messages = []
    for item in raw_messages:
        normalized = normalize_chat_history_message(item)
        if normalized:
            messages.append(normalized)
    _CURRENT_CHAT_HISTORY_MESSAGES = copy.deepcopy(messages)
    return messages


def render_chat_history_markdown(messages: list[dict]) -> str:
    blocks = []
    for index, message in enumerate(messages):
        blocks.append(f'### {format_message_label(message["role"], message.get("timestamp", ""))}')
        blocks.append(render_message_markdown(message))
    return '\n\n'.join(block for block in blocks if block).strip()


def render_chat_message_display_html(message: dict, index: int, *, include_separator: bool) -> str:
    blocks = []
    if include_separator and message['role'] == 'user':
        blocks.append('<div class="chat-separator"></div>')
    blocks.append(f'<div id="msg-{index}" class="chat-anchor"></div>')
    label = 'Q' if message['role'] == 'user' else 'A'
    label_class = 'q' if message['role'] == 'user' else 'a'
    timestamp = message.get('timestamp', '')
    source = str(message.get('source', '') or '').strip()
    meta_parts = []
    if timestamp:
        meta_parts.append(f'<span class="qa-time">{html.escape(timestamp)}</span>')
    if source:
        meta_parts.append(f'<span class="qa-source">{html.escape(source)}</span>')
    model_label = str(message.get('model_label', '') or '').strip()
    if model_label and message['role'] == 'assistant':   # the model (and profile) that answered
        meta_parts.append(f'<span class="qa-time qa-model">{html.escape(model_label)}</span>')
    if meta_parts:
        blocks.append(
            f'<div class="qa-meta-row"><span class="qa-label qa-label-{label_class}">{label}</span>'
            f'{"".join(meta_parts)}</div>'
        )
    else:
        blocks.append(f'<span class="qa-label qa-label-{label_class}">{label}</span>')
    display_prefix_html = linkify_bare_urls_in_html(str(message.get('display_prefix_html', '') or '').strip())
    if display_prefix_html and message['role'] == 'assistant':
        blocks.append(display_prefix_html)
    if message['role'] == 'assistant':
        content_html = render_markdown_fragment(render_message_markdown(message))
    else:
        content_html = render_message_display_markup(message)
    blocks.append(
        f'<div class="agent-message-content" data-message-index="{index}">'
        f'{content_html}'
        '</div>'
    )
    return ''.join(block for block in blocks if block).strip()


def render_chat_message_card_html(message: dict,
                                  index: int,
                                  *,
                                  dark: bool | None = None,
                                  use_cache: bool = True) -> str:
    normalized = normalize_chat_history_message(message)
    if not normalized:
        return ''
    if dark is None:
        dark = bool(is_dark_theme(app))
    message_hash = chat_message_render_hash(normalized)
    cache_key = (bool(dark), int(AGENT_RENDERER_VERSION), message_hash)
    template = None
    if use_cache:
        with _AGENT_MESSAGE_HTML_CACHE_LOCK:
            template = _AGENT_MESSAGE_HTML_CACHE.get(cache_key)
    if template is None:
        rendered = render_chat_message_display_html(
            normalized,
            AGENT_MESSAGE_INDEX_TOKEN,
            include_separator=False,
        )
        role = html.escape(str(normalized.get('role', '') or '').strip().lower(), quote=True)
        message_hash_attr = html.escape(message_hash, quote=True)
        template = (
            f'<section class="chat-display-message" data-message-index="{AGENT_MESSAGE_INDEX_TOKEN}" '
            f'data-message-role="{role}" data-message-hash="{message_hash_attr}">'
            '__BROCCOLI_MESSAGE_SEPARATOR__'
            f'{rendered}'
            '</section>'
        )
        if use_cache:
            with _AGENT_MESSAGE_HTML_CACHE_LOCK:
                if len(_AGENT_MESSAGE_HTML_CACHE) >= _AGENT_MESSAGE_HTML_CACHE_LIMIT:
                    _AGENT_MESSAGE_HTML_CACHE.clear()
                _AGENT_MESSAGE_HTML_CACHE[cache_key] = template
    separator = '<div class="chat-separator"></div>' if int(index) > 0 else ''
    return template.replace('__BROCCOLI_MESSAGE_SEPARATOR__', separator).replace(
        AGENT_MESSAGE_INDEX_TOKEN,
        str(int(index)),
    )


def render_chat_message_cards(messages: list[dict],
                              start_index: int = 0,
                              *,
                              dark: bool | None = None,
                              use_cache: bool = True) -> list[str]:
    cards = []
    for offset, message in enumerate(messages or []):
        card = render_chat_message_card_html(
            message,
            int(start_index) + offset,
            dark=dark,
            use_cache=use_cache,
        )
        if card:
            cards.append(card)
    return cards


def render_chat_history_display_html(messages: list[dict],
                                     *,
                                     dark: bool | None = None,
                                     use_cache: bool = True) -> str:
    return ''.join(render_chat_message_cards(messages, 0, dark=dark, use_cache=use_cache)).strip()


def render_chat_messages_display_fragment_html(messages: list[dict],
                                               start_index: int,
                                               *,
                                               dark: bool | None = None,
                                               use_cache: bool = True) -> str:
    return ''.join(
        render_chat_message_cards(
            messages,
            int(start_index),
            dark=dark,
            use_cache=use_cache,
        )
    ).strip()


def render_markdown_display_fragment_to_html(markdown_text: str, display_prefix_map: dict[str, str] | None = None) -> str:
    fragment = render_markdown_fragment(markdown_text)
    for placeholder, prefix_html in (display_prefix_map or {}).items():
        fragment = fragment.replace(f'<p>{placeholder}</p>', prefix_html)
        fragment = fragment.replace(placeholder, prefix_html)
    return fragment


def render_structured_transfer_editor_html(messages: list[dict], dark: bool) -> str:
    normal_display_css = render_chat_display_document_css(dark)
    body_bg = '#2D2D2D' if dark else '#FFFFFF'
    body_fg = '#F2F2F7' if dark else '#20242B'
    muted = '#A7AEB8' if dark else '#7A8391'
    panel_bg = '#343436' if dark else '#F7F8FA'
    panel_border = '#4A4B4F' if dark else '#E2E5EA'
    editor_bg = '#2A2A2C' if dark else '#FFFFFF'
    q_bg = '#2E5C91' if dark else '#D9EAF8'
    q_fg = '#FFFFFF' if dark else '#184B7A'
    a_bg = '#4B5F3E' if dark else '#DDE8D6'
    a_fg = '#FFFFFF' if dark else '#355728'
    sections = []
    for index, message in enumerate(messages):
        role = str(message.get('role', '') or '').strip().lower()
        label = 'Q' if role == 'user' else 'A'
        label_class = 'q' if role == 'user' else 'a'
        timestamp = str(message.get('timestamp', '') or '').strip()
        source = str(message.get('source', '') or '').strip()
        meta = html.escape(format_message_label(role, timestamp), quote=False)
        if source:
            meta += f'<span class="source">{html.escape(source)}</span>'
        content = html.escape(str(message.get('content', '') or ''), quote=False)
        attachments = attachment_plaintext_block(
            message, header=_tr('Attachments:'), retrieval_label=_tr('retrieval'))
        attachment_hint = ''
        if attachments:
            attachment_hint = (
                '<div class="attachment-note">'
                + html.escape(attachments, quote=False)
                + '</div>'
            )
        sections.append(
            f'''
            <section class="message-card" data-message-index="{index}" data-message-role="{html.escape(role, quote=True)}">
                <div id="msg-{index}" class="chat-anchor"></div>
                <div class="message-meta">
                    <span class="role-pill role-{label_class}">{label}</span>
                    <span class="meta-text">{meta}</span>
                </div>
                <div class="message-editor"
                     contenteditable="plaintext-only"
                     spellcheck="false"
                     data-edit-content="1"
                     data-message-index="{index}">{content}</div>
                {attachment_hint}
            </section>
            '''
        )
    return f"""
    <html>
    <head>
    <meta content="text/html; charset=utf-8" http-equiv="content-type" />
    <style id="broccoli-normal-display-css">
        {normal_display_css}
        .chat-display-message {{
            display: block;
            margin: 0;
        }}
    </style>
    <style>
        html, body {{
            margin: 0;
            background: {body_bg};
            color: {body_fg};
            font-family: -apple-system, BlinkMacSystemFont, "Helvetica Neue", Helvetica, Arial, sans-serif;
        }}
        body {{
            padding: 18px 18px 28px 18px;
            box-sizing: border-box;
        }}
        .message-card {{
            margin: 0 0 18px 0;
            padding: 13px 14px 14px 14px;
            border: 1px solid {panel_border};
            border-radius: 12px;
            background: {panel_bg};
        }}
        .chat-anchor {{
            position: relative;
            top: -12px;
            height: 0;
        }}
        .message-meta {{
            display: flex;
            align-items: center;
            gap: 9px;
            margin: 0 0 10px 0;
        }}
        .role-pill {{
            display: inline-block;
            padding: 3px 10px;
            border-radius: 999px;
            font-size: 12px;
            font-weight: 700;
            letter-spacing: 0.08em;
        }}
        .role-q {{
            background: {q_bg};
            color: {q_fg};
        }}
        .role-a {{
            background: {a_bg};
            color: {a_fg};
        }}
        .meta-text {{
            color: {muted};
            font-size: 12px;
            font-weight: 600;
        }}
        .source {{
            margin-left: 8px;
            opacity: 0.85;
        }}
        .message-editor {{
            min-height: 34px;
            padding: 10px 11px;
            border: 1px solid {panel_border};
            border-radius: 8px;
            background: {editor_bg};
            color: {body_fg};
            outline: none;
            white-space: pre-wrap;
            word-break: break-word;
            line-height: 1.56;
            font-size: 14px;
        }}
        .message-editor:focus {{
            border-color: {q_bg};
            box-shadow: 0 0 0 2px rgba(46, 92, 145, 0.22);
        }}
        .attachment-note {{
            margin-top: 10px;
            color: {muted};
            font-size: 12px;
            white-space: pre-wrap;
            word-break: break-word;
            line-height: 1.45;
        }}
    </style>
    </head>
    <body>
        {''.join(sections)}
        <script>
        window.__broccoliStructuredTransferDirty = false;
        document.addEventListener('input', function(event) {{
            if (event.target && event.target.closest('[data-edit-content="1"]')) {{
                window.__broccoliStructuredTransferDirty = true;
            }}
        }});
        window.broccoliCollectStructuredMessages = function(clearDirty) {{
            const items = Array.from(document.querySelectorAll('[data-edit-content="1"]'));
            const messages = items.map((el) => {{
                let text = el.innerText || '';
                text = text.replace(/\\u00a0/g, ' ');
                text = text.replace(/\\n$/, '');
                return {{
                    index: Number(el.getAttribute('data-message-index')),
                    content: text
                }};
            }});
            const dirty = !!window.__broccoliStructuredTransferDirty;
            if (clearDirty) window.__broccoliStructuredTransferDirty = false;
            return {{ dirty, messages }};
        }};
        </script>
    </body>
    </html>
    """


def _chat_history_plaintext_blocks(messages: list[dict]) -> list[tuple[str, int]]:
    """(block text, index of the message whose label this block is, else -1)."""
    blocks = []
    for index, message in enumerate(messages):
        if index > 0 and message['role'] == 'user':
            blocks.append(('--------------------', -1))
        blocks.append((format_message_label(message['role'], message.get('timestamp', '')), index))
        blocks.append((render_message_plaintext(message), -1))
    return [(text, index) for text, index in blocks if text]


def render_chat_history_plaintext(messages: list[dict]) -> str:
    return '\n\n'.join(text for text, _index in _chat_history_plaintext_blocks(messages)).strip()


def chat_history_plaintext_label_offsets(messages: list[dict]) -> dict:
    """Message index → character offset of its label in render_chat_history_plaintext()."""
    offsets, position = {}, 0
    for text, index in _chat_history_plaintext_blocks(messages):
        if index >= 0:
            offsets[index] = position
        position += len(text) + 2
    return offsets


def chat_preview_rail_messages(history_messages: list[dict], question_text: str) -> list[dict]:
    """The messages a build_chat_preview() shows, minus the answer being generated."""
    return list(history_messages or []) + [{'role': 'user', 'content': str(question_text or '')}]


def save_chat_history_messages(messages: list[dict]) -> str:
    global _CURRENT_CHAT_HISTORY_MESSAGES
    perf_started = time.perf_counter()
    ensure_broccoli_data_dir()
    normalized_messages = []
    for item in messages:
        normalized = normalize_chat_history_message(item)
        if normalized:
            normalized_messages.append(normalized)
    normalized_at = time.perf_counter()
    _CURRENT_CHAT_HISTORY_MESSAGES = copy.deepcopy(normalized_messages)
    markdown = render_chat_history_markdown(normalized_messages)
    _enqueue_async_file_write(
        {
            'kind': 'chat_history',
            'history_path': CHAT_HISTORY_PATH,
            'messages': copy.deepcopy(normalized_messages),
            'output_path': BasePath + 'output.txt',
            'markdown': markdown,
        }
    )
    history_written_at = time.perf_counter()
    finished_at = time.perf_counter()
    _agent_render_perf_log(
        'save_chat_history',
        messages=len(normalized_messages),
        normalize_ms=round((normalized_at - perf_started) * 1000, 2),
        history_write_ms=round((history_written_at - normalized_at) * 1000, 2),
        output_write_ms=round((finished_at - history_written_at) * 1000, 2),
        total_ms=round((finished_at - perf_started) * 1000, 2),
    )
    return markdown


def clear_chat_history_messages(clear_output: bool = True) -> None:
    global _CURRENT_CHAT_HISTORY_MESSAGES
    ensure_broccoli_data_dir()
    _CURRENT_CHAT_HISTORY_MESSAGES = []
    _enqueue_async_file_write(
        {
            'kind': 'chat_history',
            'history_path': CHAT_HISTORY_PATH,
            'messages': [],
            'output_path': BasePath + 'output.txt' if clear_output else '',
            'markdown': '',
        }
    )


def get_current_chat_history_messages() -> list[dict]:
    messages = load_chat_history_messages()
    if not messages:
        return []
    if _CURRENT_CHAT_HISTORY_MESSAGES is not None:
        return messages
    current_output = read_file_contents(BasePath + 'output.txt', '').strip()
    rendered_output = render_chat_history_markdown(messages).strip()
    if current_output != rendered_output:
        return []
    return messages


def append_chat_turn(history_messages: list[dict], question_text: str, answer_text: str, attachments: list[dict] | None = None, assistant_display_prefix_html: str = '', persist_current: bool = True, model_label: str = '') -> tuple[list[dict], str]:
    new_messages = list(history_messages)
    user_message = {'role': 'user', 'content': question_text.strip(), 'timestamp': current_chat_timestamp()}
    if attachments:
        normalized_attachments = []
        for attachment in attachments:
            normalized_attachment = normalize_attachment_record(attachment)
            if normalized_attachment:
                normalized_attachments.append(normalized_attachment)
        if normalized_attachments:
            user_message['attachments'] = normalized_attachments
    new_messages.append(user_message)
    assistant_message = {'role': 'assistant', 'content': answer_text.strip(), 'timestamp': current_chat_timestamp()}
    if str(assistant_display_prefix_html or '').strip():
        assistant_message['display_prefix_html'] = str(assistant_display_prefix_html).strip()
    if str(model_label or '').strip():
        assistant_message['model_label'] = str(model_label).strip()
    new_messages.append(assistant_message)
    if persist_current:
        markdown = save_chat_history_messages(new_messages)
    else:
        markdown = render_chat_history_markdown(new_messages)
    return new_messages, markdown


def output_kind_from_path(path: str) -> str:
    suffix = Path(str(path or '')).suffix.lower()
    if suffix in ATTACHMENT_IMAGE_EXTS:
        return 'image'
    if suffix in ATTACHMENT_AUDIO_EXTS:
        return 'audio'
    if suffix in ATTACHMENT_VIDEO_EXTS:
        return 'video'
    if suffix in {'.py', '.js', '.ts', '.html', '.css', '.json', '.xml', '.sh', '.swift', '.kt', '.java', '.go', '.rs', '.c', '.cpp', '.h'}:
        return 'code'
    if suffix in {'.txt', '.md', '.csv', '.yaml', '.yml', '.toml'}:
        return 'text'
    return 'file'


def default_output_filename(record: dict) -> str:
    filename = str(record.get('filename', '')).strip()
    if filename:
        return filename
    title = sanitize_conversation_filename(str(record.get('title', '') or 'broccoli-output'), max_len=48)
    kind = str(record.get('kind', 'text')).strip().lower()
    if kind == 'code':
        return f'{title}.txt'
    if kind == 'text':
        return f'{title}.txt'
    path = str(record.get('path', '')).strip()
    if path:
        return os.path.basename(path)
    return f'{title}.txt'


def normalize_output_record(item: dict, fallback_index: int = 0) -> dict | None:
    if not isinstance(item, dict):
        return None
    content = str(item.get('content', '') or '')
    path = str(item.get('path', '') or '').strip()
    if not content.strip() and not path:
        return None
    kind = str(item.get('kind', '') or '').strip().lower()
    if kind not in {'code', 'text', 'image', 'audio', 'video', 'file'}:
        kind = output_kind_from_path(path) if path else 'text'
    try:
        question_index = int(item.get('question_index', -1))
    except (TypeError, ValueError):
        question_index = -1
    try:
        assistant_index = int(item.get('assistant_index', -1))
    except (TypeError, ValueError):
        assistant_index = -1
    created_at = str(item.get('created_at', '') or '').strip() or datetime.datetime.now().isoformat(timespec='seconds')
    output_id = str(item.get('id', '') or '').strip()
    if not output_id:
        seed = f'{created_at}-{question_index}-{assistant_index}-{fallback_index}-{kind}-{path}-{content[:80]}'
        output_id = f'out-{abs(hash(seed))}'
    title = str(item.get('title', '') or '').strip()
    if not title:
        if question_index >= 0:
            title = f'Output from Q{question_index // 2 + 1}'
        else:
            title = f'Output {fallback_index + 1}'
    normalized = {
        'id': output_id,
        'kind': kind,
        'title': title,
        'filename': str(item.get('filename', '') or '').strip(),
        'content': content,
        'path': path,
        'question': str(item.get('question', '') or '').strip(),
        'question_index': question_index,
        'assistant_index': assistant_index,
        'created_at': created_at,
        'source': str(item.get('source', '') or '').strip() or 'assistant',
    }
    annotations = []
    if isinstance(item.get('annotations'), list):
        for ann_index, annotation in enumerate(item.get('annotations') or []):
            if not isinstance(annotation, dict):
                continue
            comment = str(annotation.get('comment', '') or '').strip()
            if not comment:
                continue
            normalized_annotation = dict(annotation)
            normalized_annotation['id'] = str(annotation.get('id', '') or f'ann-{fallback_index}-{ann_index}').strip()
            normalized_annotation['comment'] = comment
            normalized_annotation['kind'] = str(annotation.get('kind', 'note') or 'note').strip()
            annotations.append(normalized_annotation)
    if annotations:
        normalized['annotations'] = annotations
    model_name = str(item.get('model_name', '') or '').strip()
    if model_name:
        normalized['model_name'] = model_name
    # 用户在成品浮窗里手动改过：保留模型最初给的版本和修改时间。
    if isinstance(item.get('original_content'), str):
        normalized['original_content'] = item['original_content']
    edited_at = str(item.get('edited_at', '') or '').strip()
    if edited_at:
        normalized['edited_at'] = edited_at
    return normalized


def normalize_output_records(items) -> list[dict]:
    normalized = []
    seen = set()
    if not isinstance(items, list):
        return normalized
    for index, item in enumerate(items):
        record = normalize_output_record(item, fallback_index=index)
        if not record or record['id'] in seen:
            continue
        seen.add(record['id'])
        normalized.append(record)
    return normalized


def remap_text_annotations(text: str, annotations: list) -> list[dict]:
    """Text comments keep start/end offsets plus the quoted text. After the user edits the
    output, re-find each quote (nearest occurrence to its old place). A quote that no
    longer exists keeps its comment but loses its highlight (start = end = 0)."""
    text = str(text or '')
    remapped = []
    for annotation in annotations or []:
        if not isinstance(annotation, dict):
            continue
        item = dict(annotation)
        if str(item.get('kind', '')) == 'text_span':
            quote = str(item.get('quote', '') or '')
            try:
                start = int(item.get('start', 0) or 0)
                end = int(item.get('end', start) or start)
            except (TypeError, ValueError):
                start = end = 0
            if quote and text[start:end] != quote:
                positions, cursor = [], text.find(quote)
                while cursor >= 0 and len(positions) < 200:
                    positions.append(cursor)
                    cursor = text.find(quote, cursor + 1)
                if positions:
                    best = min(positions, key=lambda position: abs(position - start))
                    item['start'], item['end'] = best, best + len(quote)
                else:
                    item['start'], item['end'] = 0, 0
        remapped.append(item)
    return remapped


def merge_output_records(existing: list, new_items: list) -> list[dict]:
    merged = normalize_output_records(existing)
    by_id = {item['id']: item for item in merged}
    for item in normalize_output_records(new_items):
        current = by_id.get(item['id'])
        if current and current.get('edited_at') and not item.get('edited_at'):
            # 同一个成品又被提取一次时，不能把用户手改过的内容和评论盖回原样。
            item = dict(item)
            for key in ('content', 'original_content', 'edited_at'):
                if key in current:
                    item[key] = current[key]
            if current.get('annotations') and not item.get('annotations'):
                item['annotations'] = current['annotations']
        by_id[item['id']] = item
    merged = list(by_id.values())
    merged.sort(key=lambda item: (str(item.get('created_at', '')), int(item.get('assistant_index', -1))), reverse=False)
    return merged


def agent_quick_annotation_labels() -> set[str]:
    return {item['label'] for item in AGENT_QUICK_ANNOTATIONS}


def agent_annotation_color_for_label(label: str) -> str:
    label = str(label or '').strip()
    for item in AGENT_QUICK_ANNOTATIONS:
        if item['label'] == label:
            return item['color']
    return AGENT_COMMENT_ANNOTATION_COLOR


def normalize_agent_annotation_record(item: dict,
                                      fallback_index: int = 0,
                                      message_count: int | None = None) -> dict | None:
    if not isinstance(item, dict):
        return None
    try:
        message_index = int(item.get('message_index', -1))
        start = int(item.get('start', -1))
        end = int(item.get('end', -1))
    except (TypeError, ValueError):
        return None
    if message_index < 0 or start < 0 or end <= start:
        return None
    if message_count is not None and message_index >= max(0, int(message_count)):
        return None
    annotation_type = str(item.get('type', '') or '').strip().lower()
    label = str(item.get('label', '') or '').strip()
    quick_labels = agent_quick_annotation_labels()
    if annotation_type == 'quick':
        if label not in quick_labels:
            return None
        comment = str(item.get('comment', '') or '').strip()
    elif annotation_type == 'favorite':
        # 收藏高亮：不需要 comment，颜色固定淡黄，正文渲染成背景色而非下划线。
        label = ''
        comment = str(item.get('comment', '') or '').strip()
    else:
        annotation_type = 'comment'
        comment = str(item.get('comment', '') or '').strip()
        if not comment:
            return None
        label = ''
    default_color = (
        AGENT_FAVORITE_ANNOTATION_COLOR
        if annotation_type == 'favorite'
        else agent_annotation_color_for_label(label)
    )
    color = str(item.get('color', '') or '').strip() or default_color
    if not QColor(color).isValid():
        color = default_color
    created_at = str(item.get('created_at', '') or '').strip() or datetime.datetime.now().isoformat(timespec='seconds')
    updated_at = str(item.get('updated_at', '') or '').strip() or created_at
    annotation_id = str(item.get('id', '') or '').strip()
    if not annotation_id:
        annotation_id = stable_legacy_agent_annotation_id(
            {
                **item,
                'message_index': message_index,
                'start': start,
                'end': end,
                'type': annotation_type,
                'label': label,
                'comment': comment,
                'created_at': created_at,
            },
            fallback_index,
        )
    return {
        'id': annotation_id,
        'message_index': message_index,
        'start': start,
        'end': end,
        'quote': str(item.get('quote', '') or ''),
        'type': annotation_type,
        'label': label,
        'color': color,
        'comment': comment,
        'created_at': created_at,
        'updated_at': updated_at,
    }


def normalize_agent_annotation_records(items, message_count: int | None = None) -> list[dict]:
    normalized = []
    seen = set()
    if not isinstance(items, list):
        return normalized
    for index, item in enumerate(items):
        record = normalize_agent_annotation_record(item, index, message_count=message_count)
        if not record or record['id'] in seen:
            continue
        seen.add(record['id'])
        normalized.append(record)
    normalized.sort(key=lambda ann: (int(ann.get('message_index', 0)), int(ann.get('start', 0)), str(ann.get('created_at', ''))))
    return normalized


def normalize_agent_saved_comment_text(text: str) -> str:
    return re.sub(r'\s+', ' ', str(text or '')).strip()


def agent_comment_menu_preview(text: str, max_chars: int = 48) -> str:
    compact = normalize_agent_saved_comment_text(text)
    limit = max(8, int(max_chars))
    if len(compact) <= limit:
        return compact
    return compact[:max(1, limit - 3)].rstrip() + '...'


def _new_agent_saved_comment_template_id() -> str:
    return f'agent-comment-template-{time.time_ns()}'


def normalize_agent_saved_comment_template_record(item, fallback_index: int = 0) -> dict | None:
    if isinstance(item, dict):
        text = str(item.get('text', '') or '').strip()
        created_at = str(item.get('created_at', '') or '').strip()
        updated_at = str(item.get('updated_at', '') or '').strip()
        template_id = str(item.get('id', '') or '').strip()
    else:
        text = str(item or '').strip()
        created_at = ''
        updated_at = ''
        template_id = ''
    if not normalize_agent_saved_comment_text(text):
        return None
    now = datetime.datetime.now().isoformat(timespec='seconds')
    if not created_at:
        created_at = now
    if not updated_at:
        updated_at = created_at
    if not template_id:
        seed = f'{fallback_index}-{normalize_agent_saved_comment_text(text)[:80]}-{created_at}'
        template_id = f'agent-comment-template-{abs(hash(seed))}'
    return {
        'id': template_id,
        'text': text,
        'created_at': created_at,
        'updated_at': updated_at,
    }


def normalize_agent_saved_comment_templates(items) -> list[dict]:
    normalized = []
    seen_text = set()
    seen_ids = set()
    if not isinstance(items, list):
        return normalized
    for index, item in enumerate(items):
        record = normalize_agent_saved_comment_template_record(item, index)
        if not record:
            continue
        text_key = normalize_agent_saved_comment_text(record.get('text', ''))
        if not text_key or text_key in seen_text:
            continue
        record_id = str(record.get('id', '') or '').strip()
        if record_id in seen_ids:
            record['id'] = f'{record_id}-{index + 1}'
        seen_text.add(text_key)
        seen_ids.add(str(record.get('id', '') or '').strip())
        normalized.append(record)
    return normalized


def format_agent_annotations_prompt_block(annotations: list[dict], messages: list[dict] | None = None) -> str:
    normalized = normalize_agent_annotation_records(annotations, len(messages or []))
    if not normalized:
        return ''
    lines = [
        'User annotations for this conversation (highest-priority user feedback):',
        '- Manual comments are the most accurate source in this conversation and override model-generated text.',
        '- Quick labels are explicit user feedback. If text is marked "Error", treat that selected text as user-flagged wrong; do not plan to verify whether the user annotation itself is correct unless the user explicitly asks.',
        '',
    ]
    for index, annotation in enumerate(normalized, start=1):
        message_index = int(annotation.get('message_index', -1))
        role = ''
        timestamp = ''
        if messages and 0 <= message_index < len(messages):
            message = normalize_chat_history_message(messages[message_index]) or {}
            role = str(message.get('role', '') or '').strip()
            timestamp = str(message.get('timestamp', '') or '').strip()
        where = f'message_index={message_index}'
        if role:
            where += f', role={role}'
        if timestamp:
            where += f', timestamp={timestamp}'
        where += f", chars={int(annotation.get('start', 0))}-{int(annotation.get('end', 0))}"
        lines.append(f'[{index}] {where}')
        quote = str(annotation.get('quote', '') or '').strip()
        if quote:
            lines.append('Selected text:')
            lines.append(quote)
        if str(annotation.get('type', '') or '') == 'quick':
            lines.append(f'User quick label: "{str(annotation.get("label", "") or "").strip()}"')
        else:
            lines.append('User manual comment:')
            lines.append(str(annotation.get('comment', '') or '').strip())
        lines.append('')
    return '\n'.join(lines).strip()


def build_memory_retrieval_chunks(memory_text: str, memory_items: list[dict]) -> list[dict]:
    chunks = []
    permanent = str(memory_text or '').strip()
    if permanent:
        for chunk_index, chunk_text in enumerate(chunk_text_for_retrieval(permanent)):
            chunks.append(
                {
                    'id': f'perm-{chunk_index}',
                    'name': 'Permanent memory',
                    'text': chunk_text,
                    'display_text': f'Permanent memory\n{chunk_text}',
                }
            )
    for item_index, item in enumerate(normalize_memory_item_records(memory_items)):
        item_text = item['text']
        name = str(item.get('source_date', '')).strip() or f'Memory note {item_index + 1}'
        chunks.append(
            {
                'id': f'item-{item_index}',
                'name': name,
                'text': item_text,
                'display_text': f'{name}\n{item_text}',
            }
        )
    return chunks


def build_memory_context_block(relevant_chunks: list[dict]) -> str:
    if not relevant_chunks:
        return ''
    blocks = []
    for index, chunk in enumerate(relevant_chunks, start=1):
        blocks.append(
            f"[Relevant memory {index} — {chunk.get('name', 'Memory')}]\n"
            f"{chunk.get('text', '').strip()}"
        )
    return 'Relevant saved memory:\n' + '\n\n'.join(block for block in blocks if block)


def build_saved_memory_context(question_text: str,
                               embedding_config: dict | None,
                               embedding_ok: bool) -> str:
    store = load_settings_store()
    globals_store = store.get('globals', {})
    # 从成品修改里学到的偏好：整节每次都带上（写作偏好和提问通常不相关，检索不到），
    # 也因此不再参与下面的分块检索，避免重复。
    memory_text, learned_lines = split_learned_output_preferences(str(globals_store.get('memory_text', '')).strip())
    learned_block = learned_output_preferences_context(learned_lines)
    retrieved_block = _build_retrieved_memory_block(
        memory_text.strip(),
        normalize_memory_item_records(globals_store.get('memory_items', [])),
        question_text, embedding_config, embedding_ok,
    )
    return '\n\n'.join(block for block in (learned_block, retrieved_block) if block)


def _build_retrieved_memory_block(memory_text: str,
                                  memory_items: list[dict],
                                  question_text: str,
                                  embedding_config: dict | None,
                                  embedding_ok: bool) -> str:
    chunks = build_memory_retrieval_chunks(memory_text, memory_items)
    if not chunks:
        return ''

    relevant_chunks = []
    strategy = 'keyword'
    keyword_candidates = keyword_retrieve_attachment_chunks(
        chunks,
        question_text,
        top_k=ATTACHMENT_RETRIEVAL_CANDIDATE_K,
    )
    if embedding_ok and embedding_config is not None and keyword_candidates:
        try:
            relevant_chunks = retrieve_attachment_chunks(
                keyword_candidates,
                question_text,
                embedding_config['api_key'],
                embedding_config['endpoint'],
                embedding_config['timeout'],
                embedding_config['model'],
                min_cosine=retrieval_min_cosine('memory'),
            )
            strategy = 'keyword+embedding'
        except Exception:
            relevant_chunks = []
    if not relevant_chunks:
        relevant_chunks = keyword_candidates[:ATTACHMENT_RETRIEVAL_TOP_K]
        strategy = 'keyword'

    # print_retrieval_debug('memory', strategy, question_text, relevant_chunks)

    return build_memory_context_block(relevant_chunks)


def format_conversation_updated_label(updated_at: str) -> str:
    try:
        dt = datetime.datetime.fromisoformat(updated_at)
        return _tr('Updated {time}').format(time=dt.strftime('%Y-%m-%d %H:%M'))
    except Exception:
        return _tr('Updated recently')


def format_unified_history_subtitle(record: dict) -> str:
    updated = format_conversation_updated_label(str((record or {}).get('updated_at', '') or ''))
    if not ICLOUD_M7_UNIFIED_HISTORY_ENABLED:
        return updated
    unknown = _tr('unknown')
    source = str((record or {}).get('source_device_id', '') or unknown)
    executor = str((record or {}).get('last_executor_device_id', '') or (record or {}).get('owner_device_id', '') or unknown)
    # Display labels for the stored sync_status codes (codes themselves stay English).
    raw_sync_status = str((record or {}).get('sync_status', '') or 'unknown')
    sync_status = {
        'local': _tr('local'), 'synced': _tr('synced'), 'conflict': _tr('conflict'),
        'local_ahead': _tr('local ahead'), 'cloud_newer': _tr('cloud newer'),
        'cloud_only': _tr('cloud only'), 'local_only': _tr('local only'), 'unknown': unknown,
    }.get(raw_sync_status, raw_sync_status.replace('_', ' '))
    if bool((record or {}).get('profile_fallback', False)):
        template = _tr('{updated} · From {source} · Last ran on {executor} · {status} · Default Profile fallback')
    else:
        template = _tr('{updated} · From {source} · Last ran on {executor} · {status}')
    return template.format(updated=updated, source=source, executor=executor, status=sync_status)


def sanitize_conversation_title(title: str, max_len: int = 48) -> str:
    text = re.sub(r'\s+', ' ', str(title or '').strip())
    if not text:
        return 'Untitled chat'
    return text[:max_len].rstrip()


def sanitize_conversation_filename(title: str, max_len: int = 48) -> str:
    safe = sanitize_conversation_title(title, max_len=max_len)
    safe = re.sub(r'[\\/:*?"<>|]+', '-', safe)
    safe = re.sub(r'\s+', '-', safe).strip(' .-_')
    return safe or 'Untitled-chat'


def new_broccoli_uuid(prefix: str = '') -> str:
    token = str(uuid.uuid4()) if ICLOUD_M1A_UUID_IDS_ENABLED else datetime.datetime.now().strftime('%Y%m%d-%H%M%S-%f')
    return f'{str(prefix or "")}{token}'


def allocate_conversation_identity(title: str) -> tuple[str, str]:
    """Reserve a unique conversation id/path before the async writer runs."""
    ensure_broccoli_data_dir()
    clean_title = sanitize_conversation_title(title)
    for _attempt in range(256):
        convo_id = new_broccoli_uuid()
        filename = f'{convo_id}_{sanitize_conversation_filename(clean_title)}.json'
        path = os.path.join(CONVERSATIONS_DIR, filename)
        attachment_dir = os.path.join(CONVERSATIONS_DIR, f'{convo_id}_attachments')
        with _CONVERSATION_RECORD_CACHE_LOCK:
            already_reserved = convo_id in _CONVERSATION_ID_RESERVATIONS
            if not already_reserved and not os.path.exists(path) and not os.path.exists(attachment_dir):
                if not any(Path(CONVERSATIONS_DIR).glob(f'{convo_id}_*.json')):
                    _CONVERSATION_ID_RESERVATIONS.add(convo_id)
                    return convo_id, path
    raise RuntimeError('Unable to allocate a unique Broccoli conversation id.')


def new_agent_annotation_id() -> str:
    return new_broccoli_uuid('agent-ann-')


def stable_legacy_agent_annotation_id(item: dict, fallback_index: int = 0) -> str:
    def _integer(key: str) -> int:
        try:
            return int(item.get(key, -1))
        except (TypeError, ValueError):
            return -1

    payload = {
        'message_index': _integer('message_index'),
        'start': _integer('start'),
        'end': _integer('end'),
        'quote': str(item.get('quote', '') or ''),
        'type': str(item.get('type', '') or ''),
        'label': str(item.get('label', '') or ''),
        'comment': str(item.get('comment', '') or ''),
        'created_at': str(item.get('created_at', '') or ''),
        'fallback_index': int(fallback_index),
    }
    seed = json.dumps(payload, ensure_ascii=False, sort_keys=True, separators=(',', ':'))
    return f'agent-ann-{uuid.uuid5(uuid.NAMESPACE_URL, "broccoli-agent-annotation:" + seed)}'


def conversation_attachment_dir(conversation_path: str) -> str:
    convo_id = Path(conversation_path).stem.split('_', 1)[0]
    return os.path.join(CONVERSATIONS_DIR, f'{convo_id}_attachments')


def agent_step_archive_root(conversation_path: str) -> str:
    if str(conversation_path or '').strip():
        root = os.path.join(conversation_attachment_dir(conversation_path), 'agent_steps')
    else:
        root = os.path.join(BROCCOLI_APP_DATA_DIR, 'SpecializedOutputs', 'agent_steps')
    os.makedirs(root, exist_ok=True)
    return root


def _agent_step_archive_slug(value: str, fallback: str = 'run') -> str:
    slug = re.sub(r'[^a-zA-Z0-9_-]+', '-', str(value or '')).strip('-')
    return slug or fallback


def agent_step_archive_run_dir(conversation_path: str, run_id: str) -> str:
    fallback = datetime.datetime.now().strftime('%Y%m%d-%H%M%S-%f')
    run_dir = os.path.join(agent_step_archive_root(conversation_path), _agent_step_archive_slug(run_id, fallback))
    os.makedirs(run_dir, exist_ok=True)
    return run_dir


def _archive_safe(fn, *args, **kwargs):
    try:
        return fn(*args, **kwargs)
    except BaseException:
        return None


def _archive_write_text(path: str, text: str) -> None:
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, 'w', encoding='utf-8', newline='\n') as handle:
        handle.write(str(text or ''))


def _archive_write_json(path: str, value) -> None:
    _archive_write_text(path, json.dumps(value, ensure_ascii=False, indent=2))


def _archive_clip_line(value, limit: int) -> str:
    return re.sub(r'\s+', ' ', str(value or '')).strip()[:max(0, int(limit or 0))]


def _archive_output_with_cap(text: str) -> tuple[str, bool]:
    raw = str(text or '')
    encoded = raw.encode('utf-8')
    if len(encoded) <= AGENT_STEP_ARCHIVE_FILE_CAP:
        return raw, False
    marker = '\n\n[Archive output truncated at 2 MB; tail omitted.]\n'
    budget = max(0, AGENT_STEP_ARCHIVE_FILE_CAP - len(marker.encode('utf-8')))
    clipped = encoded[:budget].decode('utf-8', errors='ignore')
    return clipped + marker, True


def write_step_archive_entry(run_dir: str, step_index, result: dict, extra: dict | None = None) -> dict | None:
    try:
        result = result if isinstance(result, dict) else {}
        extra = extra if isinstance(extra, dict) else {}
        capability = str(result.get('capability', '') or extra.get('capability', '') or 'step').strip()
        step_token = _agent_step_archive_slug(str(step_index), '00')
        step_dir = os.path.join(run_dir, f'step-{step_token}-{_agent_step_archive_slug(capability, "step")}')
        os.makedirs(step_dir, exist_ok=True)
        output_text = str(result.get('text_output', '') or '')
        context_output = str(result.get('context_output', '') or '')
        output_saved, truncated = _archive_output_with_cap(output_text)
        output_path = os.path.abspath(os.path.join(step_dir, 'output.md'))
        _archive_write_text(output_path, output_saved)
        reviewed_path = ''
        if context_output and context_output != output_text:
            reviewed_saved, reviewed_truncated = _archive_output_with_cap(context_output)
            reviewed_path = os.path.abspath(os.path.join(step_dir, 'reviewed.md'))
            _archive_write_text(reviewed_path, reviewed_saved)
            truncated = truncated or reviewed_truncated
        metadata = dict(result.get('metadata') or {})
        review = metadata.get('step_review') if isinstance(metadata.get('step_review'), dict) else {}
        skipped = bool(metadata.get('skipped_reason')) or str(extra.get('status', '') or '') == 'skipped'
        if skipped:
            status = 'skipped'
        elif review:
            status = 'finished' if bool(review.get('meets_goal', False)) else 'failed'
        else:
            status = 'finished' if output_text.strip() else 'failed'
        artifacts = [os.path.abspath(str(path)) for path in (result.get('artifacts') or []) if str(path or '').strip()]
        sources = metadata.get('sources') if isinstance(metadata.get('sources'), list) else []
        digest_source = context_output or output_text
        digest = _archive_clip_line(digest_source, AGENT_STEP_ARCHIVE_DIGEST_CHARS)
        now = datetime.datetime.now().isoformat(timespec='seconds')
        meta = {
            'capability': capability,
            'capability_label': str(result.get('capability_label', '') or ''),
            'goal': str(metadata.get('goal', '') or extra.get('goal', '') or ''),
            'model_name': str(result.get('model_name', '') or ''),
            'status': status,
            'meets_goal': bool(review.get('meets_goal', False)) if review else None,
            'review_summary': specialized_step_review_summary(result),
            'sources': [str(item) for item in sources],
            'artifacts': artifacts,
            'output_chars': len(output_text),
            'reviewed_chars': len(context_output),
            'truncated': bool(truncated),
            'created_at': str(extra.get('created_at', '') or now),
            'updated_at': now,
            'digest': digest,
            'output_path': output_path,
            'reviewed_path': reviewed_path,
        }
        meta_path = os.path.abspath(os.path.join(step_dir, 'meta.json'))
        _archive_write_json(meta_path, meta)
        return {'step': str(step_index), 'step_dir': os.path.abspath(step_dir), 'meta_path': meta_path, **meta}
    except BaseException:
        return None


def rewrite_step_archive_manifest(run_dir: str, run_info: dict, entries: list[dict]) -> None:
    clean_entries = [dict(entry) for entry in (entries or []) if isinstance(entry, dict)]
    payload = {'run': dict(run_info or {}), 'entries': clean_entries}
    _archive_write_json(os.path.join(run_dir, 'manifest.json'), payload)
    lines = [f'# Agent step archive: {str((run_info or {}).get("run_id", "") or Path(run_dir).name)}', '']
    for entry in clean_entries:
        artifacts = ', '.join(str(path) for path in (entry.get('artifacts') or [])) or 'none'
        meets = entry.get('meets_goal')
        meets_text = 'unknown' if meets is None else ('yes' if meets else 'no')
        trunc = ' [truncated]' if entry.get('truncated') else ''
        lines.append(
            f'- {Path(str(entry.get("step_dir", "step"))).name}'
            f' | goal: {_archive_clip_line(entry.get("goal", ""), 120)}'
            f' | status: {entry.get("status", "")}'
            f' | meets_goal: {meets_text}'
            f' | digest: {_archive_clip_line(entry.get("digest", ""), AGENT_STEP_ARCHIVE_DIGEST_CHARS)}'
            f' | output: {entry.get("output_path", "")} ({int(entry.get("output_chars", 0) or 0):,} chars){trunc}'
            f' | artifacts: {artifacts}'
        )
    _archive_write_text(os.path.join(run_dir, 'MANIFEST.md'), '\n'.join(lines).rstrip() + '\n')


def _agent_step_archive_run_dirs(conversation_path: str, limit: int | None = None) -> list[str]:
    try:
        root = agent_step_archive_root(conversation_path)
        dirs = [str(path) for path in Path(root).iterdir() if path.is_dir()]
        dirs.sort(key=lambda path: os.path.getmtime(path), reverse=True)
        return dirs[:limit] if limit is not None else dirs
    except BaseException:
        return []


def build_step_archive_manifest_block(conversation_path: str, run_dirs: list[str] | None = None,
                                      max_chars: int = AGENT_STEP_ARCHIVE_MANIFEST_PROMPT_CHARS) -> str:
    lines = []
    for run_dir in (run_dirs if run_dirs is not None else _agent_step_archive_run_dirs(conversation_path)):
        path = os.path.join(str(run_dir), 'MANIFEST.md')
        try:
            with open(path, 'r', encoding='utf-8', errors='replace') as handle:
                current = [line.rstrip() for line in handle if line.strip()]
        except OSError:
            continue
        lines.extend(current)
    if not lines:
        return ''
    header = 'Archived step catalog (newest runs first):\n'
    body_lines = list(lines)
    omitted = False
    while body_lines and len(header + '\n'.join(body_lines)) > max_chars:
        body_lines.pop(0)
        omitted = True
    marker = '[...older steps omitted...]\n' if omitted else ''
    return (header + marker + '\n'.join(body_lines))[:max_chars].rstrip()


def prune_agent_step_archives(conversation_path: str, current_run_dir: str = '') -> None:
    root = agent_step_archive_root(conversation_path)
    dirs = [str(path) for path in Path(root).iterdir() if path.is_dir()]
    dirs.sort(key=lambda path: os.path.getmtime(path), reverse=True)
    for old in dirs[AGENT_STEP_ARCHIVE_KEEP_RUNS:]:
        shutil.rmtree(old, ignore_errors=True)
    dirs = [path for path in dirs[:AGENT_STEP_ARCHIVE_KEEP_RUNS] if os.path.isdir(path)]
    def tree_size(path):
        total = 0
        for base, _dirs, files in os.walk(path):
            for name in files:
                try:
                    total += os.path.getsize(os.path.join(base, name))
                except OSError:
                    pass
        return total
    total = sum(tree_size(path) for path in dirs)
    for old in reversed(dirs):
        if total <= AGENT_STEP_ARCHIVE_MAX_BYTES:
            break
        if os.path.realpath(old) == os.path.realpath(current_run_dir or ''):
            continue
        size = tree_size(old)
        shutil.rmtree(old, ignore_errors=True)
        total -= size


def append_step_archive_stream(run_dir: str, step_slug: str, text: str) -> None:
    if not run_dir or not text:
        return
    live_dir = os.path.join(run_dir, 'live')
    os.makedirs(live_dir, exist_ok=True)
    path = os.path.join(live_dir, _agent_step_archive_slug(step_slug, 'step') + '.stream.log')
    try:
        current = os.path.getsize(path)
    except OSError:
        current = 0
    if current >= AGENT_STEP_ARCHIVE_FILE_CAP:
        return
    data = str(text).encode('utf-8')[:max(0, AGENT_STEP_ARCHIVE_FILE_CAP - current)]
    with open(path, 'ab') as handle:
        handle.write(data)


def _archive_path_is_within(path: str, root: str) -> bool:
    try:
        real_path = os.path.realpath(path)
        real_root = os.path.realpath(root)
        return os.path.commonpath([real_path, real_root]) == real_root
    except (OSError, ValueError):
        return False


def _archive_artifact_whitelist(conversation_path: str) -> set[str]:
    allowed = set()
    for run_dir in _agent_step_archive_run_dirs(conversation_path):
        try:
            with open(os.path.join(run_dir, 'manifest.json'), 'r', encoding='utf-8') as handle:
                payload = json.load(handle)
        except (OSError, ValueError, TypeError):
            continue
        for entry in payload.get('entries', []) if isinstance(payload, dict) else []:
            if not isinstance(entry, dict):
                continue
            for path in entry.get('artifacts', []) or []:
                if str(path or '').strip():
                    allowed.add(os.path.realpath(str(path)))
    return allowed


def validate_agent_step_archive_path(conversation_path: str, path: str) -> tuple[bool, str]:
    candidate = os.path.realpath(str(path or ''))
    root = agent_step_archive_root(conversation_path)
    if _archive_path_is_within(candidate, root):
        return True, candidate
    if candidate in _archive_artifact_whitelist(conversation_path):
        return True, candidate
    return False, candidate


def _archive_text_files(conversation_path: str) -> list[str]:
    root = agent_step_archive_root(conversation_path)
    found = []
    for base, _dirs, files in os.walk(root):
        for name in files:
            if name in {'output.md', 'reviewed.md'} or name.endswith('.stream.log'):
                found.append(os.path.join(base, name))
    return sorted(found)


def _archive_goal_for_path(path: str) -> str:
    meta_path = os.path.join(os.path.dirname(path), 'meta.json')
    try:
        with open(meta_path, 'r', encoding='utf-8') as handle:
            return _archive_clip_line((json.load(handle) or {}).get('goal', ''), 120)
    except (OSError, ValueError, TypeError):
        return ''


def search_agent_step_archives(conversation_path: str, query: str,
                               top_k: int = ARCHIVE_SEARCH_TOP_K) -> str:
    files = _archive_text_files(conversation_path)
    chunks = []
    overlap = 200
    for path in files:
        try:
            with open(path, 'r', encoding='utf-8', errors='replace') as handle:
                content = handle.read()
        except OSError:
            continue
        start = 0
        while start < len(content):
            end = min(len(content), start + ARCHIVE_SEARCH_CHUNK_CHARS)
            chunks.append({
                'text': content[start:end], 'path': os.path.abspath(path),
                'start_char': start, 'end_char': end, 'goal': _archive_goal_for_path(path),
            })
            if end >= len(content):
                break
            start = max(start + 1, end - overlap)
    terms = _keyword_query_terms(query)
    ranked = _rank_keyword_chunks(chunks, terms, max(1, min(int(top_k or ARCHIVE_SEARCH_TOP_K), ARCHIVE_SEARCH_TOP_K)))
    if not ranked and query_contains_cjk(query):
        translated_terms = _keyword_query_terms(translate_query_to_english_keywords(query))
        merged = terms + [term for term in translated_terms if term not in terms]
        ranked = _rank_keyword_chunks(chunks, merged, max(1, min(int(top_k or ARCHIVE_SEARCH_TOP_K), ARCHIVE_SEARCH_TOP_K)))
        terms = merged
    if not ranked:
        run_names = ', '.join(Path(path).name for path in _agent_step_archive_run_dirs(conversation_path)) or 'none'
        return (
            f'Archive search: NO matches for terms [{", ".join(terms)}] across {len(files)} files '
            f'(run dirs: {run_names}). Do not search again; proceed and report the gap.'
        )
    lines = [f'Archive search results for "{query}" ({len(ranked)} of {min(int(top_k or ARCHIVE_SEARCH_TOP_K), ARCHIVE_SEARCH_TOP_K)} slots used):']
    for index, chunk in enumerate(ranked, start=1):
        excerpt = str(chunk.get('text', '') or '')[:ARCHIVE_SEARCH_EXCERPT_CHARS]
        goal = f', step goal: {chunk.get("goal", "")}' if chunk.get('goal') else ''
        lines.append(
            f'{index}. {chunk.get("path")} (chars {chunk.get("start_char")}–{chunk.get("end_char")}{goal}):\n{excerpt}'
        )
    return '\n'.join(lines)


def make_agent_step_archive_reader(conversation_path: str):
    state = {'served': 0, 'seen': set()}

    def reader(request: dict) -> str:
        if not isinstance(request, dict):
            return 'Archive read request error: expected one JSON object with "query" or "paths".'
        if str(request.get('query', '') or '').strip():
            query = str(request.get('query', '') or '').strip()
            try:
                top_k = max(1, min(int(request.get('top_k', ARCHIVE_SEARCH_TOP_K) or ARCHIVE_SEARCH_TOP_K), ARCHIVE_SEARCH_TOP_K))
            except (TypeError, ValueError):
                top_k = ARCHIVE_SEARCH_TOP_K
            normalized_terms = tuple(sorted(_keyword_query_terms(query)))
            key = ('query', normalized_terms or (re.sub(r'\s+', ' ', query.lower()),), top_k)
            if key in state['seen']:
                return 'Archive read request already answered; do not repeat it. Proceed with the prior result.'
            state['seen'].add(key)
            feedback = search_agent_step_archives(conversation_path, query, top_k)
            remaining = max(0, AGENT_STEP_ARCHIVE_READ_BUDGET - state['served'])
            feedback = feedback[:remaining]
            state['served'] += len(feedback)
            return feedback or 'Archive read budget exhausted; proceed and report the gap.'
        raw_paths = request.get('paths')
        if not isinstance(raw_paths, list) or not raw_paths:
            return 'Archive read request error: provide a non-empty "query" or "paths" list.'
        try:
            offset = max(0, int(request.get('offset', 0) or 0))
        except (TypeError, ValueError):
            offset = 0
        try:
            max_chars = max(1, min(int(request.get('max_chars', 20000) or 20000), 20000))
        except (TypeError, ValueError):
            max_chars = 20000
        normalized_paths = tuple(sorted(os.path.realpath(str(path or '')) for path in raw_paths))
        key = ('paths', normalized_paths, offset, max_chars)
        if key in state['seen']:
            return 'Archive read request already answered; do not repeat it. Proceed with the prior result.'
        state['seen'].add(key)
        remaining = max(0, min(max_chars, AGENT_STEP_ARCHIVE_READ_BUDGET - state['served']))
        lines = ['Archive read result:']
        for raw_path in raw_paths:
            valid, path = validate_agent_step_archive_path(conversation_path, str(raw_path or ''))
            if not valid:
                lines.append(f'{path}: rejected (outside this conversation archive and artifact whitelist).')
                continue
            if remaining <= 0:
                lines.append(f'{path}: archive read budget exhausted.')
                continue
            if Path(path).suffix.lower() not in {'.md', '.txt', '.log', '.json', '.csv', '.yaml', '.yml'}:
                lines.append(f'{path}: binary artifact; inspect its archived meta.json reference instead of reading bytes.')
                continue
            try:
                with open(path, 'r', encoding='utf-8', errors='replace') as handle:
                    content = handle.read()
            except OSError as exc:
                lines.append(f'{path}: read failed ({exc}).')
                continue
            piece = content[offset:offset + remaining]
            end = offset + len(piece)
            paging = '; request again with "offset" for more' if end < len(content) else ''
            lines.append(f'{path} (chars {offset}–{end} of {len(content)}{paging}):\n{piece}')
            remaining -= len(piece)
            state['served'] += len(piece)
        return '\n'.join(lines)

    reader.state = state
    return reader


def build_agent_step_archive_preload(conversation_path: str, refs, max_chars: int = AGENT_STEP_ARCHIVE_PRELOAD_CHARS) -> str:
    remaining = max(0, int(max_chars or 0))
    blocks = []
    for ref in list(refs or [])[:4]:
        valid, path = validate_agent_step_archive_path(conversation_path, str(ref or ''))
        if not valid or remaining <= 0:
            continue
        try:
            with open(path, 'r', encoding='utf-8', errors='replace') as handle:
                content = handle.read()
        except OSError:
            continue
        piece = content[:remaining]
        blocks.append(f'{path} (chars 0–{len(piece)} of {len(content)}):\n{piece}')
        remaining -= len(piece)
    return '\n\n'.join(blocks)


def extract_archive_read_request(text: str) -> dict | None:
    match = re.search(r'```broccoli_archive_read\s*\n?(.*?)```', str(text or ''), flags=re.IGNORECASE | re.DOTALL)
    if not match:
        return None
    parsed = parse_json_object_from_text(match.group(1))
    return parsed if isinstance(parsed, dict) else {}


def _copy_attachment_into_conversation(conversation_path: str, source_path: str) -> tuple[str, str]:
    attach_dir = conversation_attachment_dir(conversation_path)
    os.makedirs(attach_dir, exist_ok=True)
    source = Path(source_path)
    safe_name = sanitize_conversation_filename(source.stem, max_len=72)
    suffix = source.suffix.lower()
    base_name = f"{datetime.datetime.now().strftime('%Y%m%d-%H%M%S-%f')}_{safe_name}{suffix}"
    target_path = os.path.join(attach_dir, base_name)
    counter = 2
    while os.path.exists(target_path):
        target_path = os.path.join(attach_dir, f"{datetime.datetime.now().strftime('%Y%m%d-%H%M%S-%f')}_{safe_name}-{counter}{suffix}")
        counter += 1
    shutil.copy2(source_path, target_path)
    return target_path, os.path.relpath(target_path, os.path.dirname(conversation_path))


def persist_conversation_attachments(conversation_path: str, attachment_items: list[dict]) -> tuple[list, list, list]:
    direct_attachments = []
    retrieval_documents = []
    saved_records = []
    for item in attachment_items:
        path = str(item.get('path', '')).strip()
        if not path or not os.path.exists(path):
            continue
        use_embedding = bool(item.get('use_embedding'))
        stored_path, stored_rel_path = _copy_attachment_into_conversation(conversation_path, path)
        ext = os.path.splitext(path)[1].lower()
        kind = 'image' if ext in ATTACHMENT_IMAGE_EXTS else ext.lstrip('.') or 'file'
        record = {
            'name': os.path.basename(path),
            'original_path': path,
            'stored_path': stored_path,
            'stored_rel_path': stored_rel_path,
            'kind': kind,
            'use_embedding': use_embedding,
        }

        extracted = None
        # Parse the attachment to TEXT at add-time (before any reasoning), for every type:
        # text PDFs/docs -> text extraction; image PDFs/screenshots/images -> macOS Vision OCR.
        # allow_ocr=True so image-only files also yield text. Done once here, then carried.
        if attachment_supports_embedding(path) or ext in ATTACHMENT_IMAGE_EXTS:
            extracted = extract_attachment_text(path, allow_ocr=True, limit_chars=None if use_embedding else 512 * 1024)
            if extracted and extracted.get('content', '').strip():
                record['extracted_text'] = extracted['content']
                if extracted.get('via_ocr'):
                    record['via_ocr'] = True
        # Mark "image-based" (an image, or a PDF with no text layer that we OCR'd) so it can
        # also be re-sent as page image(s) on demand when you actually need to SEE it.
        if kind == 'image' or (extracted and extracted.get('via_ocr')):
            record['image_based'] = True

        if use_embedding and extracted and extracted.get('content', '').strip():
            record['send_mode'] = 'retrieval_text'
            retrieval_chunks = build_attachment_retrieval_chunks([{'name': record['name'], 'content': extracted['content']}])
            if retrieval_chunks:
                record['retrieval_chunks'] = retrieval_chunks
            retrieval_documents.append({'name': record['name'], 'content': extracted['content']})
        else:
            encoded = _encode_attachment_file(path)
            if encoded:
                direct_attachments.append(encoded)
                if isinstance(encoded, list):
                    record['send_mode'] = 'image_direct' if any(att.get('kind') == 'image' for att in encoded if isinstance(att, dict)) else 'file_direct'
                else:
                    record['send_mode'] = 'image_direct' if encoded.get('kind') == 'image' else 'text_direct'
            else:
                record['send_mode'] = 'file_direct'
        saved_records.append(record)
    return direct_attachments, retrieval_documents, saved_records


def conversation_title_from_messages(messages: list[dict], fallback: str = 'Untitled chat') -> str:
    for message in messages:
        if message.get('role') == 'user':
            return sanitize_conversation_title(message.get('content', ''), max_len=48)
    return fallback


# A title the user gave (a rename) is marked in the record. Saves used to rebuild the title
# from the first question every time, so the first save after a rename (a follow-up, a run
# finishing) put the old name back on the tag and in the history (2026-10-26).
CONVERSATION_TITLE_USER_SET_KEY = 'title_user_set'


def conversation_title_for_save(record: dict, messages: list[dict], fallback: str) -> str:
    """The title a save writes: the user's own stays; otherwise the first question."""
    title = str((record or {}).get('title', '') or '').strip()
    if title and (record or {}).get(CONVERSATION_TITLE_USER_SET_KEY):
        return title
    return conversation_title_from_messages(messages, fallback=fallback)


def conversation_turns_from_messages(messages: list[dict]) -> list[dict]:
    turns = []
    pending_question = None
    for message in messages:
        role = message.get('role')
        if role == 'user':
            pending_question = {
                'question': render_message_plaintext(message),
                'question_time': message.get('timestamp', ''),
                'answer': '',
                'answer_time': '',
            }
            turns.append(pending_question)
            continue
        if role == 'assistant':
            if pending_question is None:
                pending_question = {
                    'question': '',
                    'question_time': '',
                    'answer': render_message_plaintext(message),
                    'answer_time': message.get('timestamp', ''),
                }
                turns.append(pending_question)
            else:
                pending_question['answer'] = render_message_plaintext(message)
                pending_question['answer_time'] = message.get('timestamp', '')
            pending_question = None
    return turns


def chunk_text_for_retrieval(text: str,
                             max_chars: int = CONVERSATION_RETRIEVAL_CHARS,
                             overlap: int = CONVERSATION_RETRIEVAL_OVERLAP) -> list[str]:
    content = str(text or '').strip()
    if not content:
        return []
    if len(content) <= max_chars:
        return [content]
    chunks = []
    start = 0
    text_len = len(content)
    while start < text_len:
        end = min(text_len, start + max_chars)
        chunk = content[start:end].strip()
        if chunk:
            chunks.append(chunk)
        if end >= text_len:
            break
        start = max(0, end - overlap)
    return chunks


def build_retrieval_chunks(messages: list[dict]) -> list[dict]:
    chunks = []
    for message_index, message in enumerate(messages):
        role = message.get('role', '')
        label = 'Q' if role == 'user' else 'A'
        timestamp = message.get('timestamp', '')
        prefix = f'{label}'
        if timestamp:
            prefix += f' · {timestamp}'
        prefix += '\n'
        for chunk_index, chunk_text in enumerate(chunk_text_for_retrieval(message.get('content', ''))):
            chunks.append(
                {
                    'id': f'm{message_index}-c{chunk_index}',
                    'message_index': message_index,
                    'role': role,
                    'timestamp': timestamp,
                    'text': chunk_text,
                    'display_text': prefix + chunk_text,
                }
            )
        for attachment_index, attachment in enumerate(message.get('attachments', []) or []):
            attachment_name = str(attachment.get('name', 'Attachment')).strip() or 'Attachment'
            attachment_chunks = []
            if isinstance(attachment.get('retrieval_chunks'), list):
                attachment_chunks = [chunk for chunk in attachment['retrieval_chunks'] if isinstance(chunk, dict) and str(chunk.get('text', '')).strip()]
            elif str(attachment.get('extracted_text', '')).strip():
                attachment_chunks = [
                    {'id': f'm{message_index}-a{attachment_index}-c{chunk_index}', 'text': chunk_text}
                    for chunk_index, chunk_text in enumerate(chunk_text_for_retrieval(attachment['extracted_text']))
                ]
            for chunk_index, chunk in enumerate(attachment_chunks):
                chunk_text = str(chunk.get('text', '')).strip()
                if not chunk_text:
                    continue
                display_text = str(chunk.get('display_text', '')).strip() or f'Attachment · {attachment_name}\n{chunk_text}'
                chunk_id = str(chunk.get('id', '')).strip() or f'm{message_index}-a{attachment_index}-c{chunk_index}'
                chunks.append(
                    {
                        'id': chunk_id,
                        'message_index': message_index,
                        'role': role,
                        'timestamp': message.get('timestamp', ''),
                        'text': chunk_text,
                        'display_text': display_text,
                    }
                )
    return chunks


def normalize_retrieval_chunk(chunk: dict) -> dict | None:
    if not isinstance(chunk, dict):
        return None
    text = str(chunk.get('text', '')).strip()
    if not text:
        return None
    role = str(chunk.get('role', '')).strip().lower()
    if role not in {'user', 'assistant'}:
        role = 'assistant'
    timestamp = str(chunk.get('timestamp', '')).strip()
    try:
        message_index = int(chunk.get('message_index', 0))
    except (TypeError, ValueError):
        message_index = 0
    normalized = {
        'id': str(chunk.get('id', '')).strip() or f'{role}-{abs(hash(text))}',
        'message_index': message_index,
        'role': role,
        'timestamp': timestamp,
        'text': text,
        'display_text': str(chunk.get('display_text', '')).strip() or (
            ('Q' if role == 'user' else 'A') + (f' · {timestamp}' if timestamp else '') + '\n' + text
        ),
    }
    embedding = chunk.get('embedding')
    if isinstance(embedding, list):
        vector = []
        for item in embedding:
            try:
                vector.append(float(item))
            except (TypeError, ValueError):
                vector = []
                break
        if vector:
            normalized['embedding'] = vector
    return normalized


URL_EXTRACT_RE = re.compile(r'https?://[^\s<>"\']+')
HREF_EXTRACT_RE = re.compile(r'''href\s*=\s*["']([^"']+)["']''', re.IGNORECASE)


def clean_extracted_url(url: str) -> str:
    cleaned = str(url or '').strip()
    while cleaned and cleaned[-1] in '.,;:!?)]}>\'"':
        cleaned = cleaned[:-1]
    return cleaned


def extract_urls_from_text(text: str) -> list[str]:
    urls = []
    seen = set()
    for match in URL_EXTRACT_RE.findall(str(text or '')):
        url = clean_extracted_url(match)
        if not url or url in seen:
            continue
        seen.add(url)
        urls.append(url)
    return urls


def extract_urls_from_html_fragment(fragment: str) -> list[str]:
    urls = []
    seen = set()
    raw_fragment = str(fragment or '')
    for match in HREF_EXTRACT_RE.findall(raw_fragment):
        url = clean_extracted_url(html.unescape(match))
        if not url or not url.startswith(('http://', 'https://')) or url in seen:
            continue
        seen.add(url)
        urls.append(url)
    for url in extract_urls_from_text(html.unescape(raw_fragment)):
        if url in seen:
            continue
        seen.add(url)
        urls.append(url)
    return urls


def extract_urls_from_message(message: dict) -> list[str]:
    seen = set()
    urls = []
    for field in ('content', 'display_prefix_html'):
        value = str(message.get(field, '') or '')
        field_urls = extract_urls_from_html_fragment(value) if field == 'display_prefix_html' else extract_urls_from_text(value)
        for url in field_urls:
            if url in seen:
                continue
            seen.add(url)
            urls.append(url)
    return urls


def normalize_link_record(item: dict | str) -> dict | None:
    if isinstance(item, str):
        item = {'url': item}
    if not isinstance(item, dict):
        return None
    url = clean_extracted_url(item.get('url', ''))
    if not url:
        return None
    return {
        'url': url,
        'title': str(item.get('title', '')).strip(),
        'first_seen_at': str(item.get('first_seen_at', '')).strip(),
        'source': str(item.get('source', 'assistant')).strip() or 'assistant',
    }


def merge_conversation_links(existing_links: list, messages: list[dict], fallback_seen_at: str = '') -> list[dict]:
    merged = {}
    for item in existing_links or []:
        normalized = normalize_link_record(item)
        if normalized:
            merged[normalized['url']] = normalized

    for message in messages or []:
        if message.get('role') != 'assistant':
            continue
        seen_at = str(message.get('timestamp', '')).strip() or fallback_seen_at
        for url in extract_urls_from_message(message):
            existing = merged.get(url)
            if existing is not None:
                if not existing.get('first_seen_at'):
                    existing['first_seen_at'] = seen_at
                continue
            merged[url] = {
                'url': url,
                'title': '',
                'first_seen_at': seen_at,
                'source': 'assistant',
            }
    return list(merged.values())


def normalize_conversation_branch_data(branches: dict | None, messages: list[dict]) -> dict:
    valid_user_indices = {
        message_index
        for message_index, message in enumerate(messages or [])
        if str(message.get('role', '')).strip().lower() == 'user'
    }
    roots = []
    seen_indices = set()
    seen_ids = set()

    def unique_node_id(raw_id: str, message_index: int) -> str:
        base = str(raw_id or '').strip() or f'q{message_index + 1}'
        candidate = base
        suffix = 2
        while candidate in seen_ids:
            candidate = f'{base}_{suffix}'
            suffix += 1
        seen_ids.add(candidate)
        return candidate

    def normalize_node(node: dict) -> dict | None:
        if not isinstance(node, dict):
            return None
        try:
            message_index = int(node.get('message_index', -1))
        except (TypeError, ValueError):
            return None
        if message_index not in valid_user_indices or message_index in seen_indices:
            return None
        seen_indices.add(message_index)
        normalized = {
            'id': unique_node_id(node.get('id', ''), message_index),
            'message_index': message_index,
            'text': str(node.get('text', '')).strip(),
            'full_text': str(node.get('full_text', node.get('text', ''))).strip(),
            'checked': bool(node.get('checked', True)),
            'children': [],
        }
        for child in node.get('children', []) or []:
            normalized_child = normalize_node(child)
            if normalized_child is not None:
                normalized['children'].append(normalized_child)
        return normalized

    branch_payload = branches if isinstance(branches, dict) else {}
    for node in branch_payload.get('roots', []) or []:
        normalized = normalize_node(node)
        if normalized is not None:
            roots.append(normalized)

    for message_index in sorted(valid_user_indices):
        if message_index in seen_indices:
            continue
        roots.append({
            'id': unique_node_id('', message_index),
            'message_index': message_index,
            'text': '',
            'full_text': '',
            'children': [],
        })

    available_ids = set()

    def collect_ids(node: dict):
        available_ids.add(str(node.get('id', '')).strip())
        for child in node.get('children', []) or []:
            collect_ids(child)

    for root in roots:
        collect_ids(root)

    active_node_id = str(branch_payload.get('active_node_id', '')).strip()
    if active_node_id not in available_ids:
        active_node_id = ''

    return {
        'roots': roots,
        'active_node_id': active_node_id,
        'append_as_child': bool(branch_payload.get('append_as_child', False) and active_node_id),
    }


_CONVERSATION_CORE_KEYS = {
    'schema_version', 'revision', 'id', 'title', 'messages', 'created_at', 'updated_at',
    'rendered_markdown', 'display', 'memory', 'retrieval', 'links', 'outputs',
    'agent_annotations', 'webfetch', 'external_sessions', 'branches', 'extensions',
    'path', 'search_blob', '_retrieval_loaded', '_legacy_retrieval_present',
}
_CONVERSATION_INTERNAL_KEYS = {
    'path', 'search_blob', '_retrieval_loaded', '_legacy_retrieval_present',
}


def conversation_retrieval_sidecar_path(path: str) -> str:
    path = str(path or '')
    return path[:-5] + CONVERSATION_RETRIEVAL_SUFFIX if path.endswith('.json') else path + CONVERSATION_RETRIEVAL_SUFFIX


def conversation_derived_sidecar_path(path: str, conversation_id: str = '') -> str:
    path = str(path or '')
    convo_id = str(conversation_id or '').strip()
    if not convo_id:
        stem = Path(path).stem
        if stem.endswith('.derived'):
            stem = stem[:-8]
        convo_id = stem.split('_', 1)[0]
    return os.path.join(os.path.dirname(path) or CONVERSATIONS_DIR, f'{convo_id}{CONVERSATION_DERIVED_SUFFIX}')


def _read_conversation_retrieval_payload(path: str) -> dict:
    sidecar_path = conversation_retrieval_sidecar_path(path)
    if os.path.exists(sidecar_path):
        try:
            with open(sidecar_path, 'r', encoding='utf-8') as handle:
                payload = json.load(handle)
            return payload if isinstance(payload, dict) else {'chunks': []}
        except Exception:
            return {'chunks': []}
    with _CONVERSATION_RECORD_CACHE_LOCK:
        payload = _CONVERSATION_LAZY_RETRIEVAL.get(path)
        return copy.deepcopy(payload) if isinstance(payload, dict) else {'chunks': []}


def _read_conversation_derived_payload(path: str, conversation_id: str = '') -> dict:
    derived_path = conversation_derived_sidecar_path(path, conversation_id)
    if os.path.exists(derived_path):
        try:
            with open(derived_path, 'r', encoding='utf-8') as handle:
                payload = json.load(handle)
            if isinstance(payload, dict):
                return payload
        except Exception:
            pass
    legacy_retrieval = _read_conversation_retrieval_payload(path)
    return {'retrieval': legacy_retrieval} if isinstance(legacy_retrieval, dict) else {}


def _conversation_extensions_from_data(data: dict) -> dict:
    extensions = copy.deepcopy(data.get('extensions')) if isinstance(data.get('extensions'), dict) else {}
    for key, value in data.items():
        key_text = str(key or '')
        if key_text in _CONVERSATION_CORE_KEYS or key_text in _CONVERSATION_INTERNAL_KEYS or key_text.startswith('_'):
            continue
        extensions[key_text] = copy.deepcopy(value)
    return extensions


def normalize_conversation_record(data: dict, path: str, *, include_retrieval: bool = True) -> dict:
    ensure_broccoli_data_dir()
    data = data if isinstance(data, dict) else {}
    messages = []
    if isinstance(data.get('messages'), list):
        for item in data['messages']:
            normalized = normalize_chat_history_message(item)
            if normalized:
                messages.append(normalized)
    convo_id = str(data.get('id', Path(path).stem.split('_', 1)[0])).strip() or new_broccoli_uuid()
    try:
        schema_version = max(0, int(data.get('schema_version', 0) or 0))
    except (TypeError, ValueError):
        schema_version = 0
    try:
        revision = max(0, int(data.get('revision', 0) or 0))
    except (TypeError, ValueError):
        revision = 0
    title = sanitize_conversation_title(
        data.get('title', conversation_title_from_messages(messages, fallback=convo_id))
    )
    created_at = str(data.get('created_at', ''))
    updated_at = str(data.get('updated_at', created_at or datetime.datetime.now().isoformat(timespec='seconds')))
    derived = _read_conversation_derived_payload(path, convo_id) if ICLOUD_M1A_DERIVED_STORAGE_ENABLED else {}
    derived_display = derived.get('display') if isinstance(derived.get('display'), dict) else {}
    markdown = str(
        data.get('rendered_markdown')
        or derived.get('rendered_markdown')
        or render_chat_history_markdown(messages)
    )
    display = data.get('display') if isinstance(data.get('display'), dict) else derived_display
    memory = data.get('memory') if isinstance(data.get('memory'), dict) else {}
    inline_retrieval = data.get('retrieval') if isinstance(data.get('retrieval'), dict) else {}
    if isinstance(inline_retrieval.get('chunks'), list) and inline_retrieval.get('chunks'):
        with _CONVERSATION_RECORD_CACHE_LOCK:
            _CONVERSATION_LAZY_RETRIEVAL[path] = inline_retrieval
    retrieval = {}
    if include_retrieval:
        if inline_retrieval and bool(data.get('_retrieval_loaded', True)):
            retrieval = inline_retrieval
        elif isinstance(derived.get('retrieval'), dict):
            retrieval = derived.get('retrieval') or {}
        else:
            retrieval = _read_conversation_retrieval_payload(path)
    raw_outputs = data.get('outputs') if isinstance(data.get('outputs'), list) else []
    raw_links = data.get('links') if isinstance(data.get('links'), list) else []
    raw_agent_annotations = data.get('agent_annotations') if isinstance(data.get('agent_annotations'), list) else []
    display_turns = conversation_turns_from_messages(messages)
    normalized_chunks = []
    if include_retrieval and isinstance(retrieval.get('chunks'), list):
        for chunk in retrieval['chunks']:
            normalized_chunk = normalize_retrieval_chunk(chunk)
            if normalized_chunk:
                normalized_chunks.append(normalized_chunk)
    try:
        last_summarized_turn_count = max(0, int(memory.get('last_summarized_turn_count', 0) or 0))
    except (TypeError, ValueError):
        last_summarized_turn_count = 0
    normalized_links = merge_conversation_links(raw_links, messages, fallback_seen_at=updated_at)
    normalized_outputs = normalize_output_records(raw_outputs)
    normalized_agent_annotations = normalize_agent_annotation_records(raw_agent_annotations, len(messages))
    webfetch = data.get('webfetch') if isinstance(data.get('webfetch'), dict) else {}
    webfetch_attachments = collect_webfetch_attachments_from_messages(messages)
    if isinstance(webfetch.get('attachments'), list):
        for item in webfetch['attachments']:
            normalized = normalize_webfetch_attachment_record(item)
            if normalized is None:
                continue
            stored_path = str(normalized.get('stored_path', '')).strip()
            if stored_path and all(str(att.get('stored_path', '')).strip() != stored_path for att in webfetch_attachments):
                webfetch_attachments.append(normalized)
    normalized_branches = normalize_conversation_branch_data(data.get('branches'), messages)
    external_sessions = normalize_external_sessions(data.get('external_sessions'))
    normalized_memory = copy.deepcopy(memory)
    normalized_memory.update({
        'running_summary': str(memory.get('running_summary', '')).strip(),
        'last_summarized_turn_count': last_summarized_turn_count,
    })
    normalized_retrieval = copy.deepcopy(retrieval) if isinstance(retrieval, dict) else {}
    normalized_retrieval['chunks'] = normalized_chunks
    normalized_display = copy.deepcopy(display) if isinstance(display, dict) else {}
    normalized_display.update({
        'turns': display_turns,
        'rendered_markdown': str(display.get('rendered_markdown', markdown)),
    })
    extensions = _conversation_extensions_from_data(data) if ICLOUD_M1A_SCHEMA_PASSTHROUGH_ENABLED else {}
    normalized_record = {
        'schema_version': schema_version,
        'revision': revision,
        'id': convo_id,
        **({
            'identity': copy.deepcopy(data.get('identity'))
            if isinstance(data.get('identity'), dict)
            else (
                copy.deepcopy(extensions.get('identity'))
                if isinstance(extensions.get('identity'), dict)
                else local_conversation_identity()
            )
        } if ICLOUD_M1C_UNIFIED_FINALIZER_ENABLED else {}),
        'title': title,
        'messages': messages,
        'created_at': created_at or updated_at,
        'updated_at': updated_at,
        'rendered_markdown': markdown,
        'display': normalized_display,
        'memory': normalized_memory,
        'retrieval': normalized_retrieval,
        '_retrieval_loaded': bool(include_retrieval),
        '_legacy_retrieval_present': bool(inline_retrieval.get('chunks')),
        'links': normalized_links,
        'outputs': normalized_outputs,
        'agent_annotations': normalized_agent_annotations,
        'webfetch': {
            'attachments': webfetch_attachments,
        },
        'external_sessions': external_sessions,
        'branches': normalized_branches,
        'extensions': extensions,
        'path': path,
    }
    for key, value in extensions.items():
        if key not in normalized_record and key not in _CONVERSATION_INTERNAL_KEYS and not str(key).startswith('_'):
            normalized_record[key] = copy.deepcopy(value)
    return normalized_record


def _conversation_history_index_entry(record: dict) -> dict:
    messages = list(record.get('messages', []) or [])
    search_blob = '\n'.join(str(message.get('content', '') or '') for message in messages)
    attachment_blob = '\n'.join(
        '\n'.join(
            str(attachment.get('name', '')) + '\n' + str(attachment.get('extracted_text', ''))
            for attachment in (message.get('attachments') or [])
            if isinstance(attachment, dict)
        )
        for message in messages
        if isinstance(message, dict)
    )
    links_blob = '\n'.join(
        (str(link.get('title', '')).strip() + '\n' + str(link.get('url', '')).strip()).strip()
        for link in record.get('links', [])
        if isinstance(link, dict)
    )
    outputs_blob = '\n'.join(
        (
            str(output.get('title', '')).strip()
            + '\n' + str(output.get('content', '')).strip()
            + '\n' + str(output.get('path', '')).strip()
        ).strip()
        for output in record.get('outputs', [])
        if isinstance(output, dict)
    )
    running_summary = str(record.get('memory', {}).get('running_summary', '') or '').strip()
    combined = '\n'.join(
        part for part in (
            str(record.get('title', '') or ''),
            search_blob,
            attachment_blob,
            links_blob,
            outputs_blob,
            running_summary,
        ) if part
    ).lower()
    path = str(record.get('path', '') or '')
    try:
        mtime = os.path.getmtime(path) if path and os.path.exists(path) else 0.0
    except Exception:
        mtime = 0.0
    identity = record.get('identity') if isinstance(record.get('identity'), dict) else {}
    extensions = record.get('extensions') if isinstance(record.get('extensions'), dict) else {}
    return {
        'conversation_id': str(record.get('id', '') or ''),
        'path': path,
        'title': str(record.get('title', '') or ''),
        'updated_at': str(record.get('updated_at', '') or ''),
        'search_blob': combined,
        'origin_user_id': str(identity.get('origin_user_id', '') or identity.get('user_id', '') or ''),
        'owner_device_id': str(identity.get('owner_device_id', '') or ''),
        'source_device_id': str(identity.get('origin_device_id', '') or ''),
        'last_executor_device_id': str(extensions.get('last_executor_device_id', '') or identity.get('owner_device_id', '') or ''),
        'sync_status': str(record.get('sync_status', '') or 'local'),
        '_mtime': mtime,
    }


def _update_conversation_history_index(record: dict) -> None:
    entry = _conversation_history_index_entry(record)
    path = str(entry.get('path', '') or '')
    if not path:
        return
    with _CONVERSATION_HISTORY_INDEX_LOCK:
        _CONVERSATION_HISTORY_INDEX[path] = entry
    provider = _UNIFIED_HISTORY_PROVIDER
    if ICLOUD_M7_UNIFIED_HISTORY_ENABLED and isinstance(provider, UnifiedHistoryProvider):
        provider.invalidate()


HISTORY_INDEX_LAST_ERROR_PATH = os.path.join(BROCCOLI_APP_DATA_DIR, 'history_index_last_error.txt')


def _note_history_index_error(stage: str, error: BaseException) -> None:
    try:
        with open(HISTORY_INDEX_LAST_ERROR_PATH, 'w', encoding='utf-8') as handle:
            handle.write('%s | %s\n%s: %s\n\n%s' % (
                datetime.datetime.now().isoformat(timespec='seconds'), stage,
                type(error).__name__, error, traceback.format_exc(),
            ))
    except Exception:
        pass


def conversation_history_index_records() -> list[dict]:
    if ICLOUD_M7_UNIFIED_HISTORY_ENABLED:
        try:
            provider = get_unified_history_provider()
            if isinstance(provider, UnifiedHistoryProvider):
                records = provider.records()
                if records:
                    return records
        except Exception as exc:
            _note_history_index_error('records', exc)
    with _CONVERSATION_HISTORY_INDEX_LOCK:
        records = [dict(item) for item in _CONVERSATION_HISTORY_INDEX.values()]
    records.sort(key=lambda item: item.get('updated_at', ''), reverse=True)
    return records


def apply_history_title_repairs() -> int:
    """GUI thread: write back the user titles a rebuild found undone by an old save."""
    if not ICLOUD_M7_UNIFIED_HISTORY_ENABLED:
        return 0
    try:
        provider = get_unified_history_provider()
        if isinstance(provider, UnifiedHistoryProvider) and provider.enabled:
            return provider.apply_title_repairs()
    except Exception as exc:
        _note_history_index_error('title_repairs', exc)
    return 0


def history_index_needs_rebuild() -> bool:
    """The unified history dropped its list (a rename / delete / publish) and nothing has rebuilt
    it yet. Until then conversation_history_index_records() falls back to the few records
    written since — after a rename the panel showed only that one conversation."""
    if not ICLOUD_M7_UNIFIED_HISTORY_ENABLED:
        return False
    try:
        provider = get_unified_history_provider()
        return bool(isinstance(provider, UnifiedHistoryProvider) and provider.enabled and provider.is_stale())
    except Exception:
        return False


def unified_history_generation() -> int:
    try:
        provider = get_unified_history_provider()
        return provider.generation() if isinstance(provider, UnifiedHistoryProvider) else 0
    except Exception:
        return 0


def build_conversation_history_index() -> list[dict]:
    global _CONVERSATION_HISTORY_INDEX_READY
    if ICLOUD_M7_UNIFIED_HISTORY_ENABLED:
        records = []
        try:
            provider = get_unified_history_provider()
            records = provider.refresh() if isinstance(provider, UnifiedHistoryProvider) else []
        except Exception as exc:
            # The provider merges the iCloud tree; any failure there must never
            # blank the panel. Record it for diagnosis and fall through to the
            # plain local scan below.
            _note_history_index_error('refresh', exc)
            records = []
        if records:
            with _CONVERSATION_HISTORY_INDEX_LOCK:
                _CONVERSATION_HISTORY_INDEX_READY = True
            return records
        # Provider unavailable, failed, or (suspiciously) empty: fall back to
        # the local-records index so the panel always shows what is on disk.
    records = list_conversation_records()
    entries = {}
    for record in records:
        entry = _conversation_history_index_entry(record)
        if entry.get('path'):
            entries[entry['path']] = entry
    with _CONVERSATION_HISTORY_INDEX_LOCK:
        for path, current in _CONVERSATION_HISTORY_INDEX.items():
            scanned = entries.get(path)
            if scanned is None or str(current.get('updated_at', '')) > str(scanned.get('updated_at', '')):
                entries[path] = current
        _CONVERSATION_HISTORY_INDEX.clear()
        _CONVERSATION_HISTORY_INDEX.update(entries)
        _CONVERSATION_HISTORY_INDEX_READY = True
    return conversation_history_index_records()


def _write_json_atomic(path: str, payload, *, indent=None) -> None:
    path = str(path or '')
    if not path:
        return
    os.makedirs(os.path.dirname(path) or '.', exist_ok=True)
    if not ICLOUD_M1A_ATOMIC_WRITE_ENABLED:
        with open(path, 'w', encoding='utf-8') as handle:
            json.dump(payload, handle, ensure_ascii=False, indent=indent, separators=None if indent else (',', ':'))
        return
    tmp_path = f'{path}.tmp-{os.getpid()}-{threading.get_ident()}-{uuid.uuid4()}'
    try:
        with open(tmp_path, 'w', encoding='utf-8') as handle:
            json.dump(payload, handle, ensure_ascii=False, indent=indent, separators=None if indent else (',', ':'))
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(tmp_path, path)
    finally:
        if os.path.exists(tmp_path):
            try:
                os.unlink(tmp_path)
            except Exception:
                pass


def _conversation_current_revision(path: str) -> int:
    with _CONVERSATION_RECORD_CACHE_LOCK:
        cached = _CONVERSATION_RECORD_CACHE.get(str(path or ''))
        if isinstance(cached, dict):
            try:
                return max(0, int(cached.get('revision', 0) or 0))
            except (TypeError, ValueError):
                pass
    try:
        with open(path, 'r', encoding='utf-8') as handle:
            payload = json.load(handle)
        return max(0, int((payload or {}).get('revision', 0) or 0)) if isinstance(payload, dict) else 0
    except Exception:
        return 0


def write_conversation_derived_data(path: str,
                                    updates: dict,
                                    *,
                                    conversation_id: str = '',
                                    expected_revision: int | None = None) -> bool:
    """Write device-local derived data without ever touching canonical JSON."""
    path = resolve_conversation_path(str(path or '').strip())
    if not path or not isinstance(updates, dict):
        return False
    current_revision = _conversation_current_revision(path)
    if expected_revision is not None and current_revision != int(expected_revision):
        return False
    convo_id = str(conversation_id or '').strip() or Path(path).stem.split('_', 1)[0]
    payload = _read_conversation_derived_payload(path, convo_id)
    payload = copy.deepcopy(payload) if isinstance(payload, dict) else {}
    for key, value in updates.items():
        payload[str(key)] = copy.deepcopy(value)
    payload['schema_version'] = CONVERSATION_SCHEMA_VERSION
    payload['conversation_id'] = convo_id
    payload['source_revision'] = current_revision
    _write_json_atomic(conversation_derived_sidecar_path(path, convo_id), payload, indent=None)
    with _CONVERSATION_RECORD_CACHE_LOCK:
        cached = _CONVERSATION_RECORD_CACHE.get(path)
        if isinstance(cached, dict) and int(cached.get('revision', 0) or 0) == current_revision:
            if isinstance(updates.get('retrieval'), dict):
                cached['retrieval'] = copy.deepcopy(updates['retrieval'])
                cached['_retrieval_loaded'] = True
            if 'rendered_markdown' in updates:
                cached['rendered_markdown'] = str(updates.get('rendered_markdown', '') or '')
            if isinstance(updates.get('display'), dict):
                cached['display'] = copy.deepcopy(updates['display'])
    return True


def _async_file_write_worker() -> None:
    while True:
        item = _ASYNC_FILE_WRITE_QUEUE.get()
        try:
            kind = str((item or {}).get('kind', '') or '')
            if kind == 'stop':
                return
            if kind == 'conversation':
                path = str(item.get('path', '') or '')
                _write_json_atomic(path, item.get('payload', {}), indent=item.get('indent'))
                derived_payload = item.get('derived_payload')
                if isinstance(derived_payload, dict):
                    _write_json_atomic(
                        conversation_derived_sidecar_path(path, str(derived_payload.get('conversation_id', '') or '')),
                        derived_payload,
                        indent=None,
                    )
                retrieval_payload = item.get('retrieval_payload')
                if not ICLOUD_M1A_DERIVED_STORAGE_ENABLED and isinstance(retrieval_payload, dict):
                    _write_json_atomic(conversation_retrieval_sidecar_path(path), retrieval_payload, indent=None)
                generation = int(item.get('generation', 0) or 0)
                with _CONVERSATION_RECORD_CACHE_LOCK:
                    if generation == int(_CONVERSATION_RECORD_GENERATION.get(path, 0) or 0):
                        try:
                            _CONVERSATION_RECORD_CACHE_META[path] = os.path.getmtime(path)
                        except Exception:
                            _CONVERSATION_RECORD_CACHE_META[path] = 0.0
                if item.get('needs_embedding_refresh') and not bool(getattr(_BACKGROUND_EMBEDDING_LOCAL, 'suppress', False)):
                    enqueue_func = globals().get('enqueue_background_embedding_refresh')
                    if callable(enqueue_func):
                        try:
                            enqueue_func('agent', path, delay=BACKGROUND_EMBEDDING_AGENT_DEBOUNCE_SECONDS, reason='conversation_write')
                        except Exception:
                            pass
            elif kind == 'chat_history':
                _write_json_atomic(str(item.get('history_path', '') or ''), item.get('messages', []), indent=2)
                output_path = str(item.get('output_path', '') or '')
                if output_path:
                    write_text_file(output_path, str(item.get('markdown', '') or ''))
        except Exception:
            logging.exception('Async Broccoli file write failed: %r', item)
        finally:
            _ASYNC_FILE_WRITE_QUEUE.task_done()


def _ensure_async_file_writer() -> None:
    global _ASYNC_FILE_WRITE_THREAD
    with _ASYNC_FILE_WRITE_LOCK:
        if _ASYNC_FILE_WRITE_THREAD is not None and _ASYNC_FILE_WRITE_THREAD.is_alive():
            return
        _ASYNC_FILE_WRITE_THREAD = threading.Thread(
            target=_async_file_write_worker,
            name='broccoli-file-writer',
            daemon=True,
        )
        _ASYNC_FILE_WRITE_THREAD.start()


def _enqueue_async_file_write(item: dict) -> None:
    _ensure_async_file_writer()
    _ASYNC_FILE_WRITE_QUEUE.put(dict(item or {}))


def flush_async_file_writes(timeout: float = 2.0) -> bool:
    deadline = time.monotonic() + max(0.0, float(timeout))
    while getattr(_ASYNC_FILE_WRITE_QUEUE, 'unfinished_tasks', 0) > 0 and time.monotonic() < deadline:
        time.sleep(0.01)
    complete = getattr(_ASYNC_FILE_WRITE_QUEUE, 'unfinished_tasks', 0) == 0
    if not complete:
        logging.warning('Timed out flushing Broccoli file writes; pending=%s', _ASYNC_FILE_WRITE_QUEUE.unfinished_tasks)
    return complete


atexit.register(flush_async_file_writes)


def write_conversation_record(path: str, record: dict) -> dict:
    record = dict(record or {})
    migration_internal = bool(record.pop('_migration_internal_write', False))
    guard_device = globals().get('_ICLOUD_MIRROR_GUARD_DEVICE_ID')
    owner_elsewhere = conversation_owned_elsewhere(record, guard_device) if guard_device and not migration_internal else ''
    if owner_elsewhere:
        # A read-only copy: the owner device is the only writer. Local changes are
        # not saved (deliberate edits are refused with a message in the UI), so
        # the copy never drifts from the owner or gets published into the owner's
        # folder as if it were newer. Automatic writes (link titles, layout
        # state) are dropped here quietly.
        resolved = resolve_conversation_path(str(path or '').strip())
        logging.info('Not saving %s: read-only copy of a conversation owned by %s.', resolved, owner_elsewhere)
        return normalize_conversation_record(record, resolved, include_retrieval=False)
    migration_manager = globals().get('_ACTIVE_CONVERSATION_MIGRATION_MANAGER')
    if ICLOUD_M4B_MIGRATION_ENABLED and not migration_internal and isinstance(migration_manager, ConversationMigrationManager):
        conversation_id = str(record.get('id', '') or conversation_id_for_reference(path) or '')
        if conversation_id and not migration_manager.write_allowed(conversation_id):
            raise ICloudUserError('conversation_frozen')
    path = resolve_conversation_path(str(path or '').strip())
    retrieval_loaded = bool(record.get('_retrieval_loaded', True))
    normalized = normalize_conversation_record(record, path, include_retrieval=retrieval_loaded)
    retrieval_payload = None
    if retrieval_loaded:
        retrieval_payload = copy.deepcopy(normalized.get('retrieval', {}))
    elif bool(record.get('_legacy_retrieval_present', False)):
        retrieval_payload = _read_conversation_retrieval_payload(path)
    elif ICLOUD_M1A_DERIVED_STORAGE_ENABLED:
        current_derived = _read_conversation_derived_payload(path, normalized.get('id', ''))
        retrieval_payload = copy.deepcopy(current_derived.get('retrieval', {})) if isinstance(current_derived.get('retrieval'), dict) else {'chunks': []}
    else:
        retrieval_payload = _read_conversation_retrieval_payload(path)
    display_payload = {}
    display_markdown = str(normalized.get('display', {}).get('rendered_markdown', '') or '')
    if display_markdown and display_markdown != normalized['rendered_markdown']:
        display_payload['rendered_markdown'] = display_markdown
    message_webfetch_paths = {
        str(item.get('stored_path', '') or '').strip()
        for item in collect_webfetch_attachments_from_messages(normalized.get('messages', []))
        if isinstance(item, dict) and str(item.get('stored_path', '') or '').strip()
    }
    webfetch_extras = [
        item for item in normalized.get('webfetch', {}).get('attachments', [])
        if isinstance(item, dict)
        and str(item.get('stored_path', '') or '').strip() not in message_webfetch_paths
    ]
    with _CONVERSATION_RECORD_CACHE_LOCK:
        cached = _CONVERSATION_RECORD_CACHE.get(path)
        try:
            cached_revision = int((cached or {}).get('revision', 0) or 0) if isinstance(cached, dict) else 0
        except (TypeError, ValueError):
            cached_revision = 0
        if ICLOUD_M1A_SCHEMA_PASSTHROUGH_ENABLED:
            normalized['schema_version'] = CONVERSATION_SCHEMA_VERSION
            normalized['revision'] = max(int(normalized.get('revision', 0) or 0), cached_revision) + 1

    payload = {
        'id': normalized['id'],
        'title': normalized['title'],
        'created_at': normalized['created_at'],
        'updated_at': normalized['updated_at'],
        'messages': normalized['messages'],
        'memory': normalized['memory'],
        'links': normalized['links'],
        'outputs': normalized['outputs'],
        'agent_annotations': normalized.get('agent_annotations', []),
        # Attachments already present on messages are reconstructed during load.
        'webfetch': {'attachments': webfetch_extras},
        'external_sessions': normalized.get('external_sessions', {}),
        'branches': normalized['branches'],
    }
    if ICLOUD_M1A_SCHEMA_PASSTHROUGH_ENABLED:
        payload['schema_version'] = normalized['schema_version']
        payload['revision'] = normalized['revision']
        payload['extensions'] = copy.deepcopy(normalized.get('extensions', {}))
    if not ICLOUD_M1A_DERIVED_STORAGE_ENABLED:
        payload['rendered_markdown'] = normalized['rendered_markdown']
        payload['display'] = display_payload
    fresh_keys = [
        (chunk.get('id'), chunk.get('text'))
        for chunk in build_retrieval_chunks(normalized.get('messages', []))
    ]
    stored_chunks = (
        normalized.get('retrieval', {}).get('chunks', []) or []
        if retrieval_loaded else list((retrieval_payload or {}).get('chunks', []) or [])
    )
    stored_keys = [
        (chunk.get('id'), chunk.get('text'))
        for chunk in stored_chunks
        if isinstance(chunk, dict)
    ]
    needs_embedding_refresh = bool(normalized.get('messages')) and (
        fresh_keys != stored_keys
        or any(isinstance(chunk, dict) and not chunk.get('embedding') for chunk in stored_chunks)
    )
    derived_payload = None
    if ICLOUD_M1A_DERIVED_STORAGE_ENABLED:
        search_projection = _conversation_history_index_entry(normalized)
        derived_payload = {
            'schema_version': CONVERSATION_SCHEMA_VERSION,
            'conversation_id': normalized['id'],
            'source_revision': int(normalized.get('revision', 0) or 0),
            'retrieval': copy.deepcopy(retrieval_payload or {'chunks': []}),
            'rendered_markdown': normalized['rendered_markdown'],
            'display': copy.deepcopy(normalized.get('display', {})),
            'search_index': search_projection,
        }
    with _CONVERSATION_RECORD_CACHE_LOCK:
        generation = int(_CONVERSATION_RECORD_GENERATION.get(path, 0) or 0) + 1
        _CONVERSATION_RECORD_GENERATION[path] = generation
        _CONVERSATION_RECORD_CACHE[path] = copy.deepcopy(normalized)
        _CONVERSATION_RECORD_CACHE_META[path] = None
    _update_conversation_history_index(normalized)
    if ICLOUD_M2_CONVERSATION_RESOLVER_ENABLED:
        resolver = get_conversation_path_resolver()
        if resolver is not None:
            LocalConversationTreeStorage(resolver).register(normalized, path)
    _enqueue_async_file_write(
        {
            'kind': 'conversation',
            'path': path,
            'payload': payload,
            'indent': None,
            'retrieval_payload': retrieval_payload,
            'derived_payload': derived_payload,
            'generation': generation,
            'needs_embedding_refresh': needs_embedding_refresh,
        }
    )
    return normalized


def _copy_conversation_record_for_use(record: dict, *, include_retrieval: bool) -> dict:
    if include_retrieval:
        return copy.deepcopy(record)
    copied = {
        key: copy.deepcopy(value)
        for key, value in record.items()
        if key != 'retrieval'
    }
    copied['retrieval'] = {'chunks': []}
    copied['_retrieval_loaded'] = False
    return copied


def load_conversation_record(path: str, *, include_retrieval: bool = True) -> dict | None:
    path = resolve_conversation_path(str(path or '').strip())
    ensure_broccoli_data_dir()
    with _CONVERSATION_RECORD_CACHE_LOCK:
        cached = _CONVERSATION_RECORD_CACHE.get(path)
        cached_mtime = _CONVERSATION_RECORD_CACHE_META.get(path)
        if cached is not None:
            if include_retrieval and not bool(cached.get('_retrieval_loaded', False)):
                enriched = copy.deepcopy(cached)
                if ICLOUD_M1A_DERIVED_STORAGE_ENABLED:
                    enriched['retrieval'] = _read_conversation_derived_payload(
                        path, str(cached.get('id', '') or '')
                    ).get('retrieval', {'chunks': []})
                else:
                    enriched['retrieval'] = _read_conversation_retrieval_payload(path)
                enriched['_retrieval_loaded'] = True
                enriched = normalize_conversation_record(enriched, path, include_retrieval=True)
                _CONVERSATION_RECORD_CACHE[path] = copy.deepcopy(enriched)
                return enriched
            elif not include_retrieval or bool(cached.get('_retrieval_loaded', False)):
                if cached_mtime is None:
                    return _copy_conversation_record_for_use(cached, include_retrieval=include_retrieval)
                try:
                    if os.path.exists(path) and os.path.getmtime(path) == cached_mtime:
                        return _copy_conversation_record_for_use(cached, include_retrieval=include_retrieval)
                except Exception:
                    pass
    if not os.path.exists(path):
        return None
    perf_started = time.perf_counter()
    try:
        with open(path, 'r', encoding='utf-8') as handle:
            raw_text = handle.read()
        read_at = time.perf_counter()
        data = json.loads(raw_text)
        parsed_at = time.perf_counter()
    except Exception:
        return None
    if not isinstance(data, dict):
        return None
    normalized = normalize_conversation_record(data, path, include_retrieval=include_retrieval)
    if ICLOUD_M2_CONVERSATION_RESOLVER_ENABLED:
        resolver = get_conversation_path_resolver()
        if resolver is not None:
            resolver.register(str(normalized.get('id', '') or ''), path, normalized)
    with _CONVERSATION_RECORD_CACHE_LOCK:
        _CONVERSATION_RECORD_CACHE[path] = copy.deepcopy(normalized)
        try:
            _CONVERSATION_RECORD_CACHE_META[path] = os.path.getmtime(path)
        except Exception:
            _CONVERSATION_RECORD_CACHE_META[path] = 0.0
    finished_at = time.perf_counter()
    _agent_render_perf_log(
        'load_conversation',
        bytes=len(raw_text.encode('utf-8', errors='ignore')),
        json_ms=round((parsed_at - read_at) * 1000, 2),
        normalize_ms=round((finished_at - parsed_at) * 1000, 2),
        path=os.path.basename(path),
        read_ms=round((read_at - perf_started) * 1000, 2),
        total_ms=round((finished_at - perf_started) * 1000, 2),
    )
    return normalized


def list_conversation_records() -> list[dict]:
    ensure_broccoli_data_dir()
    records = []
    candidate_paths = {str(path) for path in Path(CONVERSATIONS_DIR).glob('*.json')}
    if ICLOUD_M2_CONVERSATION_RESOLVER_ENABLED:
        resolver = get_conversation_path_resolver()
        if resolver is not None:
            candidate_paths.update(resolver.all_current_paths())
    for raw_path in sorted(candidate_paths):
        path = Path(raw_path)
        if str(path).endswith(CONVERSATION_RETRIEVAL_SUFFIX) or str(path).endswith(CONVERSATION_DERIVED_SUFFIX):
            continue
        record = load_conversation_record(str(path), include_retrieval=False)
        if record:
            search_blob = '\n'.join(message['content'] for message in record['messages'])
            attachment_blob = '\n'.join(
                '\n'.join(
                    str(attachment.get('name', '')) + '\n' + str(attachment.get('extracted_text', ''))
                    for attachment in (message.get('attachments') or [])
                )
                for message in record['messages']
            )
            links_blob = '\n'.join(
                (str(link.get('title', '')).strip() + '\n' + str(link.get('url', '')).strip()).strip()
                for link in record.get('links', [])
            )
            outputs_blob = '\n'.join(
                (
                    str(output.get('title', '')).strip()
                    + '\n'
                    + str(output.get('content', '')).strip()
                    + '\n'
                    + str(output.get('path', '')).strip()
                ).strip()
                for output in record.get('outputs', [])
            )
            running_summary = record.get('memory', {}).get('running_summary', '')
            record['search_blob'] = f"{record['title']}\n{search_blob}\n{attachment_blob}\n{links_blob}\n{outputs_blob}".lower()
            if running_summary:
                record['search_blob'] += '\n' + running_summary.lower()
            records.append(record)
    records.sort(key=lambda item: item.get('updated_at', ''), reverse=True)
    return records


class UnifiedHistoryProvider:
    """M7 conversation_id provider over local records + every canonical L1/L2/L3 path."""

    def __init__(self,
                 *,
                 cloud_root: str | None = None,
                 device_id: str = '',
                 origin_user_id: str = '',
                 materializer: ICloudFileMaterializer | None = None,
                 local_cache_root: str | None = None,
                 local_records_provider=None,
                 enabled: bool | None = None):
        self.enabled = ICLOUD_M7_UNIFIED_HISTORY_ENABLED if enabled is None else bool(enabled)
        self.backend = CloudTreeBackend(cloud_root or BROCCOLI_ICLOUD_ROOT, materializer)
        self.device_id = _cloud_file_component(device_id or BROCCOLI_LOCAL_DEVICE_ID, 'device')
        self.origin_user_id = str(origin_user_id or BROCCOLI_LOCAL_USER_ID)
        self.local_cache_root = os.path.abspath(os.path.expanduser(str(
            local_cache_root or os.path.join(BROCCOLI_APP_DATA_DIR, 'UnifiedHistoryCache')
        )))
        self.local_records_provider = local_records_provider or list_conversation_records
        self._lock = threading.RLock()
        self._records = []
        self._canonical_records = {}
        self._entry_by_id = {}
        self._retrieval_round_seen = {}
        self._stale = False        # the list was dropped (rename / delete / publish), no rebuild yet
        self._generation = 0       # bumped by every drop: a rebuild that began before it is not fresh

    @staticmethod
    def _rank(record: dict) -> tuple:
        try:
            route_epoch = int(record.get('route_epoch', 0) or 0)
        except (TypeError, ValueError):
            route_epoch = 0
        try:
            revision = int(record.get('revision', 0) or 0)
        except (TypeError, ValueError):
            revision = 0
        return route_epoch, revision, str(record.get('updated_at', '') or '')

    @staticmethod
    def _identity(record: dict) -> dict:
        return record.get('identity') if isinstance(record.get('identity'), dict) else {}

    def _is_provider_cache(self, path: str) -> bool:
        path = os.path.abspath(os.path.expanduser(str(path or ''))) if path else ''
        return bool(path) and os.path.commonpath([self.local_cache_root, path]) == self.local_cache_root

    def _local_records(self) -> list[dict]:
        try:
            values = self.local_records_provider()
        except Exception:
            values = []
        output = []
        for item in values or []:
            if not isinstance(item, dict) or not str(item.get('id', '') or ''):
                continue
            identity = self._identity(item)
            origin = str(identity.get('origin_user_id', '') or identity.get('user_id', '') or BROCCOLI_LOCAL_USER_ID)
            if self.origin_user_id and origin != self.origin_user_id:
                continue
            if self._is_provider_cache(str(item.get('path', '') or '')):
                continue
            output.append(copy.deepcopy(item))
        return output

    def _scan_cloud(self) -> tuple[dict[str, list[dict]], dict[str, list[dict]]]:
        revisions = {}
        metadata = {}
        canonical_root = Path(self.backend.path('canonical'))
        if not canonical_root.exists():
            return revisions, metadata
        for path in sorted(canonical_root.glob('*/*/*/*/revisions/*.json')):
            payload = self.backend.read_json(str(path), timeout=0.5)
            if not verify_cloud_payload(payload):
                continue
            try:
                conversation_dir = path.parents[1]
                origin_from_tree = conversation_dir.parent.name
                device_from_tree = conversation_dir.parent.parent.name
                owner_from_tree = conversation_dir.parent.parent.parent.name
                conversation_id = conversation_dir.name
            except Exception:
                continue
            if str(payload.get('id', '') or '') != conversation_id:
                continue
            identity = self._identity(payload)
            origin = str(identity.get('origin_user_id', '') or origin_from_tree)
            if self.origin_user_id and origin != self.origin_user_id:
                continue
            candidate = copy.deepcopy(payload)
            candidate['_cloud_path'] = str(path)
            candidate['_tree_owner_user_id'] = owner_from_tree
            candidate['_tree_owner_device_id'] = device_from_tree
            candidate['_tree_origin_user_id'] = origin_from_tree
            revisions.setdefault(conversation_id, []).append(candidate)
        for path in sorted(canonical_root.glob('*/*/*/*/events/*.json')):
            payload = self.backend.read_json(str(path), timeout=0.5)
            if not verify_cloud_payload(payload):
                continue
            event_type = str(payload.get('event_type', '') or '')
            if event_type not in {'history_renamed', 'history_deleted'}:
                continue
            try:
                conversation_dir = path.parents[1]
                origin_from_tree = conversation_dir.parent.name
                conversation_id = conversation_dir.name
            except Exception:
                continue
            if self.origin_user_id and origin_from_tree != self.origin_user_id:
                continue
            metadata.setdefault(conversation_id, []).append(copy.deepcopy(payload))
        return revisions, metadata

    def _cache_cloud_record(self, record: dict) -> dict | None:
        conversation_id = str(record.get('id', '') or '')
        if not conversation_id:
            return None
        route_epoch, revision, _updated = self._rank(record)
        owner_device = str(self._identity(record).get('owner_device_id', '') or record.get('_tree_owner_device_id', '') or 'owner')
        directory = os.path.join(self.local_cache_root, _cloud_file_component(conversation_id, 'conversation'))
        path = os.path.join(directory, '{}-{}-{}.json'.format(
            route_epoch, revision, _cloud_file_component(owner_device, 'device'),
        ))
        payload = {
            str(key): copy.deepcopy(value)
            for key, value in record.items()
            if not str(key).startswith('_') and str(key) != 'content_hash'
        }
        _write_json_atomic(path, payload)
        normalized = load_conversation_record(path, include_retrieval=False)
        if isinstance(normalized, dict):
            normalized['_unified_history_cloud_cache'] = True
        return normalized

    @staticmethod
    def _max_cloud(candidates: list[dict]) -> tuple[dict | None, bool]:
        if not candidates:
            return None, False
        best_rank = max(UnifiedHistoryProvider._rank(item) for item in candidates)
        top = [item for item in candidates if UnifiedHistoryProvider._rank(item) == best_rank]
        hashes = {str(item.get('content_hash', '') or cloud_payload_hash(item)) for item in top}
        top.sort(key=lambda item: (str(item.get('content_hash', '') or ''), str(item.get('_cloud_path', '') or '')))
        return top[-1], len(hashes) > 1

    def refresh(self) -> list[dict]:
        if not self.enabled:
            return []
        with self._lock:
            started_generation = self._generation
        local_records = self._local_records()
        cloud_by_id, metadata_by_id = self._scan_cloud()
        local_by_id = {}
        for record in local_records:
            conversation_id = str(record.get('id', '') or '')
            current = local_by_id.get(conversation_id)
            if current is None or self._rank(record) >= self._rank(current):
                local_by_id[conversation_id] = record
        entries = []
        canonical_records = {}
        repairs = {}
        all_ids = set(local_by_id) | set(cloud_by_id)
        for conversation_id in sorted(all_ids):
            local_record = local_by_id.get(conversation_id)
            cloud_record, cloud_conflict = self._max_cloud(cloud_by_id.get(conversation_id, []))
            local_rank = self._rank(local_record) if isinstance(local_record, dict) else None
            cloud_rank = self._rank(cloud_record) if isinstance(cloud_record, dict) else None
            if local_record is not None and (cloud_record is None or local_rank >= cloud_rank):
                selected = copy.deepcopy(local_record)
                path = str(selected.get('path', '') or '')
            elif cloud_record is not None:
                selected = self._cache_cloud_record(cloud_record) or copy.deepcopy(cloud_record)
                path = str(selected.get('path', '') or '')
            else:
                continue
            metadata_events = sorted(
                metadata_by_id.get(conversation_id, []),
                key=lambda item: (str(item.get('created_at', '') or ''), str(item.get('producer_id', '') or ''), str(item.get('producer_seq', '') or '')),
            )
            if metadata_events:
                # Tombstones are permanent protocol facts; a later rename/result can
                # never revive a deleted conversation.
                if any(str(item.get('event_type', '') or '') == 'history_deleted' for item in metadata_events):
                    continue
                latest_metadata = metadata_events[-1]
                if str(latest_metadata.get('event_type', '') or '') == 'history_renamed':
                    renamed = sanitize_conversation_title(str(latest_metadata.get('title', '') or selected.get('title', '')))
                    selected['title'] = renamed
                    self._note_title_repair(local_record, renamed, repairs)
            local_cloud_conflict = False
            if local_record is not None and cloud_record is not None and local_rank == cloud_rank:
                # Recompute BOTH hashes under the same canonicalization. The
                # stored content_hash freezes whatever shape the payload had at
                # publish time, so comparing against it flags every historical
                # schema addition as a permanent conflict.
                local_hash = cloud_payload_hash(cloud_canonical_record(local_record))
                cloud_hash = cloud_payload_hash(cloud_canonical_record(cloud_record))
                local_cloud_conflict = bool(cloud_hash and local_hash != cloud_hash)
            if cloud_conflict or local_cloud_conflict:
                sync_status = 'conflict'
            elif local_record is not None and cloud_record is not None:
                sync_status = 'synced' if local_rank == cloud_rank else ('local_ahead' if local_rank > cloud_rank else 'cloud_newer')
            elif cloud_record is not None:
                sync_status = 'cloud_only'
            else:
                sync_status = 'local_only'
            selected['path'] = path
            identity = self._identity(selected)
            origin_user = str(identity.get('origin_user_id', '') or identity.get('user_id', '') or self.origin_user_id)
            owner_device = str(identity.get('owner_device_id', '') or (cloud_record or {}).get('_tree_owner_device_id', '') or self.device_id)
            source_device = str(identity.get('origin_device_id', '') or selected.get('source_device_id', '') or owner_device)
            extensions = selected.get('extensions') if isinstance(selected.get('extensions'), dict) else {}
            last_executor = str(extensions.get('last_executor_device_id', '') or selected.get('last_executor_device_id', '') or owner_device)
            history_entry = _conversation_history_index_entry(selected)
            history_entry.update({
                'conversation_id': conversation_id,
                'origin_user_id': origin_user,
                'user_id': origin_user,
                'owner_user_id': str(identity.get('owner_user_id', '') or (cloud_record or {}).get('_tree_owner_user_id', '') or ''),
                'owner_device_id': owner_device,
                'source_device_id': source_device,
                'last_executor_device_id': last_executor,
                'sync_status': sync_status,
                'route_epoch': int(selected.get('route_epoch', 0) or 0),
                'revision': int(selected.get('revision', 0) or 0),
                'profile_fallback': bool(extensions.get('profile_fallback', False)),
            })
            entries.append(history_entry)
            canonical_records[conversation_id] = selected
        entries.sort(key=lambda item: (str(item.get('updated_at', '') or ''), str(item.get('conversation_id', '') or '')), reverse=True)
        with self._lock:
            self._canonical_records = canonical_records
            self._entry_by_id = {str(item.get('conversation_id', '') or ''): copy.deepcopy(item) for item in entries}
            self._title_repairs = repairs
            if self._generation == started_generation:
                self._records = copy.deepcopy(entries)
                self._stale = False
            # else: a rename / save landed while it ran — this list was read before it (the
            # tag went back to the old name until the next rebuild); stay stale, the next
            # rebuild installs the list
        return copy.deepcopy(entries)

    def _note_title_repair(self, local_record, renamed: str, repairs: dict):
        """A save before the user-title mark put the first question back over a rename: the
        file's title is exactly that auto title, the latest rename says otherwise, and the
        conversation is this Mac's — put the user's name back (apply_title_repairs)."""
        if not isinstance(local_record, dict) or not renamed or local_record.get(CONVERSATION_TITLE_USER_SET_KEY):
            return
        path = str(local_record.get('path', '') or '')
        current = str(local_record.get('title', '') or '')
        if not path or current == renamed:
            return
        if current != conversation_title_from_messages(list(local_record.get('messages') or []), fallback=''):
            return
        owner = str(self._identity(local_record).get('owner_device_id', '') or self.device_id)
        if owner == self.device_id:
            repairs[str(local_record.get('id', '') or '')] = (path, renamed)

    def apply_title_repairs(self) -> int:
        """Write the noted user titles back into their files (GUI thread). Each file is
        re-read and re-checked first; returns how many were repaired."""
        with self._lock:
            repairs, self._title_repairs = dict(getattr(self, '_title_repairs', {}) or {}), {}
        fixed = 0
        for path, title in repairs.values():
            try:
                record = load_conversation_record(path)
                if not isinstance(record, dict) or record.get(CONVERSATION_TITLE_USER_SET_KEY):
                    continue
                current = str(record.get('title', '') or '')
                if current == title or current != conversation_title_from_messages(list(record.get('messages') or []), fallback=''):
                    continue
                record['title'] = title
                record[CONVERSATION_TITLE_USER_SET_KEY] = True
                write_conversation_record(str(record.get('path', '') or path), record)
                fixed += 1
            except Exception:
                logging.exception('Conversation title repair failed for %s', path)
        if fixed:
            self.invalidate()
        return fixed

    def is_stale(self) -> bool:
        """Its list was dropped (a rename / delete / publish) and not rebuilt since."""
        with self._lock:
            return bool(self._stale)

    def generation(self) -> int:
        with self._lock:
            return int(self._generation)

    def records(self) -> list[dict]:
        with self._lock:
            return copy.deepcopy(self._records)

    def canonical_record(self, conversation_id: str) -> dict | None:
        with self._lock:
            record = self._canonical_records.get(str(conversation_id or ''))
            return copy.deepcopy(record) if isinstance(record, dict) else None

    def invalidate(self):
        with self._lock:
            self._records = []
            self._entry_by_id = {}
            self._stale = True
            self._generation += 1

    def _publish_revision(self, record: dict) -> str:
        payload = cloud_canonical_record(record)
        identity = self._identity(payload)
        owner_user = _cloud_file_component(identity.get('owner_user_id', '') or BROCCOLI_LOCAL_USER_ID, 'owner')
        owner_device = _cloud_file_component(identity.get('owner_device_id', '') or self.device_id, 'device')
        origin_user = _cloud_file_component(identity.get('origin_user_id', '') or identity.get('user_id', '') or self.origin_user_id, 'origin')
        conversation_id = _cloud_file_component(payload.get('id', ''), 'conversation')
        route_epoch = int(payload.get('route_epoch', 0) or 0)
        revision = int(payload.get('revision', 0) or 0)
        sealed = seal_cloud_payload(payload)
        return self.backend.publish_json(
            self.backend.path('canonical', owner_user, owner_device, origin_user, conversation_id, 'revisions'),
            '{}-{}-{}.json'.format(route_epoch, revision, owner_device), sealed,
        )

    def touch(self, reference: str) -> dict:
        if not self.enabled:
            return {'status': 'disabled'}
        conversation_id = conversation_id_for_reference(reference) or str(reference or '')
        if not self._entry_by_id:
            self.refresh()
        entry = self._entry_by_id.get(conversation_id)
        record = self._canonical_records.get(conversation_id)
        if not isinstance(entry, dict) or not isinstance(record, dict):
            return {'status': 'missing'}
        if str(entry.get('sync_status', '') or '') not in {'local_only', 'local_ahead'}:
            return {'status': 'already_synced', 'record': copy.deepcopy(record)}
        path = str(record.get('path', '') or '')
        fresh = load_conversation_record(path) if path else None
        if isinstance(fresh, dict) and str(fresh.get('id', '') or '') == str(record.get('id', '') or ''):
            record = fresh   # the file as it is now (this list's copy can be older)
        destination = self._publish_revision(record)
        self.invalidate()
        return {'status': 'published', 'conversation_id': conversation_id, 'destination': destination}

    def _publish_metadata_event(self, record: dict, event_type: str, **fields) -> dict:
        identity = self._identity(record)
        event_id = new_broccoli_uuid('history-event-')
        payload = seal_cloud_payload({
            'schema_version': ICLOUD_PROTOCOL_VERSION,
            'record_type': 'HistoryMetadataRequest',
            'event_id': event_id,
            'event_type': str(event_type or ''),
            'conversation_id': str(record.get('id', '') or ''),
            'owner_user_id': str(identity.get('owner_user_id', '') or BROCCOLI_LOCAL_USER_ID),
            'owner_device_id': str(identity.get('owner_device_id', '') or self.device_id),
            'origin_user_id': str(identity.get('origin_user_id', '') or self.origin_user_id),
            'executor_id': str(identity.get('owner_device_id', '') or self.device_id),
            'source_device_id': self.device_id,
            'route_epoch': int(record.get('route_epoch', 0) or 0),
            'producer_id': self.device_id,
            'producer_seq': event_id,
            'created_at': datetime.datetime.now().isoformat(timespec='milliseconds'),
            **_task_store_json_safe(fields),
        })
        directory = self.backend.path(
            'canonical',
            _cloud_file_component(payload.get('owner_user_id', ''), 'owner'),
            _cloud_file_component(payload.get('owner_device_id', ''), 'device'),
            _cloud_file_component(payload.get('origin_user_id', ''), 'origin'),
            _cloud_file_component(payload.get('conversation_id', ''), 'conversation'),
            'events',
        )
        filename = '{}-{}-{}.json'.format(self.device_id, _cloud_file_component(event_id, 'event'), event_type)
        formal = self.backend.publish_json(directory, filename, payload)
        inbox = self.backend.publish_json(
            self.backend.path('control', 'inbox', _cloud_file_component(payload.get('executor_id', ''), 'device')),
            filename, payload,
        )
        return {'payload': payload, 'formal': formal, 'inbox': inbox}

    def rename(self, reference: str, new_title: str) -> dict:
        conversation_id = conversation_id_for_reference(reference) or str(reference or '')
        if not self._entry_by_id:
            self.refresh()
        record = self._canonical_records.get(conversation_id)
        if not isinstance(record, dict):
            return {'status': 'missing'}
        title = sanitize_conversation_title(new_title)
        identity = self._identity(record)
        event = self._publish_metadata_event(record, 'history_renamed', title=title)
        if str(identity.get('owner_device_id', '') or self.device_id) == self.device_id:
            path = str(record.get('path', '') or '')
            if path:
                # the file as it is now: this list's copy can be older (a save while it was
                # being rebuilt) and writing it back dropped the newest turns
                flush_async_file_writes(2.0)
                fresh = load_conversation_record(path)
                if isinstance(fresh, dict) and str(fresh.get('id', '') or '') == str(record.get('id', '') or ''):
                    record = fresh
                    path = str(fresh.get('path', '') or path)
            record['title'] = title
            record[CONVERSATION_TITLE_USER_SET_KEY] = True
            record['updated_at'] = datetime.datetime.now().isoformat(timespec='seconds')
            if path:
                record = write_conversation_record(path, record)
            self._publish_revision(record)
            status = 'renamed'
        else:
            status = 'rename_requested'
        self.invalidate()
        return {'status': status, 'record': copy.deepcopy(record), 'event': event}

    def delete(self, reference: str) -> dict:
        conversation_id = conversation_id_for_reference(reference) or str(reference or '')
        if not self._entry_by_id:
            self.refresh()
        record = self._canonical_records.get(conversation_id)
        if not isinstance(record, dict):
            return {'status': 'missing'}
        event = self._publish_metadata_event(record, 'history_deleted')
        resolver = get_conversation_path_resolver()
        if resolver is not None:
            resolver.mark_deleted(conversation_id, str(record.get('path', '') or ''))
        self.invalidate()
        return {'status': 'tombstoned', 'conversation_id': conversation_id, 'event': event}

    @staticmethod
    def rollup_records_by_user(records: list[dict]) -> dict[str, list[dict]]:
        grouped = {}
        seen = set()
        for item in sorted(
            (dict(value) for value in records or [] if isinstance(value, dict)),
            key=lambda value: (str(value.get('updated_at', '') or ''), str(value.get('conversation_id', '') or '')),
            reverse=True,
        ):
            conversation_id = str(item.get('conversation_id', '') or item.get('id', '') or '')
            user_id = str(item.get('origin_user_id', '') or item.get('user_id', '') or 'unknown-user')
            if not conversation_id or conversation_id in seen:
                continue
            seen.add(conversation_id)
            grouped.setdefault(user_id, []).append(item)
        return grouped

    def rollup_by_user(self) -> dict[str, list[dict]]:
        return self.rollup_records_by_user(self.records())

    def retrieval_records(self, *, active_conversation_id: str = '', round_id: str = '') -> list[tuple[dict, str, str]]:
        if not self._records:
            self.refresh()
        active_conversation_id = str(active_conversation_id or '')
        round_id = str(round_id or '')
        with self._lock:
            seen = self._retrieval_round_seen.setdefault(round_id, set()) if round_id else set()
            output = []
            for entry in self._records:
                conversation_id = str(entry.get('conversation_id', '') or '')
                if not conversation_id or conversation_id == active_conversation_id or conversation_id in seen:
                    continue
                record = self._canonical_records.get(conversation_id)
                if not isinstance(record, dict):
                    continue
                output.append((copy.deepcopy(record), str(entry.get('path', '') or ''), 'agent'))
                seen.add(conversation_id)
            if round_id:
                self._retrieval_round_seen[round_id] = seen
                while len(self._retrieval_round_seen) > 64:
                    self._retrieval_round_seen.pop(next(iter(self._retrieval_round_seen)), None)
            return output


def get_unified_history_provider(*,
                                 cloud_root: str | None = None,
                                 device_id: str = '',
                                 origin_user_id: str = '',
                                 materializer: ICloudFileMaterializer | None = None,
                                 local_cache_root: str | None = None) -> UnifiedHistoryProvider | None:
    global _UNIFIED_HISTORY_PROVIDER
    if not ICLOUD_M7_UNIFIED_HISTORY_ENABLED:
        return None
    requested_root = os.path.abspath(os.path.expanduser(str(cloud_root or BROCCOLI_ICLOUD_ROOT)))
    requested_device = _cloud_file_component(device_id or BROCCOLI_LOCAL_DEVICE_ID, 'device')
    requested_origin = str(origin_user_id or BROCCOLI_LOCAL_USER_ID)
    requested_cache = os.path.abspath(os.path.expanduser(str(local_cache_root or os.path.join(BROCCOLI_APP_DATA_DIR, 'UnifiedHistoryCache'))))
    with _UNIFIED_HISTORY_PROVIDER_LOCK:
        if (
            _UNIFIED_HISTORY_PROVIDER is None
            or _UNIFIED_HISTORY_PROVIDER.backend.root != requested_root
            or _UNIFIED_HISTORY_PROVIDER.device_id != requested_device
            or _UNIFIED_HISTORY_PROVIDER.origin_user_id != requested_origin
            or _UNIFIED_HISTORY_PROVIDER.local_cache_root != requested_cache
        ):
            _UNIFIED_HISTORY_PROVIDER = UnifiedHistoryProvider(
                cloud_root=requested_root, device_id=requested_device, origin_user_id=requested_origin,
                materializer=materializer, local_cache_root=requested_cache, enabled=True,
            )
        return _UNIFIED_HISTORY_PROVIDER


def reset_unified_history_provider_for_tests():
    global _UNIFIED_HISTORY_PROVIDER
    with _UNIFIED_HISTORY_PROVIDER_LOCK:
        _UNIFIED_HISTORY_PROVIDER = None


def create_conversation_record(first_question: str, history_messages: list[dict] | None = None) -> dict:
    ensure_broccoli_data_dir()
    title = sanitize_conversation_title(first_question)
    convo_id, path = allocate_conversation_identity(title)
    base_messages = list(history_messages or [])
    base_messages.append({'role': 'user', 'content': first_question.strip(), 'timestamp': current_chat_timestamp()})
    now = datetime.datetime.now().isoformat(timespec='seconds')
    return write_conversation_record(
        path,
        {
            'id': convo_id,
            **({'identity': local_conversation_identity()} if ICLOUD_M1C_UNIFIED_FINALIZER_ENABLED else {}),
            'title': title,
            'created_at': now,
            'updated_at': now,
            'messages': base_messages,
            'rendered_markdown': render_chat_history_markdown(base_messages),
        },
    )


def rename_conversation_record(path: str, new_title: str) -> dict | None:
    flush_async_file_writes(2.0)
    path = resolve_conversation_path(path)
    record = load_conversation_record(path)
    if record is None:
        return None
    title = sanitize_conversation_title(new_title)
    record[CONVERSATION_TITLE_USER_SET_KEY] = True   # later saves keep it (no first question over it)
    if ICLOUD_M2_CONVERSATION_RESOLVER_ENABLED:
        record['title'] = title
        record['updated_at'] = datetime.datetime.now().isoformat(timespec='seconds')
        saved = write_conversation_record(path, record)
        resolver = get_conversation_path_resolver()
        if resolver is not None:
            resolver.rename_metadata(str(saved.get('id', '') or ''), title)
        return saved
    prefix = record['id']
    new_filename = f"{prefix}_{sanitize_conversation_filename(title)}.json"
    new_path = os.path.join(CONVERSATIONS_DIR, new_filename)
    suffix = 2
    while new_path != path and os.path.exists(new_path):
        new_filename = f"{prefix}_{sanitize_conversation_filename(title)}-{suffix}.json"
        new_path = os.path.join(CONVERSATIONS_DIR, new_filename)
        suffix += 1
    record['title'] = title
    record['updated_at'] = datetime.datetime.now().isoformat(timespec='seconds')
    if new_path != path:
        os.replace(path, new_path)
        old_retrieval_path = conversation_retrieval_sidecar_path(path)
        new_retrieval_path = conversation_retrieval_sidecar_path(new_path)
        if os.path.exists(old_retrieval_path):
            os.replace(old_retrieval_path, new_retrieval_path)
        with _CONVERSATION_RECORD_CACHE_LOCK:
            _CONVERSATION_RECORD_CACHE.pop(path, None)
            _CONVERSATION_RECORD_CACHE_META.pop(path, None)
            _CONVERSATION_RECORD_GENERATION.pop(path, None)
            lazy_retrieval = _CONVERSATION_LAZY_RETRIEVAL.pop(path, None)
            if lazy_retrieval is not None:
                _CONVERSATION_LAZY_RETRIEVAL[new_path] = lazy_retrieval
        with _CONVERSATION_HISTORY_INDEX_LOCK:
            _CONVERSATION_HISTORY_INDEX.pop(path, None)
        record['path'] = new_path
    return write_conversation_record(new_path, record)


def create_openai_client(api_key: str, endpoint: str, timeout: int):
    return OpenAI(api_key=api_key, base_url=endpoint, timeout=timeout)


def _merge_leading_system_messages_into_user(messages: list[dict]) -> list[dict]:
    cloned = copy.deepcopy(messages)
    system_parts = []
    index = 0
    while index < len(cloned) and str(cloned[index].get('role', '')).strip().lower() == 'system':
        content = str(cloned[index].get('content', '') or '').strip()
        if content:
            system_parts.append(content)
        index += 1
    if not system_parts:
        return cloned

    remaining = cloned[index:]
    system_text = '\n\n'.join(system_parts).strip()
    prefix = 'System instructions:\n' + system_text
    for item in remaining:
        if str(item.get('role', '')).strip().lower() == 'user':
            user_content = item.get('content', '')
            if isinstance(user_content, list):
                item['content'] = [{'type': 'text', 'text': prefix + '\n\nUser message:'}] + user_content
            else:
                item['content'] = (prefix + '\n\nUser message:\n' + str(user_content or '')).strip()
            return remaining
    return [{'role': 'user', 'content': prefix}] + remaining


def _should_retry_without_system_role(exc: Exception, messages: list[dict]) -> bool:
    if not messages:
        return False
    first_role = str(messages[0].get('role', '') if isinstance(messages[0], dict) else '').strip().lower()
    if first_role != 'system':
        return False
    text = str(exc)
    return (
        'messages.0.role' in text
        and ('Invalid input' in text or 'invalid_request_error' in text or 'invalid' in text.lower())
    )


def _should_retry_with_default_max_tokens(exc: Exception, kwargs: dict) -> bool:
    if 'max_tokens' in kwargs or 'max_completion_tokens' in kwargs:
        return False
    text = str(exc)
    return (
        'max_tokens' in text
        and 'Invalid input' in text
        and ('undefined' in text or 'expected number' in text)
    )


def _default_max_tokens_for_chat_completion(model: str) -> int:
    model_name = str(model or '').strip().lower()
    if 'claude-3-haiku' in model_name and '3-5' not in model_name:
        return 4096
    return ANTHROPIC_COMPAT_DEFAULT_MAX_TOKENS


# ── LLM 录制/回放（方案4）────────────────────────────────────────
# 学 DeepSeek Harness 的录制会话回放测试：所有 23 处模型调用都走
# create_chat_completion 这个唯一入口，在这里加开关即可全覆盖（编辑器线
# 也在内）。按环境变量启用，每次启动显式选择，不进设置（录制会把完整
# 提示词和回复写盘，必须是每次运行的显式决定）：
#   BROCCOLI_LLM_RECORD_DIR=<目录>  录制：真实请求照发，成功响应按请求
#     指纹写 <sha256>.json；流式响应在消费完后落盘（中途弃流不录）。
#   BROCCOLI_LLM_REPLAY_DIR=<目录>  回放：完全不碰网络/密钥，按指纹读盘；
#     没有对应录制文件时抛错（回放模式就该 fail loud）。
# 指纹 = endpoint + messages + 全部 kwargs（含 stream、model）的规范化
# JSON 的 SHA256。提示词里带时间戳会导致指纹变化——回放场景要固定输入。
def _llm_payload_to_jsonable(value):
    dump = getattr(value, 'model_dump', None)
    if callable(dump):
        try:
            return dump()
        except Exception:
            pass
    to_dict = getattr(value, 'to_dict', None)
    if callable(to_dict):
        try:
            return to_dict()
        except Exception:
            pass
    try:
        json.dumps(value)
        return value
    except Exception:
        return str(value)


def _llm_request_fingerprint(endpoint: str, messages: list[dict], kwargs: dict) -> str:
    payload = json.dumps(
        {
            'endpoint': str(endpoint or ''),
            'messages': messages,
            'kwargs': {key: kwargs.get(key) for key in sorted(kwargs)},
        },
        ensure_ascii=False, sort_keys=True, default=str,
    )
    return hashlib.sha256(payload.encode('utf-8')).hexdigest()


class _LLMReplayObject:
    """录制 JSON 的属性视图：让 response.choices[0].message.content 之类的
    访问在回放对象上原样成立；缺属性抛 AttributeError（getattr 默认值可用）。"""

    def __init__(self, payload: dict):
        object.__setattr__(self, '_payload', payload)

    def __getattr__(self, name):
        payload = object.__getattribute__(self, '_payload')
        if isinstance(payload, dict) and name in payload:
            return _llm_replay_wrap(payload[name])
        raise AttributeError(name)

    def __repr__(self):
        return f'_LLMReplayObject({object.__getattribute__(self, "_payload")!r})'


def _llm_replay_wrap(value):
    if isinstance(value, dict):
        return _LLMReplayObject(value)
    if isinstance(value, list):
        return [_llm_replay_wrap(item) for item in value]
    return value


class _LLMRecordingStream:
    """录制模式的流式包装：边转发块边积累，流耗尽时整卷落盘。
    消费方中途弃流（如零 token 失败切换）则不落盘——半卷录制没有回放价值。"""

    def __init__(self, stream, record_path: str, meta: dict):
        self._stream = stream
        self._record_path = record_path
        self._meta = meta
        self._chunks = []
        self._finalized = False

    def __iter__(self):
        return self

    def __next__(self):
        try:
            chunk = next(self._stream)
        except StopIteration:
            self._finalize()
            raise
        self._chunks.append(_llm_payload_to_jsonable(chunk))
        return chunk

    def _finalize(self):
        if self._finalized:
            return
        self._finalized = True
        try:
            record = dict(self._meta)
            record['stream'] = True
            record['chunks'] = self._chunks
            os.makedirs(os.path.dirname(self._record_path), exist_ok=True)
            with open(self._record_path, 'w', encoding='utf-8') as handle:
                json.dump(record, handle, ensure_ascii=False)
        except Exception:
            logging.exception('LLM recording failed: %s', self._record_path)

    def __getattr__(self, name):
        return getattr(self._stream, name)


class _LLMReplayStream:
    def __init__(self, chunks: list):
        self._chunks = list(chunks)
        self._index = 0

    def __iter__(self):
        return self

    def __next__(self):
        if self._index >= len(self._chunks):
            raise StopIteration
        chunk = _llm_replay_wrap(self._chunks[self._index])
        self._index += 1
        return chunk

    def close(self):
        pass


def _llm_record_replay_paths(endpoint: str, messages: list[dict], kwargs: dict):
    record_dir = str(os.environ.get('BROCCOLI_LLM_RECORD_DIR', '') or '').strip()
    replay_dir = str(os.environ.get('BROCCOLI_LLM_REPLAY_DIR', '') or '').strip()
    if not record_dir and not replay_dir:
        return '', '', ''
    fingerprint = _llm_request_fingerprint(endpoint, messages, kwargs)
    record_path = os.path.join(record_dir, f'{fingerprint}.json') if record_dir else ''
    replay_path = os.path.join(replay_dir, f'{fingerprint}.json') if replay_dir else ''
    return fingerprint, record_path, replay_path


def _llm_replay_response(replay_path: str, fingerprint: str, endpoint: str, kwargs: dict):
    if not os.path.exists(replay_path):
        raise RuntimeError(
            'Broccoli LLM replay miss: no recording for fingerprint '
            f'{fingerprint} (endpoint={endpoint!r}, model={kwargs.get("model", "")!r}) '
            f'under {os.path.dirname(replay_path)!r}'
        )
    with open(replay_path, encoding='utf-8') as handle:
        record = json.load(handle)
    if record.get('stream'):
        return _LLMReplayStream(record.get('chunks') or [])
    return _llm_replay_wrap(record.get('response') or {})


def _llm_record_response(record_path: str, meta: dict, response, is_stream: bool):
    # 流式与否由请求参数决定，不做对象嗅探（pydantic 响应对象同样可迭代，
    # 嗅探会误判）。
    if is_stream:
        return _LLMRecordingStream(response, record_path, meta)
    try:
        record = dict(meta)
        record['stream'] = False
        record['response'] = _llm_payload_to_jsonable(response)
        os.makedirs(os.path.dirname(record_path), exist_ok=True)
        with open(record_path, 'w', encoding='utf-8') as handle:
            json.dump(record, handle, ensure_ascii=False)
    except Exception:
        logging.exception('LLM recording failed: %s', record_path)
    return response


def create_chat_completion(client, *, endpoint: str = '', messages: list[dict], **kwargs):
    fingerprint, record_path, replay_path = _llm_record_replay_paths(endpoint, messages, kwargs)
    if replay_path:
        return _llm_replay_response(replay_path, fingerprint, endpoint, kwargs)
    current_messages = messages
    current_kwargs = dict(kwargs)
    retried_without_system_role = False
    retried_with_default_max_tokens = False

    for _ in range(3):
        try:
            response = client.chat.completions.create(messages=current_messages, **current_kwargs)
            if record_path:
                # 录制按原始请求指纹落盘（补偿重试改写了消息/参数也算同一次
                # 调用）：回放时同样的调用方输入能命中。
                response = _llm_record_response(
                    record_path,
                    {'fingerprint': fingerprint, 'endpoint': str(endpoint or ''),
                     'model': str(current_kwargs.get('model', '') or ''),
                     'recorded_at': datetime.datetime.now().isoformat(timespec='seconds')},
                    response,
                    bool(current_kwargs.get('stream')),
                )
            return response
        except Exception as exc:
            # Workaround for proxies that translate OpenAI chat-completions payloads
            # into Anthropic native Messages requests without hoisting system messages.
            # Native Anthropic Messages accepts top-level system text, not a
            # {"role": "system"} item inside messages.
            if not retried_without_system_role and _should_retry_without_system_role(exc, current_messages):
                current_messages = _merge_leading_system_messages_into_user(current_messages)
                retried_without_system_role = True
                log_broccoli_claude(
                    'Retrying chat completion without system role in messages for endpoint: '
                    + str(endpoint or '')
                )
                continue

            # Workaround for proxies that require Anthropic native max_tokens but
            # receive an OpenAI-style request where max_tokens is optional. 8192 is
            # large enough for normal Broccoli answers while staying below current
            # Claude 3.5+ output caps and avoiding the rate-limit cost of 32K/64K.
            if not retried_with_default_max_tokens and _should_retry_with_default_max_tokens(exc, current_kwargs):
                current_kwargs = dict(current_kwargs)
                current_kwargs['max_tokens'] = _default_max_tokens_for_chat_completion(
                    current_kwargs.get('model', '')
                )
                retried_with_default_max_tokens = True
                log_broccoli_claude(
                    'Retrying chat completion with default max_tokens='
                    + str(current_kwargs['max_tokens'])
                    + ' for endpoint: '
                    + str(endpoint or '')
                )
                continue
            raise

    return client.chat.completions.create(messages=current_messages, **current_kwargs)


# ── 思考强度（reasoning effort）：能力探测 + 档案缓存 + 抽象档翻译 ──────
# 档案旁挂存储（不进 profiles——避开设置 Save 的整表覆盖与字段白名单），
# 键 = endpoint|model|append_v1，两个同模型 profile 天然共享档案。
# 探测只挂在 profile 生命周期（保存补探/运行时缺档案后台补探），
# 任务执行路径零探测、零额外请求。
REASONING_PROBES_PATH = os.path.join(BROCCOLI_APP_DATA_DIR, 'reasoning_probes.json')
REASONING_EFFORT_STEP_LEVELS = ('light', 'standard', 'deep')
REASONING_EFFORT_PARAM_BY_LEVEL = {'light': 'low', 'standard': 'medium', 'deep': 'high'}
REASONING_EFFORT_PARAM_ORDER = ('minimal', 'low', 'medium', 'high')
REASONING_PROBE_ERROR_RETRY_SECONDS = 3600
_REASONING_PROBE_LOCK = threading.Lock()
_REASONING_PROBE_CACHE = None
_REASONING_PROBES_IN_FLIGHT = set()
REASONING_PROBE_QUESTION = 'What is 15% of 240? Reply with just the number.'


def reasoning_probe_key(profile: dict) -> str:
    endpoint = normalize_endpoint_value(str((profile or {}).get('endpoint', '') or ''))
    model = str((profile or {}).get('model', '') or '').strip()
    append_v1 = bool((profile or {}).get('append_v1', True))
    return f'{endpoint}|{model}|{int(append_v1)}'


def _load_reasoning_probe_cache() -> dict:
    global _REASONING_PROBE_CACHE
    with _REASONING_PROBE_LOCK:
        if _REASONING_PROBE_CACHE is None:
            records = {}
            try:
                if os.path.exists(REASONING_PROBES_PATH):
                    with open(REASONING_PROBES_PATH, 'r', encoding='utf-8') as handle:
                        loaded = json.load(handle)
                    if isinstance(loaded, dict):
                        records = {str(k): v for k, v in loaded.items() if isinstance(v, dict)}
            except Exception:
                records = {}
            _REASONING_PROBE_CACHE = records
        return _REASONING_PROBE_CACHE


def get_reasoning_probe_record(profile: dict) -> dict | None:
    record = _load_reasoning_probe_cache().get(reasoning_probe_key(profile))
    return dict(record) if isinstance(record, dict) else None


def save_reasoning_probe_record(profile: dict, record: dict):
    cache = _load_reasoning_probe_cache()
    with _REASONING_PROBE_LOCK:
        cache[reasoning_probe_key(profile)] = dict(record or {})
        try:
            ensure_broccoli_data_dir()
            with open(REASONING_PROBES_PATH, 'w', encoding='utf-8') as handle:
                json.dump(cache, handle, ensure_ascii=False, indent=2)
        except Exception:
            pass


def _is_unsupported_reasoning_param_error(exc) -> bool:
    text = str(exc or '').lower()
    if 'reasoning_effort' in text or 'reasoning.effort' in text or "'reasoning'" in text:
        return True
    status = getattr(exc, 'status_code', None)
    if status in (400, 422) and any(
        marker in text
        for marker in ('unsupported', 'unknown parameter', 'unexpected keyword', 'invalid parameter',
                       'unrecognized', 'extra fields', 'not supported')
    ):
        return True
    return False


def _response_reasoning_tokens(response):
    usage = getattr(response, 'usage', None)
    details = getattr(usage, 'completion_tokens_details', None)
    tokens = getattr(details, 'reasoning_tokens', None)
    if tokens is None:
        return None
    try:
        return int(tokens)
    except (TypeError, ValueError):
        return None


def probe_profile_reasoning_capability(profile: dict, send=None) -> dict:
    """探测一个 profile 的思考强度支持：参数试探 + 档位枚举 + 差分验证。

    共 3 个小请求（low / minimal / high）。差分验证靠响应里的思考 token
    明细：high 明显多于低档 → 参数真实生效（识破中转静默丢参）；两侧
    无差异 → 判不支持；服务不报明细 → supported 但 unverified。
    send(effort_value) 可注入（测试用），默认真发请求。"""
    if send is None:
        api_key = str(profile.get('api_key', '') or '').strip()
        model = str(profile.get('model', '') or '').strip()
        if not api_key or not model:
            return {'status': 'error', 'error': 'profile missing key/model',
                    'error_at': datetime.datetime.now().isoformat(timespec='seconds')}
        try:
            timeout = int(profile.get('timeout', 60) or 60)
        except (TypeError, ValueError):
            timeout = 60
        endpoint = profile_runtime_base_url(profile)
        client = create_openai_client(api_key, endpoint, min(timeout, 90))

        def send(effort_value):
            return create_chat_completion(
                client,
                endpoint=endpoint,
                model=model,
                messages=[{'role': 'user', 'content': REASONING_PROBE_QUESTION}],
                stream=False,
                extra_body={'reasoning_effort': effort_value},
            )

    now_iso = datetime.datetime.now().isoformat(timespec='seconds')
    try:
        response_low = send('low')
    except Exception as exc:
        if _is_unsupported_reasoning_param_error(exc):
            return {'status': 'unsupported', 'mechanism': '', 'levels': [], 'verified': False, 'probed_at': now_iso}
        return {'status': 'error', 'error': str(exc)[:300], 'error_at': now_iso}
    levels = ['low']
    minimal_response = None
    try:
        minimal_response = send('minimal')
        levels.insert(0, 'minimal')
    except Exception:
        minimal_response = None
    try:
        response_high = send('high')
        levels.append('medium')   # low 与 high 都可用时按枚举连续性推断 medium
        levels.append('high')
    except Exception as exc:
        if _is_unsupported_reasoning_param_error(exc):
            response_high = None
        else:
            return {'status': 'error', 'error': str(exc)[:300], 'error_at': now_iso}
    low_side = minimal_response if minimal_response is not None else response_low
    tokens_low = _response_reasoning_tokens(low_side)
    tokens_high = _response_reasoning_tokens(response_high) if response_high is not None else None
    verified = False
    if tokens_low is not None and tokens_high is not None:
        if tokens_high > max(tokens_low * 1.3, tokens_low + 48):
            verified = True
        else:
            # 明细存在但高低无差异：参数被服务端接受却不生效（静默丢参）。
            return {'status': 'unsupported', 'mechanism': '', 'levels': [], 'verified': False, 'probed_at': now_iso}
    return {
        'status': 'supported',
        'mechanism': 'reasoning_effort',
        'levels': levels,
        'verified': verified,
        'probed_at': now_iso,
    }


def get_reasoning_override(profile: dict) -> str:
    """手动覆盖：'on'（强制注入）/'off'（永不注入）/'auto'（按探测档案）。
    探测误判时的人工纠正口，存在探测档案里（不动 profiles 结构）。"""
    record = get_reasoning_probe_record(profile) or {}
    mode = str(record.get('override', '') or '').strip()
    return mode if mode in ('on', 'off') else 'auto'


def set_reasoning_override(profile: dict, mode: str):
    record = get_reasoning_probe_record(profile) or {}
    mode = str(mode or '').strip()
    if mode in ('on', 'off'):
        record['override'] = mode
    else:
        record.pop('override', None)
    save_reasoning_probe_record(profile, record)


def resolve_reasoning_effort_param(profile: dict, level: str) -> str | None:
    """抽象档（light/standard/deep）→ 该 profile 实际可用的参数值。"""
    level = str(level or '').strip().lower()
    target = REASONING_EFFORT_PARAM_BY_LEVEL.get(level)
    if not target:
        return None
    record = get_reasoning_probe_record(profile)
    override = str((record or {}).get('override', '') or '')
    if override == 'off':
        return None
    if override != 'on' and (not record or record.get('status') != 'supported'):
        return None
    levels = [value for value in ((record or {}).get('levels') or []) if value in REASONING_EFFORT_PARAM_ORDER]
    if not levels or target in levels:
        return target
    order = list(REASONING_EFFORT_PARAM_ORDER)
    target_index = order.index(target)
    return min(levels, key=lambda value: abs(order.index(value) - target_index))


def resolve_reasoning_effort_param_for_runtime(endpoint: str, model: str, level: str) -> str | None:
    """按运行时 endpoint+model 反查 profile 再翻译抽象档——给只持有散装
    连接参数（而非 profile dict）的最终回答管线用。"""
    endpoint = str(endpoint or '').strip().rstrip('/')
    model = str(model or '').strip()
    if not endpoint or not model or not level:
        return None
    try:
        store = load_settings_store()
    except Exception:
        return None
    for profile in store.get('profiles', []):
        if str(profile.get('model', '') or '').strip() != model:
            continue
        try:
            if profile_runtime_base_url(profile).rstrip('/') != endpoint:
                continue
        except Exception:
            continue
        return resolve_reasoning_effort_param(profile, level)
    return None


def mark_reasoning_probe_unsupported(profile: dict):
    save_reasoning_probe_record(profile, {
        'status': 'unsupported', 'mechanism': '', 'levels': [], 'verified': False,
        'probed_at': datetime.datetime.now().isoformat(timespec='seconds'),
        'source': 'runtime_400',
    })


def ensure_reasoning_probe_async(profile: dict):
    """档案缺失（或探测失败已过退避期）时后台补探一次；有终态档案、
    探测中、退避期内都直接返回。任务路径调用它永不阻塞。"""
    profile = dict(profile or {})
    key = reasoning_probe_key(profile)
    record = _load_reasoning_probe_cache().get(key)
    if isinstance(record, dict):
        if str(record.get('override', '') or '') in ('on', 'off'):
            return   # 手动覆盖生效中，探测结论不会被使用，省掉请求
        status = str(record.get('status', '') or '')
        if status in ('supported', 'unsupported'):
            return
        if status == 'error':
            try:
                error_at = datetime.datetime.fromisoformat(str(record.get('error_at', '') or ''))
                if (datetime.datetime.now() - error_at).total_seconds() < REASONING_PROBE_ERROR_RETRY_SECONDS:
                    return
            except (TypeError, ValueError):
                pass
    with _REASONING_PROBE_LOCK:
        if key in _REASONING_PROBES_IN_FLIGHT:
            return
        _REASONING_PROBES_IN_FLIGHT.add(key)

    def run_probe():
        try:
            record = probe_profile_reasoning_capability(profile)
            save_reasoning_probe_record(profile, record)
        except Exception:
            pass
        finally:
            with _REASONING_PROBE_LOCK:
                _REASONING_PROBES_IN_FLIGHT.discard(key)

    threading.Thread(target=run_probe, daemon=True, name='reasoning-probe').start()


# ── 能力槽位多候选 + 模型质量档案 ────────────────────────────────
# specialized_profiles 保持单值（= 第一顺位，兼容全部旧代码）；候选有序
# 名单存 specialized_profile_candidates。质量档案旁挂文件：每步 review 的
# meets_goal 顺手落档（零额外请求），planner 选型时按门槛读取摘要。
MODEL_QUALITY_RECORDS_PATH = os.path.join(BROCCOLI_APP_DATA_DIR, 'model_quality_records.json')
MODEL_QUALITY_MAX_RECORDS = 200
MODEL_QUALITY_MIN_RECORDS_FOR_SUMMARY = 5
_MODEL_QUALITY_LOCK = threading.Lock()
_MODEL_QUALITY_CACHE = None


def normalize_specialized_profile_candidates(raw) -> dict:
    normalized = {}
    if not isinstance(raw, dict):
        return normalized
    for capability, names in raw.items():
        capability = str(capability or '').strip()
        if not capability:
            continue
        cleaned = []
        for name in (names if isinstance(names, (list, tuple)) else [names]):
            name = str(name or '').strip()
            if name and name not in cleaned:
                cleaned.append(name)
        if cleaned:
            normalized[capability] = cleaned
    return normalized


def get_specialized_profile_candidates_from_store(store: dict | None = None) -> dict:
    if store is None:
        store = load_settings_store()
    globals_store = store.get('globals', {}) if isinstance(store, dict) else {}
    candidates = normalize_specialized_profile_candidates(globals_store.get('specialized_profile_candidates'))
    # 单值槽位兜底：candidates 缺失时退化为各单值键的单人名单。
    # router/embedding/browser_use 也有候选（"每个工具都可排序"），执行
    # 语义仍取第一顺位（= 原单值键，行为不变）。
    specialized = normalize_specialized_profiles(globals_store.get('specialized_profiles'))
    for capability, name in specialized.items():
        name = str(name or '').strip()
        if name and capability not in candidates:
            candidates[capability] = [name]
    for slot_key, globals_key in (('embedding', 'embedding_profile'), ('browser_use', 'browser_use_profile')):
        name = str(globals_store.get(globals_key, '') or '').strip()
        if name and slot_key not in candidates:
            candidates[slot_key] = [name]
    # Default chat / 最终答复也可排序（选项 A）：缺配置时第一顺位 = 当前激活
    # 档案，行为与今天一致；配置后由第一顺位决定 default chat 模型、其余顺位
    # 供运行时失败回退。final_answer 不进 SPECIALIZED_CAPABILITIES，故
    # build_model_candidates_block 不会把它漏给 planner（那里按步骤能力过滤）。
    if 'final_answer' not in candidates:
        active_name = str(store.get('active_profile', '') or '').strip()
        if active_name and get_profile_from_store_by_name(store, active_name) is not None:
            candidates['final_answer'] = [active_name]
    return candidates


def first_usable_profile_candidate(store: dict, capability: str) -> str:
    """能力候选里第一个真实存在的普通 profile——@/& 目标运行时不可用
    （没打开/被删）时的回落对象；没有则返回空串。"""
    for name in get_specialized_profile_candidates_from_store(store).get(str(capability or ''), []):
        if name.startswith('@') or name.startswith(CUSTOM_SERVICE_PREFIX):
            continue
        if get_profile_from_store_by_name(store, name) is not None:
            return name
    return ''


def ordered_usable_profile_candidates(store: dict, capability: str, exclude=None) -> list:
    """能力候选里按顺位排列、真实存在的普通 profile 名（跳过 @/& 目标与
    exclude 里已试过的名字）。运行时某顺位不可用时，逐顺位回退用。"""
    excluded = {str(n or '').strip() for n in (exclude or ())}
    out = []
    for name in get_specialized_profile_candidates_from_store(store).get(str(capability or ''), []):
        name = str(name or '').strip()
        if not name or name in excluded or name in out:
            continue
        if name.startswith('@') or name.startswith(CUSTOM_SERVICE_PREFIX):
            continue
        if get_profile_from_store_by_name(store, name) is not None:
            out.append(name)
    return out


# 运行时"该换下一顺位模型"的失败判定：只认"这个模型/供应商暂时不可用，或
# 凭据/额度问题"这一类——换一个不同 key/endpoint 的候选有意义。参数错、正常
# 内容/拒答、用户停止都不在此列（换同类模型也白搭）。
_MODEL_UNAVAILABLE_MARKERS = (
    'model_cooldown', 'cooling down', 'cooldown',
    'rate limit', 'rate_limit', 'ratelimit', 'too many requests',
    'overloaded', 'over capacity', 'at capacity',
    'temporarily unavailable', 'service unavailable', 'service_unavailable',
    'bad gateway', 'gateway timeout', 'timeout', 'timed out',
    'connection error', 'connection reset', 'connection aborted', 'connection refused',
    'insufficient', 'quota', 'billing', 'payment required',
    'invalid api key', 'incorrect api key', 'invalid_api_key', 'unauthorized',
)
_MODEL_UNAVAILABLE_STATUS = {401, 402, 408, 409, 429, 500, 502, 503, 504}


def _is_model_unavailable_error(exc: Exception) -> bool:
    status = getattr(exc, 'status_code', None)
    if status is None:
        status = getattr(exc, 'http_status', None)
    if status is None:
        resp = getattr(exc, 'response', None)
        status = getattr(resp, 'status_code', None) if resp is not None else None
    try:
        if status is not None and int(status) in _MODEL_UNAVAILABLE_STATUS:
            return True
    except (TypeError, ValueError):
        pass
    text = str(exc).lower()
    for code in ('429', '401', '402', '408', '409', '500', '502', '503', '504'):
        if code in text:
            return True
    return any(marker in text for marker in _MODEL_UNAVAILABLE_MARKERS)


BROWSER_USE_FAILOVER_ERROR_TAIL = 5
_BROWSER_USE_LLM_ERROR_CODE_RE = re.compile(
    r'error code:\s*(401|402|408|409|429|500|502|503|504)\b',
    re.IGNORECASE,
)
_BROWSER_USE_LLM_ERROR_MARKERS = (
    'auth_unavailable', 'no auth available',
    'rate limit', 'rate_limit', 'ratelimit', 'too many requests',
    'model_cooldown', 'cooling down', 'cooldown',
    'insufficient_quota', 'quota', 'billing', 'payment required',
    'invalid api key', 'incorrect api key', 'invalid_api_key', 'unauthorized',
    'overloaded',
)


def _browser_use_llm_unavailable_text(text: str) -> bool:
    candidate = str(text or '')
    if _BROWSER_USE_LLM_ERROR_CODE_RE.search(candidate):
        return True
    lowered = candidate.lower()
    return any(marker in lowered for marker in _BROWSER_USE_LLM_ERROR_MARKERS)


def _browser_use_result_needs_failover(result) -> bool:
    if not isinstance(result, dict) or result.get('cancelled'):
        return False
    metadata = result.get('metadata')
    if not isinstance(metadata, dict) or not metadata.get('partial'):
        return False
    errors = metadata.get('errors') or []
    texts = [str(metadata.get('error', '') or '')]
    texts.extend(str(item) for item in errors[-BROWSER_USE_FAILOVER_ERROR_TAIL:])
    return any(_browser_use_llm_unavailable_text(text) for text in texts)


def _computer_use_result_needs_failover(result) -> bool:
    # Computer Use twin of _browser_use_result_needs_failover, adapted to the cua
    # worker's result shape: a partial is `ok is False` (with salvage metadata).
    # Switch models ONLY when the error text looks like an availability/credential/
    # quota failure — a max-steps exhaustion or an overall-time-limit ending must
    # never restart the desktop task on the next model.
    if not isinstance(result, dict) or result.get('cancelled'):
        return False
    if result.get('ok') is not False:
        return False
    metadata = result.get('metadata')
    if not isinstance(metadata, dict) or not metadata.get('partial'):
        return False
    # Driver/MCP failures can legitimately contain words such as "timeout",
    # "401" or "unauthorized". Re-running the whole desktop task on another
    # model cannot fix those failures and can duplicate side effects. Only the
    # worker's explicitly classified model/LLM availability failures rotate.
    failure_source = str(
        metadata.get('failure_source', '') or metadata.get('error_source', '') or ''
    ).strip().lower()
    if failure_source not in {'model', 'llm'} and not metadata.get('model_unavailable'):
        return False
    return _browser_use_llm_unavailable_text(str(result.get('error', '') or ''))


COMPUTER_USE_PARTIAL_OUTPUT_LABEL = 'Partial output (task did not complete):'


def _computer_use_failure_detail(result) -> str:
    """Render a final Computer Use failure without letting stale model prose
    hide the worker/driver error.  Keep this separate from failover: callers
    must first inspect the original structured result, then render it only once
    no further model candidate will be tried."""
    payload = result if isinstance(result, dict) else {}
    error_text = str(payload.get('error', '') or '').strip() or 'Computer Use failed.'
    partial_text = str(payload.get('answer', '') or '').strip()
    if partial_text:
        return error_text + '\n\n' + COMPUTER_USE_PARTIAL_OUTPUT_LABEL + '\n' + partial_text
    return error_text


def _computer_use_result_text(result,
                              *,
                              failure_prefix: str = 'Computer Use failed: ',
                              success_default: str = 'Computer Use task completed.') -> str:
    payload = result if isinstance(result, dict) else {}
    if payload.get('cancelled'):
        return str(payload.get('answer', '') or 'Computer Use task was stopped.').strip()
    if payload.get('ok') is False:
        return str(failure_prefix or '') + _computer_use_failure_detail(payload)
    return str(payload.get('answer', '') or payload.get('error', '') or success_default).strip()


def _load_model_quality_cache() -> dict:
    global _MODEL_QUALITY_CACHE
    with _MODEL_QUALITY_LOCK:
        if _MODEL_QUALITY_CACHE is None:
            records = {}
            try:
                if os.path.exists(MODEL_QUALITY_RECORDS_PATH):
                    with open(MODEL_QUALITY_RECORDS_PATH, 'r', encoding='utf-8') as handle:
                        loaded = json.load(handle)
                    if isinstance(loaded, dict):
                        records = {str(k): v for k, v in loaded.items() if isinstance(v, dict)}
            except Exception:
                records = {}
            _MODEL_QUALITY_CACHE = records
        return _MODEL_QUALITY_CACHE


def _save_model_quality_cache():
    cache = _load_model_quality_cache()
    with _MODEL_QUALITY_LOCK:
        try:
            ensure_broccoli_data_dir()
            with open(MODEL_QUALITY_RECORDS_PATH, 'w', encoding='utf-8') as handle:
                json.dump(cache, handle, ensure_ascii=False, indent=2)
        except Exception:
            pass


def get_model_quality_entry(profile_name: str) -> dict:
    entry = _load_model_quality_cache().get(str(profile_name or '').strip())
    if not isinstance(entry, dict):
        return {'auto_records': [], 'stats': {}, 'user_notes': ''}
    return {
        'auto_records': list(entry.get('auto_records') or []),
        'stats': dict(entry.get('stats') or {}),
        'user_notes': str(entry.get('user_notes', '') or ''),
    }


def record_model_quality(profile_name: str, capability: str, meets_goal: bool, reason: str = ''):
    profile_name = str(profile_name or '').strip()
    capability = str(capability or '').strip()
    if not profile_name or not capability:
        return
    if profile_name.startswith('@') or profile_name.startswith(CUSTOM_SERVICE_PREFIX):
        return
    cache = _load_model_quality_cache()
    with _MODEL_QUALITY_LOCK:
        entry = cache.setdefault(profile_name, {'auto_records': [], 'stats': {}, 'user_notes': ''})
        records = entry.setdefault('auto_records', [])
        records.append({
            'capability': capability,
            'meets_goal': bool(meets_goal),
            'reason': str(reason or '').strip()[:200],
            'at': datetime.datetime.now().isoformat(timespec='seconds'),
        })
        del records[:-MODEL_QUALITY_MAX_RECORDS]
        stats = entry.setdefault('stats', {})
        capability_stats = stats.setdefault(capability, {'met': 0, 'total': 0})
        capability_stats['total'] = int(capability_stats.get('total', 0) or 0) + 1
        if meets_goal:
            capability_stats['met'] = int(capability_stats.get('met', 0) or 0) + 1
    _save_model_quality_cache()


def set_model_user_notes(profile_name: str, notes: str):
    profile_name = str(profile_name or '').strip()
    if not profile_name:
        return
    cache = _load_model_quality_cache()
    with _MODEL_QUALITY_LOCK:
        entry = cache.setdefault(profile_name, {'auto_records': [], 'stats': {}, 'user_notes': ''})
        entry['user_notes'] = str(notes or '').strip()
    _save_model_quality_cache()


def model_quality_auto_summary(profile_name: str, min_records: int = MODEL_QUALITY_MIN_RECORDS_FOR_SUMMARY,
                               localize: bool = False) -> str:
    # localize=True only for the Settings model-quality table; the planner prompt
    # (build_model_candidates_block) keeps the default English text.
    """自动档案的一行摘要（达标率 + 最近一条失败原句）。样本不足门槛
    返回空串——小样本统计只会误导 planner。"""
    entry = get_model_quality_entry(profile_name)
    stats = entry.get('stats') or {}
    total = sum(int((s or {}).get('total', 0) or 0) for s in stats.values())
    if total < max(1, int(min_records)):
        return ''
    met = sum(int((s or {}).get('met', 0) or 0) for s in stats.values())
    met_template = _tr('{met}/{total} steps met goal') if localize else '{met}/{total} steps met goal'
    parts = [met_template.format(met=met, total=total)]
    capability_bits = [
        f"{capability} {int(s.get('met', 0) or 0)}/{int(s.get('total', 0) or 0)}"
        for capability, s in sorted(stats.items())
        if int((s or {}).get('total', 0) or 0) > 0
    ]
    if capability_bits:
        parts.append('(' + ', '.join(capability_bits[:4]) + ')')
    last_failure = next(
        (r for r in reversed(entry.get('auto_records') or []) if not r.get('meets_goal') and str(r.get('reason', '') or '').strip()),
        None,
    )
    if last_failure:
        miss_template = _tr('recent miss: {reason}') if localize else 'recent miss: {reason}'
        parts.append(miss_template.format(reason=str(last_failure.get('reason', ''))[:100]))
    return '; '.join(parts)


def build_model_candidates_block(store: dict | None = None) -> str:
    """planner 提示词的候选模型段：只列出多候选能力，每个候选一行
    （顺位 + 名字 + 质量摘要 + 用户笔记）。单候选能力不出现（无可选）。"""
    candidates = get_specialized_profile_candidates_from_store(store)
    step_capabilities = {key for key, _label in SPECIALIZED_CAPABILITIES}
    lines = []
    for capability, names in sorted(candidates.items()):
        # 只有 planner 可分配的步骤能力进提示词；router/embedding/
        # browser_use 的排序是"首选+备选"，不参与步骤选型。
        if capability not in step_capabilities:
            continue
        usable = [n for n in names if not n.startswith('@') and not n.startswith(CUSTOM_SERVICE_PREFIX)]
        if len(usable) < 2:
            continue
        lines.append(f'{capability}:')
        for rank, name in enumerate(usable, start=1):
            summary = model_quality_auto_summary(name)
            notes = get_model_quality_entry(name).get('user_notes', '')[:120]
            detail = '; '.join(part for part in (summary, ('user notes: ' + notes) if notes else '') if part)
            lines.append(f'  {rank}. {name}' + (f' — {detail}' if detail else ''))
    return '\n'.join(lines)


def capture_all_screens_png_bytes() -> bytes:
    try:
        import Quartz as _Quartz
        from PIL import Image as _PILImage
    except Exception as exc:
        raise RuntimeError(f'Background vision screenshot dependencies unavailable: {exc}') from exc

    image = _Quartz.CGWindowListCreateImage(
        _Quartz.CGRectInfinite,
        _Quartz.kCGWindowListOptionOnScreenOnly,
        _Quartz.kCGNullWindowID,
        _Quartz.kCGWindowImageDefault,
    )
    if image is None:
        raise RuntimeError('No screen image captured. Check macOS Screen Recording permission for Broccoli.')

    width = _Quartz.CGImageGetWidth(image)
    height = _Quartz.CGImageGetHeight(image)
    bytes_per_row = _Quartz.CGImageGetBytesPerRow(image)
    provider = _Quartz.CGImageGetDataProvider(image)
    raw_data = _Quartz.CGDataProviderCopyData(provider)
    pil_image = _PILImage.frombuffer(
        'RGBA',
        (width, height),
        bytes(raw_data),
        'raw',
        'BGRA',
        bytes_per_row,
        1,
    )
    with BytesIO() as output:
        pil_image.save(output, format='PNG')
        return output.getvalue()


class BackgroundVisionWorker(QThread):
    status = pyqtSignal(str)
    error = pyqtSignal(str)
    record_ready = pyqtSignal(object)

    def __init__(self, targets: list[dict], settings: dict, parent=None):
        super().__init__(parent)
        self.targets = [dict(target) for target in targets if isinstance(target, dict)]
        self.settings = normalize_background_vision_settings(settings)
        self._stop_event = threading.Event()
        self._executor = None
        self._round_index = 0
        self._active_rounds = 0
        self._active_rounds_lock = threading.Lock()
        self._history_lock = threading.Lock()
        self._history_turns_by_target = {}
        self._after_completion_event = threading.Event()

    def stop(self):
        self._stop_event.set()

    def _wait_with_countdown(self, total_seconds: float) -> bool:
        deadline = time.monotonic() + max(0.0, float(total_seconds or 0))
        while not self._stop_event.is_set():
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                return False
            if self._stop_event.wait(min(1.0, remaining)):
                return True
        return True

    def _try_reserve_round_slot(self) -> bool:
        with self._active_rounds_lock:
            if self._active_rounds >= int(self.settings.get('background_vision_max_workers', 1)):
                return False
            self._active_rounds += 1
            return True

    def _release_round_slot(self):
        with self._active_rounds_lock:
            if self._active_rounds > 0:
                self._active_rounds -= 1

    def run(self):
        if not self.targets:
            self.error.emit('Background vision has no usable profile target.')
            return
        max_workers = int(self.settings.get('background_vision_max_workers', 1) or 1)
        self._executor = ThreadPoolExecutor(max_workers=max_workers, thread_name_prefix='broccoli-bg-vision')
        try:
            if self.settings.get('background_vision_schedule_mode') == 'after_completion':
                self._run_after_completion_schedule()
            else:
                self._run_fixed_interval_schedule()
        finally:
            if self._executor is not None:
                self._executor.shutdown(wait=True, cancel_futures=False)
                self._executor = None

    def _run_fixed_interval_schedule(self):
        interval = int(self.settings.get('background_vision_interval_sec', DEFAULT_BACKGROUND_VISION_INTERVAL_SECONDS) or DEFAULT_BACKGROUND_VISION_INTERVAL_SECONDS)
        next_run = time.monotonic()
        while not self._stop_event.is_set():
            now = time.monotonic()
            if now < next_run:
                if self._wait_with_countdown(next_run - now):
                    break
                continue
            self._submit_round()
            next_run += max(1, interval)

    def _run_after_completion_schedule(self):
        delay = int(self.settings.get('background_vision_completion_delay_sec', DEFAULT_BACKGROUND_VISION_COMPLETION_DELAY_SECONDS) or 0)
        while not self._stop_event.is_set():
            self._after_completion_event.clear()
            self._submit_round()
            while not self._stop_event.is_set():
                if self._after_completion_event.wait(0.2):
                    break
            if self._stop_event.is_set():
                break
            if delay > 0 and self._wait_with_countdown(delay):
                break

    def _submit_round(self):
        if self._executor is None or self._stop_event.is_set():
            return
        self._round_index += 1
        round_id = self._round_index
        if not self._try_reserve_round_slot():
            self.status.emit('Background vision skipped one round because concurrency is full.')
            return
        try:
            self._executor.submit(self._run_round_and_release, round_id)
        except Exception:
            self._release_round_slot()
            raise

    def _run_round_and_release(self, round_id: int):
        try:
            self._run_single_round(round_id)
        finally:
            self._release_round_slot()

    def _save_capture_image(self, round_id: int, image_png: bytes) -> str:
        if not bool(self.settings.get('background_vision_save_captures', False)):
            return ''
        capture_dir = str(self.settings.get('background_vision_capture_dir', '') or BACKGROUND_VISION_CAPTURE_DIR).strip() or BACKGROUND_VISION_CAPTURE_DIR
        os.makedirs(capture_dir, exist_ok=True)
        timestamp = datetime.datetime.now().strftime('%Y%m%d_%H%M%S')
        path = os.path.join(capture_dir, f'background_vision_{round_id:04d}_{timestamp}.png')
        with open(path, 'wb') as handle:
            handle.write(image_png)
        return path

    def _encode_image_payload(self, png_bytes: bytes, image_format: str) -> dict:
        image_format = normalize_background_vision_image_format(image_format)
        if image_format == 'webp_lossless':
            try:
                from PIL import Image as _PILImage
                with _PILImage.open(BytesIO(png_bytes)) as image:
                    converted = image.convert('RGBA') if image.mode not in ('RGB', 'RGBA') else image.copy()
                with BytesIO() as output:
                    converted.save(output, format='WEBP', lossless=True, method=6)
                    image_bytes = output.getvalue()
                return {
                    'format': 'webp_lossless',
                    'mime_type': 'image/webp',
                    'base64': base64.b64encode(image_bytes).decode('utf-8'),
                }
            except Exception:
                pass
        return {
            'format': 'png',
            'mime_type': 'image/png',
            'base64': base64.b64encode(png_bytes).decode('utf-8'),
        }

    def _get_history_turns(self, history_key: str) -> list[tuple[str, str]]:
        if not bool(self.settings.get('background_vision_keep_history_context', False)):
            return []
        with self._history_lock:
            return list(self._history_turns_by_target.get(history_key, []))

    def _append_history_turn(self, history_key: str, round_id: int, assistant_text: str):
        if not bool(self.settings.get('background_vision_keep_history_context', False)):
            return
        max_messages = int(self.settings.get('background_vision_max_history_messages', 0) or 0)
        with self._history_lock:
            turns = self._history_turns_by_target.setdefault(history_key, [])
            turns.append((f'Round {round_id}: new full-screen screenshot.', str(assistant_text or '').strip()))
            max_turns = max_messages // 2
            if max_turns <= 0:
                turns.clear()
            elif len(turns) > max_turns:
                self._history_turns_by_target[history_key] = turns[-max_turns:]

    def _run_single_round(self, round_id: int):
        created_at = datetime.datetime.now().isoformat(timespec='seconds')
        record = {
            'id': f'vision-{int(time.time() * 1000)}-{round_id}',
            'round_id': round_id,
            'created_at': created_at,
            'completed_at': '',
            'complete': False,
            'prompt': str(self.settings.get('background_vision_prompt', DEFAULT_BACKGROUND_VISION_PROMPT) or ''),
            'capture_path': '',
            'targets': [],
            'context_text': '',
        }
        try:
            self.status.emit(f'Background vision round {round_id}: capturing screen')
            png_bytes = capture_all_screens_png_bytes()
            record['capture_path'] = self._save_capture_image(round_id, png_bytes)
            payload = self._encode_image_payload(
                png_bytes,
                self.settings.get('background_vision_image_format', 'png'),
            )
            if len(self.targets) == 1:
                results = [self._run_single_target(round_id, self.targets[0], payload)]
            else:
                worker_count = max(1, min(len(self.targets), 16))
                results = []
                with ThreadPoolExecutor(max_workers=worker_count, thread_name_prefix=f'bg-vision-round-{round_id}') as executor:
                    futures = [executor.submit(self._run_single_target, round_id, target, payload) for target in self.targets]
                    for future in as_completed(futures):
                        results.append(future.result())
            record['targets'] = results
            record['complete'] = any(item.get('status') == 'ok' and str(item.get('text', '')).strip() for item in results)
            record['context_text'] = self._build_context_text(results)
            record['completed_at'] = datetime.datetime.now().isoformat(timespec='seconds')
            self.record_ready.emit(record)
            self.status.emit(f'Background vision round {round_id}: complete')
        except Exception as exc:
            record['completed_at'] = datetime.datetime.now().isoformat(timespec='seconds')
            record['targets'] = [{'profile': '', 'model': '', 'status': 'error', 'text': '', 'error': str(exc)}]
            self.record_ready.emit(record)
            self.error.emit(str(exc))
        finally:
            if self.settings.get('background_vision_schedule_mode') == 'after_completion':
                self._after_completion_event.set()

    def _run_single_target(self, round_id: int, target: dict, image_payload: dict) -> dict:
        profile_name = str(target.get('name', '') or 'Profile').strip()
        model = str(target.get('model', '') or '').strip()
        result = {'profile': profile_name, 'model': model, 'status': 'error', 'text': '', 'error': ''}
        try:
            api_key = str(target.get('api_key', '') or '').strip()
            endpoint = str(target.get('endpoint', '') or '').strip()
            timeout = _coerce_int(target.get('timeout', 60), 60, 5, 600)
            if not api_key or not endpoint or not model:
                raise RuntimeError('profile is missing API key, endpoint, or model')
            client = create_openai_client(api_key, endpoint, timeout)
            prompt = str(self.settings.get('background_vision_prompt', DEFAULT_BACKGROUND_VISION_PROMPT) or '').strip() or DEFAULT_BACKGROUND_VISION_PROMPT
            messages = [{'role': 'system', 'content': prompt}]
            for user_text, assistant_text in self._get_history_turns(profile_name):
                messages.append({'role': 'user', 'content': user_text})
                messages.append({'role': 'assistant', 'content': assistant_text})
            data_url = f"data:{image_payload['mime_type']};base64,{image_payload['base64']}"
            messages.append({
                'role': 'user',
                'content': [
                    {'type': 'text', 'text': 'Analyze this current full-screen screenshot for background context.'},
                    {'type': 'image_url', 'image_url': {'url': data_url}},
                ],
            })
            response = create_chat_completion(
                client,
                endpoint=endpoint,
                model=model,
                messages=messages,
                stream=False,
            )
            text = str(response.choices[0].message.content or '').strip()
            result.update({'status': 'ok', 'text': text, 'error': ''})
            self._append_history_turn(profile_name, round_id, text)
        except Exception as exc:
            result['error'] = str(exc)
        finally:
            if (
                self.settings.get('background_vision_schedule_mode') == 'after_completion'
                and self.settings.get('background_vision_multi_target_wait_mode') == 'first_done'
            ):
                self._after_completion_event.set()
        return result

    def _build_context_text(self, results: list[dict]) -> str:
        ok_items = [
            item for item in results
            if isinstance(item, dict) and item.get('status') == 'ok' and str(item.get('text', '')).strip()
        ]
        if not ok_items:
            return ''
        blocks = []
        for item in ok_items:
            profile_name = str(item.get('profile', '') or 'Vision model').strip()
            text = _compact_background_vision_text(item.get('text', ''), 2400)
            if text:
                blocks.append(f'[{profile_name}] {text}')
        return _compact_background_vision_text('\n'.join(blocks), DEFAULT_BACKGROUND_VISION_CONTEXT_MAX_CHARS)


def get_specialized_profiles_from_store(store: dict | None = None) -> dict:
    if store is None:
        store = load_settings_store()
    globals_store = store.get('globals', {}) if isinstance(store, dict) else {}
    return normalize_specialized_profiles(globals_store.get('specialized_profiles'))


def get_specialized_execution_modes_from_store(store: dict | None = None) -> dict:
    if store is None:
        store = load_settings_store()
    globals_store = store.get('globals', {}) if isinstance(store, dict) else {}
    return normalize_specialized_execution_modes(globals_store.get('specialized_execution_modes'))


def resolve_specialized_execution_mode(store: dict | None, capability: str) -> str:
    modes = get_specialized_execution_modes_from_store(store)
    return str(modes.get(capability, default_specialized_execution_modes().get(capability, '')) or '').strip()


def get_planner_profile_from_store(store: dict | None = None) -> dict:
    if store is None:
        store = load_settings_store()
    specialized = get_specialized_profiles_from_store(store)
    planner_name = str(specialized.get('router', '')).strip()
    if planner_name:
        profile = get_profile_from_store_by_name(store, planner_name)
        if profile is not None:
            return profile
    return load_active_settings_profile()


def resolve_specialized_profile(store: dict, capability: str, fallback_profile: dict | None = None) -> dict | None:
    specialized = get_specialized_profiles_from_store(store)
    profile_name = str(specialized.get(capability, '')).strip()
    if profile_name:
        profile = get_profile_from_store_by_name(store, profile_name)
        if profile is not None:
            return profile
    return fallback_profile


def parse_json_object_from_text(text: str) -> dict | None:
    raw = str(text or '').strip()
    if not raw:
        return None
    try:
        obj = json.loads(raw)
        return obj if isinstance(obj, dict) else None
    except Exception:
        pass
    match = re.search(r'\{.*\}', raw, re.DOTALL)
    if not match:
        return None
    try:
        obj = json.loads(match.group(0))
        return obj if isinstance(obj, dict) else None
    except Exception:
        return None


class ReviewStreamProbe:
    """Incrementally translates a STREAMING review JSON into short human-readable
    fragments for the live preview. Client-side only — the review prompt, output
    and final parse are untouched; this just watches the accumulating raw text.
    feed(delta) returns the NEW display fragment ('' when nothing new completed).
    Scalar verdict fields are emitted once when their value is complete; the big
    context_output string is decoded and streamed incrementally. Escape sequences
    split across deltas are carried over in a pending buffer. Display-only: a
    pathological context_output that itself contains review-field text could echo
    a bogus line — harmless, never touches parsing."""

    _CTX_OPEN = re.compile(r'"context_output"\s*:\s*"')

    def __init__(self):
        self._buf = ''
        self._done = set()
        self._ctx_state = 'searching'   # searching -> streaming -> done
        self._ctx_pos = 0
        self._pending_escape = ''

    @staticmethod
    def _unescape(value):
        try:
            decoded = json.loads('"%s"' % value)
            return decoded if isinstance(decoded, str) else str(decoded)
        except Exception:
            return value

    @staticmethod
    def _unescape_sequence(seq):
        try:
            decoded = json.loads('"%s"' % seq)
            return decoded if isinstance(decoded, str) else str(decoded)
        except Exception:
            return seq[1:] if len(seq) >= 2 else seq

    def feed(self, delta):
        text = str(delta or '')
        if not text:
            return ''
        self._buf += text
        out = []
        if 'meets_goal' not in self._done:
            match = re.search(r'"meets_goal"\s*:\s*(true|false)', self._buf)
            if match:
                self._done.add('meets_goal')
                out.append('\n· ' + (_tr('goal met') if match.group(1) == 'true' else _tr('goal NOT met')))
        for field, label in (('next_action', _tr('next: {value}')), ('missing', _tr('missing: {value}')), ('reason', _tr('reason: {value}'))):
            if field in self._done:
                continue
            match = re.search(r'"%s"\s*:\s*"((?:[^"\\]|\\.)*)"' % field, self._buf)
            if match:
                self._done.add(field)
                value = re.sub(r'\s+', ' ', str(self._unescape(match.group(1)))).strip()
                if value:
                    if len(value) > 110:
                        value = value[:107].rstrip() + '...'
                    out.append('\n· ' + label.format(value=value))
        out.extend(self._feed_context())
        return ''.join(out)

    def _feed_context(self):
        pieces = []
        if self._ctx_state == 'searching':
            match = self._CTX_OPEN.search(self._buf)
            if match:
                self._ctx_state = 'streaming'
                self._ctx_pos = match.end()
                pieces.append('\n· ' + _tr('evidence:') + ' ')
        if self._ctx_state == 'streaming':
            decoded, consumed, closed = self._decode_json_string(self._buf[self._ctx_pos:])
            self._ctx_pos += consumed
            if decoded:
                pieces.append(decoded)
            if closed:
                self._ctx_state = 'done'
        return pieces

    def _decode_json_string(self, raw):
        """Streaming-safe JSON-string decoder → (decoded, chars_consumed, closed).
        An escape split across deltas is kept in self._pending_escape and completed
        on a later feed (its chars are consumed as they arrive)."""
        decoded = []
        i = 0
        n = len(raw)
        while i < n:
            if self._pending_escape:
                seq = self._pending_escape + raw[i]
                if len(seq) >= 2 and seq[1] == 'u' and len(seq) < 6:
                    self._pending_escape = seq
                    i += 1
                    continue
                self._pending_escape = ''
                decoded.append(self._unescape_sequence(seq))
                i += 1
                continue
            ch = raw[i]
            if ch == '\\':
                self._pending_escape = ch
                i += 1
                continue
            if ch == '"':
                return ''.join(decoded), i + 1, True
            decoded.append(ch)
            i += 1
        return ''.join(decoded), n, False


def summarize_attachment_types(attachment_records: list[dict]) -> str:
    if not attachment_records:
        return 'No attachments.'
    parts = []
    for item in attachment_records:
        name = str(item.get('name', '') or os.path.basename(str(item.get('stored_path', '') or ''))).strip() or 'attachment'
        kind = str(item.get('kind', '')).strip() or 'file'
        parts.append(f'{kind}: {name}')
    return '\n'.join(parts)


def format_utc_offset(offset: str) -> str:
    text = str(offset or '').strip()
    if len(text) == 5 and (text.startswith('+') or text.startswith('-')):
        return text[:3] + ':' + text[3:]
    return text or 'local'


def build_runtime_context_block() -> str:
    try:
        now = datetime.datetime.now().astimezone()
    except Exception:
        now = datetime.datetime.now()
    try:
        utc_now = now.astimezone(datetime.timezone.utc)
    except Exception:
        utc_now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    tz_name = ''
    try:
        tz_name = now.tzname() or ''
    except Exception:
        tz_name = ''
    offset = ''
    try:
        offset = now.strftime('%z')
    except Exception:
        offset = ''
    try:
        weekday = now.strftime('%A')
    except Exception:
        weekday = ''
    local_datetime = now.isoformat(timespec='seconds') if hasattr(now, 'isoformat') else str(now)
    utc_datetime = utc_now.isoformat(timespec='seconds') if hasattr(utc_now, 'isoformat') else str(utc_now)
    local_date = ''
    try:
        local_date = now.date().isoformat()
    except Exception:
        local_date = ''
    timezone_text = ' '.join(part for part in [tz_name, f'(UTC{format_utc_offset(offset)})' if offset else ''] if part).strip()
    return (
        'Runtime context:\n'
        f'- Current local datetime: {local_datetime}\n'
        + (f'- Current local date: {local_date}' + (f' ({weekday})' if weekday else '') + '\n' if local_date else '')
        + f'- Current UTC datetime: {utc_datetime}\n'
        + (f'- System time zone: {timezone_text}\n' if timezone_text else '')
        + '- User-facing locale: Chinese-language UI; answer in the user\'s language unless they request another language.\n'
        + '- Interpret "now", "today", "yesterday", "tomorrow", "latest", "current", and "as of now" relative to the local datetime above.\n'
        + '- For schedules, news, sports, finance, laws, and other current-status tasks, distinguish source publication date, event date, status update date, and retrieval date.\n'
        + '- If a source says an event has not started but the runtime date is after the event start date, treat that source as potentially stale unless an official live/status source confirms it.\n'
        + '- For conflicting current-status sources, preserve the conflict explicitly instead of flattening it; use absolute dates in the final answer when ambiguity matters.'
    )


def build_planner_messages(user_text: str,
                           attachment_summary: str,
                           skill_catalog: str = '',
                           conversation_context: str = '',
                           model_candidates_block: str = '',
                           editor_note: str = '',
                           archive_note: str = '',
                           skill_names=None) -> list[dict]:
    slash_segments = parse_specialized_slash_segments(user_text, skill_names)
    editor_note = str(editor_note or '').strip()
    editor_rule = (
        '\n- Files open in the user\'s Broccoli Editor are listed in the user message under '
        '"Editor status". NEVER plan terminal_command or browser_use to create, edit, or write any file '
        'listed there — such edits are delivered by the default answer as an editor_edit permission block. '
        'For a request that only edits an editor-open file, plan NO steps unless genuine research is needed.\n'
        if editor_note else ''
    )
    archive_planner_rule = (
        '- When a previous run\'s archived file already contains material needed by a step, set "archive_refs" to the relevant absolute path or paths (maximum 4).\n'
        if str(archive_note or '').strip() else ''
    )
    # 浏览器并行的登录限制随设置变化：共享登录态开启时，已登录站点也可拆并行；
    # 否则并行成员是全新未登录配置档，登录任务必须保持串行。
    try:
        _share_login = bool(normalize_browser_use_settings(
            load_settings_store().get('globals', {})
        ).get('browser_use_parallel_share_login', False))
    except Exception:
        _share_login = False
    browser_parallel_login_clause = (
        'Parallel browser_use members inherit the user\'s login cookies, so logged-in sites may be grouped too.'
        if _share_login else
        'Group browser_use steps ONLY when they do not need the user\'s logged-in session (parallel browser members start from a fresh, logged-out profile); keep logged-in browser tasks sequential.'
    )
    archive_planner_schema = (
        ', "archive_refs": ["optional archived absolute path"]'
        if str(archive_note or '').strip() else ''
    )
    skill_rules = ''
    if str(skill_catalog or '').strip():
        skill_rules = (
            '\nAvailable skills:\n'
            + str(skill_catalog or '').strip()
            + '\n\nSkill step rules:\n'
            '- A skill is an isolated inserted task, not global context.\n'
            '- Use capability "skill" only when a listed skill description clearly matches the request.\n'
            '- Set "skill_name" exactly to one of the listed skill names.\n'
            '- The skill will run with the default main model and its full instructions will be loaded only for that step.\n'
            '- Later steps and the final answer will receive only the reviewed skill result, not the full skill prompt.\n'
        )
    else:
        skill_rules = '\nNo skills are configured.\n'
    return [
        {
            'role': 'system',
            'content': (
                'You are a task planner for a desktop AI assistant.\n\n'
                + build_runtime_context_block()
                + '\n\n'
                'Analyze the user request and decide whether any specialized capabilities are needed.\n'
                'Available capabilities:\n'
                + planner_capability_list_text()
                + skill_rules
                + '\n'
                'Step design rules:\n'
                '- Attached files (see "Attachment summary") are ALREADY provided directly to the '
                'answer: their extracted text and/or page images are injected automatically. NEVER plan '
                'a step (task_reasoning, terminal_command, code, browser_use) to find, locate, open, read, '
                'download, or OCR an attached file, and never run a filesystem search (e.g. `find`) for it. '
                'If the request is only to read, summarize, describe, translate, or answer questions about '
                'attached files, plan NO steps and let the default answer use the provided content.\n'
                '- Do not include embedding. Retrieval is handled separately by the system.\n'
                '- Use browser_use when the request requires a real browser session, logged-in pages, clicking, forms, dynamic pages, or for the specific sub-task bound by a /browser use slash segment.\n'
                '- Use computer_use only when the request must operate a local native desktop app. It operates only task-approved explicit application targets, and every state-changing action must identify its target. Because there is one real desktop, computer_use runs serially. Web-page work remains browser_use.\n'
                '- Use terminal_command when the request requires local shell commands, project/file search, reading local files, creating or editing files, AppleScript/osascript, macOS app automation, or system commands. This is not Code Runner; it executes in the Terminal tab with user approval and visible history. Do NOT use it to locate or read a file that is already attached -- attached files are provided directly, so searching the disk for them is wrong.\n'
                + editor_rule +
                '- Use Code execution runners only for deterministic Python/Node-style code snippets produced inside a specialist step. Do not use Code Runner for shell commands, osascript, or project file operations.\n'
                '- Slash binding scope: a slash command binds ONLY the paragraph it starts (each binding is listed under "Specialized slash bindings" in the user message when present). For EACH listed binding, include at least one step with exactly that capability whose goal is that segment\'s task text; when the binding names a skill (capability "skill"), set that step\'s skill_name to exactly the listed skill_name. Later steps or the final answer may summarize/analyze its result. All other sub-tasks in the request must choose capabilities independently by their own nature -- never apply a slash-bound capability to text outside its own paragraph.\n'
                '- If no specialized capability is needed, return an empty "steps" list.\n'
                '- Use the fewest steps that fully satisfy the request. Do not add steps that do not materially improve the final answer.\n'
                '- When two sequences both satisfy the request, prefer the one with fewer steps and higher relevance to the user\'s core intent.\n'
                '- Order steps so information-gathering steps (web_search, task_reasoning for research) come before synthesis or generation steps.\n'
                '- PARALLEL steps: when the request has several INDEPENDENT facets that do not need each other\'s output — e.g. researching multiple distinct aspects of one topic, running the SAME kind of lookup across several distinct entities (each company/product/city/region separately), or drafting several alternative proposals/designs — give those steps the SAME "parallel_group" value so they run at the same time, and set depends_on_previous:false on them. Follow the group with a synthesis step (depends_on_previous:true) that combines the group. Only group READ-ONLY or GENERATIVE capabilities (web_search, task_reasoning, image/video/audio generation) and browser_use; NEVER put terminal_command or computer_use in a parallel_group. browser_use split rule: when one browser task must search or check SEVERAL independent keywords, entities, or pages on the same site, plan ONE browser_use step per keyword/entity and give them the SAME parallel_group (plus a synthesis step) instead of one overloaded step. ' + browser_parallel_login_clause + ' Leave parallel_group empty for ordinary sequential steps.\n'
                '- Web research step count: for a SINGLE topic that needs broad research, plan ONE web_search step (do not plan multiple broad web_search steps for the same topic; if verification is needed, make it a targeted verification step with a narrow missing/conflicting field, or use task_reasoning to arbitrate conflicting results). BUT when the request enumerates SEVERAL INDEPENDENT entities or items that each need the SAME kind of separate lookup — e.g. pricing for 5 named companies, specs for 4 products, weather for 3 cities — plan ONE web_search per entity and give them all the SAME parallel_group so they run at the same time, then add a synthesis step (depends_on_previous:true) that combines them; N focused parallel searches are faster and more reliable than one overloaded search. Example: "get each of Company A/B/C/D/E\'s pricing" -> five web_search steps sharing parallel_group "pricing" + one task_reasoning synthesis step.\n'
                '- For deterministic counting, calculation, parsing, validation, or exact verification, include a task_reasoning step unless a more specific skill step handles it.\n'
                f'- Code execution runners: {code_runner_catalog_text()}\n'
                '- For each step, set reasoning_effort: "light" for extraction, formatting, simple lookups, or straightforward summarization; "standard" for regular research, comparison, and synthesis; "deep" for math, code, multi-constraint reasoning, or verification-critical analysis. If the executing model does not support reasoning control the value is safely ignored.\n'
                '- Model choice: when the user message lists "Model candidates" for a capability, you may set model_profile on steps of that capability to any listed candidate name (copy it exactly). Candidates are ordered by user preference (1 = most preferred); pick a lower-ranked one only when its quality summary or traits clearly fit the step better. Omit model_profile to use the top choice.\n'
                '- For each step, set context_policy to "fresh" when that step should retrieve memory/history/MCP/attachments using its own narrower query, "none" when no extra retrieval is useful, or "auto" when unsure.\n'
                '- Use context_query only when you can write a better retrieval query than the step goal. Make it concise and specific to that step, not a copy of the full user request.\n'
                + archive_planner_rule +
                '- Return JSON only.\n\n'
                'Goal field rules (critical):\n'
                '- Write "goal" as a single precise instruction to the specialist: what to do, what input to use, what output is expected.\n'
                '- Do NOT write vague goals like "help with the request". Be specific: "Search for X and return key facts about Y".\n'
                '- The goal must be self-contained enough that the specialist can act on it without reading the full conversation.\n\n'
                '- Every step must have a non-empty goal. If you cannot write a concrete goal for a step, do not include that step.\n\n'
                'Extract field rules (critical for context efficiency):\n'
                '- When depends_on_previous is true, set "extract" to a short phrase naming exactly what the next step needs from the previous output.\n'
                '- Example: "search result URLs", "translated text", "reasoning summary", "image prompt".\n'
                '- If depends_on_previous is false, omit "extract" or set it to "".\n\n'
                'Finalize field rules:\n'
                '- Set finalize_with_default_chat to true when the step results need to be synthesized into a final user-facing response.\n'
                '- Set "finalize_focus" to a short phrase telling the final chat what to synthesize: e.g. "summarize findings into an answer", "combine image prompt and reasoning into a description".\n\n'
                'Output format:\n'
                '{\n'
                '  "steps": [\n'
                '    {"capability": "...", "skill_name": "only for skill steps", "goal": "...", "depends_on_previous": true, "extract": "...", "context_policy": "auto|fresh|none", "context_query": "optional focused retrieval query"'
                + archive_planner_schema
                + ', "reasoning_effort": "light|standard|deep", "model_profile": "optional candidate name", "parallel_group": "optional group name — steps sharing the same value run AT THE SAME TIME"}\n'
                '  ],\n'
                '  "finalize_with_default_chat": true,\n'
                '  "finalize_focus": "...",\n'
                '  "reason": "..."\n'
                '}'
            ),
        },
        {
            'role': 'user',
            'content': (
                (
                    'Recent conversation context and user annotations for resolving follow-up references and planning constraints:\n'
                    + str(conversation_context or '').strip()
                    + '\n\n'
                    if str(conversation_context or '').strip() else ''
                ) +
                'Latest user request:\n' + str(user_text or '').strip() +
                (
                    '\n\nSpecialized slash bindings (each binds ONLY its own paragraph; plan the rest of the request independently):\n'
                    + '\n'.join(
                        (
                            f'{index}. capability "skill" (skill_name "{segment.get("skill_name", "")}"): {segment["task"]}'
                            if segment.get('capability') == SPECIALIZED_SKILL_CAPABILITY
                            else f'{index}. capability "{segment["capability"]}": {segment["task"]}'
                        )
                        for index, segment in enumerate(
                            (s for s in slash_segments if str(s.get('task', '') or '').strip()),
                            start=1,
                        )
                    )
                    if any(str(s.get('task', '') or '').strip() for s in slash_segments) else ''
                ) +
                (
                    '\n\nModel candidates (ordered by user preference; quality from past step reviews):\n'
                    + str(model_candidates_block).strip()
                    if str(model_candidates_block or '').strip() else ''
                ) +
                (('\n\n' + editor_note) if editor_note else '') +
                (('\n\nPrevious agent runs of this conversation (archived step materials):\n' + str(archive_note).strip()) if str(archive_note or '').strip() else '') +
                '\n\nAttachment summary:\n' + str(attachment_summary or 'No attachments.')
            ),
        },
    ]


def normalize_specialized_step_context_policy(value) -> str:
    policy = str(value or '').strip().lower()
    if policy in {'none', 'auto', 'fresh'}:
        return policy
    return 'auto'


def normalize_agent_step_archive_refs(value) -> list[str]:
    if not isinstance(value, list):
        return []
    refs = []
    for item in value:
        path = str(item or '').strip()
        if path and path not in refs:
            refs.append(path)
        if len(refs) >= 4:
            break
    return refs


def normalize_parallel_group_value(value, capability='') -> str:
    """A short slug id; steps sharing it run concurrently. Single-surface
    capabilities (registry single_surface=True: terminal_command 单终端会话+模态
    审批、computer_use 单真实桌面) can NEVER be grouped, so they are forced to ''
    regardless of what the planner said."""
    if capability_is_single_surface(capability):
        return ''
    raw = re.sub(r'\s+', ' ', str(value or '').strip().lower())
    slug = re.sub(r'[^0-9A-Za-z_-]+', '-', raw).strip('-')
    if re.search(r'[^0-9a-z_\- ]', raw):
        # Non-ASCII names (e.g. a Chinese "驾校口碑") used to collapse to '' (group silently
        # dropped -> sequential) or collide ("口碑A"/"评价A" -> "a"). Suffix a stable hash of
        # the original name: same name -> same slug, different names never merge.
        digest = hashlib.sha1(raw.encode('utf-8')).hexdigest()[:8]
        slug = f'{slug[:31]}-{digest}' if slug else f'g-{digest}'
    return slug[:40]


def specialized_step_batch(steps, start_index):
    """Return the list of step indices that run TOGETHER starting at start_index.
    A batch is a maximal contiguous run of steps that (a) share the same non-empty
    parallel_group, (b) do not depend on each other (depends_on_previous is treated
    as False within a group), and (c) are not single-surface capabilities
    (registry single_surface=True: terminal_command / computer_use).
    A step with no parallel_group (or a solo group) returns just [start_index] —
    the ordinary sequential path. Deleted/consumed markers are the caller's concern."""
    if not isinstance(steps, list) or start_index < 0 or start_index >= len(steps):
        return [start_index]
    first = steps[start_index] if isinstance(steps[start_index], dict) else {}
    group = str(first.get('parallel_group', '') or '').strip()
    if not group or capability_is_single_surface(first.get('capability', '')):
        return [start_index]
    batch = [start_index]
    j = start_index + 1
    while j < len(steps):
        s = steps[j] if isinstance(steps[j], dict) else {}
        if str(s.get('parallel_group', '') or '').strip() != group:
            break
        if capability_is_single_surface(s.get('capability', '')):
            break
        batch.append(j)
        j += 1
    return batch


class ParallelFactBoard:
    """Thread-safe, run-local fact exchange for one parallel step group."""

    _HEADER = (
        'Shared fact board (live notes from sibling steps running in parallel and from the user).\n'
        'Treat entries as LEADS, not as independent confirmation. If you rely on one, cite it as\n'
        'board-sourced. Do not repeat a board entry back as a new finding. Facts you report later\n'
        'must carry your own source references.'
    )
    _DIGEST_HEADER = (
        'Shared fact board digest from parallel specialist steps and user notes.\n'
        'For synthesis and the final answer, weight corroborated facts above user notes above proposed facts.\n'
        'ARBITRATE disputed entries explicitly; both supporting and disagreeing verdicts are included.'
    )

    def __init__(self):
        self._lock = threading.RLock()
        self._entries = []
        self._entry_by_id = {}
        self._entry_by_key = {}
        self._last_seen = {}
        self._seq = 0

    @staticmethod
    def _clean_text(value, limit=SPECIALIZED_BOARD_ENTRY_CHARS):
        text = re.sub(r'\s+', ' ', str(value or '')).strip()
        return text[:max(0, int(limit))]

    @staticmethod
    def _entry_sort_key(entry):
        kind = str(entry.get('kind', '') or '')
        status = str(entry.get('status', '') or '')
        if kind == 'user_note':
            rank = 1
        else:
            rank = {'corroborated': 0, 'proposed': 2, 'disputed': 3}.get(status, 2)
        return rank, int(entry.get('seq', 0) or 0)

    @staticmethod
    def _entry_line(entry, is_new=False, digest=False):
        entry_id = str(entry.get('entry_id', '') or '')
        status = str(entry.get('status', 'proposed') or 'proposed')
        source = str(entry.get('source', '') or '')
        marker = '[NEW]' if is_new else ''
        line = '[%s][%s][from %s]%s %s' % (
            entry_id, status, source, marker, str(entry.get('text', '') or ''),
        )
        refs = [str(ref).strip() for ref in (entry.get('refs') or []) if str(ref).strip()]
        if refs:
            line += ' — refs: ' + '; '.join(refs)
        verdicts = list(entry.get('verdicts') or [])
        disagrees = [v for v in verdicts if not bool(v.get('agree'))]
        if status == 'disputed' and disagrees:
            line += ' (DISPUTED: %s)' % str(disagrees[-1].get('reason', '') or '').strip()
        if digest and verdicts:
            rendered = []
            for verdict in verdicts:
                rendered.append('%s %s: %s' % (
                    str(verdict.get('by', '') or ''),
                    'agrees' if bool(verdict.get('agree')) else 'disagrees',
                    str(verdict.get('reason', '') or '').strip(),
                ))
            line += ' — verdicts: ' + '; '.join(rendered)
        return line

    @staticmethod
    def _bounded_render(header, lines, max_chars):
        """Returns (rendered_text, lines_included) — the count lets render_for_member
        advance a member's NEW marker only past entries that actually made the cut."""
        try:
            budget = max(0, int(max_chars))
        except (TypeError, ValueError):
            budget = 0
        if budget <= 0:
            return '', 0
        if len(header) >= budget:
            return header[:budget], 0
        output = header
        included = 0
        for line in lines:
            addition = '\n' + str(line or '')
            if len(output) + len(addition) > budget:
                break
            output += addition
            included += 1
        return output, included

    def post_fact(self, member_id, text, refs, round_index):
        with self._lock:
            cleaned = self._clean_text(text)
            if not cleaned:
                return None, 'empty text'
            clean_refs = [str(ref).strip() for ref in (refs or []) if str(ref).strip()]
            if not clean_refs:
                return None, 'refs required'
            key = re.sub(r'\s+', ' ', cleaned).strip().lower()
            existing = self._entry_by_key.get(key)
            if existing:
                return existing, 'duplicate'
            if len(self._entries) >= SPECIALIZED_BOARD_MAX_ENTRIES:
                return None, 'board full'
            self._seq += 1
            entry_id = 'b%d' % self._seq
            try:
                round_value = int(round_index)
            except (TypeError, ValueError):
                round_value = 0
            entry = {
                'entry_id': entry_id,
                'kind': 'fact',
                'text': cleaned,
                'source': str(member_id or '').strip(),
                'refs': clean_refs,
                'status': 'proposed',
                'verdicts': [],
                'round': round_value,
                'seq': self._seq,
            }
            self._entries.append(entry)
            self._entry_by_id[entry_id] = entry
            self._entry_by_key[key] = entry_id
            return entry_id, ''

    def post_verdict(self, member_id, entry_id, agree, reason):
        with self._lock:
            entry = self._entry_by_id.get(str(entry_id or '').strip())
            member = str(member_id or '').strip()
            if not entry or entry.get('kind') != 'fact' or member == str(entry.get('source', '') or ''):
                return False
            verdict = {
                'by': member,
                'agree': bool(agree),
                'reason': self._clean_text(reason),
            }
            entry['verdicts'].append(verdict)
            if entry.get('status') == 'disputed' or any(
                    not bool(v.get('agree')) for v in entry.get('verdicts') or []):
                entry['status'] = 'disputed'
            elif any(
                    bool(v.get('agree')) and str(v.get('by', '') or '') != str(entry.get('source', '') or '')
                    for v in entry.get('verdicts') or []):
                entry['status'] = 'corroborated'
            return True

    def add_user_note(self, text):
        with self._lock:
            cleaned = self._clean_text(text)
            if not cleaned:
                return None
            key = re.sub(r'\s+', ' ', cleaned).strip().lower()
            existing = self._entry_by_key.get(key)
            if existing:
                return existing
            if len(self._entries) >= SPECIALIZED_BOARD_MAX_ENTRIES:
                return None
            self._seq += 1
            entry_id = 'b%d' % self._seq
            entry = {
                'entry_id': entry_id,
                'kind': 'user_note',
                'text': cleaned,
                'source': 'user',
                'refs': [],
                'status': 'corroborated',
                'verdicts': [],
                'round': 0,
                'seq': self._seq,
            }
            self._entries.append(entry)
            self._entry_by_id[entry_id] = entry
            self._entry_by_key[key] = entry_id
            return entry_id

    def render_for_member(self, member_id, max_chars=SPECIALIZED_BOARD_RENDER_CHARS):
        with self._lock:
            if not self._entries:
                return ''
            member = str(member_id or '').strip()
            last_seen = int(self._last_seen.get(member, 0) or 0)
            ordered = sorted(self._entries, key=self._entry_sort_key)
            lines = [self._entry_line(entry, int(entry.get('seq', 0) or 0) > last_seen)
                     for entry in ordered]
            output, included = self._bounded_render(self._HEADER, lines, max_chars)
            # Advance the NEW marker only past entries the member ACTUALLY saw. If the
            # budget truncated the render, every dropped entry must keep seq > last_seen
            # so it still shows [NEW] on a later read — so the marker may only advance
            # to just below the lowest dropped seq. (An already-rendered entry with a
            # higher seq may show [NEW] twice; repeating NEW is safe, hiding it is not.)
            dropped = ordered[included:]
            if dropped:
                candidate = min(int(e.get('seq', 0) or 0) for e in dropped) - 1
            else:
                candidate = max(int(e.get('seq', 0) or 0) for e in self._entries)
            self._last_seen[member] = max(last_seen, candidate)
            return output

    def render_digest(self, max_chars=SPECIALIZED_BOARD_DIGEST_CHARS):
        with self._lock:
            if not self._entries:
                return ''
            ordered = sorted(self._entries, key=self._entry_sort_key)
            lines = [self._entry_line(entry, digest=True) for entry in ordered]
            output, _included = self._bounded_render(self._DIGEST_HEADER, lines, max_chars)
            return output

    def snapshot(self):
        with self._lock:
            facts = [entry for entry in self._entries if entry.get('kind') == 'fact']
            return {
                'facts': len(facts),
                'disputed': sum(1 for entry in facts if entry.get('status') == 'disputed'),
                'proposed': sum(1 for entry in facts if entry.get('status') == 'proposed'),
                'corroborated': sum(1 for entry in facts if entry.get('status') == 'corroborated'),
                'user_notes': sum(1 for entry in self._entries if entry.get('kind') == 'user_note'),
                # Deep-copy the mutable sub-lists: snapshots cross the worker→GUI thread
                # boundary, and a shallow dict(entry) would keep sharing the LIVE
                # refs/verdicts lists that post_verdict later appends to.
                'entries': [
                    {**entry,
                     'refs': list(entry.get('refs') or []),
                     'verdicts': [dict(v) for v in (entry.get('verdicts') or [])]}
                    for entry in self._entries
                ],
            }

    def stats_line(self):
        with self._lock:
            snapshot = self.snapshot()
            return _tr('%d facts · %d disputed · %d proposed') % (
                snapshot['facts'], snapshot['disputed'], snapshot['proposed'],
            )


# Auto-parallel (opt-in, default OFF) only groups these read-only / generative
# capabilities. Deliberately EXCLUDES terminal_command (single surface), computer_use
# (single real desktop), and browser_use (may need the user's logged-in session — isolation forces a fresh logged-out
# profile), and user skills (unpredictable). The planner can still group browser_use
# explicitly, where it judges the login question; heuristic inference must not.
AUTO_PARALLEL_CAPABILITIES = {
    key for key, spec in SPECIALIZED_CAPABILITY_REGISTRY.items() if spec.get('auto_parallel')
}


def infer_auto_parallel_groups(plan):
    """Opt-in (default OFF). Group each maximal run of >=2 CONSECUTIVE independent
    steps — parallel_group already empty (never override the planner), depends_on_previous
    False (declared independent of its predecessor), capability in AUTO_PARALLEL_CAPABILITIES
    — under one synthetic slug so specialized_step_batch/run_parallel_group pick them up.
    A dependent step (e.g. a synthesis with depends_on_previous:true) breaks the run and
    stays sequential. Mutates and returns the same plan dict."""
    if not isinstance(plan, dict):
        return plan
    steps = plan.get('steps')
    if not isinstance(steps, list) or len(steps) < 2:
        return plan

    def eligible(s):
        return (
            isinstance(s, dict)
            and not str(s.get('parallel_group', '') or '').strip()
            and not bool(s.get('depends_on_previous', False))
            and str(s.get('capability', '') or '').strip() in AUTO_PARALLEL_CAPABILITIES
        )

    # Slugs already present (planner / slash bindings). Auto slugs MUST avoid these,
    # else specialized_step_batch — which merges any contiguous same-slug run — could
    # sweep a planner-grouped neighbour into an auto group (indirectly overriding the
    # planner). normalize_parallel_group_value can produce 'auto-N' from a planner value,
    # so the collision is real even if unlikely.
    existing = {str(s.get('parallel_group', '') or '').strip()
                for s in steps if isinstance(s, dict)}
    existing.discard('')
    i = 0
    group_seq = 0
    n = len(steps)
    while i < n:
        if not eligible(steps[i]):
            i += 1
            continue
        j = i + 1
        while j < n and eligible(steps[j]):
            j += 1
        if j - i >= 2:
            slug = ''
            while not slug or slug in existing:
                group_seq += 1
                slug = normalize_parallel_group_value('auto-%d' % group_seq, '')
            existing.add(slug)
            for k in range(i, j):
                steps[k]['parallel_group'] = slug
        i = j
    return plan


