class AsyncRenderThread(threading.Thread):
    def __init__(self, config: dict, signals: AsyncRenderSignals):
        super().__init__(daemon=True)
        self.config = config
        self.signals = signals

    def run(self):
        perf_started = time.perf_counter()
        try:
            history_messages = list(self.config.get('history_messages') or [])
            markdown_text = str(self.config.get('markdown_text', '') or '')
            dark = bool(self.config.get('dark', False))
            pre_rendered_body_html = None
            message_cards = []
            if history_messages:
                display_text = render_chat_history_markdown(history_messages)
                message_cards = render_chat_message_cards(history_messages, dark=dark)
                pre_rendered_body_html = ''.join(message_cards)
            else:
                display_text = markdown_text
            messages_rendered_at = time.perf_counter()
            html_text = render_markdown_document_to_html(
                display_text,
                dark,
                str(self.config.get('display_prefix_html', '') or ''),
                pre_rendered_body_html=pre_rendered_body_html,
            )
            finished_at = time.perf_counter()
            _agent_render_perf_log(
                'async_render',
                document_ms=round((finished_at - messages_rendered_at) * 1000, 2),
                html_bytes=len(html_text.encode('utf-8', errors='ignore')),
                message_html_ms=round((messages_rendered_at - perf_started) * 1000, 2),
                messages=len(history_messages),
                request_id=int(self.config.get('request_id', 0) or 0),
                total_ms=round((finished_at - perf_started) * 1000, 2),
            )
            self.signals.finished.emit(
                {
                    'request_id': int(self.config.get('request_id', 0) or 0),
                    'html': html_text,
                    'message_cards': message_cards,
                    'message_hashes': chat_message_render_hashes(history_messages),
                    'has_explicit_math': bool(re.search(r'(?<!\\)\$\$|\\\(|\\\[|\\begin\{', display_text, re.DOTALL)),
                    'dark': dark,
                }
            )
        except Exception as exc:
            self.signals.failed.emit(
                {
                    'request_id': int(self.config.get('request_id', 0) or 0),
                    'error': str(exc),
                    'markdown_text': str(self.config.get('markdown_text', '') or ''),
                    'display_prefix_html': str(self.config.get('display_prefix_html', '') or ''),
                    'history_messages': history_messages,
                }
            )


