class AsyncTaskCapsuleSignals(QObject):
    finished = pyqtSignal(object)
    failed = pyqtSignal(str)


class AsyncTaskCapsuleThread(threading.Thread):
    def __init__(self, config: dict, signals: AsyncTaskCapsuleSignals):
        super().__init__(daemon=True)
        self.config = dict(config or {})
        self.signals = signals

    @staticmethod
    def _strip_yaml_fence(text: str) -> str:
        text = str(text or '').strip()
        match = re.match(r'^```(?:yaml|yml)?\s*(.*?)\s*```$', text, flags=re.IGNORECASE | re.DOTALL)
        return match.group(1).strip() if match else text

    def run(self):
        try:
            api_key = str(self.config.get('api_key', '') or '').strip()
            endpoint = str(self.config.get('endpoint', '') or '').strip()
            model = str(self.config.get('model', '') or '').strip()
            timeout = int(self.config.get('timeout', 60) or 60)
            markdown_text = str(self.config.get('markdown_text', '') or '').strip()
            capsule_id = str(self.config.get('capsule_id', '') or '').strip()
            source_meta = self.config.get('source_meta') if isinstance(self.config.get('source_meta'), dict) else {}
            source_lines = []
            if source_meta:
                for key in ('source', 'title', 'url'):
                    value = str(source_meta.get(key, '') or '').strip()
                    if value:
                        source_lines.append(f'{key}: {value}')
            source_block = ('Source metadata:\n' + '\n'.join(source_lines) + '\n\n') if source_lines else ''
            if not api_key or not endpoint or not model:
                raise RuntimeError(_tr('No active API profile is configured.'))
            if not markdown_text:
                raise RuntimeError(_tr('There is no conversation content to summarize.'))

            system_prompt = (
                'You convert a chat conversation into a reusable Task Capsule. '
                'Remove noise, rejected plans, emotional tone, and intermediate attempts. '
                'Preserve final decisions, constraints, accepted requirements, unresolved questions, '
                'handoff notes, and verification criteria. Return only YAML matching the requested schema.'
            )
            user_prompt = f"""
Create a Task Capsule from the conversation below.

Compression rules:
1. Delete rejected intermediate plans and keep only the final accepted direction.
2. Fold repeated user clarifications into constraints.
3. Put examples, source material, files, URLs, and prior outputs under inputs.
4. Drop user emotion unless it represents a concrete preference.
5. Do not copy full assistant answers into handoff; summarize what was done and what remains.
6. Separate actions from acceptance criteria.
7. Make every field self-contained enough that another AI can execute without reading the original conversation.

Return this exact YAML shape:
task_capsule:
  id: {capsule_id}
  goal: <one-sentence final deliverable or final state>
  intent: <why this task exists now and decision background>
  inputs:
    - type: text | file | url | prior_output
      ref: <content summary or pointer>
  constraints:
    hard: [<must not violate>]
    soft: [<preference>]
  actions:
    - step: <imperative action>
      expected_output: <output for this step>
  acceptance:
    must: [<hard verification criteria>]
    should: [<soft verification criteria>]
  handoff:
    from_model: {model}
    confidence: <0.0-1.0 estimate>
    open_questions: [<unresolved questions>]
    next_role: executor | reviewer | rewriter

{source_block}
Conversation markdown:
{markdown_text}
""".strip()
            client = create_openai_client(api_key, endpoint, timeout)
            response = create_chat_completion(
                client,
                endpoint=endpoint,
                model=model,
                messages=[
                    {'role': 'system', 'content': system_prompt},
                    {'role': 'user', 'content': user_prompt},
                ],
                stream=False,
            )
            content = ''
            try:
                content = response.choices[0].message.content or ''
            except Exception:
                content = str(response or '')
            content = self._strip_yaml_fence(content)
            if not content.strip():
                raise RuntimeError(_tr('Task Capsule generation returned empty output.'))
            self.signals.finished.emit(
                {
                    'title': _tr('Task Capsule'),
                    'text': content.strip(),
                    'capsule_id': capsule_id,
                    'dialog_title': str(self.config.get('dialog_title', '') or _tr('Task Capsule')),
                    'dialog_subtitle': str(self.config.get('dialog_subtitle', '') or ''),
                    'force_dark': bool(self.config.get('force_dark', False)),
                }
            )
        except Exception as exc:
            self.signals.failed.emit(str(exc))


class NativeHotkeyTapThread(threading.Thread):
    def __init__(self, manager):
        super().__init__(daemon=True)
        self.manager = manager
        self._runloop = None
        self._tap_port = None
        self._callback = None

    def run(self):
        if not HOTKEY_BACKEND_AVAILABLE:
            return

        event_mask = CGEventMaskBit(kCGEventKeyDown)

        def callback(proxy, event_type, event, refcon):
            if event_type == kCGEventKeyDown:
                flags = int(CGEventGetFlags(event)) & HOTKEY_ALLOWED_FLAGS
                keycode = int(CGEventGetIntegerValueField(event, kCGKeyboardEventKeycode))
                self.manager.handle_keydown(flags, keycode)
            return event

        self._callback = callback
        self._tap_port = CGEventTapCreate(
            kCGHIDEventTap,
            kCGHeadInsertEventTap,
            kCGEventTapOptionDefault,
            event_mask,
            self._callback,
            None,
        )
        if self._tap_port is None:
            logging.error("Failed to create native hotkey event tap.")
            self.manager.mark_backend_failed()
            return

        source = CFMachPortCreateRunLoopSource(None, self._tap_port, 0)
        self._runloop = CFRunLoopGetCurrent()
        CFRunLoopAddSource(self._runloop, source, kCFRunLoopDefaultMode)
        CGEventTapEnable(self._tap_port, True)
        self.manager.mark_backend_ready()
        CFRunLoopRun()

    def stop(self):
        if self._runloop is not None:
            CFRunLoopStop(self._runloop)


BROWSER_BRIDGE_PORT = 49152


class BrowserBridgeSignals(QObject):
    received = pyqtSignal(dict)


class BrowserBridgeServer(threading.Thread):
    def __init__(self, signals: BrowserBridgeSignals):
        super().__init__(daemon=True)
        self.signals = signals
        self._server = None

    def run(self):
        import socketserver
        from http.server import BaseHTTPRequestHandler

        signals = self.signals

        class Handler(BaseHTTPRequestHandler):
            def log_message(self, *args):
                pass

            def _cors(self):
                self.send_header('Access-Control-Allow-Origin', '*')
                self.send_header('Access-Control-Allow-Methods', 'POST, GET, OPTIONS')
                self.send_header('Access-Control-Allow-Headers', 'Content-Type')

            def do_OPTIONS(self):
                self.send_response(204)
                self._cors()
                self.end_headers()

            def do_GET(self):
                if self.path == '/ping':
                    body = b'pong'
                    self.send_response(200)
                    self._cors()
                    self.send_header('Content-Type', 'text/plain')
                    self.send_header('Content-Length', str(len(body)))
                    self.end_headers()
                    self.wfile.write(body)
                else:
                    self.send_response(404)
                    self.end_headers()

            def do_POST(self):
                if self.path not in {'/ask', '/translate-popup', '/selection-menu'}:
                    self.send_response(404)
                    self.end_headers()
                    return
                length = int(self.headers.get('Content-Length', 0))
                raw = self.rfile.read(length)
                try:
                    payload = json.loads(raw.decode('utf-8'))
                except Exception:
                    payload = {}
                body = b'ok'
                self.send_response(200)
                self._cors()
                self.send_header('Content-Type', 'text/plain')
                self.send_header('Content-Length', str(len(body)))
                self.end_headers()
                self.wfile.write(body)
                if self.path == '/translate-popup':
                    payload['action'] = 'translate_popup'
                elif self.path == '/selection-menu':
                    payload['action'] = 'selection_menu'
                signals.received.emit(payload)

        class ReusableTCPServer(socketserver.TCPServer):
            allow_reuse_address = True

        try:
            self._server = ReusableTCPServer(('127.0.0.1', BROWSER_BRIDGE_PORT), Handler)
            self._server.serve_forever()
        except Exception as exc:
            logging.warning('BrowserBridgeServer failed to start: %s', exc)

    def stop(self):
        if self._server is not None:
            self._server.shutdown()


def load_or_create_agent_automation_token() -> str:
    ensure_broccoli_data_dir()
    token = ''
    try:
        if os.path.exists(AGENT_AUTOMATION_INFO_PATH):
            with open(AGENT_AUTOMATION_INFO_PATH, 'r', encoding='utf-8') as handle:
                data = json.load(handle)
            token = str(data.get('token', '') or '').strip()
    except Exception:
        token = ''
    if not token:
        token = base64.urlsafe_b64encode(os.urandom(24)).decode('ascii').rstrip('=')
    try:
        with open(AGENT_AUTOMATION_INFO_PATH, 'w', encoding='utf-8') as handle:
            json.dump(
                {
                    'host': '127.0.0.1',
                    'port': AGENT_AUTOMATION_PORT,
                    'endpoint': f'http://127.0.0.1:{AGENT_AUTOMATION_PORT}/agent/tasks',
                    'token': token,
                    'updated_at': datetime.datetime.now().isoformat(timespec='seconds'),
                    'schema': {
                        'title': 'optional task title',
                        'prompt': 'required user instruction',
                        'source': 'optional external automation source',
                        'metadata': 'optional object',
                    },
                },
                handle,
                ensure_ascii=False,
                indent=2,
            )
    except Exception:
        logging.warning('Failed to write Agent automation server info.', exc_info=True)
    return token


class AgentAutomationSignals(QObject):
    received = pyqtSignal(dict)


class AgentAutomationServer(threading.Thread):
    def __init__(self, signals: AgentAutomationSignals, token: str):
        super().__init__(daemon=True)
        self.signals = signals
        self.token = str(token or '').strip()
        self._server = None

    def run(self):
        import socketserver
        from http.server import BaseHTTPRequestHandler

        signals = self.signals
        token = self.token

        class Handler(BaseHTTPRequestHandler):
            def log_message(self, *args):
                pass

            def _cors(self):
                self.send_header('Access-Control-Allow-Origin', '*')
                self.send_header('Access-Control-Allow-Methods', 'POST, GET, OPTIONS')
                self.send_header('Access-Control-Allow-Headers', 'Content-Type, Authorization, X-Broccoli-Agent-Token')

            def _send_json(self, status: int, payload: dict):
                body = json.dumps(payload, ensure_ascii=False).encode('utf-8')
                self.send_response(status)
                self._cors()
                self.send_header('Content-Type', 'application/json; charset=utf-8')
                self.send_header('Content-Length', str(len(body)))
                self.end_headers()
                self.wfile.write(body)

            def do_OPTIONS(self):
                self.send_response(204)
                self._cors()
                self.end_headers()

            def do_GET(self):
                if self.path == '/ping':
                    self._send_json(200, {'ok': True, 'service': 'broccoli-agent-automation'})
                else:
                    self._send_json(404, {'ok': False, 'error': 'not_found'})

            def do_POST(self):
                if self.path != '/agent/tasks':
                    self._send_json(404, {'ok': False, 'error': 'not_found'})
                    return
                supplied = str(self.headers.get('X-Broccoli-Agent-Token', '') or '').strip()
                auth = str(self.headers.get('Authorization', '') or '').strip()
                if auth.lower().startswith('bearer '):
                    supplied = auth[7:].strip()
                if token and supplied != token:
                    self._send_json(401, {'ok': False, 'error': 'unauthorized'})
                    return
                try:
                    length = int(self.headers.get('Content-Length', 0) or 0)
                except Exception:
                    length = 0
                raw = self.rfile.read(max(0, min(length, 2_000_000)))
                try:
                    payload = json.loads(raw.decode('utf-8'))
                    if not isinstance(payload, dict):
                        payload = {}
                except Exception:
                    payload = {}
                prompt = str(payload.get('prompt', '') or payload.get('instruction', '') or '').strip()
                if not prompt:
                    self._send_json(400, {'ok': False, 'error': 'missing_prompt'})
                    return
                payload['received_at'] = datetime.datetime.now().isoformat(timespec='seconds')
                signals.received.emit(payload)
                self._send_json(202, {'ok': True, 'status': 'accepted'})

        class ReusableTCPServer(socketserver.TCPServer):
            allow_reuse_address = True

        try:
            self._server = ReusableTCPServer(('127.0.0.1', AGENT_AUTOMATION_PORT), Handler)
            self._server.serve_forever()
        except Exception as exc:
            logging.warning('AgentAutomationServer failed to start: %s', exc)

    def stop(self):
        if self._server is not None:
            self._server.shutdown()


class GlobalHotkeyManager(QObject):
    ui_hotkey_pressed = pyqtSignal()
    same_position_screenshot_pressed = pyqtSignal()
    region_screenshot_pressed = pyqtSignal()   # FIX-45: wake the capture overlay
    edge_toggle_pressed = pyqtSignal()
    shortcut_recorded = pyqtSignal(str, str)
    shortcut_record_failed = pyqtSignal(str, str)
    backend_ready = pyqtSignal()
    backend_failed = pyqtSignal()

    def __init__(self):
        super().__init__()
        self._lock = threading.Lock()
        self._thread = None
        self._record_target = None
        self._backend_ready_flag = False
        self._cooldown_seconds = 0.35
        self._last_trigger = 0.0
        self._ui_spec = self._read_shortcut_spec(UI_SHORTCUT_PATH, DEFAULT_UI_SHORTCUT)
        self._same_position_screenshot_spec = self._read_settings_shortcut_spec('same_position_screenshot_shortcut')
        self._region_screenshot_spec = self._read_settings_shortcut_spec('region_screenshot_shortcut')
        self._edge_toggle_spec = self._read_settings_shortcut_spec('edge_toggle_shortcut')

    @property
    def available(self) -> bool:
        return HOTKEY_BACKEND_AVAILABLE

    @property
    def record_target(self):
        with self._lock:
            return self._record_target

    def _read_shortcut_spec(self, path: str, default_shortcut: str) -> dict:
        try:
            return build_shortcut_spec(read_text_file(path, ''), default_shortcut)
        except ValueError:
            logging.warning("Invalid shortcut in %s. Falling back to %s.", path, default_shortcut)
            normalized = normalize_shortcut_text('', default_shortcut)
            write_text_file(path, normalized)
            return build_shortcut_spec(normalized, default_shortcut)

    def _read_settings_shortcut_spec(self, key: str) -> dict | None:
        text = str(load_settings_store().get('globals', {}).get(key, '') or '').strip()
        if not text:
            return None
        try:
            return build_shortcut_spec(text, text)
        except ValueError:
            logging.warning("Invalid optional shortcut setting %s. Shortcut disabled.", key)
            return None

    def start(self):
        if not self.available or self._thread is not None:
            return
        self._thread = NativeHotkeyTapThread(self)
        self._thread.start()

    def stop(self):
        if self._thread is not None:
            self._thread.stop()
            self._thread = None
        self._backend_ready_flag = False

    def reload_shortcuts(self):
        with self._lock:
            self._ui_spec = self._read_shortcut_spec(UI_SHORTCUT_PATH, DEFAULT_UI_SHORTCUT)
            self._same_position_screenshot_spec = self._read_settings_shortcut_spec('same_position_screenshot_shortcut')
            self._region_screenshot_spec = self._read_settings_shortcut_spec('region_screenshot_shortcut')
            self._edge_toggle_spec = self._read_settings_shortcut_spec('edge_toggle_shortcut')

    def begin_recording(self, target: str) -> bool:
        if not self.available or not self._backend_ready_flag or target not in {
                'ui', 'same_position_screenshot', 'region_screenshot', 'edge_toggle'}:
            return False
        with self._lock:
            self._record_target = target
        return True

    def cancel_recording(self):
        with self._lock:
            self._record_target = None

    def mark_backend_ready(self):
        self._backend_ready_flag = True
        self.backend_ready.emit()

    def mark_backend_failed(self):
        self._backend_ready_flag = False
        self.backend_failed.emit()

    def handle_keydown(self, flags: int, keycode: int):
        key_token = KEYCODE_TO_TOKEN.get(keycode)
        if key_token is None:
            return

        now = time.monotonic()
        with self._lock:
            record_target = self._record_target
            ui_spec = dict(self._ui_spec)
            same_position_screenshot_spec = (
                dict(self._same_position_screenshot_spec)
                if self._same_position_screenshot_spec is not None
                else None
            )
            region_screenshot_spec = (
                dict(self._region_screenshot_spec)
                if self._region_screenshot_spec is not None
                else None
            )
            edge_toggle_spec = (
                dict(self._edge_toggle_spec)
                if self._edge_toggle_spec is not None
                else None
            )

        if record_target is not None:
            if flags == 0:
                self.shortcut_record_failed.emit(record_target, _tr('Shortcut must include at least one modifier key.'))
                return

            normalized = serialize_shortcut(flags, key_token)
            updated_spec = build_shortcut_spec(normalized, normalized)

            with self._lock:
                if record_target == 'ui':
                    write_text_file(UI_SHORTCUT_PATH, normalized)
                    self._ui_spec = build_shortcut_spec(normalized, DEFAULT_UI_SHORTCUT)
                elif record_target == 'same_position_screenshot':
                    self._same_position_screenshot_spec = updated_spec
                elif record_target == 'region_screenshot':
                    self._region_screenshot_spec = updated_spec
                elif record_target == 'edge_toggle':
                    self._edge_toggle_spec = updated_spec
                self._record_target = None

            self.shortcut_recorded.emit(record_target, normalized)
            return

        matched_action = None
        if keycode == ui_spec['keycode'] and flags == ui_spec['flags']:
            matched_action = 'ui'
        elif (
            same_position_screenshot_spec is not None
            and keycode == same_position_screenshot_spec['keycode']
            and flags == same_position_screenshot_spec['flags']
        ):
            matched_action = 'same_position_screenshot'
        elif (
            region_screenshot_spec is not None
            and keycode == region_screenshot_spec['keycode']
            and flags == region_screenshot_spec['flags']
        ):
            matched_action = 'region_screenshot'
        elif (
            edge_toggle_spec is not None
            and keycode == edge_toggle_spec['keycode']
            and flags == edge_toggle_spec['flags']
        ):
            matched_action = 'edge_toggle'
        if matched_action is None:
            return
        if now - self._last_trigger < self._cooldown_seconds:
            return
        self._last_trigger = now
        if matched_action == 'same_position_screenshot':
            self.same_position_screenshot_pressed.emit()
        elif matched_action == 'region_screenshot':
            self.region_screenshot_pressed.emit()
        elif matched_action == 'edge_toggle':
            self.edge_toggle_pressed.emit()
        else:
            self.ui_hotkey_pressed.emit()


