# ── Native macOS notifications (UNUserNotificationCenter) ──────────────────────
# A real system notification on agent completion, with an "Open" action that brings
# Broccoli to the front and jumps to that conversation. The app icon + correct click
# routing require running as the packaged .app bundle (dev mode is attributed to the
# Python framework org.python.python). Alert only -- no sound.
_MAC_NOTIFICATION_DELEGATE_CLASS = None
if sys.platform == 'darwin' and objc is not None:
    try:
        from Foundation import NSObject as _NSObjectForNotif

        class _BroccoliNotificationDelegate(_NSObjectForNotif):
            def userNotificationCenter_willPresentNotification_withCompletionHandler_(
                    self, center, notification, completionHandler):
                # Show the banner even when Broccoli is the foreground app.
                try:
                    from UserNotifications import (
                        UNNotificationPresentationOptionBanner,
                        UNNotificationPresentationOptionList,
                    )
                    completionHandler(int(UNNotificationPresentationOptionBanner)
                                      | int(UNNotificationPresentationOptionList))
                except Exception:
                    try:
                        completionHandler(0)
                    except Exception:
                        pass

            def userNotificationCenter_didReceiveNotificationResponse_withCompletionHandler_(
                    self, center, response, completionHandler):
                try:
                    path = ''
                    info = response.notification().request().content().userInfo()
                    if info is not None:
                        # userInfo may bridge back as a Python dict OR an NSDictionary;
                        # .get() works for both, objectForKey_ only for NSDictionary.
                        try:
                            path = str(info.get('path', '') or '')
                        except Exception:
                            try:
                                path = str(info.objectForKey_('path') or '')
                            except Exception:
                                path = ''
                    mgr = globals().get('_mac_notifier')
                    if mgr is not None:
                        mgr.handle_click(path)
                except Exception:
                    logging.exception('notification click handling failed')
                try:
                    completionHandler()
                except Exception:
                    pass

        _MAC_NOTIFICATION_DELEGATE_CLASS = _BroccoliNotificationDelegate
    except Exception:
        _MAC_NOTIFICATION_DELEGATE_CLASS = None


class _MacNotificationManager:
    def __init__(self):
        self._center = None
        self._delegate = None   # strong ref required (else garbage-collected)
        self._ready = False
        self._window = None

    def setup(self, window):
        self._window = window
        if self._ready or sys.platform != 'darwin' or objc is None or _MAC_NOTIFICATION_DELEGATE_CLASS is None:
            return
        try:
            from Foundation import NSSet
            from UserNotifications import (
                UNUserNotificationCenter, UNNotificationAction, UNNotificationCategory,
                UNAuthorizationOptionAlert, UNNotificationActionOptionForeground,
                UNNotificationCategoryOptionNone,
            )
            center = UNUserNotificationCenter.currentNotificationCenter()
            if center is None:
                return
            self._delegate = _MAC_NOTIFICATION_DELEGATE_CLASS.alloc().init()
            center.setDelegate_(self._delegate)
            open_action = UNNotificationAction.actionWithIdentifier_title_options_(
                'OPEN', _tr('Open'), UNNotificationActionOptionForeground)
            category = UNNotificationCategory.categoryWithIdentifier_actions_intentIdentifiers_options_(
                'BROCCOLI_AGENT', [open_action], [], UNNotificationCategoryOptionNone)
            center.setNotificationCategories_(NSSet.setWithObject_(category))
            center.requestAuthorizationWithOptions_completionHandler_(
                int(UNAuthorizationOptionAlert), lambda granted, error: None)
            self._center = center
            self._ready = True
        except Exception:
            logging.exception('macOS notification setup failed')

    def post(self, title, body, path):
        if not self._ready or self._center is None:
            return
        try:
            from UserNotifications import UNMutableNotificationContent, UNNotificationRequest
            content = UNMutableNotificationContent.alloc().init()
            content.setTitle_(str(title or 'Broccoli'))
            content.setBody_(str(body or ''))
            content.setCategoryIdentifier_('BROCCOLI_AGENT')
            content.setUserInfo_({'path': str(path or '')})
            ident = f'broccoli-agent-{int(time.time() * 1000)}'
            req = UNNotificationRequest.requestWithIdentifier_content_trigger_(ident, content, None)
            self._center.addNotificationRequest_withCompletionHandler_(req, None)
        except Exception:
            logging.exception('macOS notification post failed')

    def handle_click(self, path):
        window = self._window
        if window is None:
            return
        try:
            if NSApp is not None:
                NSApp.activateIgnoringOtherApps_(True)
        except Exception:
            pass
        try:
            window.show()
            window.raise_()
            window.activateWindow()
        except Exception:
            pass
        path = str(path or '').strip()
        if path and hasattr(window, '_activate_agent_conversation_badge'):
            try:
                window._activate_agent_conversation_badge(path)
            except Exception:
                logging.exception('notification navigate failed')


_mac_notifier = _MacNotificationManager()


# ── macOS 27: guard against the Qt tray-icon crash (NSInternalInconsistencyException) ──
# On macOS 27 the status-bar item is driven by gesture recognizers / scene actions, so
# when Qt's cocoa plugin (QCocoaSystemTrayIcon::emitActivated, all released Qt <= 6.11.2)
# reacts to the tray menu opening it reads `NSApp.currentEvent` -- now a stale MouseExited
# event rather than the click -- and calls `-[NSEvent clickCount]` on it.  AppKit raises
# "Invalid message sent to event" for non-mouse events and the whole process aborts.
# Qt fixed this upstream only in its dev branch (qt_mac_isMouseEvent guard), so until a
# released PyQt6-Qt6 carries it we make clickCount return 0 for non-mouse events instead
# of raising.  Real mouse events are untouched (their original implementation is called).
_NSEVENT_CLICKCOUNT_GUARD = None


def _install_macos_nsevent_clickcount_guard():
    """Return True when the guard is installed (or already was); False otherwise."""
    global _NSEVENT_CLICKCOUNT_GUARD
    if _NSEVENT_CLICKCOUNT_GUARD is not None:
        return True
    if sys.platform != 'darwin':
        return False
    try:
        import ctypes
        import ctypes.util
        ctypes.CDLL('/System/Library/Frameworks/AppKit.framework/AppKit')
        lib = ctypes.CDLL(ctypes.util.find_library('objc') or '/usr/lib/libobjc.dylib')
        lib.objc_getClass.restype = ctypes.c_void_p
        lib.objc_getClass.argtypes = [ctypes.c_char_p]
        lib.sel_registerName.restype = ctypes.c_void_p
        lib.sel_registerName.argtypes = [ctypes.c_char_p]
        lib.class_getInstanceMethod.restype = ctypes.c_void_p
        lib.class_getInstanceMethod.argtypes = [ctypes.c_void_p, ctypes.c_void_p]
        lib.method_getImplementation.restype = ctypes.c_void_p
        lib.method_getImplementation.argtypes = [ctypes.c_void_p]
        lib.method_setImplementation.restype = ctypes.c_void_p
        lib.method_setImplementation.argtypes = [ctypes.c_void_p, ctypes.c_void_p]
        ns_event = lib.objc_getClass(b'NSEvent')
        sel_click = lib.sel_registerName(b'clickCount')
        sel_type = lib.sel_registerName(b'type')
        method = lib.class_getInstanceMethod(ns_event, sel_click) if ns_event else None
        if not method:
            return False
        imp_t = ctypes.CFUNCTYPE(ctypes.c_long, ctypes.c_void_p, ctypes.c_void_p)     # NSInteger (id, SEL)
        type_t = ctypes.CFUNCTYPE(ctypes.c_ulong, ctypes.c_void_p, ctypes.c_void_p)   # NSUInteger (id, SEL)
        original = imp_t(lib.method_getImplementation(method))
        event_type = type_t(ctypes.cast(lib.objc_msgSend, ctypes.c_void_p).value)
        # NSEventType values for which clickCount is legal: left/right down+up, moved,
        # left/right dragged, other down/up/dragged.
        mouse_types = frozenset({1, 2, 3, 4, 5, 6, 7, 25, 26, 27})

        def _guarded_click_count(self_ptr, cmd_ptr):
            try:
                if self_ptr and event_type(self_ptr, sel_type) in mouse_types:
                    return original(self_ptr, cmd_ptr)
            except Exception:
                pass
            return 0

        replacement = imp_t(_guarded_click_count)
        lib.method_setImplementation(method, ctypes.cast(replacement, ctypes.c_void_p).value)
        # Keep the callbacks alive for the process lifetime (the ObjC runtime holds raw pointers).
        _NSEVENT_CLICKCOUNT_GUARD = (replacement, original, event_type, lib)
        return True
    except Exception:
        logging.exception('macOS NSEvent clickCount guard install failed')
        return False


_install_macos_nsevent_clickcount_guard()


