        bk.setContentsMargins(0, 0, 0, 0)
        bk.addWidget(l1)
        bk.addWidget(l2)
        widge_all.setLayout(bk)

        m1 = QLabel(_tr('Thank you for your kind support! 😊'), self)
        m2 = QLabel(_tr('I will write more interesting apps! 🥳'), self)

        widg_c = QWidget()
