        bt1.setMinimumWidth(100)
        bt1.clicked.connect(self.cancel)
        bt2 = WhiteButton(_tr('Neither one above? Buy me a coffee~'))
        bt2.setMinimumWidth(260)
        bt2.clicked.connect(self.coffee)
        blay8 = QHBoxLayout()
        blay8.setContentsMargins(0, 0, 0, 0)
        blay8.addStretch()
        blay8.addWidget(bt1)
        blay8.addWidget(bt2)
