# ---- One-click in-app update: download → verify → install → relaunch ---------
# Every release ships one notarized DMG (GitHub's asset `digest` = its sha256).
#  1. window_update downloads it into ~/Library/Caches/Broccoli/Updates with a
#     progress bar (a .part file, resumed with an HTTP Range request), then
#     checks size + sha256.
#  2. It mounts the DMG read-only (the DMG shows a licence agreement first, so
#     "Y" is answered on stdin), copies Broccoli.app into a hidden folder NEXT TO
#     the running bundle (same volume → the swap later is a plain rename) and
#     requires the copy to satisfy BROCCOLI_UPDATE_CODE_REQUIREMENT (Developer
#     ID + this team + this bundle id): a tampered or foreign package never
#     gets installed.
#  3. Broccoli quits through its normal path. AFTER app.exec() returns, this same
#     process swaps the bundles. macOS App Management lets an app modify apps
#     signed by its own Team ID; doing the swap in-process keeps that
#     attribution certain (a helper script outliving us might not be credited).
#  4. A detached waiter reopens the app once this PID is gone (the single-
#     instance lock would turn away an early launch). The new build deletes the
#     previous bundle on its first start and reports the result.
# The same Developer ID signature also keeps macOS privacy permissions
# (Accessibility, Screen Recording…) attached across the swap.
BROCCOLI_UPDATE_LATEST_API = 'https://api.github.com/repos/Ryan-the-hito/Broccoli/releases/latest'
BROCCOLI_UPDATE_RELEASES_URL = 'https://github.com/Ryan-the-hito/Broccoli/releases'
BROCCOLI_UPDATE_BUNDLE_ID = 'Broccoli'
BROCCOLI_UPDATE_TEAM_ID = '49C7YMHM5Q'
BROCCOLI_UPDATE_CODE_REQUIREMENT = (
    'anchor apple generic and identifier "%s"'
    ' and certificate 1[field.1.2.840.113635.100.6.2.6] exists'      # Developer ID CA
    ' and certificate leaf[field.1.2.840.113635.100.6.1.13] exists'  # Developer ID Application
    ' and certificate leaf[subject.OU] = "%s"' % (BROCCOLI_UPDATE_BUNDLE_ID, BROCCOLI_UPDATE_TEAM_ID))
BROCCOLI_UPDATE_CACHE_DIR = os.path.join(str(Path.home()), 'Library', 'Caches', 'Broccoli', 'Updates')
BROCCOLI_UPDATE_RESULT_PATH = os.path.join(BROCCOLI_UPDATE_CACHE_DIR, 'last_install.json')
BROCCOLI_UPDATE_STAGING_DIRNAME = '.Broccoli-update'
_BROCCOLI_UPDATE_FS_LOCK = threading.Lock()   # staging vs. the startup cleanup of the same folder
_BROCCOLI_PENDING_UPDATE_INSTALL = None        # set right before quitting for an install


class BroccoliUpdateError(Exception):
    """A user-presentable reason the update stopped (already translated)."""


class BroccoliUpdateCanceled(BroccoliUpdateError):
    pass


def broccoli_parse_version(text) -> tuple | None:
    match = re.search(r'(\d+)\.(\d+)\.(\d+)', str(text or ''))
    return tuple(int(part) for part in match.groups()) if match else None


def broccoli_is_newer_version(candidate, current) -> bool:
    newer, older = broccoli_parse_version(candidate), broccoli_parse_version(current)
    return bool(newer and older and newer > older)


def broccoli_running_app_bundle() -> Path | None:
    """The .app bundle this process runs from (packaged builds only)."""
    if not getattr(sys, 'frozen', False):
        return None
    try:
        bundle = Path(sys.executable).resolve().parents[2]
    except Exception:
        return None
    if bundle.suffix != '.app' or not (bundle / 'Contents' / 'Info.plist').is_file():
        return None
    return bundle


def broccoli_update_install_blocker(bundle: Path | None) -> str:
    """Why this copy cannot replace itself ('' when it can)."""
    if sys.platform != 'darwin':
        return _tr('automatic install needs macOS')
    if bundle is None:
        return _tr('Broccoli is not running from an installed app')
    if '/AppTranslocation/' in str(bundle):
        return _tr('macOS is running Broccoli from a temporary copy; move it into Applications first')
    # renaming the bundle into another folder needs write access to it and its parent
    if not os.access(str(bundle.parent), os.W_OK) or not os.access(str(bundle), os.W_OK):
        return _tr('no permission to replace {path}').format(path=str(bundle))
    return ''


def broccoli_fetch_latest_release() -> dict | None:
    """Latest release from the GitHub API: tag, version and its DMG asset
    (dmg_* fields stay empty when the release carries no DMG)."""
    response = requests.get(BROCCOLI_UPDATE_LATEST_API, timeout=(4, 6),
                            headers={'Accept': 'application/vnd.github+json'})
    if not response.ok:
        return None
    data = response.json() or {}
    tag = str(data.get('tag_name', '') or '').strip()
    if not re.fullmatch(r'v\d+\.\d+\.\d+', tag):
        return None
    info = {'tag': tag, 'version': tag[1:], 'dmg_name': '', 'dmg_url': '', 'dmg_size': 0, 'dmg_sha256': ''}
    dmgs = [asset for asset in (data.get('assets') or []) if isinstance(asset, dict)
            and str(asset.get('name', '')).lower().endswith('.dmg')
            and str(asset.get('state', 'uploaded')) == 'uploaded'
            and str(asset.get('browser_download_url', '')).startswith('https://')]
    dmgs.sort(key=lambda asset: not str(asset.get('name', '')).lower().startswith('broccoli'))
    if dmgs:
        asset = dmgs[0]
        digest = str(asset.get('digest') or '')
        info.update(dmg_name=str(asset.get('name')),
                    dmg_url=str(asset.get('browser_download_url')),
                    dmg_size=int(asset.get('size') or 0),
                    dmg_sha256=digest[7:].lower() if digest.lower().startswith('sha256:') else '')
    return info


def _broccoli_sha256_file(path: str) -> str:
    digest = hashlib.sha256()
    with open(path, 'rb') as handle:
        for block in iter(lambda: handle.read(4 << 20), b''):
            digest.update(block)
    return digest.hexdigest()


def _broccoli_update_file_matches(path: str, size: int, sha256: str) -> bool:
    try:
        if size and os.path.getsize(path) != size:
            return False
        return not sha256 or _broccoli_sha256_file(path) == sha256
    except OSError:
        return False


def broccoli_download_update_dmg(info: dict, progress, cancel_event, status=None) -> str:
    """Download the release DMG into the cache (resuming an earlier .part),
    verify size + sha256 and return its path. progress(done, total) and
    status(text) run on the calling worker thread; cancel_event aborts
    between chunks and keeps the .part for the next attempt."""
    status = status or (lambda _text: None)
    url = str(info.get('dmg_url') or '')
    if not url:
        raise BroccoliUpdateError(_tr('This release has no installer package.'))
    size = int(info.get('dmg_size') or 0)
    sha256 = str(info.get('dmg_sha256') or '').lower()
    os.makedirs(BROCCOLI_UPDATE_CACHE_DIR, exist_ok=True)
    name = re.sub(r'[^A-Za-z0-9._-]+', '_', str(info.get('dmg_name') or '')).strip('.') or 'Broccoli-update.dmg'
    final_path = os.path.join(BROCCOLI_UPDATE_CACHE_DIR, name)
    part_path = final_path + '.part'
    if os.path.isfile(final_path):
        status(_tr('Verifying the download…'))
        if _broccoli_update_file_matches(final_path, size, sha256):
            return final_path
        os.remove(final_path)
    have = os.path.getsize(part_path) if os.path.isfile(part_path) else 0
    if size and have > size:
        os.remove(part_path)
        have = 0
    if not size or have < size:
        headers = {'Range': 'bytes=%d-' % have} if have else {}
        try:
            with requests.get(url, stream=True, timeout=(10, 60), headers=headers) as response:
                if have and response.status_code == 206:
                    mode = 'ab'
                elif response.status_code == 200:
                    mode, have = 'wb', 0
                else:
                    raise BroccoliUpdateError(
                        _tr('Download failed (HTTP {code}).').format(code=response.status_code))
                total = size or (have + int(response.headers.get('Content-Length') or 0))
                progress(have, total)
                with open(part_path, mode) as handle:
                    for chunk in response.iter_content(chunk_size=1 << 20):
                        if cancel_event.is_set():
                            raise BroccoliUpdateCanceled(_tr('Download canceled.'))
                        if chunk:
                            handle.write(chunk)
                            have += len(chunk)
                            progress(have, total)
        except BroccoliUpdateError:
            raise
        except Exception as exc:
            raise BroccoliUpdateError(_tr('Download interrupted: {err}').format(err=exc)) from exc
    status(_tr('Verifying the download…'))
    if not _broccoli_update_file_matches(part_path, size, sha256):
        try:
            os.remove(part_path)
        except OSError:
            pass
        raise BroccoliUpdateError(_tr('The download is damaged (checksum mismatch). Please try again.'))
    os.replace(part_path, final_path)
    return final_path


def _broccoli_attach_dmg(dmg_path: str, mountpoint: str) -> None:
    env = dict(os.environ, PAGER='/bin/cat')
    commands = (
        ['/usr/bin/hdiutil', 'attach', '-nobrowse', '-readonly', '-noautoopen', '-noverify',
         '-mountpoint', mountpoint, dmg_path],
        # hdiutil is deprecated from macOS 27 on; diskutil image is its successor
        ['/usr/sbin/diskutil', 'image', 'attach', '--mountOptions', 'nobrowse', '--readOnly',
         '--mountPoint', mountpoint, dmg_path],
    )
    for command in commands:
        if not os.path.exists(command[0]):
            continue
        try:
            # the release DMG shows a licence agreement before mounting; "Y" accepts it
            subprocess.run(command, input=b'Y\n', capture_output=True, timeout=300, env=env)
        except Exception:
            continue
        if os.path.ismount(mountpoint):
            return
    raise BroccoliUpdateError(_tr('Could not open the downloaded installer.'))


def _broccoli_detach_dmg(mountpoint: str) -> None:
    for command in (['/usr/bin/hdiutil', 'detach', mountpoint, '-quiet'],
                    ['/usr/bin/hdiutil', 'detach', mountpoint, '-force', '-quiet'],
                    ['/usr/sbin/diskutil', 'eject', mountpoint]):
        if not os.path.ismount(mountpoint):
            break
        if not os.path.exists(command[0]):
            continue
        try:
            subprocess.run(command, capture_output=True, timeout=60)
        except Exception:
            pass
    if not os.path.ismount(mountpoint):
        try:
            os.rmdir(mountpoint)
        except OSError:
            pass


def _broccoli_bundle_info(bundle: Path) -> dict:
    try:
        with open(Path(bundle) / 'Contents' / 'Info.plist', 'rb') as handle:
            data = plistlib.load(handle)
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}


def broccoli_verify_update_bundle(bundle: Path) -> str:
    """Return the bundle's version once its whole signature satisfies
    BROCCOLI_UPDATE_CODE_REQUIREMENT; raise BroccoliUpdateError otherwise."""
    info = _broccoli_bundle_info(bundle)
    if info.get('CFBundleIdentifier') != BROCCOLI_UPDATE_BUNDLE_ID:
        raise BroccoliUpdateError(_tr('The installer does not contain Broccoli.'))
    try:
        result = subprocess.run(['/usr/bin/codesign', '--verify', '--deep', '--strict',
                                 '-R=' + BROCCOLI_UPDATE_CODE_REQUIREMENT, str(bundle)],
                                capture_output=True, timeout=900)
    except Exception as exc:
        raise BroccoliUpdateError(_tr('Could not check the signature: {err}').format(err=exc)) from exc
    if result.returncode != 0:
        logging.warning('Update bundle rejected by codesign: %s',
                        result.stderr.decode('utf-8', 'replace')[-800:])
        raise BroccoliUpdateError(
            _tr('The update is not signed by the Broccoli developer, so it was not installed.'))
    return str(info.get('CFBundleShortVersionString') or '')


def broccoli_stage_update(dmg_path: str, target: Path, status=None) -> dict:
    """Copy the DMG's Broccoli.app into <target's folder>/.Broccoli-update and
    verify the copy. Returns the pending-install record applied after the
    event loop ends (broccoli_apply_pending_update_install)."""
    import tempfile
    status = status or (lambda _text: None)
    target = Path(target)
    staging_root = target.parent / BROCCOLI_UPDATE_STAGING_DIRNAME
    staged = staging_root / target.name
    with _BROCCOLI_UPDATE_FS_LOCK:
        try:
            if staging_root.exists():
                shutil.rmtree(staging_root, ignore_errors=True)
            staging_root.mkdir(parents=True, exist_ok=True)
            os.makedirs(BROCCOLI_UPDATE_CACHE_DIR, exist_ok=True)
            mountpoint = tempfile.mkdtemp(prefix='mnt-', dir=BROCCOLI_UPDATE_CACHE_DIR)
            try:
                status(_tr('Opening the installer…'))
                _broccoli_attach_dmg(dmg_path, mountpoint)
                source = next((entry for entry in sorted(Path(mountpoint).iterdir())
                               if entry.suffix == '.app' and entry.is_dir() and not entry.is_symlink()
                               and _broccoli_bundle_info(entry).get('CFBundleIdentifier') == BROCCOLI_UPDATE_BUNDLE_ID),
                              None)
                if source is None:
                    raise BroccoliUpdateError(_tr('The installer does not contain Broccoli.'))
                status(_tr('Copying the new version…'))
                copied = subprocess.run(['/usr/bin/ditto', str(source), str(staged)],
                                        capture_output=True, timeout=1800)
                if copied.returncode != 0 or not staged.is_dir():
                    raise BroccoliUpdateError(_tr('Could not copy the new version: {err}').format(
                        err=copied.stderr.decode('utf-8', 'replace').strip()[-300:]))
            finally:
                _broccoli_detach_dmg(mountpoint)
            subprocess.run(['/usr/bin/xattr', '-dr', 'com.apple.quarantine', str(staged)],
                           capture_output=True, timeout=300)
            status(_tr('Checking the developer signature…'))
            version = broccoli_verify_update_bundle(staged)
            if broccoli_is_newer_version(VERSION, version):
                raise BroccoliUpdateError(
                    _tr('The installer holds an older version (v{v}); nothing was changed.').format(v=version))
        except Exception as exc:
            shutil.rmtree(staging_root, ignore_errors=True)
            if isinstance(exc, BroccoliUpdateError):
                raise
            raise BroccoliUpdateError(_tr('Could not prepare the update: {err}').format(err=exc)) from exc
    return {'target': str(target), 'staged': str(staged),
            'backup': str(staging_root / ('previous-' + target.name)),
            'version': version, 'dmg': str(dmg_path)}


def _broccoli_write_update_result(record: dict) -> None:
    try:
        os.makedirs(BROCCOLI_UPDATE_CACHE_DIR, exist_ok=True)
        with open(BROCCOLI_UPDATE_RESULT_PATH, 'w', encoding='utf-8') as handle:
            json.dump(record, handle, ensure_ascii=False)
    except Exception:
        pass


def broccoli_take_last_update_result() -> dict:
    """The record the previous run left after an install attempt (read once)."""
    try:
        with open(BROCCOLI_UPDATE_RESULT_PATH, 'r', encoding='utf-8') as handle:
            record = json.load(handle)
    except Exception:
        return {}
    try:
        os.remove(BROCCOLI_UPDATE_RESULT_PATH)
    except OSError:
        pass
    return record if isinstance(record, dict) else {}


def _broccoli_spawn_relauncher(app_path: str) -> None:
    """Reopen app_path once this process has exited (force-kill after ~60 s if
    it hangs). Double-forked: the waiter is reparented to launchd, so no
    child-process reaping on our way out can touch it."""
    waiter = ('pid=$1; app=$2; n=0; '
              'while kill -0 "$pid" 2>/dev/null; do '
              'n=$((n+1)); if [ "$n" -ge 300 ]; then kill -9 "$pid" 2>/dev/null; sleep 1; break; fi; '
              'sleep 0.2; done; sleep 0.5; /usr/bin/open "$app"')
    try:
        subprocess.Popen(['/bin/sh', '-c', '(' + waiter + ') </dev/null >/dev/null 2>&1 &',
                          'broccoli-relaunch', str(os.getpid()), str(app_path)],
                         stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                         start_new_session=True, close_fds=True).wait(timeout=10)
    except Exception:
        pass


def broccoli_apply_pending_update_install() -> None:
    """Runs after app.exec() returns: swap the staged bundle in, record the
    outcome, schedule the relaunch. A failed rename rolls back and reopens the
    old build, which then shows the reason (window_update startup note)."""
    pending = _BROCCOLI_PENDING_UPDATE_INSTALL
    if not pending:
        return
    target, staged, backup = Path(pending['target']), Path(pending['staged']), Path(pending['backup'])
    record = {'status': 'failed', 'version': str(pending.get('version') or ''), 'previous': VERSION,
              'dmg': str(pending.get('dmg') or ''), 'reason': '', 'time': time.time()}
    try:
        # exit hooks (lock release, child reaping, pending writes) run now, while every
        # file of the running build is still where this process expects it
        atexit._run_exitfuncs()
    except Exception:
        pass
    launch = target
    try:
        if not staged.is_dir():
            raise FileNotFoundError(str(staged))
        if backup.exists():
            shutil.rmtree(backup, ignore_errors=True)
        os.rename(target, backup)
        try:
            os.rename(staged, target)
        except OSError:
            try:
                os.rename(backup, target)
            except OSError:
                launch = backup
            raise
        record['status'] = 'installed'
    except Exception as exc:
        record['reason'] = '%s: %s' % (type(exc).__name__, exc)
    _broccoli_write_update_result(record)
    _broccoli_spawn_relauncher(str(launch))


def broccoli_cleanup_update_leftovers() -> None:
    """Startup (background thread): drop the previous bundle kept by the last
    swap or a stale staged copy, stale mounts, and cached installers this
    build has already reached. A failed install keeps its DMG for the retry."""
    with _BROCCOLI_UPDATE_FS_LOCK:
        bundle = broccoli_running_app_bundle()
        if bundle is not None:
            staging_root = bundle.parent / BROCCOLI_UPDATE_STAGING_DIRNAME
            if staging_root.is_dir():
                shutil.rmtree(staging_root, ignore_errors=True)
        if not os.path.isdir(BROCCOLI_UPDATE_CACHE_DIR):
            return
        for name in os.listdir(BROCCOLI_UPDATE_CACHE_DIR):
            path = os.path.join(BROCCOLI_UPDATE_CACHE_DIR, name)
            try:
                if name.startswith('mnt-') and os.path.isdir(path):
                    _broccoli_detach_dmg(path)
                elif name.endswith(('.dmg', '.dmg.part')) and not broccoli_is_newer_version(name, VERSION):
                    os.remove(path)
            except Exception:
                pass


class _UpdateProgressBar(QWidget):
    """Slim rounded track for the update window. busy=True sweeps an
    indeterminate segment (mount / copy / signature check have no percentage)."""

    def __init__(self, parent=None):
        super().__init__(parent)
        self._fraction = 0.0
        self._busy = False
        self._phase = 0.0
        self._timer = QTimer(self)
        self._timer.setInterval(30)
        self._timer.timeout.connect(self._advance)
        self.setFixedHeight(6)

    def fraction(self) -> float:
        return self._fraction

    def is_busy(self) -> bool:
        return self._busy

    def set_fraction(self, fraction: float):
        self._busy = False
        self._timer.stop()
        self._fraction = max(0.0, min(1.0, float(fraction)))
        self.update()

    def set_busy(self, busy: bool = True):
        self._busy = bool(busy)
        if self._busy and self.isVisible():
            self._timer.start()
        else:
            self._timer.stop()
        self.update()

    def showEvent(self, event):
        super().showEvent(event)
        if self._busy:
            self._timer.start()

    def hideEvent(self, event):
        self._timer.stop()
        super().hideEvent(event)

    def _advance(self):
        self._phase = (self._phase + 0.015) % 1.0
        self.update()

    def paintEvent(self, event):
        painter = QPainter(self)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)
        rect = QRectF(self.rect())
        radius = rect.height() / 2.0
        dark = is_dark_theme(app)
        track = QPainterPath()
        track.addRoundedRect(rect, radius, radius)
        painter.fillPath(track, QColor('#3A3A3C') if dark else QColor('#E5E5EA'))
        if self._busy:
            segment = rect.width() * 0.3
            fill_rect = QRectF(rect.left() - segment + (rect.width() + segment) * self._phase,
                               rect.top(), segment, rect.height())
        else:
            fill_rect = QRectF(rect.left(), rect.top(), rect.width() * self._fraction, rect.height())
        if fill_rect.width() > 0:
            fill = QPainterPath()
            fill.addRoundedRect(fill_rect, radius, radius)
            painter.setClipPath(track)
            painter.fillPath(fill, QColor('#0A84FF') if dark else QColor('#007AFF'))


class _UpdateStatusLabel(QLabel):
    """The update window's status line; tells the window when its text changes (the window
    shows the line only while it says something, and fits its height to it)."""
    text_changed = None

    def setText(self, text):
        super().setText(text)
        if callable(self.text_changed):
            self.text_changed()


class window_update(QWidget):  # 增加更新页面（Check for Updates）
    # (result_text, update_ready, popup_when_ready, release_info) from the fetch thread.
    update_check_finished = pyqtSignal(str, bool, bool, object)
    # one-click install worker → GUI thread
    install_progress = pyqtSignal(object, object)   # (done_bytes, total_bytes)
    install_status = pyqtSignal(str)                # a phase without percentage
    install_failed = pyqtSignal(str)
    install_ready = pyqtSignal(object)              # pending-install record

    def __init__(self):
        super().__init__()
        self.radius = 36
        self.drag_pos = None
        self._check_inflight = False
        self._release_info = None
        self._update_available = False
        self._install_busy = False
        self._install_can_cancel = False
        self._install_cancel = None
        self._download_started_at = 0.0
        self._download_started_bytes = 0
        self._startup_note = self._read_startup_note()
        self.update_check_finished.connect(self._on_update_check_finished)
        self.install_progress.connect(self._on_install_progress)
        self.install_status.connect(self._on_install_status)
        self.install_failed.connect(self._on_install_failed)
        self.install_ready.connect(self._on_install_ready)
        self.setWindowFlags(
            Qt.WindowType.FramelessWindowHint |
            Qt.WindowType.Window |
            Qt.WindowType.WindowStaysOnTopHint
        )
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground)
        self.setAttribute(Qt.WidgetAttribute.WA_NoSystemBackground)
        self.initUI()

    def initUI(self):  # 说明页面内信息
        self.setUpMainWindow()
        self.setFixedWidth(320)
        self._fit_height()
        self.center()
        self.setWindowTitle(_tr('Broccoli Updates'))
        self.setFocus()

    def _fit_height(self):
        """As tall as the content: no empty band at the bottom. While a download runs the
        progress bar and the status line appear under the buttons and the window grows by
        that much (its top edge and everything above stay where they are)."""
        layout = self.layout()
        if layout is None:
            return
        busy = not self.install_progress_bar.isHidden() or bool(self.install_status_lbl.text().strip())
        self._progress_block.setVisible(busy)
        layout.activate()
        width = self.width() or 320
        height = layout.totalHeightForWidth(width) if layout.hasHeightForWidth() else layout.totalSizeHint().height()
        self.setFixedHeight(max(1, int(height)))

    def paintEvent(self, event):
        if getattr(self, '_liquid_glass_active', False):
            return   # the window's Liquid Glass is the card
        painter = QPainter(self)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)
        painter.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform)
        rect = QRectF(self.rect())
        path = smooth_round_rect_path(rect, self.radius)
        painter.setClipPath(path)
        bg_color = self.palette().color(QPalette.ColorRole.Window)
        painter.fillPath(path, bg_color)

    def mousePressEvent(self, event):
        if event.button() == Qt.MouseButton.LeftButton:
            self.drag_pos = event.globalPosition().toPoint() - self.frameGeometry().topLeft()
            event.accept()

    def mouseMoveEvent(self, event):
        if event.buttons() == Qt.MouseButton.LeftButton and self.drag_pos is not None:
            self.move(event.globalPosition().toPoint() - self.drag_pos)
            event.accept()

    def setUpMainWindow(self):
        self.close_button = MacWindowButton("#FF605C", "x", self)
        self.close_button.move(10, 10)
        self.close_button.clicked.connect(self.close)

        # Laid out like the About window: the same margins and rhythm (text lines 6 + 5 px
        # apart, button rows in 50 px rows), everything centred on the middle line, the two
        # action rows sharing one label column and one button column. The window is as tall
        # as its content (see _fit_height).
        title = QLabel(_tr("<h2>Broccoli Update</h2>"), self)
        title.setAlignment(Qt.AlignmentFlag.AlignCenter)

        self.lbl = QLabel(_tr('Current version: v{v}').format(v=VERSION), self)
        self.lbl.setAlignment(Qt.AlignmentFlag.AlignCenter)

        widg5 = QWidget()
        lbl1 = QLabel(_tr('Latest version:'), self)
        self.lbl2 = QLabel('', self)
        blay5 = QHBoxLayout()
        blay5.setContentsMargins(0, 0, 0, 0)
        blay5.setSpacing(4)
        blay5.addStretch(1)
        blay5.addWidget(lbl1)
        blay5.addWidget(self.lbl2)
        blay5.addStretch(1)
        widg5.setLayout(blay5)

        lbl0 = QLabel(_tr('Check release:'), self)
        bt1 = WhiteButton(_tr('Github'))
        bt1.setFixedWidth(120)
        bt1.clicked.connect(self.upd)
        # one-click update: download with progress → verify → install → relaunch
        lbl_install = QLabel(_tr('Install update:'), self)
        self.install_btn = WhiteButton(_tr('Update Now'))
        self.install_btn.setFixedWidth(120)
        self.install_btn.setEnabled(False)
        self.install_btn.clicked.connect(self.start_install)
        label_width = max(lbl0.sizeHint().width(), lbl_install.sizeHint().width())
        action_rows = []
        for label, button in ((lbl0, bt1), (lbl_install, self.install_btn)):
            label.setFixedWidth(label_width)
            label.setAlignment(Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter)
            row = QWidget()
            row.setFixedHeight(50)   # About's button rows
            row_layout = QHBoxLayout(row)
            row_layout.setContentsMargins(0, 0, 0, 0)
            row_layout.setSpacing(12)
            row_layout.addStretch(1)
            row_layout.addWidget(label)
            row_layout.addWidget(button)
            row_layout.addStretch(1)
            action_rows.append(row)

        # progress bar + status line: only while there is something to show
        self._progress_block = QWidget()
        progress_layout = QVBoxLayout(self._progress_block)
        progress_layout.setContentsMargins(0, 6, 0, 0)
        progress_layout.setSpacing(10)
        self.install_progress_bar = _UpdateProgressBar(self._progress_block)
        self.install_progress_bar.hide()
        self.install_status_lbl = _UpdateStatusLabel(self._progress_block)
        self.install_status_lbl.setWordWrap(True)
        self.install_status_lbl.setAlignment(Qt.AlignmentFlag.AlignHCenter | Qt.AlignmentFlag.AlignTop)
        self.install_status_lbl.text_changed = lambda: QTimer.singleShot(0, self._fit_height)
        progress_layout.addWidget(self.install_progress_bar)
        progress_layout.addWidget(self.install_status_lbl)
        self.install_progress_bar.installEventFilter(self)
        self._progress_block.hide()

        main_h_box = QVBoxLayout()
        main_h_box.setContentsMargins(20, 40, 20, 20)
        main_h_box.addSpacing(10)
        main_h_box.addWidget(title)
        main_h_box.addSpacing(5)
        main_h_box.addWidget(self.lbl)
        main_h_box.addSpacing(5)
        main_h_box.addWidget(widg5)
        main_h_box.addSpacing(16)
        for row in action_rows:
            main_h_box.addWidget(row)
        main_h_box.addWidget(self._progress_block)
        main_h_box.addSpacing(10)
        self.setLayout(main_h_box)

    def upd(self):
        webbrowser.open(BROCCOLI_UPDATE_RELEASES_URL)

    def eventFilter(self, obj, event):
        if obj is getattr(self, 'install_progress_bar', None) and event.type() in (QEvent.Type.Show, QEvent.Type.Hide):
            QTimer.singleShot(0, self._fit_height)
        return super().eventFilter(obj, event)

    def center(self):  # 设置窗口居中
        qr = self.frameGeometry()
        cp = self.screen().availableGeometry().center()
        qr.moveCenter(cp)
        self.move(qr.topLeft())

    def activate(self):  # 设置窗口显示
        self.show()
        self.checkupdate()

    @staticmethod
    def _read_startup_note() -> str:
        """What the previous run's install attempt left behind, shown once
        with the startup check."""
        record = broccoli_take_last_update_result()
        if record.get('status') == 'installed' and not broccoli_is_newer_version(record.get('version'), VERSION):
            return _tr('Broccoli was updated to v{v}.').format(v=VERSION)
        if record.get('status') == 'failed':
            return _tr('The last update could not be installed ({reason}). Click Update Now to try again.').format(
                reason=str(record.get('reason') or '?'))
        return ''

    def checkupdate(self, *, popup_when_ready: bool = False):
        """Kick off the release check WITHOUT touching the network on the GUI
        thread. The old implementation fetched github.com synchronously here;
        with GitHub unreachable (DNS blackhole / dropped packets) that froze
        startup and the tray action for up to ~45 s. The fetch now runs in a
        daemon thread and reports back through update_check_finished."""
        if self._check_inflight:
            return
        self._check_inflight = True
        self.lbl2.setText(_tr('Checking…'))
        self.lbl2.adjustSize()

        def worker():
            alertupdate = _tr('No Internet')
            ready = False
            info = None
            try:
                info = self.fetch_latest_release_info()
                result = (info or {}).get('tag')
                if result:
                    # only a strictly NEWER release is an update (a dev build ahead of
                    # the latest release must never be offered a downgrade)
                    if broccoli_is_newer_version(result, VERSION):
                        alertupdate = _tr('{tag} is ready!').format(tag=result)
                        ready = True
                    else:
                        alertupdate = _tr('{tag} (up-to-date)').format(tag=result)
            except Exception:
                pass
            try:
                self.update_check_finished.emit(alertupdate, ready, popup_when_ready, info)
            except RuntimeError:
                pass   # window destroyed during shutdown

        threading.Thread(target=worker, daemon=True, name='broccoli-update-check').start()

    def _on_update_check_finished(self, alertupdate: str, ready: bool, popup_when_ready: bool, info):
        self._check_inflight = False
        self.lbl2.setText(str(alertupdate or ''))
        self.lbl2.adjustSize()
        if not self._install_busy:
            self._update_available = bool(ready)
            self._release_info = dict(info) if (ready and isinstance(info, dict)) else None
            has_package = bool((self._release_info or {}).get('dmg_url'))
            self.install_btn.setEnabled(has_package)
            if ready and not has_package:
                self.install_status_lbl.setText(_tr('This release has no installer package; use the Github button.'))
        note = self._startup_note if popup_when_ready else ''
        if note and not self._install_busy:
            self._startup_note = ''
            self.install_status_lbl.setText(note)
        if popup_when_ready and (ready or note) and not self.isVisible():
            self.show()

    # ---- one-click install ----------------------------------------------------
    def start_install(self):
        if self._install_busy:
            # the same button reads "Cancel" while the download runs
            if self._install_can_cancel and self._install_cancel is not None:
                self._install_cancel.set()
                self.install_btn.setEnabled(False)
            return
        info = dict(self._release_info or {})
        if not info.get('dmg_url'):
            return
        self._install_busy = True
        self._install_can_cancel = True
        self._install_cancel = threading.Event()
        self._download_started_at = 0.0
        self._download_started_bytes = 0
        self.install_btn.setText(_tr('Cancel'))
        self.install_progress_bar.set_fraction(0.0)
        self.install_progress_bar.show()
        self.install_status_lbl.setText(_tr('Connecting…'))
        threading.Thread(target=self._install_worker, args=(info, self._install_cancel),
                         daemon=True, name='broccoli-update-install').start()

    def _install_worker(self, info: dict, cancel_event):
        last_emit = [0.0]

        def progress(done, total):
            now = time.monotonic()
            if now - last_emit[0] >= 0.1 or (total and done >= total):
                last_emit[0] = now
                self.install_progress.emit(int(done), int(total))

        try:
            dmg_path = broccoli_download_update_dmg(info, progress, cancel_event,
                                                    status=self.install_status.emit)
            bundle = broccoli_running_app_bundle()
            blocker = broccoli_update_install_blocker(bundle)
            if blocker:
                # can't swap this copy: hand the verified DMG to Finder instead
                subprocess.Popen(['/usr/bin/open', dmg_path],
                                 stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
                self.install_ready.emit({'manual': True, 'reason': blocker, 'dmg': dmg_path})
                return
            self.install_ready.emit(broccoli_stage_update(dmg_path, bundle, status=self.install_status.emit))
        except BroccoliUpdateError as exc:
            self.install_failed.emit(str(exc))
        except Exception as exc:
            logging.exception('One-click update failed.')
            self.install_failed.emit(_tr('Update failed: {err}').format(err=exc))

    def _on_install_progress(self, done, total):
        done, total = int(done or 0), int(total or 0)
        now = time.monotonic()
        if not self._download_started_at:
            self._download_started_at, self._download_started_bytes = now, done
        mb = 1024 * 1024
        text = _tr('Downloading… {done} / {total} MB').format(
            done='%.1f' % (done / mb), total=('%.1f' % (total / mb)) if total else '?')
        elapsed = now - self._download_started_at
        if elapsed >= 1.0 and done > self._download_started_bytes:
            text += ' · %.1f MB/s' % ((done - self._download_started_bytes) / mb / elapsed)
        self.install_progress_bar.set_fraction(done / total if total else 0.0)
        self.install_status_lbl.setText(text)

    def _on_install_status(self, text: str):
        # verify / mount / copy / signature: no percentage and no way back
        self._install_can_cancel = False
        self.install_btn.setEnabled(False)
        self.install_btn.setText(_tr('Installing…'))
        self.install_progress_bar.set_busy(True)
        self.install_status_lbl.setText(str(text or ''))

    def _reset_install_controls(self):
        self._install_busy = False
        self._install_can_cancel = False
        self._install_cancel = None
        self.install_progress_bar.set_busy(False)
        self.install_progress_bar.hide()
        self.install_btn.setText(_tr('Update Now'))
        self.install_btn.setEnabled(self._update_available and bool((self._release_info or {}).get('dmg_url')))

    def _on_install_failed(self, message: str):
        self._reset_install_controls()
        self.install_status_lbl.setText(str(message or ''))
        if not self.isVisible():
            self.show()

    def _on_install_ready(self, pending):
        pending = dict(pending or {})
        if pending.get('manual'):
            self._reset_install_controls()
            self.install_status_lbl.setText(
                _tr("Can't install automatically ({reason}). The installer is open: drag Broccoli into Applications.")
                .format(reason=pending.get('reason', '')))
            return
        global _BROCCOLI_PENDING_UPDATE_INSTALL
        _BROCCOLI_PENDING_UPDATE_INSTALL = pending
        self.install_progress_bar.set_fraction(1.0)
        self.install_status_lbl.setText(_tr('Restarting Broccoli to finish the update…'))
        if not self.isVisible():
            self.show()
        QTimer.singleShot(800, self._quit_for_install)

    def _quit_for_install(self):
        # the normal Quit path; the swap itself runs after app.exec() returns
        main = globals().get('w3')
        if main is not None and hasattr(main, 'totalquit'):
            main.totalquit()
        else:
            app.quit()

    @classmethod
    def fetch_latest_release_info(cls) -> dict | None:
        """Release info (tag + DMG asset) from the API; when the API is
        unavailable, the tag alone from the releases page (no one-click
        install then — the Github button still works)."""
        try:
            info = broccoli_fetch_latest_release()
            if info:
                return info
        except Exception:
            pass
        tag = cls.extract_latest_tag(cls.fetch_latest_version_text())
        return {'tag': tag} if tag else None

    @classmethod
    def fetch_latest_release_tag(cls):
        """Latest release tag ('vX.Y.Z') or None. API first (small, stable
        JSON), HTML scrape as the fallback. Tight timeouts: this must fail in
        seconds when GitHub is unreachable, and it runs off the GUI thread."""
        return (cls.fetch_latest_release_info() or {}).get('tag')

    @staticmethod
    def fetch_latest_version_text():
        targetURL = BROCCOLI_UPDATE_RELEASES_URL
        try:
            s = requests.session()
            s.keep_alive = False
            response = s.get(targetURL, timeout=(4, 8))
            response.encoding = 'utf-8'
            html_content = response.text
            soup = BeautifulSoup(html_content, "html.parser")
            for img in soup.find_all("img"):
                img.decompose()
            text_maker = html2text.HTML2Text()
            text_maker.ignore_links = True
            text_maker.ignore_images = True
            plain_text = text_maker.handle(str(soup))
            plain_text_utf8 = plain_text.encode(response.encoding).decode("utf-8")
            for _ in range(10):
                plain_text_utf8 = (plain_text_utf8
                                   .replace('\n\n\n\n', '\n\n')
                                   .replace('\n\n\n', '\n\n')
                                   .replace('   ', ' ')
                                   .replace('  ', ' '))
            return plain_text_utf8
        except Exception:
            return None

    @staticmethod
    def extract_latest_tag(plain_text_utf8: str) -> str | None:
        if not plain_text_utf8:
            return None
        pattern2 = re.compile(r'(v\d+\.\d+\.\d+)\sLatest')
        result = pattern2.findall(plain_text_utf8)
        if result:
            return result[0]
        return None


class TimeoutException(Exception):
    pass


