class PillNavBar(QWidget):
    """
    药丸形状导航栏：
    - Bar 本体：白色/浅色背景，带底部 drop shadow
    - Tab 之间竖线分隔符
    - 选中 pill：深灰色，覆盖两侧分隔符，平滑滑动动画
    - 无选中 pill 的阴影；pill 直接在 paintEvent 绘制，透明按钮露出 pill
    """
    tab_changed = pyqtSignal(int)

    def __init__(self, tabs, initial_index=0, parent=None):
        super().__init__(parent)
        self._tabs = tabs
        self._current = initial_index
        self._buttons = []
        self._theme = 'light'
        self._pill_rect = QRect()
        self._anim_start = QRect()
        self._anim_end = QRect()
        self._anim_progress = 1.0
        self._anim_timer = QTimer(self)
        self._anim_timer.setInterval(14)  # ≈ 70fps
        self._anim_timer.timeout.connect(self._anim_tick)
        self._setup()

    # ── 动画 ──────────────────────────────────────────────
    def _ease_out_cubic(self, t):
        return 1.0 - (1.0 - t) ** 3

    def _lerp_rect(self, r1, r2, t):
        def li(a, b): return int(round(a + (b - a) * t))
        return QRect(li(r1.x(), r2.x()), li(r1.y(), r2.y()),
                     li(r1.width(), r2.width()), li(r1.height(), r2.height()))

    def _anim_tick(self):
        self._anim_progress = min(1.0, self._anim_progress + 0.065)
        t = self._ease_out_cubic(self._anim_progress)
        self._pill_rect = self._lerp_rect(self._anim_start, self._anim_end, t)
        self.update()
        if self._anim_progress >= 1.0:
            self._anim_timer.stop()

    # ── 初始化 ──────────────────────────────────────────
    def _setup(self):
        # 高度 46px：外框 + 足够的 pill 高度
        self.setFixedHeight(36)

        # Bar 本身的底部 drop shadow（通过 QGraphicsDropShadowEffect）
        shadow = QGraphicsDropShadowEffect(self)
        shadow.setBlurRadius(40)
        shadow.setXOffset(0)
        shadow.setYOffset(0)
        shadow.setColor(QColor(0, 0, 0, 40))
        self.setGraphicsEffect(shadow)

        layout = QHBoxLayout(self)
        layout.setContentsMargins(2, 2, 2, 2)
        layout.setSpacing(0)
        for i, label in enumerate(self._tabs):
            btn = QPushButton(label, self)
            btn.setFlat(True)
            btn.setFixedHeight(32)  # fill bar height (36 - top_margin 2 - bottom_margin 2)
            btn.setCursor(Qt.CursorShape.PointingHandCursor)
            btn.clicked.connect(lambda checked=False, idx=i: self.select(idx))
            layout.addWidget(btn)
            self._buttons.append(btn)
        self._apply_button_styles()

    def _theme_palette(self):
        if self._theme == 'dark':
            return {
                'bar_bg': '#2D2D2D',
                'pill_bg': '#3A3A3A',
                'active_text': '#FFFFFF',
                'inactive_text': '#B8B8B8',
                'separator': QColor(255, 255, 255, 36),
            }
        return {
            'bar_bg': '#FFFFFF',
            'pill_bg': '#CBCBCB',
            'active_text': '#111111',
            'inactive_text': '#777777',
            'separator': QColor(0, 0, 0, 35),
        }

    def set_theme(self, theme):
        theme = 'dark' if theme == 'dark' else 'light'
        if self._theme == theme:
            return
        self._theme = theme
        self._apply_button_styles()
        self.update()
        helper = getattr(self, '_broccoli_inwindow_glass', None)
        if helper is not None:
            helper.sync()

    def _apply_button_styles(self):
        palette = self._theme_palette()
        if getattr(self, '_liquid_glass_active', False):
            # The labels are drawn into the glass by the bar itself (see paintEvent).
            for btn in self._buttons:
                btn.setStyleSheet("QPushButton { background: transparent; border: none; color: transparent; padding: 0; }")
            return
        for i, btn in enumerate(self._buttons):
            if i == self._current:
                btn.setStyleSheet(
                    "QPushButton { background: transparent; border: none; "
                    f"color: {palette['active_text']}; font-size: 13px; font-weight: 600; padding: 0; }} "
                    "QPushButton:pressed { background: transparent; border: none; }"
                )
            else:
                btn.setStyleSheet(
                    "QPushButton { background: transparent; border: none; "
                    f"color: {palette['inactive_text']}; font-size: 13px; font-weight: normal; padding: 0; }} "
                    "QPushButton:pressed { background: transparent; border: none; }"
                )

    def _pill_rect_for(self, idx):
        """
        pill 宽度覆盖整个按钮（0 横向 inset），确保覆盖两侧竖线分隔符。
        纵向 inset = 2px，生成饱满的药丸形状。
        """
        if 0 <= idx < len(self._buttons):
            btn = self._buttons[idx]
            # x: 与按钮左边对齐（覆盖左侧分隔符）
            # width: 按钮宽 +1（确保覆盖右侧分隔符）
            return QRect(btn.x() + 1, btn.y() + 1, btn.width() - 2, btn.height() - 2)
        return QRect()

    # ── 首次显示定位 ──────────────────────────────────────
    def showEvent(self, event):
        super().showEvent(event)
        QTimer.singleShot(0, self._init_pill)
        if getattr(self, '_broccoli_inwindow_glass', None) is None and inwindow_glass_available():
            QTimer.singleShot(0, self._attach_liquid_glass)

    # ── liquid glass (InWindowLiquidGlass): glass bar; the pill + labels are drawn into it ──
    def _attach_liquid_glass(self):
        if getattr(self, '_broccoli_inwindow_glass', None) is None and self.isVisible():
            attach_inwindow_liquid_glass(self, lambda w=self: w.height() / 2.0, lambda w=self: w._theme == 'dark')

    def _on_inwindow_glass_changed(self, active: bool):
        effect = self.graphicsEffect()
        if effect is not None:
            effect.setEnabled(not active)   # the glass brings its own shadow
        self._apply_button_styles()

    def _init_pill(self):
        r = self._pill_rect_for(self._current)
        if r.isValid():
            self._pill_rect = r
            self.update()

    # ── 切换 Tab ──────────────────────────────────────────
    def select(self, index):
        if index == self._current:
            return
        self._current = index
        self._apply_button_styles()
        target = self._pill_rect_for(index)
        if target.isValid():
            self._anim_start = QRect(self._pill_rect) if self._pill_rect.isValid() else target
            self._anim_end = target
            self._anim_progress = 0.0
            self._anim_timer.start()
        self.tab_changed.emit(index)

    # ── 绘制 ─────────────────────────────────────────────
    def _paint_glass_foreground(self, painter, palette):
        dark = self._theme == 'dark'
        if self._buttons:
            painter.setPen(QPen(palette['separator'], 1))
            for i in range(1, len(self._buttons)):
                if i == self._current or i == self._current + 1:
                    continue
                x = self._buttons[i].x()
                painter.drawLine(x, 9, x, self.height() - 9)
        if self._pill_rect.isValid():
            pill_rr = self._pill_rect.height() / 2.0
            painter.setPen(Qt.PenStyle.NoPen)
            painter.setBrush(QBrush(QColor(255, 255, 255, 46) if dark else QColor(0, 0, 0, 30)))
            painter.drawRoundedRect(self._pill_rect, pill_rr, pill_rr)
        for i, btn in enumerate(self._buttons):
            font = QFont(btn.font())
            font.setPixelSize(13)
            font.setWeight(QFont.Weight.DemiBold if i == self._current else QFont.Weight.Normal)
            painter.setFont(font)
            painter.setPen(QColor(palette['active_text'] if i == self._current else palette['inactive_text']))
            painter.drawText(btn.geometry(), Qt.AlignmentFlag.AlignCenter, btn.text())

    def paintEvent(self, event):
        if getattr(self, '_liquid_glass_active', False):
            if not getattr(self, '_glass_foreground_pass', False):
                return   # pill + labels live in the glass
            painter = QPainter(self)
            painter.setRenderHint(QPainter.RenderHint.Antialiasing)
            painter.setRenderHint(QPainter.RenderHint.TextAntialiasing)
            self._paint_glass_foreground(painter, self._theme_palette())
            painter.end()
            return
        painter = QPainter(self)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)
        palette = self._theme_palette()

        outer_r = self.height() / 2.0

        # 1. Bar 本体
        painter.setBrush(QBrush(QColor(palette['bar_bg'])))
        painter.setPen(Qt.PenStyle.NoPen)
        painter.drawRoundedRect(QRect(0, 0, self.width(), self.height()), outer_r, outer_r)

        # 2. 竖线分隔符（先于 pill 绘制，pill 会覆盖相邻分隔符）
        if self._buttons:
            sep_pen = QPen(palette['separator'])
            sep_pen.setWidth(1)
            painter.setPen(sep_pen)
            for i in range(1, len(self._buttons)):
                # suppress separators on both sides of the selected pill
                if i == self._current or i == self._current + 1:
                    continue
                x = self._buttons[i].x()
                painter.drawLine(x, 9, x, self.height() - 9)

        # 3. 选中的深灰药丸（后于分隔符绘制 → 覆盖紧邻的竖线）
        if self._pill_rect.isValid():
            pill_rr = self._pill_rect.height() / 2.0
            painter.setPen(Qt.PenStyle.NoPen)
            painter.setBrush(QBrush(QColor(palette['pill_bg'])))
            painter.drawRoundedRect(self._pill_rect, pill_rr, pill_rr)

        painter.end()


class MainWindowChromeButton(QPushButton):
    """Round side button for the main pin strip."""
    def __init__(self, text='', parent=None, diameter: int = 36):
        super().__init__('', parent)
        self._force_dark = False
        self._diameter = max(10, int(diameter))
        self._theme_applying = False
        self.setFixedSize(self._diameter, self._diameter)
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.setFocusPolicy(Qt.FocusPolicy.NoFocus)
        self._apply_theme()

    def set_diameter(self, diameter: int):
        self._diameter = max(10, int(diameter))
        self.setFixedSize(self._diameter, self._diameter)
        self._apply_theme()

    def set_force_dark(self, force_dark: bool):
        force_dark = bool(force_dark)
        if self._force_dark == force_dark:
            return
        self._force_dark = force_dark
        self._apply_theme()

    def _apply_theme(self):
        if getattr(self, '_theme_applying', False):
            return
        self._theme_applying = True
        try:
            self._apply_theme_style()
        finally:
            self._theme_applying = False

    def _apply_theme_style(self):
        accent = QColor(get_accent_color_hex())
        if not accent.isValid():
            accent = QColor('#0A84FF')
        bg = accent.name()
        hover = accent.darker(112).name()
        pressed = accent.darker(128).name()
        checked_bg = accent.darker(145).name()
        checked_hover = accent.darker(158).name()
        self.setStyleSheet(f"""
            QPushButton {{
                background: {bg};
                color: transparent;
                border: 1px outset grey;
                border-radius: {self._diameter // 2}px;
                font-size: {max(8, min(15, self._diameter - 2))}px;
                font-weight: 600;
                padding: 0;
            }}
            QPushButton:hover {{
                background: {hover};
            }}
            QPushButton:pressed {{
                background: {pressed};
            }}
            QPushButton:checked {{
                background: {checked_bg};
                color: white;
            }}
            QPushButton:checked:hover {{
                background: {checked_hover};
            }}
        """)

    def changeEvent(self, event):
        super().changeEvent(event)
        if getattr(self, '_theme_applying', False):
            return
        if event.type() in (QEvent.Type.PaletteChange, QEvent.Type.ApplicationPaletteChange):
            self._apply_theme()


def _pill_lerp_rect(r1, r2, t):
    """FIX-36: shared rect interpolation for the pill-bar highlight animations
    (WebNavBar / TerminalSessionBar / EditorFileBar) — same math as PillNavBar."""
    def li(a, b):
        return int(round(a + (b - a) * t))
    return QRect(li(r1.x(), r2.x()), li(r1.y(), r2.y()),
                 li(r1.width(), r2.width()), li(r1.height(), r2.height()))


class NavSitePill(QWidget):
    """
    URL 导航条目。
    - 激活态：长条 pill，透明背景（WebNavBar 绘制高亮），显示 favicon + URL 文字。
    - 非激活态：圆形，仅显示 favicon/字母。
    - 编辑模式：QLineEdit 叠加在 pill 上，Enter 提交，Escape 取消。
    - 右键：删除菜单；双击激活态 pill：进入编辑模式。
    """
    clicked_sig       = pyqtSignal()
    delete_requested  = pyqtSignal()
    refresh_requested = pyqtSignal()
    back_requested    = pyqtSignal()
    forward_requested = pyqtSignal()
    home_requested    = pyqtSignal()      # navigate back to this pill's root URL
    move_left_requested = pyqtSignal()
    move_right_requested = pyqtSignal()
    url_submitted     = pyqtSignal(str)   # 编辑完成后提交 url
    hover_entered     = pyqtSignal()
    hover_left        = pyqtSignal()

    CIRCLE_SIZE = 34
    HEIGHT      = 34

    def __init__(self, url='', label='', active=False, edit_on_show=False, parent=None):
        super().__init__(parent)
        self._url          = url
        self._label        = label or (self._domain(url) if url else '')
        self._icon         = None
        self._active       = active
        self._edit_on_show = edit_on_show
        w = 190 if active else self.CIRCLE_SIZE
        self._cur_w        = w
        self.setFixedSize(w, self.HEIGHT)
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground)

        # 动画 timer
        self._timer = QTimer(self)
        self._timer.setInterval(14)
        self._timer.timeout.connect(self._tick)
        self._t0 = w; self._t1 = w; self._prog = 1.0
        # FIX-36: position animates on the SAME clock/progress as width
        self._x0 = 0; self._x1 = 0; self._y = 0
        self._has_pos = False

        # 编辑 QLineEdit（隐藏叠加）
        self._le = QLineEdit(self)
        self._le.setVisible(False)
        self._apply_theme()
        self._le.returnPressed.connect(self._submit)
        self._le.installEventFilter(self)

    def _apply_theme(self):
        dark = is_dark_theme(app)
        self._le.setStyleSheet(
            f"QLineEdit {{ border: none; background: transparent;"
            f" color: {'#F2F2F7' if dark else '#222222'}; font-size: 12px; padding: 0; }}"
        )

    @staticmethod
    def _domain(url):
        try:
            from urllib.parse import urlparse
            return urlparse(url).netloc or url
        except Exception:
            return url

    def showEvent(self, event):
        super().showEvent(event)
        if self._edit_on_show:
            self._edit_on_show = False
            QTimer.singleShot(50, self.enter_edit_mode)
        if getattr(self, '_broccoli_inwindow_glass', None) is None:
            # Only a compact (circle) site pill is a glass disc; the expanded one (URL text)
            # and the inline editor are painted into the bar's glass as before.
            install_inwindow_circle_glass(
                self, lambda w: QRect((w.CIRCLE_SIZE - 26) // 2, (w.HEIGHT - 26) // 2, 26, 26),
                wanted_for=lambda w: not w._active and not w._le.isVisible() and w._cur_w <= w.CIRCLE_SIZE + 2,
                dark_for=lambda w: is_dark_theme(app))

    def set_icon(self, pixmap):
        self._icon = pixmap
        self.update()

    def set_label(self, text):
        self._label = self._domain(text) if '://' in text else text
        self.update()

    # ── 动画 ────────────────────────────────────────────────
    def expand(self):
        self._active = True
        bar = self.parentWidget()
        if bar is not None and hasattr(bar, '_relayout_pills'):
            bar._relayout_pills(animated=True)
        else:
            self._animate(self._target_pill_w())

    def collapse(self):
        self._active = False
        self._le.setVisible(False)
        bar = self.parentWidget()
        if bar is not None and hasattr(bar, '_relayout_pills'):
            bar._relayout_pills(animated=True)
        else:
            self._animate(self.CIRCLE_SIZE)

    def _target_pill_w(self):
        """激活 pill 宽度：尽量撑满 bar 内的剩余空间。"""
        bar = self.parentWidget()
        if bar is None:
            return 190
        n_inactive = max(0, len(bar._pills) - 1) if hasattr(bar, '_pills') else 0
        used = (n_inactive * (self.CIRCLE_SIZE + 6)
                + bar._hbox.contentsMargins().left()
                + bar._hbox.contentsMargins().right()
                + self.CIRCLE_SIZE + 6   # "+" button + spacing
                + 6 * 2)                 # pill's own spacing
        return max(150, bar.width() - used)

    def sync_active_width(self, animated: bool = False):
        if not self._active:
            return
        bar = self.parentWidget()
        if bar is not None and hasattr(bar, '_relayout_pills'):
            bar._relayout_pills(animated=animated)
            return
        target = self._target_pill_w()
        self.set_target_width(target, animated=animated)

    def set_target_width(self, target: int, animated: bool = False):
        target = max(self.CIRCLE_SIZE, int(target or self.CIRCLE_SIZE))
        if animated:
            self._animate(target)
            return
        self._timer.stop()
        self._cur_w = target
        self._t0 = target
        self._t1 = target
        self._prog = 1.0
        self._x0 = self._x1 = self.x()
        self.setFixedWidth(self._cur_w)
        if self._le.isVisible():
            self._le.setGeometry(self.CIRCLE_SIZE + 4, 2,
                                 self._cur_w - self.CIRCLE_SIZE - 8, self.HEIGHT - 4)
        parent = self.parentWidget()
        if parent is not None:
            parent.update()

    def set_target_geometry(self, x, y, target_w, animated=False):
        """FIX-36: apply the bar-computed slot with position and width on ONE
        animation clock (shared _prog/easing), so pills glide to their slot
        instead of teleporting while only the width eases behind."""
        x = int(x)
        y = int(y)
        target_w = max(self.CIRCLE_SIZE, int(target_w or self.CIRCLE_SIZE))
        self._y = y
        if not animated or not self._has_pos:
            first_layout = not self._has_pos
            self._has_pos = True
            self._x0 = self._x1 = x
            self.move(x, y)
            if animated and first_layout and self._cur_w != target_w:
                # first layout of a NEW pill: position snaps into its slot (no
                # (0,0) fly-in) but the WIDTH keeps the pre-FIX36 grow ease
                self._t0 = self._cur_w
                self._t1 = target_w
                self._prog = 0.0
                self._timer.start()
                return
            self._timer.stop()
            self._prog = 1.0
            self._cur_w = target_w
            self._t0 = self._t1 = target_w
            self.setFixedWidth(target_w)
            if self._le.isVisible():
                self._le.setGeometry(self.CIRCLE_SIZE + 4, 2,
                                     self._cur_w - self.CIRCLE_SIZE - 8, self.HEIGHT - 4)
            parent = self.parentWidget()
            if parent is not None:
                parent.update()
            return
        if self._timer.isActive() and self._x1 == x and self._t1 == target_w:
            return  # same targets — let the running animation finish (never restart-stall)
        if not self._timer.isActive() and self._cur_w == target_w and self.x() == x and self.y() == y:
            return  # already at rest on target
        # Retarget: rebase to CURRENT values (value-continuous) and run a fresh ease.
        self._x0 = self.x()
        self._t0 = self._cur_w
        self._x1 = x
        self._t1 = target_w
        self._prog = 0.0
        self._timer.start()

    def _animate(self, target):
        target = max(self.CIRCLE_SIZE, int(target or self.CIRCLE_SIZE))
        self._t0 = self._cur_w; self._t1 = target
        self._x0 = self._x1 = self.x()   # width-only path keeps position still
        self._prog = 0.0
        self._timer.start()

    def _tick(self):
        self._prog = min(1.0, self._prog + 0.08)
        t = 1.0 - (1.0 - self._prog) ** 3
        self._cur_w = int(self._t0 + (self._t1 - self._t0) * t)
        self.setFixedWidth(max(self.CIRCLE_SIZE, self._cur_w))
        if self._has_pos and self._x0 != self._x1:
            self.move(int(round(self._x0 + (self._x1 - self._x0) * t)), self._y)
        if self._le.isVisible():
            edit_w = max(0, self._cur_w - self.CIRCLE_SIZE - 8)
            self._le.setGeometry(self.CIRCLE_SIZE + 4, 2, edit_w, self.HEIGHT - 4)
        p = self.parentWidget()
        if p:
            p.update()   # 让 WebNavBar 重绘高亮
        if self._prog >= 1.0:
            self._timer.stop()

    # ── 编辑模式 ─────────────────────────────────────────────
    def enter_edit_mode(self):
        if not self._active:
            return
        self._le.setText(self._url)
        edit_w = max(0, self._cur_w - self.CIRCLE_SIZE - 8)
        self._le.setGeometry(self.CIRCLE_SIZE + 4, 2, edit_w, self.HEIGHT - 4)
        self._le.setVisible(True)
        self._le.selectAll()
        self._le.setFocus()
        self.update()

    def _submit(self):
        url = self._le.text().strip()
        self._le.setVisible(False)
        if url:
            if not url.startswith('http'):
                url = 'https://' + url
            self._url   = url
            self._label = self._domain(url)
            self.update()
            self.url_submitted.emit(url)

    def eventFilter(self, obj, event):
        if obj is self._le and event.type() == event.Type.KeyPress:
            from PyQt6.QtCore import Qt as _Qt
            if event.key() == _Qt.Key.Key_Escape:
                self._le.setVisible(False)
                if not self._url:           # 空 placeholder → 请求删除
                    self.delete_requested.emit()
                return True
        return super().eventFilter(obj, event)

    # ── 鼠标事件 ─────────────────────────────────────────────
    def mousePressEvent(self, event):
        if event.button() == Qt.MouseButton.LeftButton:
            self.clicked_sig.emit()

    def mouseDoubleClickEvent(self, event):
        if event.button() == Qt.MouseButton.LeftButton and self._active:
            self.enter_edit_mode()

    def enterEvent(self, event):
        self.hover_entered.emit()
        super().enterEvent(event)

    def leaveEvent(self, event):
        self.hover_left.emit()
        super().leaveEvent(event)

    def contextMenuEvent(self, event):
        from PyQt6.QtWidgets import QMenu
        menu = style_broccoli_context_menu(QMenu(self))
        back_act    = menu.addAction(_tr('← Back'))
        fwd_act     = menu.addAction(_tr('→ Forward'))
        menu.addSeparator()
        move_left_act = menu.addAction(_tr('Move Left'))
        move_right_act = menu.addAction(_tr('Move Right'))
        menu.addSeparator()
        home_act    = menu.addAction(_tr('Home'))
        ref_act     = menu.addAction(_tr('Refresh'))
        menu.addSeparator()
        del_act     = menu.addAction(_tr('Delete'))
        act = menu.exec(event.globalPos())
        if act == back_act:
            self.back_requested.emit()
        elif act == fwd_act:
            self.forward_requested.emit()
        elif act == move_left_act:
            self.move_left_requested.emit()
        elif act == move_right_act:
            self.move_right_requested.emit()
        elif act == home_act:
            self.home_requested.emit()
        elif act == ref_act:
            self.refresh_requested.emit()
        elif act == del_act:
            self.delete_requested.emit()

    # ── 绘制（透明背景，WebNavBar 负责绘高亮）────────────────
    def paintEvent(self, event):
        if self._le.isVisible():
            return   # 编辑模式：lineedit 覆盖，不用绘制文字
        painter = QPainter(self)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)
        dark = is_dark_theme(app)
        bar = self.parentWidget()
        expanded_by_bar = False
        if bar is not None and hasattr(bar, '_expanded_index') and hasattr(bar, '_pills'):
            try:
                expanded_by_bar = 0 <= bar._expanded_index < len(bar._pills) and bar._pills[bar._expanded_index] is self
            except Exception:
                expanded_by_bar = False
        expanded = self._active or expanded_by_bar

        icon_size = 20
        icon_y    = (self.HEIGHT - icon_size) // 2
        bg_size = 26
        bg_x = (self.CIRCLE_SIZE - bg_size) / 2.0
        bg_y = (self.HEIGHT - bg_size) / 2.0
        circle_bg = QColor('#3A3A3A' if dark else '#FFFFFF')
        circle_rect = QRectF(bg_x, bg_y, bg_size, bg_size)
        if not getattr(self, '_liquid_glass_active', False):   # glass disc behind the favicon
            painter.setBrush(QBrush(circle_bg))
            painter.setPen(Qt.PenStyle.NoPen)
            painter.drawEllipse(circle_rect)

        if self._icon and not self._icon.isNull():
            # FIX-36: ALWAYS left-anchored in the circle box. Centering in the
            # animated _cur_w painted the old icon at ~half of a still-wide pill
            # the moment it lost active state ("jumps right of the new icon").
            # For compact pills (_cur_w == CIRCLE_SIZE) this is the same value.
            icon_x = (self.CIRCLE_SIZE - icon_size) // 2
            # Clip to a circle so all icons appear round regardless of source shape.
            from PyQt6.QtGui import QPainterPath
            clip = QPainterPath()
            clip.addEllipse(icon_x, icon_y, icon_size, icon_size)
            painter.setClipPath(clip)
            # Let Qt scale from the full-resolution source at draw time;
            # pre-scaling with .scaled() discards pixels before they reach the GPU.
            painter.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform)
            painter.drawPixmap(QRect(icon_x, icon_y, icon_size, icon_size), self._icon)
            painter.setClipping(False)
        else:
            painter.setPen(QPen(QColor('#D0D0D4' if dark else '#555555')))
            f = painter.font(); f.setPixelSize(13); f.setBold(True)
            painter.setFont(f)
            # FIX-36: same left-anchor rule as the icon branch (was centered in the
            # animated width for non-active pills — identical mid-shrink artifact).
            box_w = self.CIRCLE_SIZE
            painter.drawText(QRect(0, 0, box_w, self.HEIGHT),
                             Qt.AlignmentFlag.AlignCenter,
                             self._label[0].upper() if self._label else '+')

        if expanded and self._cur_w > self.CIRCLE_SIZE + 20:
            fade_range = max(1, self._cur_w - self.CIRCLE_SIZE - 20)
            alpha = min(255, int(fade_range / 60 * 255))
            tc = QColor('#F2F2F7' if dark else '#333333'); tc.setAlpha(alpha)
            painter.setPen(QPen(tc))
            f2 = painter.font(); f2.setPixelSize(12); f2.setBold(False)
            painter.setFont(f2)
            text_x = self.CIRCLE_SIZE + 4
            text_w = max(0, self._cur_w - text_x - 6)
            if text_w <= 0:
                painter.end()
                return
            elided = painter.fontMetrics().elidedText(
                self._label,
                Qt.TextElideMode.ElideMiddle,
                text_w,
            )
            painter.drawText(QRect(text_x, 0, text_w, self.HEIGHT),
                             Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft,
                             elided)
        painter.end()


# JS run after page load to find the highest-resolution icon link declared in <head>.
# Returns the absolute URL string, or '' if nothing useful is found.
_ICON_JS = (
    "(function(){"
    "  var found = [];"
    "  document.querySelectorAll('link[rel]').forEach(function(l){"
    "    var rel = (l.getAttribute('rel')||'').toLowerCase();"
    "    if (!rel.includes('icon')) return;"
    "    var href = l.href;"
    "    if (!href || href === window.location.href) return;"
    # apple-touch-icon always scores ≥ 180 even when the sizes attr is absent
    "    var isTouch = rel.includes('apple-touch-icon');"
    "    var sz = isTouch ? 180 : 0;"
    "    var s = l.getAttribute('sizes');"
    "    if (s) { var p = s.split('x'); var n = parseInt(p[0])||0; if (n > sz) sz = n; }"
    "    found.push([sz, href]);"
    "  });"
    "  found.sort(function(a,b){ return b[0]-a[0]; });"
    "  return found.length ? found[0][1] : '';"
    "})()"
)

