class ICloudShortcutsProtocol:
    """Filesystem recipe model for iOS Shortcuts; it never assumes push/background execution."""

    def __init__(self,
                 *,
                 cloud_root: str,
                 source_device_id: str = 'iphone-shortcut',
                 materializer: ICloudFileMaterializer | None = None):
        self.backend = CloudTreeBackend(cloud_root, materializer)
        self.source_device_id = _cloud_file_component(source_device_id, 'shortcut-device')

    def list_conversations(self, user_id: str) -> list[dict]:
        directory = Path(self.backend.path('control', 'conversation-index', _cloud_file_component(user_id, 'user')))
        deduped = {}
        for path in sorted(directory.glob('*.json')) if directory.exists() else []:
            item = self.backend.read_json(str(path), timeout=0.5)
            if not verify_cloud_payload(item) or str(item.get('record_type', '') or '') != 'ConversationIndexEntry':
                continue
            conversation_id = str(item.get('conversation_id', '') or '')
            current = deduped.get(conversation_id)
            key = (int(item.get('route_epoch', 0) or 0), int(item.get('revision', 0) or 0), str(item.get('updated_at', '') or ''))
            old_key = (
                int((current or {}).get('route_epoch', 0) or 0), int((current or {}).get('revision', 0) or 0),
                str((current or {}).get('updated_at', '') or ''),
            )
            if conversation_id and (current is None or key >= old_key):
                deduped[conversation_id] = item
        return sorted(deduped.values(), key=lambda item: str(item.get('updated_at', '') or ''), reverse=True)

    def _publish_assets(self, request: dict, attachment_paths: list[str]) -> list[dict]:
        manifest = []
        directory = self.backend.path(
            'canonical',
            _cloud_file_component(request.get('owner_user_id', ''), 'owner'),
            _cloud_file_component(request.get('owner_device_id', ''), 'device'),
            _cloud_file_component(request.get('origin_user_id', ''), 'origin'),
            _cloud_file_component(request.get('conversation_id', ''), 'conversation'),
            'assets',
        )
        for source_path in attachment_paths:
            source_path = os.path.abspath(os.path.expanduser(str(source_path or '')))
            digest = hashlib.sha256(Path(source_path).read_bytes()).hexdigest()
            self.backend.publish_file(directory, digest, source_path, expected_hash=digest)
            manifest.append({
                'asset_id': digest,
                'sha256': digest,
                'name': os.path.basename(source_path),
                'size': os.path.getsize(source_path),
                'cloud_path': str(Path('canonical') / _cloud_file_component(request.get('owner_user_id', ''), 'owner') /
                                  _cloud_file_component(request.get('owner_device_id', ''), 'device') /
                                  _cloud_file_component(request.get('origin_user_id', ''), 'origin') /
                                  _cloud_file_component(request.get('conversation_id', ''), 'conversation') / 'assets' / digest),
            })
        return manifest

    def submit_question(self,
                        question: str,
                        *,
                        executor_id: str,
                        user_id: str,
                        member_id: str,
                        logical_agent_id: str = 'main-agent',
                        conversation: dict | None = None,
                        attachment_paths: list[str] | None = None,
                        notes_writer_id: str = '',
                        notes_account_name: str = 'iCloud') -> dict:
        question = str(question or '')
        if not question and not attachment_paths:
            raise ValueError('Shortcut question or attachment is required.')
        self.backend.ensure_layout()
        executor_id = _cloud_file_component(executor_id, 'executor')
        conversation = dict(conversation or {})
        continuing = bool(conversation.get('conversation_id') or conversation.get('id'))
        conversation_id = str(conversation.get('conversation_id', '') or conversation.get('id', '') or new_broccoli_uuid('conversation-'))
        owner_device_id = str(conversation.get('owner_device_id', '') or executor_id)
        owner_user_id = str(conversation.get('owner_user_id', '') or user_id)
        origin_user_id = str(conversation.get('origin_user_id', '') or user_id)
        now = datetime.datetime.now().isoformat(timespec='milliseconds')
        task_id = new_broccoli_uuid('task-')
        attempt_id = new_broccoli_uuid('attempt-')
        producer_seq = datetime.datetime.now().strftime('%Y%m%d-%H%M%S') + '-' + new_broccoli_uuid('shortcut-')
        request = {
            'schema_version': ICLOUD_PROTOCOL_VERSION,
            'record_type': 'TaskRequest',
            'task_kind': 'continue_conversation' if continuing else 'new_conversation',
            'task_id': task_id,
            'attempt_id': attempt_id,
            'turn_id': new_broccoli_uuid('turn-'),
            'conversation_id': conversation_id,
            'conversation_title': str(conversation.get('title', '') or question[:80]),
            'space_id': '',
            'project_workspace_id': '',
            'user_id': str(user_id or ''),
            'member_id': str(member_id or ''),
            'origin_user_id': origin_user_id,
            'source_device_id': self.source_device_id,
            'executor_id': executor_id,
            'owner_device_id': owner_device_id,
            'owner_user_id': owner_user_id,
            'logical_agent_id': str(logical_agent_id or 'main-agent'),
            'agent_profile_id': '',
            'route_epoch': int(conversation.get('route_epoch', 0) or 0),
            'base_revision': int(conversation.get('revision', 0) or 0),
            'question': question,
            'asset_manifest': [],
            'execution_preferences': {'origin_surface': 'ios_shortcut'},
            'required_capabilities': ['chat'],
            'origin_surface': 'ios_shortcut',
            'notes_mirror_requested': True,
            'notes_writer_id': _cloud_file_component(notes_writer_id or executor_id, 'notes-writer'),
            'notes_account_name': str(notes_account_name or 'iCloud'),
            'producer_id': self.source_device_id,
            'producer_seq': producer_seq,
            'created_at': now,
        }
        request['asset_manifest'] = self._publish_assets(request, list(attachment_paths or []))
        sealed = seal_cloud_payload(request)
        filename = '{}-{}-TaskRequest.json'.format(self.source_device_id, _cloud_file_component(producer_seq, 'seq'))
        destination = self.backend.publish_json(self.backend.path('control', 'inbox', executor_id), filename, sealed)
        return {'request': sealed, 'destination': destination, 'status': 'submitted'}

    def read_status(self, request: dict) -> dict:
        request = dict(request or {})
        directory = Path(self.backend.path(
            'canonical',
            _cloud_file_component(request.get('owner_user_id', ''), 'owner'),
            _cloud_file_component(request.get('owner_device_id', ''), 'device'),
            _cloud_file_component(request.get('origin_user_id', ''), 'origin'),
            _cloud_file_component(request.get('conversation_id', ''), 'conversation'),
        ))
        events = []
        for path in sorted((directory / 'events').glob('*.json')) if (directory / 'events').exists() else []:
            item = self.backend.read_json(str(path), timeout=0.5)
            if verify_cloud_payload(item) and str(item.get('task_id', '') or '') == str(request.get('task_id', '') or ''):
                events.append(item)
        formal = [item for item in events if str(item.get('event_type', '') or '') != 'notes_mirror_state']
        revisions = []
        for path in sorted((directory / 'revisions').glob('*.json')) if (directory / 'revisions').exists() else []:
            item = self.backend.read_json(str(path), timeout=0.5)
            extensions = item.get('extensions') if isinstance((item or {}).get('extensions'), dict) else {}
            if verify_cloud_payload(item) and str(extensions.get('remote_task_id', '') or '') == str(request.get('task_id', '') or ''):
                revisions.append(item)
        if formal or revisions:
            terminal = next((item for item in reversed(formal) if item.get('event_type') == 'attempt_terminal'), formal[-1] if formal else {})
            result = max(revisions, key=lambda item: (int(item.get('route_epoch', 0) or 0), int(item.get('revision', 0) or 0))) if revisions else {}
            return {
                'source': 'task_events_result',
                'state': str(terminal.get('state', '') or (result.get('extensions') or {}).get('remote_status', '') or 'executing'),
                'result': result,
                'events': formal,
            }
        index = next((item for item in self.list_conversations(str(request.get('owner_user_id', '') or request.get('user_id', '') or ''))
                      if str(item.get('conversation_id', '') or '') == str(request.get('conversation_id', '') or '')), None)
        if isinstance(index, dict):
            return {'source': 'conversation_index', 'state': str(index.get('state', '') or 'known'), 'conversation': index}
        notes = [item for item in events if str(item.get('event_type', '') or '') == 'notes_mirror_state']
        if notes:
            return {'source': 'notes', 'state': str(notes[-1].get('notes_state', '') or ''), 'notes': notes[-1]}
        return {'source': 'pending', 'state': 'pending', 'notes_missing': True}


def selection_text_to_apple_notes_html(text: str) -> str:
    """纯文本 → Notes body HTML 片段：每行一个 div，空行 <div><br></div>。
    selection_markdown_to_apple_notes_html 渲染失败时的兜底。"""
    lines = str(text or '').replace('\r\n', '\n').replace('\r', '\n').split('\n')
    parts = []
    for line in lines:
        if line.strip():
            parts.append(f'<div>{html.escape(line)}</div>')
        else:
            parts.append('<div><br></div>')
    return ''.join(parts)


def selection_markdown_to_apple_notes_html(text: str) -> str:
    """渲染后的选区纯文本 → Notes body HTML（兜底路径，找不回 markdown 原文时用）。
    extras 照搬 Watermelon 的 markdown_to_html；额外加 break-on-newline，因为
    渲染后的文本里单个换行有意义，不能被 markdown 段落规则合并掉。"""
    text = str(text or '').replace('\r\n', '\n').replace('\r', '\n')
    if not text.strip():
        return '<div><br></div>'
    try:
        rendered = markdown2.markdown(
            text,
            extras=[
                'fenced-code-blocks',
                'tables',
                'strike',
                'task_list',
                'cuddled-lists',
                'code-friendly',
                'break-on-newline',
            ],
        )
        rendered = str(rendered or '').strip()
        if rendered:
            return rendered
    except Exception:
        pass
    return selection_text_to_apple_notes_html(text)


def markdown_source_to_apple_notes_html(source_md: str) -> str:
    """对话记录里的 markdown 原文片段 → Notes body HTML（主路径）。
    extras 与 Watermelon 的 markdown_to_html 一致；不加 break-on-newline——
    这是真 markdown 源，换行语义要与 Broccoli 正文渲染保持一致。"""
    source_md = str(source_md or '').strip('\n')
    if not source_md.strip():
        return ''
    try:
        rendered = markdown2.markdown(
            source_md,
            extras=[
                'fenced-code-blocks',
                'tables',
                'strike',
                'task_list',
                'cuddled-lists',
                'code-friendly',
            ],
        )
        return str(rendered or '').strip()
    except Exception:
        return ''


# ── 选区 → Notes 的三层内容管线 ─────────────────────────────────────
# 第 1 层：DOM 选区 HTML（页面端 cloneContents，所见即所得）+ 白名单清洗；
# 第 2 层：LLM 仅格式重排 + 内容不变性机器校验；
# 第 3 层：纯文本。
_APPLE_NOTES_ALLOWED_TAGS = {
    'p', 'div', 'br', 'strong', 'b', 'em', 'i', 'u', 's', 'del', 'code', 'pre',
    'ul', 'ol', 'li', 'table', 'thead', 'tbody', 'tr', 'th', 'td',
    'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'blockquote', 'a', 'sup', 'sub',
}
APPLE_NOTES_LLM_REFORMAT_MAX_CHARS = 8000


def sanitize_selection_html_for_apple_notes(raw_html: str) -> tuple[str, bool]:
    """real2 选区 HTML → Notes 可用 HTML。白名单过滤：保留基础格式标签、
    其余解包保内容；属性全部剥离（a 只留 href）；MathJax 的展示 DOM 删除，
    用它自带的 math/tex 源还原成 $…$ 文本。返回 (清洗后HTML, 是否还原过公式)。"""
    raw_html = str(raw_html or '').strip()
    if not raw_html:
        return '', False
    soup = BeautifulSoup(raw_html, 'html.parser')
    had_math = False
    for node in list(soup.find_all('script')):
        if getattr(node, 'decomposed', False):
            continue
        node_type = str(node.get('type', '') or '')
        if 'math/tex' in node_type:
            had_math = True
            tex = str(node.string or '').strip()
            if tex:
                node.replace_with(f'$$ {tex} $$' if 'mode=display' in node_type else f'$ {tex} $')
            else:
                node.decompose()
        else:
            node.decompose()
    for node in list(soup.find_all('style')):
        if not getattr(node, 'decomposed', False):
            node.decompose()
    for node in list(soup.find_all(True)):
        if getattr(node, 'decomposed', False):
            continue
        class_attr = ' '.join(node.get('class') or [])
        if 'MathJax' in class_attr:
            had_math = True
            node.decompose()
    for node in list(soup.find_all(True)):
        if getattr(node, 'decomposed', False):
            continue
        name = str(node.name or '').lower()
        if name in _APPLE_NOTES_ALLOWED_TAGS:
            href = node.get('href') if name == 'a' else None
            node.attrs = {}
            if href:
                node.attrs['href'] = href
        else:
            node.unwrap()
    return str(soup).strip(), had_math


def _selection_html_text_matches(cleaned_html: str, selected_text: str) -> bool:
    """清洗后 HTML 的纯文本 == 选区文本（忽略空白）——防清洗器缺陷的机器校验。"""
    try:
        html_text = BeautifulSoup(cleaned_html, 'html.parser').get_text()
    except Exception:
        return False
    normalize = lambda value: re.sub(r'\s+', '', str(value or ''))
    return normalize(html_text) == normalize(selected_text)


def _markdown_content_signature(value: str) -> str:
    """剥掉全部 markdown 格式字符后的内容签名——校验 LLM 重排"只改格式、
    不改内容"。签名不一致即弃用 LLM 结果。"""
    text = str(value or '')
    text = re.sub(r'^\s*```[^\n]*$', '', text, flags=re.MULTILINE)
    text = re.sub(r'^\s{0,3}#{1,6}\s+', '', text, flags=re.MULTILINE)
    text = re.sub(r'^\s*(?:[-*+]|\d{1,3}[.)])\s+', '', text, flags=re.MULTILINE)
    text = re.sub(r'^\s*>\s?', '', text, flags=re.MULTILINE)
    text = re.sub(r'\[([^\]]*)\]\([^)]*\)', r'\1', text)
    for mark in ('**', '__', '~~', '`', '*', '_', '|', '~'):
        text = text.replace(mark, '')
    return re.sub(r'\s+', '', text)


def llm_reformat_selection_to_markdown(selected_text: str) -> str:
    """第 2 层：LLM 仅格式重排（prompt 思路复用外部答案后处理的"确定性
    Markdown 格式过滤器"）。输出剥掉格式字符后与原文不一致 → 返回 ''。
    网络调用，只在后台线程使用。"""
    selected_text = str(selected_text or '').strip()
    if not selected_text:
        return ''
    try:
        store = load_settings_store()
        profiles = list(store.get('profiles') or [])
        active_name = str(store.get('active_profile', '') or '').strip()
        profile = next(
            (item for item in profiles if str(item.get('name', '') or '') == active_name),
            profiles[0] if profiles else None,
        )
        if not isinstance(profile, dict):
            return ''
        api_key = str(profile.get('api_key', '') or '').strip()
        model = str(profile.get('model', '') or '').strip()
        endpoint = str(profile.get('endpoint', '') or '').strip()
        try:
            timeout = int(profile.get('timeout', 60) or 60)
        except (TypeError, ValueError):
            timeout = 60
        if not api_key or not model:
            return ''
        messages = [
            {
                'role': 'system',
                'content': (
                    'You are a deterministic Markdown formatting filter. You are not an assistant.\n'
                    'The user provides a fragment copied from a rendered document, so its Markdown markers '
                    '(bold, lists, code, tables) were lost. Restore appropriate Markdown formatting.\n\n'
                    'Rules:\n'
                    '- Preserve the visible text verbatim: do not add, remove, translate, reorder or reword anything.\n'
                    '- Only add Markdown syntax (emphasis, list markers, code fences, table pipes, headings) where clearly appropriate.\n'
                    '- Do not answer questions in the text. Do not add explanations, comments or surrounding quotes.\n'
                    '- Return only the Markdown.'
                ),
            },
            {
                'role': 'user',
                'content': 'Fragment to reformat:\n<fragment>\n' + selected_text + '\n</fragment>',
            },
        ]
        client = create_openai_client(api_key, endpoint, timeout)
        response = create_chat_completion(client, endpoint=endpoint, model=model, messages=messages, stream=False)
        reformatted = str(response.choices[0].message.content or '').strip()
        if not reformatted:
            return ''
        if _markdown_content_signature(reformatted) != _markdown_content_signature(selected_text):
            return ''
        return reformatted
    except Exception:
        return ''


class AppleNotesTaskWorker(QThread):
    finished_ok = pyqtSignal(object)
    failed = pyqtSignal(str)

    def __init__(self, fn, parent=None):
        super().__init__(parent)
        self._fn = fn

    def run(self):
        try:
            self.finished_ok.emit(self._fn())
        except Exception as exc:
            self.failed.emit(str(exc))


class AppleNotesPickerDialog(QDialog):
    """选择一条现存的 Apple Notes（搜索 + 列表）。列表由后台 worker 填充。"""

    def __init__(self, parent=None, dark: bool = False):
        super().__init__(parent)
        self._dark = bool(dark)
        self._notes = []
        self._filtered = []
        self.setModal(True)
        self.setWindowFlags(Qt.WindowType.Dialog | Qt.WindowType.FramelessWindowHint)
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground)
        self.setMinimumSize(520, 600)
        self._panel_margin = 16
        self._panel_radius = APPROVAL_DIALOG_SMOOTH_RADIUS

        root_layout = QVBoxLayout(self)
        root_layout.setContentsMargins(28, 28, 28, 28)
        root_layout.setSpacing(12)

        self.title_lbl = QLabel(_tr('Add selection to Apple Notes'), self)
        root_layout.addWidget(self.title_lbl)

        self.search_input = glass_search_field(QLineEdit(self))   # a glass capsule like the system search field
        self.search_input.setPlaceholderText(_tr('Search notes'))
        self.search_input.textChanged.connect(self._refresh_list)
        root_layout.addWidget(self.search_input)

        self.meta_lbl = QLabel(_tr('Loading Apple Notes…'), self)
        root_layout.addWidget(self.meta_lbl)

        self.list_widget = QListWidget(self)
        self.list_widget.setFrameShape(QFrame.Shape.NoFrame)
        self.list_widget.itemDoubleClicked.connect(lambda _item: self._accept_if_selected())
        root_layout.addWidget(self.list_widget, 1)

        button_row = QHBoxLayout()
        button_row.setContentsMargins(0, 4, 0, 0)
        button_row.setSpacing(4)
        button_row.addStretch()
        self.cancel_button = MacNormalButton(_tr('Cancel'), self)
        self.cancel_button.clicked.connect(self.reject)
        self.add_button = MacNormalButton(_tr('Add'), self)
        self.add_button.clicked.connect(self._accept_if_selected)
        btn_w = max(self.cancel_button.sizeHint().width(), self.add_button.sizeHint().width())
        self.cancel_button.setFixedWidth(btn_w)
        self.add_button.setFixedWidth(btn_w)
        button_row.addWidget(self.cancel_button)
        button_row.addWidget(self.add_button)
        root_layout.addLayout(button_row)

        self._apply_theme()
        QTimer.singleShot(0, self.search_input.setFocus)

    def paintEvent(self, event):
        painter = QPainter(self)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)
        panel_rect = QRectF(
            self._panel_margin,
            self._panel_margin,
            self.width() - self._panel_margin * 2,
            self.height() - self._panel_margin * 2,
        )
        bg_path = smooth_round_rect_path(panel_rect, self._panel_radius)
        if not getattr(self, '_liquid_glass_active', False):   # 液态玻璃时由系统玻璃当底
            painter.fillPath(bg_path, QColor('#2D2D2D' if self._dark else '#FFFFFF'))
            painter.setPen(QPen(QColor('#3A3A3A' if self._dark else '#ECECEC'), 1))
            painter.drawPath(bg_path)
        painter.end()

    def _apply_theme(self):
        dark = self._dark
        self.title_lbl.setStyleSheet(
            'font-family: "Helvetica Neue", Helvetica, Arial, sans-serif; font-size: 13px; '
            f'font-weight: 600; color: {"#F2F2F7" if dark else "#20242B"};'
        )
        self.search_input.setStyleSheet(_search_input_stylesheet(dark))
        self.meta_lbl.setStyleSheet(
            f'color: {"#A7AEB8" if dark else "#7A8391"}; '
            'font-family: "Helvetica Neue", Helvetica, Arial, sans-serif; font-size: 11px;'
        )
        self.list_widget.setStyleSheet(_input_card_stylesheet(dark))

    def set_notes(self, notes, refreshing: bool = False):
        """refreshing=True 表示当前显示的是缓存，后台仍在刷新最新清单。"""
        self._notes = [note for note in list(notes or []) if isinstance(note, dict)]
        self._refreshing = bool(refreshing)
        self._refresh_failed = False
        self._refresh_list()

    def set_error(self, message: str):
        self.meta_lbl.setText(_tr('Failed to load notes: {msg}').format(msg=str(message or _tr('unknown error'))))

    def set_refresh_failed(self, message: str):
        # 有缓存在显示，仅提示后台刷新失败，不清列表。
        self._refreshing = False
        self._refresh_failed = True
        self._refresh_list()

    def _refresh_list(self):
        query = self.search_input.text().strip().lower()
        self.list_widget.clear()
        self._filtered = []
        for note in self._notes:
            folder = str(note.get('folder', '') or 'Unfiled')
            title = str(note.get('title', '') or '')
            if query and query not in f'{folder} {title}'.lower():
                continue
            self._filtered.append(note)
            folder_display = _tr('Unfiled') if folder == 'Unfiled' else folder
            item = QListWidgetItem(f'{title}    ·    {folder_display}')
            item.setToolTip(f'{folder_display} / {title}')
            self.list_widget.addItem(item)
        count = len(self._filtered)
        meta = _tr('{n} note{s}').format(n=count, s='s' if count != 1 else '')
        if getattr(self, '_refreshing', False):
            meta += _tr(' · refreshing…')
        elif getattr(self, '_refresh_failed', False):
            meta += _tr(' · refresh failed, showing cached list')
        self.meta_lbl.setText(meta)
        if count:
            self.list_widget.setCurrentRow(0)

    def selected_note(self) -> dict | None:
        row = self.list_widget.currentRow()
        if 0 <= row < len(self._filtered):
            return dict(self._filtered[row])
        return None

    def _accept_if_selected(self):
        if self.selected_note() is not None:
            self.accept()


class CustomServicesDialog(QDialog):
    """自定义服务管理浮窗（非 OpenAI 形状的独立 REST，如 Ollama web search）。
    即时落盘：Save/Delete 直接写 settings store，不经 Settings 的 Save 按钮。"""

    def __init__(self, parent=None, dark: bool = False):
        super().__init__(parent)
        self._dark = bool(dark)
        self._services = get_custom_services_from_store()
        self._current_index = -1
        self._test_worker = None
        self.setModal(True)
        self.setWindowFlags(Qt.WindowType.Dialog | Qt.WindowType.FramelessWindowHint)
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground)
        # narrower than the main window like the approval dialogs (it was 680 → a 648 card)
        self.setFixedWidth(approval_window_width(parent, 680))
        self.setMinimumHeight(480)
        self._panel_margin = 16
        self._panel_radius = APPROVAL_DIALOG_SMOOTH_RADIUS

        root_layout = QVBoxLayout(self)
        root_layout.setContentsMargins(28, 28, 28, 28)
        root_layout.setSpacing(10)

        self.title_lbl = QLabel(_tr('Custom services'), self)
        root_layout.addWidget(self.title_lbl)
        self.hint_lbl = QLabel(
            _tr('Non-OpenAI REST services, referenced as &name in specialized capability selectors.\n'
            'Web search shape: POST {endpoint}/api/web_search with Bearer key '
            '(e.g. endpoint https://ollama.com, key from ollama.com/settings/keys).'),
            self,
        )
        self.hint_lbl.setWordWrap(True)
        root_layout.addWidget(self.hint_lbl)

        body_row = QVBoxLayout()   # the list above the form: side by side the fields were too narrow
        body_row.setSpacing(12)
        self.list_widget = QListWidget(self)
        self.list_widget.setFrameShape(QFrame.Shape.NoFrame)
        self.list_widget.setFixedHeight(120)
        self.list_widget.currentRowChanged.connect(self._on_row_changed)
        body_row.addWidget(self.list_widget)

        form_col = QVBoxLayout()
        form_col.setSpacing(8)

        def form_row(label_text, widget):
            row = QHBoxLayout()
            label = QLabel(label_text, self)
            label.setFixedWidth(110)
            row.addWidget(label)
            row.addWidget(widget, 1)
            form_col.addLayout(row)
            return label

        self.name_input = QLineEdit(self)
        self.name_input.setPlaceholderText(_tr('e.g. ollama-search'))
        self._label_name = form_row(_tr('Name'), self.name_input)
        # 供应商形状下拉：一个供应商一组，当前仅 Ollama；Brave/Tavily 等
        # 将来各自新增条目与适配分支。控件与设置面板同款（自绘 DropdownButton）。
        self.kind_combo = DropdownButton(self, always_dark=False, compact_light=True)
        for kind_value, kind_label in CUSTOM_SERVICE_KIND_LABELS:
            self.kind_combo.addItem(_tr(kind_label), kind_value)
        self._label_kind = form_row(_tr('Kind'), self.kind_combo)
        self.endpoint_input = QLineEdit(self)
        self.endpoint_input.setPlaceholderText('https://ollama.com')
        self._label_endpoint = form_row(_tr('Endpoint'), self.endpoint_input)
        self.api_key_input = QLineEdit(self)
        self.api_key_input.setEchoMode(QLineEdit.EchoMode.Password)
        self.api_key_input.setPlaceholderText(_tr('Bearer key'))
        self._label_key = form_row(_tr('API key'), self.api_key_input)
        self.max_results_input = QLineEdit(self)
        self.max_results_input.setPlaceholderText(_tr('5 (max 10)'))
        self._label_max = form_row(_tr('Max results'), self.max_results_input)
        self.enabled_checkbox = QCheckBox(_tr('Enabled'), self)
        self.enabled_checkbox.setChecked(True)
        form_col.addWidget(self.enabled_checkbox)
        self.status_lbl = QLabel('', self)
        self.status_lbl.setWordWrap(True)
        form_col.addWidget(self.status_lbl)
        form_col.addStretch(1)
        body_row.addLayout(form_col, 1)
        root_layout.addLayout(body_row, 1)

        button_row = QHBoxLayout()
        button_row.setSpacing(4)
        self.add_button = MacNormalButton(_tr('Add'), self)
        self.add_button.clicked.connect(self._add_service)
        self.save_button = MacNormalButton(_tr('Save'), self)
        self.save_button.clicked.connect(self._save_current)
        self.delete_button = MacNormalButton(_tr('Delete'), self)
        self.delete_button.clicked.connect(self._delete_current)
        self.test_button = MacNormalButton(_tr('Test'), self)
        self.test_button.clicked.connect(self._test_current)
        self.close_button = MacNormalButton(_tr('Close'), self)
        self.close_button.clicked.connect(self.accept)
        for button in (self.add_button, self.save_button, self.delete_button, self.test_button):
            button_row.addWidget(button)
        button_row.addStretch()
        button_row.addWidget(self.close_button)
        root_layout.addLayout(button_row)

        self._apply_theme()
        self._refresh_list()

    def paintEvent(self, event):
        painter = QPainter(self)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)
        panel_rect = QRectF(
            self._panel_margin,
            self._panel_margin,
            self.width() - self._panel_margin * 2,
            self.height() - self._panel_margin * 2,
        )
        bg_path = smooth_round_rect_path(panel_rect, self._panel_radius)
        if not getattr(self, '_liquid_glass_active', False):   # 液态玻璃时由系统玻璃当底
            painter.fillPath(bg_path, QColor('#2D2D2D' if self._dark else '#FFFFFF'))
            painter.setPen(QPen(QColor('#3A3A3A' if self._dark else '#ECECEC'), 1))
            painter.drawPath(bg_path)
        painter.end()

    def _apply_theme(self):
        dark = self._dark
        title_color = '#F2F2F7' if dark else '#20242B'
        hint_color = '#A7AEB8' if dark else '#7A8391'
        self.title_lbl.setStyleSheet(
            'font-family: "Helvetica Neue", Helvetica, Arial, sans-serif; font-size: 13px; '
            f'font-weight: 600; color: {title_color};'
        )
        for label in (self.hint_lbl, self.status_lbl,
                      self._label_name, self._label_kind, self._label_endpoint,
                      self._label_key, self._label_max):
            label.setStyleSheet(
                f'color: {hint_color}; '
                'font-family: "Helvetica Neue", Helvetica, Arial, sans-serif; font-size: 11px;'
            )
        # Kind 下拉与设置面板同款自绘控件，同一套主题机制。
        self.kind_combo._force_dark = dark
        self.kind_combo._update_style()
        for button in (self.add_button, self.save_button, self.delete_button,
                       self.test_button, self.close_button):
            button._force_dark = dark
            button.update_theme()
        self.enabled_checkbox.setStyleSheet(
            f'color: {title_color}; '
            'font-family: "Helvetica Neue", Helvetica, Arial, sans-serif; spacing: 6px; background: transparent;'
        )
        line_style = _settings_lineedit_stylesheet(dark)
        for line_edit in (self.name_input, self.endpoint_input, self.api_key_input, self.max_results_input):
            line_edit.setStyleSheet(line_style)
        self.list_widget.setStyleSheet(_input_card_stylesheet(dark))

    def _persist(self):
        self._services = normalize_custom_service_records(self._services)
        update_settings_globals({'custom_services': self._services})

    def _refresh_list(self, select_index: int = -1):
        self.list_widget.blockSignals(True)
        self.list_widget.clear()
        for service in self._services:
            marker = '' if service.get('enabled', True) else _tr(' (off)')
            self.list_widget.addItem(f"{CUSTOM_SERVICE_PREFIX}{service.get('name', '')}{marker}")
        self.list_widget.blockSignals(False)
        if 0 <= select_index < len(self._services):
            self.list_widget.setCurrentRow(select_index)
        elif self._services:
            self.list_widget.setCurrentRow(0)
        else:
            self._current_index = -1
            self._load_form(None)

    def _on_row_changed(self, row: int):
        self._current_index = row
        record = self._services[row] if 0 <= row < len(self._services) else None
        self._load_form(record)

    def _load_form(self, record: dict | None):
        record = record or {}
        self.name_input.setText(str(record.get('name', '') or ''))
        kind = str(record.get('kind', '') or CUSTOM_SERVICE_DEFAULT_KIND)
        kind_index = self.kind_combo.findData(kind)
        self.kind_combo.setCurrentIndex(kind_index if kind_index >= 0 else 0)
        self.endpoint_input.setText(str(record.get('endpoint', '') or ''))
        self.api_key_input.setText(str(record.get('api_key', '') or ''))
        self.max_results_input.setText(str(record.get('max_results', 5) or 5))
        self.enabled_checkbox.setChecked(bool(record.get('enabled', True)))

    def _collect_form(self) -> dict | None:
        record = normalize_custom_service_record({
            'id': (self._services[self._current_index].get('id', '')
                   if 0 <= self._current_index < len(self._services) else ''),
            'name': self.name_input.text(),
            'kind': str(self.kind_combo.currentData() or CUSTOM_SERVICE_DEFAULT_KIND),
            'endpoint': self.endpoint_input.text(),
            'api_key': self.api_key_input.text(),
            'max_results': self.max_results_input.text().strip() or 5,
            'enabled': self.enabled_checkbox.isChecked(),
        })
        if record is None:
            self.status_lbl.setText(_tr('Name and endpoint are required.'))
        return record

    def _add_service(self):
        self._services.append({
            'id': f'svc-{int(time.time() * 1000)}',
            'name': f'service-{len(self._services) + 1}',
            'kind': CUSTOM_SERVICE_DEFAULT_KIND,
            'endpoint': 'https://ollama.com',
            'api_key': '',
            'max_results': 5,
            'enabled': True,
        })
        self._persist()
        self._refresh_list(select_index=len(self._services) - 1)
        self.status_lbl.setText(_tr('Added. Fill in the fields and press Save.'))

    def _save_current(self):
        if self._current_index < 0:
            self._add_service()
            return
        record = self._collect_form()
        if record is None:
            return
        self._services[self._current_index] = record
        self._persist()
        self._refresh_list(select_index=min(self._current_index, len(self._services) - 1))
        self.status_lbl.setText(_tr('Saved {name}.').format(name=CUSTOM_SERVICE_PREFIX + str(record["name"])))

    def _delete_current(self):
        if not (0 <= self._current_index < len(self._services)):
            return
        removed = self._services.pop(self._current_index)
        self._persist()
        self._refresh_list(select_index=min(self._current_index, len(self._services) - 1))
        self.status_lbl.setText(_tr('Deleted {name}.').format(name=CUSTOM_SERVICE_PREFIX + str(removed.get("name", ""))))

    def _test_current(self):
        record = self._collect_form()
        if record is None:
            return
        if self._test_worker is not None and self._test_worker.isRunning():
            return
        self.status_lbl.setText(_tr('Testing…'))
        self.test_button.setEnabled(False)

        worker = AppleNotesTaskWorker(lambda: custom_service_web_search(record, 'test'), self)

        def _done(results):
            self.test_button.setEnabled(True)
            count = len(results or [])
            self.status_lbl.setText(_tr('✓ Service reachable — {n} result{s} for "test".').format(n=count, s='s' if count != 1 else ''))

        def _fail(message):
            self.test_button.setEnabled(True)
            self.status_lbl.setText(_tr('✗ Test failed: {msg}').format(msg=message))

        worker.finished_ok.connect(_done)
        worker.failed.connect(_fail)
        worker.finished.connect(worker.deleteLater)
        self._test_worker = worker
        worker.start()


class TerminalHistoryPanel(SmoothPanelWidget):
    copy_requested = pyqtSignal(str)
    terminal_input_requested = pyqtSignal(str, bool)
    delete_requested = pyqtSignal(str)

    def __init__(self, parent=None):
        super().__init__(parent)
        self._records_by_source = {'shell': [], 'broccoli': []}
        self._build_ui()

    def _build_ui(self):
        self.setObjectName('TerminalHistoryPanel')
        self.setAttribute(Qt.WidgetAttribute.WA_StyledBackground, True)
        self.setFixedSize(500, 760)
        shadow = QGraphicsDropShadowEffect(self)
        shadow.setBlurRadius(34)
        shadow.setXOffset(0)
        shadow.setYOffset(10)
        shadow.setColor(QColor(0, 0, 0, 45))
        self.setGraphicsEffect(shadow)

        self.source_combo = DropdownButton(self, always_dark=True)
        self.source_combo.setFixedHeight(36)
        self.source_combo.addItem(_tr('Shell history (~/.zsh_history)'), 'shell')
        self.source_combo.addItem(_tr('Broccoli terminal history'), 'broccoli')
        self.source_combo.currentIndexChanged.connect(self._refresh_list)

        self.search_input = glass_search_field(QLineEdit(self))   # a glass capsule like the system search field
        self.search_input.setPlaceholderText(_tr('Search command history'))
        self.search_input.textChanged.connect(self._refresh_list)

        self.meta_lbl = QLabel('', self)
        self.list_widget = QListWidget(self)
        self.list_widget.setFrameShape(QFrame.Shape.NoFrame)
        self.list_widget.setSpacing(6)
        self.list_widget.setContextMenuPolicy(Qt.ContextMenuPolicy.CustomContextMenu)
        self.list_widget.itemClicked.connect(self._on_item_clicked)
        self.list_widget.customContextMenuRequested.connect(self._show_context_menu)

        layout = QVBoxLayout(self)
        layout.setContentsMargins(24, 24, 24, 24)
        layout.setSpacing(14)
        layout.addWidget(self.source_combo)
        layout.addWidget(self.search_input)
        layout.addWidget(self.meta_lbl)
        layout.addWidget(self.list_widget, 1)
        self._apply_theme()

    def _apply_theme(self):
        self.set_smooth_panel_background('#2D2D2D', '#2D2D2D', 59)
        self.setStyleSheet('QWidget#TerminalHistoryPanel { border: none; background: transparent; }')
        self.search_input.setStyleSheet(_search_input_stylesheet(True))
        self.meta_lbl.setStyleSheet(
            'color: #A7AEB8; font-family: "Helvetica Neue", Helvetica, Arial, sans-serif; font-size: 11px;'
        )
        self.list_widget.setStyleSheet('''
            QListWidget {
                border: none;
                background: transparent;
                outline: none;
                font-family: "Helvetica Neue", Helvetica, Arial, sans-serif;
                font-size: 15px;
                color: #F2F2F7;
            }
            QListWidget::item {
                border-radius: 14px;
                padding: 12px 14px;
                background: #3A3A3A;
                margin: 0 0 6px 0;
            }
            QListWidget::item:selected {
                background: #2E5C91;
                color: #FFFFFF;
            }
            QListWidget::item:hover {
                background: #454547;
            }
        ''')

    def set_sources(self, shell_records: list[dict], broccoli_records: list[dict]):
        next_sources = {
            'shell': list(shell_records or []),
            'broccoli': list(broccoli_records or []),
        }
        if self._records_by_source == next_sources:
            return
        self._records_by_source = next_sources
        self._refresh_list()

    def _refresh_list(self):
        source = str(self.source_combo.currentData() or 'shell')
        query = self.search_input.text().strip().lower()
        records = list(reversed(self._records_by_source.get(source, [])))
        self.list_widget.clear()
        matched = []
        for record in records:
            haystack = str(record.get('search_blob', '') or '').lower()
            if query and query not in haystack:
                continue
            command = str(record.get('command', '') or '').strip()
            if not command:
                continue
            matched.append(record)
        visible_records = matched[:TERMINAL_PANEL_ROW_LIMIT]
        for record in visible_records:
            command = str(record.get('command', '') or '').strip()
            created_at = str(record.get('created_at', '') or '').strip()
            mode_text = str(record.get("mode", "run") or "run").replace("_", " ")
            meta = (_tr('Shell history') if source == 'shell' else _tr('Broccoli terminal · {mode}').format(mode=_tr(mode_text))).strip()
            if created_at:
                meta = f'{meta} · {created_at}' if meta else created_at
            subtitle = _terminal_output_preview(record.get('output', ''))
            item = QListWidgetItem()
            item.setData(Qt.ItemDataRole.UserRole - 1, str(record.get('id', '') or '').strip())
            item.setData(Qt.ItemDataRole.UserRole, command)
            item.setToolTip(command + (('\n\n' + _tr('Output:') + '\n' + str(record.get("output", ""))) if subtitle else ''))
            item.setSizeHint(QSize(0, 80 if subtitle else 66))
            self.list_widget.addItem(item)
            self.list_widget.setItemWidget(
                item,
                TerminalCommandListItemWidget(_terminal_command_preview(command, 110), subtitle, meta)
            )
        hidden = len(matched) - len(visible_records)
        if hidden > 0:
            footer = QListWidgetItem(_tr('{n} more · type to search all').format(n=hidden))
            footer.setFlags(Qt.ItemFlag.NoItemFlags)
            self.list_widget.addItem(footer)
        label = _tr('Shell history') if source == 'shell' else _tr('Broccoli terminal history')
        visible = len(visible_records)
        self.meta_lbl.setText(_tr('{n} item{s} · {label}').format(n=visible, s='s' if visible != 1 else '', label=label))

    def _on_item_clicked(self, item):
        command = str(item.data(Qt.ItemDataRole.UserRole) or '').strip()
        if command:
            self.copy_requested.emit(command)

    def _show_context_menu(self, pos):
        item = self.list_widget.itemAt(pos)
        if item is None:
            return
        command = str(item.data(Qt.ItemDataRole.UserRole) or '').strip()
        if not command:
            return
        record_id = str(item.data(Qt.ItemDataRole.UserRole - 1) or '').strip()
        is_broccoli = str(self.source_combo.currentData() or 'shell') == 'broccoli'
        menu = style_broccoli_context_menu(QMenu(self))
        replace_action = menu.addAction(_tr('Replace terminal input'))
        append_action = menu.addAction(_tr('Append to terminal input'))
        delete_action = None
        if is_broccoli and record_id:
            menu.addSeparator()
            delete_action = menu.addAction(_tr('Delete'))
        chosen = menu.exec(self.list_widget.mapToGlobal(pos))
        if chosen == replace_action:
            self.terminal_input_requested.emit(command, False)
        elif chosen == append_action:
            self.terminal_input_requested.emit(command, True)
        elif delete_action is not None and chosen == delete_action:
            self.delete_requested.emit(record_id)


