        app.aboutToQuit.connect(self.stop_background_vision)
        app.aboutToQuit.connect(self.stop_all_persistent_terminal_sessions)
        # Reap CLI subprocesses on EVERY catchable exit path, not just Qt's aboutToQuit:
        #  - atexit: any normal interpreter shutdown,
        #  - SIGTERM/SIGINT: `kill <pid>` / Ctrl-C (a QTimer keeps the interpreter awake so
        #    Python signal handlers fire while the Qt C++ loop runs).
        # (SIGKILL / force-quit are uncatchable by any program; those orphans go to launchd.)
        atexit.register(_force_kill_all_children)
        for _term_sig in (signal.SIGTERM, signal.SIGINT):
            try:
                signal.signal(_term_sig, self._on_terminate_signal)
            except Exception:
                pass
        self._signal_wakeup_timer = QTimer(self)
        self._signal_wakeup_timer.setInterval(250)
