        # only fire on real user edits to popup.edit, never on the blocked mirror. The event
        # filter handles keyboard nav + focus tracking while focus is in popup.edit. The
        # slash/mention popups re-anchor to popup.edit on every keystroke, so no extra hook is
        # needed when the floating window settles.
        self._text1_popup.edit.textChanged.connect(self._refresh_slash_command_popup)
        self._text1_popup.edit.textChanged.connect(self._refresh_mention_target_popup)
        self._text1_popup.edit.textChanged.connect(self._directive_highlight_timer.start)
        self._text1_popup.edit.installEventFilter(self)
        self._last_prompt_editor = self.text1
        self.text1.popup_content_changed.connect(lambda _state: self._refresh_text1_popup_visibility())
        self.text1.anchor_geometry_changed.connect(self._update_text1_popup_geometry)
        app.focusChanged.connect(self._on_prompt_focus_changed)

        self.btn_sub1 = AssistantCapsuleButton(_tr('🔺 Send'), self)
        self.btn_sub1.clicked.connect(self.SendX)
        self.btn_sub4 = self.btn_sub1   # btn_sub4 removed; alias keeps old references working
        # While an Agent run generates, typing flips ⛔️ Stop <-> 📥 Queue. Connected after
        # the popup->text1 sync above, so text1 already holds the popup's text here.
        self.text1.textChanged.connect(self._on_agent_prompt_text_changed_for_run_button)
        self._text1_popup.edit.textChanged.connect(self._on_agent_prompt_text_changed_for_run_button)

        # Per-@target strictness control: a tiny info-style "ⓘ" button that appears only
