        self.btn_strictness = QPushButton('⚙︎', self)
        self.btn_strictness.setFixedSize(18, 18)
        self.btn_strictness.setFlat(True)
        self.btn_strictness.setCursor(Qt.CursorShape.PointingHandCursor)
        self.btn_strictness.setToolTip(_tr('Strictness'))
        self.btn_strictness.setStyleSheet(
            'QPushButton { border: none; background: transparent; color: #8E8E93; '
            'font-size: 14px; padding: 0px; }'
            'QPushButton:hover { color: #0A84FF; }'
        )
        self.btn_strictness.setVisible(False)
        self.btn_strictness.clicked.connect(self._on_strictness_button_clicked)

