        self.widget0 = DropdownButton(self, always_dark=False)
        self.widget0.setCurrentIndex(0)
        self.widget0.addItems([_tr('Chat and ask'), _tr('Command (AppleScript)'), _tr('Translate'), _tr('Polish'), _tr('Summarize'), _tr('Grammatically analyze'), _tr('Explain code'), _tr('Customize')])
        self.widget0.currentIndexChanged.connect(self.ModeX)
        self.widget0.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed)

        self.widget1 = DropdownButton(self, always_dark=False)
        self.widget1.setCurrentIndex(0)
        langs = codecs.open(fulldir3, 'r', encoding='utf-8').read()
        fulllanglist = []
        langs_list = ['English', '中文', '日本語']
        if langs != '':
            langs_list = langs.split('\n')
            while '' in langs_list:
                langs_list.remove('')
            for i in range(len(langs_list)):
                fulllanglist.append(langs_list[i])
        if langs == '':
            for i in range(len(langs_list)):
                fulllanglist.append(langs_list[i])
        self.widget1.addItems(langs_list)
        self.widget1.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed)
        self.widget1.setVisible(False)
        self.widget1.currentIndexChanged.connect(self.TranslateX)

        self.lbl1 = QLabel('▶', self)
        self.lbl1.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self.lbl1.setFixedWidth(24)
        self.lbl1.setVisible(False)

        self.widget2 = DropdownButton(self, always_dark=False)
        self.widget2.setCurrentIndex(0)
        self.widget2.setPlaceholderText(_tr('Target language'))
        currentlang = self.widget1.currentText()
        while currentlang in langs_list:
            langs_list.remove(currentlang)
        self.widget2.addItems(langs_list)
        self.widget2.setCurrentIndex(preferred_runtime_translate_target_index(langs_list))
        self.widget2.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed)
        self.widget2.setVisible(False)
        self.widget2.currentIndexChanged.connect(self._on_translate_target_changed)

        self.widget3 = DropdownButton(self, always_dark=False)
        self.widget3.setCurrentIndex(0)
        self.widget3.addItems(['Context: None', 'Banana', 'Strawberry', 'Orange', 'All'])
        self.widget3.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed)
        self.widget3.setVisible(False)  # cancel this setting at the end.

        self.widget4 = DropdownButton(self, always_dark=False)
        self.widget4.setCurrentIndex(0)
        self.widget4.addItems(fulllanglist)
        self.widget4.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed)
        self.widget4.setVisible(False)

        self.widget5 = DropdownButton(self, always_dark=False)
        self.widget5.setCurrentIndex(0)
        itemlist = [title for title, _prompt in load_custom_prompt_items()]
        if itemlist != []:
            self.widget5.addItems(itemlist)
        if itemlist == []:
            self.widget5.addItems([_tr('No customized prompts, please add one in Settings')])
        self.widget5.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed)
        self.widget5.setVisible(False)
        self.widget5.currentIndexChanged.connect(self.CustomChange)

        self.btn_sub5 = AssistantCapsuleButton(_tr('Run command'), self)
        self.btn_sub5.clicked.connect(self.RunCommand)
        self.btn_sub5.setVisible(False)

        # self.btn0_1 = QPushButton('', self)
        # self.btn0_1.setFixedSize(25, 25)
