        self.drawing_layer = DrawingLayer(self)
        self.drawing_layer_2 = DrawingLayer2(self)
        self.drawing_layer_2.setVisible(False)

        # ── Left pill content: qw1_3 widgets ─────────────────
        _left_content = QWidget()
        _left_content_lay = QHBoxLayout(_left_content)
        self._left_content = _left_content
        self._left_content_lay = _left_content_lay
        _left_content_lay.setContentsMargins(0, 0, 0, 0)
        _left_content_lay.setSpacing(4)
        _left_content_lay.addWidget(self.widget0, 1)
