    def _set_prompt_edit_read_only(self, enabled: bool):
        self.text1.setReadOnly(bool(enabled))
        if hasattr(self, '_text1_popup'):
            self._text1_popup.edit.setReadOnly(bool(enabled))

    def _clear_and_hide_agent_prompt_after_send(self):
        self._set_prompt_edit_read_only(False)
        self._prompt_syncing = True
        blockers = []
        try:
            blockers.append(QSignalBlocker(self.text1))
            self.text1.clear()
            if hasattr(self, '_text1_popup'):
                blockers.append(QSignalBlocker(self._text1_popup.edit))
                self._text1_popup.edit.clear()
        finally:
            blockers.clear()
            self._prompt_syncing = False
        try:
            self.text1._emit_multiline_if_needed()
        except Exception:
            pass
        if hasattr(self, '_text1_popup'):
            self._text1_popup.hide()
        if hasattr(self, '_slash_command_popup'):
            self._slash_command_popup.hide()
        if hasattr(self, '_mention_target_popup'):
            self._mention_target_popup.hide()
        # text1 was cleared with signals blocked, so textChanged never fired -> the
        # strictness ⓘ button would linger. Re-evaluate it (and its popup) explicitly.
        if hasattr(self, 'btn_strictness'):
            self._refresh_strictness_button()
        self._refresh_text1_popup_visibility()
        self._update_send_shortcut_enabled()

    def _clear_agent_prompt_if_unchanged(self, sent_text: str):
        if str(self.text1.toPlainText() or '') != str(sent_text or ''):
            return
        self._clear_and_hide_agent_prompt_after_send()

    def _ordered_unique_external_aliases(self, text: str) -> list:
        # The @target aliases used in a prompt, in order, de-duplicated. Covers web
        # (@claude-ai) and terminal (@codex/@claude-code) alike -- the parser tags every
        # @alias block as 'external'.
        aliases, seen = [], set()
        try:
            for block in self._parse_prompt_directive_blocks(text):
                if not isinstance(block, dict) or block.get('kind') != 'external':
                    continue
                ref = str(block.get('ref', '') or '').strip()
                if ref and ref not in seen:
                    seen.add(ref)
                    aliases.append(ref)
        except Exception:
            pass
        return aliases

    def _prefill_prompt_with_targets(self, text: str, cursor_pos: int):
        # Mirror of _clear_and_hide_agent_prompt_after_send, but SET the carried-over
        # @target lines instead of clearing. Both editors are written signal-blocked
        # (so text1 <-> popup stay in sync), then the same refreshes are fired by hand
        # because textChanged was suppressed.
        self._set_prompt_edit_read_only(False)
        self._prompt_syncing = True
        blockers = []
        try:
            blockers.append(QSignalBlocker(self.text1))
            self.text1.setPlainText(text)
            cursor = self.text1.textCursor()
            cursor.setPosition(max(0, min(int(cursor_pos), len(text))))
            self.text1.setTextCursor(cursor)
            if hasattr(self, '_text1_popup'):
                blockers.append(QSignalBlocker(self._text1_popup.edit))
                self._text1_popup.edit.setPlainText(text)
        finally:
            blockers.clear()
            self._prompt_syncing = False
        try:
            self.text1._emit_multiline_if_needed()
        except Exception:
            pass
        try:
            self._refresh_prompt_directive_highlight()
        except Exception:
            pass
        if hasattr(self, 'btn_strictness'):
            self._refresh_strictness_button()
        self._refresh_text1_popup_visibility()
        self._update_send_shortcut_enabled()
        self.text1.setFocus()

    def _last_user_message_text_of_current_conversation(self) -> str:
        # The raw text of the LAST user message of the open conversation (it keeps the
        # '@alias' it was sent with), or '' if there is none.
        try:
            for msg in reversed(load_chat_history_messages()):
                if isinstance(msg, dict) and msg.get('role') == 'user':
                    return str(msg.get('content', '') or '')
        except Exception:
            pass
        return ''

    def _apply_carryover_targets(self, source_text=None):
        # The prompt box's default = the @targets used in the LAST user message, so they are
        # present whenever you land on the agent tab: right after a send, after switching in
        # from another tab, AND after restarting + opening a conversation. `source_text` is
        # the just-sent text when given, otherwise it is read from the open conversation's
        # last user message. No @target there -> the box just stays empty ("auto-clear").
        if str(self.text1.toPlainText() or '').strip():
            return   # never overwrite text already in the box
        if source_text is None:
            source_text = self._last_user_message_text_of_current_conversation()
        targets = self._ordered_unique_external_aliases(source_text or '')
        if targets:
            self._prefill_prompt_with_targets(
                '\n'.join(f'@{alias} ' for alias in targets), len(f'@{targets[0]} '))

    def _install_selection_context_menus(self):
        if not hasattr(self, '_selection_context_widgets'):
            self._selection_context_widgets = set()
        widgets = []
        # real2 (QWebEngineView) is wired separately to _show_real2_context_menu,
        # which itself delegates to the selection menu when text is selected. Adding
        # it here too would connect two slots to one customContextMenuRequested
        # signal, making both menus pop up in sequence.
        for name in ('real1',):
            widget = getattr(self, name, None)
            if widget is not None:
                widgets.append(widget)
        terminal = getattr(self, 'terminal_widget', None)
        if terminal is not None:
            # 每个终端会话都接，不只当前这个：以前新开或切过去的会话要等下一次切换主标签
            # 才接上，在那之前右键是 Qt 自带的菜单。
            sessions = [session for session in (getattr(terminal, '_widgets_by_id', None) or {}).values()
                        if session is not None] or [terminal]
            for session in sessions:
                for widget in (getattr(session, 'output', None), getattr(session, 'input_line', None)):
                    if widget is not None:
                        widgets.append(widget)
        for panel_name in ('ai_web_panel', 'localhost_panel'):
            panel = getattr(self, panel_name, None)
            for view in list(getattr(panel, '_views', []) or []):
                if view is not None:
                    widgets.append(view)
        for widget in widgets:
            ident = id(widget)
            if ident in self._selection_context_widgets:
                continue
            try:
                # 一律用“自定义菜单”信号接：文字框（流式预览、终端输出）的右键事件送到里面的
                # 显示区，装在外壳上的事件过滤器看不到，以前流式预览就因此弹 Qt 自带的
                # “复制 / 全选”。滚动区发来的位置是显示区坐标。
                widget.setContextMenuPolicy(Qt.ContextMenuPolicy.CustomContextMenu)
                widget.customContextMenuRequested.connect(
                    lambda pos, w=widget: self._handle_selection_context_menu_at(
                        w, (w.viewport() if isinstance(w, QAbstractScrollArea) else w).mapToGlobal(pos))
                )
                self._selection_context_widgets.add(ident)
            except Exception:
                pass

    def eventFilter(self, obj, event):
        slash_popup = getattr(self, '_slash_command_popup', None)
        mention_popup = getattr(self, '_mention_target_popup', None)
        if event.type() in (QEvent.Type.KeyPress, QEvent.Type.MouseButtonPress, QEvent.Type.Wheel):
            self._note_agent_engagement(obj, event)
        if event.type() == QEvent.Type.Wheel:
            real2 = getattr(self, 'real2', None)
            if real2 is not None and (obj is real2 or obj is real2.focusProxy()):
                timer = getattr(self, '_agent_rail_scroll_timer', None)
                if timer is not None:
                    timer.start()
        if event.type() == QEvent.Type.FocusIn:
            # Remember which prompt editor the user is in, so _active_prompt_editor() can route
            # inserts/anchors correctly even when focus is transiently on a popup list mid-click.
            if obj is getattr(self, 'text1', None):
                self._last_prompt_editor = self.text1
            elif obj is getattr(getattr(self, '_text1_popup', None), 'edit', None):
                self._last_prompt_editor = self._text1_popup.edit
        prompt_editors = (
            getattr(self, 'text1', None),
            getattr(getattr(self, '_text1_popup', None), 'edit', None),
        )
        if obj in prompt_editors and event.type() == QEvent.Type.KeyPress:
            if mention_popup is not None and mention_popup.isVisible():
                key = event.key()
                if key in (Qt.Key.Key_Down, Qt.Key.Key_Up):
                    count = mention_popup.list_widget.count()
                    if count:
                        row = mention_popup.list_widget.currentRow()
                        delta = 1 if key == Qt.Key.Key_Down else -1
                        mention_popup.list_widget.setCurrentRow(max(0, min(count - 1, row + delta)))
                    return True
                if key in (Qt.Key.Key_Return, Qt.Key.Key_Enter, Qt.Key.Key_Tab):
                    command = mention_popup.current_command()
                    if command:
                        self._insert_mention_target(command)
                        return True
                if key == Qt.Key.Key_Escape:
                    mention_popup.hide()
                    return True
            if slash_popup is not None and slash_popup.isVisible():
                key = event.key()
                if key in (Qt.Key.Key_Down, Qt.Key.Key_Up):
                    count = slash_popup.list_widget.count()
                    if count:
                        row = slash_popup.list_widget.currentRow()
                        delta = 1 if key == Qt.Key.Key_Down else -1
                        slash_popup.list_widget.setCurrentRow(max(0, min(count - 1, row + delta)))
                    return True
                if key in (Qt.Key.Key_Return, Qt.Key.Key_Enter, Qt.Key.Key_Tab):
                    command = slash_popup.current_command()
                    if command:
                        self._insert_slash_command(command)
                        return True
                if key == Qt.Key.Key_Escape:
                    slash_popup.hide()
                    return True
        if slash_popup is not None and obj is slash_popup.list_widget and event.type() == QEvent.Type.KeyPress:
            if event.key() in (Qt.Key.Key_Return, Qt.Key.Key_Enter, Qt.Key.Key_Tab):
                command = slash_popup.current_command()
                if command:
                    self._insert_slash_command(command)
                    return True
            if event.key() == Qt.Key.Key_Escape:
                slash_popup.hide()
                self._active_prompt_editor().setFocus()
                return True
        if isinstance(obj, QWebEngineView):
            return False
        if event.type() == QEvent.Type.ContextMenu:
            # Web views (real2 etc.) own their context menu via customContextMenuRequested
            # -> _show_real2_context_menu, which itself delegates to the selection menu on
            # selected text. Installing an event filter on real2's focus proxy (for
            # engagement detection) re-exposed its ContextMenu event here; a focus proxy is
            # NOT a QWebEngineView instance so the guard above misses it. Skip any widget
            # OWNED by a web view so only ONE menu ever shows.
            if isinstance(self._selection_context_owner(obj), QWebEngineView):
                return False
            if self._is_selection_context_widget(obj) and self._handle_selection_context_menu(obj, event):
                return True
        return super().eventFilter(obj, event)

    def _current_slash_query(self) -> str:
        ed = self._active_prompt_editor()
        text = ed.toPlainText()
        cursor_pos = ed.textCursor().position()
        before_cursor = text[:cursor_pos]
        line_start = before_cursor.rfind('\n') + 1
        current_line = before_cursor[line_start:]
        stripped = current_line.lstrip()
        if not stripped.startswith('/'):
            return ''
        return stripped

    def _refresh_slash_command_popup(self):
        popup = getattr(self, '_slash_command_popup', None)
        if popup is None:
            return
        query = self._current_slash_query()
        focus_widget = QApplication.focusWidget()
        popup_edit = getattr(getattr(self, '_text1_popup', None), 'edit', None)
        focus_ok = focus_widget is self.text1 or focus_widget is popup.list_widget or focus_widget is popup_edit
        mention_visible = bool(getattr(getattr(self, '_mention_target_popup', None), 'isVisible', lambda: False)())
        if query and focus_ok and self.stacked_widget.currentIndex() == TAB_API and not mention_visible:
            popup.set_skill_commands(getattr(self, '_enabled_skills_cache', []))
            popup.show_for_anchor(self._active_prompt_editor(), query)
        else:
            popup.hide()

    def _insert_slash_command(self, command: str):
        command = str(command or '')
        if not command:
            return
        ed = self._active_prompt_editor()
        cursor = ed.textCursor()
        text = ed.toPlainText()
        pos = cursor.position()
        before = text[:pos]
        line_start = before.rfind('\n') + 1
        line_prefix = text[line_start:pos]
        slash_offset = len(line_prefix) - len(line_prefix.lstrip())
        replace_start = line_start + slash_offset
        cursor.setPosition(replace_start)
        cursor.setPosition(pos, QTextCursor.MoveMode.KeepAnchor)
        cursor.insertText(command)
        ed.setTextCursor(cursor)
        if getattr(self, '_slash_command_popup', None) is not None:
            self._slash_command_popup.hide()
        ed.setFocus()

    def _current_mention_query(self) -> str:
        ed = self._active_prompt_editor()
        text = ed.toPlainText()
        cursor_pos = ed.textCursor().position()
        before_cursor = text[:cursor_pos]
        line_start = before_cursor.rfind('\n') + 1
        current_line = before_cursor[line_start:]
        # @ is only recognized at the start of a line (after optional leading
        # whitespace), matching the /command rule. Aliases contain no spaces, so once
        # a space separates the alias from its text, stop suggesting targets.
        stripped = current_line.lstrip()
        if not stripped.startswith('@') or ' ' in stripped or '\t' in stripped:
            return ''
        return stripped

    def _refresh_mention_target_popup(self):
        popup = getattr(self, '_mention_target_popup', None)
        if popup is None:
            return
        query = self._current_mention_query()
        focus_widget = QApplication.focusWidget()
        popup_edit = getattr(getattr(self, '_text1_popup', None), 'edit', None)
        focus_ok = focus_widget is self.text1 or focus_widget is popup.list_widget or focus_widget is popup_edit
        if query and focus_ok and self.stacked_widget.currentIndex() == TAB_API:
            if getattr(self, '_slash_command_popup', None) is not None:
                self._slash_command_popup.hide()
            popup.show_for_anchor(self._active_prompt_editor(), query)
        else:
            popup.hide()

    def _strictness_kind_in_prompt(self) -> str:
        # The terminal_kind ('codex'/'claude') of the FIRST codex/claude @target currently
        # in the prompt, else ''. terminal_kind lives on the resolved target, not the block.
        try:
            for block in self._parse_prompt_directive_blocks(self.text1.toPlainText()):
                if block.get('kind') != 'external':
                    continue
                tgt = self._external_target_by_alias(block.get('ref', '')) or {}
                tk = str(tgt.get('terminal_kind', '') or '').strip().lower()
                if tk == 'claude_tui':
                    tk = 'claude'
                if tk in ('codex', 'claude'):
                    return tk
        except Exception:
            pass
        return ''

    def _refresh_strictness_button(self):
        btn = getattr(self, 'btn_strictness', None)
        if btn is None:
            return
        kind = self._strictness_kind_in_prompt()
        self._strictness_active_kind = kind
        btn.setVisible(bool(kind))
        if not kind:
            popup = getattr(self, '_strictness_popup', None)
            if popup is not None and popup.isVisible():
                popup.hide()

    def _on_strictness_button_clicked(self):
        popup = getattr(self, '_strictness_popup', None)
        if popup is not None and popup.isVisible():
            popup.hide()   # second click on the button closes it (toggle)
            return
        kind = getattr(self, '_strictness_active_kind', '') or ''
        if kind not in EXTERNAL_STRICTNESS_TIERS or popup is None:
            return
        popup.set_context(kind, get_external_strictness_tier(kind))
        popup.show_for_anchor(self.btn_strictness)

    def _on_strictness_tier_selected(self, tier: str):
        kind = getattr(self, '_strictness_active_kind', '') or ''
        if getattr(self, '_strictness_popup', None) is not None:
            self._strictness_popup.hide()
        if kind and tier:
            self._apply_strictness_tier(kind, tier)

    def _insert_mention_target(self, command: str):
        command = str(command or '')
        if not command:
            return
        ed = self._active_prompt_editor()
        cursor = ed.textCursor()
        text = ed.toPlainText()
        pos = cursor.position()
        before = text[:pos]
        line_start = before.rfind('\n') + 1
        token_start = max(line_start, before.rfind(' ') + 1, before.rfind('\t') + 1)
        cursor.setPosition(token_start)
        cursor.setPosition(pos, QTextCursor.MoveMode.KeepAnchor)
        cursor.insertText(command)
        ed.setTextCursor(cursor)
        if getattr(self, '_mention_target_popup', None) is not None:
            self._mention_target_popup.hide()
        ed.setFocus()

    def _prompt_directive_alias_set(self) -> set:
        try:
            aliases = {str(t.get('alias', '') or '') for t in self._collect_external_targets()}
        except Exception:
            aliases = set()
        aliases.discard('')
        return aliases

    def _refresh_enabled_skills_cache(self):
        """把已启用 skill（name + description）缓存到主线程，供 `//` 弹窗补全和
        输入框指令块高亮使用——两者都高频触发，不能每次去读设置盘。设置保存后
        由 persist_current_settings 调一次刷新。"""
        try:
            records = load_skill_records_from_store(enabled_only=True)
        except Exception:
            records = []
        cache = []
        for record in records:
            name = sanitize_skill_name(record.get('name', ''), '')
            if not name:
                continue
            cache.append({'name': name, 'description': str(record.get('description', '') or '').strip()})
        self._enabled_skills_cache = cache

    def _prompt_directive_skill_names(self) -> list:
        return [entry['name'] for entry in getattr(self, '_enabled_skills_cache', [])]

    def _parse_prompt_directive_blocks(self, text: str) -> list[dict]:
        """Split the prompt into ordered blocks for highlight (P1) and later routing.

        A directive block begins on a line that, after optional leading whitespace,
        starts with @<registered target alias> or /<built-in slash command>. The rest
        of that line plus following non-directive lines IN THE SAME PARAGRAPH form the
        block body: a blank line ends the block (a directive task must be written
        within one paragraph -- same boundary as parse_specialized_slash_segments, so
        the highlighted range IS the bound range). All non-directive text collects
        into a single 'plain' block. Unrecognized @x // x are NOT directives -- they
        stay as plain text. Char offsets (start/end and the header token
        header_start/header_end) are relative to `text`, for highlighting.
        Pure parsing, no side effects."""
        text = str(text or '')
        aliases = self._prompt_directive_alias_set()
        skill_names = self._prompt_directive_skill_names()
        commands = sorted(
            ((cmd.lower(), cap) for cmd, cap, _desc in SPECIALIZED_SLASH_COMMANDS),
            key=lambda item: len(item[0]), reverse=True,
        )

        def detect(content: str):
            if content.startswith('@'):
                match = re.match(r'@([A-Za-z0-9][A-Za-z0-9_.-]{0,63})', content)
                if match:
                    alias = external_target_alias_slug(match.group(1))
                    if alias and alias in aliases:
                        return ('external', alias, match.end())
                return None
            # 双斜杠 `//<已启用 skill 名>`：与 `/tool` 同类（kind='capability'），
            # 高亮走完全相同的路径。先于单斜杠判定（`//` 也以 `/` 开头）。
            if content.startswith('//'):
                name = match_skill_directive_name(content[2:], skill_names)
                if name:
                    return ('capability', name, 2 + len(name))
                return None
            if content.startswith('/'):
                low = content.lower()
                for cmd, cap in commands:
                    if low == cmd or low.startswith(cmd + ' '):
                        return ('capability', cap, len(cmd))
            return None

        plain0 = None
        directive_blocks = []
        cur = None
        offset = 0
        for raw_line in text.splitlines(keepends=True):
            line_len = len(raw_line)
            line_start = offset
            offset += line_len
            line_body = raw_line.rstrip('\n')
            if line_body.endswith('\r'):
                line_body = line_body[:-1]
            lead = len(line_body) - len(line_body.lstrip())
            content = line_body.lstrip()
            directive = detect(content) if content else None
            if directive is not None:
                kind, ref, token_len = directive
                header_start = line_start + lead
                cur = {
                    'kind': kind, 'ref': ref,
                    'header_start': header_start,
                    'header_end': header_start + token_len,
                    'start': line_start, 'end': line_start + line_len,
                    'body_parts': [content[token_len:].strip()],
                }
                directive_blocks.append(cur)
            elif cur is not None and line_body.strip():
                cur['end'] = line_start + line_len
                cur['body_parts'].append(line_body.strip())
            else:
                if not line_body.strip():
                    # 空行结束指令块：斜杠/@ 任务必须一段内写完。
                    cur = None
                if plain0 is None:
                    plain0 = {
                        'kind': 'plain', 'ref': '',
                        'header_start': -1, 'header_end': -1,
                        'start': line_start, 'end': line_start + line_len,
                        'body_parts': [],
                    }
                plain0['end'] = line_start + line_len
                if line_body.strip():
                    plain0['body_parts'].append(line_body.strip())

        ordered = []
        if plain0 is not None and any(plain0['body_parts']):
            ordered.append(plain0)
        ordered.extend(directive_blocks)
        for index, block in enumerate(ordered):
            block['body'] = '\n'.join(part for part in block['body_parts'] if part).strip()
            block['step_index'] = index
            block.pop('body_parts', None)
        return ordered

    @staticmethod
    def _directive_step_colors(step_index: int, dark: bool):
        # Golden-angle hue spacing gives visually distinct colors for any step count.
        hue = (int(step_index) * 137) % 360
        if dark:
            return QColor.fromHsl(hue, 95, 66), QColor.fromHsl(hue, 120, 92)
        return QColor.fromHsl(hue, 150, 231), QColor.fromHsl(hue, 165, 204)

    def _refresh_prompt_directive_highlight(self):
        text1 = getattr(self, 'text1', None)
        if text1 is None:
            return
        text = text1.toPlainText()
        blocks = self._parse_prompt_directive_blocks(text)
        directive_blocks = [b for b in blocks if b['kind'] in ('external', 'capability')]
        dark = is_dark_theme(app)
        text_len = len(text)
        edits = [text1]
        popup = getattr(self, '_text1_popup', None)
        popup_edit = getattr(popup, 'edit', None) if popup is not None else None
        if popup_edit is not None:
            edits.append(popup_edit)
        for edit in edits:
            selections = []
            if directive_blocks:
                doc = edit.document()
                for block in directive_blocks:
                    bg, header_bg = self._directive_step_colors(block['step_index'], dark)
                    body_cursor = QTextCursor(doc)
                    body_cursor.setPosition(max(0, min(block['start'], text_len)))
                    body_cursor.setPosition(max(0, min(block['end'], text_len)), QTextCursor.MoveMode.KeepAnchor)
                    body_fmt = QTextCharFormat()
                    body_fmt.setBackground(bg)
                    body_sel = QTextEdit.ExtraSelection()
                    body_sel.cursor = body_cursor
                    body_sel.format = body_fmt
                    selections.append(body_sel)
                    if block['header_end'] > block['header_start']:
                        head_cursor = QTextCursor(doc)
                        head_cursor.setPosition(max(0, min(block['header_start'], text_len)))
                        head_cursor.setPosition(max(0, min(block['header_end'], text_len)), QTextCursor.MoveMode.KeepAnchor)
                        head_fmt = QTextCharFormat()
                        head_fmt.setBackground(header_bg)
                        head_sel = QTextEdit.ExtraSelection()
                        head_sel.cursor = head_cursor
                        head_sel.format = head_fmt
                        selections.append(head_sel)
            try:
                edit.setExtraSelections(selections)
            except Exception:
                pass

    def _selection_context_owner(self, obj):
        current = obj
        terminal = getattr(self, 'terminal_widget', None)
        terminal_output = getattr(terminal, 'output', None) if terminal is not None else None
        terminal_input = getattr(terminal, 'input_line', None) if terminal is not None else None
        while current is not None:
            if current in (getattr(self, 'real1', None), getattr(self, 'real2', None)):
                return current
            if current in (terminal_output, terminal_input):
                return current
            for panel_name in ('ai_web_panel', 'localhost_panel'):
                panel = getattr(self, panel_name, None)
                if current in list(getattr(panel, '_views', []) or []):
                    return current
            if isinstance(current, QWebEngineView):
                return current
            current = current.parentWidget() if hasattr(current, 'parentWidget') else None
        return obj

    def _is_selection_context_widget(self, obj) -> bool:
        owner = self._selection_context_owner(obj)
        if owner in (getattr(self, 'real1', None), getattr(self, 'real2', None)):
            return True
        terminal = getattr(self, 'terminal_widget', None)
        if terminal is not None and owner in (getattr(terminal, 'output', None), getattr(terminal, 'input_line', None)):
            return True
        for panel_name in ('ai_web_panel', 'localhost_panel'):
            panel = getattr(self, panel_name, None)
            if owner in list(getattr(panel, '_views', []) or []):
                return True
        return isinstance(owner, QWebEngineView)

    def _is_terminal_selection_context_widget(self, obj) -> bool:
        obj = self._selection_context_owner(obj)
        if bool(getattr(obj, '_broccoli_is_terminal_xterm', False)):
            return True
        terminal = getattr(self, 'terminal_widget', None)
        return bool(terminal is not None and obj in (getattr(terminal, 'output', None), getattr(terminal, 'input_line', None)))

    def _selected_text_from_widget(self, obj) -> str:
        obj = self._selection_context_owner(obj)
        try:
            if isinstance(obj, QWebEngineView):
                return str(obj.page().selectedText() or '').strip()
        except Exception:
            return ''
        try:
            if isinstance(obj, QLineEdit):
                return str(obj.selectedText() or '').strip()
            if hasattr(obj, 'textCursor'):
                cursor = obj.textCursor()
                if cursor.hasSelection():
                    return cursor.selectedText().replace('\u2029', '\n').strip()
        except Exception:
            return ''
        return ''

    def _agent_annotation_icon(self, color: str) -> QIcon:
        pixmap = QPixmap(14, 14)
        pixmap.fill(Qt.GlobalColor.transparent)
        painter = QPainter(pixmap)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)
        qcolor = QColor(color if QColor(str(color)).isValid() else AGENT_COMMENT_ANNOTATION_COLOR)
        painter.setBrush(QBrush(qcolor))
        painter.setPen(QPen(Qt.PenStyle.NoPen))
        painter.drawEllipse(QRectF(2, 2, 10, 10))
        painter.end()
        return QIcon(pixmap)

    def _active_agent_annotations(self) -> list[dict]:
        path = str(getattr(self, '_active_conversation_path', '') or '').strip()
        if not path:
            return []
        record = load_conversation_record(path, include_retrieval=False)
        if not isinstance(record, dict):
            return []
        return list(record.get('agent_annotations') or [])

    def _save_active_agent_annotations(self, annotations: list[dict]) -> None:
        path = str(getattr(self, '_active_conversation_path', '') or '').strip()
        if not path:
            return
        if self._refuse_edit_of_remote_copy(path):
            return
        record = load_conversation_record(path, include_retrieval=False)
        if not isinstance(record, dict):
            return
        record['agent_annotations'] = normalize_agent_annotation_records(
            annotations,
            len(record.get('messages', []) or []),
        )
        record['updated_at'] = datetime.datetime.now().isoformat(timespec='seconds')
        saved = write_conversation_record(path, record)
        self._active_conversation_path = saved.get('path', path)
        self._apply_agent_annotations_to_real2()
        self._refresh_history_panel()

    def _agent_annotations_context_for_path(self, path: str) -> str:
        record = load_conversation_record(str(path or '').strip()) if str(path or '').strip() else None
        if not isinstance(record, dict):
            return ''
        # 收藏（favorite）是给用户自己看的书签，不进模型上下文。
        annotations = [
            item for item in list(record.get('agent_annotations') or [])
            if str((item or {}).get('type', '') or '').strip().lower() != 'favorite'
        ]
        return format_agent_annotations_prompt_block(
            annotations,
            list(record.get('messages') or []),
        )

    def _apply_agent_annotations_to_real2(self):
        if getattr(self, 'real2', None) is None:
            return
        annotations = self._active_agent_annotations()
        script = (
            'window.broccoliApplyAgentAnnotations && '
            'window.broccoliApplyAgentAnnotations(%s);'
        ) % json.dumps(annotations, ensure_ascii=False)
        try:
            self.real2.page().runJavaScript(script)
        except Exception:
            pass

    def _resolve_agent_selection_info(self, callback):
        if getattr(self, 'real2', None) is None:
            callback({})
            return
        try:
            self.real2.page().runJavaScript(
                'window.broccoliAgentSelectionInfo ? window.broccoliAgentSelectionInfo() : null',
                lambda value: callback(value if isinstance(value, dict) else {}),
            )
        except Exception:
            callback({})

    @staticmethod
    def _agent_annotation_overlaps(annotation: dict, selection: dict) -> bool:
        try:
            return (
                int(annotation.get('message_index', -1)) == int(selection.get('message_index', -2))
                and int(annotation.get('start', 0)) < int(selection.get('end', 0))
                and int(annotation.get('end', 0)) > int(selection.get('start', 0))
            )
        except Exception:
            return False

    def _toggle_agent_quick_annotation(self, selection: dict, label: str):
        if not isinstance(selection, dict):
            return
        label = str(label or '').strip()
        annotations = self._active_agent_annotations()
        overlapping = [
            item for item in annotations
            if str(item.get('type', '') or '') == 'quick'
            and str(item.get('label', '') or '') == label
            and self._agent_annotation_overlaps(item, selection)
        ]
        if overlapping:
            remove_ids = {str(item.get('id', '') or '') for item in overlapping}
            annotations = [item for item in annotations if str(item.get('id', '') or '') not in remove_ids]
            self._save_active_agent_annotations(annotations)
            return
        now = datetime.datetime.now().isoformat(timespec='seconds')
        annotations.append(
            {
                'id': new_agent_annotation_id(),
                'message_index': int(selection.get('message_index', -1)),
                'start': int(selection.get('start', 0)),
                'end': int(selection.get('end', 0)),
                'quote': str(selection.get('quote', '') or ''),
                'type': 'quick',
                'label': label,
                'color': agent_annotation_color_for_label(label),
                'comment': '',
                'created_at': now,
                'updated_at': now,
            }
        )
        self._save_active_agent_annotations(annotations)

    def _append_agent_comment_annotation(self, selection: dict, comment: str):
        if not isinstance(selection, dict):
            return
        comment = str(comment or '').strip()
        if not comment:
            return
        annotations = self._active_agent_annotations()
        now = datetime.datetime.now().isoformat(timespec='seconds')
        annotations.append(
            {
                'id': new_agent_annotation_id(),
                'message_index': int(selection.get('message_index', -1)),
                'start': int(selection.get('start', 0)),
                'end': int(selection.get('end', 0)),
                'quote': str(selection.get('quote', '') or ''),
                'type': 'comment',
                'label': '',
                'color': AGENT_COMMENT_ANNOTATION_COLOR,
                'comment': comment,
                'created_at': now,
                'updated_at': now,
            }
        )
        self._save_active_agent_annotations(annotations)

    def _add_agent_comment_annotation(self, selection: dict):
        if not isinstance(selection, dict):
            return
        dialog = AnnotationDialog(
            _tr('Add comment'),
            parent=self,
            always_dark=is_dark_theme(app),
            extra_button_text=_tr('Add to Saved Comments'),
            extra_callback=lambda dlg: self._pin_agent_comment_template(dlg.text()),
        )
        _center_broccoli_dialog(dialog, self)
        if dialog.exec() != QDialog.DialogCode.Accepted or not dialog.text():
            return
        self._append_agent_comment_annotation(selection, dialog.text())

    def _edit_agent_comment_annotation(self, annotation_id: str):
        annotation_id = str(annotation_id or '').strip()
        if not annotation_id:
            return
        annotations = self._active_agent_annotations()
        for annotation in annotations:
            if str(annotation.get('id', '') or '') != annotation_id:
                continue
            dialog = AnnotationDialog(
                _tr('Edit comment'),
                str(annotation.get('comment', '') or ''),
                self,
                always_dark=is_dark_theme(app),
                extra_button_text=_tr('Add to Saved Comments'),
                extra_callback=lambda dlg: self._pin_agent_comment_template(dlg.text()),
            )
            _center_broccoli_dialog(dialog, self)
            if dialog.exec() != QDialog.DialogCode.Accepted or not dialog.text():
                return
            annotation['comment'] = dialog.text()
            annotation['updated_at'] = datetime.datetime.now().isoformat(timespec='seconds')
            self._save_active_agent_annotations(annotations)
            return

    def _delete_agent_annotation(self, annotation_id: str):
        annotation_id = str(annotation_id or '').strip()
        if not annotation_id:
            return
        annotations = [
            item for item in self._active_agent_annotations()
            if str(item.get('id', '') or '') != annotation_id
        ]
        self._save_active_agent_annotations(annotations)

    def _agent_saved_comment_templates(self) -> list[dict]:
        try:
            store = load_settings_store()
            return normalize_agent_saved_comment_templates(
                store.get('globals', {}).get('agent_saved_comment_templates', [])
            )
        except Exception:
            return []

    def _save_agent_saved_comment_templates(self, templates: list[dict]) -> None:
        update_settings_globals({
            'agent_saved_comment_templates': normalize_agent_saved_comment_templates(templates),
        })

    def _agent_saved_comment_template_for_text(self, text: str) -> dict | None:
        text_key = normalize_agent_saved_comment_text(text)
        if not text_key:
            return None
        for template in self._agent_saved_comment_templates():
            if normalize_agent_saved_comment_text(template.get('text', '')) == text_key:
                return template
        return None

    def _pin_agent_comment_template(self, text: str) -> bool:
        raw_text = str(text or '').strip()
        text_key = normalize_agent_saved_comment_text(raw_text)
        if not text_key:
            return False
        templates = self._agent_saved_comment_templates()
        now = datetime.datetime.now().isoformat(timespec='seconds')
        matched = None
        remaining = []
        for template in templates:
            if normalize_agent_saved_comment_text(template.get('text', '')) == text_key and matched is None:
                matched = dict(template)
            else:
                remaining.append(template)
        if matched is None:
            matched = {
                'id': _new_agent_saved_comment_template_id(),
                'text': raw_text,
                'created_at': now,
                'updated_at': now,
            }
        else:
            matched['text'] = raw_text
            matched['updated_at'] = now
        self._save_agent_saved_comment_templates([matched, *remaining])
        return True

    def _remove_agent_comment_template_by_text(self, text: str) -> None:
        text_key = normalize_agent_saved_comment_text(text)
        if not text_key:
            return
        templates = [
            template for template in self._agent_saved_comment_templates()
            if normalize_agent_saved_comment_text(template.get('text', '')) != text_key
        ]
        self._save_agent_saved_comment_templates(templates)

    def _remove_agent_comment_template_by_id(self, template_id: str) -> None:
        template_id = str(template_id or '').strip()
        if not template_id:
            return
        templates = [
            template for template in self._agent_saved_comment_templates()
            if str(template.get('id', '') or '') != template_id
        ]
        self._save_agent_saved_comment_templates(templates)

    def _add_agent_comment_scroll_area(self, menu: QMenu, comment_hits: list[dict]):
        if not comment_hits:
            return
        scroll = QScrollArea(menu)
        scroll.setWidgetResizable(True)
        scroll.setFrameShape(QFrame.Shape.NoFrame)
        scroll.setFixedSize(360, min(230, max(92, len(comment_hits) * 74)))
        container = QWidget(scroll)
        layout = QVBoxLayout(container)
        layout.setContentsMargins(8, 8, 8, 8)
        layout.setSpacing(6)
        dark = is_dark_theme(app)
        native_rows = []
        for index, annotation in enumerate(comment_hits, start=1):
            row = QWidget(container)
            row_layout = QVBoxLayout(row)
            row_layout.setContentsMargins(0, 0, 0, 0)
            row_layout.setSpacing(4)
            raw_comment = str(annotation.get('comment', '') or '').strip()
            comment = agent_comment_menu_preview(raw_comment, 58)
            native_ann_id = str(annotation.get('id', '') or '')
            # Native menu: each comment is a submenu with the same three actions.
            native_rows.append({
                'title': _tr('Comment {index}: {comment}').format(index=index, comment=comment or _tr('(empty)')),
                'tooltip': raw_comment,
                'children': [
                    {'title': _tr('Edit Comment'),
                     'callback': lambda aid=native_ann_id: self._edit_agent_comment_annotation(aid)},
                    {'title': _tr('Delete Comment'),
                     'callback': lambda aid=native_ann_id: self._delete_agent_annotation(aid)},
                    {'title': _tr('Add to Menu'), 'tooltip': _tr('Add Comment to Menu'),
                     'callback': lambda text=raw_comment: self._pin_agent_comment_template(text)},
                ],
            })
            label = QLabel(_tr('Comment {index}: {comment}').format(index=index, comment=comment or _tr('(empty)')), row)
            label.setWordWrap(True)
            label.setToolTip(raw_comment)
            label.setStyleSheet(
                f'color: {"#F2F2F7" if dark else "#20242B"}; '
                'font-family: "Helvetica Neue", Helvetica, Arial, sans-serif; font-size: 12px;'
            )
            buttons = QWidget(row)
            button_layout = QHBoxLayout(buttons)
            button_layout.setContentsMargins(0, 0, 0, 0)
            button_layout.setSpacing(6)
            edit_btn = MacNormalButton(_tr('Edit Comment'), buttons, always_dark=dark)
            delete_btn = MacNormalButton(_tr('Delete Comment'), buttons, always_dark=dark)
            pin_btn = MacNormalButton(_tr('Add to Menu'), buttons, always_dark=dark)
            pin_btn.setToolTip(_tr('Add Comment to Menu'))
            ann_id = str(annotation.get('id', '') or '')
            edit_btn.clicked.connect(lambda _checked=False, aid=ann_id, m=menu: (m.close(), self._edit_agent_comment_annotation(aid)))
            delete_btn.clicked.connect(lambda _checked=False, aid=ann_id, m=menu: (m.close(), self._delete_agent_annotation(aid)))
            pin_btn.clicked.connect(lambda _checked=False, text=raw_comment, m=menu: (m.close(), self._pin_agent_comment_template(text)))
            button_layout.addWidget(edit_btn)
            button_layout.addWidget(delete_btn)
            button_layout.addWidget(pin_btn)
            button_layout.addStretch()
            row_layout.addWidget(label)
            row_layout.addWidget(buttons)
            layout.addWidget(row)
        layout.addStretch()
        scroll.setWidget(container)
        action = QWidgetAction(menu)
        action.setDefaultWidget(scroll)
        menu.addAction(action)
        set_native_menu_items(action, native_rows)

    def _add_agent_saved_comment_template_actions(self, menu: QMenu, selection: dict):
        templates = self._agent_saved_comment_templates()
        if not templates:
            return
        menu.addSeparator()
        header = menu.addAction(_tr('Saved Comments'))
        header.setEnabled(False)
        scroll = QScrollArea(menu)
        scroll.setWidgetResizable(True)
        scroll.setFrameShape(QFrame.Shape.NoFrame)
        scroll.setFixedWidth(360)
        container = QWidget(scroll)
        layout = QVBoxLayout(container)
        layout.setContentsMargins(8, 8, 8, 8)
        layout.setSpacing(6)
        dark = is_dark_theme(app)
        visible_rows = 0
        native_uses, native_removes = [], []
        for template in templates:
            template_id = str(template.get('id', '') or '')
            text = str(template.get('text', '') or '').strip()
            if not normalize_agent_saved_comment_text(text):
                continue
            visible_rows += 1
            # Native menu: "Use …" items, and the removals grouped in one submenu (a bare
            # "Remove" next to each row would not say which comment it removes).
            native_preview = agent_comment_menu_preview(text, 46).replace('"', "'")
            native_uses.append({
                'title': _tr('Use "{preview}"').format(preview=native_preview), 'tooltip': text,
                'callback': lambda sel=dict(selection), comment=text: self._append_agent_comment_annotation(sel, comment),
            })
            native_removes.append({
                'title': f'"{native_preview}"', 'tooltip': text,
                'callback': lambda tid=template_id: self._remove_agent_comment_template_by_id(tid),
            })
            row = QWidget(container)
            row_layout = QHBoxLayout(row)
            row_layout.setContentsMargins(0, 0, 0, 0)
            row_layout.setSpacing(6)
            preview = agent_comment_menu_preview(text, 46).replace('"', "'")
            use_btn = MacNormalButton(_tr('Use "{preview}"').format(preview=preview), row, always_dark=dark)
            remove_btn = MacNormalButton(_tr('Remove'), row, always_dark=dark)
            use_btn.setToolTip(text)
            remove_btn.setToolTip(_tr('Remove this saved comment from the menu'))
            use_btn.clicked.connect(
                lambda _checked=False, sel=dict(selection), comment=text, m=menu: (
                    m.close(),
                    self._append_agent_comment_annotation(sel, comment),
                )
            )
            remove_btn.clicked.connect(
                lambda _checked=False, tid=template_id, m=menu: (
                    m.close(),
                    self._remove_agent_comment_template_by_id(tid),
                )
            )
            row_layout.addWidget(use_btn, 1)
            row_layout.addWidget(remove_btn)
            layout.addWidget(row)
        if visible_rows <= 0:
            return
        layout.activate()
        container.adjustSize()
        content_height = container.sizeHint().height() + 2
        scroll.setFixedHeight(min(230, max(46, content_height)))
        scroll.setWidget(container)
        action = QWidgetAction(menu)
        action.setDefaultWidget(scroll)
        menu.addAction(action)
        set_native_menu_items(action, native_uses + [{'title': _tr('Remove Saved Comment'), 'children': native_removes}])

    def _add_agent_quick_annotation_action(self, menu: QMenu, text: str, color: str, selection: dict, label: str):
        dark = is_dark_theme(app)
        hover = '#3A3A3A' if dark else '#F2F2F7'
        text_color = '#F2F2F7' if dark else '#20242B'
        button = QPushButton(str(text or ''), menu)
        button.setFlat(True)
        button.setCursor(Qt.CursorShape.PointingHandCursor)
        button.setIcon(self._agent_annotation_icon(color))
        button.setIconSize(QSize(14, 14))
        button.setMinimumWidth(250)
        button.setStyleSheet(f"""
            QPushButton {{
                background: transparent;
                border: none;
                border-radius: 8px;
                color: {text_color};
                font-family: "Helvetica Neue", Helvetica, Arial, sans-serif;
                font-size: 13px;
                padding: 7px 28px 7px 8px;
                text-align: left;
            }}
            QPushButton:hover {{
                background: {hover};
            }}
        """)
        action = QWidgetAction(menu)
        action.setDefaultWidget(button)
        menu.addAction(action)
        button.clicked.connect(
            lambda _checked=False, sel=dict(selection), lab=str(label or ''), m=menu: (
                m.close(),
                self._toggle_agent_quick_annotation(sel, lab),
            )
        )
        # Native menu: the same row as a plain item with its colour dot.
        set_native_menu_items(action, [{
            'title': str(text or ''),
            'icon': self._agent_annotation_icon(color),
            'callback': lambda sel=dict(selection), lab=str(label or ''): self._toggle_agent_quick_annotation(sel, lab),
        }])

    def _add_agent_annotation_menu_actions(self, menu: QMenu, selection: dict):
        if not isinstance(selection, dict) or not selection.get('ok'):
            return
        try:
            start = int(selection.get('start', 0))
            end = int(selection.get('end', 0))
            message_index = int(selection.get('message_index', -1))
        except Exception:
            return
        if message_index < 0 or end <= start:
            return
        active_annotations = self._active_agent_annotations()
        hits = [
            item for item in active_annotations
            if self._agent_annotation_overlaps(item, selection)
        ]
        menu.addSeparator()
        for item in AGENT_QUICK_ANNOTATIONS:
            label = item['label']
            matching_quick_hits = [
                hit for hit in hits
                if str(hit.get('type', '') or '') == 'quick'
                and str(hit.get('label', '') or '') == label
            ]
            existing = bool(matching_quick_hits)
            action_text = (_tr('Remove "{label}"') if existing else _tr('Mark "{label}"')).format(label=label)
            if existing and len(matching_quick_hits) > 1:
                action_text += f' ({len(matching_quick_hits)})'
            self._add_agent_quick_annotation_action(
                menu,
                action_text,
                item['color'],
                selection,
                label,
            )
        comment_hits = [hit for hit in hits if str(hit.get('type', '') or '') == 'comment']
        menu.addSeparator()
        if not comment_hits:
            add_comment_action = menu.addAction(_tr('Add Comment'))
            add_comment_action.triggered.connect(
                lambda _checked=False, sel=dict(selection): self._add_agent_comment_annotation(sel)
            )
        elif len(comment_hits) == 1:
            ann_id = str(comment_hits[0].get('id', '') or '')
            comment_text = str(comment_hits[0].get('comment', '') or '').strip()
            edit_action = menu.addAction(_tr('Edit Comment'))
            edit_action.triggered.connect(lambda _checked=False, aid=ann_id: self._edit_agent_comment_annotation(aid))
            delete_action = menu.addAction(_tr('Delete Comment'))
            delete_action.triggered.connect(lambda _checked=False, aid=ann_id: self._delete_agent_annotation(aid))
            pin_action = menu.addAction(_tr('Add Comment to Menu'))
            pin_action.triggered.connect(
                lambda _checked=False, text=comment_text: self._pin_agent_comment_template(text)
            )
        else:
            header = menu.addAction(_tr('{n} Comments').format(n=len(comment_hits)))
            header.setEnabled(False)
            self._add_agent_comment_scroll_area(menu, comment_hits)
        self._add_agent_saved_comment_template_actions(menu, selection)

    def _show_selection_context_menu_at(self,
                                        obj,
                                        global_pos,
                                        selected_text: str,
                                        copy_via_clipboard: bool = False,
                                        menu: QMenu | None = None,
                                        agent_selection: dict | None = None) -> None:
        obj = self._selection_context_owner(obj)
        if menu is None:
            menu = style_broccoli_context_menu(QMenu(self))
            if isinstance(obj, QWebEngineView):
                copy_action = menu.addAction(_tr('Copy'))
                if copy_via_clipboard:
                    copy_action.triggered.connect(
                        lambda _checked=False, text=selected_text: QApplication.clipboard().setText(text)
                    )
                else:
                    copy_action.triggered.connect(
                        lambda _checked=False, view=obj: view.page().triggerAction(QWebEnginePage.WebAction.Copy)
                    )
        if obj is getattr(self, 'real2', None) and isinstance(agent_selection, dict) and agent_selection.get('ok'):
            self._add_agent_annotation_menu_actions(menu, agent_selection)
            menu.addSeparator()
            favorite_action = menu.addAction(_tr('Add selection to favorites'))
            favorite_action.triggered.connect(
                lambda _checked=False, sel=dict(agent_selection), text=selected_text:
                self._add_agent_favorite_from_selection(sel, text)
            )
            append_note_action = menu.addAction(_tr('Add selection to an Apple Note…'))
            append_note_action.triggered.connect(
                lambda _checked=False, text=selected_text, sel=dict(agent_selection):
                self._append_selection_to_apple_note(text, sel)
            )
            new_note_action = menu.addAction(_tr('Add selection to a new Apple Note'))
            new_note_action.triggered.connect(
                lambda _checked=False, text=selected_text, sel=dict(agent_selection):
                self._create_apple_note_from_selection(text, sel)
            )
        if menu.actions():
            menu.addSeparator()
        replace_menu = menu.addMenu(_tr('Replace prompt with selection'))
        append_menu = menu.addMenu(_tr('Append selection to prompt'))
        targets = [
            ('Agent', TAB_API),
            ('Web', TAB_WEB),
            ('Localhost', TAB_LOCALHOST),
            ('Terminal', TAB_TERMINAL),
        ]
        for label, target in targets:
            replace_action = replace_menu.addAction(_tr(label))
            replace_action.triggered.connect(
                lambda _checked=False, t=target, text=selected_text: self._route_selection_to_prompt(t, text, append=False)
            )
            append_action = append_menu.addAction(_tr(label))
            append_action.triggered.connect(
                lambda _checked=False, t=target, text=selected_text: self._route_selection_to_prompt(t, text, append=True)
            )
        if self._is_terminal_selection_context_widget(obj):
            favorite_action = menu.addAction(_tr('Add selection to Terminal favorites'))
            favorite_action.triggered.connect(
                lambda _checked=False, text=selected_text: self._add_terminal_favorite_from_text(text)
            )
        output_action = menu.addAction(_tr('Add selection to Generated outputs'))
        output_action.triggered.connect(lambda _checked=False, text=selected_text: self._add_selected_text_output(text))
        menu.exec(global_pos)

    def _show_terminal_xterm_context_menu(self, view, global_pos):
        # xterm.js keeps its own selection (not reliably mirrored to the DOM), so read it via
        # window.term.getSelection() and then show the same custom selection menu.
        if view is None:
            return
        page = view.page() if hasattr(view, 'page') else None
        if page is None:
            self._handle_selection_context_menu_at(view, global_pos, selection_override='', copy_via_clipboard=True)
            return

        def _on_selection(sel):
            self._handle_selection_context_menu_at(
                view, global_pos, selection_override=str(sel or ''), copy_via_clipboard=True
            )

        try:
            page.runJavaScript(
                'window.term && window.term.getSelection ? window.term.getSelection() : ""',
                _on_selection,
            )
        except Exception:
            self._handle_selection_context_menu_at(view, global_pos, selection_override='', copy_via_clipboard=True)

    def _handle_selection_context_menu(self, obj, event) -> bool:
        return self._handle_selection_context_menu_at(obj, event.globalPos())

    def _handle_selection_context_menu_at(self, obj, global_pos, selection_override=None, copy_via_clipboard=False) -> bool:
        obj = self._selection_context_owner(obj)
        if selection_override is not None:
            # Caller already resolved the selection (e.g. xterm via term.getSelection()).
            selected_text = str(selection_override or '').strip()
        else:
            selected_text = self._selected_text_from_widget(obj)
        if isinstance(obj, QWebEngineView):
            if not selected_text:
                return True
            if obj is getattr(self, 'real2', None):
                self._resolve_agent_selection_info(
                    lambda info, view=obj, pos=global_pos, text=selected_text, direct=copy_via_clipboard:
                    self._show_selection_context_menu_at(
                        view,
                        pos,
                        text,
                        copy_via_clipboard=direct,
                        agent_selection=info,
                    )
                )
                return True
            self._show_selection_context_menu_at(
                obj,
                global_pos,
                selected_text,
                copy_via_clipboard=copy_via_clipboard,
            )
            return True
        else:
            try:
                menu = style_broccoli_context_menu(obj.createStandardContextMenu())
            except Exception:
                menu = style_broccoli_context_menu(QMenu(self))
            if not selected_text:
                if menu is not None:
                    menu.exec(global_pos)
                    return True
                return False
        self._show_selection_context_menu_at(obj, global_pos, selected_text, menu=menu)
        return True

    def _set_plain_text_prompt(self, editor, text: str, append: bool):
        text = str(text or '')
        if append:
            current = editor.toPlainText() if hasattr(editor, 'toPlainText') else editor.text()
            merged = (str(current).rstrip() + '\n\n' + text).strip() if str(current).strip() else text
        else:
            merged = text
        if hasattr(editor, 'setPlainText'):
            editor.setPlainText(merged)
            try:
                cursor = editor.textCursor()
                cursor.movePosition(QTextCursor.MoveOperation.End)
                editor.setTextCursor(cursor)
            except Exception:
                pass
        else:
            editor.setText(merged)
            try:
                editor.end(False)
            except Exception:
                pass

    def _select_main_tab(self, index: int):
        index = max(0, min(3, int(index)))
        try:
            self.pill_nav.select(index)
        except Exception:
            self.stacked_widget.setCurrentIndex(index)
        if self.stacked_widget.currentIndex() != index:
            self.stacked_widget.setCurrentIndex(index)

    def _route_text_to_api_prompt(self, text: str, append: bool = False, new_conversation: bool = False):
        text = str(text or '').strip()
        if not text:
            return
        if new_conversation:
            self.ClearX()
        self._select_main_tab(TAB_API)
        self._set_plain_text_prompt(self.text1, text, append)
        self.text1.setFocus()
        self._refresh_text1_popup_visibility()

    def _route_text_to_external_prompt(self, target_index: int, text: str, append: bool = False, site_index=None):
        text = str(text or '').strip()
        if not text:
            return
        target_index = int(target_index)
        self._select_main_tab(target_index)
        panel, dock = self._external_prompt_panel_for_index(target_index)
        if panel is None or dock is None:
            return
        try:
            if site_index is not None:
                panel.select_site(int(site_index))
        except Exception:
            pass
        panel.set_prompt_dock_visible(True, animated=True)
        self._set_plain_text_prompt(dock.prompt_edit, text, append)
        dock.prompt_edit.setFocus()

    def _route_text_to_terminal_prompt(self, text: str, append: bool = False):
        text = str(text or '').strip()
        if not text:
            return
        self._select_main_tab(TAB_TERMINAL)
        terminal = getattr(self, 'terminal_widget', None)
        input_line = getattr(terminal, 'input_line', None) if terminal is not None else None
        if input_line is not None:
            self._set_plain_text_prompt(input_line, text, append)
            input_line.setFocus()

    def _route_selection_to_prompt(self, target_index: int, text: str, append: bool = False):
        text = str(text or '').strip()
        if not text:
            return
        target_index = int(target_index)
        if target_index == TAB_API:
            self._route_text_to_api_prompt(text, append)
            return
        if target_index in EXTERNAL_PROMPT_TAB_INDICES:
            self._route_text_to_external_prompt(target_index, text, append)
            return
        if target_index == TAB_TERMINAL:
            self._route_text_to_terminal_prompt(text, append)

    def _add_selected_text_output(self, text: str):
        text = str(text or '').strip()
        if not text:
            return
        created_at = datetime.datetime.now().isoformat(timespec='seconds')
        snippet = re.sub(r'\s+', ' ', text).strip()
        if len(snippet) > 48:
            snippet = snippet[:48].rstrip() + '...'
        tab_labels = MAIN_TAB_LABELS
        current_index = self.stacked_widget.currentIndex()
        tab_label = tab_labels[current_index] if 0 <= current_index < len(tab_labels) else 'Selection'
        scope_key = self._tab_output_scope_key(current_index)
        output = {
            'id': f'sel-{int(time.time() * 1000)}',
            'kind': 'text',
            'title': f'Selected text · {created_at}',
            'filename': 'selected-text.txt',
            'content': text,
            'path': '',
            'question': f'{tab_label} selection · {snippet or "Selected text"}',
            'question_index': -1,
            'assistant_index': -1,
            'created_at': created_at,
            'source': 'manual_selection',
            'tab_scope': scope_key or 'api',
        }
        if scope_key:
            outputs = merge_output_records(self._load_tab_outputs(scope_key), [output])
            self._save_tab_outputs(scope_key, outputs)
        else:
            if self._active_conversation_path and self._refuse_edit_of_remote_copy(self._active_conversation_path):
                return
            history_messages = get_current_chat_history_messages()
            self._ensure_active_conversation(text, history_messages)
            record = load_conversation_record(self._active_conversation_path) if self._active_conversation_path else None
            if record is None:
                record = create_conversation_record('Selected outputs', history_messages=history_messages)
                self._active_conversation_path = record['path']
            record['outputs'] = merge_output_records(record.get('outputs', []), [output])
            record['updated_at'] = created_at
            saved = write_conversation_record(self._active_conversation_path, record)
            self._active_conversation_path = saved['path']
        self._refresh_outputs_panel(prefer_latest=True)
        self.show_outputs_panel()

    def _sync_prompt_from_inline(self):
        if getattr(self, '_prompt_syncing', False):
            return
        text = self.text1.toPlainText()
        cursor_pos = self.text1.textCursor().position()
        self._prompt_syncing = True
        try:
            if self._text1_popup.edit.toPlainText() != text:
                blocker = QSignalBlocker(self._text1_popup.edit)
                self._text1_popup.edit.setPlainText(text)
                del blocker
            cursor = self._text1_popup.edit.textCursor()
            cursor.setPosition(min(cursor_pos, len(text)))
            self._text1_popup.edit.setTextCursor(cursor)
        finally:
            self._prompt_syncing = False
        self._refresh_text1_popup_visibility()

    def _sync_prompt_from_popup(self):
        if getattr(self, '_prompt_syncing', False):
            return
        text = self._text1_popup.edit.toPlainText()
        cursor_pos = self._text1_popup.edit.textCursor().position()
        self._prompt_syncing = True
        try:
            if self.text1.toPlainText() != text:
                blocker = QSignalBlocker(self.text1)
                self.text1.setPlainText(text)
                del blocker
            cursor = self.text1.textCursor()
            cursor.setPosition(min(cursor_pos, len(text)))
            self.text1.setTextCursor(cursor)
        finally:
            self._prompt_syncing = False
        self.text1._emit_multiline_if_needed()
        self._refresh_text1_popup_visibility()

    def _active_prompt_editor(self):
        """The prompt editor the user is actually typing in: the floating popup's .edit when
        it is the focused editor, else the pill-bar text1. When focus is transiently on a
        mention/slash list (mid-click), fall back to the last editor that held focus so an
        inserted @/command goes to (and refocuses) the editor the user was using."""
        popup = getattr(self, '_text1_popup', None)
        if popup is None:
            return self.text1
        fw = QApplication.focusWidget()
        if fw is popup.edit:
            return popup.edit
        if fw is self.text1:
            return self.text1
        return getattr(self, '_last_prompt_editor', self.text1)

    def _prompt_widget_has_focus(self, widget) -> bool:
        current = widget
        while current is not None:
            if current is self.text1 or current is self._text1_popup or current is self._text1_popup.edit:
                return True
            current = current.parentWidget()
        return False

    def _should_show_text1_popup(self) -> bool:
        if not hasattr(self, '_text1_popup'):
            return False
        if not self.isVisible() or not self._is_assistant_tab():
            return False
        if not self._right_pill._active or not self.text1.isVisible():
            return False
        if not self.text1.has_popup_content():
            return False
        return self._prompt_widget_has_focus(QApplication.focusWidget())

    def _update_text1_popup_geometry(self):
        if not hasattr(self, '_text1_popup'):
            return
        if self._text1_popup.isVisible():
            self._text1_popup.show_for_anchor(self.text1)
        anchor = self._active_prompt_editor()
        if hasattr(self, '_slash_command_popup') and self._slash_command_popup.isVisible():
            self._slash_command_popup.show_for_anchor(anchor, self._current_slash_query())
        if hasattr(self, '_mention_target_popup') and self._mention_target_popup.isVisible():
            self._mention_target_popup.show_for_anchor(anchor, self._current_mention_query())

    def _refresh_text1_popup_visibility(self):
        if not hasattr(self, '_text1_popup'):
            return
        if self._should_show_text1_popup():
            self._text1_popup.show_for_anchor(self.text1)
            # An open / or @ list moves above the editor (its show_for_anchor avoids it).
            anchor = self._active_prompt_editor()
            if hasattr(self, '_slash_command_popup') and self._slash_command_popup.isVisible():
                self._slash_command_popup.show_for_anchor(anchor, self._current_slash_query())
            if hasattr(self, '_mention_target_popup') and self._mention_target_popup.isVisible():
                self._mention_target_popup.show_for_anchor(anchor, self._current_mention_query())
        else:
            focus_widget = QApplication.focusWidget()
            # Don't yank focus back to text1 while a mention/slash popup is open (a single-line
            # insert would otherwise steal focus out of popup.edit mid-interaction).
            slash_or_mention_visible = (
                bool(getattr(getattr(self, '_slash_command_popup', None), 'isVisible', lambda: False)())
                or bool(getattr(getattr(self, '_mention_target_popup', None), 'isVisible', lambda: False)())
            )
            if (
                self._text1_popup.isVisible()
                and not self.text1.has_popup_content()
                and self._prompt_widget_has_focus(focus_widget)
                and focus_widget is not self.text1
                and not slash_or_mention_visible
            ):
                self.text1.setFocus()
            self._text1_popup.hide_animated()

    def _on_prompt_focus_changed(self, _old, _new):
        QTimer.singleShot(0, self._refresh_text1_popup_visibility)
        QTimer.singleShot(0, self._refresh_slash_command_popup)
        QTimer.singleShot(0, self._refresh_mention_target_popup)

    def _sync_branch_state_metadata(self, state: dict | None):
        if not isinstance(state, dict):
            return
        node_by_id = {}
        checked_node_ids = set()
        message_index_to_node_id = {}

        def walk(node: dict, parent_id: str = ''):
            node['parent_id'] = parent_id
            node_id = str(node.get('id', '')).strip()
            if not node_id:
                return
            node_by_id[node_id] = node
            try:
                msg_idx = int(node.get('message_index', -1))
            except (TypeError, ValueError):
                msg_idx = -1
            if msg_idx >= 0:
                message_index_to_node_id[msg_idx] = node_id
            if bool(node.get('checked', True)):
                checked_node_ids.add(node_id)
            for child in node.get('children', []) or []:
                walk(child, node_id)

        for root in state.get('roots', []) or []:
            walk(root, '')
        state['node_by_id'] = node_by_id
        state['checked_node_ids'] = checked_node_ids
        state['message_index_to_node_id'] = message_index_to_node_id
        if not bool(state.get('append_as_child', False)):
            state['active_node_id'] = ''
        elif str(state.get('active_node_id', '')).strip() not in node_by_id:
            if node_by_id:
                latest = max(node_by_id.values(), key=lambda node: int(node.get('message_index', -1) or -1))
                state['active_node_id'] = str(latest.get('id', ''))
            else:
                state['active_node_id'] = ''
        next_id = 1
        for node_id in node_by_id:
            # Only pure q<digits> ids count: int() would happily parse the
            # dedupe suffix in 'q1_2' as the underscore literal 12.
            if node_id.startswith('q') and node_id[1:].isdigit():
                next_id = max(next_id, int(node_id[1:]) + 1)
        # Take the MAX of the stored counter and the ids actually present: a
        # rebuilt state used to come back with next_id=1, so the next appended
        # question minted a duplicate id (q1) that shadowed the old q1 in
        # node_by_id and silently dropped its message from the selection.
        try:
            stored_next = int(state.get('next_id', 1) or 1)
        except (TypeError, ValueError):
            stored_next = 1
        state['next_id'] = max(1, stored_next, next_id)

    def _sort_branch_nodes_by_message_index(self, nodes: list[dict]) -> list[dict]:
        ordered = []
        for node in list(nodes or []):
            if not isinstance(node, dict):
                continue
            node['children'] = self._sort_branch_nodes_by_message_index(node.get('children', []) or [])
            ordered.append(node)
        ordered.sort(key=lambda node: int(node.get('message_index', -1) or -1))
        return ordered

    def _build_branch_state_from_messages(self, messages: list[dict], stored_branches: dict | None = None) -> dict:
        state = {
            'conversation_path': str(self._active_conversation_path or ''),
            'roots': [],
            'node_by_id': {},
            'checked_node_ids': set(),
            'message_index_to_node_id': {},
            'active_node_id': '',
            'next_id': 1,
            'append_as_child': False,
        }
        user_messages = {
            message_index: str(message.get('content', '')).strip()
            for message_index, message in enumerate(messages or [])
            if str(message.get('role', '')).strip().lower() == 'user'
        }
        used_indices = set()
        used_ids = set()

        def unique_node_id(raw_id: str, message_index: int) -> str:
            base = str(raw_id or '').strip() or f"q{message_index + 1}"
            candidate = base
            suffix = 2
            while candidate in used_ids:
                candidate = f'{base}_{suffix}'
                suffix += 1
            used_ids.add(candidate)
            return candidate

        def build_node(node_data: dict, parent_id: str = '') -> dict | None:
            if not isinstance(node_data, dict):
                return None
            try:
                message_index = int(node_data.get('message_index', -1))
            except (TypeError, ValueError):
                return None
            if message_index not in user_messages or message_index in used_indices:
                return None
            used_indices.add(message_index)
            full_text = user_messages[message_index]
            node_id = unique_node_id(node_data.get('id', ''), message_index)
            node = {
                'id': node_id,
                'text': full_text,
                'full_text': full_text,
                'message_index': message_index,
                'checked': bool(node_data.get('checked', True)),
                'children': [],
                'parent_id': parent_id,
            }
            for child_data in node_data.get('children', []) or []:
                child = build_node(child_data, node_id)
                if child is not None:
                    node['children'].append(child)
            return node

        branch_payload = stored_branches if isinstance(stored_branches, dict) else {}
        for root_data in branch_payload.get('roots', []) or []:
            root_node = build_node(root_data, '')
            if root_node is not None:
                state['roots'].append(root_node)

        for message_index in sorted(user_messages):
            if message_index in used_indices:
                continue
            node_id = unique_node_id('', message_index)
            full_text = user_messages[message_index]
            state['roots'].append({
                'id': node_id,
                'text': full_text,
                'full_text': full_text,
                'message_index': message_index,
                'checked': True,
                'children': [],
                'parent_id': '',
            })

        state['roots'] = self._sort_branch_nodes_by_message_index(state.get('roots', []))
        self._sync_branch_state_metadata(state)
        active_node_id = str(branch_payload.get('active_node_id', '')).strip()
        if bool(branch_payload.get('append_as_child', False)) and active_node_id in state['node_by_id']:
            state['active_node_id'] = active_node_id
        else:
            state['active_node_id'] = ''
        state['append_as_child'] = bool(branch_payload.get('append_as_child', False) and state.get('active_node_id'))
        return state

    def _serialize_branch_state_for_storage(self, state: dict | None) -> dict:
        if not isinstance(state, dict):
            return {'roots': [], 'active_node_id': '', 'append_as_child': False}

        def serialize_node(node: dict) -> dict:
            return {
                'id': str(node.get('id', '')).strip(),
                'message_index': int(node.get('message_index', -1) or -1),
                'text': str(node.get('text', '') or '')[:200],
                'checked': bool(node.get('checked', True)),
                'children': [serialize_node(child) for child in node.get('children', []) or []],
            }

        active_node_id = str(state.get('active_node_id', '')).strip()
        if not bool(state.get('append_as_child', False)) or active_node_id not in state.get('node_by_id', {}):
            active_node_id = ''
        return {
            'roots': [serialize_node(node) for node in state.get('roots', []) or []],
            'active_node_id': active_node_id,
            'append_as_child': bool(state.get('append_as_child', False) and active_node_id),
        }

    def _persist_active_branch_structure(self, state: dict | None = None):
        if not self._active_conversation_path:
            return
        if state is None:
            state = self._current_branch_state()
        if not isinstance(state, dict):
            return
        record = self._load_active_conversation_record()
        if record is None:
            return
        record['branches'] = self._serialize_branch_state_for_storage(state)
        saved = write_conversation_record(self._active_conversation_path, record)
        self._active_conversation_path = saved['path']

    def _current_branch_state(self) -> dict | None:
        path = self._branch_state_key()
        if not path:
            return None
        return self._branch_states.get(path)

    def _branch_state_key(self, history_messages: list[dict] | None = None) -> str:
        path = str(self._active_conversation_path or '').strip()
        if path:
            return path
        if history_messages is None:
            history_messages = get_current_chat_history_messages()
        return '__current__' if history_messages else ''

    def _ensure_branch_state_loaded(self, history_messages: list[dict] | None = None) -> dict | None:
        path = self._branch_state_key(history_messages)
        if not path:
            self.branch_panel.set_branch_state(None)
            return None
        state = self._branch_states.get(path)
        if state is None and path != '__current__':
            # Saves rename the conversation file (auto title), and most save
            # sites update _active_conversation_path without re-keying this
            # cache. Adopt the orphaned state by conversation id instead of
            # rebuilding (rebuilds lose checked/active state and, worse, used
            # to restart the id counter).
            conv_id = ''
            try:
                conv_id = conversation_id_for_reference(path)
            except Exception:
                conv_id = ''
            if conv_id:
                for old_path, old_state in list(self._branch_states.items()):
                    if old_path in ('', '__current__') or not isinstance(old_state, dict):
                        continue
                    if str(old_state.get('conversation_id', '') or '') == conv_id and not os.path.exists(old_path):
                        state = self._branch_states.pop(old_path)
                        self._branch_states[path] = state
                        break
        if state is not None and not (state.get('node_by_id') or {}):
            # A cached tree with zero nodes is corruption (see below), never a
            # user choice — drop it so it gets rebuilt from the record.
            self._branch_states.pop(path, None)
            state = None
        if state is None:
            record = None
            if history_messages is None:
                record = self._load_active_conversation_record() if path == str(self._active_conversation_path or '').strip() else load_conversation_record(path) if path and path != '__current__' else None
                history_messages = list(record.get('messages', [])) if record else []
            elif path == str(self._active_conversation_path or '').strip():
                record = self._load_active_conversation_record()
            elif path and path != '__current__':
                record = load_conversation_record(path)
            stored_branches = record.get('branches') if record else None
            state = self._build_branch_state_from_messages(history_messages or [], stored_branches)
            state['conversation_path'] = path
            if record is not None:
                state['conversation_id'] = str(record.get('id', '') or '')
            if state.get('node_by_id') or record is not None:
                self._branch_states[path] = state
            # else: the record was unreadable at this instant (rename/atomic
            # replace in flight) — hand back a transient state but do NOT cache
            # it, or every later send would keep seeing an empty tree.
        else:
            state['conversation_path'] = path
            self._sync_branch_state_metadata(state)
        self.branch_panel.set_branch_state(state)
        return state

    def _selected_branch_message_indices(self, history_messages: list[dict], state: dict | None = None) -> set[int]:
        if state is None:
            state = self._ensure_branch_state_loaded(history_messages)
        if not state:
            return set(range(len(history_messages or [])))
        node_by_id = state.get('node_by_id', {}) or {}
        if not node_by_id:
            # Degenerate tree (no nodes at all — e.g. built while the record was
            # briefly unreadable). That is corruption, not a user choice: fall
            # back to the FULL history instead of silently sending none.
            return set(range(len(history_messages or [])))
        selected_user_indices = {
            int(node.get('message_index', -1))
            for node_id, node in node_by_id.items()
            if node_id in state.get('checked_node_ids', set())
        }
        if not selected_user_indices:
            # Nodes exist and the user unchecked every one of them: that IS a
            # deliberate "send without history".
            return set()
        selected_indices = set()
        keep = False
        for message_index, message in enumerate(history_messages or []):
            if str(message.get('role', '')).strip().lower() == 'user':
                keep = message_index in selected_user_indices
                if keep:
                    selected_indices.add(message_index)
            elif keep:
                selected_indices.add(message_index)
        if not selected_indices and history_messages:
            # Checked nodes exist but none maps onto the current messages: the
            # tree belongs to another shape of this conversation (stale cache).
            # Full history is the safe answer, never an empty one.
            return set(range(len(history_messages)))
        return selected_indices

    def _filter_history_messages_by_branch(self, history_messages: list[dict]) -> tuple[list[dict], set[int]]:
        state = self._ensure_branch_state_loaded(history_messages)
        selected_indices = self._selected_branch_message_indices(history_messages, state)
        if not selected_indices:
            return [], set()
        return [
            message for message_index, message in enumerate(history_messages)
            if message_index in selected_indices
        ], selected_indices

    def _append_question_to_branch_state(self, question_text: str, message_index: int):
        path = self._branch_state_key()
        if not path:
            return
        state = self._ensure_branch_state_loaded(get_current_chat_history_messages())
        if state is None:
            state = self._build_branch_state_from_messages([])
            state['conversation_path'] = path
            self._branch_states[path] = state
        next_id = int(state.get('next_id', 1) or 1)
        existing_ids = set(state.get('node_by_id', {}) or {})
        while f'q{next_id}' in existing_ids:
            next_id += 1   # belt-and-suspenders: an id collision shadows a node
        node_id = f'q{next_id}'
        state['next_id'] = next_id + 1
        parent_id = str(state.get('active_node_id', '') or '').strip()
        append_as_child = bool(state.get('append_as_child', False))
        parent = state.get('node_by_id', {}).get(parent_id) if (append_as_child and parent_id) else None
        node = {
            'id': node_id,
            'text': str(question_text or '').strip(),
            'full_text': str(question_text or '').strip(),
            'message_index': int(message_index),
            'checked': True,
            'children': [],
            'parent_id': parent_id if parent is not None else '',
        }
        if parent is None:
            state.setdefault('roots', []).append(node)
        else:
            parent.setdefault('children', []).append(node)
            current = parent
            while current is not None:
                current['checked'] = True
                current = state.get('node_by_id', {}).get(str(current.get('parent_id', '')).strip())
        state['roots'] = self._sort_branch_nodes_by_message_index(state.get('roots', []))
        state['active_node_id'] = node_id
        if parent is not None:
            state['append_as_child'] = True
        self._sync_branch_state_metadata(state)
        self.branch_panel.set_branch_state(state)
        self._persist_active_branch_structure(state)

    def _refresh_branch_state_from_current_conversation(self):
        if not self._active_conversation_path:
            self.branch_panel.set_branch_state(None)
            return
        record = self._load_active_conversation_record()
        history_messages = list(record.get('messages', [])) if record else get_current_chat_history_messages()
        self._ensure_branch_state_loaded(history_messages)

    def _on_branch_state_changed(self, state: dict):
        path = self._branch_state_key()
        if not path:
            return
        self._sync_branch_state_metadata(state)
        self._branch_states[path] = state
        if self._active_conversation_path and self._refuse_edit_of_remote_copy(self._active_conversation_path):
            return  # a read-only copy: the owner's branches are not changed from here
        # Checked/parenting changes now survive a restart: persist them
        # (debounced) instead of waiting for the next question append.
        if self._active_conversation_path:
            timer = getattr(self, '_branch_persist_timer', None)
            if timer is None:
                timer = QTimer(self)
                timer.setSingleShot(True)
                timer.timeout.connect(lambda: self._persist_active_branch_structure())
                self._branch_persist_timer = timer
            timer.start(1500)

    def _jump_to_message_index(self, message_index: int):
        message_index = max(0, int(message_index))
        self.real2.page().runJavaScript(
            "(() => { const el = document.getElementById('msg-%d'); if (el) { el.scrollIntoView({behavior:'smooth', block:'center'}); } })();" % message_index
        )

    def _branch_panel_shown_rect(self):
        width = min(500, max(320, self.qw3.width() - 36))
        height = min(760, max(360, self.qw3.height() - 36))
        x = max(18, (self.qw3.width() - width) // 2)
        return QRect(x, 18, width, height)

    def _branch_panel_hidden_rect(self):
        shown = self._branch_panel_shown_rect()
        return QRect(shown.x(), -shown.height() - 24, shown.width(), shown.height())

    def _update_branch_overlay_geometry(self):
        if not hasattr(self, '_branch_scrim'):
            return
        stacked_pos = self.stacked_widget.mapTo(self.qw3, QPoint(0, 0))
        trigger_w = max(0, self.stacked_widget.width() - 20)
        self._branch_trigger_btn.setGeometry(
            stacked_pos.x() + 10,
            stacked_pos.y(),
            trigger_w,
            self._branch_trigger_band_h,
        )
        self._branch_trigger_btn.raise_()
        self._branch_scrim.setGeometry(self.qw3.rect())
        if self._branch_panel_visible:
            self.branch_panel.setGeometry(self._branch_panel_shown_rect())
        else:
            self.branch_panel.setGeometry(self._branch_panel_hidden_rect())
        self._raise_webfetch_panel_if_visible()

    def _raise_webfetch_panel_if_visible(self):
        if hasattr(self, 'webfetch_panel') and self.webfetch_panel.isVisible():
            self.webfetch_panel.raise_()

    def _outputs_panel_shown_rect(self):
        safe_w = max(280, self.qw3.width() - 56)
        safe_h = max(320, self.qw3.height() - 96)
        width = min(620, safe_w)
        height = min(620, safe_h)
        x = max(28, (self.qw3.width() - width) // 2)
        y = max(38, (self.qw3.height() - height) // 2)
        return QRect(x, y, width, height)

