    @staticmethod
    def _web_auto_send_after_inject_enabled() -> bool:
        return bool(load_settings_store().get('globals', {}).get('web_auto_send_after_inject', False))

    @staticmethod
    def _webfetch_context_use_embedding_enabled() -> bool:
        return bool(load_settings_store().get('globals', {}).get('webfetch_context_use_embedding', True))

    @staticmethod
    def _clear_attachments_after_send_enabled() -> bool:
        return bool(load_settings_store().get('globals', {}).get('clear_attachments_after_send', True))

    @staticmethod
    def _generated_output_context_use_embedding_enabled() -> bool:
        return bool(load_settings_store().get('globals', {}).get('generated_output_context_use_embedding', False))

    def _send_web_view_mouse_click(self, view: QWebEngineView, x: float, y: float):
        try:
            view_point = QPoint(int(x), int(y))
            target = view.childAt(view_point) or view.focusProxy() or view
            if target is not view:
                target_point = target.mapFrom(view, view_point)
            else:
                target_point = view_point
            local = QPointF(float(target_point.x()), float(target_point.y()))
            global_point = target.mapToGlobal(target_point)
            global_pos = QPointF(float(global_point.x()), float(global_point.y()))
            press = PyQt6.QtGui.QMouseEvent(
                QEvent.Type.MouseButtonPress,
                local,
                global_pos,
                Qt.MouseButton.LeftButton,
                Qt.MouseButton.LeftButton,
                Qt.KeyboardModifier.NoModifier,
            )
            release = PyQt6.QtGui.QMouseEvent(
                QEvent.Type.MouseButtonRelease,
                local,
                global_pos,
                Qt.MouseButton.LeftButton,
                Qt.MouseButton.NoButton,
                Qt.KeyboardModifier.NoModifier,
            )
            view.setFocus(Qt.FocusReason.MouseFocusReason)
            target.setFocus(Qt.FocusReason.MouseFocusReason)
            press_sent = bool(QApplication.sendEvent(target, press))
            release_sent = bool(QApplication.sendEvent(target, release))
            return press_sent and release_sent
        except Exception:
            return False

    def _send_web_view_cmd_return(self, view: QWebEngineView):
        log_broccoli_claude('sending Claude submit shortcut sequence')
        try:
            target = QApplication.focusWidget()
            if target is None or (target is not view and not view.isAncestorOf(target)):
                target = view.focusProxy() or view.childAt(QPoint(max(1, view.width() // 2), max(1, view.height() // 2))) or view
            log_broccoli_claude(f'shortcut target={type(target).__name__}')
            view.setFocus(Qt.FocusReason.ShortcutFocusReason)
            target.setFocus(Qt.FocusReason.ShortcutFocusReason)

            def send_qt_key(key, modifiers, label):
                log_broccoli_claude(f'Qt key event: {label}')
                press = PyQt6.QtGui.QKeyEvent(
                    QEvent.Type.KeyPress,
                    key,
                    modifiers,
                    '\r',
                )
                release = PyQt6.QtGui.QKeyEvent(
                    QEvent.Type.KeyRelease,
                    key,
                    modifiers,
                    '\r',
                )
                QApplication.sendEvent(target, press)
                QApplication.sendEvent(target, release)

            # On macOS Qt maps Command to ControlModifier; keep MetaModifier as a fallback for embedded Chromium.
            for qt_key_name, qt_key in (('Return', Qt.Key.Key_Return), ('Enter', Qt.Key.Key_Enter)):
                send_qt_key(qt_key, Qt.KeyboardModifier.ControlModifier, f'Command+{qt_key_name}')
                send_qt_key(qt_key, Qt.KeyboardModifier.MetaModifier, f'Meta+{qt_key_name}')

            log_broccoli_claude('scheduling pyautogui submit fallback sequence')
            QTimer.singleShot(180, lambda: (
                log_broccoli_claude('pyautogui command+enter fallback fired'),
                pyautogui.hotkey('command', 'enter')
            ))
            QTimer.singleShot(360, lambda: (
                log_broccoli_claude('pyautogui ctrl+enter fallback fired'),
                pyautogui.hotkey('ctrl', 'enter')
            ))
            QTimer.singleShot(540, lambda: (
                log_broccoli_claude('pyautogui command+return fallback fired'),
                pyautogui.hotkey('command', 'return')
            ))
        except Exception as exc:
            log_broccoli_claude(f'shortcut send failed: {exc}')
            try:
                pyautogui.hotkey('command', 'enter')
                pyautogui.hotkey('ctrl', 'enter')
            except Exception:
                pass

    def _activate_web_composer(self, view: QWebEngineView, callback=None):
        js = """
        (function() {
            const visible = (node) => {
                if (!node) return false;
                const rect = node.getBoundingClientRect();
                const style = window.getComputedStyle(node);
                return rect.width > 8 && rect.height > 8 && style.display !== 'none' && style.visibility !== 'hidden';
            };
            const input = Array.from(document.querySelectorAll('div[contenteditable="true"], [contenteditable="plaintext-only"], [role="textbox"], textarea'))
                .filter(visible)
                .sort((a, b) => b.getBoundingClientRect().bottom - a.getBoundingClientRect().bottom)[0];
            if (!input) return null;
            const rect = input.getBoundingClientRect();
            return {
                x: Math.max(8, Math.min(window.innerWidth - 8, rect.left + Math.min(80, Math.max(12, rect.width * 0.18)))),
                y: Math.max(8, Math.min(window.innerHeight - 8, rect.top + Math.min(24, Math.max(10, rect.height * 0.5))))
            };
        })()
        """

        def after(result):
            if isinstance(result, dict) and result.get('x') is not None and result.get('y') is not None:
                self._send_web_view_mouse_click(view, float(result.get('x')), float(result.get('y')))
            if callback:
                QTimer.singleShot(140, callback)

        try:
            view.page().runJavaScript(js, after)
        except Exception:
            if callback:
                QTimer.singleShot(0, callback)

    def _activate_claude_composer(self, view: QWebEngineView, callback=None):
        self._activate_web_composer(view, callback=callback)

    def _click_claude_send_button_if_present(self, view: QWebEngineView):
        js = """
        (function() {
            const visible = (node) => {
                if (!node) return false;
                const rect = node.getBoundingClientRect();
                const style = window.getComputedStyle(node);
                return rect.width > 8
                    && rect.height > 8
                    && style.display !== 'none'
                    && style.visibility !== 'hidden'
                    && Number(style.opacity || 1) > 0.01;
            };
            const disabled = (node) => {
                const className = String(node.className || '');
                return node.disabled
                    || node.getAttribute('aria-disabled') === 'true'
                    || node.getAttribute('disabled') !== null
                    || /(?:^|\\s)(disabled|is-disabled)(?:\\s|$)/i.test(className);
            };
            const btn = Array.from(document.querySelectorAll('button')).find(node => {
                return visible(node)
                    && !disabled(node)
                    && String(node.getAttribute('aria-label') || '').trim().toLowerCase() === 'send message';
            });
            if (!btn) return null;
            btn.focus && btn.focus();
            btn.dispatchEvent(new PointerEvent('pointerdown', { bubbles: true, cancelable: true, composed: true, pointerType: 'mouse' }));
            btn.dispatchEvent(new MouseEvent('mousedown', { bubbles: true, cancelable: true, composed: true }));
            btn.dispatchEvent(new PointerEvent('pointerup', { bubbles: true, cancelable: true, composed: true, pointerType: 'mouse' }));
            btn.dispatchEvent(new MouseEvent('mouseup', { bubbles: true, cancelable: true, composed: true }));
            btn.dispatchEvent(new MouseEvent('click', { bubbles: true, cancelable: true, composed: true }));
            return 'clicked';
        })()
        """
        try:
            view.page().runJavaScript(js)
        except Exception:
            pass

    def _submit_claude_with_shortcut(self, view: QWebEngineView):
        log_broccoli_claude('submit via Claude send button requested')
        self._activate_claude_composer(
            view,
            callback=lambda v=view: (
                QTimer.singleShot(180, lambda: self._click_claude_send_button_if_present(v)),
            ),
        )

    @staticmethod
    def _inject_text_to_web_view(view: QWebEngineView, text: str, callback=None):
        text_json = json.dumps(str(text or ''), ensure_ascii=False)
        js = f"""
        (function() {{
            const t = {text_json};
            const visible = (node) => {{
                if (!node) return false;
                const rect = node.getBoundingClientRect();
                const style = window.getComputedStyle(node);
                return rect.width > 8
                    && rect.height > 8
                    && style.display !== 'none'
                    && style.visibility !== 'hidden'
                    && Number(style.opacity || 1) > 0.01;
            }};
            const candidates = Array.from(document.querySelectorAll('div[contenteditable="true"], [contenteditable="plaintext-only"], [role="textbox"], textarea'))
                .filter(visible)
                .sort((a, b) => b.getBoundingClientRect().bottom - a.getBoundingClientRect().bottom);
            const input = candidates[0] || null;
            if (!input) return {{ ok: false, mode: 'no-input', observedLength: 0, expectedLength: t.length }};
            const observed = () => String(
                input.tagName && input.tagName.toLowerCase() === 'textarea'
                    ? (input.value || '')
                    : (input.innerText || input.textContent || '')
            );
            const fireInputEvents = (data) => {{
                try {{
                    input.dispatchEvent(new InputEvent('beforeinput', {{
                        bubbles: true,
                        cancelable: true,
                        composed: true,
                        inputType: 'insertText',
                        data
                    }}));
                }} catch (err) {{}}
                try {{
                    input.dispatchEvent(new InputEvent('input', {{
                        bubbles: true,
                        cancelable: true,
                        composed: true,
                        inputType: 'insertText',
                        data
                    }}));
                }} catch (err) {{
                    input.dispatchEvent(new Event('input', {{ bubbles: true, cancelable: true, composed: true }}));
                }}
                input.dispatchEvent(new Event('change', {{ bubbles: true, cancelable: true, composed: true }}));
                input.dispatchEvent(new KeyboardEvent('keyup', {{ key: ' ', code: 'Space', bubbles: true, composed: true }}));
            }};
            input.focus();
            input.click && input.click();
            if (input.tagName && input.tagName.toLowerCase() === 'textarea') {{
                const setter = Object.getOwnPropertyDescriptor(
                    HTMLTextAreaElement.prototype, 'value').set;
                setter.call(input, t);
                fireInputEvents(t);
                const value = observed();
                return {{ ok: value.length > 0 || t.length === 0, mode: 'textarea', observedLength: value.length, expectedLength: t.length }};
            }}
            const selection = window.getSelection && window.getSelection();
            if (selection && document.createRange) {{
                const range = document.createRange();
                range.selectNodeContents(input);
                selection.removeAllRanges();
                selection.addRange(range);
            }}
            document.execCommand('selectAll', false, null);
            document.execCommand('insertText', false, t);
            fireInputEvents(t);
            let value = observed();
            if (t.length > 0 && value.length === 0) {{
                input.textContent = '';
                input.appendChild(document.createTextNode(t));
                fireInputEvents(t);
                value = observed();
            }}
            return {{ ok: value.length > 0 || t.length === 0, mode: 'contenteditable', observedLength: value.length, expectedLength: t.length }};
        }})()
        """
        def after(result):
            if callback:
                callback(result if isinstance(result, dict) else {})
        if callback:
            view.page().runJavaScript(js, after)
        else:
            view.page().runJavaScript(js)

    def _prepare_web_upload_file_payloads(self, paths: list[str], max_bytes: int = 25 * 1024 * 1024) -> list[dict]:
        payloads = []
        for path in paths or []:
            path = str(path)
            if not path or not os.path.exists(path) or not os.path.isfile(path):
                continue
            try:
                if os.path.getsize(path) > max_bytes:
                    continue
                with open(path, 'rb') as fh:
                    encoded = base64.b64encode(fh.read()).decode('ascii')
            except Exception:
                continue
            payloads.append({
                'name': os.path.basename(path),
                'mime': mimetypes.guess_type(path)[0] or 'application/octet-stream',
                'b64': encoded,
            })
        return payloads

    def _wait_for_web_attachment_presence(self,
                                          view: QWebEngineView,
                                          expected_names: list[str] | None = None,
                                          timeout_ms: int = 6000,
                                          interval_ms: int = 350,
                                          callback=None):
        names = [
            os.path.basename(str(name)).lower()
            for name in (expected_names or [])
            if str(name).strip()
        ]
        started_at = time.monotonic()
        names_json = json.dumps(names, ensure_ascii=False)
        probe_js = """
        (function() {
            const names = __EXPECTED_NAMES__;
            const visible = (node) => {
                if (!node) return false;
                const rect = node.getBoundingClientRect();
                const style = window.getComputedStyle(node);
                return rect.width > 8 && rect.height > 8 && style.display !== 'none' && style.visibility !== 'hidden';
            };
            const textOf = (node) => [
                node.innerText,
                node.getAttribute && node.getAttribute('aria-label'),
                node.getAttribute && node.getAttribute('title'),
                node.getAttribute && node.getAttribute('data-testid'),
                node.getAttribute && node.getAttribute('alt'),
                node.id,
                node.className
            ].filter(Boolean).join(' ').toLowerCase();
            const input = document.querySelector('div[contenteditable="true"], [contenteditable="plaintext-only"], [role="textbox"], textarea');
            const composerCandidates = [
                input && input.closest('form'),
                input && input.closest('[data-testid*="composer"]'),
                input && input.closest('[class*="composer"]'),
                input && input.closest('[class*="prompt"]'),
                input && input.parentElement && input.parentElement.parentElement,
                input && input.parentElement
            ].filter(node => node && visible(node));
            const area = (node) => {
                const rect = node.getBoundingClientRect();
                return rect.width * rect.height;
            };
            const composer = composerCandidates
                .sort((a, b) => area(b) - area(a))
                .find(node => {
                    const rect = node.getBoundingClientRect();
                    return rect.width >= 180 && rect.height >= 36;
                }) || null;
            const composerRect = composer ? composer.getBoundingClientRect() : null;
            const inAttachmentArea = (node) => {
                if (!node) return false;
                const rect = node.getBoundingClientRect();
                if (!composerRect) {
                    return rect.top > window.innerHeight * 0.32;
                }
                return rect.bottom >= composerRect.top - 120
                    && rect.top <= composerRect.bottom + 80
                    && rect.right >= composerRect.left - 40
                    && rect.left <= composerRect.right + 40;
            };
            const scopedVisible = Array.from(document.querySelectorAll('body *'))
                .filter(node => visible(node) && inAttachmentArea(node));
            if (names.length) {
                const named = scopedVisible.find(node => {
                    const text = textOf(node);
                    return names.some(name => name && text.includes(name));
                });
                if (named) return { present: true, reason: 'filename' };
            }
            const attachmentLike = scopedVisible.find(node => {
                const tag = String(node.tagName || '').toLowerCase();
                const text = textOf(node);
                const isControl = tag === 'button'
                    || tag === 'label'
                    || node.getAttribute('role') === 'button'
                    || /(remove|delete|trash|close|clear|attach|upload|削除|消去|删除|移除|上传|アップロード)/.test(text);
                if (!isControl && /(attachment|attached|thumbnail|preview|image attached|file attached|添付済|附件已添加|已添加附件)/.test(text)) return true;
                if (['img', 'canvas', 'figure', 'picture'].includes(tag) || node.getAttribute('role') === 'img') {
                    const rect = node.getBoundingClientRect();
                    return rect.width >= 24 && rect.height >= 24;
                }
                if (!isControl) {
                    const rect = node.getBoundingClientRect();
                    const style = window.getComputedStyle(node);
                    const hasBgImage = style.backgroundImage && style.backgroundImage !== 'none' && /url\\(/.test(style.backgroundImage);
                    if (hasBgImage && rect.width >= 24 && rect.height >= 24) return true;
                    if (/(attachment|attached|thumbnail|preview|image|file|upload)/.test(text)
                        && rect.width >= 36
                        && rect.height >= 24
                        && node.querySelector('img, canvas, figure, picture, [role="img"]')) {
                        return true;
                    }
                }
                return false;
            });
            if (attachmentLike) return { present: true, reason: 'attachment-node' };
            const busy = scopedVisible.find(node => {
                const text = textOf(node);
                return node.getAttribute('role') === 'progressbar'
                    || node.getAttribute('aria-busy') === 'true'
                    || /(uploading|upload in progress|attaching|processing file|processing image|正在上传|上传中|処理中|アップロード中)/.test(text);
            });
            if (busy) return { present: true, reason: 'uploading' };
            return { present: false, reason: 'not-found' };
        })()
        """.replace('__EXPECTED_NAMES__', names_json)

        def probe():
            if time.monotonic() - started_at > max(1, timeout_ms) / 1000:
                if callback:
                    callback(False)
                return
            try:
                page = view.page()
            except Exception:
                if callback:
                    callback(False)
                return

            def after(result):
                result = result if isinstance(result, dict) else {}
                if bool(result.get('present')):
                    if callback:
                        callback(True)
                    return
                QTimer.singleShot(max(100, int(interval_ms)), probe)

            try:
                page.runJavaScript(probe_js, after)
            except Exception:
                QTimer.singleShot(max(100, int(interval_ms)), probe)

        probe()

    @staticmethod
    def _chatgpt_external_attachment_probe_js(expected_names: list[str] | None = None) -> str:
        """ChatGPT-only attachment state.  Count real removable file chips, not
        arbitrary filename text in the (very large) composer prompt, and surface
        provider upload dialogs before any presence result is accepted."""
        names = [
            os.path.basename(str(name)).strip().lower()
            for name in (expected_names or [])
            if str(name).strip()
        ]
        names_json = json.dumps(names, ensure_ascii=False)
        return r"""
        (function() {
            const names = __EXPECTED_NAMES__;
            const visible = (node) => {
                if (!node) return false;
                const rect = node.getBoundingClientRect();
                const style = window.getComputedStyle(node);
                return rect.width > 4 && rect.height > 4
                    && style.display !== 'none' && style.visibility !== 'hidden'
                    && Number(style.opacity || 1) > 0.01;
            };
            const token = (node) => [
                node && node.innerText,
                node && node.getAttribute && node.getAttribute('aria-label'),
                node && node.getAttribute && node.getAttribute('title'),
                node && node.getAttribute && node.getAttribute('data-testid'),
                node && node.id,
                node && node.className
            ].filter(Boolean).join(' ').replace(/\s+/g, ' ').trim().toLowerCase();
            const uploadErrorRe = /(already uploaded|try uploading something new|upload failed|failed to upload|could not upload|couldn't upload|unsupported file|file is too large|文件.*上传失败|无法上传|上传失败|アップロード.*失敗)/i;
            const dialogs = Array.from(document.querySelectorAll('[role="dialog"], [role="alertdialog"]'))
                .filter(visible);
            const errorDialog = dialogs.find(node => uploadErrorRe.test(token(node))) || null;
            const dialogText = errorDialog
                ? String(errorDialog.innerText || errorDialog.textContent || '').replace(/\s+/g, ' ').trim().slice(0, 500)
                : '';
            const controls = Array.from(document.querySelectorAll('button, [role="button"]')).filter(visible);
            const removeControls = controls.filter(node => {
                const text = token(node);
                return /(remove file|remove attachment|delete file|delete attachment|移除文件|删除文件|移除附件|删除附件|ファイルを削除|添付.*削除)/i.test(text);
            });
            const counts = {};
            Array.from(new Set(names)).forEach(name => {
                counts[name] = removeControls.filter(node => token(node).includes(name)).length;
            });
            const input = Array.from(document.querySelectorAll('div[contenteditable="true"], [contenteditable="plaintext-only"], [role="textbox"], textarea'))
                .filter(visible)
                .sort((a, b) => b.getBoundingClientRect().bottom - a.getBoundingClientRect().bottom)[0] || null;
            const composer = input && input.closest ? (input.closest('form') || input.parentElement) : null;
            const busyNodes = composer
                ? Array.from(composer.querySelectorAll('[role="progressbar"], [aria-busy="true"], [role="status"], [aria-live]')).filter(visible)
                : [];
            const busy = busyNodes.some(node => {
                const text = token(node);
                return node.getAttribute('role') === 'progressbar'
                    || node.getAttribute('aria-busy') === 'true'
                    || /(uploading|upload in progress|attaching|processing file|processing image|正在上传|上传中|処理中|アップロード中)/i.test(text);
            });
            return {
                counts,
                chip_count: removeControls.length,
                busy,
                upload_error: !!errorDialog,
                dialog_text: dialogText
            };
        })()
        """.replace('__EXPECTED_NAMES__', names_json)

    def _probe_chatgpt_external_attachment_state(self, view, expected_names, callback) -> None:
        js = self._chatgpt_external_attachment_probe_js(expected_names)

        def after(result):
            if callback:
                callback(result if isinstance(result, dict) else {})

        try:
            view.page().runJavaScript(js, after)
        except Exception:
            if callback:
                QTimer.singleShot(0, lambda: callback({}))

    def _cleanup_chatgpt_external_attachment_state(self,
                                                    view,
                                                    expected_names,
                                                    callback=None,
                                                    timeout_ms: int = 4500) -> None:
        """Before a new external-target attempt, dismiss only known upload-error
        dialogs and remove stale chips for this run's filenames.  The failure
        dialog produced by the CURRENT attempt is deliberately left visible so
        the menu-bar inspector can reveal the exact provider error."""
        names = [
            os.path.basename(str(name)).strip().lower()
            for name in (expected_names or [])
            if str(name).strip()
        ]
        names_json = json.dumps(names, ensure_ascii=False)
        started_at = time.monotonic()
        finished = {'done': False}
        cleanup_js = r"""
        (function() {
            const names = __EXPECTED_NAMES__;
            const visible = (node) => {
                if (!node) return false;
                const rect = node.getBoundingClientRect();
                const style = window.getComputedStyle(node);
                return rect.width > 4 && rect.height > 4
                    && style.display !== 'none' && style.visibility !== 'hidden';
            };
            const token = (node) => [
                node && node.innerText,
                node && node.getAttribute && node.getAttribute('aria-label'),
                node && node.getAttribute && node.getAttribute('title'),
                node && node.getAttribute && node.getAttribute('data-testid')
            ].filter(Boolean).join(' ').replace(/\s+/g, ' ').trim().toLowerCase();
            const uploadErrorRe = /(already uploaded|try uploading something new|upload failed|failed to upload|could not upload|couldn't upload|unsupported file|file is too large|文件.*上传失败|无法上传|上传失败|アップロード.*失敗)/i;
            let dismissed = 0;
            for (const dialog of Array.from(document.querySelectorAll('[role="dialog"], [role="alertdialog"]')).filter(visible)) {
                if (!uploadErrorRe.test(token(dialog))) continue;
                const button = Array.from(dialog.querySelectorAll('button, [role="button"]')).find(node => {
                    const text = String(node.innerText || node.getAttribute('aria-label') || node.getAttribute('title') || '')
                        .replace(/\s+/g, ' ').trim().toLowerCase();
                    return /^(ok|okay|close|dismiss|知道了|确定|好的|閉じる)$/.test(text);
                });
                if (button) { try { button.click(); dismissed += 1; } catch (err) {} }
            }
            let removed = 0;
            for (const node of Array.from(document.querySelectorAll('button, [role="button"]')).filter(visible)) {
                const text = token(node);
                const remove = /(remove file|remove attachment|delete file|delete attachment|移除文件|删除文件|移除附件|删除附件|ファイルを削除|添付.*削除)/i.test(text);
                if (!remove || !names.some(name => name && text.includes(name))) continue;
                try { node.click(); removed += 1; } catch (err) {}
            }
            return { dismissed, removed };
        })()
        """.replace('__EXPECTED_NAMES__', names_json)

        def finish(ok: bool, reason: str, state=None):
            if finished.get('done'):
                return
            finished['done'] = True
            if callback:
                callback(bool(ok), str(reason or ''), state if isinstance(state, dict) else {})

        def verify_clean():
            def after_state(state):
                state = state if isinstance(state, dict) else {}
                counts = state.get('counts') if isinstance(state.get('counts'), dict) else {}
                stale = any(int(counts.get(name, 0) or 0) > 0 for name in set(names))
                if not stale and not bool(state.get('upload_error')):
                    finish(True, 'chatgpt-preflight-clean', state)
                    return
                if time.monotonic() - started_at >= max(1, timeout_ms) / 1000:
                    finish(False, 'chatgpt-preflight-cleanup-timeout', state)
                    return
                run_cleanup()

            self._probe_chatgpt_external_attachment_state(view, names, after_state)

        def run_cleanup():
            try:
                view.page().runJavaScript(cleanup_js, lambda _result: QTimer.singleShot(280, verify_clean))
            except Exception:
                if time.monotonic() - started_at >= max(1, timeout_ms) / 1000:
                    finish(False, 'chatgpt-preflight-cleanup-js-error', {})
                else:
                    QTimer.singleShot(280, run_cleanup)

        run_cleanup()

    def _inject_chatgpt_external_files(self, view, paths, transport: str, callback=None) -> None:
        """Dispatch exactly ONE file transport for ChatGPT external targets."""
        mode = str(transport or '').strip().lower()
        if mode not in {'drop', 'paste'}:
            if callback:
                QTimer.singleShot(0, lambda: callback({'ok': False, 'reason': 'invalid-transport'}))
            return
        payloads = self._prepare_web_upload_file_payloads(paths)
        if not payloads:
            if callback:
                QTimer.singleShot(0, lambda: callback({'ok': False, 'reason': 'no-files'}))
            return
        payload_json = json.dumps(payloads, ensure_ascii=False)
        mode_json = json.dumps(mode)
        js = f"""
        (function() {{
            const payloads = {payload_json};
            const transport = {mode_json};
            const visible = (node) => {{
                if (!node) return false;
                const rect = node.getBoundingClientRect();
                const style = window.getComputedStyle(node);
                return rect.width > 0 && rect.height > 0 && style.display !== 'none' && style.visibility !== 'hidden';
            }};
            const b64ToBytes = (b64) => {{
                const bin = atob(b64);
                const bytes = new Uint8Array(bin.length);
                for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
                return bytes;
            }};
            const files = payloads.map(item => new File(
                [b64ToBytes(item.b64)], item.name || 'attachment',
                {{ type: item.mime || 'application/octet-stream', lastModified: Date.now() }}
            ));
            const target = Array.from(document.querySelectorAll('[contenteditable="true"], textarea'))
                .filter(visible)
                .sort((a, b) => b.getBoundingClientRect().bottom - a.getBoundingClientRect().bottom)[0]
                || Array.from(document.querySelectorAll('[data-testid*="composer"], form, main'))
                    .filter(visible)
                    .sort((a, b) => b.getBoundingClientRect().bottom - a.getBoundingClientRect().bottom)[0]
                || document.body;
            if (!target || !files.length) return {{ ok: false, reason: !target ? 'no-target' : 'no-files' }};
            target.focus && target.focus();
            target.click && target.click();
            const makeDataTransfer = () => {{
                const dt = new DataTransfer();
                files.forEach(file => dt.items.add(file));
                return dt;
            }};
            if (transport === 'drop') {{
                const dt = makeDataTransfer();
                for (const type of ['dragenter', 'dragover', 'drop']) {{
                    target.dispatchEvent(new DragEvent(type, {{
                        bubbles: true, cancelable: true, composed: true, dataTransfer: dt
                    }}));
                }}
            }} else {{
                const dt = makeDataTransfer();
                try {{
                    target.dispatchEvent(new ClipboardEvent('paste', {{
                        bubbles: true, cancelable: true, composed: true, clipboardData: dt
                    }}));
                }} catch (err) {{
                    const ev = new Event('paste', {{ bubbles: true, cancelable: true, composed: true }});
                    Object.defineProperty(ev, 'clipboardData', {{ value: dt }});
                    target.dispatchEvent(ev);
                }}
            }}
            return {{ ok: true, transport, file_count: files.length, names: files.map(file => file.name) }};
        }})()
        """

        def after(result):
            if callback:
                callback(result if isinstance(result, dict) else {'ok': False, 'reason': 'invalid-js-result'})

        try:
            view.page().runJavaScript(js, after)
        except Exception:
            if callback:
                QTimer.singleShot(0, lambda: callback({'ok': False, 'reason': 'js-error'}))

    def _wait_for_chatgpt_external_attachment_delta(self,
                                                     view,
                                                     expected_names,
                                                     baseline_counts,
                                                     callback=None,
                                                     timeout_ms: int = 6000,
                                                     interval_ms: int = 350) -> None:
        names = [
            os.path.basename(str(name)).strip().lower()
            for name in (expected_names or [])
            if str(name).strip()
        ]
        required = {}
        for name in names:
            required[name] = int(required.get(name, 0)) + 1
        baseline = baseline_counts if isinstance(baseline_counts, dict) else {}
        baseline = {name: int(baseline.get(name, 0) or 0) for name in required}
        started_at = time.monotonic()
        tracker = {'done': False, 'stable_hits': 0, 'ever_busy': False, 'max_added': 0}

        def finish(ok: bool, reason: str, state=None):
            if tracker.get('done'):
                return
            tracker['done'] = True
            payload = dict(state) if isinstance(state, dict) else {}
            payload['ever_busy'] = bool(tracker.get('ever_busy'))
            payload['max_added'] = int(tracker.get('max_added', 0) or 0)
            if callback:
                callback(bool(ok), str(reason or ''), payload)

        if not required:
            finish(True, 'chatgpt-no-files', {})
            return

        def probe():
            def after_state(state):
                state = state if isinstance(state, dict) else {}
                if bool(state.get('upload_error')):
                    detail = str(state.get('dialog_text', '') or '').strip()
                    finish(False, 'chatgpt-upload-error' + (f': {detail}' if detail else ''), state)
                    return
                counts = state.get('counts') if isinstance(state.get('counts'), dict) else {}
                deltas = {
                    name: max(0, int(counts.get(name, 0) or 0) - int(baseline.get(name, 0) or 0))
                    for name in required
                }
                added = sum(deltas.values())
                tracker['max_added'] = max(int(tracker.get('max_added', 0) or 0), added)
                tracker['ever_busy'] = bool(tracker.get('ever_busy')) or bool(state.get('busy'))
                state['deltas'] = deltas
                complete = all(int(deltas.get(name, 0)) >= count for name, count in required.items())
                if complete:
                    tracker['stable_hits'] = int(tracker.get('stable_hits', 0)) + 1
                    if tracker['stable_hits'] >= 2:
                        finish(True, 'chatgpt-all-attachments-new', state)
                        return
                else:
                    tracker['stable_hits'] = 0
                if time.monotonic() - started_at >= max(1, timeout_ms) / 1000:
                    if int(tracker.get('max_added', 0) or 0) > 0:
                        reason = 'chatgpt-partial-attachment-presence'
                    elif bool(tracker.get('ever_busy')):
                        reason = 'chatgpt-upload-busy-timeout'
                    else:
                        reason = 'chatgpt-no-new-attachments'
                    finish(False, reason, state)
                    return
                QTimer.singleShot(max(100, int(interval_ms)), probe)

            self._probe_chatgpt_external_attachment_state(view, names, after_state)

        probe()

    def _inject_files_to_claude_by_drop(self, view: QWebEngineView, paths: list[str], fallback_callback=None, callback=None):
        payloads = self._prepare_web_upload_file_payloads(paths)
        if not payloads:
            if fallback_callback:
                QTimer.singleShot(0, fallback_callback)
            elif callback:
                QTimer.singleShot(0, callback)
            return
        payload_json = json.dumps(payloads, ensure_ascii=False)
        js = f"""
        (async function() {{
            const payloads = {payload_json};
            const visible = (node) => {{
                if (!node) return false;
                const rect = node.getBoundingClientRect();
                const style = window.getComputedStyle(node);
                return rect.width > 0 && rect.height > 0 && style.display !== 'none' && style.visibility !== 'hidden';
            }};
            const b64ToBytes = (b64) => {{
                const bin = atob(b64);
                const bytes = new Uint8Array(bin.length);
                for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
                return bytes;
            }};
            const files = payloads.map(item => new File(
                [b64ToBytes(item.b64)],
                item.name || 'attachment',
                {{ type: item.mime || 'application/octet-stream', lastModified: Date.now() }}
            ));
            if (!files.length) return 'no-files';
            const target =
                Array.from(document.querySelectorAll('[contenteditable="true"], textarea'))
                    .filter(visible)
                    .sort((a, b) => b.getBoundingClientRect().bottom - a.getBoundingClientRect().bottom)[0]
                || Array.from(document.querySelectorAll('[data-testid*="composer"], form, main'))
                    .filter(visible)
                    .sort((a, b) => b.getBoundingClientRect().bottom - a.getBoundingClientRect().bottom)[0]
                || document.body;
            if (!target) return 'no-target';
            target.focus && target.focus();
            target.click && target.click();
            const makeDataTransfer = () => {{
                const dt = new DataTransfer();
                files.forEach(file => dt.items.add(file));
                return dt;
            }};
            const dragDt = makeDataTransfer();
            for (const type of ['dragenter', 'dragover', 'drop']) {{
                target.dispatchEvent(new DragEvent(type, {{
                    bubbles: true,
                    cancelable: true,
                    composed: true,
                    dataTransfer: dragDt
                }}));
            }}
            const pasteDt = makeDataTransfer();
            try {{
                target.dispatchEvent(new ClipboardEvent('paste', {{
                    bubbles: true,
                    cancelable: true,
                    composed: true,
                    clipboardData: pasteDt
                }}));
            }} catch (err) {{
                const ev = new Event('paste', {{ bubbles: true, cancelable: true, composed: true }});
                Object.defineProperty(ev, 'clipboardData', {{ value: pasteDt }});
                target.dispatchEvent(ev);
            }}
            return 'dropped';
        }})()
        """

        def after(result):
            if str(result or '') == 'dropped':
                if callback:
                    QTimer.singleShot(0, callback)
            elif fallback_callback:
                QTimer.singleShot(0, fallback_callback)
            elif callback:
                QTimer.singleShot(0, callback)

        try:
            view.page().runJavaScript(js, after)
        except Exception:
            if fallback_callback:
                QTimer.singleShot(0, fallback_callback)
            elif callback:
                QTimer.singleShot(0, callback)

    def _inject_files_to_web_by_drop(self, view: QWebEngineView, paths: list[str], fallback_callback=None, callback=None):
        self._inject_files_to_claude_by_drop(
            view,
            paths,
            fallback_callback=fallback_callback,
            callback=callback,
        )

    def _upload_external_web_target_attachments(self,
                                                view: QWebEngineView,
                                                paths: list[str],
                                                callback=None,
                                                *,
                                                target=None):
        upload_paths = []
        seen = set()
        for path in paths or []:
            value = str(path or '').strip()
            if not value or not os.path.exists(value) or not os.path.isfile(value):
                continue
            value = os.path.abspath(value)
            if value in seen:
                continue
            seen.add(value)
            upload_paths.append(value)
        if not upload_paths:
            if callback:
                QTimer.singleShot(0, lambda: callback(True, 'no-files'))
            return
        names = [os.path.basename(path) for path in upload_paths]
        finished = {'done': False}

        def finish(ok: bool, reason: str):
            if finished.get('done'):
                return
            finished['done'] = True
            if callback:
                callback(bool(ok), str(reason or ''))

        # ChatGPT external targets need a provider-specific handoff.  The legacy
        # helper deliberately dispatches BOTH drop and paste for broad Claude/Web
        # compatibility; current ChatGPT accepts both and rejects the second copy.
        # Keep every other provider byte-for-byte on the old path below.
        if self._external_target_is_chatgpt(target, view):
            def start_chatgpt_upload():
                def after_cleanup(ok: bool, reason: str, state):
                    state = state if isinstance(state, dict) else {}
                    if not bool(ok):
                        finish(False, reason or 'chatgpt-preflight-cleanup-failed')
                        return
                    baseline = state.get('counts') if isinstance(state.get('counts'), dict) else {}

                    def after_paste_wait(paste_ok: bool, paste_reason: str, _paste_state):
                        if bool(paste_ok):
                            finish(True, 'chatgpt-paste-all-confirmed')
                        else:
                            finish(False, paste_reason or 'chatgpt-paste-presence-timeout')

                    def after_paste_dispatch(result):
                        result = result if isinstance(result, dict) else {}
                        if not bool(result.get('ok')):
                            finish(False, 'chatgpt-paste-dispatch-' + str(result.get('reason', 'failed') or 'failed'))
                            return
                        QTimer.singleShot(
                            700,
                            lambda: self._wait_for_chatgpt_external_attachment_delta(
                                view,
                                names,
                                baseline,
                                callback=after_paste_wait,
                                timeout_ms=45000,
                                interval_ms=350,
                            ),
                        )

                    def after_drop_wait(drop_ok: bool, drop_reason: str, drop_state):
                        drop_state = drop_state if isinstance(drop_state, dict) else {}
                        if bool(drop_ok):
                            finish(True, 'chatgpt-drop-all-confirmed')
                            return
                        # Paste is a true fallback, never a second simultaneous
                        # delivery: only use it when drop produced ZERO chips and
                        # the page never reported upload activity or an error.
                        can_fallback = (
                            str(drop_reason or '') == 'chatgpt-no-new-attachments'
                            and int(drop_state.get('max_added', 0) or 0) == 0
                            and not bool(drop_state.get('ever_busy'))
                        )
                        if not can_fallback:
                            finish(False, drop_reason or 'chatgpt-drop-presence-timeout')
                            return
                        self._inject_chatgpt_external_files(
                            view,
                            upload_paths,
                            'paste',
                            callback=after_paste_dispatch,
                        )

                    def after_drop_dispatch(result):
                        result = result if isinstance(result, dict) else {}
                        if not bool(result.get('ok')):
                            finish(False, 'chatgpt-drop-dispatch-' + str(result.get('reason', 'failed') or 'failed'))
                            return
                        QTimer.singleShot(
                            700,
                            lambda: self._wait_for_chatgpt_external_attachment_delta(
                                view,
                                names,
                                baseline,
                                callback=after_drop_wait,
                                timeout_ms=6000,
                                interval_ms=350,
                            ),
                        )

                    self._inject_chatgpt_external_files(
                        view,
                        upload_paths,
                        'drop',
                        callback=after_drop_dispatch,
                    )

                self._cleanup_chatgpt_external_attachment_state(
                    view,
                    names,
                    callback=after_cleanup,
                )

            self._activate_web_composer(view, callback=start_chatgpt_upload)
            return

        def wait_for_presence():
            QTimer.singleShot(
                1400,
                lambda: self._wait_for_web_attachment_presence(
                    view,
                    names,
                    timeout_ms=45000,
                    interval_ms=350,
                    callback=lambda ok: finish(bool(ok), 'presence-confirmed' if ok else 'presence-timeout'),
                ),
            )

        def start_drop():
            self._inject_files_to_web_by_drop(
                view,
                upload_paths,
                fallback_callback=wait_for_presence,
                callback=wait_for_presence,
            )

        self._activate_web_composer(view, callback=start_drop)

    def _submit_grok_with_button(self, view: QWebEngineView):
        js = """
        (function() {
            const visible = (node) => {
                if (!node) return false;
                const rect = node.getBoundingClientRect();
                const style = window.getComputedStyle(node);
                return rect.width > 8
                    && rect.height > 8
                    && style.display !== 'none'
                    && style.visibility !== 'hidden'
                    && Number(style.opacity || 1) > 0.01;
            };
            const disabled = (node) => {
                const className = String(node.className || '');
                return node.disabled
                    || node.getAttribute('aria-disabled') === 'true'
                    || node.getAttribute('disabled') !== null
                    || /(?:^|\\s)(disabled|is-disabled)(?:\\s|$)/i.test(className);
            };
            const buttons = Array.from(document.querySelectorAll('button'));
            const btn = buttons.find(node => {
                if (!visible(node) || disabled(node)) return false;
                const label = String(node.getAttribute('aria-label') || '').trim().toLowerCase();
                const testid = String(node.getAttribute('data-testid') || '').trim().toLowerCase();
                const type = String(node.getAttribute('type') || '').trim().toLowerCase();
                return label === 'submit' && (testid === 'chat-submit' || type === 'submit');
            });
            if (!btn) return null;
            const rect = btn.getBoundingClientRect();
            return {
                x: Math.max(8, Math.min(window.innerWidth - 8, rect.left + rect.width / 2)),
                y: Math.max(8, Math.min(window.innerHeight - 8, rect.top + rect.height / 2))
            };
        })()
        """

        def after(result):
            if isinstance(result, dict) and result.get('x') is not None and result.get('y') is not None:
                self._send_web_view_mouse_click(view, float(result.get('x')), float(result.get('y')))

        try:
            view.page().runJavaScript(js, after)
        except Exception:
            pass

    def _submit_perplexity_with_button(self, view: QWebEngineView):
        js = """
        (function() {
            const visible = (node) => {
                if (!node) return false;
                const rect = node.getBoundingClientRect();
                const style = window.getComputedStyle(node);
                return rect.width > 8
                    && rect.height > 8
                    && style.display !== 'none'
                    && style.visibility !== 'hidden'
                    && Number(style.opacity || 1) > 0.01;
            };
            const disabled = (node) => {
                const className = String(node.className || '');
                return node.disabled
                    || node.getAttribute('aria-disabled') === 'true'
                    || node.getAttribute('disabled') !== null
                    || /(?:^|\\s)(disabled|is-disabled)(?:\\s|$)/i.test(className);
            };
            const btn = Array.from(document.querySelectorAll('button')).find(node => {
                if (!visible(node) || disabled(node)) return false;
                const label = String(node.getAttribute('aria-label') || '').trim().toLowerCase();
                const type = String(node.getAttribute('type') || '').trim().toLowerCase();
                return label === 'submit' && type === 'button';
            });
            if (!btn) return null;
            const rect = btn.getBoundingClientRect();
            return {
                x: Math.max(8, Math.min(window.innerWidth - 8, rect.left + rect.width / 2)),
                y: Math.max(8, Math.min(window.innerHeight - 8, rect.top + rect.height / 2))
            };
        })()
        """

        def after(result):
            if isinstance(result, dict) and result.get('x') is not None and result.get('y') is not None:
                self._send_web_view_mouse_click(view, float(result.get('x')), float(result.get('y')))

        try:
            view.page().runJavaScript(js, after)
        except Exception:
            pass

    def _click_web_view_send_button(self, view: QWebEngineView):
        claude = self._is_claude_web_view(view)
        if claude:
            self._submit_claude_with_shortcut(view)
            return
        if self._is_grok_web_view(view):
            self._submit_grok_with_button(view)
            return
        if self._is_perplexity_web_view(view):
            self._submit_perplexity_with_button(view)
            return
        js = """
        (function() {
            const visible = (node) => {
                if (!node) return false;
                const rect = node.getBoundingClientRect();
                const style = window.getComputedStyle(node);
                return rect.width > 8 && rect.height > 8 && style.display !== 'none' && style.visibility !== 'hidden';
            };
            const disabled = (node) => {
                const className = String(node.className || '');
                return node.disabled
                    || node.getAttribute('aria-disabled') === 'true'
                    || node.getAttribute('disabled') !== null
                    || /(?:^|\\s)(disabled|is-disabled)(?:\\s|$)/i.test(className);
            };
            const clickButton = (btn) => {
                btn.focus && btn.focus();
                btn.dispatchEvent(new PointerEvent('pointerdown', {bubbles: true, cancelable: true, composed: true, pointerType: 'mouse'}));
                btn.dispatchEvent(new MouseEvent('mousedown', {bubbles: true, cancelable: true, composed: true}));
                btn.dispatchEvent(new PointerEvent('pointerup', {bubbles: true, cancelable: true, composed: true, pointerType: 'mouse'}));
                btn.dispatchEvent(new MouseEvent('mouseup', {bubbles: true, cancelable: true, composed: true}));
                btn.dispatchEvent(new MouseEvent('click', {bubbles: true, cancelable: true, composed: true}));
            };
            const buttons = Array.from(document.querySelectorAll('button, [role="button"]'));
            const candidates = buttons.filter(btn => {
                if (!visible(btn) || disabled(btn)) return false;
                const text = [
                    btn.innerText,
                    btn.getAttribute('aria-label'),
                    btn.getAttribute('title'),
                    btn.getAttribute('data-testid')
                ].filter(Boolean).join(' ').toLowerCase();
                if (/(stop|cancel|停止|中止|キャンセル|voice|mic|microphone|audio|dictate)/.test(text)) return false;
                return /(send|submit|发送|送信|送出|送信する|送出する)/.test(text);
            });
            if (candidates.length) {
                clickButton(candidates[candidates.length - 1]);
                return 'button';
            }
            const input = document.querySelector('div[contenteditable="true"], [contenteditable="plaintext-only"], [role="textbox"], textarea');
            if (input) {
                input.focus();
                const opts = {
                    key: 'Enter',
                    code: 'Enter',
                    bubbles: true,
                    cancelable: true,
                    composed: true,
                    metaKey: false,
                    ctrlKey: false,
                    shiftKey: false,
                    altKey: false
                };
                input.dispatchEvent(new KeyboardEvent('keydown', opts));
                input.dispatchEvent(new KeyboardEvent('keypress', opts));
                input.dispatchEvent(new KeyboardEvent('keyup', opts));
                return 'enter';
            }
            return 'not-found';
        })()
        """
        try:
            view.page().runJavaScript(js)
        except Exception:
            pass

    def _wait_then_click_web_send_button(self,
                                         view: QWebEngineView,
                                         timeout_ms: int = 15000,
                                         interval_ms: int = 450,
                                         stable_hits: int = 2,
                                         callback=None,
                                         show_error: bool = True,
                                         caller: str = '',
                                         result_callback=None):
        claude = self._is_claude_web_view(view)
        caller = str(caller or '').strip()

        def skipped_message() -> tuple[str, str]:
            title = _tr('Auto send skipped')
            if caller:
                title = _tr('Auto send skipped ({caller})').format(caller=caller)
            if caller == 'online_memory':
                return (
                    title,
                    _tr('The web page did not finish enabling Send for the online memory prompt. The prompt was left in the page.'),
                )
            if caller in {'web_forward', 'web_cross_forward'}:
                return (
                    title,
                    _tr('The target web page did not finish enabling Send after forwarded text was inserted. The prompt was left in the page.'),
                )
            if caller.startswith('claude_dock') or caller.startswith('web_dock'):
                return (
                    title,
                    _tr('The web page did not finish enabling Send after the prompt or attachment was added. The prompt and attachment were left in the page.'),
                )
            return (
                title,
                _tr('The web page did not finish enabling Send after the attachment was added. The prompt and attachment were left in the page.'),
            )

        def after_ready(result):
            result = result if isinstance(result, dict) else {}
            if bool(result.get('ready')):
                if claude:
                    log_broccoli_claude(f'send readiness ready; caller={caller or "unknown"}; reason={result.get("reason", "")}')
                self._click_web_view_send_button(view)
                if result_callback:
                    payload = dict(result)
                    payload['clicked'] = True
                    payload['caller'] = caller
                    result_callback(payload)
                if callback:
                    callback(True)
                return
            if claude:
                log_broccoli_claude(f'auto send skipped after timeout; caller={caller or "unknown"}; last_reason={result.get("reason", "")}')
            if show_error:
                title, message = skipped_message()
                show_broccoli_message(
                    self,
                    title,
                    message,
                )
            if result_callback:
                payload = dict(result)
                payload['clicked'] = False
                payload['caller'] = caller
                result_callback(payload)
            if callback:
                callback(False)

        wait_for_web_chat_ready(
            view,
            after_ready,
            timeout_ms=timeout_ms,
            interval_ms=interval_ms,
            stable_hits=stable_hits,
            mode='send',
            allow_text_stability_fallback=False,
        )

    def _inject_images_to_web_view(self, view: QWebEngineView, image_items: list[dict], callback=None):
        items = [item for item in image_items if isinstance(item, dict) and item.get('b64')]
        if not items:
            if callback:
                QTimer.singleShot(0, callback)
            return
        focus_js = """
        (function() {
            const el = document.querySelector('div[contenteditable="true"]')
                    || document.querySelector('textarea');
            if (el) { el.focus(); return true; }
            return false;
        })()
        """

        def paste_next(idx: int):
            if idx >= len(items):
                if callback:
                    QTimer.singleShot(650, callback)
                return
            item = items[idx]
            try:
                raw = base64.b64decode(item.get('b64', ''))
                qimg = QImage.fromData(raw)
            except Exception:
                QTimer.singleShot(50, lambda: paste_next(idx + 1))
                return
            if qimg.isNull():
                QTimer.singleShot(50, lambda: paste_next(idx + 1))
                return
            QGuiApplication.clipboard().setImage(qimg)

            def do_paste(focused):
                if focused:
                    view.page().triggerAction(QWebEnginePage.WebAction.Paste)
                QTimer.singleShot(350, lambda: paste_next(idx + 1))

            view.page().runJavaScript(focus_js, do_paste)

        paste_next(0)

    def _refresh_web_lifecycle_visibility(self, current_index: int | None = None):
        if current_index is None:
            try:
                current_index = self.stacked_widget.currentIndex()
            except Exception:
                current_index = -1
        for tab_index, attr in ((TAB_WEB, 'ai_web_panel'), (TAB_LOCALHOST, 'localhost_panel')):
            panel = getattr(self, attr, None)
            if panel is not None and hasattr(panel, 'set_panel_visible'):
                panel.set_panel_visible(int(current_index) == tab_index)

    def apply_web_lifecycle_settings(self, mode: str | None = None):
        if mode is None:
            mode = load_settings_store().get('globals', {}).get('web_lifecycle_mode', DEFAULT_WEB_LIFECYCLE_MODE)
        mode = normalize_web_lifecycle_mode(mode)
        for attr in ('ai_web_panel', 'localhost_panel'):
            panel = getattr(self, attr, None)
            if panel is not None and hasattr(panel, 'set_lifecycle_mode'):
                panel.set_lifecycle_mode(mode)
        self._refresh_web_lifecycle_visibility()

    def _schedule_deferred_tab_refresh(self, index: int):
        generation = int(getattr(self, '_tab_deferred_refresh_generation', 0) or 0) + 1
        self._tab_deferred_refresh_generation = generation

        def run_deferred():
            if generation != int(getattr(self, '_tab_deferred_refresh_generation', 0) or 0):
                return
            if int(self.stacked_widget.currentIndex()) != int(index):
                return
            started = time.perf_counter()
            force_dark = int(index) == TAB_TERMINAL
            if not getattr(self, '_settings_panel_visible', False):
                self.settings_panel.set_force_dark(force_dark)
            if not getattr(self, '_outputs_panel_visible', False):
                self.outputs_panel.set_force_dark(force_dark)
            theme_done = time.perf_counter()
            self._refresh_agent_conversation_shelf()
            shelf_done = time.perf_counter()
            self._refresh_outputs_panel(render_preview=False)
            finished = time.perf_counter()
            _agent_render_perf_log(
                'tab_deferred_refresh',
                index=int(index),
                outputs_ms=round((finished - shelf_done) * 1000.0, 2),
                shelf_ms=round((shelf_done - theme_done) * 1000.0, 2),
                theme_ms=round((theme_done - started) * 1000.0, 2),
                total_ms=round((finished - started) * 1000.0, 2),
            )

        QTimer.singleShot(0, run_deferred)

    def _on_tab_changed(self, index):
        """Tab 切换时更新 DrawingLayer 可见性和 qw3 背景色。"""
        tab_perf_started = time.perf_counter()
        tab_perf = {
            'background_ms': 0.0,
            'branch_ms': 0.0,
            'common_chrome_ms': 0.0,
            'drawing_ms': 0.0,
            'external_prompt_ms': 0.0,
            'lifecycle_ms': 0.0,
            'outputs_ms': 0.0,
            'overlays_ms': 0.0,
            'setup_ms': 0.0,
            'shelf_ms': 0.0,
            'terminal_chrome_ms': 0.0,
            'terminal_favorites_ms': 0.0,
            'terminal_history_ms': 0.0,
            'theme_ms': 0.0,
        }
        perf_started = time.perf_counter()
        self._install_selection_context_menus()
        self._update_send_shortcut_enabled()
        is_assistant = (index == TAB_API)
        is_terminal = (index == TAB_TERMINAL)
        is_external_prompt_tab = index in EXTERNAL_PROMPT_TAB_INDICES
        if is_assistant:
            self._apply_carryover_targets()
        tab_perf['setup_ms'] = (time.perf_counter() - perf_started) * 1000.0
        perf_started = time.perf_counter()
        self._refresh_web_lifecycle_visibility(index)
        tab_perf['lifecycle_ms'] = (time.perf_counter() - perf_started) * 1000.0
        perf_started = time.perf_counter()
        self.pill_nav.set_theme('dark' if (index == TAB_TERMINAL or is_dark_theme(app)) else 'light')
        self._set_top_chrome_button_theme(index == TAB_TERMINAL or is_dark_theme(app))
        if self._settings_panel_visible:
            self.settings_panel.set_force_dark(index == TAB_TERMINAL)
        if self._outputs_panel_visible:
            self.outputs_panel.set_force_dark(index == TAB_TERMINAL)
        tab_perf['theme_ms'] = (time.perf_counter() - perf_started) * 1000.0
        overlays_started = time.perf_counter()
        if not is_assistant:
            self._history_trigger_btn.hide()
            self._links_trigger_btn.hide()
            self._agent_favorites_trigger_btn.hide()
            self._branch_trigger_btn.hide()
            if hasattr(self, 'webfetch_panel') and not is_external_prompt_tab:
                self.webfetch_panel.hide()
            if self._history_panel_visible:
                self.hide_history_panel()
            if self._links_panel_visible:
                self.hide_links_panel()
            if self._agent_favorites_panel_visible:
                self.hide_agent_favorites_panel()
            if self._branch_panel_visible:
                self.hide_branch_panel()
            if self._share_panel_visible:
                self.hide_share_panel()
            self._text1_popup.hide()
        else:
            self._branch_trigger_btn.show()
            self._branch_trigger_btn.raise_()
            self._raise_webfetch_panel_if_visible()
            self._history_trigger_btn.show()
            self._history_trigger_btn.raise_()
            self._links_trigger_btn.show()
            self._links_trigger_btn.raise_()
            self._agent_favorites_trigger_btn.show()
            self._agent_favorites_trigger_btn.raise_()
            if getattr(self, '_webfetch_records', None) and not getattr(self, '_webfetch_panel_dismissed', False):
                self._show_webfetch_panel()
            self._refresh_text1_popup_visibility()
            perf_started = time.perf_counter()
            self._refresh_branch_state_from_current_conversation()
            tab_perf['branch_ms'] = (time.perf_counter() - perf_started) * 1000.0
            self._refresh_agent_send_button_state()
        tab_perf['overlays_ms'] = (time.perf_counter() - overlays_started) * 1000.0
        perf_started = time.perf_counter()
        self._schedule_deferred_tab_refresh(index)
        tab_perf['shelf_ms'] = (time.perf_counter() - perf_started) * 1000.0
        if not is_terminal:
            perf_started = time.perf_counter()
            self._hide_terminal_side_triggers()
            if self._terminal_history_panel_visible:
                self.hide_terminal_history_panel()
            if self._terminal_favorites_panel_visible:
                self.hide_terminal_favorites_panel()
            tab_perf['terminal_chrome_ms'] = (time.perf_counter() - perf_started) * 1000.0
        else:
            perf_started = time.perf_counter()
            self._refresh_terminal_history_panel()
            tab_perf['terminal_history_ms'] = (time.perf_counter() - perf_started) * 1000.0
            perf_started = time.perf_counter()
            self._refresh_terminal_favorites_panel()
            tab_perf['terminal_favorites_ms'] = (time.perf_counter() - perf_started) * 1000.0
            perf_started = time.perf_counter()
            self._show_terminal_side_triggers()
            tab_perf['terminal_chrome_ms'] = (time.perf_counter() - perf_started) * 1000.0
        perf_started = time.perf_counter()
        self._outputs_trigger_btn.show()
        self._outputs_trigger_btn.raise_()
        tab_perf['common_chrome_ms'] = (time.perf_counter() - perf_started) * 1000.0
        perf_started = time.perf_counter()
        if is_external_prompt_tab:
            self._update_external_prompt_trigger_geometry()
            self._update_web_conversation_sync_button_geometry()
            panel, _dock = self._external_prompt_panel_for_index(index)
            try:
                active_idx = panel.active_index() if panel is not None and hasattr(panel, 'active_index') else 0
                self._schedule_web_conversation_capture(index, active_idx, reason='tab-switch', delay_ms=1800)
            except Exception:
                pass
            if panel is not None and panel.is_prompt_dock_visible() and getattr(self, '_webfetch_records', None) and not getattr(self, '_webfetch_panel_dismissed', False):
                self._show_webfetch_panel()
            elif hasattr(self, 'webfetch_panel'):
                self.webfetch_panel.hide()
        elif hasattr(self, '_external_prompt_trigger_btn'):
            self._external_prompt_trigger_btn.hide()
            if hasattr(self, 'web_conversation_sync_button'):
                self.web_conversation_sync_button.hide()
        tab_perf['external_prompt_ms'] = (time.perf_counter() - perf_started) * 1000.0
        perf_started = time.perf_counter()
        if not self._settings_panel_visible:
            self._settings_trigger_btn.show()
            self._settings_trigger_btn.raise_()
        tab_perf['common_chrome_ms'] += (time.perf_counter() - perf_started) * 1000.0
        # self.btn0_2.setVisible(is_assistant)

        perf_started = time.perf_counter()
        if not is_assistant:
            self.drawing_layer.setVisible(False)
        else:
            is_expanded = (self.i % 2 == 1)
            trans = getattr(self, 'trans', 0)
            is_html_view = (trans % 2 == 0)
            self.drawing_layer.setVisible(is_expanded and is_html_view)
        tab_perf['drawing_ms'] = (time.perf_counter() - perf_started) * 1000.0

        perf_started = time.perf_counter()
        if index == TAB_API:  # Assistant
            self._set_qw3_bg('#2D2D2D' if is_dark_theme(app) else '#FFFFFF')
        elif index == TAB_WEB:   # AI Web
            self._prime_external_tab_background(TAB_WEB)
            _web_view = self.ai_web_panel.active_view()
            if _web_view is not None:
                _web_view.page().runJavaScript(
                    self._BG_JS,
                    lambda color, tab_index=TAB_WEB: self._apply_web_bg(color, tab_index),
                )
        elif index == TAB_LOCALHOST:  # Localhost
            self._prime_external_tab_background(TAB_LOCALHOST)
            _lh_view = self.localhost_panel.active_view()
            if _lh_view is not None:
                _lh_view.page().runJavaScript(
                    self._BG_JS,
                    lambda color, tab_index=TAB_LOCALHOST: self._apply_web_bg(color, tab_index),
                )
        elif index == TAB_TERMINAL:  # Terminal
            self._set_qw3_bg('#2D2D2D', border='#2D2D2D')
        tab_perf['background_ms'] = (time.perf_counter() - perf_started) * 1000.0
        _agent_render_perf_log(
            'tab_changed',
            index=int(index),
            total_ms=round((time.perf_counter() - tab_perf_started) * 1000.0, 2),
            **{key: round(value, 2) for key, value in tab_perf.items()},
        )

    # JS 取背景色：采样 viewport 内可见点，向上寻找最近的不透明背景色。
    _BG_JS = (
        "(function(){"
        "  function opaque(c){"
        "    if(!c||c==='transparent'||c==='rgba(0, 0, 0, 0)') return false;"
        "    var m=c.match(/^rgba\\(([^,]+),([^,]+),([^,]+),([^\\)]+)\\)$/);"
        "    if(m) return parseFloat(m[4])>0.12;"
        "    return true;"
        "  }"
        "  function normalize(c){"
        "    if(!c) return '';"
        "    var m=c.match(/^rgb\\((\\d+),\\s*(\\d+),\\s*(\\d+)\\)$/);"
        "    if(m){"
        "      function hx(n){return Math.max(0,Math.min(255,parseInt(n,10))).toString(16).padStart(2,'0');}"
        "      return '#'+hx(m[1])+hx(m[2])+hx(m[3]);"
        "    }"
        "    return c;"
        "  }"
        "  function bgAt(x,y){"
        "    var el=document.elementFromPoint(x,y);"
        "    while(el){"
        "      var c=getComputedStyle(el).backgroundColor;"
        "      if(opaque(c)) return normalize(c);"
        "      el=el.parentElement;"
        "    }"
        "    return '';"
        "  }"
        "  var w=Math.max(1,window.innerWidth||document.documentElement.clientWidth||1);"
        "  var h=Math.max(1,window.innerHeight||document.documentElement.clientHeight||1);"
        "  var points=["
        "    [0.04,0.04],[0.5,0.04],[0.96,0.04],"
        "    [0.04,0.18],[0.5,0.18],[0.96,0.18],"
        "    [0.04,0.5],[0.5,0.5],[0.96,0.5],"
        "    [0.04,0.82],[0.5,0.82],[0.96,0.82],"
        "    [0.04,0.96],[0.5,0.96],[0.96,0.96]"
        "  ];"
        "  var counts={};"
        "  for(var i=0;i<points.length;i++){"
        "    var c=bgAt(Math.round((w-1)*points[i][0]),Math.round((h-1)*points[i][1]));"
        "    if(c) counts[c]=(counts[c]||0)+1;"
        "  }"
        "  var best='',bestCount=0;"
        "  Object.keys(counts).forEach(function(c){if(counts[c]>bestCount){best=c;bestCount=counts[c];}});"
        "  if(best) return best;"
        "  var body=getComputedStyle(document.body||document.documentElement).backgroundColor;"
        "  if(opaque(body)) return normalize(body);"
        "  var root=getComputedStyle(document.documentElement).backgroundColor;"
        "  if(opaque(root)) return normalize(root);"
        "  return '#FFFFFF';"
        "})()"
    )

    def _on_web_loaded(self, ok, panel, tab_index):
        """活跃 view 加载完成后，若该 tab 正在显示则更新背景色。"""
        if ok and self.stacked_widget.currentIndex() == tab_index:
            view = panel.active_view()
            if view is not None:
                view.page().runJavaScript(
                    self._BG_JS,
                    lambda color, tab_index=tab_index: self._apply_web_bg(color, tab_index),
                )

    def _apply_web_bg(self, color_str, tab_index=None):
        """将 JS 返回的颜色应用到 qw3；透明/空时回退白色。"""
        if tab_index is not None:
            try:
                if self.stacked_widget.currentIndex() != int(tab_index):
                    return
            except Exception:
                return
        if not color_str or color_str.strip() in ('rgba(0, 0, 0, 0)', 'transparent', ''):
            color_str = '#FFFFFF'
        if tab_index in EXTERNAL_PROMPT_TAB_INDICES:
            try:
                self._external_tab_backgrounds[int(tab_index)] = color_str
            except Exception:
                pass
        self._set_external_tab_background(tab_index, color_str)

    def _set_external_tab_background(self, tab_index, color_str: str):
        color_str = str(color_str or '').strip() or '#FFFFFF'
        if tab_index == TAB_WEB:
            panel = getattr(self, 'ai_web_panel', None)
        elif tab_index == TAB_LOCALHOST:
            panel = getattr(self, 'localhost_panel', None)
        else:
            panel = None
        if panel is not None and hasattr(panel, 'set_panel_background'):
            panel.set_panel_background(color_str)
        self._set_qw3_bg(color_str)

    def _prime_external_tab_background(self, tab_index: int):
        try:
            tab_index = int(tab_index)
        except Exception:
            return
        cached = getattr(self, '_external_tab_backgrounds', {}).get(tab_index, '#FFFFFF')
        self._set_external_tab_background(tab_index, cached or '#FFFFFF')

    def _set_qw3_bg(self, bg_css, border='#ECECEC'):
        """动态覆盖 qw3 的背景色（保留其他样式属性）。"""
        if border == '#ECECEC' and is_dark_theme(app):
            border = '#2D2D2D'
        if hasattr(self.qw3, 'set_smooth_panel_background'):
            self.qw3.set_smooth_panel_background(bg_css, border, MAIN_WINDOW_SMOOTH_RADIUS)
        if not getattr(self, '_qw3_transparent_style_applied', False):
            self.qw3.setStyleSheet("QWidget#Main-1 { border: none; background: transparent; }")
            self._qw3_transparent_style_applied = True

    def _apply_assistant_surfaces_theme(self, dark_mode: bool):
        self.real1.setStyleSheet(_assistant_readonly_text_stylesheet(dark_mode))
        self.real2.setStyleSheet(_assistant_webview_stylesheet(dark_mode))
        try:
            self.text1._apply_theme()
        except Exception:
            pass
        try:
            self._text1_popup._apply_theme()
        except Exception:
            pass
        try:
            self._bar_transfer_btn._apply_theme()
            self.btn_sub1._apply_theme()
        except Exception:
            pass

    def _refresh_assistant_render_for_theme(self):
        if self.trans % 2 == 1:
            return
        history_messages = get_current_chat_history_messages()
        all_text = read_file_contents(BasePath + 'output.txt', '')
        if history_messages or all_text.strip():
            self.render_final_output(all_text, history_messages=history_messages or None)
        else:
            self.show_welcome_state()

    def _refresh_current_tab_background(self):
        current_index = self.stacked_widget.currentIndex()
        if current_index == TAB_WEB:
            self._prime_external_tab_background(TAB_WEB)
            try:
                self.ai_web_panel.active_view().page().runJavaScript(
                    self._BG_JS,
                    lambda color, tab_index=TAB_WEB: self._apply_web_bg(color, tab_index),
                )
            except Exception:
                pass
        elif current_index == TAB_API:
            self._set_qw3_bg('#2D2D2D' if is_dark_theme(app) else '#FFFFFF')
        elif current_index == TAB_LOCALHOST:
            self._prime_external_tab_background(TAB_LOCALHOST)
            try:
                self.localhost_panel.active_view().page().runJavaScript(
                    self._BG_JS,
                    lambda color, tab_index=TAB_LOCALHOST: self._apply_web_bg(color, tab_index),
                )
            except Exception:
                pass
        elif current_index == TAB_TERMINAL:
            self._set_qw3_bg('#2D2D2D', border='#2D2D2D')

    def _refresh_web_surfaces_for_theme(self):
        self._refresh_assistant_render_for_theme()
        QTimer.singleShot(0, self._refresh_current_tab_background)
        QTimer.singleShot(250, self._refresh_current_tab_background)

    def apply_theme(self, dark_mode: bool):
        current_index = self.stacked_widget.currentIndex()
        self.pill_nav.set_theme('dark' if (current_index == TAB_TERMINAL or dark_mode) else 'light')
        self._set_top_chrome_button_theme(current_index == TAB_TERMINAL or dark_mode)
        self._apply_assistant_surfaces_theme(dark_mode)
        # FIX-37 review: a theme flip recolors the blank-tab placeholder, so the
        # cached chrome color for panels whose ACTIVE view is a placeholder must
        # follow — otherwise the next tab visit primes the stale color first.
        try:
            blank_bg = '#2D2D2D' if dark_mode else '#FFFFFF'
            for tab_index, panel in ((TAB_WEB, getattr(self, 'ai_web_panel', None)),
                                     (TAB_LOCALHOST, getattr(self, 'localhost_panel', None))):
                if panel is None or not getattr(panel, '_views', None):
                    continue
                view = panel.active_view()
                if view is not None and bool(view.property('broccoli_blank_html')):
                    self._external_tab_backgrounds[tab_index] = blank_bg
        except Exception:
            pass
        self._refresh_web_surfaces_for_theme()
        _apply_window_palette(self, dark_mode)
        for panel in (self.settings_panel, self.history_panel, self.links_panel, self.outputs_panel, self.share_panel, self.webfetch_panel):
            try:
                panel._apply_theme()
            except Exception:
                pass

    def set_hotkey_manager(self, hotkey_manager):
        self.settings_panel.set_hotkey_manager(hotkey_manager)

    def _background_vision_targets_from_store(self, store: dict) -> list[dict]:
        globals_store = store.get('globals', {}) if isinstance(store, dict) else {}
        settings = normalize_background_vision_settings(globals_store)
        selected_names = normalize_background_vision_profile_names(settings.get('background_vision_profile_names', []))
        profiles = list(store.get('profiles', []) if isinstance(store, dict) else [])
        by_name = {
            str(profile.get('name', '') or '').strip(): profile
            for profile in profiles
            if isinstance(profile, dict) and str(profile.get('name', '') or '').strip()
        }
        if not selected_names:
            active_name = str(store.get('active_profile', '') or '').strip() if isinstance(store, dict) else ''
            selected_names = [active_name] if active_name else []
        targets = []
        for name in selected_names:
            profile = by_name.get(name)
            if not profile:
                continue
            target = dict(profile)
            target['endpoint'] = profile_runtime_base_url(profile)
            targets.append(target)
        if not targets and profiles:
            profile = profiles[0]
            target = dict(profile)
            target['endpoint'] = profile_runtime_base_url(profile)
            targets.append(target)
        return targets

    def _background_vision_signature_for(self, settings: dict, targets: list[dict]) -> str:
        compact_targets = [
            {
                'name': str(target.get('name', '') or ''),
                'endpoint': str(target.get('endpoint', '') or ''),
                'model': str(target.get('model', '') or ''),
                'timeout': str(target.get('timeout', '') or ''),
                'api_key_hint': str(target.get('api_key', '') or '')[:8],
            }
            for target in targets
        ]
        payload = {
            'settings': normalize_background_vision_settings(settings),
            'targets': compact_targets,
        }
        return json.dumps(payload, ensure_ascii=False, sort_keys=True)

    def apply_background_vision_settings(self):
        store = load_settings_store()
        globals_store = store.get('globals', {})
        settings = normalize_background_vision_settings(globals_store)
        if not bool(settings.get('background_vision_enabled', False)):
            self.stop_background_vision()
            return
        targets = self._background_vision_targets_from_store(store)
        signature = self._background_vision_signature_for(settings, targets)
        worker = getattr(self, '_background_vision_worker', None)
        if worker is not None and worker.isRunning() and signature == getattr(self, '_background_vision_signature', ''):
            return
        self.stop_background_vision()
        if not targets:
            return
        self._background_vision_generation += 1
        generation = self._background_vision_generation
        worker = BackgroundVisionWorker(targets, settings)
        worker.record_ready.connect(lambda record, gen=generation: self._on_background_vision_record_ready(record, gen))
        worker.error.connect(lambda message, gen=generation: self._on_background_vision_error(message, gen))
        worker.finished.connect(worker.deleteLater)
        self._background_vision_worker = worker
        self._background_vision_signature = signature
        worker.start()

    def stop_background_vision(self):
        self._background_vision_generation += 1
        worker = getattr(self, '_background_vision_worker', None)
        self._background_vision_worker = None
        self._background_vision_signature = ''
        if worker is not None:
            try:
                self._background_vision_stopping_workers.append(worker)
                worker.finished.connect(lambda w=worker: self._background_vision_stopping_workers.remove(w) if w in self._background_vision_stopping_workers else None)
                worker.stop()
                worker.wait(500)
            except Exception:
                pass

    def _on_background_vision_record_ready(self, record, generation: int):
        if generation != getattr(self, '_background_vision_generation', 0):
            return
        if not isinstance(record, dict):
            return
        settings = normalize_background_vision_settings(load_settings_store().get('globals', {}))
        append_background_vision_record(record, settings.get('background_vision_max_records', DEFAULT_BACKGROUND_VISION_MAX_RECORDS))
        if bool(settings.get('background_vision_show_overlay', True)) and bool(record.get('complete')):
            ttl_ms = int(settings.get('background_vision_toast_sec', DEFAULT_BACKGROUND_VISION_TOAST_SECONDS) or DEFAULT_BACKGROUND_VISION_TOAST_SECONDS) * 1000
            self._background_vision_toasts.show_record(record, ttl_ms=ttl_ms)

    def _on_background_vision_error(self, message: str, generation: int):
        if generation != getattr(self, '_background_vision_generation', 0):
            return
        # Keep background failures non-modal; the record file stores round-level errors.
        return

    def _build_background_vision_prompt_context(self) -> str:
        globals_store = load_settings_store().get('globals', {})
        if not bool(globals_store.get('background_vision_enabled', False)):
            return ''
        return load_latest_background_vision_context()

    def _refresh_history_panel(self):
        perf_started = time.perf_counter()
        self.history_panel.set_display_limit(normalize_history_display_limit(
            load_settings_store().get('globals', {}).get('history_display_limit', 0)))
        self.history_panel.set_pinned_paths(getattr(self, '_agent_conversation_open_badges', set()))
        records = conversation_history_index_records()
        rebuilding = history_index_needs_rebuild()
        self.history_panel.set_loading(not _CONVERSATION_HISTORY_INDEX_READY)
        if not (rebuilding and self.history_panel.has_records()):
            # while rebuilding, `records` holds only what was written since: the panel keeps its
            # full list (the caller patched the renamed / deleted row) until the rebuild lands
            self.history_panel.set_records(records)
        self._refresh_agent_conversation_shelf()
        if not _CONVERSATION_HISTORY_INDEX_READY or rebuilding:
            self._start_history_index_build()
        _agent_render_perf_log(
            'refresh_history_panel',
            records=len(records),
            total_ms=round((time.perf_counter() - perf_started) * 1000, 2),
        )

    def _start_history_index_build(self):
        if self._history_index_building:
            return
        self._history_index_building = True
        self._history_index_signals = ConversationHistoryIndexSignals()
        self._history_index_signals.finished.connect(
            self._on_history_index_finished,
            Qt.ConnectionType.QueuedConnection,
        )
        self._history_index_signals.failed.connect(
            self._on_history_index_failed,
            Qt.ConnectionType.QueuedConnection,
        )
        self._history_index_generation = unified_history_generation()
        self._history_index_thread = ConversationHistoryIndexThread(self._history_index_signals)
        self._history_index_thread.start()

    def _on_history_index_finished(self, payload: dict):
        self._history_index_building = False
        self._history_index_thread = None
        self._history_index_signals = None
        records = list((payload or {}).get('records') or conversation_history_index_records())
        self.history_panel.set_loading(False)
        overtaken = history_index_needs_rebuild() and unified_history_generation() != getattr(self, '_history_index_generation', None)
        if not (overtaken and self.history_panel.has_records()):
            # overtaken: a rename / save landed while it ran, its list is older — the panel keeps
            # its (patched) rows until the next build lands
            self.history_panel.set_records(records)
        apply_history_title_repairs()   # renames a save had undone (before the user-title mark)
        self._refresh_agent_conversation_shelf()   # the tags read the rebuilt list too
        if history_index_needs_rebuild() and unified_history_generation() != getattr(self, '_history_index_generation', None):
            self._start_history_index_build()   # another rename / delete landed while it ran
        _agent_render_perf_log(
            'history_index_ready',
            records=len(records),
            total_ms=(payload or {}).get('elapsed_ms', 0),
        )

    def _on_history_index_failed(self, payload: dict):
        self._history_index_building = False
        self._history_index_thread = None
        self._history_index_signals = None
        self.history_panel.set_loading(False)
        logging.warning('Conversation history index build failed: %s', (payload or {}).get('error', 'unknown'))
        try:
            _note_history_index_error('thread', Exception(str((payload or {}).get('error', 'unknown'))))
        except Exception:
            pass
        # Never leave the panel empty: show whatever the fallback path holds.
        try:
            self.history_panel.set_records(conversation_history_index_records())
            self._refresh_agent_conversation_shelf()
        except Exception:
            logging.exception('history panel fallback failed')

    def _agent_badge_title_for_path(self, path: str, fallback: str = '') -> str:
        record = load_conversation_record(path, include_retrieval=False)
        return agent_conversation_badge_title(record, fallback=fallback)

    def _persist_agent_conversation_open_badges(self):
        paths = [
            conversation_sidecar_reference(str(path or '').strip())
            for path in getattr(self, '_agent_conversation_open_badges', set())
            if str(path or '').strip()
        ]
        paths.sort()
        _save_json_list(AGENT_CONVERSATION_BADGES_PATH, paths)

    def _set_conversation_left_tag(self, path: str, add: bool):
        """History panel right-click: add a conversation to the left tags (shelf) or take it off."""
        path = str(path or '').strip()
        if not path:
            return
        if add:
            if load_conversation_record(path) is None:
                return
            self._show_agent_conversation_badge(
                path,
                status=str((self._agent_run_for_path(path) or {}).get('phase', '') or 'finished'),
                title=self._agent_badge_title_for_path(path),
            )
        else:
            self._hide_agent_conversation_badge(path)
        self.history_panel.set_pinned_paths(getattr(self, '_agent_conversation_open_badges', set()))

    def open_current_agent_conversation_badge(self):
        path = str(getattr(self, '_active_conversation_path', '') or '').strip()
        if not path:
            messages = get_current_chat_history_messages()
            if messages:
                record = self._bootstrap_conversation_from_messages(messages)
                path = str(record.get('path', '') or '')
        if not path or load_conversation_record(path) is None:
            return
        self._show_agent_conversation_badge(
            path,
            status=str((self._agent_run_for_path(path) or {}).get('phase', '') or 'finished'),
            title=self._agent_badge_title_for_path(path),
        )

    def _show_agent_conversation_badge(self, path: str, status: str = 'running', title: str = ''):
        path = str(path or '').strip()
        if not path:
            return
        self._agent_conversation_open_badges.add(path)
        self._agent_conversation_hidden_badges.discard(path)
        self._persist_agent_conversation_open_badges()
        if status not in {'running', 'stopping', 'preflight', 'chat', 'browser_use', 'terminal_pending', 'terminal_command'}:
            self._agent_conversation_finished_badges[path] = {
                'status': status,
                'title': title or self._agent_badge_title_for_path(path),
                'updated_at': datetime.datetime.now().isoformat(timespec='seconds'),
            }
        self._refresh_agent_conversation_shelf()

    def _mark_agent_conversation_badge_finished(self, path: str, status: str = 'finished', title: str = ''):
        path = str(path or '').strip()
        if not path:
            return
        self._agent_conversation_finished_badges[path] = {
            'status': status,
            'title': title or self._agent_badge_title_for_path(path),
            'updated_at': datetime.datetime.now().isoformat(timespec='seconds'),
        }
        # A freshly finished result the user has not looked at yet -> mark unseen so its
        # shelf badge glows (green for finished, red for failed -- the badge picks the
        # colour from its status) and fire a native notification.
        status_l = str(status or '').strip()
        if status_l in {'finished', 'done', 'failed', 'error'}:
            if not hasattr(self, '_agent_unseen_paths'):
                self._agent_unseen_paths = set()
            self._agent_unseen_paths.add(path)
            title_text = str(title or self._agent_badge_title_for_path(path) or _tr('Agent conversation')).strip()
            if status_l in {'failed', 'error'}:
                body = _tr('Agent run failed — {title}').format(title=title_text)
            else:
                body = _tr('Answer ready — {title}').format(title=title_text)
            _mac_notifier.post('Broccoli', body, path)
        self._refresh_agent_conversation_shelf()

    def _mark_agent_conversation_seen(self, path: str):
        path = str(path or '').strip()
        if not path or path not in getattr(self, '_agent_unseen_paths', set()):
            return
        self._agent_unseen_paths.discard(path)
        shelf = getattr(self, 'agent_conversation_shelf', None)
        badge = shelf._badges.get(path) if shelf is not None else None
        if badge is not None:
            badge.set_unseen(False)   # gradual fade-out, driven by the shelf timer

    def _note_agent_engagement(self, obj, event):
        # Active engagement with the currently-shown conversation (typing/clicking in the
        # prompt, scrolling/clicking the answer) counts as "seen" -- no badge click needed
        # when the conversation is already on top.
        text1 = getattr(self, 'text1', None)
        real2 = getattr(self, 'real2', None)
        hit = obj is text1
        if not hit and real2 is not None:
            hit = obj is real2 or obj is real2.focusProxy()
        if hit:
            self._mark_agent_conversation_seen(str(self._active_conversation_path or ''))

    def _ensure_real2_engagement_filter(self):
        real2 = getattr(self, 'real2', None)
        if real2 is None:
            return
        proxy = real2.focusProxy()
        if proxy is not None and id(proxy) not in getattr(self, '_real2_filtered_proxies', set()):
            try:
                proxy.installEventFilter(self)
                self._real2_filtered_proxies.add(id(proxy))
            except Exception:
                pass

    def _hide_agent_conversation_badge(self, path: str):
        path = str(path or '').strip()
        if not path:
            return
        self._agent_conversation_open_badges.discard(path)
        self._agent_conversation_hidden_badges.add(path)
        self._agent_conversation_finished_badges.pop(path, None)
        self._persist_agent_conversation_open_badges()
        self._refresh_agent_conversation_shelf()

    def _activate_agent_conversation_badge(self, path: str):
        self._mark_agent_conversation_seen(path)
        self._select_main_tab(TAB_API)
        self._load_conversation_from_path(path)
        try:
            self.show()
            self.raise_()
            self.activateWindow()
        except Exception:
            pass

    def _agent_conversation_shelf_records(self) -> list[dict]:
        if not hasattr(self, 'stacked_widget'):
            return []
        records = []
        missing = []
        indexed_by_path = {
            str(item.get('path', '') or ''): item
            for item in conversation_history_index_records()
            if isinstance(item, dict) and str(item.get('path', '') or '')
        }
        open_paths = set(getattr(self, '_agent_conversation_open_badges', set()) or set())
        for path in open_paths:
            path = str(path or '').strip()
            if not path:
                continue
            record = indexed_by_path.get(path)
            if record is None:
                # Pinned tags are the user's special cases: even when the index
                # misses this path (rename race, provider hiccup, resolver moved
                # the file), the title must come from the record itself, never a
                # default. load_conversation_record resolves id-era paths that a
                # bare os.path.exists() would call missing.
                loaded = load_conversation_record(path, include_retrieval=False)
                if isinstance(loaded, dict):
                    record = {
                        'title': str(loaded.get('title', '') or ''),
                        'updated_at': str(loaded.get('updated_at', '') or ''),
                    }
            run = self._agent_run_for_path(path)
            info = getattr(self, '_agent_conversation_finished_badges', {}).get(path, {})
            if record is None and run is None and not info and not os.path.exists(path):
                missing.append(path)
                continue
            if run is not None:
                status = str(run.get('phase', '') or run.get('status', '') or 'running')
                title = str((record or {}).get('title', '') or info.get('title', '') or run.get('question_text', '') or _tr('Agent conversation'))
                updated_at = str(run.get('updated_at', '') or '')
            else:
                status = str(info.get('status', '') or 'finished')
                if status in {'running', 'stopping', 'preflight', 'chat', 'browser_use'}:
                    with _CONVERSATION_RECORD_CACHE_LOCK:
                        cached = _CONVERSATION_RECORD_CACHE.get(path)
                        cached_record = copy.deepcopy(cached) if isinstance(cached, dict) else None
                    messages = list((cached_record or {}).get('messages') or [])
                    if messages and any(str(message.get('role', '') or '') == 'assistant' for message in messages if isinstance(message, dict)):
                        status = 'finished'
                title = str((record or {}).get('title', '') or info.get('title', '') or _tr('Agent conversation'))
                updated_at = str(info.get('updated_at', '') or (record or {}).get('updated_at', '') or '')
            records.append({
                'path': path,
                'title': title,
                'status': status,
                'updated_at': updated_at,
                'unseen': path in getattr(self, '_agent_unseen_paths', set()),
            })
        if missing:
            for path in missing:
                self._agent_conversation_open_badges.discard(path)
            self._persist_agent_conversation_open_badges()
        records.sort(key=lambda item: item.get('updated_at', ''), reverse=True)
        return records

    def _refresh_agent_conversation_shelf(self):
        shelf = getattr(self, 'agent_conversation_shelf', None)
        if shelf is None:
            return
        # While the window is pinned-collapsed to the small circle, keep the side
        # shelf hidden no matter what triggered this refresh (agent activity calls
        # this from ~9 places, and set_records would otherwise re-show it).
        if self._is_main_window_pinned_collapsed():
            shelf.hide()
            return
        shelf.set_records(self._agent_conversation_shelf_records())
        self._update_agent_conversation_shelf_geometry()

    def _agent_conversation_shelf_side(self) -> str:
        try:
            frame = self.frameGeometry()
            screen = QGuiApplication.screenAt(frame.center()) or QGuiApplication.primaryScreen()
            if screen is None:
                return 'left'
            available = screen.availableGeometry()
            edge_threshold = AgentConversationBadge.PEEK_W + 8
            if frame.left() <= available.left() + edge_threshold:
                return 'right'
            if frame.right() >= available.right() - edge_threshold:
                return 'left'
        except Exception:
            pass
        return 'left'

    def _update_agent_conversation_shelf_geometry(self):
        shelf = getattr(self, 'agent_conversation_shelf', None)
        if shelf is None:
            return
        # moveEvent calls this on every window move, including when pin_a_tab shrinks
        # to the circle -> never position/show the shelf in the collapsed state.
        if self._is_main_window_pinned_collapsed():
            shelf.hide()
            return
        side = self._agent_conversation_shelf_side()
        shelf.set_side(side)
        shelf_w = AgentConversationBadge.EXPANDED_W
        frame = self.frameGeometry()
        shelf_h = max(80, frame.height() - 164)
        y = frame.y() + 104
        if side == 'right':
            x = frame.right() + 1
        else:
            x = frame.left() - shelf_w
        shelf.resize(shelf_w, shelf_h)
        shelf.move(x, y)
        shelf.restack_with_owner()
        # Mirror the main window's Space behavior so the shelf rides along into
        # fullscreen Spaces instead of staying pinned to its origin Space. Safe to
        # re-apply every refresh: collectionBehavior persists on the NSWindow and
        # the call is a cheap no-op once set.
        self._apply_agent_conversation_shelf_space_behavior()

    def _refresh_links_panel(self):
        record = self._load_active_conversation_record()
        links = record.get('links', []) if record else []
        self.links_panel.set_links(links)
        if record:
            for link in links:
                url = str(link.get('url', '')).strip()
                title = str(link.get('title', '')).strip()
                # Mojibake titles were persisted by the old Latin-1 default
                # decode; treat them as missing so they self-heal via refetch.
                if url and (not title or _link_title_looks_mojibake(title)) \
                        and url not in self._link_title_fetch_inflight:
                    self._link_title_fetch_inflight.add(url)
                    self._link_title_fetcher.fetch(url)

    def _tab_output_scope_key(self, index: int | None = None) -> str:
        if index is None:
            index = self.stacked_widget.currentIndex()
        return {TAB_WEB: 'web', TAB_LOCALHOST: 'localhost', TAB_TERMINAL: 'terminal'}.get(int(index), '')

    def _tab_outputs_path(self, scope_key: str) -> str:
        ensure_broccoli_data_dir()
        safe_key = re.sub(r'[^a-zA-Z0-9_-]+', '-', str(scope_key or '').strip()).strip('-') or 'tab'
        return os.path.join(TAB_GENERATED_OUTPUTS_DIR, f'{safe_key}.json')

    def _tab_outputs_attachment_dir(self, scope_key: str) -> str:
        ensure_broccoli_data_dir()
        safe_key = re.sub(r'[^a-zA-Z0-9_-]+', '-', str(scope_key or '').strip()).strip('-') or 'tab'
        target = os.path.join(TAB_GENERATED_OUTPUTS_DIR, f'{safe_key}_attachments')
        os.makedirs(target, exist_ok=True)
        return target

    def _load_tab_outputs(self, scope_key: str) -> list[dict]:
        path = self._tab_outputs_path(scope_key)
        try:
            with open(path, 'r', encoding='utf-8') as handle:
                payload = json.load(handle)
        except Exception:
            payload = {}
        if isinstance(payload, dict):
            return normalize_output_records(payload.get('outputs', []))
        if isinstance(payload, list):
            return normalize_output_records(payload)
        return []

    def _save_tab_outputs(self, scope_key: str, outputs: list[dict]):
        path = self._tab_outputs_path(scope_key)
        payload = {
            'schema': 'broccoli-tab-generated-outputs/v1',
            'scope': str(scope_key or ''),
            'updated_at': datetime.datetime.now().isoformat(timespec='seconds'),
            'outputs': normalize_output_records(outputs),
        }
        with open(path, 'w', encoding='utf-8') as handle:
            json.dump(payload, handle, ensure_ascii=False, indent=2)

    def _current_outputs_storage_dir(self) -> str:
        scope_key = self._tab_output_scope_key()
        if scope_key:
            return self._tab_outputs_attachment_dir(scope_key)
        if self._active_conversation_path:
            out_dir = conversation_attachment_dir(self._active_conversation_path)
        else:
            out_dir = self._tab_outputs_attachment_dir('api-unsaved')
        os.makedirs(out_dir, exist_ok=True)
        return out_dir

    def _recover_structured_outputs_from_conversation_record(self, record: dict | None) -> tuple[list[dict], bool]:
        if not isinstance(record, dict):
            return [], False
        messages = list(record.get('messages', []) or [])
        recovered = []
        changed = False
        for assistant_index, message in enumerate(messages):
            if not isinstance(message, dict) or str(message.get('role', '')).strip().lower() != 'assistant':
                continue
            content = str(message.get('content', '') or '')
            if '<broccoli-output' not in content.lower():
                continue
            cleaned, structured_outputs = split_structured_outputs_from_answer(content)
            if cleaned != content:
                message['content'] = cleaned
                changed = True
            if not structured_outputs:
                continue
            question_text = ''
            question_index = -1
            for idx in range(assistant_index - 1, -1, -1):
                candidate = messages[idx]
                if isinstance(candidate, dict) and str(candidate.get('role', '')).strip().lower() == 'user':
                    question_text = str(candidate.get('content', '') or '').strip()
                    question_index = idx
                    break
            recovered.extend(
                self._build_output_records_for_turn(
                    question_text=question_text,
                    question_index=question_index,
                    assistant_index=assistant_index,
                    model_name=str(message.get('model_name', '') or ''),
                    structured_outputs=structured_outputs,
                    step_results=[],
                )
            )
        if changed:
            record['messages'] = messages
            record['rendered_markdown'] = render_chat_history_markdown(messages)
        return normalize_output_records(recovered), changed

    def _recover_and_persist_structured_outputs(self, record: dict | None, *, persist: bool) -> dict | None:
        if not isinstance(record, dict):
            return record
        outputs = record.get('outputs', [])
        recovered_outputs, recovered_changed = self._recover_structured_outputs_from_conversation_record(record)
        if recovered_outputs:
            merged = merge_output_records(outputs, recovered_outputs)
            if merged != normalize_output_records(outputs):
                record['outputs'] = merged
                recovered_changed = True
        if recovered_changed and persist and str(record.get('path', '') or '').strip():
            saved = write_conversation_record(record['path'], record)
            if str(self._active_conversation_path or '') == str(record.get('path', '') or ''):
                self._active_conversation_path = saved.get('path', self._active_conversation_path)
            return saved
        return record

    def _refresh_outputs_panel(self, prefer_latest: bool = False, render_preview: bool | None = None):
        scope_key = self._tab_output_scope_key()
        if scope_key:
            outputs = self._load_tab_outputs(scope_key)
        else:
            record = self._load_active_conversation_record()
            outputs = record.get('outputs', []) if record else []
        if render_preview is None:
            render_preview = bool(getattr(self, '_outputs_panel_visible', False))
        self.outputs_panel.set_outputs(
            outputs,
            prefer_latest=prefer_latest,
            render_preview=bool(render_preview),
        )

    def _auto_show_outputs_panel_for_new_outputs(self,
                                                 new_outputs: list[dict] | None,
                                                 *,
                                                 visible_conversation: bool = True):
        if not visible_conversation or self.stacked_widget.currentIndex() != TAB_API:
            return
        outputs = normalize_output_records(new_outputs or [])
        if not outputs:
            return
        seen_ids = getattr(self, '_auto_shown_output_ids', set())
        output_ids = [
            str(output.get('id', '') or '').strip()
            for output in outputs
            if str(output.get('id', '') or '').strip()
        ]
        fresh_ids = [output_id for output_id in output_ids if output_id not in seen_ids]
        if not fresh_ids:
            return
        seen_ids.update(fresh_ids)
        self._auto_shown_output_ids = seen_ids

        def show_latest_outputs():
            if self.stacked_widget.currentIndex() != TAB_API:
                return
            self._refresh_outputs_panel(prefer_latest=True)
            if self._outputs_panel_visible:
                self.outputs_panel.raise_()
            else:
                self.show_outputs_panel()

        QTimer.singleShot(0, show_latest_outputs)

    def _copy_output_record(self, output: dict):
        kind = str(output.get('kind', 'text')).strip().lower()
        path = str(output.get('path', '') or '').strip()
        clipboard = QApplication.clipboard()
        if kind == 'image' and path and os.path.exists(path):
            pixmap = QPixmap(path)
            if not pixmap.isNull():
                clipboard.setPixmap(pixmap)
                return
        content = str(output.get('content', '') or '').strip()
        clipboard.setText(content or path)

    def _save_output_record_as(self, output: dict):
        kind = str(output.get('kind', 'text')).strip().lower()
        path = str(output.get('path', '') or '').strip()
        default_name = default_output_filename(output)
        target, _ = QFileDialog.getSaveFileName(self, _tr('Save output as'), default_name)
        if not target:
            return
        if path and os.path.exists(path):
            shutil.copy2(path, target)
            return
        write_text_file(target, str(output.get('content', '') or ''))

    def _open_output_record_in_editor(self, output: dict):
        path = editor_output_record_path(output)
        if path:
            self.open_editor_window([path])

    def _save_output_annotations(self, output: dict):
        self._save_output_record_fields(output, ('annotations',))

    def _save_output_record_fields(self, output: dict, keys: tuple) -> bool:
        """Write the given fields of one output back to where it lives: the current
        tab's outputs file (Web / Localhost / Terminal) or the active conversation."""
        output_id = str(output.get('id', '') or '').strip()
        if not output_id:
            return False

        def merge_into(outputs: list) -> bool:
            for index, item in enumerate(outputs):
                if str(item.get('id', '') or '').strip() == output_id:
                    merged = dict(item)
                    for key in keys:
                        if key == 'annotations':
                            merged['annotations'] = list(output.get('annotations', []) or [])
                        elif key in output:
                            merged[key] = output[key]
                    outputs[index] = merged
                    return True
            return False

        scope_key = self._tab_output_scope_key()
        if scope_key:
            outputs = list(self._load_tab_outputs(scope_key))
            if merge_into(outputs):
                self._save_tab_outputs(scope_key, outputs)
                return True
            return False
        if not self._active_conversation_path:
            return False
        if self._refuse_edit_of_remote_copy(self._active_conversation_path):
            return False
        record = load_conversation_record(self._active_conversation_path)
        if record is None:
            return False
        outputs = list(record.get('outputs', []) or [])
        if not merge_into(outputs):
            return False
        record['outputs'] = outputs
        saved = write_conversation_record(self._active_conversation_path, record)
        self._active_conversation_path = saved['path']
        return True

    def _complete_output_edit(self, payload: dict):
        """「完成」：先把改后的文字存回成品，再在后台让模型对比改前/改后，学到的偏好
        追加进永久记忆（不打扰当前对话；结果显示在成品浮窗标题下那一行）。"""
        output = dict((payload or {}).get('output') or {})
        output_id = str(output.get('id', '') or '').strip()
        if not output_id:
            return
        saved = self._save_output_record_fields(output, ('content', 'original_content', 'edited_at', 'annotations'))
        if not saved:
            logging.warning('Saving an edited output failed: %s not found.', output_id)
        previous = str((payload or {}).get('previous_content', '') or '')
        edited = str(output.get('content', '') or '')
        signals = self._output_learning_signals

        def run():
            try:
                result = learn_from_output_edit(
                    previous, edited,
                    question=str(output.get('question', '') or ''),
                    kind=str(output.get('kind', 'text') or 'text'),
                    title=str(output.get('title', '') or ''),
                )
            except Exception as exc:  # learn_from_output_edit never raises; belt and braces
                result = {'status': 'error', 'lines': [], 'error': str(exc)[:200]}
            result['output_id'] = output_id
            signals.finished.emit(result)

        threading.Thread(target=run, name='output-edit-learning', daemon=True).start()

    def _on_output_edit_learned(self, result: dict):
        result = result if isinstance(result, dict) else {}
        logging.info('Output edit learning: %s %s', result.get('status'), result.get('lines'))
        self.outputs_panel.show_learning_result(result)

    def _output_annotations_text(self, output: dict) -> str:
        annotations = list(output.get('annotations', []) or [])
        if not annotations:
            return ''
        lines = [
            f"Output: {str(output.get('title', '') or default_output_filename(output)).strip()}",
            f"Kind: {str(output.get('kind', 'text')).strip()}",
        ]
        question = str(output.get('question', '') or '').strip()
        if question:
            lines.append(f"Question: {question}")
        lines.append('')
        for index, annotation in enumerate(annotations, start=1):
            kind = str(annotation.get('kind', 'note')).replace('_', ' ')
            lines.append(f'[{index}] {kind}')
            if annotation.get('time_seconds') is not None:
                try:
                    seconds = float(annotation.get('time_seconds') or 0)
                    lines.append(f"Time: {int(seconds // 60):02d}:{int(seconds % 60):02d}.{int((seconds % 1) * 1000):03d}")
                except Exception:
                    pass
            quote = str(annotation.get('quote', '') or '').strip()
            if quote:
                lines.append('Selected text:')
                lines.append(quote)
            lines.append('Comment:')
            lines.append(str(annotation.get('comment', '') or '').strip())
            lines.append('')
        return '\n'.join(lines).strip()

    def _annotated_text_for_output(self, output: dict) -> str:
        base = str(output.get('content', '') or '')
        comments = self._output_annotations_text(output)
        if comments:
            return base.rstrip() + '\n\n---\n\nReviewer comments:\n' + comments + '\n'
        return base

    def _write_annotations_attachment(self, output: dict) -> str:
        comments = self._output_annotations_text(output)
        if not comments:
            return ''
        out_dir = self._current_outputs_storage_dir()
        os.makedirs(out_dir, exist_ok=True)
        filename = sanitize_conversation_filename(str(output.get('title', '') or 'output-comments'), max_len=64)
        target = os.path.join(out_dir, f"{datetime.datetime.now().strftime('%Y%m%d-%H%M%S-%f')}_{filename}-comments.txt")
        write_text_file(target, comments)
        return target

    def _write_composited_output_image(self, output: dict) -> str:
        if self.outputs_panel.current_output() and self.outputs_panel.current_output().get('id') == output.get('id'):
            pixmap = self.outputs_panel.image_preview.composited_pixmap()
        else:
            pixmap = QPixmap(str(output.get('path', '') or ''))
        if pixmap.isNull():
            return ''
        out_dir = self._current_outputs_storage_dir()
        os.makedirs(out_dir, exist_ok=True)
        filename = sanitize_conversation_filename(str(output.get('title', '') or 'annotated-output'), max_len=64)
        target = os.path.join(out_dir, f"{datetime.datetime.now().strftime('%Y%m%d-%H%M%S-%f')}_{filename}-annotated.png")
        pixmap.save(target, 'PNG')
        return target

    def _materialize_output_context_file(self, output: dict) -> str:
        path = str(output.get('path', '') or '').strip()
        if path and os.path.exists(path):
            return path
        out_dir = self._current_outputs_storage_dir()
        os.makedirs(out_dir, exist_ok=True)
        filename = sanitize_conversation_filename(Path(default_output_filename(output)).stem, max_len=64)
        suffix = Path(default_output_filename(output)).suffix or '.txt'
        timestamp = datetime.datetime.now().strftime('%Y%m%d-%H%M%S-%f')
        target = os.path.join(out_dir, f'{timestamp}_{filename}{suffix}')
        write_text_file(target, str(output.get('content', '') or ''))
        return target

    def _add_context_files_to_current_tab(self, paths: list[str]):
        paths = [str(path) for path in (paths or []) if path and os.path.exists(str(path))]
        if not paths:
            return
        use_embedding = self._generated_output_context_use_embedding_enabled()
        current_index = self.stacked_widget.currentIndex()
        if current_index == TAB_API:
            for path in paths:
                self._attachment_tray.add_file(path, use_embedding=use_embedding)
            self._show_tray_animated()
            return
        if current_index in EXTERNAL_PROMPT_TAB_INDICES:
            panel, dock = self._external_prompt_panel_for_index(current_index)
            if panel is not None and dock is not None:
                dock.add_files_instant(paths, use_embedding=use_embedding)
                panel.set_prompt_dock_visible(True, animated=True)
                QTimer.singleShot(0, lambda p=panel, d=dock: self._sync_external_prompt_dock_height(p, d))
                QTimer.singleShot(240, lambda p=panel, d=dock: self._sync_external_prompt_dock_height(p, d))
            return
        if current_index == TAB_TERMINAL:
            terminal = getattr(self, 'terminal_widget', None)
            if terminal is not None and hasattr(terminal, 'add_context_files'):
                terminal.add_context_files(paths, use_embedding=use_embedding)

    def _use_output_as_context(self, output: dict):
        paths = []
        kind = str(output.get('kind', 'text')).strip().lower()
        if kind in {'text', 'code'}:
            out_dir = self._current_outputs_storage_dir()
            os.makedirs(out_dir, exist_ok=True)
            filename = sanitize_conversation_filename(Path(default_output_filename(output)).stem, max_len=64)
            target = os.path.join(out_dir, f"{datetime.datetime.now().strftime('%Y%m%d-%H%M%S-%f')}_{filename}-with-comments.txt")
            write_text_file(target, self._annotated_text_for_output(output))
            paths.append(target)
        elif kind == 'image':
            annotated = self._write_composited_output_image(output)
            if annotated:
                paths.append(annotated)
            comments = self._write_annotations_attachment(output)
            if comments:
                paths.append(comments)
        elif kind == 'video':
            annotated = self._write_composited_output_image(output)
            if annotated:
                paths.append(annotated)
            comments = self._write_annotations_attachment(output)
            if comments:
                paths.append(comments)
        elif kind == 'audio':
            comments = self._write_annotations_attachment(output)
            if comments:
                paths.append(comments)
        if not paths:
            fallback = self._materialize_output_context_file(output)
            if fallback:
                paths.append(fallback)
        if paths:
            self._add_context_files_to_current_tab(paths)
            if getattr(self, '_outputs_panel_visible', False):
                self.hide_outputs_panel()

    def _run_profile_chat_completion(self, profile: dict, messages: list[dict], on_delta=None,
                                     reasoning_effort: str = '', retry_timeouts: bool = True) -> str:
        api_key = str(profile.get('api_key', '')).strip()
        model = str(profile.get('model', '')).strip()
        if not api_key or not model:
            raise ValueError('Selected profile is missing API key or model.')
        try:
            timeout = int(profile.get('timeout', 60) or 60)
        except (TypeError, ValueError):
            timeout = 60
        endpoint = profile_runtime_base_url(profile)
        client = create_openai_client(api_key, endpoint, timeout)
        # 思考强度：查档案翻译抽象档；缺档案本次不注入、后台补探（首跑
        # 无感、次跑生效）；注入用 extra_body 兼容任何 SDK 版本。
        reasoning_param = None
        if reasoning_effort:
            probe_record = get_reasoning_probe_record(profile)
            if probe_record is None or probe_record.get('status') == 'error':
                ensure_reasoning_probe_async(profile)
            elif probe_record.get('status') == 'supported':
                reasoning_param = resolve_reasoning_effort_param(profile, reasoning_effort)
        reasoning_kwargs = {'extra_body': {'reasoning_effort': reasoning_param}} if reasoning_param else {}
        if callable(on_delta):
            # 流式路径（专项步骤的进度可视化）：逐片段回调；端点不支持流式
            # 或流中断时，回退到下面的完成式请求。
            try:
                chunks = []
                citation_urls = []
                response_stream = create_chat_completion(
                    # retry_timeouts=False: a stream that times out sent nothing for the whole
                    # timeout; resending the same request (the client's 2 automatic retries)
                    # or falling back to a non-streamed one only waits that long again.
                    client if retry_timeouts else client.with_options(max_retries=0),
                    endpoint=endpoint,
                    model=model,
                    messages=messages,
                    stream=True,
                    **reasoning_kwargs,
                )
                for response in response_stream:
                    for url in extract_perplexity_citation_urls(getattr(response, 'citations', None)):
                        if url not in citation_urls:
                            citation_urls.append(url)
                    if not getattr(response, 'choices', None):
                        continue
                    delta = getattr(response.choices[0].delta, 'content', None)
                    if delta:
                        chunks.append(delta)
                        try:
                            on_delta(delta)
                        except Exception:
                            pass
                answer = ''.join(chunks).strip()
                if answer:
                    if is_perplexity_endpoint(profile.get('endpoint', '')) and citation_urls:
                        citations_block = format_perplexity_citations_block(citation_urls)
                        if citations_block:
                            answer = answer + '\n\n' + citations_block
                    return answer
            except Exception as exc:
                if not retry_timeouts and isinstance(exc, openai.APITimeoutError):
                    raise
        try:
            response = create_chat_completion(
                client,
                endpoint=endpoint,
                model=model,
                messages=messages,
                stream=False,
                **reasoning_kwargs,
            )
        except Exception as exc:
            # 注入被服务端拒绝：摘参重试保住本次调用，档案落盘不再注入。
            if reasoning_kwargs and _is_unsupported_reasoning_param_error(exc):
                mark_reasoning_probe_unsupported(profile)
                response = create_chat_completion(
                    client,
                    endpoint=endpoint,
                    model=model,
                    messages=messages,
                    stream=False,
                )
            else:
                raise
        answer = str(response.choices[0].message.content or '').strip()
        # Perplexity exposes citations on its chat-compatible responses, but the
        # field shape is provider-specific rather than OpenAI-standard. Keep this
        # special-case local and explicit instead of pretending it is generic.
        if is_perplexity_endpoint(profile.get('endpoint', '')):
            citations_block = format_perplexity_citations_block(getattr(response, 'citations', None))
            if citations_block:
                answer = answer + ('\n\n' if answer else '') + citations_block
        return answer

    def _run_profile_chat_completion_with_code_execution(self,
                                                         profile: dict,
                                                         messages: list[dict],
                                                         on_delta=None,
                                                         reasoning_effort: str = '',
                                                         archive_reader=None,
                                                         archive_read_instruction: str = '',
                                                         enable_code_execution: bool = True,
                                                         retry_timeouts: bool = True) -> tuple[str, list[dict]]:
        current_messages = clone_messages_as_text(messages)
        instruction = str(archive_read_instruction or '').strip()
        if instruction and callable(archive_reader):
            # The relay drops system-role messages, and some callers (terminal
            # planning, review) build their user content inline without the fence
            # protocol: deliver it in user role here unless a prompt builder
            # already embedded the same text.
            if all(instruction not in str(m.get('content', '') or '') for m in current_messages):
                for m in reversed(current_messages):
                    if m.get('role') == 'user':
                        m['content'] = str(m.get('content', '') or '') + '\n\n' + instruction
                        break
                else:
                    current_messages.append({'role': 'user', 'content': instruction})
        output = self._run_profile_chat_completion(
            profile, current_messages, on_delta=on_delta, reasoning_effort=reasoning_effort,
            retry_timeouts=retry_timeouts,
        )
        executions = []
        seen_codes = set()
        archive_rounds = 0
        code_rounds = 0
        store = load_settings_store()
        for _round in range(CODE_EXECUTION_MAX_ROUNDS + (ARCHIVE_READ_MAX_ROUNDS if callable(archive_reader) else 0)):
            archive_request = extract_archive_read_request(output)
            if archive_request is not None and callable(archive_reader):
                if archive_rounds >= ARCHIVE_READ_MAX_ROUNDS:
                    break
                archive_rounds += 1
                feedback = archive_reader(archive_request)
                current_messages.append({'role': 'assistant', 'content': output})
                current_messages.append({'role': 'user', 'content': str(feedback or '')})
                output = self._run_profile_chat_completion(
                    profile, current_messages, on_delta=on_delta, reasoning_effort=reasoning_effort,
                    retry_timeouts=retry_timeouts,
                )
                continue
            if not enable_code_execution or code_rounds >= CODE_EXECUTION_MAX_ROUNDS:
                break
            candidates = extract_code_candidates(output)
            selected = None
            for candidate in candidates:
                language = normalize_code_runner_language(candidate.get('language', ''), '')
                code = str(candidate.get('code', '') or '').strip()
                key = f'{language}\n{code}'
                if language and code and key not in seen_codes:
                    selected = {'language': language, 'code': code}
                    break
            if not selected:
                break
            code_rounds += 1
            seen_codes.add(f"{selected['language']}\n{selected['code']}")
            result = run_code_in_worker_thread(selected['language'], selected['code'], store=store)
            executions.append({'language': selected['language'], 'code': selected['code'], 'result': result})
            current_messages.append({'role': 'assistant', 'content': output})
            current_messages.append({'role': 'user', 'content': format_code_execution_feedback(executions[-1:])})
            output = self._run_profile_chat_completion(
                profile, current_messages, on_delta=on_delta, reasoning_effort=reasoning_effort,
                retry_timeouts=retry_timeouts,
            )
        return output, executions

    def _specialized_output_dir(self) -> str:
        if self._active_conversation_path:
            out_dir = conversation_attachment_dir(self._active_conversation_path)
        else:
            out_dir = os.path.join(BROCCOLI_APP_DATA_DIR, 'SpecializedOutputs')
        os.makedirs(out_dir, exist_ok=True)
        return out_dir

    def _write_specialized_output_bytes(self, prefix: str, suffix: str, data: bytes) -> str:
        out_dir = self._specialized_output_dir()
        base = sanitize_conversation_filename(prefix, max_len=40)
        timestamp = datetime.datetime.now().strftime('%Y%m%d-%H%M%S-%f')
        path = os.path.join(out_dir, f'{timestamp}_{base}{suffix}')
        with open(path, 'wb') as handle:
            handle.write(data)
        return path

    def _response_text_from_response_api(self, response) -> str:
        output_text = str(getattr(response, 'output_text', '') or '').strip()
        if output_text:
            return output_text
        parts = []
        for item in getattr(response, 'output', []) or []:
            try:
                dumped = item.model_dump()
            except Exception:
                dumped = {}
            for content in dumped.get('content', []) if isinstance(dumped, dict) else []:
                if not isinstance(content, dict):
                    continue
                text_value = str(content.get('text', '') or '').strip()
                if text_value:
                    parts.append(text_value)
        return '\n\n'.join(part for part in parts if part).strip()

    def _extract_web_search_sources(self, response) -> list[dict]:
        found = []
        seen = set()

        def walk(value):
            if isinstance(value, dict):
                url = str(value.get('url', '') or '').strip()
                title = str(value.get('title', '') or value.get('name', '') or '').strip()
                if url and url not in seen:
                    seen.add(url)
                    found.append({'url': url, 'title': title})
                for child in value.values():
                    walk(child)
            elif isinstance(value, list):
                for child in value:
                    walk(child)

        for item in getattr(response, 'output', []) or []:
            try:
                walk(item.model_dump())
            except Exception:
                continue
        return found

    def _extract_media_source_path(self, attachment_records: list[dict], allowed_exts: set[str]) -> str:
        for attachment in attachment_records:
            for key in ('stored_path', 'source_path', 'original_path'):
                path = str(attachment.get(key, '')).strip()
                if path and os.path.exists(path) and Path(path).suffix.lower() in allowed_exts:
                    return path
        return ''

    def _build_media_generation_input(self,
                                      question_text: str,
                                      shared_context: str,
                                      step_context: str,
                                      previous_results: list[dict],
                                      goal: str,
                                      archive_context: dict | None = None) -> str:
        parts = [build_runtime_context_block()]
        if question_text.strip():
            parts.append(f'User request:\n{question_text.strip()}')
        if goal.strip():
            parts.append(f'Step goal:\n{goal.strip()}')
        if shared_context.strip():
            parts.append(f'Global retrieved context:\n{shared_context.strip()}')
        if step_context.strip():
            parts.append(f'Step-specific retrieved context:\n{step_context.strip()}')
        if previous_results:
            prev = []
            for result in previous_results:
                body = specialized_step_context_output(result)
                if body:
                    prev.append(f"{result.get('capability', 'previous_step')}:\n{body}")
            if prev:
                parts.append('Previous step outputs:\n' + '\n\n'.join(prev))
        archive_context = archive_context if isinstance(archive_context, dict) else {}
        if str(archive_context.get('manifest', '') or '').strip():
            parts.append('Archived step materials:\n' + str(archive_context.get('manifest', '')).strip())
        if str(archive_context.get('preload', '') or '').strip():
            parts.append('Archived material provided for this step:\n' + str(archive_context.get('preload', '')).strip())
        return '\n\n'.join(part for part in parts if part).strip()

    def _run_custom_service_step(self,
                                 service: dict,
                                 capability: str,
                                 goal: str,
                                 question_text: str) -> dict:
        """自定义服务步骤（纯搜索源）：调服务拿结果，格式化后原样上交——
        总结交给下游的 review 压缩与最终回答，步骤内不再过模型。"""
        service_ref = CUSTOM_SERVICE_PREFIX + str(service.get('name', '') or '')
        kind = str(service.get('kind', '') or CUSTOM_SERVICE_DEFAULT_KIND).strip().lower()
        query = str(goal or '').strip() or str(question_text or '').strip()
        query = re.sub(r'\s+', ' ', query)[:300]
        try:
            # 按 kind 分发到供应商专属适配器；新增供应商（Brave/Tavily…）时
            # 在这里加分支。
            if kind == 'ollama_web_search':
                results = custom_service_web_search(service, query)
            else:
                raise ValueError(f'Unsupported custom service kind: {kind}')
        except Exception as exc:
            return {
                'capability': capability,
                'capability_label': specialized_capability_label(capability),
                'model_name': service_ref,
                'text_output': f'Custom web search service {service_ref} failed: {exc}',
                'artifacts': [],
                'metadata': {'goal': goal, 'execution_mode': 'custom_service', 'custom_service': service_ref},
            }
        if not results:
            text_output = f'Custom web search returned no results for: {query}'
        else:
            blocks = []
            for index, item in enumerate(results, start=1):
                lines = [f"[{index}] {item.get('title') or item.get('url') or 'Result'}"]
                if item.get('url'):
                    lines.append(item['url'])
                if item.get('content'):
                    lines.append(item['content'])
                blocks.append('\n'.join(lines))
            source_block = 'Sources:\n' + '\n'.join(
                f"- {item.get('title', '').strip() or item['url']} ({item['url']})"
                for item in results if item.get('url')
            )
            text_output = '\n\n'.join(blocks + [source_block])
        return {
            'capability': capability,
            'capability_label': specialized_capability_label(capability),
            'model_name': service_ref,
            'text_output': text_output,
            'artifacts': [],
            'metadata': {
                'goal': goal,
                'execution_mode': 'custom_service',
                'custom_service': service_ref,
                'search_query': query,
                'sources': [item.get('url', '') for item in results if item.get('url')],
            },
        }

    def _run_web_search_step(self,
                             profile: dict,
                             goal: str,
                             question_text: str,
                             shared_context: str,
                             step_context: str,
                             previous_results: list[dict],
                             archive_context: dict | None = None) -> dict:
        model_name = str(profile.get('model', '')).strip()
        try:
            timeout = int(profile.get('timeout', 60) or 60)
        except (TypeError, ValueError):
            timeout = 60
        client = create_openai_client(
            str(profile.get('api_key', '')).strip(),
            profile_runtime_base_url(profile),
            timeout,
        )
        prompt = (
            self._build_media_generation_input(
                question_text, shared_context, step_context, previous_results, goal, archive_context=archive_context
            )
            + '\n\nWeb search freshness rules:\n'
            '- Prefer official live/status/result pages and sources updated near the runtime date.\n'
            '- Do not rely on stale previews, old schedule announcements, or old "not started yet" articles when the runtime date is after the event start date.\n'
            '- If official and secondary sources conflict, preserve the conflict with source URLs and absolute dates instead of flattening it.'
        )
        response = client.responses.create(
            model=model_name,
            input=prompt,
            tools=[{'type': 'web_search_preview'}],
            include=['web_search_call.action.sources'],
            stream=False,
        )
        text_output = self._response_text_from_response_api(response)
        sources = self._extract_web_search_sources(response)
        if sources:
            source_block = 'Sources:\n' + '\n'.join(
                f"- {source.get('title', '').strip() or source['url']} ({source['url']})" for source in sources
            )
            text_output = text_output + ('\n\n' if text_output else '') + source_block
        return {
            'capability': 'web_search',
            'capability_label': specialized_capability_label('web_search'),
            'model_name': model_name,
            'text_output': text_output or 'Web search completed.',
            'artifacts': [],
            'metadata': {'goal': goal, 'sources': sources},
        }

    def _run_image_generation_step(self,
                                   profile: dict,
                                   goal: str,
                                   question_text: str,
                                   shared_context: str,
                                   step_context: str,
                                   previous_results: list[dict],
                                   archive_context: dict | None = None) -> dict:
        model_name = str(profile.get('model', '')).strip()
        try:
            timeout = int(profile.get('timeout', 60) or 60)
        except (TypeError, ValueError):
            timeout = 60
        client = create_openai_client(
            str(profile.get('api_key', '')).strip(),
            profile_runtime_base_url(profile),
            timeout,
        )
        prompt = self._build_media_generation_input(
            question_text, shared_context, step_context, previous_results, goal, archive_context=archive_context
        )
        response = client.images.generate(
            model=model_name,
            prompt=prompt,
            size='1024x1024',
        )
        artifacts = []
        text_output = 'Image generated successfully.'
        image_data = (getattr(response, 'data', None) or [])
        if image_data:
            first = image_data[0]
            revised_prompt = str(getattr(first, 'revised_prompt', '') or '').strip()
            b64_json = str(getattr(first, 'b64_json', '') or '').strip()
            image_url = str(getattr(first, 'url', '') or '').strip()
            output_format = str(getattr(response, 'output_format', '') or 'png').strip().lower() or 'png'
            if b64_json:
                image_bytes = base64.b64decode(b64_json)
                ext = '.jpg' if output_format == 'jpeg' else f'.{output_format}'
                artifacts.append(self._write_specialized_output_bytes('generated-image', ext, image_bytes))
            elif image_url:
                text_output += f'\nImage URL: {image_url}'
            if revised_prompt:
                text_output += f'\nRevised prompt: {revised_prompt}'
        return {
            'capability': 'image_generation',
            'capability_label': specialized_capability_label('image_generation'),
            'model_name': model_name,
            'text_output': text_output,
            'artifacts': artifacts,
            'metadata': {'goal': goal, 'prompt': prompt},
        }

    def _run_video_generation_step(self,
                                   profile: dict,
                                   goal: str,
                                   question_text: str,
                                   shared_context: str,
                                   step_context: str,
                                   previous_results: list[dict],
                                   archive_context: dict | None = None) -> dict:
        """OpenAI Videos（Sora）：创建任务 → 轮询到 completed/failed → 下载 mp4。
        视频任务是异步作业（通常几十秒到几分钟），profile 的 timeout 只管单次
        HTTP 请求；整体等待上限由 VIDEO_GENERATION_MAX_WAIT_SECONDS 管。"""
        model_name = str(profile.get('model', '')).strip()
        try:
            timeout = int(profile.get('timeout', 60) or 60)
        except (TypeError, ValueError):
            timeout = 60
        client = create_openai_client(
            str(profile.get('api_key', '')).strip(),
            profile_runtime_base_url(profile),
            timeout,
        )
        videos_api = getattr(client, 'videos', None)
        if videos_api is None:
            raise RuntimeError(
                'The installed openai SDK has no videos API; upgrade the openai package to use video generation.'
            )
        # 视频端点只认 sora 系模型；profile 绑的是聊天模型时用服务端默认
        # sora-2（metadata 里如实记录实际请求的模型）。
        video_model = model_name if model_name.lower().startswith('sora') else 'sora-2'
        prompt = self._build_media_generation_input(
            question_text, shared_context, step_context, previous_results, goal, archive_context=archive_context
        )
        job = videos_api.create(model=video_model, prompt=prompt)
        job_id = str(getattr(job, 'id', '') or '')
        status = str(getattr(job, 'status', '') or '')
        deadline = time.monotonic() + VIDEO_GENERATION_MAX_WAIT_SECONDS
        while status not in ('completed', 'failed'):
            if time.monotonic() >= deadline:
                raise RuntimeError(
                    f'Video generation timed out after {VIDEO_GENERATION_MAX_WAIT_SECONDS}s '
                    f'(job {job_id or "unknown"} still {status or "pending"}).'
                )
            time.sleep(VIDEO_GENERATION_POLL_SECONDS)
            job = videos_api.retrieve(job_id)
            status = str(getattr(job, 'status', '') or '')
        if status == 'failed':
            error = getattr(job, 'error', None)
            error_message = str(getattr(error, 'message', '') or error or 'unknown error')
            raise RuntimeError(f'Video generation failed (job {job_id}): {error_message}')
        content = videos_api.download_content(job_id)
        video_bytes = content.read()
        artifact_path = self._write_specialized_output_bytes('generated-video', '.mp4', video_bytes)
        seconds = str(getattr(job, 'seconds', '') or '')
        size = str(getattr(job, 'size', '') or '')
        text_output = 'Video generated successfully.'
        if seconds or size:
            text_output += f' ({seconds}s, {size})'.replace('(s, )', '').rstrip()
        return {
            'capability': 'video_generation',
            'capability_label': specialized_capability_label('video_generation'),
            'model_name': model_name,
            'text_output': text_output,
            'artifacts': [artifact_path],
            'metadata': {
                'goal': goal,
                'prompt': prompt,
                'video_model': video_model,
                'video_job_id': job_id,
                'video_seconds': seconds,
                'video_size': size,
            },
        }

    def _run_text_to_speech_step(self,
                                 profile: dict,
                                 goal: str,
                                 question_text: str,
                                 step_context: str,
                                 previous_results: list[dict],
                                 archive_context: dict | None = None) -> dict:
        model_name = str(profile.get('model', '')).strip()
        try:
            timeout = int(profile.get('timeout', 60) or 60)
        except (TypeError, ValueError):
            timeout = 60
        client = create_openai_client(
            str(profile.get('api_key', '')).strip(),
            profile_runtime_base_url(profile),
            timeout,
        )
        input_text = ''
        for result in reversed(previous_results):
            input_text = specialized_step_context_output(result)
            if input_text:
                break
        if not input_text:
            input_text = str(step_context or '').strip()
        if not input_text and str((archive_context or {}).get('preload', '') or '').strip():
            input_text = str((archive_context or {}).get('preload', '')).strip()
        if not input_text:
            input_text = str(question_text or '').strip()
        if not input_text:
            raise ValueError('No text is available for text-to-speech generation.')
        if len(input_text) > 3900:
            input_text = input_text[:3900].rstrip()
        audio_response = client.audio.speech.create(
            model=model_name,
            voice='alloy',
            input=input_text,
            response_format='mp3',
        )
        audio_bytes = audio_response.read()
        artifact_path = self._write_specialized_output_bytes('generated-audio', '.mp3', audio_bytes)
        return {
            'capability': 'text_to_speech',
            'capability_label': specialized_capability_label('text_to_speech'),
            'model_name': model_name,
            'text_output': 'Audio generated successfully.',
            'artifacts': [artifact_path],
            'metadata': {'goal': goal},
        }

    def _run_transcription_step(self,
                                capability: str,
                                profile: dict,
                                goal: str,
                                attachment_records: list[dict]) -> dict:
        model_name = str(profile.get('model', '')).strip()
        try:
            timeout = int(profile.get('timeout', 60) or 60)
        except (TypeError, ValueError):
            timeout = 60
        client = create_openai_client(
            str(profile.get('api_key', '')).strip(),
            profile_runtime_base_url(profile),
            timeout,
        )
        allowed_exts = ATTACHMENT_AUDIO_EXTS if capability == 'speech_to_text' else (ATTACHMENT_AUDIO_EXTS | ATTACHMENT_VIDEO_EXTS)
        source_path = self._extract_media_source_path(attachment_records, allowed_exts)
        if not source_path:
            raise ValueError('No compatible media attachment was found for transcription.')
        with open(source_path, 'rb') as media_file:
            transcription = client.audio.transcriptions.create(
                model=model_name,
                file=media_file,
                response_format='text',
            )
        text_output = str(transcription or '').strip() or 'Transcription completed.'
        return {
            'capability': capability,
            'capability_label': specialized_capability_label(capability),
            'model_name': model_name,
            'text_output': text_output,
            'artifacts': [],
            'metadata': {'goal': goal, 'source_path': source_path},
        }

    def _plan_specialized_request(self,
                                  question_text: str,
                                  attachment_records: list[dict],
                                  conversation_context: str = '',
                                  editor_note: str = '',
                                  archive_note: str = '',
                                  run_id: str = '') -> dict:
        store = load_settings_store()
        planner_profile = get_planner_profile_from_store(store)
        skills = load_skill_records_from_store(store, enabled_only=True)
        catalog = skill_catalog_text(skills)
        skill_names = {record.get('name', '') for record in skills}
        slash_segments = parse_specialized_slash_segments(question_text, skill_names)
        model_candidates = get_specialized_profile_candidates_from_store(store)
        try:
            planner_output = self._run_profile_chat_completion(
                planner_profile,
                build_planner_messages(
                    question_text,
                    summarize_attachment_types(attachment_records),
                    catalog,
                    conversation_context,
                    model_candidates_block=build_model_candidates_block(store),
                    editor_note=editor_note,
                    archive_note=archive_note,
                    skill_names=skill_names,
                ),
                reasoning_effort='standard',
            )
        except Exception:
            planner_output = ''
        plan = normalize_planner_plan(
            parse_json_object_from_text(planner_output), skill_names, model_candidates=model_candidates
        )
        plan = apply_slash_bindings_to_plan(plan, slash_segments)
        # Opt-in (default OFF): after the planner's own grouping + slash bindings are
        # settled, auto-group any remaining runs of independent read-only/generative
        # steps. Consumed at plan-build time; no live-window apply needed.
        if bool((store.get('globals') or {}).get('agent_auto_parallel_enabled', False)):
            plan = infer_auto_parallel_groups(plan)
        append_agent_run_event(run_id, 'planner/plan', {
            'question_text': question_text,
            'conversation_context_chars': len(str(conversation_context or '')),
            'attachments': len(attachment_records or []),
            'slash_segments': slash_segments,
            'plan': plan,
        })
        return plan

    def _review_specialized_step_result(self,
                                        result: dict,
                                        *,
                                        capability: str,
                                        goal: str,
                                        question_text: str,
                                        downstream_extract: str = '',
                                        final_focus: str = '',
                                        review_profile_name: str = '',
                                        attachment_records: list[dict] | None = None,
                                        external_target_runner=None,
                                        board_context: str = '',
                                        stream_callback=None,
                                        archive_manifest: str = '',
                                        archive_reader=None) -> dict:
        if not isinstance(result, dict):
            return result
        reviewed = dict(result)
        metadata = dict(reviewed.get('metadata') or {})
        output_text = str(reviewed.get('text_output', '') or '').strip()
        review_output_text = output_text
        code_executions = metadata.get('code_executions') or metadata.get('python_executions') or []
        if code_executions:
            review_output_text = (
                review_output_text
                + ('\n\n' if review_output_text else '')
                + 'Actual code execution feedback from the app:\n'
                + format_code_execution_feedback(code_executions)
            )
        artifact_paths = [str(path).strip() for path in (reviewed.get('artifacts') or []) if str(path).strip()]
        if not review_output_text and not artifact_paths:
            reviewed['context_output'] = ''
            metadata['step_review'] = {
                'reviewed': True,
                'meets_goal': False,
                'missing': 'The step produced no text output or artifacts.',
                'reason': 'No usable step output.',
                'next_action': 'accept',
                'new_step': None,
            }
            reviewed['metadata'] = metadata
            return reviewed

        store = load_settings_store()
        planner_profile = (
            get_profile_from_store_by_name(store, review_profile_name)
            if str(review_profile_name or '').strip()
            else None
        ) or get_planner_profile_from_store(store)
        skills = load_skill_records_from_store(store, enabled_only=True)
        catalog = skill_catalog_text(skills)
        skill_names = {record.get('name', '') for record in skills}
        try:
            external_review = str(review_profile_name or '').strip().startswith('@') and callable(external_target_runner)
            review_messages = build_specialized_step_review_messages(
                capability,
                goal,
                question_text,
                downstream_extract,
                final_focus,
                review_output_text,
                artifact_paths,
                catalog,
                tail_task_sections=external_review,
                board_context=board_context,
                archive_manifest=archive_manifest,
            )
            if external_review:
                external_result = external_target_runner({
                    'profile_name': str(review_profile_name or '').strip(),
                    'prompt': self._external_target_prompt_from_messages(review_messages),
                    'goal': f'Verify step result: {goal}',
                    'question_text': question_text,
                    'shared_context': review_output_text,
                    'attachment_records': list(attachment_records or []),
                })
                review_text = str(
                    (external_result or {}).get('answer', '')
                    or (external_result or {}).get('text', '')
                    or ''
                ).strip()
            else:
                # 直播复核内容（可选）：原始输出是纯 JSON（半截不可读），所以
                # 不直接透传——ReviewStreamProbe 在客户端把流增量翻译成人话
                # （达标与否/蒸馏证据逐字/缺什么），提示词与解析完全不动。
                review_stream = None
                if callable(stream_callback):
                    probe = ReviewStreamProbe()
                    try:
                        stream_callback('\n%s\n' % REVIEW_STREAM_DIVIDER)
                    except Exception:
                        pass

                    def review_stream(chunk, _probe=probe):
                        try:
                            fragment = _probe.feed(str(chunk or ''))
                            if fragment:
                                stream_callback(fragment)
                        except Exception:
                            pass
                # 复核是压缩+判定任务，固定 light 档（推理模型深思考在这里
                # 只贡献延迟——历史实测 gpt-5.5 复核 33 秒）。
                review_text, _review_executions = self._run_profile_chat_completion_with_code_execution(
                    planner_profile,
                    review_messages,
                    on_delta=review_stream,
                    reasoning_effort='light',
                    archive_reader=archive_reader,
                    archive_read_instruction=AGENT_STEP_ARCHIVE_READ_INSTRUCTION if callable(archive_reader) else '',
                    # 复核历来是单发请求，只为读档接进循环：代码围栏在这里
                    # 不该被执行（复核约定只回 JSON）。
                    enable_code_execution=False,
                )
            parsed = parse_json_object_from_text(review_text)
            if not isinstance(parsed, dict):
                raise ValueError('Planner review did not return JSON.')
            raw_new_step = parsed.get('new_step')
            if isinstance(raw_new_step, dict):
                raw_new_step = dict(raw_new_step)
                if not raw_new_step.get('archive_refs') and isinstance(parsed.get('archive_refs'), list):
                    raw_new_step['archive_refs'] = parsed.get('archive_refs')
                for key in ('retry_reason', 'delta_goal', 'source_strategy', 'success_criteria'):
                    if not str(raw_new_step.get(key, '') or '').strip() and str(parsed.get(key, '') or '').strip():
                        raw_new_step[key] = str(parsed.get(key, '') or '').strip()
            context_output = limit_specialized_context_output(str(parsed.get('context_output', '') or ''))
            raw_board_facts = parsed.get('board_facts')
            board_facts = []
            if isinstance(raw_board_facts, list):
                for item in raw_board_facts:
                    if not isinstance(item, dict):
                        continue
                    fact_text = str(item.get('text', '') or '').strip()
                    raw_refs = item.get('refs')
                    refs = (
                        [str(ref).strip() for ref in raw_refs if str(ref).strip()]
                        if isinstance(raw_refs, list) else []
                    )
                    if fact_text:
                        board_facts.append({'text': fact_text, 'refs': refs})
                    if len(board_facts) >= 3:
                        break
            raw_board_verdicts = parsed.get('board_verdicts')
            board_verdicts = []
            if isinstance(raw_board_verdicts, list):
                for item in raw_board_verdicts:
                    if not isinstance(item, dict) or not isinstance(item.get('agree'), bool):
                        continue
                    entry_id = str(item.get('entry_id', '') or '').strip()
                    if not entry_id:
                        continue
                    board_verdicts.append({
                        'entry_id': entry_id,
                        'agree': bool(item.get('agree')),
                        'reason': str(item.get('reason', '') or '').strip(),
                    })
                    if len(board_verdicts) >= 6:
                        break
            reviewed['context_output'] = context_output
            metadata['step_review'] = {
                'reviewed': True,
                'meets_goal': bool(parsed.get('meets_goal', False)),
                'missing': str(parsed.get('missing', '') or '').strip(),
                'reason': str(parsed.get('reason', '') or '').strip(),
                'downstream_need': str(downstream_extract or final_focus or '').strip(),
                'next_action': str(parsed.get('next_action', 'accept') or 'accept').strip(),
                'retry_reason': str(parsed.get('retry_reason', '') or '').strip(),
                'delta_goal': str(parsed.get('delta_goal', '') or '').strip(),
                'source_strategy': str(parsed.get('source_strategy', '') or '').strip(),
                'success_criteria': str(parsed.get('success_criteria', '') or '').strip(),
                'archive_refs': normalize_agent_step_archive_refs(parsed.get('archive_refs')),
                'new_step': normalize_dynamic_specialized_step(raw_new_step, skill_names),
                'board_facts': board_facts,
                'board_verdicts': board_verdicts,
            }
        except Exception as exc:
            reviewed['context_output'] = limit_specialized_context_output(review_output_text)
            metadata['step_review'] = {
                'reviewed': False,
                'meets_goal': True,
                'missing': '',
                'reason': f'Review failed; used locally truncated output. {exc}',
                'downstream_need': str(downstream_extract or final_focus or '').strip(),
                'next_action': 'accept',
                'new_step': None,
            }
        reviewed['metadata'] = metadata
        return reviewed

    def _execute_skill_step(self,
                            *,
                            skill_name: str,
                            goal: str,
                            question_text: str,
                            shared_context: str,
                            step_context: str,
                            previous_results: list[dict],
                            downstream_extract: str = '',
                            store: dict | None = None,
                            profile_override_name: str = '',
                            reasoning_effort: str = '',
                            archive_context: dict | None = None,
                            archive_reader=None,
                            parent_run_id: str = '') -> dict:
        if store is None:
            store = load_settings_store()
        skills = load_skill_records_from_store(store, enabled_only=True)
        skill = find_skill_record(skills, skill_name)
        if skill is None:
            return {
                'capability': SPECIALIZED_SKILL_CAPABILITY,
                'capability_label': 'Skill',
                'model_name': '',
                'text_output': f'Skill step failed: skill not found or disabled: {skill_name}',
                'artifacts': [],
                'metadata': {'goal': goal, 'skill_name': skill_name},
            }
        active_profile_name = str(store.get('active_profile', '') or '').strip()
        profile = (
            get_profile_from_store_by_name(store, profile_override_name)
            if str(profile_override_name or '').strip()
            else None
        ) or get_profile_from_store_by_name(store, active_profile_name) or load_active_settings_profile()
        model_name = str(profile.get('model', '') or '').strip()
        executions = []
        try:
            output, executions = self._run_profile_chat_completion_with_code_execution(
                profile,
                build_skill_step_messages(
                    skill=skill,
                    goal=goal,
                    question_text=question_text,
                    shared_context=shared_context,
                    step_context=step_context,
                    previous_results=previous_results,
                    downstream_extract=downstream_extract,
                    archive_context=archive_context,
                ),
                reasoning_effort=reasoning_effort,
                archive_reader=archive_reader,
                archive_read_instruction=str((archive_context or {}).get('read_instruction', '') or ''),
            )
        except Exception as exc:
            output = f'Skill step failed: {exc}'
        clean_skill_name = sanitize_skill_name(skill.get('name', skill_name), skill_name or 'Skill')
        return {
            'capability': SPECIALIZED_SKILL_CAPABILITY,
            'capability_label': f'Skill · {clean_skill_name}',
            'model_name': model_name,
            'text_output': output,
            'artifacts': [],
            'metadata': {
                'goal': goal,
                'skill_name': clean_skill_name,
                'skill_description': str(skill.get('description', '') or '').strip(),
                'execution_mode': 'default_main_model',
                'code_executions': executions,
            },
        }

    def _execute_browser_use_step(self,
                                  *,
                                  goal: str,
                                  question_text: str,
                                  shared_context: str,
                                  step_context: str,
                                  previous_results: list[dict],
                                  downstream_extract: str = '',
                                  conversation_path: str | None = None,
                                  stop_event: threading.Event | None = None,
                                  step_stream_callback=None,
                                  reasoning_effort: str = '',
                                  profile_override_name: str = '',
                                  archive_context: dict | None = None,
                                  parent_run_id: str = '') -> dict:
        # 任务全文会随浏览器 agent 的每一步模型调用反复发送（还叠加元素树
        # 与截图），上下文必须限长，否则每步请求都无谓地巨大。
        def clip(text: str, limit: int) -> str:
            text = str(text or '').strip()
            if len(text) <= limit:
                return text
            return text[:limit].rstrip() + '\n[...truncated]'

        # 任务书档位（Settings > General > Browser Use）：compact 收紧各段限额
        # 并把自动化目标置顶（官方提示词指南主张具体动作优先，背景仅供参考）；
        # full 保持历史拼装逐字节不变。任务书位于每步请求里"分歧点"下游，
        # 每个内部步骤都全价重发，限额直接决定每步的输入体积。
        _task_globals = load_settings_store().get('globals', {})
        compact_task = normalize_browser_use_settings(_task_globals)['browser_use_task_context'] != 'full'
        question_limit = 1500 if compact_task else 4000
        context_limit = 1000 if compact_task else 3500
        manifest_limit = 1000 if compact_task else 3500
        previous_limit = 800 if compact_task else 1800

        previous_sections = []
        for result in previous_results or []:
            body = specialized_step_context_output(result)
            if body:
                previous_sections.append(
                    clip(f"{result.get('capability', 'previous_step')} ({result.get('model_name', '')}):\n{body}", previous_limit)
                )
        if compact_task:
            task_parts = [
                'Browser automation goal:\n' + str(goal or '').strip(),
                'Work through the goal step by step with concrete browser actions. '
                'The sections below are background reference only.',
                'Original user request (background):\n' + clip(question_text, question_limit),
            ]
        else:
            task_parts = [
                'Original user request:\n' + clip(question_text, question_limit),
                'Browser automation goal:\n' + str(goal or '').strip(),
            ]
        if shared_context.strip():
            task_parts.append('Broccoli global retrieved context:\n' + clip(shared_context, context_limit))
        if step_context.strip():
            task_parts.append('Broccoli step-specific retrieved context:\n' + clip(step_context, context_limit))
        archive_context = archive_context if isinstance(archive_context, dict) else {}
        if str(archive_context.get('manifest', '') or '').strip():
            task_parts.append('Archived step materials:\n' + clip(archive_context.get('manifest', ''), manifest_limit))
        if str(archive_context.get('preload', '') or '').strip():
            task_parts.append('Archived material provided for this step:\n' + clip(archive_context.get('preload', ''), AGENT_STEP_ARCHIVE_PRELOAD_CHARS))
        if previous_sections:
            task_parts.append('Previous step output:\n' + '\n\n'.join(previous_sections[-3:]))
        if downstream_extract:
            task_parts.append('Downstream handoff requirement:\n' + clip(downstream_extract, 800))
        task_parts.append(
            'Use the browser to complete only the browser automation part of this step. '
            'Return concrete findings, relevant URLs, and any errors encountered.'
        )
        task = '\n\n'.join(task_parts)
        session_id = ''
        child_attempt = None
        try:
            config = self._prepare_browser_use_config(
                task,
                history_messages=[],
                storage_history_messages=[],
                interactive=False,
                profile_override_name=profile_override_name,
            )
            if not config:
                raise RuntimeError('Browser Use configuration unavailable.')
            if ICLOUD_M1C_UNIFIED_FINALIZER_ENABLED and str(parent_run_id or '').strip():
                child_attempt = self._register_child_agent_attempt(
                    {
                        'parent_run_id': str(parent_run_id or '').strip(),
                        'conversation_path': str(conversation_path or ''),
                        'question_text': str(goal or ''),
                        'task': task,
                        'source': 'specialized_browser_use',
                    },
                    'browser_use',
                )
            # 浏览器步骤不再注入 planner 分配的思考档（2026-08-24 提速方案）：
            # "看元素树→选动作"是低难度决策，思考档让每步模型调用多出几十秒；
            # 形参保留以维持调用方签名，值在此有意忽略。
            config, session = self._allocate_browser_use_session(
                config,
                run_id='specialized-browser-use',
                conversation_path=str(conversation_path or ''),
            )
            session_id = str(session.get('session_id', '') or '')
            on_progress = None
            if callable(step_stream_callback):
                on_progress = lambda message: step_stream_callback(str(message or '') + '\n')
            worker = BrowserUseThread(config, on_progress=on_progress)
            if isinstance(child_attempt, dict):
                child_attempt['browser_use_thread'] = worker
            holder = {'result': None, 'error': None}

            def run_worker():
                try:
                    holder['result'] = worker.run_blocking()
                except Exception as exc:
                    holder['error'] = exc

            thread = threading.Thread(target=run_worker, daemon=True)
            thread.start()
            while thread.is_alive():
                if stop_event is not None and stop_event.is_set():
                    worker.request_stop()
                thread.join(0.25)
            if holder.get('error') is not None:
                raise holder['error']
            result = holder.get('result') or {}
            answer = str((result or {}).get('answer', '') or 'Browser Use task completed.').strip()
            metadata = dict((result or {}).get('metadata') or {})
            metadata.update({
                'goal': goal,
                'execution_mode': str(config.get('llm_wrapper', '') or ''),
                'browser_task': task,
                'browser_use_isolated_session': bool(config.get('browser_use_isolated_session')),
                'browser_use_profile_slot': int(config.get('browser_use_profile_slot', 0) or 0),
            })
            return {
                'capability': BROWSER_USE_CAPABILITY,
                'capability_label': specialized_capability_label(BROWSER_USE_CAPABILITY),
                'model_name': str(config.get('model', '') or '').strip(),   # the worker updates it on failover
                'profile_name': str(config.get('profile_name', '') or '').strip(),
                'text_output': answer,
                'artifacts': [],
                'metadata': metadata,
            }
        except Exception as exc:
            if isinstance(child_attempt, dict):
                child_attempt['finalize_reason'] = str(exc)
            return {
                'capability': BROWSER_USE_CAPABILITY,
                'capability_label': specialized_capability_label(BROWSER_USE_CAPABILITY),
                'model_name': '',
                'text_output': f'Browser Use step failed: {str(exc)}',
                'artifacts': [],
                'metadata': {'goal': goal, 'execution_mode': 'browser_use'},
            }
        finally:
            self._release_browser_use_session(session_id)
            if isinstance(child_attempt, dict):
                child_attempt['status'] = 'failed' if child_attempt.get('finalize_reason') else 'finished'
                self._finalize_agent_run(
                    child_attempt,
                    str(child_attempt.get('status', '') or 'finished'),
                    str(child_attempt.get('finalize_reason', '') or ''),
                )

    def _execute_computer_use_step(self,
                                   *,
                                   goal: str,
                                   question_text: str,
                                   shared_context: str,
                                   step_context: str,
                                   previous_results: list[dict],
                                   downstream_extract: str = '',
                                   conversation_path: str | None = None,
                                   stop_event: threading.Event | None = None,
                                   step_stream_callback=None,
                                   profile_override_name: str = '',
                                   **_kwargs) -> dict:
        def clip(text: str, limit: int) -> str:
            text = str(text or '').strip()
            return text if len(text) <= limit else text[:limit].rstrip() + '\n[...truncated]'

        prior = []
        for result in (previous_results or [])[-3:]:
            body = specialized_step_context_output(result)
            if body:
                prior.append(clip(body, 1800))
        parts = [
            'Original user request:\n' + clip(question_text, 4000),
            'Desktop automation goal:\n' + str(goal or '').strip(),
        ]
        if shared_context.strip():
            parts.append('Broccoli global retrieved context:\n' + clip(shared_context, 3500))
        if step_context.strip():
            parts.append('Broccoli step-specific retrieved context:\n' + clip(step_context, 3500))
        if prior:
            parts.append('Previous step output:\n' + '\n\n'.join(prior))
        if downstream_extract:
            parts.append('Downstream handoff requirement:\n' + clip(downstream_extract, 800))
        parts.append(
            'Use the local computer only for the desktop-automation part of this step. '
            'Return concrete evidence, applications/windows visited, and errors encountered.'
        )
        task = '\n\n'.join(parts)
        try:
            config = self._prepare_computer_use_config(
                task, history_messages=[], storage_history_messages=[], interactive=False,
                profile_override_name=profile_override_name,
            )
            if str(conversation_path or '').strip():
                # Park the final screenshot with the conversation's other step
                # artifacts (per-conversation attachments dir) instead of the
                # global captures dir; the worker mkdirs the parent on save.
                config['final_screenshot'] = os.path.join(
                    conversation_attachment_dir(str(conversation_path)),
                    f'computer_use_{int(time.time() * 1000)}.png',
                )
            request = {
                'task': task,
                'target_display': config.get('target_display'),
                'event': threading.Event(),
                'approved': False,
            }
            self.computer_use_approval_requested.emit(request)
            while not request['event'].wait(0.25):
                if stop_event is not None and stop_event.is_set():
                    return {
                        'capability': COMPUTER_USE_CAPABILITY,
                        'capability_label': 'Computer Use',
                        'model_name': str(config.get('model', '') or ''),
                        'text_output': 'Computer Use task was cancelled.',
                        'artifacts': [],
                        'metadata': {'goal': goal, 'cancelled': True},
                    }
            if not request.get('approved'):
                return {
                    'capability': COMPUTER_USE_CAPABILITY,
                    'capability_label': 'Computer Use',
                    'model_name': str(config.get('model', '') or ''),
                    'text_output': 'Computer Use task was cancelled by the user.',
                    'artifacts': [],
                    'metadata': {'goal': goal, 'cancelled': True},
                }
            on_progress = None
            if callable(step_stream_callback):
                on_progress = lambda message: step_stream_callback(str(message or '') + '\n')
            worker = ComputerUseThread(config, on_progress=on_progress)
            holder = {'result': None, 'error': None}

            def run_worker():
                try:
                    holder['result'] = worker.run_blocking()
                except Exception as exc:
                    holder['error'] = exc

            thread = threading.Thread(target=run_worker, daemon=True)
            thread.start()
            while thread.is_alive():
                if stop_event is not None and stop_event.is_set():
                    worker.request_stop()
                thread.join(0.25)
            if holder['error'] is not None:
                raise holder['error']
            result = holder['result'] or {}
            metadata = dict(result.get('metadata') or {})
            metadata.update({'goal': goal, 'computer_task': task, 'execution_mode': 'openai'})
            screenshot = str(metadata.get('final_screenshot', '') or '')
            # the worker switches models on a COPY of the config: what it really used is there
            used = getattr(worker, 'config', None) if isinstance(getattr(worker, 'config', None), dict) else config
            return {
                'capability': COMPUTER_USE_CAPABILITY,
                'capability_label': 'Computer Use',
                'model_name': str(used.get('model', '') or config.get('model', '') or ''),
                'profile_name': str(used.get('profile_name', '') or config.get('profile_name', '') or ''),
                'text_output': _computer_use_result_text(
                    result,
                    failure_prefix='Computer Use step failed: ',
                ),
                'artifacts': [screenshot] if screenshot else [],
                'metadata': metadata,
            }
        except Exception as exc:
            return {
                'capability': COMPUTER_USE_CAPABILITY,
                'capability_label': 'Computer Use',
                'model_name': '',
                'text_output': f'Computer Use step failed: {exc}',
                'artifacts': [],
                'metadata': {'goal': goal, 'execution_mode': 'computer_use'},
            }

    def _execute_terminal_command_step(self,
                                       *,
                                       goal: str,
                                       question_text: str,
                                       shared_context: str,
                                       step_context: str,
                                       previous_results: list[dict],
                                       downstream_extract: str = '',
                                       terminal_command_runner=None,
                                       profile_override_name: str = '',
                                       reasoning_effort: str = '',
                                       archive_context: dict | None = None,
                                       archive_reader=None,
                                       parent_run_id: str = '') -> dict:
        capability_label = specialized_capability_label(TERMINAL_COMMAND_CAPABILITY)
        if not callable(terminal_command_runner):
            return {
                'capability': TERMINAL_COMMAND_CAPABILITY,
                'capability_label': capability_label,
                'model_name': '',
                'text_output': 'Terminal command step failed: Terminal command runner is unavailable.',
                'artifacts': [],
                'metadata': {'goal': goal, 'execution_mode': 'broccoli_terminal'},
            }
        store = load_settings_store()
        profile = (
            get_profile_from_store_by_name(store, profile_override_name)
            if str(profile_override_name or '').strip()
            else None
        ) or get_planner_profile_from_store(store) or load_active_settings_profile()
        model_name = str(profile.get('model', '') or '').strip()
        prompt = self._build_media_generation_input(
            question_text, shared_context, step_context, previous_results, goal, archive_context=archive_context
        )
        messages = [
            {
                'role': 'system',
                'content': (
                    'You prepare one local terminal command for Broccoli Agent. '
                    'Return one JSON object only, with no markdown. '
                    'The command will be shown to the user for approval and run visibly in Broccoli Terminal. '
                    'Prefer read-only inspection commands first. For write or modification commands, include exact target_paths '
                    'so Broccoli can back them up before asking for approval. '
                    'Never invent file paths; use only paths from the user request, context, or current workspace assumptions. '
                    # FIX-45: the approval dialog reads these fields out to the user
                    f'Use {preferred_ui_language()} for purpose, expected_result, risk explanations, and every explanatory string. '
                    'Keep command and target_paths exact and untranslated.'
                ),
            },
            {
                'role': 'user',
                'content': (
                    f'Current workspace: {os.getcwd()}\n\n'
                    f'User request and context:\n{prompt}\n\n'
                    f'Step goal:\n{goal}\n'
                    + (f'Downstream need:\n{downstream_extract}\n' if downstream_extract else '')
                    + (
                        '\nThe command may reference archived file paths directly (e.g. process a downloaded artifact).\n'
                        if str((archive_context or {}).get('manifest', '') or '').strip()
                        or str((archive_context or {}).get('preload', '') or '').strip()
                        else ''
                    )
                    + '\nReturn JSON with fields: command, purpose, expected_result, risk '
                      '("read", "write", "dangerous", or "unknown"), target_paths array, timeout_seconds. '
                    + f'All explanatory field values must be written in {preferred_ui_language()}.'
                ),
            },
        ]
        raw = ''
        try:
            raw, _executions = self._run_profile_chat_completion_with_code_execution(
                profile,
                messages,
                reasoning_effort=reasoning_effort,
                archive_reader=archive_reader,
                archive_read_instruction=str((archive_context or {}).get('read_instruction', '') or ''),
                # 命令规划历来单发，只为读档接进循环：代码围栏若被执行会
                # 绕过终端命令审批对话框。
                enable_code_execution=False,
                # Streamed: a long script takes the model minutes to write (137 s measured
                # 2026-10-21), and a non-streamed reply must arrive whole within the
                # profile timeout (60 s). The stream only needs to keep flowing.
                on_delta=lambda _delta: None,
                retry_timeouts=False,
            )
            arguments = parse_json_object_from_text(raw)
        except Exception as exc:
            return {
                'capability': TERMINAL_COMMAND_CAPABILITY,
                'capability_label': capability_label,
                'model_name': model_name,
                'text_output': f'Terminal command step failed while preparing command: {exc}',
                'artifacts': [],
                'metadata': {'goal': goal, 'execution_mode': 'broccoli_terminal'},
            }
        if not isinstance(arguments, dict):
            arguments = {}
        command = str(arguments.get('command', '') or '').strip()
        if not command:
            return {
                'capability': TERMINAL_COMMAND_CAPABILITY,
                'capability_label': capability_label,
                'model_name': model_name,
                'text_output': 'Terminal command step failed: no command was proposed.',
                'artifacts': [],
                'metadata': {'goal': goal, 'execution_mode': 'broccoli_terminal', 'raw_command_plan': raw},
            }
        result = terminal_command_runner(arguments)
        result_text = str((result or {}).get('text', '') or '').strip()
        if not result_text:
            result_text = (
                f"Terminal command {str((result or {}).get('status', '') or 'finished')}.\n"
                f"Command: {command}\n\n"
                + _agent_terminal_result_text(str((result or {}).get('output', '') or ''))
            ).strip()
        return {
            'capability': TERMINAL_COMMAND_CAPABILITY,
            'capability_label': capability_label,
            'model_name': model_name,
            'text_output': result_text,
            'artifacts': [],
            'metadata': {
                'goal': goal,
                'execution_mode': 'broccoli_terminal',
                'terminal_command': command,
                'terminal_result': result or {},
            },
        }

    def _execute_specialized_step(self,
                                  capability: str,
                                  goal: str,
                                  question_text: str,
                                  shared_context: str,
                                  step_context: str,
                                  previous_results: list[dict],
                                  attachment_records: list[dict],
                                  downstream_extract: str = '',
                                  skill_name: str = '',
                                  conversation_path: str | None = None,
                                  stop_event: threading.Event | None = None,
                                  terminal_command_runner=None,
                                  external_target_runner=None,
                                  profile_override_name: str = '',
                                  external_tail_task_sections: bool = False,
                                  step_stream_callback=None,
                                  reasoning_effort: str = '',
                                  archive_context: dict | None = None,
                                  archive_reader=None,
                                  parent_run_id: str = '',
                                  _tried_profiles: frozenset = frozenset()) -> dict:
        """事件日志包装（方案3 影子账本）：真正的执行逻辑在
        _execute_specialized_step_impl。profile 兜底 / 模型失败切换的递归
        重试也从这里进，所以每次尝试各有一对 step/start-result 事件。"""
        run_id = str(parent_run_id or '')
        append_agent_run_event(run_id, 'step/start', {
            'capability': capability,
            'goal': goal,
            'skill_name': skill_name,
            'profile_override_name': profile_override_name,
            'reasoning_effort': reasoning_effort,
            'shared_context_chars': len(str(shared_context or '')),
            'step_context_chars': len(str(step_context or '')),
            'previous_results': len(previous_results or []),
            'tried_profiles': sorted(_tried_profiles) if _tried_profiles else [],
        })
        try:
            result = self._execute_specialized_step_impl(
                capability=capability,
                goal=goal,
                question_text=question_text,
                shared_context=shared_context,
                step_context=step_context,
                previous_results=previous_results,
                attachment_records=attachment_records,
                downstream_extract=downstream_extract,
                skill_name=skill_name,
                conversation_path=conversation_path,
                stop_event=stop_event,
                terminal_command_runner=terminal_command_runner,
                external_target_runner=external_target_runner,
                profile_override_name=profile_override_name,
                external_tail_task_sections=external_tail_task_sections,
                step_stream_callback=step_stream_callback,
                reasoning_effort=reasoning_effort,
                archive_context=archive_context,
                archive_reader=archive_reader,
                parent_run_id=parent_run_id,
                _tried_profiles=_tried_profiles,
            )
        except BaseException as exc:
            append_agent_run_event(run_id, 'step/error', {
                'capability': capability,
                'goal': goal,
                'error': str(exc),
            })
            raise
        summary = result if isinstance(result, dict) else {}
        if isinstance(result, dict) and not str(result.get('profile_name', '') or '').strip():
            # a failover retry came back through this wrapper and was named there already
            result['profile_name'] = self._step_profile_name(capability, profile_override_name,
                                                             result.get('model_name', ''))
        text_output = str(summary.get('text_output', '') or '')
        append_agent_run_event(run_id, 'step/result', {
            'capability': summary.get('capability', capability),
            'model_name': summary.get('model_name', ''),
            'profile_name': summary.get('profile_name', ''),
            'text_output': text_output[:2000],
            'text_chars': len(text_output),
            'artifacts': list(summary.get('artifacts') or []),
            'metadata': summary.get('metadata', {}),
        })
        return result

    @staticmethod
    def _step_profile_name(capability: str, profile_override_name: str = '', model_name: str = '') -> str:
        """The settings profile a step ran on — the same choice its executor makes. Browser /
        Computer Use name it themselves (their workers switch models inside); a web target or a
        custom service (@ / &) has no profile: its name is what the step shows as the model."""
        if str(model_name or '').strip().startswith(('@', '&')):
            return ''
        if capability in (BROWSER_USE_CAPABILITY, COMPUTER_USE_CAPABILITY):
            return ''
        try:
            store = load_settings_store()
            name = str(profile_override_name or '').strip()
            if name:
                profile = get_profile_from_store_by_name(store, name)
                return str((profile or {}).get('name', '') or name)
            if capability == SPECIALIZED_SKILL_CAPABILITY:
                profile = (get_profile_from_store_by_name(store, str(store.get('active_profile', '') or ''))
                           or load_active_settings_profile())
            elif capability == TERMINAL_COMMAND_CAPABILITY:
                profile = get_planner_profile_from_store(store) or load_active_settings_profile()
            else:
                profile = resolve_specialized_profile(store, capability, None)
            return str((profile or {}).get('name', '') or '')
        except Exception:
            return ''

    def _execute_specialized_step_impl(self,
                                       capability: str,
                                       goal: str,
                                       question_text: str,
                                       shared_context: str,
                                       step_context: str,
                                       previous_results: list[dict],
                                       attachment_records: list[dict],
                                       downstream_extract: str = '',
                                       skill_name: str = '',
                                       conversation_path: str | None = None,
                                       stop_event: threading.Event | None = None,
                                       terminal_command_runner=None,
                                       external_target_runner=None,
                                       profile_override_name: str = '',
                                       external_tail_task_sections: bool = False,
                                       step_stream_callback=None,
                                       reasoning_effort: str = '',
                                       archive_context: dict | None = None,
                                       archive_reader=None,
                                       parent_run_id: str = '',
                                       _tried_profiles: frozenset = frozenset()) -> dict:
        store = load_settings_store()
        if capability == SPECIALIZED_SKILL_CAPABILITY:
            return self._execute_skill_step(
                skill_name=skill_name,
                goal=goal,
                question_text=question_text,
                shared_context=shared_context,
                step_context=step_context,
                previous_results=previous_results,
                downstream_extract=downstream_extract,
                store=store,
                profile_override_name=profile_override_name,
                reasoning_effort=reasoning_effort,
                archive_context=archive_context,
                archive_reader=archive_reader,
                parent_run_id=parent_run_id,
            )
        if capability == BROWSER_USE_CAPABILITY:
            return self._execute_browser_use_step(
                goal=goal,
                question_text=question_text,
                shared_context=shared_context,
                step_context=step_context,
                previous_results=previous_results,
                downstream_extract=downstream_extract,
                conversation_path=conversation_path,
                stop_event=stop_event,
                step_stream_callback=step_stream_callback,
                reasoning_effort=reasoning_effort,
                profile_override_name=profile_override_name,
                archive_context=archive_context,
                parent_run_id=parent_run_id,
            )
        if capability == COMPUTER_USE_CAPABILITY:
            return self._execute_computer_use_step(
                goal=goal,
                question_text=question_text,
                shared_context=shared_context,
                step_context=step_context,
                previous_results=previous_results,
                downstream_extract=downstream_extract,
                conversation_path=conversation_path,
                stop_event=stop_event,
                step_stream_callback=step_stream_callback,
                profile_override_name=profile_override_name,
            )
        if capability == TERMINAL_COMMAND_CAPABILITY:
            return self._execute_terminal_command_step(
                goal=goal,
                question_text=question_text,
                shared_context=shared_context,
                step_context=step_context,
                previous_results=previous_results,
                downstream_extract=downstream_extract,
                terminal_command_runner=terminal_command_runner,
                profile_override_name=profile_override_name,
                reasoning_effort=reasoning_effort,
                archive_context=archive_context,
                archive_reader=archive_reader,
                parent_run_id=parent_run_id,
            )
        specialized_profiles = get_specialized_profiles_from_store(store)
        selected_profile_name = (
            str(profile_override_name or '').strip()
            or str(specialized_profiles.get(capability, '') or '').strip()
        )
        def run_profile_fallback(original_name: str) -> dict | None:
            """@/& 运行时不可用：改用该能力候选里下一个可用 profile 重跑
            本步（递归一层；fallback 是普通 profile 不会再回落），并在
            metadata 记下来源，状态行可见。没有可用候选返回 None。"""
            fallback_name = first_usable_profile_candidate(store, capability)
            if not fallback_name:
                return None
            if not agent_run_budget_consume(parent_run_id, 'profile_fallbacks'):
                return None
            fallback_result = self._execute_specialized_step(
                capability=capability,
                goal=goal,
                question_text=question_text,
                shared_context=shared_context,
                step_context=step_context,
                previous_results=previous_results,
                attachment_records=attachment_records,
                downstream_extract=downstream_extract,
                skill_name=skill_name,
                conversation_path=conversation_path,
                stop_event=stop_event,
                terminal_command_runner=terminal_command_runner,
                external_target_runner=external_target_runner,
                profile_override_name=fallback_name,
                external_tail_task_sections=external_tail_task_sections,
                step_stream_callback=step_stream_callback,
                reasoning_effort=reasoning_effort,
                archive_context=archive_context,
                archive_reader=archive_reader,
            )
            if isinstance(fallback_result, dict):
                fallback_metadata = dict(fallback_result.get('metadata') or {})
                fallback_metadata['fallback_from'] = original_name
                fallback_result['metadata'] = fallback_metadata
            return fallback_result

        def run_model_failover(exc: Exception, current_profile: dict | None) -> dict | None:
            """普通 profile 跑模型时命中 429/额度类不可用（model_cooldown、
            rate limit、401/额度等，见 _is_model_unavailable_error）：按本能力
            候选顺位切到下一个可用普通 profile 重跑本步，_tried_profiles 累积
            已试名字防止环。非不可用错误、或没有下一顺位候选则返回 None，由
            调用方走原来的失败路径。"""
            if not _is_model_unavailable_error(exc):
                return None
            current_name = str((current_profile or {}).get('name', '') or '').strip()
            tried = set(_tried_profiles)
            if current_name:
                tried.add(current_name)
            next_name = ''
            for cand in ordered_usable_profile_candidates(store, capability, exclude=tried):
                next_name = cand
                break
            if not next_name:
                return None
            if not agent_run_budget_consume(parent_run_id, 'model_failovers'):
                return None
            failover_result = self._execute_specialized_step(
                capability=capability,
                goal=goal,
                question_text=question_text,
                shared_context=shared_context,
                step_context=step_context,
                previous_results=previous_results,
                attachment_records=attachment_records,
                downstream_extract=downstream_extract,
                skill_name=skill_name,
                conversation_path=conversation_path,
                stop_event=stop_event,
                terminal_command_runner=terminal_command_runner,
                external_target_runner=external_target_runner,
                profile_override_name=next_name,
                external_tail_task_sections=external_tail_task_sections,
                step_stream_callback=step_stream_callback,
                reasoning_effort=reasoning_effort,
                archive_context=archive_context,
                archive_reader=archive_reader,
                parent_run_id=parent_run_id,
                _tried_profiles=frozenset(tried),
            )
            if isinstance(failover_result, dict):
                failover_metadata = dict(failover_result.get('metadata') or {})
                failover_metadata['failover_from'] = current_name or str((current_profile or {}).get('model', '') or '')
                failover_result['metadata'] = failover_metadata
            return failover_result

        if selected_profile_name.startswith(CUSTOM_SERVICE_PREFIX):
            # 自定义服务（'&名称'）：与 @target 同构的前缀分发。
            service = find_custom_service_by_ref(selected_profile_name, store)
            if service is not None:
                # A pure search source uses the goal as its query: keep user notes out.
                return self._run_custom_service_step(
                    service, capability, strip_step_goal_user_notes(goal), question_text,
                )
            # 服务被删/停用：跳过它，用该能力候选里下一个可用 profile。
            fallback_result = run_profile_fallback(selected_profile_name)
            if fallback_result is not None:
                return fallback_result
            return {
                'capability': capability,
                'capability_label': specialized_capability_label(capability),
                'model_name': selected_profile_name,
                'text_output': f'Custom service {selected_profile_name} is not configured or is disabled.',
                'artifacts': [],
                'metadata': {'goal': goal, 'execution_mode': 'custom_service'},
            }
        if selected_profile_name.startswith('@'):
            target_active = False
            if callable(external_target_runner):
                try:
                    target_active = self._external_target_by_alias(selected_profile_name[1:]) is not None
                except Exception:
                    target_active = False
            if not target_active:
                # 目标没打开/不在此执行上下文：跳过，用下一个可用 profile。
                fallback_result = run_profile_fallback(selected_profile_name)
                if fallback_result is not None:
                    return fallback_result
                return {
                    'capability': capability,
                    'capability_label': specialized_capability_label(capability),
                    'model_name': selected_profile_name,
                    'text_output': f'External target {selected_profile_name} is not open or available in this execution context.',
                    'artifacts': [],
                    'metadata': {
                        'goal': goal,
                        'execution_mode': 'external_target',
                        'external_target_profile': selected_profile_name,
                    },
                }
            messages = build_specialized_step_messages(
                capability,
                goal,
                question_text,
                shared_context,
                previous_results,
                downstream_extract,
                step_context,
                tail_task_sections=external_tail_task_sections,
                archive_context={
                    'manifest': str((archive_context or {}).get('manifest', '') or ''),
                    'preload': str((archive_context or {}).get('preload', '') or ''),
                },
            )
            result = external_target_runner({
                'profile_name': selected_profile_name,
                'prompt': self._external_target_prompt_from_messages(messages),
                'goal': goal,
                'question_text': question_text,
                'shared_context': '\n\n'.join(part for part in [shared_context, step_context] if str(part or '').strip()),
                'attachment_records': list(attachment_records or []),
            })
            output = str((result or {}).get('answer', '') or (result or {}).get('text', '') or '').strip()
            status = str((result or {}).get('status', '') or 'finished').strip()
            if not output:
                # 目标开着但没拿到可读回复（超时/页面异常）：同样跳过，
                # 用下一个可用 profile 重跑本步。
                fallback_result = run_profile_fallback(selected_profile_name)
                if fallback_result is not None:
                    return fallback_result
                output = f'External target {selected_profile_name} returned no readable text.'
            return {
                'capability': capability,
                'capability_label': specialized_capability_label(capability),
                'model_name': selected_profile_name,
                'text_output': output,
                'artifacts': [],
                'metadata': {
                    'goal': goal,
                    'execution_mode': 'external_target',
                    'external_target_profile': selected_profile_name,
                    'external_target_status': status,
                    'external_target_payload': result or {},
                },
            }
        profile = (
            get_profile_from_store_by_name(store, profile_override_name)
            if str(profile_override_name or '').strip()
            else None
        ) or resolve_specialized_profile(store, capability, None)
        if profile is None:
            return {}
        model_name = str(profile.get('model', '')).strip()
        execution_mode = resolve_specialized_execution_mode(store, capability)
        if execution_mode == 'generic_chat_completion':
            # 通用对话模式：任何能力在设置页选了 "Chat Completions (generic)"
            # 就不走专用 SDK，改用普通对话补全（该能力注册表里的 specialist
            # 提示词引导模型产出对应交付物或提示词包）。原先只有 web_search
            # 有这个选项，2026-09-06 起媒体类能力全部提供。
            executions = []
            try:
                output, executions = self._run_profile_chat_completion_with_code_execution(
                    profile,
                    build_specialized_step_messages(capability, goal, question_text, shared_context, previous_results, downstream_extract, step_context, archive_context=archive_context),
                    on_delta=step_stream_callback,
                    reasoning_effort=reasoning_effort,
                    archive_reader=archive_reader,
                    archive_read_instruction=str((archive_context or {}).get('read_instruction', '') or ''),
                )
            except Exception as exc:
                failover = run_model_failover(exc, profile)
                if failover is not None:
                    return failover
                output = f'{specialized_capability_label(capability)} step failed: {str(exc)}'
            return {
                'capability': capability,
                'capability_label': specialized_capability_label(capability),
                'model_name': model_name,
                'text_output': output,
                'artifacts': [],
                'metadata': {'goal': goal, 'execution_mode': execution_mode, 'code_executions': executions},
            }
        if capability == 'web_search':
            try:
                return self._run_web_search_step(
                    profile, goal, question_text, shared_context, step_context, previous_results,
                    archive_context=archive_context,
                )
            except Exception as exc:
                failover = run_model_failover(exc, profile)
                if failover is not None:
                    return failover
                return {
                    'capability': capability,
                    'capability_label': specialized_capability_label(capability),
                    'model_name': model_name,
                    'text_output': f'Web search step failed: {str(exc)}',
                    'artifacts': [],
                    'metadata': {'goal': goal, 'execution_mode': execution_mode},
                }
        if capability == 'image_generation':
            try:
                return self._run_image_generation_step(
                    profile, goal, question_text, shared_context, step_context, previous_results,
                    archive_context=archive_context,
                )
            except Exception as exc:
                failover = run_model_failover(exc, profile)
                if failover is not None:
                    return failover
                return {
                    'capability': capability,
                    'capability_label': specialized_capability_label(capability),
                    'model_name': model_name,
                    'text_output': f'Image generation step failed: {str(exc)}',
                    'artifacts': [],
                    'metadata': {'goal': goal, 'execution_mode': execution_mode},
                }
        if capability == 'video_generation':
            try:
                return self._run_video_generation_step(
                    profile, goal, question_text, shared_context, step_context, previous_results,
                    archive_context=archive_context,
                )
            except Exception as exc:
                failover = run_model_failover(exc, profile)
                if failover is not None:
                    return failover
                return {
                    'capability': capability,
                    'capability_label': specialized_capability_label(capability),
                    'model_name': model_name,
                    'text_output': f'Video generation step failed: {str(exc)}',
                    'artifacts': [],
                    'metadata': {'goal': goal, 'execution_mode': execution_mode},
                }
        if capability == 'text_to_speech':
            try:
                return self._run_text_to_speech_step(
                    profile, goal, question_text, step_context, previous_results,
                    archive_context=archive_context,
                )
            except Exception as exc:
                failover = run_model_failover(exc, profile)
                if failover is not None:
                    return failover
                return {
                    'capability': capability,
                    'capability_label': specialized_capability_label(capability),
                    'model_name': model_name,
                    'text_output': f'Text-to-speech step failed: {str(exc)}',
                    'artifacts': [],
                    'metadata': {'goal': goal, 'execution_mode': execution_mode},
                }
        if capability in {'speech_to_text', 'video_to_text'}:
            try:
                return self._run_transcription_step(capability, profile, goal, attachment_records)
            except Exception as exc:
                failover = run_model_failover(exc, profile)
                if failover is not None:
                    return failover
                return {
                    'capability': capability,
                    'capability_label': specialized_capability_label(capability),
                    'model_name': model_name,
                    'text_output': f'{specialized_capability_label(capability)} step failed: {str(exc)}',
                    'artifacts': [],
                    'metadata': {'goal': goal, 'execution_mode': execution_mode},
                }
        if not capability_is_implemented(capability):
            # 注册表 implemented=False 的能力（当前只有 video_generation）：
            # planner/复审的宣传清单已隐藏它，这里兜住斜杠强制/历史计划。
            return unimplemented_capability_step_result(capability, model_name, goal, execution_mode)
        executions = []
        try:
            output, executions = self._run_profile_chat_completion_with_code_execution(
                profile,
                build_specialized_step_messages(capability, goal, question_text, shared_context, previous_results, downstream_extract, step_context, archive_context=archive_context),
                on_delta=step_stream_callback,
                reasoning_effort=reasoning_effort,
                archive_reader=archive_reader,
                archive_read_instruction=str((archive_context or {}).get('read_instruction', '') or ''),
            )
        except Exception as exc:
            failover = run_model_failover(exc, profile)
            if failover is not None:
                return failover
            output = f'Step failed: {str(exc)}'
        return {
            'capability': capability,
            'capability_label': specialized_capability_label(capability),
            'model_name': model_name,
            'text_output': output,
            'artifacts': [],
            'metadata': {'goal': goal, 'execution_mode': execution_mode, 'code_executions': executions},
        }

    def _execute_specialized_plan(self,
                                  plan: dict,
                                  question_text: str,
                                  shared_context: str,
                                  history_messages: list[dict],
                                  retrieval_documents: list[dict],
                                  api_key: str,
                                  endpoint: str,
                                  model: str,
                                  timeout: int,
                                  selected_message_indices: set | list | None,
                                  attachment_records: list[dict],
                                  conversation_path: str | None = None,
                                  run_id: str = '',
                                  progress_callback=None,
                                  stop_event: threading.Event | None = None,
                                  supplement_provider=None,
                                  initial_user_notes: list[dict] | None = None,
                                  terminal_command_runner=None,
                                  external_target_runner=None,
                                  plan_update_callback=None,
                                  plan_control_provider=None,
                                  step_stream_callback=None,
                                  member_stream_callback=None) -> list[dict]:
        steps = list(plan.get('steps', []) or [])
        # Every note the user added during this run, oldest first; each step's prompt goal
        # carries all of them (compose_step_goal_with_user_notes).
        live_user_notes = normalize_agent_supplement_records(initial_user_notes)
        for initial_index, initial_step in enumerate(steps, start=1):
            if isinstance(initial_step, dict) and not str(initial_step.get('_plan_step_id', '') or '').strip():
                initial_step['_plan_step_id'] = f"runtime-{int(time.time() * 1000)}-{initial_index}"
        final_focus = str(plan.get('finalize_focus', '') or '').strip()
        results = []
        archive_entries = []
        archive_enabled = bool(
            (load_settings_store().get('globals') or {}).get(AGENT_STEP_ARCHIVE_ENABLED_KEY, True)
        )
        archive_run_id = _agent_step_archive_slug(
            run_id, datetime.datetime.now().strftime('%Y%m%d-%H%M%S-%f')
        )
        run_dir = _archive_safe(agent_step_archive_run_dir, conversation_path or '', archive_run_id) if archive_enabled else ''
        if run_dir:
            _archive_safe(prune_agent_step_archives, conversation_path or '', run_dir)
        active_stream_slug = {'value': 'step'}

        def archive_manifest() -> str:
            if not archive_enabled:
                return ''
            return _archive_safe(
                build_step_archive_manifest_block,
                conversation_path or '',
                _agent_step_archive_run_dirs(conversation_path or '', limit=AGENT_STEP_ARCHIVE_KEEP_RUNS),
                AGENT_STEP_ARCHIVE_MANIFEST_PROMPT_CHARS,
            ) or ''

        def archive_result(step_token, item: dict, goal_text: str = '', status: str = ''):
            if not run_dir or not isinstance(item, dict):
                return
            entry = _archive_safe(
                write_step_archive_entry,
                run_dir,
                step_token,
                item,
                {'goal': goal_text, 'status': status},
            )
            if isinstance(entry, dict):
                archive_entries.append(entry)
                _archive_safe(
                    rewrite_step_archive_manifest,
                    run_dir,
                    {'run_id': archive_run_id, 'conversation_path': str(conversation_path or '')},
                    archive_entries,
                )
        i = 0
        dynamic_additions = 0
        executed_steps = 0
        max_executed_steps = len(steps) + SPECIALIZED_DYNAMIC_STEP_MAX_ADDITIONS

        def progress(message: str):
            if progress_callback is None:
                return
            try:
                progress_callback(str(message or '').strip())
            except Exception:
                pass

        def emit_plan_update(payload: dict):
            if plan_update_callback is None or not isinstance(payload, dict):
                return
            try:
                plan_update_callback(payload)
            except Exception:
                pass

        def stream_delta(text: str):
            if run_dir:
                _archive_safe(append_step_archive_stream, run_dir, active_stream_slug.get('value', 'step'), str(text or ''))
            if step_stream_callback is None:
                return
            try:
                step_stream_callback(str(text or ''))
            except Exception:
                pass

        def read_plan_control(step_id: str) -> dict:
            if not callable(plan_control_provider):
                return {}
            try:
                control = plan_control_provider(str(step_id or ''))
                return control if isinstance(control, dict) else {}
            except Exception:
                return {}

        def apply_pending_plan_order(start_index: int):
            if not callable(plan_control_provider):
                return
            order = read_plan_control('__order__').get('order') or []
            if not order:
                return
            order_map = {str(step_id): index for index, step_id in enumerate(order)}
            prefix = steps[:start_index]
            suffix = steps[start_index:]
            indexed_suffix = list(enumerate(suffix))
            indexed_suffix.sort(
                key=lambda pair: (
                    order_map.get(
                        str((pair[1] or {}).get('_plan_step_id', '') or ''),
                        len(order_map) + pair[0],
                    ),
                    pair[0],
                )
            )
            steps[:] = prefix + [item for _original_index, item in indexed_suffix]

        def pause_for_pending_step_review(step_to_review: dict, seconds: int, reason: str = ''):
            try:
                seconds = max(0, int(seconds or 0))
            except Exception:
                seconds = 0
            if seconds <= 0:
                return
            step_id = str((step_to_review or {}).get('_plan_step_id', '') or '').strip()
            label = skill_step_label(step_to_review if isinstance(step_to_review, dict) else {})
            progress(
                _tr('Waiting {seconds}s for Plan edits before execution.').format(seconds=seconds)
                + ('\n' + _tr('Reason: {reason}').format(reason=reason) if str(reason or '').strip() else '')
                + ('\n' + _tr('Step: {label}').format(label=label) if label else '')
            )
            deadline = time.monotonic() + seconds
            last_reported = seconds + 1
            held_remaining = None
            while time.monotonic() < deadline:
                if stop_event is not None and stop_event.is_set():
                    return
                # 计划浮窗的"跳过"/"立即执行"都能提前结束倒计时：跳过由调用方在
                # 暂停返回后复查 skip_requested 跳过本步；立即执行则直接进入执行。
                control_now = read_plan_control(step_id) if step_id else {}
                if bool(control_now.get('skip_requested', False)) or bool(control_now.get('run_now_requested', False)):
                    break
                if bool(control_now.get('hold_requested', False)):
                    # 冻结倒计时：剩余秒数原地不动（截止时间随时间同步后移），
                    # 用户可以慢慢编辑/调序；解除后从冻结值继续倒数。
                    if held_remaining is None:
                        held_remaining = max(1, int(math.ceil(deadline - time.monotonic())))
                        emit_plan_update({
                            'type': 'step_pause',
                            'step_id': step_id,
                            'step': dict(step_to_review or {}),
                            'capability': str((step_to_review or {}).get('capability', '') or ''),
                            'capability_label': label,
                            'goal': str((step_to_review or {}).get('goal', '') or ''),
                            'status': 'pending',
                            'pause_remaining': held_remaining,
                            'pause_held': True,
                        })
                        progress(_tr('Countdown held at {seconds}s for Plan edits.').format(seconds=held_remaining))
                    deadline = time.monotonic() + held_remaining
                    time.sleep(0.2)
                    continue
                if held_remaining is not None:
                    held_remaining = None
                    last_reported = -1   # 解除冻结：强制发一条新的倒计时事件
                remaining = max(0, int(math.ceil(deadline - time.monotonic())))
                if remaining != last_reported:
                    last_reported = remaining
                    emit_plan_update({
                        'type': 'step_pause',
                        'step_id': step_id,
                        'step': dict(step_to_review or {}),
                        'capability': str((step_to_review or {}).get('capability', '') or ''),
                        'capability_label': label,
                        'goal': str((step_to_review or {}).get('goal', '') or ''),
                        'status': 'pending',
                        'pause_remaining': remaining,
                        'pause_held': False,
                    })
                time.sleep(0.2)
            emit_plan_update({
                'type': 'step_pause',
                'step_id': step_id,
                'step': dict(step_to_review or {}),
                'capability': str((step_to_review or {}).get('capability', '') or ''),
                'capability_label': label,
                'goal': str((step_to_review or {}).get('goal', '') or ''),
                'status': 'pending',
                'pause_remaining': 0,
            })

        def consume_supplements(stage: str) -> str:
            if not callable(supplement_provider):
                return ''
            try:
                supplements = normalize_agent_supplement_records(supplement_provider() or [])
            except Exception:
                supplements = []
            if not supplements:
                return ''
            block = build_agent_supplement_instruction_block(supplements, continuation=False)
            result = build_agent_supplement_step_result(supplements, stage=stage)
            if result:
                results.append(result)
                emit_plan_update({
                    'type': 'supplement',
                    'stage': stage,
                    'text': block,
                    'status': 'finished',
                })
            if block:
                # Carried by every later step's goal (see live_user_notes), not by
                # shared_context, whose tail browser/computer-use steps clip away.
                live_user_notes.extend(supplements)
                progress(
                    _tr('Inserted user-added instruction into specialized pipeline')
                    + ('\n' + specialized_progress_snippet(block) if block else '')
                )
            return block

        def web_search_result_count() -> int:
            return sum(
                1 for item in results
                if isinstance(item, dict) and str(item.get('capability', '') or '').strip() == 'web_search'
            )

        def enrich_retry_fields(step_to_enrich: dict, review: dict) -> dict:
            enriched = dict(step_to_enrich or {})
            for key in ('retry_reason', 'delta_goal', 'source_strategy', 'success_criteria'):
                if not str(enriched.get(key, '') or '').strip() and str(review.get(key, '') or '').strip():
                    enriched[key] = str(review.get(key, '') or '').strip()
            return enriched

        def web_search_retry_is_qualified(step_to_check: dict, review: dict) -> tuple[bool, str]:
            fields = {
                key: str((step_to_check or {}).get(key, '') or review.get(key, '') or '').strip()
                for key in ('retry_reason', 'delta_goal', 'source_strategy', 'success_criteria')
            }
            missing = [key for key, value in fields.items() if not value]
            if missing:
                return False, _tr('Missing retry qualification fields: {fields}').format(fields=', '.join(missing))
            broad_goal = str((step_to_check or {}).get('goal', '') or '').lower()
            broad_phrases = (
                'latest official',
                'complete verified',
                'complete day-by-day',
                'all matches',
                'schedule/results',
                'fixtures and results',
            )
            if sum(1 for phrase in broad_phrases if phrase in broad_goal) >= 3 and not fields['delta_goal']:
                return False, _tr('Retry goal is still broad and does not specify a narrow delta.')
            return True, ''

        def make_conflict_arbitration_step(reason: str) -> dict:
            return {
                'capability': 'task_reasoning',
                'goal': (
                    'Compare the previous web_search results for the original user request. '
                    'Identify consistent facts, conflicting claims, source hierarchy, fields that remain uncertain, '
                    'and the final-answer policy. Preserve concrete dates, teams, scores, venues, statuses, and URLs. '
                    'Do not perform another web search.'
                ),
                'depends_on_previous': True,
                'extract': 'conflict arbitration and final-answer policy',
                'context_policy': 'none',
                'context_query': '',
                'dynamic': True,
                'arbitration': True,
                'retry_reason': str(reason or '').strip(),
                'delta_goal': 'Arbitrate conflicts between existing search results instead of running another broad search.',
                'source_strategy': 'Use only existing step outputs and their source URLs.',
                'success_criteria': 'Return a conflict list, source-priority decision, and answer policy for final synthesis.',
            }

        def emit_branch_update(step_id: str, branch: dict, status: str, result_excerpt: str = '', error: str = ''):
            emit_plan_update({
                'type': 'branch_update',
                'step_id': str(step_id or ''),
                'branch_id': str((branch or {}).get('branch_id', '') or ''),
                'kind': str((branch or {}).get('kind', '') or ''),
                'profile': str((branch or {}).get('profile', '') or ''),
                'status': str(status or ''),
                'result_excerpt': str(result_excerpt or ''),
                'error': str(error or ''),
            })

        def run_parallel_group(batch_indices):
            # Run a set of INDEPENDENT sibling steps concurrently under a SUPERVISOR.
            # Reuses the same per-step engine (self._execute_specialized_step) the
            # sequential path and compare-branches use; browser_use members get isolated
            # Chrome sessions automatically via _allocate_browser_use_session. Inputs are
            # FROZEN (a snapshot of prior substantive results) so no member reads a sibling.
            #
            # Phase-2 member control:
            #  - Members run on daemon threads (a Semaphore caps concurrency at 5). We do
            #    NOT use ThreadPoolExecutor: its context-manager join would block on an
            #    orphaned member we chose to skip. Daemon threads let the supervisor stop
            #    waiting on a member and move on; the orphan finishes in the background and
            #    its late result is discarded.
            #  - SKIP: read_plan_control(mid).skip_requested → set that member's cancel
            #    Event (aborts a browser_use member within ~250ms; other capabilities are a
            #    single blocking call and cannot be killed, so the group stops waiting and
            #    discards the eventual result) → finalize as 'skipped'.
            #  - RETRY: a member that FAILED stays tentative (result stored, NOT finalized)
            #    while any sibling is still executing; read_plan_control(mid).retry_requested
            #    re-launches it (cap 2). Once every sibling is terminal, tentative-failed
            #    members are accepted as failed. (No retry window after the whole group ends.)
            # Results are returned in plan order; failure isolated per member.
            snapshot = [
                r for r in results
                if str((r or {}).get('capability', '') or '') != 'user_supplement'
            ]
            members = []
            for bi in batch_indices:
                ms = steps[bi]
                if not str(ms.get('_plan_step_id', '') or '').strip():
                    ms['_plan_step_id'] = f"runtime-{int(time.time() * 1000)}-{bi + 1}"
                members.append(ms)
            group_label = str(members[0].get('parallel_group', '') or 'parallel')
            n = len(members)
            group_globals = load_settings_store().get('globals') or {}   # one disk read per group
            board_enabled = bool(group_globals.get('agent_parallel_board_enabled', False))
            board = ParallelFactBoard() if (board_enabled and n >= 2) else None
            workers_cap = normalize_agent_parallel_max_workers(
                group_globals.get('agent_parallel_max_workers', SPECIALIZED_PARALLEL_MAX_WORKERS)
            )
            progress(_tr('Running {n} steps in parallel (group "{group}")').format(n=n, group=group_label))
            emit_plan_update({
                'type': 'parallel_group_started',
                'group': group_label,
                'step_ids': [str(m.get('_plan_step_id', '') or '') for m in members],
            })

            ordered = [None] * n          # per-member result slot (plan order)
            finalized = [False] * n       # slot holds a TERMINAL result
            attempts = [0] * n            # retry count per member
            # Edge-trigger for retry_requested: the GUI thread clears the flag
            # asynchronously (on the relaunch's step_started), so a member that
            # re-fails within one poll could re-read the STALE flag and silently
            # burn the second attempt from a single click. Consume the flag once,
            # then re-arm only after observing it cleared (a genuinely new click).
            retry_armed = [True] * n
            member_cancel = [threading.Event() for _ in range(n)]
            group_lock = threading.Lock()
            group_sem = threading.Semaphore(max(1, min(workers_cap, n)))

            def member_stop_for(idx):
                ev = member_cancel[idx]

                class _MemberStop:
                    def is_set(_self):
                        return ev.is_set() or (stop_event is not None and stop_event.is_set())
                return _MemberStop()

            def emit_member(idx, kind, status):
                ms = members[idx]
                meta = (ordered[idx] or {}).get('metadata') if isinstance(ordered[idx], dict) else {}
                reason = str((meta or {}).get('parallel_error', '') or (meta or {}).get('skipped_reason', '') or '')
                payload = {
                    'type': kind, 'step_id': str(ms.get('_plan_step_id', '') or ''), 'step': dict(ms),
                    'capability': str(ms.get('capability', '') or ''),
                    'capability_label': skill_step_label(ms), 'goal': str(ms.get('goal', '') or ''),
                    'status': status, 'parallel_group': group_label,
                }
                if kind == 'step_finished':
                    payload['review_reason'] = reason
                emit_plan_update(payload)

            def worker(idx):
                ms = members[idx]
                mid = str(ms.get('_plan_step_id', '') or '')
                cap = str(ms.get('capability', '') or '')
                goal_m = str(ms.get('goal', '') or '')
                label_m = skill_step_label(ms)
                prev = snapshot[-1:] if (ms.get('depends_on_previous') and snapshot) else []
                with group_sem:
                    if member_stop_for(idx).is_set():
                        # Cancelled before it began executing (skip/stop arrived while
                        # queued). Self-finalize the slot so termination never depends on
                        # some OTHER path having finalized it — the lock + `not finalized`
                        # guard makes this a no-op if the supervisor already did.
                        with group_lock:
                            if not finalized[idx]:
                                by_user = member_cancel[idx].is_set()
                                ordered[idx] = {
                                    'capability': cap, 'capability_label': label_m, 'model_name': '',
                                    'text_output': 'Skipped by user.' if by_user else 'Stopped.',
                                    'artifacts': [],
                                    'metadata': ({'goal': goal_m, 'skipped_reason': 'user'} if by_user
                                                 else {'goal': goal_m, 'parallel_error': 'stopped'}),
                                }
                                finalized[idx] = True
                                emit_member(idx, 'step_finished', 'skipped' if by_user else 'failed')
                        return
                    goal_k = goal_m
                    rounds = 0
                    facts_posted = 0
                    last_res = None
                    while True:
                        rounds += 1
                        board_ctx = board.render_for_member(mid) if board is not None else ''
                        member_archive_context = {}
                        member_archive_reader = None
                        if archive_enabled:
                            member_archive_context = {
                                'manifest': archive_manifest(),
                                'preload': build_agent_step_archive_preload(
                                    conversation_path or '', ms.get('archive_refs') or []
                                ),
                                'read_instruction': AGENT_STEP_ARCHIVE_READ_INSTRUCTION,
                            }
                            member_archive_reader = make_agent_step_archive_reader(conversation_path or '')

                        def member_delta(text, sid=mid):
                            if run_dir:
                                _archive_safe(append_step_archive_stream, run_dir, sid, str(text or ''))
                            if callable(member_stream_callback):
                                member_stream_callback(sid, text)
                        try:
                            last_res = self._execute_specialized_step(
                                capability=cap,
                                goal=compose_step_goal_with_user_notes(goal_k, live_user_notes),
                                question_text=question_text,
                                shared_context=shared_context, step_context=board_ctx,
                                previous_results=prev, attachment_records=attachment_records,
                                downstream_extract='', skill_name=str(ms.get('skill_name', '') or '').strip(),
                                conversation_path=conversation_path, stop_event=member_stop_for(idx),
                                terminal_command_runner=terminal_command_runner,
                                external_target_runner=external_target_runner,
                                profile_override_name=str(ms.get('model_profile', '') or '').strip(),
                                external_tail_task_sections=False,
                                step_stream_callback=(
                                    member_delta
                                    if (callable(member_stream_callback) or run_dir) else None
                                ),
                                reasoning_effort=str(ms.get('reasoning_effort', '') or '').strip(),
                                archive_context=member_archive_context,
                                archive_reader=member_archive_reader,
                                parent_run_id=run_id,
                            ) or {}
                        except Exception as exc:
                            last_res = {
                                'capability': cap, 'capability_label': label_m,
                                'model_name': str(ms.get('model_profile', '') or ''),
                                'text_output': f'Parallel step failed: {exc}', 'artifacts': [],
                                'metadata': {'goal': goal_k, 'parallel_error': str(exc)},
                            }
                        if board is None:
                            break
                        if member_stop_for(idx).is_set():
                            return
                        if bool((last_res.get('metadata') or {}).get('parallel_error')):
                            break
                        try:
                            reviewed = self._review_specialized_step_result(
                                last_res,
                                capability=cap,
                                goal=compose_step_goal_with_user_notes(goal_k, live_user_notes),
                                question_text=question_text,
                                downstream_extract='',
                                review_profile_name='',
                                attachment_records=attachment_records,
                                external_target_runner=external_target_runner,
                                board_context=board.render_for_member(mid),
                                stream_callback=(
                                    member_delta
                                    if (callable(member_stream_callback) or run_dir) else None
                                ),
                                archive_manifest=member_archive_context.get('manifest', ''),
                                archive_reader=member_archive_reader,
                            )
                        except Exception:
                            break
                        if not isinstance(reviewed, dict):
                            break
                        step_review = (reviewed.get('metadata') or {}).get('step_review') or {}
                        if not isinstance(step_review, dict):
                            step_review = {}
                        # Cancel-check + board writes are ATOMIC with the supervisor's
                        # skip path: skip sets member_cancel + finalized together under
                        # group_lock, so checking under the same lock closes the window
                        # where a just-cancelled member could still post its facts.
                        # (Lock order group_lock → board's own RLock; nothing acquires
                        # them in the opposite order, so no inversion.)
                        with group_lock:
                            if finalized[idx] or member_stop_for(idx).is_set():
                                return
                            for fact in (step_review.get('board_facts') or [])[:3]:
                                if not isinstance(fact, dict):
                                    continue
                                _entry_id, reason = board.post_fact(
                                    mid, fact.get('text', ''), fact.get('refs') or [], rounds,
                                )
                                if _entry_id and reason != 'duplicate':
                                    facts_posted += 1
                            for verdict in (step_review.get('board_verdicts') or [])[:6]:
                                if not isinstance(verdict, dict):
                                    continue
                                board.post_verdict(
                                    mid,
                                    verdict.get('entry_id', ''),
                                    bool(verdict.get('agree')),
                                    verdict.get('reason', ''),
                                )
                        emit_plan_update({'type': 'board_update', 'group': group_label, **board.snapshot()})
                        if callable(member_stream_callback):
                            try:
                                round_line = _tr('round {round}/{total} · {stats}').format(
                                    round=rounds, total=SPECIALIZED_BOARD_MAX_ROUNDS, stats=board.stats_line())
                                excerpt = specialized_progress_snippet(str(last_res.get('text_output', '') or ''))
                                member_stream_callback(mid, round_line + (('\n' + excerpt) if excerpt else ''))
                            except Exception:
                                pass
                        action = str(step_review.get('next_action', 'accept') or 'accept').strip()
                        last_res = reviewed
                        # browser_use owns its own external agent loop; v1 injects the
                        # board once but never starts another browser session here.
                        if cap == BROWSER_USE_CAPABILITY or action in {'accept', 'stop'}:
                            break
                        if rounds >= SPECIALIZED_BOARD_MAX_ROUNDS:
                            break
                        if member_stop_for(idx).is_set():
                            return
                        missing = str(step_review.get('missing', '') or '').strip()
                        raw_new_step = step_review.get('new_step')
                        new_step = enrich_retry_fields(
                            raw_new_step if isinstance(raw_new_step, dict) else {}, step_review,
                        )
                        if not str(new_step.get('goal', '') or '').strip():
                            new_step['goal'] = (
                                'Retry the previous step with a corrected approach. '
                                + (missing or goal_k)
                            ).strip()
                        if action == 'retry_step' and cap == 'web_search':
                            qualified, rejection_reason = web_search_retry_is_qualified(new_step, step_review)
                            if not qualified:
                                progress(
                                    _tr('Rejected unqualified parallel-board web_search retry.\nReason: {reason}').format(
                                        reason=rejection_reason)
                                )
                                break
                        goal_k = strip_step_goal_user_notes(new_step.get('goal', ''))
                    res = last_res or {}
                    if board is not None:
                        result_metadata = dict(res.get('metadata') or {})
                        result_metadata.update({
                            'board_rounds': rounds,
                            'board_facts_posted': facts_posted,
                        })
                        res['metadata'] = result_metadata
                with group_lock:
                    if finalized[idx]:
                        return  # supervisor already skipped/stopped this member; drop late result
                    failed = bool((res.get('metadata') or {}).get('parallel_error'))
                    ordered[idx] = res
                    if failed:
                        # tentative: leave non-finalized so a retry can replace it while
                        # siblings are still running. Emit 'failed' now for the panel.
                        emit_member(idx, 'step_finished', 'failed')
                    else:
                        finalized[idx] = True
                        emit_member(idx, 'step_finished', 'finished')

            def launch(idx):
                member_cancel[idx].clear()
                emit_member(idx, 'step_started', 'running')
                if stop_event is not None and stop_event.is_set():
                    with group_lock:
                        if not finalized[idx]:
                            ordered[idx] = {
                                'capability': str(members[idx].get('capability', '') or ''),
                                'capability_label': skill_step_label(members[idx]), 'model_name': '',
                                'text_output': 'Stopped before execution.', 'artifacts': [],
                                'metadata': {'goal': str(members[idx].get('goal', '') or ''), 'parallel_error': 'stopped'},
                            }
                            finalized[idx] = True
                            emit_member(idx, 'step_finished', 'failed')
                    return
                threading.Thread(target=worker, args=(idx,), name='agent-plan-steps-%d' % idx, daemon=True).start()

            for idx in range(n):
                launch(idx)

            # ---- supervisor: poll member control + drive skip/retry until all terminal ----
            ingested_count = 0
            while not all(finalized):
                time.sleep(0.12)
                if board is not None:
                    notes = read_plan_control('__board__:' + group_label).get('notes') or []
                    notes = notes if isinstance(notes, list) else []
                    before_count = len(board.snapshot()['entries'])
                    for note in notes[ingested_count:]:
                        board.add_user_note(note)
                    ingested_count = max(ingested_count, len(notes))
                    if len(board.snapshot()['entries']) > before_count:
                        emit_plan_update({'type': 'board_update', 'group': group_label, **board.snapshot()})
                if stop_event is not None and stop_event.is_set():
                    with group_lock:
                        for idx in range(n):
                            if not finalized[idx]:
                                member_cancel[idx].set()
                                ordered[idx] = ordered[idx] or {
                                    'capability': str(members[idx].get('capability', '') or ''),
                                    'capability_label': skill_step_label(members[idx]), 'model_name': '',
                                    'text_output': 'Stopped.', 'artifacts': [],
                                    'metadata': {'goal': str(members[idx].get('goal', '') or ''), 'parallel_error': 'stopped'},
                                }
                                finalized[idx] = True
                                emit_member(idx, 'step_finished', 'failed')
                    break
                for idx in range(n):
                    if finalized[idx]:
                        continue
                    mid = str(members[idx].get('_plan_step_id', '') or '')
                    ctrl = read_plan_control(mid)
                    if bool(ctrl.get('skip_requested', False)):
                        with group_lock:
                            if not finalized[idx]:
                                member_cancel[idx].set()
                                ordered[idx] = {
                                    'capability': str(members[idx].get('capability', '') or ''),
                                    'capability_label': skill_step_label(members[idx]), 'model_name': '',
                                    'text_output': 'Skipped by user.', 'artifacts': [],
                                    'metadata': {'goal': str(members[idx].get('goal', '') or ''), 'skipped_reason': 'user'},
                                }
                                finalized[idx] = True
                                emit_member(idx, 'step_finished', 'skipped')
                        continue
                    tentative_failed = (
                        ordered[idx] is not None
                        and bool((ordered[idx].get('metadata') or {}).get('parallel_error'))
                    )
                    retry_flag = bool(ctrl.get('retry_requested', False))
                    if not retry_flag:
                        retry_armed[idx] = True  # GUI cleared it → next True is a fresh click
                    if tentative_failed and retry_flag and retry_armed[idx] and attempts[idx] < 2:
                        retry_armed[idx] = False
                        with group_lock:
                            attempts[idx] += 1
                            ordered[idx] = None
                        launch(idx)  # re-run; a fresh step_started clears retry_requested (controller)
                # Nothing left executing (every non-finalized slot already holds a failed
                # result) → accept the tentative-failed members and finish.
                still_running = any((not finalized[idx]) and (ordered[idx] is None) for idx in range(n))
                if not still_running:
                    with group_lock:
                        for idx in range(n):
                            if not finalized[idx] and ordered[idx] is not None:
                                finalized[idx] = True
            if board is not None and board.snapshot()['entries']:
                digest = board.render_digest()
                if digest:
                    ordered.append({
                        'capability': 'parallel_board',
                        'capability_label': 'Parallel fact board',
                        'model_name': '',
                        'text_output': digest,
                        'context_output': digest,
                        'artifacts': [],
                        'metadata': {
                            'goal': f'Shared fact board for group "{group_label}"',
                            'execution_mode': 'parallel_board',
                        },
                    })
            emit_plan_update({'type': 'parallel_group_finished', 'group': group_label})
            return [r for r in ordered if r is not None]

        last_unit_result_count = 1  # how many substantive results the PREVIOUS unit produced
        while i < len(steps) and executed_steps < max_executed_steps:
            if stop_event is not None and stop_event.is_set():
                progress(_tr('Specialized pipeline stopped.'))
                break
            consume_supplements(f'before_step_{executed_steps + 1}')
            apply_pending_plan_order(i)
            step = steps[i]
            capability = str(step.get('capability', '')).strip()
            if not capability:
                i += 1
                continue
            if not str(step.get('_plan_step_id', '') or '').strip():
                step['_plan_step_id'] = f"runtime-{int(time.time() * 1000)}-{i + 1}"
            plan_step_id = str(step.get('_plan_step_id', '') or '').strip()
            step_label = skill_step_label(step)
            # ---- PARALLEL GROUP: additive branch. The sequential single-step path
            # below is untouched and remains the default for non-grouped steps. ----
            batch = specialized_step_batch(steps, i)
            if len(batch) >= 2:
                # Honor per-member DELETE from the Plan panel before launching. The
                # sequential path checks control.deleted pre-execution; without this
                # filter a deleted member of a tail-anchored group (nothing after it
                # to break the batch) would still run and feed the finalize.
                runnable_batch = []
                for bi in batch:
                    member_step = steps[bi]
                    if not str(member_step.get('_plan_step_id', '') or '').strip():
                        member_step['_plan_step_id'] = f"runtime-{int(time.time() * 1000)}-{bi + 1}"
                    member_id = str(member_step.get('_plan_step_id', '') or '')
                    if bool(read_plan_control(member_id).get('deleted', False)):
                        member_label = skill_step_label(member_step)
                        emit_plan_update({
                            'type': 'step_finished',
                            'step_id': member_id,
                            'step': dict(member_step),
                            'capability': str(member_step.get('capability', '') or ''),
                            'capability_label': member_label,
                            'goal': str(member_step.get('goal', '') or ''),
                            'status': 'skipped',
                            'review_reason': 'Skipped from Plan panel before execution.',
                            'parallel_group': str(member_step.get('parallel_group', '') or ''),
                        })
                        progress(_tr('Skipping specialized step from Plan panel: {label}').format(label=member_label))
                        archive_result(
                            f'{executed_steps + 1:02d}',
                            {
                                'capability': str(member_step.get('capability', '') or ''),
                                'capability_label': member_label,
                                'model_name': '', 'text_output': 'Skipped from Plan panel before execution.',
                                'artifacts': [],
                                'metadata': {'goal': str(member_step.get('goal', '') or ''), 'skipped_reason': 'deleted'},
                            },
                            str(member_step.get('goal', '') or ''), 'skipped',
                        )
                        executed_steps += 1
                        continue
                    runnable_batch.append(bi)
                # A group shrunk to 1 survivor still runs through run_parallel_group
                # (n=1 is fine) so member skip/retry supervision keeps working.
                if runnable_batch:
                    group_results = run_parallel_group(runnable_batch)
                    results.extend(group_results)
                    for group_offset, group_result in enumerate(group_results):
                        source_step = steps[runnable_batch[group_offset]] if group_offset < len(runnable_batch) else {}
                        suffix = chr(ord('a') + min(group_offset, 25))
                        archive_result(
                            f'{executed_steps + 1:02d}{suffix}',
                            group_result,
                            str(source_step.get('goal', '') or ''),
                        )
                    executed_steps += len(runnable_batch)
                    last_unit_result_count = max(1, len([
                        r for r in group_results
                        if str((r or {}).get('capability', '') or '') != 'user_supplement'
                    ]))
                i = batch[-1] + 1
                continue
            control = read_plan_control(plan_step_id)
            if bool(control.get('deleted', False)):
                emit_plan_update({
                    'type': 'step_finished',
                    'step_id': plan_step_id,
                    'step': dict(step),
                    'capability': capability,
                    'capability_label': step_label,
                    'goal': str(step.get('goal', '') or ''),
                    'status': 'skipped',
                    'review_reason': 'Skipped from Plan panel before execution.',
                })
                progress(_tr('Skipping specialized step from Plan panel: {label}').format(label=step_label))
                archive_result(
                    f'{executed_steps + 1:02d}',
                    {'capability': capability, 'capability_label': step_label, 'model_name': '',
                     'text_output': 'Skipped from Plan panel before execution.', 'artifacts': [],
                     'metadata': {'goal': str(step.get('goal', '') or ''), 'skipped_reason': 'deleted'}},
                    str(step.get('goal', '') or ''), 'skipped',
                )
                executed_steps += 1
                i += 1
                continue
            if bool(control.get('skip_requested', False)):
                emit_plan_update({
                    'type': 'step_finished',
                    'step_id': plan_step_id,
                    'step': dict(step),
                    'capability': capability,
                    'capability_label': step_label,
                    'goal': str(step.get('goal', '') or ''),
                    'status': 'skipped',
                    'review_reason': 'Skipped from Plan panel.',
                })
                progress(_tr('Skipping specialized step from Plan panel: {label}').format(label=step_label))
                archive_result(
                    f'{executed_steps + 1:02d}',
                    {'capability': capability, 'capability_label': step_label, 'model_name': '',
                     'text_output': 'Skipped from Plan panel.', 'artifacts': [],
                     'metadata': {'goal': str(step.get('goal', '') or ''), 'skipped_reason': 'user'}},
                    str(step.get('goal', '') or ''), 'skipped',
                )
                executed_steps += 1
                i += 1
                continue
            if not bool(step.get('_plan_pause_done', False)):
                pause_for_pending_step_review(
                    step,
                    agent_plan_step_review_seconds(),
                    _tr('Review or adjust this pending step.'),
                )
                step['_plan_pause_done'] = True
                apply_pending_plan_order(i)
                reordered_step = steps[i] if i < len(steps) else None
                reordered_id = str((reordered_step or {}).get('_plan_step_id', '') or '').strip()
                if reordered_id and reordered_id != plan_step_id:
                    continue
                control = read_plan_control(plan_step_id)
                if bool(control.get('deleted', False)):
                    emit_plan_update({
                        'type': 'step_finished',
                        'step_id': plan_step_id,
                        'step': dict(step),
                        'capability': capability,
                        'capability_label': step_label,
                        'goal': str(step.get('goal', '') or ''),
                        'status': 'skipped',
                        'review_reason': 'Skipped from Plan panel before execution.',
                    })
                    progress(_tr('Skipping specialized step from Plan panel: {label}').format(label=step_label))
                    executed_steps += 1
                    i += 1
                    continue
                if bool(control.get('skip_requested', False)):
                    emit_plan_update({
                        'type': 'step_finished',
                        'step_id': plan_step_id,
                        'step': dict(step),
                        'capability': capability,
                        'capability_label': step_label,
                        'goal': str(step.get('goal', '') or ''),
                        'status': 'skipped',
                        'review_reason': 'Skipped from Plan panel.',
                    })
                    progress(_tr('Skipping specialized step from Plan panel: {label}').format(label=step_label))
                    executed_steps += 1
                    i += 1
                    continue
            if str(control.get('goal', '') or '').strip():
                step['goal'] = str(control.get('goal', '') or '').strip()
            goal = str(step.get('goal', '')).strip()
            if not goal:
                i += 1
                continue
            # Second intake right before execution: notes typed during the pre-step
            # countdown (above) used to wait until this step had already finished.
            consume_supplements(f'before_step_{executed_steps + 1}')
            prompt_goal = compose_step_goal_with_user_notes(goal, live_user_notes)
            # 模型优先级链：用户在计划面板手动指定 > planner 选型 > 第一顺位。
            user_model_override = str(control.get('model_profile', '') or '').strip()
            planner_model_choice = str(step.get('model_profile', '') or '').strip()
            profile_override_name = user_model_override or planner_model_choice
            branch_controls = [
                branch for branch in (control.get('branches') or [])
                if isinstance(branch, dict)
            ]
            comparison_branches = [
                branch for branch in branch_controls
                if str(branch.get('kind', '') or '') == 'compare' and str(branch.get('profile', '') or '').strip()
            ]
            verification_branches = [
                branch for branch in branch_controls
                if str(branch.get('kind', '') or '') == 'verify' and str(branch.get('profile', '') or '').strip()
            ]
            comparison_profiles = [
                str(branch.get('profile', '') or '').strip()
                for branch in comparison_branches
            ]
            verification_profiles = [
                str(branch.get('profile', '') or '').strip()
                for branch in verification_branches
            ]
            verification_profile = verification_profiles[0] if verification_profiles else ''
            emit_plan_update({
                'type': 'step_started',
                'step_id': plan_step_id,
                'index': executed_steps + 1,
                'step': dict(step),
                'capability': capability,
                'capability_label': step_label,
                'goal': goal,
                'status': 'running',
            })
            step_reasoning_effort = str(step.get('reasoning_effort', '') or '').strip()
            model_choice_line = ''
            if user_model_override:
                model_choice_line = '\n' + _tr('Model: {model} (user override)').format(model=user_model_override)
            elif planner_model_choice:
                model_choice_line = '\n' + _tr('Model: {model} (planner picked)').format(model=planner_model_choice)
            progress(
                (_tr('Specialized step {n}: {label} (dynamic)\nGoal: {goal}') if step.get('dynamic')
                 else _tr('Specialized step {n}: {label}\nGoal: {goal}')).format(
                    n=executed_steps + 1, label=step_label, goal=goal)
                + ('\n' + _tr('Reasoning effort: {effort}').format(effort=step_reasoning_effort) if step_reasoning_effort else '')
                + model_choice_line
            )
            substantive_results = [
                item for item in results
                if str(item.get('capability', '') or '') != 'user_supplement'
            ]
            if step.get('arbitration') and substantive_results:
                previous = substantive_results[-8:]
            elif step.get('depends_on_previous', False) and substantive_results and last_unit_result_count > 1:
                # The previous unit was a PARALLEL GROUP — a dependent (synthesis)
                # step reads ALL of the group's results, not just the last one.
                previous = substantive_results[-last_unit_result_count:]
            elif step.get('depends_on_previous', False) and substantive_results:
                extract_hint = str(step.get('extract', '')).strip()
                if extract_hint:
                    last = substantive_results[-1]
                    context_text = specialized_step_context_output(last)
                    focused = {
                        'capability': last.get('capability', ''),
                        'model_name': last.get('model_name', ''),
                        'context_output': context_text,
                        'text_output': context_text,
                        'metadata': {'extract': extract_hint},
                    }
                    previous = [focused]
                else:
                    previous = substantive_results[-1:]
            else:
                previous = []
            next_step = steps[i + 1] if i + 1 < len(steps) else None
            downstream_extract = str((next_step or {}).get('extract', '')).strip() if next_step and next_step.get('depends_on_previous') else ''
            context_policy = normalize_specialized_step_context_policy(step.get('context_policy', 'auto'))
            step_context_query = ''
            step_context = ''
            step_context_resolution = {
                'should_retrieve': False,
                'effective_policy': 'none',
                'sources': [],
                'reason': 'No step-specific retrieval requested.',
                'coverage': 1.0,
                'missing_terms': [],
            }
            if context_policy != 'none':
                step_context_query = self._build_specialized_step_retrieval_query(
                    question_text=question_text,
                    goal=goal,
                    previous_results=previous,
                    downstream_extract=downstream_extract,
                    explicit_query=str(step.get('context_query', '') or '').strip(),
                )
                step_context_resolution = self._resolve_specialized_step_retrieval_request(
                    policy=context_policy,
                    capability=capability,
                    query_text=step_context_query,
                    explicit_query=str(step.get('context_query', '') or '').strip(),
                    shared_context=shared_context,
                    previous_results=previous,
                    retrieval_documents=retrieval_documents,
                    history_messages=history_messages,
                )
                if step_context_query and step_context_resolution.get('should_retrieve'):
                    source_label = ', '.join(step_context_resolution.get('sources') or SPECIALIZED_STEP_CONTEXT_SOURCES)
                    progress(
                        (_tr('Retrieving step-specific context for {label}\nSources: {sources}\nReason: {reason}\nQuery: {query}')
                         if source_label
                         else _tr('Retrieving step-specific context for {label}\nReason: {reason}\nQuery: {query}')).format(
                            label=step_label,
                            sources=source_label,
                            reason=step_context_resolution.get('reason', ''),
                            query=specialized_progress_snippet(step_context_query),
                        )
                    )
                    try:
                        step_context = self._build_specialized_step_retrieval_context(
                            query_text=step_context_query,
                            history_messages=history_messages,
                            selected_message_indices=selected_message_indices,
                            retrieval_documents=retrieval_documents,
                            api_key=api_key,
                            endpoint=endpoint,
                            model=model,
                            timeout=timeout,
                            context_sources=step_context_resolution.get('sources') or SPECIALIZED_STEP_CONTEXT_SOURCES,
                            conversation_path=conversation_path,
                            progress_callback=progress_callback,
                        )
                    except Exception as exc:
                        progress(_tr('Step-specific context retrieval failed: {error}').format(error=exc))
                        step_context = ''
                elif context_policy == 'auto':
                    progress(
                        _tr('Skipping step-specific context for {label}\nReason: {reason}').format(
                            label=step_label, reason=step_context_resolution.get('reason', ''))
                    )
            archive_context = {}
            archive_reader = None
            if archive_enabled:
                archive_context = {
                    'manifest': archive_manifest(),
                    'preload': build_agent_step_archive_preload(
                        conversation_path or '', step.get('archive_refs') or []
                    ),
                    'read_instruction': AGENT_STEP_ARCHIVE_READ_INSTRUCTION,
                }
                archive_reader = make_agent_step_archive_reader(conversation_path or '')
            active_stream_slug['value'] = plan_step_id or f'step-{executed_steps + 1:02d}-{capability}'
            def execute_step_with_profile(profile_name: str, *, external_tail_task_sections: bool = False,
                                          allow_stream: bool = False) -> dict:
                # 只有主执行（base）开流式；并行的 compare/verify 分支不流，
                # 避免多个流交错打进同一个预览区。
                return self._execute_specialized_step(
                    capability=capability,
                    goal=prompt_goal,
                    question_text=question_text,
                    shared_context=shared_context,
                    step_context=step_context,
                    previous_results=previous,
                    attachment_records=attachment_records,
                    downstream_extract=downstream_extract,
                    skill_name=str(step.get('skill_name', '') or '').strip(),
                    conversation_path=conversation_path,
                    stop_event=stop_event,
                    terminal_command_runner=terminal_command_runner,
                    external_target_runner=external_target_runner,
                    profile_override_name=profile_name,
                    external_tail_task_sections=external_tail_task_sections,
                    step_stream_callback=stream_delta if allow_stream else None,
                    reasoning_effort=str(step.get('reasoning_effort', '') or '').strip(),
                    archive_context=archive_context,
                    archive_reader=archive_reader,
                    parent_run_id=run_id,
                )

            comparison_results = []
            # Compare-on-browser is enabled: each browser branch resolves its own
            # model profile (profile_override_name threaded into _execute_browser_use_step)
            # and gets an isolated Chrome session via _allocate_browser_use_session, so
            # concurrent browser branches don't contend. Only terminal stays excluded
            # (single approval-gated surface). NOTE: isolated sessions are fresh,
            # NOT-logged-in profiles — browser compare only suits non-login tasks.
            can_parallel_compare = bool(comparison_branches) and capability != TERMINAL_COMMAND_CAPABILITY
            if can_parallel_compare:
                futures = {}
                with ThreadPoolExecutor(
                    max_workers=max(1, min(4, len(comparison_branches) + 1)),
                    thread_name_prefix='agent-plan-compare',
                ) as executor:
                    base_future = executor.submit(execute_step_with_profile, profile_override_name, allow_stream=True)
                    futures[base_future] = {'kind': 'base'}
                    for branch in comparison_branches:
                        emit_branch_update(plan_step_id, branch, 'running')
                        compare_profile = str(branch.get('profile', '') or '').strip()
                        futures[executor.submit(
                            execute_step_with_profile,
                            compare_profile,
                            external_tail_task_sections=True,
                        )] = {
                            'kind': 'compare',
                            'branch': branch,
                            'profile': compare_profile,
                        }
                    result = {}
                    for future in as_completed(futures):
                        spec = futures[future]
                        try:
                            branch_result = future.result()
                        except Exception as exc:
                            branch_result = {
                                'capability': capability,
                                'capability_label': step_label,
                                'model_name': str(spec.get('profile', '') or ''),
                                'text_output': f'Branch failed: {exc}',
                                'artifacts': [],
                                'metadata': {'goal': goal, 'branch_error': str(exc)},
                            }
                        if spec.get('kind') == 'base':
                            result = branch_result
                        else:
                            branch = spec.get('branch') or {}
                            if branch_result:
                                branch_result['comparison_profile'] = str(spec.get('profile', '') or '')
                                comparison_results.append(branch_result)
                                emit_branch_update(
                                    plan_step_id,
                                    branch,
                                    'finished',
                                    specialized_progress_snippet(str(branch_result.get('text_output', '') or '')),
                                )
                            else:
                                emit_branch_update(plan_step_id, branch, 'failed', error='No branch result.')
            else:
                if comparison_branches:
                    for branch in comparison_branches:
                        emit_branch_update(
                            plan_step_id,
                            branch,
                            'skipped',
                            'Compare branches are disabled for terminal command steps.',
                        )
                result = execute_step_with_profile(profile_override_name, allow_stream=True)
            control_after_execution = read_plan_control(plan_step_id)
            if bool(control_after_execution.get('skip_requested', False)):
                emit_plan_update({
                    'type': 'step_finished',
                    'step_id': plan_step_id,
                    'step': dict(step),
                    'capability': capability,
                    'capability_label': step_label,
                    'goal': goal,
                    'status': 'skipped',
                    'review_reason': 'Skipped from Plan panel.',
                })
                progress(_tr('Skipped specialized step from Plan panel after execution returned: {label}').format(label=step_label))
                skipped_result = dict(result or {})
                skipped_metadata = dict(skipped_result.get('metadata') or {})
                skipped_metadata['skipped_reason'] = 'user'
                skipped_result['metadata'] = skipped_metadata
                archive_result(f'{executed_steps + 1:02d}', skipped_result, goal, 'skipped')
                executed_steps += 1
                i += 1
                continue
            if result:
                if comparison_results:
                    comparison_blocks = []
                    for comparison_result in comparison_results:
                        comparison_profile = str(comparison_result.get('comparison_profile', '') or '')
                        comparison_text = str(comparison_result.get('text_output', '') or '').strip()
                        comparison_blocks.append(
                            f'Comparison profile: {comparison_profile}\n{comparison_text}'
                        )
                    result['text_output'] = '\n\n'.join(
                        part for part in [
                            str(result.get('text_output', '') or '').strip(),
                            'Plan comparison results:\n\n' + '\n\n'.join(comparison_blocks),
                        ]
                        if part
                    )
                metadata = dict(result.get('metadata') or {})
                metadata.update({
                    'context_policy': context_policy,
                    'context_effective_policy': step_context_resolution.get('effective_policy', 'none'),
                    'context_sources': list(step_context_resolution.get('sources') or []),
                    'context_auto_reason': str(step_context_resolution.get('reason', '') or ''),
                    'context_coverage': step_context_resolution.get('coverage', 1.0),
                    'context_missing_terms': list(step_context_resolution.get('missing_terms') or [])[:12],
                    'context_query': step_context_query,
                    'step_context_chars': len(step_context),
                    'plan_model_profile_override': profile_override_name,
                    'plan_comparison_profiles': comparison_profiles,
                    'plan_verification_profile': verification_profile,
                    'plan_verification_profiles': verification_profiles,
                    'plan_branches': branch_controls,
                })
                if comparison_results:
                    metadata['plan_comparison_results'] = comparison_results
                result['metadata'] = metadata
                fallback_from = str(metadata.get('fallback_from', '') or '')
                progress(
                    _tr('Specialized step {n} output ready: {label}').format(n=executed_steps + 1, label=step_label)
                    + ('\n' + _tr('Fallback: {failed} unavailable, used {used}').format(
                        failed=fallback_from, used=str(result.get('model_name', '') or _tr('next candidate')))
                       if fallback_from else '')
                    + ('\n' + specialized_progress_snippet(str(result.get('text_output', '') or '')) if result.get('text_output') else '')
                )
                emit_plan_update({
                    'type': 'step_output',
                    'step_id': plan_step_id,
                    'step': dict(step),
                    'capability': capability,
                    'capability_label': step_label,
                    'goal': goal,
                    'status': 'running',
                    'output_excerpt': specialized_progress_snippet(str(result.get('text_output', '') or '')),
                    'model_name': str(result.get('model_name', '') or ''),
                    'profile_name': str(result.get('profile_name', '') or ''),
                })
                verification_review_results = []
                if verification_branches:
                    verify_profiles_label = ', '.join(
                        str(branch.get('profile', '') or '') for branch in verification_branches
                    )
                    progress(
                        _tr('Reviewing step output: {label}').format(label=step_label)
                        + ('\n' + _tr('Verification profiles: {profiles}').format(profiles=verify_profiles_label)
                           if verify_profiles_label else '')
                    )

                    def run_verification_branch(branch: dict) -> dict:
                        profile_name = str(branch.get('profile', '') or '').strip()
                        reviewed_branch = self._review_specialized_step_result(
                            result,
                            capability=capability,
                            goal=prompt_goal,
                            question_text=question_text,
                            downstream_extract=downstream_extract,
                            final_focus=final_focus,
                            review_profile_name=profile_name,
                            attachment_records=attachment_records,
                            external_target_runner=external_target_runner,
                            archive_manifest=archive_context.get('manifest', ''),
                            archive_reader=archive_reader,
                        )
                        reviewed_branch['verification_profile'] = profile_name
                        return reviewed_branch

                    with ThreadPoolExecutor(
                        max_workers=max(1, min(4, len(verification_branches))),
                        thread_name_prefix='agent-plan-verify',
                    ) as executor:
                        futures = {}
                        for branch in verification_branches:
                            emit_branch_update(plan_step_id, branch, 'running')
                            futures[executor.submit(run_verification_branch, branch)] = branch
                        for future in as_completed(futures):
                            branch = futures[future]
                            try:
                                reviewed_branch = future.result()
                                verification_review_results.append(reviewed_branch)
                                branch_review = (reviewed_branch.get('metadata') or {}).get('step_review', {})
                                emit_branch_update(
                                    plan_step_id,
                                    branch,
                                    'finished',
                                    specialized_progress_snippet(
                                        str(branch_review.get('reason', '') or reviewed_branch.get('context_output', '') or '')
                                    ),
                                )
                            except Exception as exc:
                                emit_branch_update(plan_step_id, branch, 'failed', error=str(exc))

                if verification_review_results:
                    reviewed_result = next(
                        (
                            item for item in verification_review_results
                            if str(((item.get('metadata') or {}).get('step_review', {}) or {}).get('next_action', 'accept') or 'accept') != 'accept'
                            or not bool(((item.get('metadata') or {}).get('step_review', {}) or {}).get('meets_goal', True))
                        ),
                        verification_review_results[0],
                    )
                    verification_metadata = dict(reviewed_result.get('metadata') or {})
                    verification_metadata['plan_verification_results'] = verification_review_results
                    reviewed_result['metadata'] = verification_metadata
                    # 与 compare 的显示方式一致：把每个 verify 分支的复核意见拼进
                    # text_output，让它出现在答案的 Specialized steps 折叠块里
                    # （此前只写 metadata，界面上完全不可见）。
                    verification_blocks = []
                    for item in verification_review_results:
                        verify_profile = str(item.get('verification_profile', '') or '')
                        review_info = (item.get('metadata') or {}).get('step_review', {}) or {}
                        block_lines = [f'Verification profile: {verify_profile}']
                        block_lines.append(f'Meets goal: {"yes" if review_info.get("meets_goal", False) else "no"}')
                        review_reason = str(review_info.get('reason', '') or '').strip()
                        if review_reason:
                            block_lines.append(f'Reason: {review_reason}')
                        review_missing = str(review_info.get('missing', '') or '').strip()
                        if review_missing:
                            block_lines.append(f'Missing: {review_missing}')
                        verification_blocks.append('\n'.join(block_lines))
                    if verification_blocks:
                        reviewed_result['text_output'] = '\n\n'.join(
                            part for part in [
                                str(reviewed_result.get('text_output', '') or '').strip(),
                                'Plan verification results:\n\n' + '\n\n'.join(verification_blocks),
                            ]
                            if part
                        )
                else:
                    # 复核可能跑在推理模型上（几十秒），必须有状态行——否则
                    # 用户只看到步骤流式字符停止增长、心跳空跳，像卡死。
                    review_profile_label = str(verification_profile or '').strip()
                    if not review_profile_label:
                        try:
                            review_profile_label = str(
                                get_specialized_profiles_from_store(load_settings_store()).get('router', '') or ''
                            ).strip()
                        except Exception:
                            review_profile_label = ''
                    progress(
                        _tr('Reviewing step output: {label}').format(label=step_label)
                        + ('\n' + _tr('Review profile: {profile}').format(profile=review_profile_label)
                           if review_profile_label else '')
                    )
                    reviewed_result = self._review_specialized_step_result(
                        result,
                        capability=capability,
                        goal=prompt_goal,
                        question_text=question_text,
                        downstream_extract=downstream_extract,
                        final_focus=final_focus,
                        review_profile_name=verification_profile,
                        attachment_records=attachment_records,
                        external_target_runner=external_target_runner,
                        stream_callback=stream_delta,
                        archive_manifest=archive_context.get('manifest', ''),
                        archive_reader=archive_reader,
                    )
                results.append(reviewed_result)
                archive_result(f'{executed_steps + 1:02d}', reviewed_result, goal)
                last_unit_result_count = 1  # this unit was a single step
                review = (reviewed_result.get('metadata') or {}).get('step_review', {})
                review_action = str(review.get('next_action', 'accept') or 'accept').strip()
                review_reason = str(review.get('reason', '') or '').strip()
                # 复核结论顺手落进模型质量档案（零额外请求；@/& 步骤在
                # record 内部被过滤）。记的是本步实际执行的 profile。
                if review.get('reviewed'):
                    executed_profile_name = (
                        profile_override_name
                        or str(get_specialized_profiles_from_store(load_settings_store()).get(capability, '') or '').strip()
                    )
                    try:
                        record_model_quality(
                            executed_profile_name,
                            capability,
                            bool(review.get('meets_goal', False)),
                            str(review.get('missing', '') or review_reason or ''),
                        )
                    except Exception:
                        pass
                context_output = specialized_step_context_output(reviewed_result)
                progress(
                    _tr('Specialized step {n} reviewed: {label}\nMeets goal: {meets}\nNext action: {action}').format(
                        n=executed_steps + 1,
                        label=step_label,
                        meets=_tr('yes') if review.get('meets_goal', False) else _tr('no'),
                        action=review_action,
                    )
                    + ('\n' + _tr('Reason: {reason}').format(reason=review_reason) if review_reason else '')
                    + ('\n' + _tr('Context for next step: {context}').format(
                        context=specialized_progress_snippet(context_output)) if context_output else '')
                )
                emit_plan_update({
                    'type': 'step_finished',
                    'step_id': plan_step_id,
                    'step': dict(step),
                    'capability': capability,
                    'capability_label': step_label,
                    'goal': goal,
                    'status': 'finished',
                    'model_name': str(result.get('model_name', '') or ''),
                    'profile_name': str(result.get('profile_name', '') or ''),
                    'meets_goal': bool(review.get('meets_goal', False)),
                    'review_action': review_action,
                    'review_reason': review_reason,
                    'retry_reason': str(review.get('retry_reason', '') or '').strip(),
                    'delta_goal': str(review.get('delta_goal', '') or '').strip(),
                    'source_strategy': str(review.get('source_strategy', '') or '').strip(),
                    'success_criteria': str(review.get('success_criteria', '') or '').strip(),
                    'raw_chars': len(str(result.get('text_output', '') or '')),
                    'reviewed_chars': len(str(context_output or '')),
                    'output_excerpt': specialized_progress_snippet(context_output),
                })
                if review_action == 'stop':
                    progress(_tr('Specialized pipeline stopped by planner review.'))
                    break
                if review_action in {'insert_step', 'retry_step'} and dynamic_additions < SPECIALIZED_DYNAMIC_STEP_MAX_ADDITIONS:
                    new_step = review.get('new_step')
                    if not new_step and review_action == 'retry_step':
                        missing = str(review.get('missing', '') or '').strip()
                        new_step = normalize_dynamic_specialized_step(
                            {
                                'capability': capability,
                                'skill_name': str(step.get('skill_name', '') or '').strip(),
                                'goal': ('Retry the previous step with a corrected approach. ' + (missing or goal)).strip(),
                                'depends_on_previous': bool(results),
                                'extract': downstream_extract,
                                'context_policy': context_policy,
                                'context_query': step_context_query,
                                'retry_reason': str(review.get('retry_reason', '') or missing or '').strip(),
                                'delta_goal': str(review.get('delta_goal', '') or '').strip(),
                                'source_strategy': str(review.get('source_strategy', '') or '').strip(),
                                'success_criteria': str(review.get('success_criteria', '') or '').strip(),
                                'archive_refs': normalize_agent_step_archive_refs(review.get('archive_refs')),
                            }
                        )
                    if new_step:
                        new_step = enrich_retry_fields(new_step, review)
                        if str(new_step.get('capability', '') or '').strip() == 'web_search':
                            previous_web_searches = web_search_result_count()
                            if previous_web_searches >= 2:
                                progress(
                                    _tr('Converted repeated web_search request into conflict arbitration.\nReason: {reason}').format(
                                        reason=review_reason or str(new_step.get('retry_reason', '') or _tr('Multiple web searches already ran.')))
                                )
                                new_step = make_conflict_arbitration_step(
                                    review_reason or str(new_step.get('retry_reason', '') or 'Multiple web searches already ran.')
                                )
                            elif previous_web_searches >= 1:
                                qualified, rejection_reason = web_search_retry_is_qualified(new_step, review)
                                if not qualified:
                                    progress(
                                        _tr('Rejected unqualified dynamic web_search retry.\nReason: {reason}\n'
                                            'Final answer will arbitrate with the evidence already collected.').format(
                                            reason=rejection_reason)
                                    )
                                    new_step = None
                        if new_step:
                            # The reviewer saw prompt_goal; keep echoed user notes out of the
                            # plan goal (the new step gets the current notes when it runs).
                            new_step['goal'] = strip_step_goal_user_notes(new_step.get('goal', ''))
                            if not str(new_step.get('_plan_step_id', '') or '').strip():
                                new_step['_plan_step_id'] = f"dynamic-{int(time.time() * 1000)}-{dynamic_additions + 1}"
                            steps.insert(i + 1, new_step)
                            dynamic_additions += 1
                            emit_plan_update({
                                'type': 'step_inserted',
                                'after_step_id': plan_step_id,
                                'step_id': str(new_step.get('_plan_step_id', '') or ''),
                                'step': dict(new_step),
                                'capability': str(new_step.get('capability', '') or ''),
                                'capability_label': skill_step_label(new_step),
                                'goal': str(new_step.get('goal', '') or ''),
                                'status': 'pending',
                            })
                            progress(
                                _tr('Planner inserted dynamic step: {label}\nGoal: {goal}').format(
                                    label=skill_step_label(new_step), goal=new_step['goal'])
                            )
                elif review_action in {'insert_step', 'retry_step'}:
                    progress(_tr('Dynamic step limit reached; continuing without inserting more steps.'))
                consume_supplements(f'after_step_{executed_steps + 1}')
            executed_steps += 1
            i += 1
        consume_supplements('after_specialized_pipeline')
        return results

    def _build_output_records_for_turn(self,
                                       *,
                                       question_text: str,
                                       question_index: int,
                                       assistant_index: int,
                                       model_name: str,
                                       structured_outputs: list[dict],
                                       step_results: list[dict]) -> list[dict]:
        created_at = datetime.datetime.now().isoformat(timespec='seconds')
        records = []
        for index, item in enumerate(structured_outputs or []):
            if isinstance(item, dict) and str(item.get('type', '') or '') == 'editor_edit':
                continue
            kind = str(item.get('kind', 'text')).strip().lower()
            if kind not in {'code', 'text'}:
                kind = 'text'
            content = str(item.get('content', '') or '').strip()
            if not content:
                continue
            title = str(item.get('title', '') or '').strip() or ('Generated code' if kind == 'code' else 'Generated text')
            records.append(
                {
                    'id': f'out-{assistant_index}-{index}-{kind}',
                    'kind': kind,
                    'title': title,
                    'filename': str(item.get('filename', '') or '').strip(),
                    'content': content,
                    'path': '',
                    'question': question_text,
                    'question_index': question_index,
                    'assistant_index': assistant_index,
                    'created_at': created_at,
                    'source': str(item.get('source', '') or '').strip() or 'assistant_block',
                    'model_name': model_name,
                }
            )
        for step_index, result in enumerate(step_results or []):
            capability = str(result.get('capability', '') or '').strip()
            capability_label = str(result.get('capability_label', '') or capability or 'Generated output').strip()
            for artifact_index, artifact_path in enumerate(result.get('artifacts') or []):
                path = str(artifact_path or '').strip()
                if not path:
                    continue
                kind = output_kind_from_path(path)
                records.append(
                    {
                        'id': f'out-{assistant_index}-artifact-{step_index}-{artifact_index}',
                        'kind': kind,
                        'title': capability_label,
                        'filename': os.path.basename(path),
                        'content': str(result.get('text_output', '') or '').strip(),
                        'path': path,
                        'question': question_text,
                        'question_index': question_index,
                        'assistant_index': assistant_index,
                        'created_at': created_at,
                        'source': capability or 'specialized_step',
                        'model_name': str(result.get('model_name', '') or model_name).strip(),
                    }
                )
        return normalize_output_records(records)

    def _restore_webfetch_from_conversation_record(self, record: dict | None):
        self._webfetch_generated_attachment = None
        self._webfetch_panel_dismissed = False
        records = []
        if isinstance(record, dict):
            for attachment in ((record.get('webfetch') or {}).get('attachments') or []):
                stored_path = str(attachment.get('stored_path', '')).strip()
                if not stored_path:
                    continue
                loaded = load_webfetch_selection_attachment(stored_path)
                if loaded:
                    records.append(loaded)
        self._webfetch_records = records
        self.webfetch_panel.set_export_records(records)
        if records and self.stacked_widget.currentIndex() == TAB_API:
            self.webfetch_panel.set_collapsed(True)
            self._show_webfetch_panel()
        else:
            self.webfetch_panel.hide()

    def _history_panel_shown_rect(self):
        panel_w = self.history_panel.width()
        panel_h = self.history_panel.height()
        x = max(0, (self.qw3.width() - panel_w) // 2)
        y = max(24, (self.qw3.height() - panel_h) // 2)
        return QRect(
            x,
            y,
            panel_w,
            panel_h,
        )

    def _history_panel_hidden_rect(self):
        shown = self._history_panel_shown_rect()
        return QRect(-shown.width() - 24, shown.y(), shown.width(), shown.height())

    def _links_panel_shown_rect(self):
        panel_w = self.links_panel.width()
        panel_h = self.links_panel.height()
        x = max(0, (self.qw3.width() - panel_w) // 2)
        y = max(24, (self.qw3.height() - panel_h) // 2)
        return QRect(
            x,
            y,
            panel_w,
            panel_h,
        )

    def _links_panel_hidden_rect(self):
        # 触发区在底部，所以面板从底部滑入/滑出（原来是从右侧）。
        shown = self._links_panel_shown_rect()
        return QRect(shown.x(), self.qw3.height() + 24, shown.width(), shown.height())

    def _open_link_url(self, url: str):
        try:
            webbrowser.open(url)
        except Exception:
            pass

    def _open_all_link_urls(self, urls: list[str]):
        for url in urls:
            try:
                webbrowser.open(url)
            except Exception:
                pass

    def _on_link_title_fetched(self, url: str, title: str):
        self._link_title_fetch_inflight.discard(url)
        url = clean_extracted_url(url)
        if not url or not title:
            return
        record = self._load_active_conversation_record()
        if record is None:
            return
        updated = False
        for link in record.get('links', []):
            existing = str(link.get('title', '')).strip()
            if str(link.get('url', '')).strip() == url \
                    and (not existing or _link_title_looks_mojibake(existing)):
                link['title'] = title
                updated = True
        if updated:
            saved = write_conversation_record(record['path'], record)
            self._active_conversation_path = saved['path']
            self._refresh_history_panel()
            self._refresh_links_panel()

    def _bootstrap_conversation_from_messages(self, messages: list[dict]) -> dict:
        ensure_broccoli_data_dir()
        title = conversation_title_from_messages(messages, fallback='Conversation')
        convo_id, path = allocate_conversation_identity(title)
        record = write_conversation_record(
            path,
            {
                'id': convo_id,
                **({'identity': local_conversation_identity()} if ICLOUD_M1C_UNIFIED_FINALIZER_ENABLED else {}),
                'title': title,
                'created_at': datetime.datetime.now().isoformat(timespec='seconds'),
                'updated_at': datetime.datetime.now().isoformat(timespec='seconds'),
                'messages': messages,
                'rendered_markdown': render_chat_history_markdown(messages),
            },
        )
        self._active_conversation_path = record['path']
        self._refresh_history_panel()
        return record

    def _load_active_conversation_record(self) -> dict | None:
        if not self._active_conversation_path:
            return None
        return load_conversation_record(self._active_conversation_path, include_retrieval=False)

    def _refresh_active_conversation_runtime_data(self,
                                                 api_key: str,
                                                 endpoint: str,
                                                 model: str,
                                                 timeout: int,
                                                 refresh_ui: bool = True,
                                                 conversation_path: str | None = None) -> dict | None:
        path = str(conversation_path or self._active_conversation_path or '').strip()
        if not path:
            return None
        result = refresh_conversation_runtime_data_for_path(
            path,
            api_key,
            endpoint,
            model,
            timeout,
        )
        if result.get('updated'):
            updated_path = str(result.get('path') or path)
            if str(self._active_conversation_path or '') == path:
                self._active_conversation_path = updated_path
            path = updated_path
            if refresh_ui and str(self._active_conversation_path or '') == path:
                self._refresh_history_panel()
        return load_conversation_record(path)

    def _build_active_history_context(self,
                                      question_text: str,
                                      history_messages: list[dict],
                                      api_key: str,
                                      endpoint: str,
                                      model: str,
                                      timeout: int,
                                      selected_message_indices: set[int] | None = None,
                                      refresh_ui: bool = True,
                                      conversation_path: str | None = None,
                                      include_recent_messages: bool = True,
                                      retrieval_round_id: str = '') -> str:
        store = load_settings_store()
        globals_store = store.get('globals', {}) if isinstance(store, dict) else {}
        display_limit = normalize_display_history_context_max_chars(
            globals_store.get('display_history_context_max_chars', DISPLAY_HISTORY_CONTEXT_MAX_CHARS)
        )
        if include_recent_messages and bool(globals_store.get('prefer_displayed_history_context', False)) and should_use_display_history_context(
            history_messages,
            max_chars=display_limit,
        ):
            blocks = [build_history_context(history_messages)]
        else:
            blocks = []
            record = self._refresh_active_conversation_runtime_data(
                api_key,
                endpoint,
                model,
                timeout,
                refresh_ui=refresh_ui,
                conversation_path=conversation_path,
            )
            embedding_config = load_embedding_runtime_config()
            embedding_ok = False
            if embedding_config is not None:
                embedding_ok, _ = probe_embedding_capability(embedding_config['profile'])

            if not history_messages and record is not None:
                # The branch filter can legitimately narrow the history, but the
                # conversation's own running summary must never disappear with
                # it: without this block the model used to be left with NOTHING
                # from this conversation while cross-history excerpts from OTHER
                # conversations were still injected — and it answered from those.
                running_summary = str(record.get('memory', {}).get('running_summary', '') or '').strip()
                if running_summary:
                    blocks.append('Conversation memory summary:\n' + running_summary)
            if history_messages:
                if record is None:
                    convo_block = build_history_context(history_messages) if include_recent_messages else ''
                    # print_retrieval_debug('conversation', 'history_fallback', question_text, [])
                else:
                    retrieval_record = record
                    if selected_message_indices is not None:
                        selected_message_indices = {int(idx) for idx in selected_message_indices}
                        retrieval_record = copy.deepcopy(record)
                        retrieval_record['messages'] = [
                            message for message_index, message in enumerate(record.get('messages', []))
                            if message_index in selected_message_indices
                        ]
                        retrieval_record.setdefault('retrieval', {})
                        retrieval_record['retrieval']['chunks'] = [
                            chunk for chunk in record.get('retrieval', {}).get('chunks', [])
                            if int(chunk.get('message_index', -1) or -1) in selected_message_indices
                        ]
                    relevant_chunks = []
                    strategy = 'keyword'
                    keyword_candidates = keyword_retrieve_conversation_chunks(
                        retrieval_record,
                        question_text,
                        top_k=CONVERSATION_RETRIEVAL_CANDIDATE_K,
                    )
                    if embedding_ok and embedding_config is not None and keyword_candidates:
                        try:
                            relevant_chunks = retrieve_conversation_chunks(
                                retrieval_record,
                                question_text,
                                embedding_config['api_key'],
                                embedding_config['endpoint'],
                                embedding_config['timeout'],
                                embedding_config['model'],
                                candidate_chunks=keyword_candidates,
                                min_cosine=retrieval_min_cosine('history'),
                            )
                            strategy = 'keyword+embedding'
                        except Exception:
                            relevant_chunks = []
                    if not relevant_chunks:
                        relevant_chunks = keyword_candidates[:CONVERSATION_RETRIEVAL_TOP_K]
                        strategy = 'keyword'
                    # print_retrieval_debug('conversation', strategy, question_text, relevant_chunks)
                    convo_block = build_conversation_context_block(
                        retrieval_record,
                        relevant_chunks,
                        recent_message_count=CONVERSATION_RECENT_MESSAGES if include_recent_messages else 0,
                    ) or (build_history_context(history_messages) if include_recent_messages else '')
                if convo_block:
                    blocks.append(convo_block)

        try:
            cross_history_chunks = retrieve_cross_history_chunks(
                question_text,
                active_conversation_path=conversation_path or getattr(self, '_active_conversation_path', ''),
                round_id=str(retrieval_round_id or ''),
            )
            # DEBUG NOTE: Cross-history retrieval debug is intentionally disabled.
            # Uncomment temporarily while debugging retrieval hits, then comment it
            # again before normal use.
            # print_cross_history_debug(question_text, cross_history_chunks)
            cross_history_block = build_cross_history_context_block(cross_history_chunks)
            if cross_history_block:
                blocks.append(cross_history_block)
        except Exception:
            pass

        return '\n\n'.join(block for block in blocks if block).strip()

    def _build_saved_memory_prompt_context(self, question_text: str) -> str:
        embedding_config = load_embedding_runtime_config()
        embedding_ok = False
        if embedding_config is not None:
            embedding_ok, _ = probe_embedding_capability(embedding_config['profile'])
        return build_saved_memory_context(question_text, embedding_config, embedding_ok)

    def _build_external_context_prompt_context(self, question_text: str, progress_callback=None) -> str:
        store = load_settings_store()
        globals_store = store.get('globals', {}) if isinstance(store, dict) else {}
        if not bool(globals_store.get('external_context_enabled', True)):
            return ''
        sources = normalize_external_context_sources(globals_store.get('external_context_sources', []))
        if not sources:
            return ''
        documents = collect_external_context_documents(sources, question_text, progress_callback)
        if not documents:
            return ''
        max_chars = normalize_external_context_max_chars(
            globals_store.get('external_context_max_chars', DEFAULT_EXTERNAL_CONTEXT_MAX_CHARS)
        )
        total_chars = sum(len(str(document.get('content', '') or '')) for document in documents)
        if total_chars <= max_chars:
            return build_external_context_full_block(documents, max_chars)

        chunks = build_attachment_retrieval_chunks(documents)
        if not chunks:
            return ''
        relevant_chunks = []
        embedding_used = False
        embedding_config = load_embedding_runtime_config()
        embedding_ok = False
        if embedding_config is not None:
            embedding_ok, _ = probe_embedding_capability(embedding_config['profile'])
        if bool(globals_store.get('external_context_use_embedding', True)) and embedding_ok and embedding_config is not None:
            keyword_candidates = keyword_retrieve_attachment_chunks(
                chunks,
                question_text,
                top_k=ATTACHMENT_RETRIEVAL_CANDIDATE_K,
            )
            try:
                if keyword_candidates:
                    relevant_chunks = retrieve_attachment_chunks(
                        keyword_candidates,
                        question_text,
                        embedding_config['api_key'],
                        embedding_config['endpoint'],
                        embedding_config['timeout'],
                        embedding_config['model'],
                        min_cosine=retrieval_min_cosine('external'),
                    )
                embedding_used = True
            except Exception:
                relevant_chunks = []
                embedding_used = False
        # Only fall back to the (thresholdless) keyword path when embedding was
        # unavailable. If embedding ran and returned nothing, that means nothing
        # cleared the relevance gate, so inject nothing rather than re-dumping
        # unrelated notes / PII just to fill the slot.
        if not relevant_chunks and not embedding_used:
            relevant_chunks = keyword_retrieve_attachment_chunks(
                chunks,
                question_text,
                top_k=ATTACHMENT_RETRIEVAL_TOP_K,
            )
        mcp_chunks = [chunk for chunk in chunks if chunk.get('source_type') in {'mcp_http', 'mcp_stdio'}]
        if mcp_chunks:
            seen = {(chunk.get('name'), chunk.get('text')) for chunk in mcp_chunks[:MCP_HTTP_CONTEXT_MAX_TOOL_CALLS]}
            relevant_chunks = (
                mcp_chunks[:MCP_HTTP_CONTEXT_MAX_TOOL_CALLS]
                + [chunk for chunk in relevant_chunks if (chunk.get('name'), chunk.get('text')) not in seen]
            )
        return build_external_context_retrieval_block(relevant_chunks)

    def _build_specialized_step_retrieval_query(self,
                                                *,
                                                question_text: str,
                                                goal: str,
                                                previous_results: list[dict],
                                                downstream_extract: str = '',
                                                explicit_query: str = '') -> str:
        explicit = str(explicit_query or '').strip()
        if explicit:
            return explicit
        parts = [
            'Original user request:\n' + str(question_text or '').strip(),
            'Current specialized step goal:\n' + str(goal or '').strip(),
        ]
        previous_sections = []
        for result in previous_results or []:
            body = specialized_step_context_output(result)
            if body:
                previous_sections.append(body)
        if previous_sections:
            parts.append('Relevant previous step result:\n' + '\n\n'.join(previous_sections))
        if downstream_extract:
            parts.append('Downstream need:\n' + str(downstream_extract or '').strip())
        return '\n\n'.join(part for part in parts if part.strip()).strip()

    def _available_specialized_step_context_sources(self,
                                                    retrieval_documents: list[dict],
                                                    history_messages: list[dict]) -> list[str]:
        available = []
        if retrieval_documents:
            available.append('attachments')
        if read_text_file(BasePath + 'history.txt', '0') == '1' and history_messages:
            available.append('history')
        active_profile = load_active_settings_profile()
        if active_profile.get('remember_memory', True):
            available.append('memory')
        store = load_settings_store()
        globals_store = store.get('globals', {}) if isinstance(store, dict) else {}
        if bool(globals_store.get('external_context_enabled', True)):
            sources = normalize_external_context_sources(globals_store.get('external_context_sources', []))
            if any(source.get('enabled', True) and source.get('auto_context', True) for source in sources):
                available.append('external')
        return [source for source in SPECIALIZED_STEP_CONTEXT_SOURCES if source in available]

    def _specialized_step_context_source_scope(self,
                                               query_text: str,
                                               available_sources: list[str],
                                               *,
                                               allow_default_local: bool = False) -> list[str]:
        selected = []
        for source in SPECIALIZED_STEP_CONTEXT_SOURCES:
            if source not in available_sources:
                continue
            if specialized_auto_query_has_hint(query_text, SPECIALIZED_AUTO_SOURCE_HINTS.get(source, set())):
                selected.append(source)
        if not selected and allow_default_local:
            selected = [source for source in ('attachments', 'history', 'memory') if source in available_sources]
        return selected

    def _resolve_specialized_step_retrieval_request(self,
                                                    *,
                                                    policy: str,
                                                    capability: str,
                                                    query_text: str,
                                                    explicit_query: str,
                                                    shared_context: str,
                                                    previous_results: list[dict],
                                                    retrieval_documents: list[dict],
                                                    history_messages: list[dict]) -> dict:
        normalized_policy = normalize_specialized_step_context_policy(policy)
        available_sources = self._available_specialized_step_context_sources(retrieval_documents, history_messages)
        query = str(query_text or '').strip()
        explicit = bool(str(explicit_query or '').strip())
        previous_context = '\n\n'.join(
            specialized_step_context_output(result)
            for result in (previous_results or [])
            if specialized_step_context_output(result)
        )
        available_context = '\n\n'.join(part for part in (shared_context, previous_context) if str(part or '').strip())
        coverage, missing_terms = specialized_auto_context_coverage(query, available_context)

        base = {
            'should_retrieve': False,
            'effective_policy': 'none',
            'sources': [],
            'reason': '',
            'coverage': coverage,
            'missing_terms': missing_terms,
        }
        if normalized_policy == 'none':
            base['reason'] = _tr('Planner requested no extra step context.')
            return base
        if not query:
            base['reason'] = _tr('Step did not produce a retrieval query.')
            return base
        if not available_sources:
            base['reason'] = _tr('No step-specific context sources are available.')
            return base

        if normalized_policy == 'fresh':
            base.update({
                'should_retrieve': True,
                'effective_policy': 'fresh',
                'sources': available_sources,
                'reason': _tr('Planner explicitly requested fresh step context.'),
            })
            return base

        source_scope = self._specialized_step_context_source_scope(
            query,
            available_sources,
            allow_default_local=False,
        )
        has_knowledge_hint = specialized_auto_query_has_hint(query, SPECIALIZED_AUTO_KNOWLEDGE_HINTS)

        if capability in SPECIALIZED_AUTO_CONTEXT_DEFAULT_SKIP_CAPABILITIES and not explicit:
            base['reason'] = _tr('Auto skipped because {capability} normally gathers or transforms its own input.').format(capability=specialized_capability_label(capability))
            return base
        if previous_context.strip() and not explicit and not has_knowledge_hint:
            base['reason'] = _tr('Auto skipped because the step is driven by previous step output.')
            return base
        if coverage >= (0.72 if explicit else 0.55):
            base['reason'] = _tr('Auto skipped because existing context covers the step query ({coverage:.0%}).').format(coverage=coverage)
            return base

        if not source_scope and explicit:
            source_scope = [source for source in ('attachments', 'history', 'memory') if source in available_sources]
        if not source_scope and not available_context.strip() and capability in SPECIALIZED_AUTO_CONTEXT_KNOWLEDGE_CAPABILITIES:
            source_scope = [source for source in ('attachments', 'history', 'memory') if source in available_sources] or available_sources

        if explicit and source_scope:
            base.update({
                'should_retrieve': True,
                'effective_policy': 'auto',
                'sources': source_scope,
                'reason': _tr('Auto found a focused context_query with missing terms ({coverage:.0%} covered).').format(coverage=coverage),
            })
            return base
        if has_knowledge_hint and source_scope and coverage < 0.65:
            base.update({
                'should_retrieve': True,
                'effective_policy': 'auto',
                'sources': source_scope,
                'reason': _tr('Auto found an explicit retrieval/source need with missing terms ({coverage:.0%} covered).').format(coverage=coverage),
            })
            return base
        if capability in SPECIALIZED_AUTO_CONTEXT_KNOWLEDGE_CAPABILITIES and source_scope and coverage < 0.35:
            base.update({
                'should_retrieve': True,
                'effective_policy': 'auto',
                'sources': source_scope,
                'reason': _tr('Auto found low coverage for a knowledge-oriented step ({coverage:.0%} covered).').format(coverage=coverage),
            })
            return base

        base['reason'] = _tr('Auto skipped because no clear new knowledge gap was found ({coverage:.0%} covered).').format(coverage=coverage)
        return base

    def _build_specialized_step_retrieval_context(self,
                                                  *,
                                                  query_text: str,
                                                  history_messages: list[dict],
                                                  selected_message_indices: set | list | None,
                                                  retrieval_documents: list[dict],
                                                  api_key: str,
                                                  endpoint: str,
                                                  model: str,
                                                  timeout: int,
                                                  context_sources: list[str] | tuple[str, ...] | set[str] | None = None,
                                                  conversation_path: str | None = None,
                                                  progress_callback=None) -> str:
        query = str(query_text or '').strip()
        if not query:
            return ''
        blocks = []
        enabled_sources = set(context_sources or SPECIALIZED_STEP_CONTEXT_SOURCES)

        def progress(message: str):
            if progress_callback is None:
                return
            try:
                progress_callback(str(message or '').strip())
            except Exception:
                pass

        if 'attachments' in enabled_sources and retrieval_documents:
            attachment_context, _attachment_references = self._build_attachment_retrieval_context(
                query,
                retrieval_documents,
                api_key,
                endpoint,
                timeout,
            )
            if attachment_context:
                blocks.append(attachment_context)

        history_enabled = read_text_file(BasePath + 'history.txt', '0') == '1'
        if 'history' in enabled_sources and history_enabled and history_messages:
            history_context = self._build_active_history_context(
                query,
                history_messages,
                api_key,
                endpoint,
                model,
                timeout,
                selected_message_indices=selected_message_indices,
                refresh_ui=False,
                conversation_path=conversation_path,
            )
            if history_context:
                blocks.append(history_context)

        active_profile = load_active_settings_profile()
        if 'memory' in enabled_sources and active_profile.get('remember_memory', True):
            memory_context = self._build_saved_memory_prompt_context(query)
            if memory_context:
                blocks.append(memory_context)

        if 'external' in enabled_sources:
            progress(_tr('Retrieving step-specific external context and MCP sources'))
            external_context = self._build_external_context_prompt_context(query, progress_callback=progress_callback)
            if external_context:
                blocks.append(external_context)

        context = '\n\n'.join(block for block in blocks if block).strip()
        if len(context) > SPECIALIZED_STEP_RETRIEVAL_CONTEXT_MAX_CHARS:
            context = context[:SPECIALIZED_STEP_RETRIEVAL_CONTEXT_MAX_CHARS].rstrip() + '\n\n[Step-specific context truncated.]'
        return context

    def _ensure_active_conversation(self, first_question: str, history_messages: list[dict]):
        if self._active_conversation_path:
            return
        record = create_conversation_record(first_question, history_messages=history_messages)
        self._active_conversation_path = record['path']
        self._refresh_history_panel()

    def _materialize_unsaved_agent_page_before_new(self):
        if self._active_conversation_path:
            return
        history_messages = get_current_chat_history_messages()
        if history_messages:
            record = self._bootstrap_conversation_from_messages(history_messages)
            self._show_agent_conversation_badge(record.get('path', ''), status='finished')
            return
        prompt = ''
        try:
            prompt = str(self.text1.toPlainText() or '').strip()
        except Exception:
            prompt = ''
        if not prompt:
            return
        record = create_conversation_record(prompt, history_messages=[])
        self._active_conversation_path = record['path']
        self._show_agent_conversation_badge(record['path'], status='finished', title=record.get('title', prompt))
        self._refresh_history_panel()

    def _save_conversation_at_path(self, path: str, messages: list[dict], new_outputs: list[dict] | None = None) -> str:
        perf_started = time.perf_counter()
        path = str(path or '').strip()
        if not messages:
            return path
        if not path:
            record = self._bootstrap_conversation_from_messages(messages)
            path = record['path']
        record = load_conversation_record(path, include_retrieval=False)
        loaded_at = time.perf_counter()
        if record is None:
            record = create_conversation_record(
                conversation_title_from_messages(messages, fallback='Agent conversation'),
                history_messages=[],
            )
            path = record['path']
        is_visible_conversation = str(self._active_conversation_path or '') == path
        if ICLOUD_M1C_UNIFIED_FINALIZER_ENABLED:
            record.setdefault('identity', local_conversation_identity())
        record['messages'] = list(messages)
        if new_outputs:
            record['outputs'] = merge_output_records(record.get('outputs', []), new_outputs)
        record['title'] = conversation_title_for_save(record, messages, fallback=record.get('title', 'Agent conversation'))
        record['updated_at'] = datetime.datetime.now().isoformat(timespec='seconds')
        record['rendered_markdown'] = render_chat_history_markdown(messages)
        record = self._recover_and_persist_structured_outputs(record, persist=False) or record
        saved = write_conversation_record(path, record)
        written_at = time.perf_counter()
        saved_path = saved['path']
        if is_visible_conversation:
            self._active_conversation_path = saved_path
            self._refresh_links_panel()
            self._refresh_outputs_panel(prefer_latest=bool(new_outputs))
            self._refresh_branch_state_from_current_conversation()
            self._auto_show_outputs_panel_for_new_outputs(new_outputs, visible_conversation=True)
        self._refresh_history_panel()
        finished_at = time.perf_counter()
        _agent_render_perf_log(
            'save_conversation_path',
            history_refresh_ms=round((finished_at - written_at) * 1000, 2),
            load_ms=round((loaded_at - perf_started) * 1000, 2),
            messages=len(messages),
            path=os.path.basename(path),
            total_ms=round((finished_at - perf_started) * 1000, 2),
            write_ms=round((written_at - loaded_at) * 1000, 2),
        )
        return saved_path

    def _save_active_conversation(self, messages: list[dict], new_outputs: list[dict] | None = None):
        if not messages:
            return
        if not self._active_conversation_path:
            self._bootstrap_conversation_from_messages(messages)
            if new_outputs:
                self._save_active_conversation(messages, new_outputs=new_outputs)
                return
            self._refresh_links_panel()
            self._refresh_outputs_panel()
            self._refresh_branch_state_from_current_conversation()
            return
        record = load_conversation_record(self._active_conversation_path, include_retrieval=False)
        if record is None:
            self._bootstrap_conversation_from_messages(messages)
            if new_outputs:
                self._save_active_conversation(messages, new_outputs=new_outputs)
                return
            self._refresh_links_panel()
            self._refresh_outputs_panel()
            self._refresh_branch_state_from_current_conversation()
            return
        record['messages'] = list(messages)
        if ICLOUD_M1C_UNIFIED_FINALIZER_ENABLED:
            record.setdefault('identity', local_conversation_identity())
        if new_outputs:
            record['outputs'] = merge_output_records(record.get('outputs', []), new_outputs)
        record['title'] = conversation_title_for_save(record, messages, fallback=record['title'])
        record['updated_at'] = datetime.datetime.now().isoformat(timespec='seconds')
        record['rendered_markdown'] = render_chat_history_markdown(messages)
        record = self._recover_and_persist_structured_outputs(record, persist=False) or record
        saved = write_conversation_record(self._active_conversation_path, record)
        self._active_conversation_path = saved['path']
        self._refresh_history_panel()
        self._refresh_links_panel()
        self._refresh_outputs_panel(prefer_latest=True)
        self._refresh_branch_state_from_current_conversation()
        self._auto_show_outputs_panel_for_new_outputs(new_outputs, visible_conversation=True)

    # ── 切换对话时的阅读位置记忆（2026-10-17）──────────────────────
    def _conversation_scroll_anchors_store(self) -> dict:
        store = getattr(self, '_conversation_scroll_anchors', None)
        if not isinstance(store, dict):
            store = {}
            self._conversation_scroll_anchors = store
        return store

    def _capture_conversation_scroll_anchor(self):
        """Remember where the reader is in the conversation now on screen: the
        topmost visible message and its offset, or "at the bottom". The page
        answers asynchronously, but before the next conversation is installed."""
        path = str(getattr(self, '_rendered_conversation_path', '') or '')
        if not path or path != str(getattr(self, '_active_conversation_path', '') or '') \
                or not getattr(self, '_agent_shell_ready', False):
            return
        store = self._conversation_scroll_anchors_store()

        def remember(result, path=path):
            if isinstance(result, dict) and result.get('ok'):
                store[path] = {key: result.get(key) for key in ('index', 'offset', 'block', 'atBottom', 'gap', 'atTop', 'total')}

        try:
            self.real2.page().runJavaScript(
                'window.broccoliCaptureScrollAnchor ? window.broccoliCaptureScrollAnchor() : null',
                remember,
            )
        except Exception:
            logging.exception('Capturing the conversation reading position failed.')

    def _take_pending_position_restore(self):
        pending = getattr(self, '_pending_position_restore', None)
        self._pending_position_restore = None
        if isinstance(pending, dict) and pending.get('path') == str(self._active_conversation_path or ''):
            return pending
        return None

    def _begin_conversation_switch_feedback(self):
        """Start the switch's loading state in the page: if the next conversation is
        not installed within CONVERSATION_SWITCH_LOADING_DELAY_MS, the current one dims
        and a thin progress bar shows. Installing the next conversation ends it."""
        if not getattr(self, '_agent_shell_ready', False):
            return
        try:
            self.real2.page().runJavaScript(
                'window.broccoliBeginConversationSwitch && window.broccoliBeginConversationSwitch(%d);'
                % int(CONVERSATION_SWITCH_LOADING_DELAY_MS)
            )
        except Exception:
            logging.exception('Starting the conversation switch feedback failed.')

    def _cancel_conversation_switch_feedback(self):
        if not getattr(self, '_agent_shell_ready', False):
            return
        try:
            self.real2.page().runJavaScript(
                'window.broccoliCancelConversationSwitch && window.broccoliCancelConversationSwitch();'
            )
        except Exception:
            logging.exception('Cancelling the conversation switch feedback failed.')

    def _load_conversation_from_path(self, path: str):
        # 先启动“加载中”计时：后面读文件、发布到 iCloud 等都算进切换耗时。
        self._begin_conversation_switch_feedback()
        if ICLOUD_M7_UNIFIED_HISTORY_ENABLED:
            provider = get_unified_history_provider()
            if isinstance(provider, UnifiedHistoryProvider):
                try:
                    provider.touch(path)
                except Exception:
                    logging.exception('Lazy history publication failed.')
        record = load_conversation_record(path, include_retrieval=False)
        if record is None:
            self._cancel_conversation_switch_feedback()
            return
        # 离开前记下当前对话的阅读位置（页面里异步取，先于新对话装载执行）。
        self._capture_conversation_scroll_anchor()
        self._pending_position_restore = None
        record = self._recover_and_persist_structured_outputs(record, persist=True) or record
        self._flush_structured_transfer_edits_for_current_conversation()
        self._reset_structured_transfer_state()
        self._mcp_conversation_allowlist = set()
        self._active_conversation_path = record['path']
        save_chat_history_messages(record['messages'])
        self.trans = 0
        self.text1.clear()
        self._set_prompt_edit_read_only(False)
        self._attachment_tray.clear()
        run = self._agent_run_for_path(record['path'])
        if run is not None:
            phase = str(run.get('phase', '') or '')
            if phase == 'preflight':
                self._active_preflight_request = run
                self._active_preflight_signals = run.get('preflight_signals')
                self._active_preflight_thread = run.get('preflight_thread')
                self._active_chat_request = None
                self._active_chat_signals = None
                self._active_chat_thread = None
                self._active_browser_use_request = None
                self._active_browser_use_signals = None
                self._active_browser_use_thread = None
            elif phase == 'browser_use':
                self._active_browser_use_request = run
                self._active_browser_use_signals = run.get('browser_use_signals')
                self._active_browser_use_thread = run.get('browser_use_thread')
                self._active_preflight_request = None
                self._active_preflight_signals = None
                self._active_preflight_thread = None
                self._active_chat_request = None
                self._active_chat_signals = None
                self._active_chat_thread = None
            elif phase == 'computer_use':
                # Computer Use keeps no module-level active-thread trackers (its
                # stop path goes through the run dict); just clear the others so
                # a stale chat/browser tracker can't shadow this run.
                self._active_preflight_request = None
                self._active_preflight_signals = None
                self._active_preflight_thread = None
                self._active_chat_request = None
                self._active_chat_signals = None
                self._active_chat_thread = None
                self._active_browser_use_request = None
                self._active_browser_use_signals = None
                self._active_browser_use_thread = None
            else:
                self._active_chat_request = run
                self._active_chat_signals = run.get('chat_signals')
                self._active_chat_thread = run.get('chat_thread')
                self._active_preflight_request = None
                self._active_preflight_signals = None
                self._active_preflight_thread = None
                self._active_browser_use_request = None
                self._active_browser_use_signals = None
                self._active_browser_use_thread = None
            # 运行中的对话改显示纯文字预览，不走网页装载：取消“加载中”。
            self._cancel_conversation_switch_feedback()
            self._render_agent_run_preview_if_active(run)
        elif record['messages']:
            # 装载完成后回到上次的阅读位置并显示位置选择浮条（运行中的对话仍跟随
            # 最新输出，不在此列）。
            anchor = self._conversation_scroll_anchors_store().get(record['path'])
            self._pending_position_restore = {
                'path': record['path'],
                'anchor': dict(anchor) if isinstance(anchor, dict) else None,
            }
            self.render_final_output(record['rendered_markdown'], history_messages=record['messages'])
            self._refresh_agent_send_button_state()
        else:
            self._cancel_conversation_switch_feedback()
            self.show_welcome_state()
            self._refresh_agent_send_button_state()
        self._restore_webfetch_from_conversation_record(record)
        self._refresh_links_panel()
        self._refresh_outputs_panel()
        self._refresh_branch_state_from_current_conversation()
        self._refresh_agent_queue_panel(record['path'])
        self.hide_history_panel()
        self._refresh_agent_conversation_shelf()
        # Default the prompt box to this conversation's last @targets (works on restart).
        self._apply_carryover_targets()
        self._refresh_remote_owner_hint()

    def _rename_conversation_from_tag(self, path: str):
        """Left tag → right-click → Rename…: the same prompt and rename as the history list."""
        record = load_conversation_record(path, include_retrieval=False)
        if not isinstance(record, dict):
            return
        new_title, ok = ask_broccoli_text(self, _tr('Rename history'), _tr('History name:'),
                                          str(record.get('title', '') or ''))
        if ok and new_title.strip():
            self._rename_conversation(record.get('path') or path, new_title.strip())

    def _rename_conversation(self, path: str, new_title: str):
        if ICLOUD_M7_UNIFIED_HISTORY_ENABLED:
            provider = get_unified_history_provider()
            result = provider.rename(path, new_title) if isinstance(provider, UnifiedHistoryProvider) else {'status': 'missing'}
            if str(result.get('status', '') or '') == 'rename_requested':
                self._refresh_history_panel()
                self._refresh_agent_conversation_shelf()
                return
            updated = result.get('record') if isinstance(result.get('record'), dict) else None
        else:
            updated = rename_conversation_record(path, new_title)
        if updated is None:
            return
        if path in self._branch_states:
            self._branch_states[updated['path']] = self._branch_states.pop(path)
            self._branch_states[updated['path']]['conversation_path'] = updated['path']
        anchors = self._conversation_scroll_anchors_store()
        if path in anchors:
            anchors[updated['path']] = anchors.pop(path)
        if self._active_conversation_path == path:
            self._active_conversation_path = updated['path']
        if path in self._agent_conversation_finished_badges:
            self._agent_conversation_finished_badges[updated['path']] = self._agent_conversation_finished_badges.pop(path)
            self._agent_conversation_finished_badges[updated['path']]['title'] = updated.get('title', new_title)
        if path in self._agent_conversation_hidden_badges:
            self._agent_conversation_hidden_badges.discard(path)
            self._agent_conversation_hidden_badges.add(updated['path'])
        if path in self._agent_conversation_open_badges:
            self._agent_conversation_open_badges.discard(path)
            self._agent_conversation_open_badges.add(updated['path'])
            self._persist_agent_conversation_open_badges()
        if path in getattr(self, '_agent_prompt_queues', {}):
            self._agent_prompt_queues[updated['path']] = self._agent_prompt_queues.pop(path)
        entry = _conversation_history_index_entry(updated)
        self.history_panel.patch_record(path, {key: entry[key] for key in ('path', 'title', 'search_blob', 'updated_at')
                                               if key in entry})   # the full list rebuilds behind it
        self._refresh_history_panel()
        self._refresh_agent_conversation_shelf()   # the tag shows the new name right away
        self._refresh_links_panel()
        self._refresh_outputs_panel()
        self._refresh_branch_state_from_current_conversation()
        self._refresh_agent_queue_panel(updated['path'])

    def _delete_conversation(self, path: str):
        flush_async_file_writes(2.0)
        path = resolve_conversation_path(path)
        if ICLOUD_M7_UNIFIED_HISTORY_ENABLED:
            provider = get_unified_history_provider()
            result = provider.delete(path) if isinstance(provider, UnifiedHistoryProvider) else {'status': 'missing'}
            if str(result.get('status', '') or '') != 'tombstoned':
                return
            self._cancel_agent_run_for_deletion(path)
            self._branch_states.pop(path, None)
            self._agent_conversation_finished_badges.pop(path, None)
            self._agent_conversation_open_badges.discard(path)
            self._agent_conversation_hidden_badges.discard(path)
            getattr(self, '_agent_prompt_queues', {}).pop(path, None)
            self._persist_agent_conversation_open_badges()
            if self._active_conversation_path == path:
                self._active_conversation_path = None
                self.ClearX(materialize_current=False)
            self.history_panel.remove_record(path)   # gone at once; the full list rebuilds behind it
            self._refresh_history_panel()
            self._refresh_links_panel()
            self._refresh_agent_queue_panel()
            return
        if not os.path.exists(path):
            return
        if ICLOUD_M2_CONVERSATION_RESOLVER_ENABLED:
            resolver = get_conversation_path_resolver()
            if resolver is not None:
                resolver.mark_deleted(conversation_id_for_reference(path), path)
        self._cancel_agent_run_for_deletion(path)
        attach_dir = conversation_attachment_dir(path)
        os.remove(path)
        retrieval_path = conversation_retrieval_sidecar_path(path)
        if os.path.exists(retrieval_path):
            os.remove(retrieval_path)
        derived_path = conversation_derived_sidecar_path(path)
        if os.path.exists(derived_path):
            os.remove(derived_path)
        with _CONVERSATION_RECORD_CACHE_LOCK:
            _CONVERSATION_RECORD_CACHE.pop(path, None)
            _CONVERSATION_RECORD_CACHE_META.pop(path, None)
            _CONVERSATION_RECORD_GENERATION.pop(path, None)
            _CONVERSATION_LAZY_RETRIEVAL.pop(path, None)
        with _CONVERSATION_HISTORY_INDEX_LOCK:
            _CONVERSATION_HISTORY_INDEX.pop(path, None)
        if os.path.isdir(attach_dir):
            shutil.rmtree(attach_dir, ignore_errors=True)
        self._branch_states.pop(path, None)
        self._agent_conversation_finished_badges.pop(path, None)
        self._agent_conversation_open_badges.discard(path)
        self._agent_conversation_hidden_badges.discard(path)
        getattr(self, '_agent_prompt_queues', {}).pop(path, None)
        self._persist_agent_conversation_open_badges()
        if self._active_conversation_path == path:
            self._active_conversation_path = None
            self.ClearX(materialize_current=False)
        self._refresh_history_panel()
        self._refresh_links_panel()
        self._refresh_agent_queue_panel()

    def apply_webfetch_watch_settings(self, folder: str):
        folder = str(folder or '').strip()
        self._webfetch_watch_manager.start(folder)

    def _on_webfetch_watch_status_changed(self, message: str):
        self._webfetch_watch_status = str(message or '').strip()

    def _on_webfetch_file_imported(self, record: dict):
        self._webfetch_records = [
            item for item in self._webfetch_records
            if str(item.get('path', '')).strip() != str(record.get('path', '')).strip()
        ]
        self._webfetch_records.append(record)
        self._webfetch_records.sort(key=lambda item: str(item.get('exported_at', '')).strip(), reverse=True)
        self._webfetch_panel_dismissed = False
        self._webfetch_generated_attachment = None
        self.webfetch_panel.append_export_record(record)
        current_index = self.stacked_widget.currentIndex()
        panel, _dock = self._external_prompt_panel_for_index(current_index)
        if current_index == TAB_API or (panel is not None and panel.is_prompt_dock_visible()):
            self.webfetch_panel.set_collapsed(False)
            self._show_webfetch_panel()

    def _close_webfetch_panel(self):
        self._webfetch_panel_dismissed = True
        previous = self._webfetch_generated_attachment or {}
        previous_path = str(previous.get('stored_path', '')).strip()
        if previous_path and os.path.exists(previous_path):
            try:
                os.remove(previous_path)
            except Exception:
                pass
        self.webfetch_panel.hide()
        self._webfetch_generated_attachment = None

    def _on_webfetch_selection_changed(self):
        self._webfetch_generated_attachment = None
        if self._active_conversation_path:
            self._persist_current_webfetch_selection(self._active_conversation_path)

    def _on_webfetch_panel_collapsed(self, collapsed: bool):
        if not hasattr(self, 'webfetch_panel'):
            return
        target = self._webfetch_panel_rect()
        if not self.webfetch_panel.isVisible():
            self.webfetch_panel.setGeometry(target)
            return
        start = self.webfetch_panel.geometry()
        if start == target:
            return
        self._webfetch_panel_anim = QPropertyAnimation(self.webfetch_panel, b'geometry', self)
        self._webfetch_panel_anim.setDuration(180)
        self._webfetch_panel_anim.setEasingCurve(QEasingCurve.Type.OutCubic)
        self._webfetch_panel_anim.setStartValue(start)
        self._webfetch_panel_anim.setEndValue(target)
        self._webfetch_panel_anim.start()

    def _webfetch_panel_rect(self) -> QRect:
        collapsed = self.webfetch_panel.is_collapsed()
        width = self.webfetch_panel.COLLAPSED_D if collapsed else self.webfetch_panel.PANEL_W
        height = self.webfetch_panel.COLLAPSED_D if collapsed else self.webfetch_panel.PANEL_H
        if collapsed:
            x = max(20, self.qw3.width() - width - 20)
        else:
            x = max(0, (self.qw3.width() - width) // 2)
        top_bar_bottom = 0
        if getattr(self, 'pill_nav', None) is not None:
            try:
                top_bar_bottom = self.qw3.mapFrom(self, self.pill_nav.geometry().bottomLeft()).y() + 22
            except Exception:
                top_bar_bottom = 0
        y = max(58, top_bar_bottom)
        return QRect(x, y, width, height)

    def _update_webfetch_panel_geometry(self):
        if not hasattr(self, 'webfetch_panel'):
            return
        self.webfetch_panel.setGeometry(self._webfetch_panel_rect())
        self.webfetch_panel.raise_()

    def _show_webfetch_panel(self):
        if self._webfetch_panel_dismissed:
            return
        current_index = self.stacked_widget.currentIndex()
        panel, _dock = self._external_prompt_panel_for_index(current_index)
        if current_index != TAB_API and not (panel is not None and panel.is_prompt_dock_visible()):
            return
        target = self._webfetch_panel_rect()
        if not self.webfetch_panel.isVisible():
            self.webfetch_panel.setGeometry(target)
            self.webfetch_panel.show()
        else:
            self._update_webfetch_panel_geometry()
        self.webfetch_panel.show()
        self.webfetch_panel.raise_()

    def _selected_webfetch_pages(self) -> list[dict]:
        if self._webfetch_panel_dismissed:
            return []
        return self.webfetch_panel.selected_pages()

    def _persist_current_webfetch_selection(self, conversation_path: str) -> dict | None:
        pages = self._selected_webfetch_pages()
        previous = self._webfetch_generated_attachment or {}
        previous_path = str(previous.get('stored_path', '')).strip()
        if not pages or not conversation_path:
            if previous_path and os.path.exists(previous_path):
                try:
                    os.remove(previous_path)
                except Exception:
                    pass
            self._webfetch_generated_attachment = None
            return None
        attach_dir = conversation_attachment_dir(conversation_path)
        os.makedirs(attach_dir, exist_ok=True)
        if previous_path and os.path.exists(previous_path):
            try:
                os.remove(previous_path)
            except Exception:
                pass
        payload = {
            'schema': 'broccoli-webfetch-selection/v1',
            'generatedAt': datetime.datetime.now().isoformat(timespec='seconds'),
            'sources': [
                {
                    'path': str(page.get('_source_path', '')).strip(),
                    'url': str(page.get('url', '')).strip(),
                    'title': str(page.get('title', '')).strip(),
                }
                for page in pages
            ],
            'count': len(pages),
            'pages': pages,
        }
        safe_name = f"Broccoli-WebFetch-Selection_{datetime.datetime.now().strftime('%Y-%m-%dT%H-%M-%S')}_{len(pages)}pages.json"
        target_path = os.path.join(attach_dir, safe_name)
        with open(target_path, 'w', encoding='utf-8') as handle:
            json.dump(payload, handle, ensure_ascii=False, indent=2)
        stored_rel_path = os.path.relpath(target_path, os.path.dirname(conversation_path))
        documents = webfetch_documents_from_pages(pages)
        extracted_text = '\n\n'.join(doc['content'] for doc in documents).strip()
        use_embedding = self._webfetch_context_use_embedding_enabled()
        retrieval_chunks = build_attachment_retrieval_chunks(documents) if use_embedding else []
        attachment_record = {
            'name': os.path.basename(target_path),
            'kind': 'json',
            'original_path': '',
            'stored_path': target_path,
            'stored_rel_path': stored_rel_path,
            'send_mode': 'retrieval_text' if use_embedding else 'text_direct',
            'use_embedding': use_embedding,
            'extracted_text': extracted_text,
            'pages': pages,
            'source_path': '',
        }
        if retrieval_chunks:
            attachment_record['retrieval_chunks'] = retrieval_chunks
        self._webfetch_generated_attachment = attachment_record
        return attachment_record

    def _current_webfetch_attachment(self, conversation_path: str) -> dict | None:
        if not conversation_path:
            return None
        if self._webfetch_generated_attachment:
            stored_path = str(self._webfetch_generated_attachment.get('stored_path', '')).strip()
            if (
                stored_path
                and os.path.exists(stored_path)
                and bool(self._webfetch_generated_attachment.get('use_embedding')) == self._webfetch_context_use_embedding_enabled()
            ):
                return self._webfetch_generated_attachment
        return self._persist_current_webfetch_selection(conversation_path)

    def _schedule_daily_memory_rollup(self):
        if not hasattr(self, '_daily_memory_timer'):
            return
        self._daily_memory_timer.stop()
        now = datetime.datetime.now()
        target = now.replace(hour=23, minute=30, second=0, microsecond=0)
        if now >= target:
            target += datetime.timedelta(days=1)
        delay_ms = max(1000, int((target - now).total_seconds() * 1000))
        self._daily_memory_timer.start(delay_ms)

    def _check_daily_memory_rollup_on_startup(self):
        store = load_settings_store()
        globals_store = store.get('globals', {})
        now = datetime.datetime.now()
        today = now.date()
        yesterday = today - datetime.timedelta(days=1)
        last = str(globals_store.get('memory_last_rollup_date', '')).strip()
        if not last or last < yesterday.isoformat():
            logging.info('Daily memory rollup missed previous day; catching up for %s.', yesterday.isoformat())
            self._start_daily_memory_rollup(force=True, target_date=yesterday.isoformat())
            return
        if now.hour > 23 or (now.hour == 23 and now.minute >= 30):
            if last != today.isoformat():
                logging.info('Daily memory rollup catching up for current day %s after cutoff.', today.isoformat())
                self._start_daily_memory_rollup(force=True, target_date=today.isoformat())

    def _start_daily_memory_rollup(self, force: bool = False, target_date: str | datetime.date | None = None):
        if getattr(self, '_daily_memory_rollup_running', False):
            logging.info('Daily memory rollup skipped: another rollup is already running.')
            return
        self._schedule_daily_memory_rollup()
        self._daily_memory_rollup_running = True
        threading.Thread(
            target=self._run_daily_memory_rollup_worker,
            args=(force, target_date),
            daemon=True,
        ).start()

    def _run_daily_memory_rollup_worker(self, force: bool = False, target_date: str | datetime.date | None = None):
        try:
            now = datetime.datetime.now()
            rollup_date = now.date()
            if target_date is not None:
                try:
                    rollup_date = target_date if isinstance(target_date, datetime.date) else datetime.date.fromisoformat(str(target_date))
                except Exception:
                    logging.warning('Daily memory rollup received invalid target date: %r', target_date)
                    rollup_date = now.date()
            if rollup_date > now.date():
                logging.info('Daily memory rollup skipped: target date %s is in the future.', rollup_date.isoformat())
                return
            rollup_day = rollup_date.isoformat()
            store = load_settings_store()
            globals_store = store.get('globals', {})
            if rollup_date == now.date() and not force and (now.hour < 23 or (now.hour == 23 and now.minute < 30)):
                logging.info('Daily memory rollup skipped: current day cutoff has not been reached.')
                return
            if str(globals_store.get('memory_last_rollup_date', '')).strip() == rollup_day:
                logging.info('Daily memory rollup skipped: %s already processed.', rollup_day)
                return

            retention_days = int(globals_store.get('memory_retention_days', 30) or 30)

            summaries = []
            for record in list_conversation_records():
                updated_at = str(record.get('updated_at', '')).strip()
                if not updated_at:
                    continue
                try:
                    updated_dt = datetime.datetime.fromisoformat(updated_at)
                except Exception:
                    continue
                if updated_dt.date().isoformat() != rollup_day:
                    continue
                summary = str(record.get('memory', {}).get('running_summary', '')).strip()
                if not summary:
                    messages = record.get('messages', []) if isinstance(record.get('messages', []), list) else []
                    if messages:
                        try:
                            summary = render_chat_history_plaintext(messages[-8:]).strip()[:4000]
                        except Exception:
                            summary = ''
                if summary:
                    summaries.append(summary)
            logging.info('Daily memory rollup %s found %d conversation summaries.', rollup_day, len(summaries))

            profile = load_active_settings_profile()
            api_key = str(profile.get('api_key', '')).strip()
            endpoint = profile_runtime_base_url(profile)
            model = str(profile.get('model', '')).strip()
            try:
                timeout = int(profile.get('timeout', 60) or 60)
            except (TypeError, ValueError):
                timeout = 60

            daily_note = ''
            if summaries and api_key and model:
                try:
                    client = create_openai_client(api_key, endpoint, timeout)
                    rollup_messages = [
                        {
                            'role': 'system',
                            'content': (
                                'You create one concise daily memory note about the user. '
                                'Based only on the provided conversation summaries, extract the most important '
                                'details that should be remembered later. Include not only stable facts and current '
                                'status, but also user preferences, explicit requirements, repeated constraints, '
                                'working-style expectations, and how the user wants tasks or answers handled. '
                                'Prioritize instructions or preferences that could affect future responses or product behavior. '
                                'Return one short memory note only. If there is nothing worth remembering, return an empty response.'
                            ),
                        },
                        {
                            'role': 'user',
                            'content': 'Today conversation summaries:\n\n' + '\n\n'.join(f'- {summary}' for summary in summaries),
                        },
                    ]
                    response = create_chat_completion(
                        client,
                        endpoint=endpoint,
                        model=model,
                        messages=rollup_messages,
                        stream=False,
                    )
                    daily_note = (response.choices[0].message.content or '').strip()
                except Exception:
                    daily_note = ''

            # The LLM call above can take minutes: apply the note to the CURRENT
            # memory items (items edited/added meanwhile survive) and write only
            # the two keys the rollup owns.
            def apply_rollup(fresh_store):
                fresh_globals = fresh_store['globals']
                updated_items = []
                for item in normalize_memory_item_records(fresh_globals.get('memory_items', [])):
                    if item.get('kind') == 'daily' and str(item.get('source_date', '')).strip() == rollup_day:
                        continue
                    updated_items.append(item)
                if daily_note:
                    updated_items.append(
                        {
                            'text': daily_note,
                            'created_at': now.isoformat(timespec='seconds'),
                            'kind': 'daily',
                            'source_date': rollup_day,
                        }
                    )
                fresh_globals['memory_items'] = prune_memory_item_records(updated_items, retention_days, now=now)
                fresh_globals['memory_last_rollup_date'] = rollup_day

            update_settings_store(apply_rollup)
            if daily_note:
                logging.info('Daily memory rollup %s wrote a daily note.', rollup_day)
            else:
                logging.info('Daily memory rollup %s completed with no daily note.', rollup_day)
        finally:
            self._daily_memory_rollup_running = False

    def _settings_panel_shown_rect(self):
        panel_w = self.settings_panel.width()
        panel_h = self.settings_panel.height()
        x = max(0, (self.qw3.width() - panel_w) // 2)
        y = max(24, (self.qw3.height() - panel_h) // 2)
        return QRect(
            x,
            y,
            panel_w,
            panel_h,
        )

    def _settings_panel_hidden_rect(self):
        shown = self._settings_panel_shown_rect()
        return QRect(shown.x(), self.qw3.height() + 24, shown.width(), shown.height())

    def _update_settings_overlay_geometry(self):
        if not hasattr(self, '_settings_scrim'):
            return
        qw3_pos = self.qw3.pos()
        self._settings_trigger_btn.setGeometry(
            qw3_pos.x() + 20,
            qw3_pos.y() + max(20, self.qw3.height() - self._settings_trigger_band_h),
            max(0, self.qw3.width() - 40),
            self._settings_trigger_band_h,
        )
        self._settings_trigger_btn.raise_()
        self._settings_scrim.setGeometry(self.qw3.rect())
        if self._settings_panel_visible:
            self.settings_panel.setGeometry(self._settings_panel_shown_rect())
        else:
            self.settings_panel.setGeometry(self._settings_panel_hidden_rect())

    def _update_history_overlay_geometry(self):
        if not hasattr(self, '_history_scrim'):
            return
        qw3_pos = self.qw3.pos()
        edge_gap = max(0, int(getattr(self, 'EDGE_AUTO_HIDE_PEEK_PX', 2)))
        self._history_trigger_btn.setGeometry(
            qw3_pos.x() + edge_gap,
            qw3_pos.y() + 18,
            max(0, 24 - edge_gap),
            max(0, self.qw3.height() - 36),
        )
        self._history_trigger_btn.raise_()
        self._history_scrim.setGeometry(self.qw3.rect())
        if self._history_panel_visible:
            self.history_panel.setGeometry(self._history_panel_shown_rect())
        else:
            self.history_panel.setGeometry(self._history_panel_hidden_rect())

    def _update_links_overlay_geometry(self):
        if not hasattr(self, '_links_scrim'):
            return
        # URL 列表的触发区在底部输入行上方的缝隙（对话区与 pill bar 之间），
        # 横向铺满输入行宽度；面板改为从底部滑入（见 _links_panel_hidden_rect）。
        bar = getattr(self, '_assistant_bar', None)
        if bar is not None:
            bar_top_left = bar.mapTo(self, QPoint(0, 0))
            band_h = 14
            self._links_trigger_btn.setGeometry(
                bar_top_left.x(),
                max(0, bar_top_left.y() - band_h),
                max(0, bar.width()),
                band_h,
            )
        self._links_trigger_btn.raise_()
        self._links_scrim.setGeometry(self.qw3.rect())
        if self._links_panel_visible:
            self.links_panel.setGeometry(self._links_panel_shown_rect())
        else:
            self.links_panel.setGeometry(self._links_panel_hidden_rect())

    def _terminal_history_panel_shown_rect(self, panel=None):
        panel = panel or self._terminal_history_panel_for_active_session()
        panel_w = panel.width()
        panel_h = panel.height()
        x = max(0, (self.qw3.width() - panel_w) // 2)
        y = max(24, (self.qw3.height() - panel_h) // 2)
        return QRect(x, y, panel_w, panel_h)

    def _terminal_history_panel_hidden_rect(self, panel=None):
        shown = self._terminal_history_panel_shown_rect(panel)
        return QRect(-shown.width() - 24, shown.y(), shown.width(), shown.height())

    def _terminal_favorites_panel_shown_rect(self):
        panel_w = self.terminal_favorites_panel.width()
        panel_h = self.terminal_favorites_panel.height()
        x = max(0, (self.qw3.width() - panel_w) // 2)
        y = max(24, (self.qw3.height() - panel_h) // 2)
        return QRect(x, y, panel_w, panel_h)

    def _terminal_favorites_panel_hidden_rect(self):
        shown = self._terminal_favorites_panel_shown_rect()
        return QRect(self.qw3.width() + 24, shown.y(), shown.width(), shown.height())

    def _can_show_terminal_side_triggers(self) -> bool:
        return (
            self.stacked_widget.currentIndex() == TAB_TERMINAL
            and not self._settings_panel_visible
            and not self._outputs_panel_visible
            and not self._terminal_history_panel_visible
            and not self._terminal_favorites_panel_visible
        )

    def _active_terminal_session_kind(self) -> str:
        terminal = getattr(self, 'terminal_widget', None)
        if terminal is not None and hasattr(terminal, 'current_session_kind'):
            try:
                return terminal.current_session_kind()
            except Exception:
                return 'terminal'
        return 'terminal'

    def _terminal_history_panel_for_active_session(self):
        if self._active_terminal_session_kind() in ('codex', 'claude', 'claude_tui') and hasattr(self, 'agent_cli_history_panel'):
            return self.agent_cli_history_panel
        return self.terminal_history_panel

    def _show_terminal_side_triggers(self):
        if not self._can_show_terminal_side_triggers():
            self._hide_terminal_side_triggers()
            return
        self._terminal_history_trigger_btn.show()
        self._terminal_history_trigger_btn.raise_()
        if self._active_terminal_session_kind() == 'terminal':
            self._terminal_favorites_trigger_btn.show()
            self._terminal_favorites_trigger_btn.raise_()
        else:
            self._terminal_favorites_trigger_btn.hide()

    def _hide_terminal_side_triggers(self):
        if hasattr(self, '_terminal_history_trigger_btn'):
            self._terminal_history_trigger_btn.hide()
        if hasattr(self, '_terminal_favorites_trigger_btn'):
            self._terminal_favorites_trigger_btn.hide()

    def _update_terminal_history_overlay_geometry(self):
        if not hasattr(self, '_terminal_history_scrim'):
            return
        edge_gap = max(0, int(getattr(self, 'EDGE_AUTO_HIDE_PEEK_PX', 2)))
        width = int(getattr(self, '_terminal_side_trigger_w', 28))
        self._terminal_history_trigger_btn.setGeometry(
            edge_gap,
            18,
            max(0, width - edge_gap),
            max(0, self.qw3.height() - 36),
        )
        self._terminal_history_trigger_btn.raise_()
        self._terminal_history_scrim.setGeometry(self.qw3.rect())
        active_panel = self._terminal_history_panel_for_active_session()
        if hasattr(self, 'agent_cli_history_panel'):
            if self._terminal_history_panel_visible and active_panel is self.agent_cli_history_panel:
                self.agent_cli_history_panel.setGeometry(self._terminal_history_panel_shown_rect(self.agent_cli_history_panel))
            else:
                self.agent_cli_history_panel.setGeometry(self._terminal_history_panel_hidden_rect(self.agent_cli_history_panel))
        if self._terminal_history_panel_visible and active_panel is self.terminal_history_panel:
            self.terminal_history_panel.setGeometry(self._terminal_history_panel_shown_rect(self.terminal_history_panel))
        else:
            self.terminal_history_panel.setGeometry(self._terminal_history_panel_hidden_rect(self.terminal_history_panel))
        if self._terminal_history_panel_visible:
            self._raise_terminal_history_overlay()

    def _raise_terminal_history_overlay(self):
        if not hasattr(self, '_terminal_history_scrim'):
            return
        active_panel = getattr(self, '_terminal_history_active_panel', None) or self._terminal_history_panel_for_active_session()
        try:
            self._terminal_history_scrim.raise_()
            active_panel.raise_()
        except Exception:
            pass

    def _update_terminal_favorites_overlay_geometry(self):
        if not hasattr(self, '_terminal_favorites_scrim'):
            return
        edge_gap = max(0, int(getattr(self, 'EDGE_AUTO_HIDE_PEEK_PX', 2)))
        width = int(getattr(self, '_terminal_side_trigger_w', 28))
        self._terminal_favorites_trigger_btn.setGeometry(
            max(0, self.qw3.width() - width),
            18,
            max(0, width - edge_gap),
            max(0, self.qw3.height() - 36),
        )
        self._terminal_favorites_trigger_btn.raise_()
        self._terminal_favorites_scrim.setGeometry(self.qw3.rect())
        if self._terminal_favorites_panel_visible:
            self.terminal_favorites_panel.setGeometry(self._terminal_favorites_panel_shown_rect())
        else:
            self.terminal_favorites_panel.setGeometry(self._terminal_favorites_panel_hidden_rect())

    def _copy_plain_text_to_clipboard(self, text: str):
        value = str(text or '')
        if value:
            QApplication.clipboard().setText(value)

    def _set_terminal_input_from_panel(self, command: str, append: bool = False):
        command = str(command or '').strip()
        if not command:
            return
        self._select_main_tab(TAB_TERMINAL)
        terminal = getattr(self, 'terminal_widget', None)
        input_line = getattr(terminal, 'input_line', None) if terminal is not None else None
        if input_line is None:
            return
        if append:
            current = str(input_line.text() or '')
            cursor_pos = max(0, input_line.cursorPosition())
            prefix = current[:cursor_pos]
            suffix = current[cursor_pos:]
            sep_left = ' ' if prefix and not prefix[-1].isspace() else ''
            sep_right = ' ' if suffix and not suffix[:1].isspace() else ''
            merged = prefix + sep_left + command + sep_right + suffix
            input_line.setText(merged)
            input_line.setCursorPosition(len(prefix + sep_left + command))
        else:
            input_line.setText(command)
            input_line.end(False)
        input_line.setFocus()
        if self._terminal_history_panel_visible:
            self.hide_terminal_history_panel()
        if self._terminal_favorites_panel_visible:
            self.hide_terminal_favorites_panel()

    def _refresh_terminal_history_panel(self):
        if hasattr(self, 'terminal_history_panel'):
            self.terminal_history_panel.set_sources(
                parse_zsh_history_records(),
                load_terminal_history_records(),
            )

    def _on_terminal_session_changed(self, session_id: str):
        if self.stacked_widget.currentIndex() == TAB_TERMINAL:
            if self._terminal_history_panel_visible:
                self.hide_terminal_history_panel()
            if self._terminal_favorites_panel_visible and self._active_terminal_session_kind() != 'terminal':
                self.hide_terminal_favorites_panel()
            self._show_terminal_side_triggers()

    def _open_agent_cli_history_record(self, provider_kind: str, record: dict):
        if not isinstance(record, dict):
            return
        self._select_main_tab(TAB_TERMINAL)
        terminal = getattr(self, 'terminal_widget', None)
        if terminal is not None and hasattr(terminal, 'open_agent_history_record'):
            terminal.open_agent_history_record(provider_kind, record)
        if self._terminal_history_panel_visible:
            self.hide_terminal_history_panel()

    def _delete_terminal_history_record(self, record_id: str):
        record_id = str(record_id or '').strip()
        if not record_id:
            return
        records = [
            item for item in load_terminal_history_records()
            if str(item.get('id', '') or '').strip() != record_id
        ]
        save_terminal_history_records(records)
        self._refresh_terminal_history_panel()

    def _refresh_terminal_favorites_panel(self):
        if hasattr(self, 'terminal_favorites_panel'):
            self.terminal_favorites_panel.set_favorites(load_terminal_favorite_records())

    def _add_terminal_favorite_from_text(self, text: str):
        command = str(text or '').strip()
        if command and upsert_terminal_favorite(command):
            self._refresh_terminal_favorites_panel()

    def _delete_terminal_favorite(self, record_id: str):
        record_id = str(record_id or '').strip()
        if not record_id:
            return
        records = [item for item in load_terminal_favorite_records() if str(item.get('id', '')).strip() != record_id]
        save_terminal_favorite_records(records)
        self._refresh_terminal_favorites_panel()

    def _edit_terminal_favorite(self, record_id: str):
        record_id = str(record_id or '').strip()
        if not record_id:
            return
        records = load_terminal_favorite_records()
        current = None
        current_index = -1
        for index, record in enumerate(records):
            if str(record.get('id', '')).strip() == record_id:
                current = record
                current_index = index
                break
        if current is None:
            return
        dialog = TerminalFavoriteEditDialog(
            caption=str(current.get('caption', '') or ''),
            command=str(current.get('command', '') or ''),
            parent=self,
        )
        if dialog.exec() != QDialog.DialogCode.Accepted:
            return
        command = dialog.command()
        if not command:
            return
        updated = dict(current)
        updated['caption'] = dialog.caption()
        updated['command'] = command
        updated['updated_at'] = datetime.datetime.now().isoformat(timespec='seconds')
        normalized = normalize_terminal_favorite_record(updated)
        if normalized is None:
            return
        records[current_index] = normalized
        save_terminal_favorite_records(records)
        self._refresh_terminal_favorites_panel()

    def show_terminal_history_panel(self):
        if self.stacked_widget.currentIndex() != TAB_TERMINAL or self._terminal_history_panel_visible:
            return
        if self._settings_panel_visible:
            self.hide_settings_panel()
        if self._outputs_panel_visible:
            self.hide_outputs_panel()
        if self._terminal_favorites_panel_visible:
            self.hide_terminal_favorites_panel()
        active_kind = self._active_terminal_session_kind()
        active_panel = self._terminal_history_panel_for_active_session()
        if active_kind in ('codex', 'claude', 'claude_tui'):
            provider_kind = 'claude' if active_kind == 'claude_tui' else active_kind
            provider = AgentCliHistoryProvider(provider_kind)
            self.agent_cli_history_panel.set_provider(provider)
            self.terminal_history_panel.hide()
        else:
            self._refresh_terminal_history_panel()
            if hasattr(self, 'agent_cli_history_panel'):
                self.agent_cli_history_panel.hide()
        self._hide_terminal_side_triggers()
        self._outputs_trigger_btn.hide()
        self._settings_trigger_btn.hide()
        if self._terminal_history_panel_anim is not None:
            self._terminal_history_panel_anim.stop()
        if self._terminal_history_scrim_anim is not None:
            self._terminal_history_scrim_anim.stop()
        self._update_terminal_history_overlay_geometry()
        self._terminal_history_panel_visible = True
        self._terminal_history_active_panel = active_panel
        start_rect = self._terminal_history_panel_hidden_rect(active_panel)
        end_rect = self._terminal_history_panel_shown_rect(active_panel)
        self._terminal_history_scrim.show()
        self._terminal_history_scrim.raise_()
        active_panel.setGeometry(start_rect)
        active_panel.show()
        self._raise_terminal_history_overlay()
        QTimer.singleShot(0, self._raise_terminal_history_overlay)
        QTimer.singleShot(80, self._raise_terminal_history_overlay)
        self._terminal_history_scrim_opacity.setOpacity(0.0)
        self._terminal_history_panel_anim = QPropertyAnimation(active_panel, b'geometry', self)
        self._terminal_history_panel_anim.setDuration(260)
        self._terminal_history_panel_anim.setStartValue(start_rect)
        self._terminal_history_panel_anim.setEndValue(end_rect)
        self._terminal_history_panel_anim.setEasingCurve(QEasingCurve.Type.OutCubic)
        self._terminal_history_scrim_anim = QPropertyAnimation(self._terminal_history_scrim_opacity, b'opacity', self)
        self._terminal_history_scrim_anim.setDuration(220)
        self._terminal_history_scrim_anim.setStartValue(0.0)
        self._terminal_history_scrim_anim.setEndValue(1.0)
        self._terminal_history_scrim_anim.setEasingCurve(QEasingCurve.Type.OutCubic)
        self._terminal_history_panel_anim.start()
        self._terminal_history_scrim_anim.start()
        active_panel.search_input.setFocus()

