    # ── Agent 聊天收藏浮窗（右缘触发，样式与 terminal 收藏一致，配色随主题）──
    def _agent_favorites_panel_shown_rect(self):
        panel_w = self.agent_favorites_panel.width()
        panel_h = self.agent_favorites_panel.height()
        x = max(0, (self.qw3.width() - panel_w) // 2)
        y = max(24, (self.qw3.height() - panel_h) // 2)
        return QRect(x, y, panel_w, panel_h)

    def _agent_favorites_panel_hidden_rect(self):
        shown = self._agent_favorites_panel_shown_rect()
        return QRect(self.qw3.width() + 24, shown.y(), shown.width(), shown.height())

    def _update_agent_favorites_overlay_geometry(self):
        if not hasattr(self, '_agent_favorites_scrim'):
            return
        edge_gap = max(0, int(getattr(self, 'EDGE_AUTO_HIDE_PEEK_PX', 2)))
        width = int(getattr(self, '_terminal_side_trigger_w', 28))
        self._agent_favorites_trigger_btn.setGeometry(
            max(0, self.qw3.width() - width),
            18,
            max(0, width - edge_gap),
            max(0, self.qw3.height() - 36),
        )
        self._agent_favorites_trigger_btn.raise_()
        self._agent_favorites_scrim.setGeometry(self.qw3.rect())
        if self._agent_favorites_panel_visible:
            self.agent_favorites_panel.setGeometry(self._agent_favorites_panel_shown_rect())
        else:
            self.agent_favorites_panel.setGeometry(self._agent_favorites_panel_hidden_rect())
        rail = getattr(self, 'agent_question_rail', None)
        if rail is not None:
            rail.set_anchor(
                max(0, self.qw3.width() - width) - 2,
                self.qw3.height() // 2,
                max(120, int(self.qw3.height() * 0.6)),
            )
            rail.sync_visibility()

