    def pin_a_tab(self, target_geometry: QRect | None = None):
        SCREEN_WEIGHT = int(self.screen().availableGeometry().width())
        SCREEN_HEIGHT = int(self.screen().availableGeometry().height())
        x_center = 0
        y_center = 0
        if self.i % 2 == 1:
            accent = get_accent_color_hex()
            btna4.setChecked(True)
            self.drawing_layer.setVisible(self.stacked_widget.currentIndex() == TAB_API)
            self.pin_tab_row.setFixedHeight(12)
            self.pin_tab_row.setMaximumWidth(16777215)
            self.window_position_pin_button.set_diameter(12)
            self.window_close_button.set_diameter(12)
            self.btn_00.setText('')
            self.btn_00.setFixedHeight(10)
            self.btn_00.setMinimumWidth(0)
            self.btn_00.setMaximumWidth(16777215)
            self.btn_00.setStyleSheet(f'''
                        border: 1px outset grey;
                        background-color: {accent};
                        border-radius: 4px;
                        padding: 1px;
                        color: #FFFFFF''')
            self.qw3.setVisible(True)
            fit_screen = None
            if isinstance(target_geometry, QRect):
                fit_screen = QGuiApplication.screenAt(target_geometry.center())
            fit_avail = QRect((fit_screen or self.screen()).availableGeometry())
            self.setFixedSize(self.MAIN_WINDOW_WIDTH, self._main_window_fit_height(fit_avail))
            if isinstance(target_geometry, QRect):
                x_center = int(target_geometry.x())
                y_center = int(target_geometry.y())
            else:
                x_center = int((SCREEN_WEIGHT / 2) + (self.width() / 2))
                y_center = int((SCREEN_HEIGHT - self.height()) // 4 * 3)
                # On narrower (laptop) screens the formula above pushes the right side past
                # the edge; stop short of the right edge instead.
                max_x = fit_avail.right() - self.width() + 1 - self.MAIN_WINDOW_EXPAND_RIGHT_GAP
                x_center = max(fit_avail.left(), min(x_center, max_x))
            y_center = self._clamp_main_window_top(y_center, self.height(), fit_avail)
        if self.i % 2 == 0:
            btna4.setChecked(False)
            self.drawing_layer.setVisible(False)
            self.window_position_pin_button.hide()
            self.window_close_button.hide()
            self.pin_tab_row.setFixedSize(50, 50)
            self.window_position_pin_button.set_diameter(12)
            self.window_close_button.set_diameter(12)
            self.btn_00.setText('🥦')
            self.btn_00.setFixedSize(50, 50)
            self.btn_00.setStyleSheet('''
                        border: 1px outset grey;
                        background-color: #FFFFFF;
                        border-radius: 25px;
                        padding: 1px;
                        color: #000000''')
            self.qw3.setVisible(False)
            self.setFixedSize(50, 50)
            x_center = int(SCREEN_WEIGHT - self.width())
            y_center = int(SCREEN_HEIGHT - 50)

        self.move_window(x_center, y_center)
        self._refresh_pin_tab_edge_state(animated=True)
        self.show()
        # Collapse -> the guard inside this hides the side shelf; expand -> it shows
        # again (if there are running conversations) and repositions it.
        self._refresh_agent_conversation_shelf()
        self._schedule_background_vision_toast_relayout()

    def showhidedock(self):
        visible = action8.isChecked()
        write_text_file(SHOWHIDE_PATH, '1' if visible else '0')
        set_dock_icon_visible(visible, activate=visible)

    def sync_start_on_login_action(self, enabled: bool):
        action = globals().get('action10')
        if action is not None:
            with QSignalBlocker(action):
                action.setChecked(bool(enabled))
        settings_panel = getattr(self, 'settings_panel', None)
        checkbox = getattr(settings_panel, 'start_on_login_checkbox', None)
        if checkbox is not None:
            with QSignalBlocker(checkbox):
                checkbox.setChecked(bool(enabled))

    def toggle_start_on_login(self, checked: bool):
        enabled = bool(checked)
        try:
            set_start_on_login_enabled(enabled)
            update_settings_globals({'start_on_login': enabled})
            self.sync_start_on_login_action(enabled)
        except Exception as exc:
            actual = is_start_on_login_enabled()
            self.sync_start_on_login_action(actual)
            show_broccoli_message(self, _tr('Start on login'), _tr('Failed to update start on login: {exc}').format(exc=exc))

    def cleanlinebreak(self, a):  # 设置清除断行的基本代码块
        for i in range(10):
            a = a.replace('\r', ' ')
            a = a.replace('\n', ' ')
        a = a.replace('   ', ' ')
        a = a.replace('  ', ' ')
        return a

    def default_clean(self, a):  # 最基本功能块
        # 【共同块】不管是全中文/全英文/中英混排，都需要清除的不规范的符号与排版
        # 清除文档排版符号
        a = a.replace('\t', '')

        # 清除连续空格（如连续两个和三个空格）
        for i in range(10):
            a = a.replace('   ', ' ')
            a = a.replace('  ', ' ')
            a = a.replace('，，，', '，')
            a = a.replace('，，', '，')
            a = a.replace(',,,', ',')
            a = a.replace(',,', ',')

        # 清除那些引用标记（括号内为纯数字），如圈圈数字和方括号引用，同时由于方括号和六角括号混用较多，清理前后不搭的情况中的引用符号
        a = re.sub(r"\{(\s)*(\d+\s)*(\d)*?\}|\[(\s)*(\d+\s)*(\d)*?\]|〔(\s)*(\d+\s)*(\d)*?〕|﹝(\s)*(\d+\s)*(\d)*?﹞", "", a)
        a = re.sub(r"\[(\s)*(\d+\s)*(\d)*?〕|\[(\s)*(\d+\s)*(\d)*?﹞|〔(\s)*(\d+\s)*(\d)*?\]|〔(\s)*(\d+\s)*(\d)*?﹞|﹝(\s)*(\d+\s)*(\d)*?\]|﹝(\s)*(\d+\s)*(\d)*?〕", "", a)
        a = re.sub(r"（(\s)*(\d+\s)*(\d)*?）|\[(\s)*(\d+\s)*(\d)*?）|（(\s)*(\d+\s)*(\d)*?\]|（(\s)*(\d+\s)*(\d)*?】|【(\s)*(\d+\s)*(\d)*?）", "", a)
        a = re.sub(r"\((\s)*(\d+\s)*(\d)*?〕|\((\s)*(\d+\s)*(\d)*?﹞|〔(\s)*(\d+\s)*(\d)*?\)|﹝(\s)*(\d+\s)*(\d)*?\)|\((\s)*(\d+\s)*(\d)*?\)|\[(\s)*(\d+\s)*(\d)*?\)|\((\s)*(\d+\s)*(\d)*?\]", "", a)
        a = re.sub(u'\u24EA|[\u2460-\u2473]|[\u3251-\u325F]|[\u32B1-\u32BF]|[\u2776-\u277F]|\u24FF|[\u24EB-\u24F4]',
                   "", a)
        a = re.sub(r"\<(\s)*(\d+\s)*(\d)*?\>|\《(\s)*(\d+\s)*(\d)*?\》|\〈(\s)*(\d+\s)*(\d)*?\〉|\＜(\s)*(\d+\s)*(\d)*?\＞", "", a)
        a = re.sub(r"\<(\s)*(\d+\s)*(\d)*?\》|\<(\s)*(\d+\s)*(\d)*?\〉|\<(\s)*(\d+\s)*(\d)*?\＞",
                   "", a)
        a = re.sub(r"\《(\s)*(\d+\s)*(\d)*?\>|\《(\s)*(\d+\s)*(\d)*?\〉|\《(\s)*(\d+\s)*(\d)*?\＞",
                   "", a)
        a = re.sub(r"\〈(\s)*(\d+\s)*(\d)*?\>|\〈(\s)*(\d+\s)*(\d)*?\》|\〈(\s)*(\d+\s)*(\d)*?\＞",
                   "", a)
        a = re.sub(r"\＜(\s)*(\d+\s)*(\d)*?\>|\＜(\s)*(\d+\s)*(\d)*?\》|\＜(\s)*(\d+\s)*(\d)*?\〉",
                   "", a)
        a = a.replace('◎', '')
        a = a.replace('®', '')
        a = a.replace('*', '')

        # 错误标点纠正：将奇怪的弯引号换为正常的弯引号，为下面执行弯引号与直引号的清除提供条件
        a = a.replace('〞', '"')
        a = a.replace('〝', '"')

        # 错误标点纠正：将角分符号（′）替换为弯引号（若需要使用角分符号则不运行此条）
        a = a.replace('′', '‘')
        # 错误标点纠正：将角秒符号（″）替换为弯引号（若需要使用角秒符号则不运行此条）
        a = a.replace('″', '“')

        # 错误标点纠正1（两个同向单引号变成一个双引号<前>，改为前后弯双引号）
        pattern = re.compile('‘(.*?)“’')
        result = pattern.findall(a)
        for i in result:
            a = a.replace('‘{}“’'.format(i), '“{}”'.format(i))

        # 错误标点纠正2（两个同向单引号变成一个双引号<后>，改为前后弯双引号）
        p1 = '(?<=“).+?(?=’’)'
        pattern1 = re.compile(p1)
        result = pattern1.findall(a)
        for i in result:
            a = a.replace('“{}’’'.format(i), '“{}”'.format(i))

        # 错误标点纠正3（前后两个单引号变成一组双引号）
        pattern = re.compile('‘(.*?)’')
        result = pattern.findall(a)
        for i in result:
            a = a.replace('‘{}’'.format(i), '“{}”'.format(i))

        # 错误标点纠正4（两个同向双引号去掉一个<前>）
        pattern = re.compile('““(.*?)”')
        result = pattern.findall(a)
        for i in result:
            a = a.replace('““{}”'.format(i), '“{}”'.format(i))

        # 错误标点纠正5（两个同向双引号去掉一个<后>）
        p1 = '(?<=“).+?(?=””)'
        pattern1 = re.compile(p1)
        result = pattern1.findall(a)
        for i in result:
            a = a.replace('“{}””'.format(i), '“{}”'.format(i))

        # 错误标点纠正6（两组双引号变成一组双引号）
        pattern = re.compile('““(.*?)””')
        result = pattern.findall(a)
        for i in result:
            a = a.replace('““{}””'.format(i), '“{}”'.format(i))

        # 错误标点纠正7（前直单引号<前>，后弯双引号<后>，改为前后弯双引号）
        pattern = re.compile("'(.*?)””")
        result = pattern.findall(a)
        for i in result:
            a = a.replace("'{}””".format(i), '“{}”'.format(i))

        # 错误标点纠正8（前直双引号<前>，后弯双引号<后>，改为前后弯双引号）
        pattern = re.compile('"(.*?)”')
        result = pattern.findall(a)
        for i in result:
            a = a.replace('"{}”'.format(i), '“{}”'.format(i))

        # 错误标点纠正9（前弯双引号<前>，后直单引号<后>，改为前后弯双引号）
        p1 = "(?<=“).+?(?=')"
        pattern1 = re.compile(p1)
        result = pattern1.findall(a)
        for i in result:
            a = a.replace("“{}'".format(i), '“{}”'.format(i))

        # 错误标点纠正10（前弯双引号<前>，后直双引号<后>，改为前后弯双引号）
        p1 = '(?<=“).+?(?=")'
        pattern1 = re.compile(p1)
        result = pattern1.findall(a)
        for i in result:
            a = a.replace('“{}"'.format(i), '“{}”'.format(i))

        # 将成对的直双引号改为成对的弯双引号
        pattern = re.compile(r'"(.*?)"')
        result = pattern.findall(a)
        for i in result:
            a = a.replace('"{}"'.format(i), '“{}”'.format(i))

        # 将成对的直单引号改为成对的弯单引号
        pattern = re.compile(r"'(.*?)'")
        result = pattern.findall(a)
        for i in result:
            a = a.replace("'{}'".format(i), '‘{}’'.format(i))

        # 对文段进行再次多余部分的清洗
        # 错误标点纠正1（两个同向单引号变成一个双引号<前>，改为前后弯双引号）
        pattern = re.compile('‘(.*?)“’')
        result = pattern.findall(a)
        for i in result:
            a = a.replace('‘{}“’'.format(i), '“{}”'.format(i))

        # 错误标点纠正2（两个同向单引号变成一个双引号<后>，改为前后弯双引号）
        p1 = '(?<=“).+?(?=’’)'
        pattern1 = re.compile(p1)
        result = pattern1.findall(a)
        for i in result:
            a = a.replace('“{}’’'.format(i), '“{}”'.format(i))

        # 错误标点纠正3（前后两个单引号变成一组双引号）
        pattern = re.compile('‘(.*?)’')
        result = pattern.findall(a)
        for i in result:
            a = a.replace('‘{}’'.format(i), '“{}”'.format(i))

