    def _center_child_dialog(self, dialog: QDialog):
        dialog.adjustSize()
        parent_window = self.window()
        parent_geometry = parent_window.frameGeometry() if parent_window is not None else self.frameGeometry()
        dialog_geometry = dialog.frameGeometry()
        dialog_geometry.moveCenter(parent_geometry.center())
