    def current_profile_names(self):
        return [profile['name'] for profile in self.settings_store['profiles']]

    def get_profile_by_name(self, profile_name: str):
        for profile in self.settings_store['profiles']:
            if profile['name'] == profile_name:
                return profile
        return None

    def _profiles_sorted_by_name(self):
        """按名称（不区分大小写）排序的 profiles 副本，只给下拉/清单展示用。
        故意不改 settings_store['profiles'] 本身——profiles[0] 在别处当“首个/
        默认回退”用（删除后回落激活档案、legacy 文件同步、找不到名字的兜底），
        重排存储会连带改掉那层语义，所以这里只排显示、不排存储。"""
        return sorted(
            self.settings_store.get('profiles', []),
            key=lambda profile: str((profile or {}).get('name', '') or '').casefold(),
        )

    def refresh_external_targets_label(self):
        label = getattr(self, 'external_targets_label', None)
        if label is None:
            return
        window = self.window()
        api_names = [
            str(profile.get('name', '') or '').strip()
            for profile in self._profiles_sorted_by_name()
            if str(profile.get('name', '') or '').strip()
        ]
        grouped = {'Web': [], 'Localhost': [], 'Terminal': []}
        if hasattr(window, '_collect_external_targets'):
            try:
                for target in window._collect_external_targets():
                    group = str((target or {}).get('group', '') or '').strip() or 'Web'
                    alias = str((target or {}).get('alias', '') or '').strip()
                    title = str((target or {}).get('label', '') or '').strip() or alias
                    capability = str((target or {}).get('capability', '') or '').strip()
                    if alias:
                        suffix = f' ({capability})' if capability and capability != 'chat' else ''
                        grouped.setdefault(group, []).append(f'@{alias} - {title}{suffix}')
            except Exception:
                pass
        parts = []
        if api_names:
            parts.append('API: ' + '; '.join(api_names[:8]))
        for group in ('Web', 'Localhost', 'Terminal'):
            items = grouped.get(group) or []
            if items:
                parts.append(_tr(group) + ': ' + '; '.join(items[:8]))
        label.setText(_tr('Profile sources:\n') + ('\n'.join(parts) if parts else _tr('none')))

    def refresh_profile_selector(self, selected_name: str | None = None):
        self._refreshing_profiles = True
        self.profile_selector.clear()
        for profile in self._profiles_sorted_by_name():
            self.profile_selector.addItem(profile['name'], profile['name'])
        if selected_name is None:
            selected_name = self.settings_store.get('active_profile', '')
        index = self.profile_selector.findData(selected_name)
        if index >= 0:
            self.profile_selector.setCurrentIndex(index)
        self._refreshing_profiles = False
        self.refresh_embedding_profile_selector(self.settings_store.get('globals', {}).get('embedding_profile', ''))
        self.refresh_specialized_profile_selectors(self.settings_store.get('globals', {}).get('specialized_profiles', {}))
        self.refresh_specialized_execution_selectors(self.settings_store.get('globals', {}).get('specialized_execution_modes', {}))
        self.refresh_browser_use_profile_selector(self.settings_store.get('globals', {}).get('browser_use_profile', ''))
        self.refresh_computer_use_profile_selector()
        self.refresh_final_answer_profile_selector('')
        self.refresh_external_targets_label()
        if hasattr(self, 'background_vision_profile_list_widget'):
            self.refresh_background_vision_profile_list(
                self.settings_store.get('globals', {}).get('background_vision_profile_names', [])
            )

