    @staticmethod
    def _computer_use_qscreen_descriptor(screen, ordinal: int) -> dict | None:
        """Build a UI-only fallback when CoreGraphics discovery is unavailable.

        Runtime config resolution deliberately does not use this fallback: a
        selected physical display must be proven from WindowServer-compatible
        CoreGraphics bounds before a Computer Use task starts.
        """
        try:
            geometry = screen.geometry()
            bounds = normalize_computer_use_display_bounds({
                'x': geometry.x(), 'y': geometry.y(),
                'width': geometry.width(), 'height': geometry.height(),
            })
            if bounds is None:
                return None
            name = str(screen.name() or '').strip()
            manufacturer = str(screen.manufacturer() or '').strip()
            model = str(screen.model() or '').strip()
            serial = str(screen.serialNumber() or '').strip()
            identity = '|'.join((serial, manufacturer, model, name))
            # Geometry only disambiguates serial-less identical displays. If
            # their layout changes, the old explicit choice becomes unavailable
            # instead of silently binding to a different physical panel.
            if not serial:
                identity += '|' + json.dumps(bounds, sort_keys=True, separators=(',', ':'))
            digest = hashlib.sha256(identity.encode('utf-8')).hexdigest()[:24]
            stable_id = 'qt:' + digest
            primary = QGuiApplication.primaryScreen()
            return {
                'stable_id': stable_id,
                'runtime_id': None,
                'bounds': bounds,
                'is_main': screen is primary,
                'is_builtin': False,
                'scale_factor': float(screen.devicePixelRatio() or 1.0),
                'label': name or f'Display {ordinal + 1}',
                'qt_fallback': True,
            }
        except Exception:
            return None

    def _computer_use_display_descriptors_for_ui(self) -> list[dict]:
        physical = [dict(item) for item in enumerate_computer_use_displays() if isinstance(item, dict)]
        qt_descriptors = []
        for ordinal, screen in enumerate(QGuiApplication.screens() or []):
            descriptor = self._computer_use_qscreen_descriptor(screen, ordinal)
            if descriptor is not None:
                qt_descriptors.append(descriptor)
        if not physical:
            return qt_descriptors
        # CoreGraphics owns identity/bounds. QScreen contributes only the
        # human-readable display name when both APIs report the same rectangle.
        for item in physical:
            bounds = normalize_computer_use_display_bounds(item.get('bounds'))
            for qt_item in qt_descriptors:
                if bounds == normalize_computer_use_display_bounds(qt_item.get('bounds')):
                    if str(qt_item.get('label', '') or '').strip():
                        item['label'] = str(qt_item['label'])
                    break
        return physical

    @staticmethod
    def _computer_use_display_item_label(descriptor: dict) -> str:
        label = str(descriptor.get('label', '') or descriptor.get('stable_id', '') or '') or _tr('Display')
        # Stored label_hint stays English; translate the generated fallback names only here.
        if label == 'Built-in Display':
            label = _tr('Built-in Display')
        elif re.fullmatch(r'Display \d+', label):
            label = _tr('Display {number}').format(number=label[len('Display '):])
        bounds = normalize_computer_use_display_bounds(descriptor.get('bounds')) or {}
        width = bounds.get('width', '?')
        height = bounds.get('height', '?')
        x = bounds.get('x', '?')
        y = bounds.get('y', '?')
        if descriptor.get('is_main'):
            scope = _tr('AX / Window / Full desktop')
            main = _tr(' — Main')
        else:
            scope = _tr('AX / Window only')
            main = ''
        return _tr('{label}{main} — {width}×{height} at ({x}, {y}) — {scope}').format(
            label=label, main=main, width=width, height=height, x=x, y=y, scope=scope)

    def refresh_computer_use_display_selector(self, selected_setting=None):
        if not hasattr(self, 'computer_use_target_display_combo'):
            return
        if selected_setting is None:
            selected_setting = self.computer_use_target_display_combo.currentData()
        selected = normalize_computer_use_target_display(selected_setting)
        descriptors = self._computer_use_display_descriptors_for_ui()
        self._computer_use_display_descriptors = descriptors
        combo = self.computer_use_target_display_combo
        combo.blockSignals(True)
        try:
            combo.clear()
            combo.addItem(_tr('Automatic (follow target window)'), default_computer_use_target_display())
            selected_index = 0
            for descriptor in descriptors:
                stable_id = str(descriptor.get('stable_id', '') or '').strip()
                bounds = normalize_computer_use_display_bounds(descriptor.get('bounds'))
                if not stable_id or bounds is None:
                    continue
                label = str(descriptor.get('label', '') or stable_id).strip()
                setting = {
                    'mode': TARGET_DISPLAY_EXPLICIT,
                    'stable_id': stable_id,
                    'label_hint': label,
                    'last_geometry': bounds,
                }
                combo.addItem(self._computer_use_display_item_label(descriptor), setting)
                if (selected.get('mode') == TARGET_DISPLAY_EXPLICIT
                        and selected.get('stable_id') == stable_id):
                    selected_index = combo.count() - 1
            if selected.get('mode') == TARGET_DISPLAY_EXPLICIT and selected_index == 0:
                missing_label = str(
                    selected.get('label_hint', '') or selected.get('stable_id', '') or _tr('Selected display')
                )
                combo.addItem(
                    _tr('Unavailable — {label} (reconnect or choose another display)').format(label=missing_label),
                    selected,
                )
                selected_index = combo.count() - 1
            combo.setCurrentIndex(selected_index)
        finally:
            combo.blockSignals(False)

    def _connect_computer_use_screen_geometry_signal(self, screen):
        if screen is None:
            return
        key = id(screen)
        if key in self._computer_use_display_signal_screens:
            return
        self._computer_use_display_signal_screens.add(key)
        try:
            screen.geometryChanged.connect(self._on_computer_use_screens_changed)
        except Exception:
            pass

    def _connect_computer_use_display_signals(self):
        gui_app = QGuiApplication.instance()
        if gui_app is None:
            return
        for signal_name in ('screenAdded', 'screenRemoved', 'primaryScreenChanged'):
            try:
                getattr(gui_app, signal_name).connect(self._on_computer_use_screens_changed)
            except Exception:
                pass
        for screen in QGuiApplication.screens() or []:
            self._connect_computer_use_screen_geometry_signal(screen)

    def _on_computer_use_screens_changed(self, *_args):
        for screen in QGuiApplication.screens() or []:
            self._connect_computer_use_screen_geometry_signal(screen)
        if hasattr(self, 'computer_use_target_display_combo'):
            self.refresh_computer_use_display_selector(
                self.computer_use_target_display_combo.currentData()
            )

    def refresh_final_answer_profile_selector(self, selected_name: str | None = None):
        # Default chat（最终答复）候选列表：只列普通 profile（不含 @/& 目标），
        # 与 embedding/browser_use 一样单独填充。第一顺位 = default chat 模型，
        # 其余顺位供运行时 429/额度类失败时逐顺位回退。
        if not hasattr(self, 'final_answer_profile_combo'):
            return
        selected_name = str(selected_name or '').strip()
        self.final_answer_profile_combo.blockSignals(True)
        self.final_answer_profile_combo.clear()
        self.final_answer_profile_combo.addItem(_tr('Default active profile'), '')
        for profile in self._profiles_sorted_by_name():
            self.final_answer_profile_combo.addItem(profile['name'], profile['name'])
        index = self.final_answer_profile_combo.findData(selected_name)
        self.final_answer_profile_combo.setCurrentIndex(index if index >= 0 else 0)
        if hasattr(self.final_answer_profile_combo, 'set_ranking'):
            stored = get_specialized_profile_candidates_from_store(self.settings_store).get('final_answer') or []
            self.final_answer_profile_combo.set_ranking(stored or ([selected_name] if selected_name else []))
        self.final_answer_profile_combo.blockSignals(False)

    def _open_custom_services_dialog(self):
        dialog = CustomServicesDialog(self, dark=bool(self._force_dark or is_dark_theme(app)))
        dialog.exec()
        # 浮窗直接写磁盘 store——把面板的内存副本同步过来，否则下拉读到
        # 旧清单,且随后的 Save 会用旧副本覆盖磁盘。
        self.settings_store.setdefault('globals', {})['custom_services'] = get_custom_services_from_store()
        # 刷新专项能力下拉，保留当前 UI 上的选择（含未保存的候选排序；
        # router 也要带上，否则这次刷新会把它的排序砍成单项）。
        current = {'router': str(self.router_profile_combo.currentData() or '')}
        current_rankings = {}
        if hasattr(self.router_profile_combo, 'ranking'):
            current_rankings['router'] = self.router_profile_combo.ranking()
        for capability, combo in self.specialized_profile_combos.items():
            current[capability] = str(combo.currentData() or '')
            if hasattr(combo, 'ranking'):
                current_rankings[capability] = combo.ranking()
        self.refresh_specialized_profile_selectors(current, candidates=current_rankings)

    def refresh_specialized_profile_selectors(self, selected_profiles: dict | None = None,
                                              candidates: dict | None = None):
        selected_profiles = normalize_specialized_profiles(selected_profiles)
        candidates_by_capability = (
            normalize_specialized_profile_candidates(candidates)
            if candidates is not None
            else get_specialized_profile_candidates_from_store(self.settings_store)
        )
        all_combos = {'router': self.router_profile_combo, **self.specialized_profile_combos}
        external_profile_names = []
        window = self.window()
        # 设置里列 @target 全集（含未打开的）——可用性是运行时的事。
        if hasattr(window, '_collect_all_external_target_names'):
            try:
                external_profile_names = list(window._collect_all_external_target_names())
            except Exception:
                external_profile_names = []
        elif hasattr(window, '_collect_external_targets'):
            try:
                for target in window._collect_external_targets():
                    alias = str((target or {}).get('alias', '') or '').strip()
                    if alias:
                        name = f'@{alias}'
                        if name not in external_profile_names:
                            external_profile_names.append(name)
            except Exception:
                external_profile_names = []
        custom_services = get_custom_services_from_store(self.settings_store)
        for key, combo in all_combos.items():
            combo.blockSignals(True)
            combo.clear()
            combo.addItem(_tr('None'), '')
            for profile in self._profiles_sorted_by_name():
                combo.addItem(profile['name'], profile['name'])
            for name in external_profile_names:
                combo.addItem(name, name)
            # 自定义服务（'&名称'）排在 @target 之后，且只出现在与其 kind
            # 匹配的能力下拉里（搜索服务只进 web_search，不污染其他能力）。
            for service in custom_services:
                if not service.get('enabled', True):
                    continue
                allowed = CUSTOM_SERVICE_KIND_CAPABILITIES.get(str(service.get('kind', '') or ''), set())
                if key not in allowed:
                    continue
                service_ref = CUSTOM_SERVICE_PREFIX + str(service.get('name', '') or '')
                combo.addItem(service_ref, service_ref)
            selected_name = str(selected_profiles.get(key, '')).strip()
            index = combo.findData(selected_name)
            combo.setCurrentIndex(index if index >= 0 else 0)
            if hasattr(combo, 'set_ranking'):
                ranked = candidates_by_capability.get(key) or ([selected_name] if selected_name else [])
                # 存储名可能是同站的另一个叫法（推导名 vs 打开后的 tab
                # 名）——按主机名翻译成当前目录里的现名，防排序丢项。
                if hasattr(window, '_resolve_external_candidate_names'):
                    try:
                        ranked = window._resolve_external_candidate_names(ranked)
                    except Exception:
                        pass
                combo.set_ranking(ranked)
            combo.blockSignals(False)
        self._update_specialized_external_target_controls()

    def _update_specialized_external_target_controls(self):
        for capability, profile_combo in getattr(self, 'specialized_profile_combos', {}).items():
            execution_combo = getattr(self, 'specialized_execution_combos', {}).get(capability)
            if execution_combo is None:
                continue
            profile_name = str(profile_combo.currentData() or profile_combo.currentText() or '').strip()
            # @target 与 &自定义服务都自带执行方式，禁用执行模式下拉。
            execution_combo.setEnabled(
                not profile_name.startswith('@')
                and not profile_name.startswith(CUSTOM_SERVICE_PREFIX)
            )

    def refresh_specialized_execution_selectors(self, selected_modes: dict | None = None):
        selected_modes = normalize_specialized_execution_modes(selected_modes)
        for capability, combo in self.specialized_execution_combos.items():
            combo.blockSignals(True)
            combo.clear()
            options = SPECIALIZED_EXECUTION_OPTIONS.get(capability, [])
            for label, value in options:
                combo.addItem(label, value)
            selected_value = str(selected_modes.get(capability, '')).strip()
            index = combo.findData(selected_value)
            combo.setCurrentIndex(index if index >= 0 else 0)
            combo.blockSignals(False)
        self._update_specialized_external_target_controls()

    def refresh_background_vision_profile_list(self, selected_names=None):
        if not hasattr(self, 'background_vision_profile_list_widget'):
            return
        selected = set(normalize_background_vision_profile_names(selected_names))
        self._background_vision_updating = True
        self.background_vision_profile_list_widget.clear()
        for profile in self._profiles_sorted_by_name():
            name = str(profile.get('name', '') or '').strip()
            if not name:
                continue
            item = QListWidgetItem(name)
            item.setFlags(item.flags() | Qt.ItemFlag.ItemIsUserCheckable)
            item.setCheckState(Qt.CheckState.Checked if name in selected else Qt.CheckState.Unchecked)
            self.background_vision_profile_list_widget.addItem(item)
        self._background_vision_updating = False

    def _current_background_vision_profile_names(self) -> list[str]:
        if not hasattr(self, 'background_vision_profile_list_widget'):
            return []
        names = []
        for index in range(self.background_vision_profile_list_widget.count()):
            item = self.background_vision_profile_list_widget.item(index)
            if item and item.checkState() == Qt.CheckState.Checked:
                names.append(item.text().strip())
        return [name for name in names if name]

    def _set_dropdown_current_data(self, combo: DropdownButton, value, fallback_index: int = 0):
        index = combo.findData(value)
        combo.setCurrentIndex(index if index >= 0 else fallback_index)

