    def _update_computer_use_controls(self):
        enabled = bool(self.computer_use_enabled_checkbox.isChecked())
        self.computer_use_driver_command_input.setEnabled(enabled)
        self.computer_use_max_steps_input.setEnabled(enabled)
        self.computer_use_target_display_combo.setEnabled(enabled)
        if hasattr(self, 'computer_use_profile_combo'):
            self.computer_use_profile_combo.setEnabled(enabled)

    def _update_browser_use_controls(self):
        enabled = bool(self.browser_use_enabled_checkbox.isChecked())
        mode = normalize_browser_use_chrome_mode(self.browser_use_chrome_mode_combo.currentData())
        open_new_window = bool(self.browser_use_open_new_window_checkbox.isChecked())
        for widget in (
            self.browser_use_profile_combo,
            self.browser_use_llm_combo,
            self.browser_use_max_steps_input,
            self.browser_use_vision_combo,
            self.browser_use_speed_mode_combo,
            self.browser_use_history_items_input,
            self.browser_use_task_context_combo,
            self.browser_use_search_engine_combo,
            self.browser_use_parallel_share_login_checkbox,
            self.browser_use_open_new_window_checkbox,
            self.browser_use_close_window_checkbox,
            self.browser_use_launch_button,
        ):
            widget.setEnabled(enabled)
        # Reusing the current Browser Use window always goes through CDP and
        # overrides chrome_mode at runtime. Keep the actual CDP field editable
        # in that state and disable the ignored mode selector.
        self.browser_use_chrome_mode_combo.setEnabled(enabled and open_new_window)
        self.browser_use_cdp_url_input.setEnabled(
            enabled and (mode == 'connect_existing' or not open_new_window)
        )
        self.browser_use_chrome_executable_input.setEnabled(enabled)
        self.browser_use_chrome_browse_button.setEnabled(enabled)
        self.browser_use_user_data_dir_input.setEnabled(enabled)
        self.browser_use_user_data_dir_button.setEnabled(enabled)

    def _update_background_vision_controls(self):
        enabled = bool(self.background_vision_enabled_checkbox.isChecked())
        show_enabled = enabled
        self.background_vision_show_overlay_checkbox.setEnabled(show_enabled)
        for widget in (
            self.background_vision_profile_list_widget,
            self.background_vision_schedule_combo,
            self.background_vision_interval_input,
            self.background_vision_completion_delay_input,
            self.background_vision_toast_duration_input,
            self.background_vision_wait_mode_combo,
            self.background_vision_max_workers_input,
            self.background_vision_image_format_combo,
            self.background_vision_keep_history_checkbox,
            self.background_vision_max_history_input,
            self.background_vision_prompt_edit,
            self.background_vision_save_captures_checkbox,
            self.background_vision_capture_dir_input,
            self.background_vision_capture_dir_button,
            self.background_vision_max_records_input,
        ):
            widget.setEnabled(enabled)
        self.background_vision_capture_dir_input.setEnabled(enabled and self.background_vision_save_captures_checkbox.isChecked())
        self.background_vision_capture_dir_button.setEnabled(enabled and self.background_vision_save_captures_checkbox.isChecked())

    def _browse_background_vision_capture_dir(self):
        chosen = QFileDialog.getExistingDirectory(
            self,
            _tr('Select background vision screenshot folder'),
            self.background_vision_capture_dir_input.text().strip() or BACKGROUND_VISION_CAPTURE_DIR,
        )
        if chosen:
            self.background_vision_capture_dir_input.setText(chosen)
            self._mark_dirty_if_needed()

    def _update_embedding_status_hint(self, message: str | None = None):
        if message is not None:
            message = str(message)
            if message.startswith('Embedding unavailable: '):
                message = _tr('Embedding unavailable: {error}').format(error=message[len('Embedding unavailable: '):])
            else:
                message = _tr(message)
            self.embedding_status_label.setText(message)
        elif str(self.embedding_profile_combo.currentData() or '').strip():
            self.embedding_status_label.setText(_tr('Embedding profile selected. Test to verify retrieval support.'))
        else:
            self.embedding_status_label.setText(_tr('No embedding profile selected. Retrieval will fall back to keywords.'))
        self.embedding_test_button.setEnabled(bool(str(self.embedding_profile_combo.currentData() or '').strip()))

