    def set_force_dark(self, enabled: bool):
        enabled = bool(enabled)
        if self._force_dark == enabled:
            return
        self._force_dark = enabled
        self._apply_theme()

    def changeEvent(self, event):
        super().changeEvent(event)
        if self._theme_updating:
            return
        if event.type() in (QEvent.Type.PaletteChange, QEvent.Type.ApplicationPaletteChange):
            self._apply_theme()

    def _edit_memory_item(self, item: QListWidgetItem):
        if item is None:
            return
        record = normalize_memory_item_record(item.data(Qt.ItemDataRole.UserRole)) or {'text': item.text(), 'created_at': datetime.datetime.now().isoformat(timespec='seconds'), 'kind': 'manual', 'source_date': ''}
        dialog = MemoryEditDialog(record['text'], self)
        if dialog.exec() == QDialog.DialogCode.Accepted and dialog.text():
            record['text'] = dialog.text()
            item.setData(Qt.ItemDataRole.UserRole, record)
            item.setText(memory_item_display_text(record))
            self._mark_dirty_if_needed()

    def _append_memory_item_to_permanent(self, item: QListWidgetItem):
        if item is None:
            return
        record = normalize_memory_item_record(item.data(Qt.ItemDataRole.UserRole))
        if record is None:
            return
        current = self.memory_text_edit.toPlainText().rstrip()
        addition = record['text'].strip()
        if not addition:
            return
        merged = (current + '\n\n' + addition).strip() if current else addition
        self.memory_text_edit.setPlainText(merged)
        self._mark_dirty_if_needed()

    def _delete_memory_item(self, item: QListWidgetItem):
        if item is None:
            return
        row = self.memory_list_widget.row(item)
        if row >= 0:
            self.memory_list_widget.takeItem(row)
            self._mark_dirty_if_needed()

    def _show_memory_context_menu(self, pos):
        item = self.memory_list_widget.itemAt(pos)
        if item is None:
            return
        menu = style_broccoli_context_menu(QMenu(self))
        append_action = menu.addAction(_tr('Append to permanent memory'))
        edit_action = menu.addAction(_tr('Edit'))
        delete_action = menu.addAction(_tr('Delete'))
        chosen = menu.exec(self.memory_list_widget.mapToGlobal(pos))
        if chosen == append_action:
            self._append_memory_item_to_permanent(item)
        elif chosen == edit_action:
            self._edit_memory_item(item)
        elif chosen == delete_action:
            self._delete_memory_item(item)

    def _set_prompt_records(self, records) -> None:
        self._prompt_updating = True
        self._prompt_records = []
        self.prompt_list_widget.clear()
        for index, record in enumerate(records or [], start=1):
            if not isinstance(record, dict):
                continue
            normalized = {
                'name': sanitize_custom_prompt_name(record.get('name', ''), f'Prompt {index}'),
                'body': str(record.get('body', '') or '').replace('\r\n', '\n').replace('\r', '\n'),
            }
            self._prompt_records.append(normalized)
            item = QListWidgetItem(normalized['name'])
            item.setFlags(item.flags() | Qt.ItemFlag.ItemIsEditable)
            self.prompt_list_widget.addItem(item)
        if self._prompt_records:
            self.prompt_list_widget.setCurrentRow(0)
            self.prompt_body_edit.setPlainText(self._prompt_records[0]['body'])
            self.prompt_body_edit.setEnabled(True)
            self.prompt_delete_button.setEnabled(True)
        else:
            self.prompt_body_edit.clear()
            self.prompt_body_edit.setEnabled(False)
            self.prompt_delete_button.setEnabled(False)
        self._prompt_updating = False

    def _on_prompt_selection_changed(self, current, previous):
        if self._prompt_updating:
            return
        self._prompt_updating = True
        row = self.prompt_list_widget.currentRow()
        if 0 <= row < len(self._prompt_records):
            self.prompt_body_edit.setEnabled(True)
            self.prompt_delete_button.setEnabled(True)
            self.prompt_body_edit.setPlainText(self._prompt_records[row].get('body', ''))
        else:
            self.prompt_body_edit.clear()
            self.prompt_body_edit.setEnabled(False)
            self.prompt_delete_button.setEnabled(False)
        self._prompt_updating = False
        self._mark_dirty_if_needed()

    def _on_prompt_body_changed(self):
        if self._prompt_updating:
            return
        row = self.prompt_list_widget.currentRow()
        if 0 <= row < len(self._prompt_records):
            self._prompt_records[row]['body'] = self.prompt_body_edit.toPlainText()
            self._mark_dirty_if_needed()

    def _on_prompt_item_changed(self, item: QListWidgetItem):
        if self._prompt_updating or item is None:
            return
        row = self.prompt_list_widget.row(item)
        if 0 <= row < len(self._prompt_records):
            new_name = sanitize_custom_prompt_name(item.text(), f'Prompt {row + 1}')
            self._prompt_updating = True
            item.setText(new_name)
            self._prompt_updating = False
            self._prompt_records[row]['name'] = new_name
            self._mark_dirty_if_needed()

    def _add_prompt_record(self):
        self._prompt_updating = True
        new_index = len(self._prompt_records) + 1
        record = {'name': f'Prompt {new_index}', 'body': ''}
        self._prompt_records.append(record)
        item = QListWidgetItem(record['name'])
        item.setFlags(item.flags() | Qt.ItemFlag.ItemIsEditable)
        self.prompt_list_widget.addItem(item)
        self.prompt_list_widget.setCurrentItem(item)
        self.prompt_body_edit.clear()
        self.prompt_body_edit.setEnabled(True)
        self.prompt_delete_button.setEnabled(True)
        self._prompt_updating = False
        self.prompt_list_widget.editItem(item)
        self._mark_dirty_if_needed()

    def _delete_prompt_record(self):
        row = self.prompt_list_widget.currentRow()
        if not (0 <= row < len(self._prompt_records)):
            return
        self._prompt_updating = True
        del self._prompt_records[row]
        self.prompt_list_widget.takeItem(row)
        if self._prompt_records:
            next_row = min(row, len(self._prompt_records) - 1)
            self.prompt_list_widget.setCurrentRow(next_row)
            self.prompt_body_edit.setPlainText(self._prompt_records[next_row].get('body', ''))
            self.prompt_body_edit.setEnabled(True)
            self.prompt_delete_button.setEnabled(True)
        else:
            self.prompt_body_edit.clear()
            self.prompt_body_edit.setEnabled(False)
            self.prompt_delete_button.setEnabled(False)
        self._prompt_updating = False
        self._mark_dirty_if_needed()

    def _skill_item_text(self, record: dict) -> str:
        name = sanitize_skill_name(record.get('name', ''), _tr('Skill'))
        description = re.sub(r'\s+', ' ', str(record.get('description', '') or '')).strip()
        if len(description) > 140:
            description = description[:140].rstrip() + '...'
        status = _tr('enabled') if record.get('enabled', True) else _tr('disabled')
        return f'{name} · {status}' + (f'\n{description}' if description else '\n' + _tr('Missing description'))

    def _set_skill_records(self, records) -> None:
        self._skill_updating = True
        self._skill_records = normalize_skill_records(records)
        self.skill_list_widget.clear()
        for record in self._skill_records:
            item = QListWidgetItem(self._skill_item_text(record))
            item.setFlags(item.flags() | Qt.ItemFlag.ItemIsUserCheckable | Qt.ItemFlag.ItemIsEnabled | Qt.ItemFlag.ItemIsSelectable)
            item.setCheckState(Qt.CheckState.Checked if record.get('enabled', True) else Qt.CheckState.Unchecked)
            self.skill_list_widget.addItem(item)
        if self._skill_records:
            self.skill_list_widget.setCurrentRow(0)
            self.skill_body_edit.setPlainText(self._skill_records[0].get('raw_text', ''))
            self.skill_body_edit.setEnabled(True)
            self.skill_delete_button.setEnabled(True)
        else:
            self.skill_body_edit.clear()
            self.skill_body_edit.setEnabled(False)
            self.skill_delete_button.setEnabled(False)
        self._skill_updating = False

    def _current_skill_records(self) -> list[dict]:
        records = []
        for index, record in enumerate(self._skill_records):
            current = dict(record)
            item = self.skill_list_widget.item(index)
            if item is not None:
                current['enabled'] = item.checkState() == Qt.CheckState.Checked
            records.append(current)
        return records

    def _refresh_skill_item(self, row: int):
        if not (0 <= row < len(self._skill_records)):
            return
        item = self.skill_list_widget.item(row)
        if item is None:
            return
        record = self._skill_records[row]
        previous = self._skill_updating
        self._skill_updating = True
        item.setText(self._skill_item_text(record))
        item.setCheckState(Qt.CheckState.Checked if record.get('enabled', True) else Qt.CheckState.Unchecked)
        self._skill_updating = previous

    def _on_skill_selection_changed(self, current, previous):
        if self._skill_updating:
            return
        self._skill_updating = True
        row = self.skill_list_widget.currentRow()
        if 0 <= row < len(self._skill_records):
            self.skill_body_edit.setEnabled(True)
            self.skill_delete_button.setEnabled(True)
            self.skill_body_edit.setPlainText(self._skill_records[row].get('raw_text', ''))
        else:
            self.skill_body_edit.clear()
            self.skill_body_edit.setEnabled(False)
            self.skill_delete_button.setEnabled(False)
        self._skill_updating = False
        self._mark_dirty_if_needed()

    def _on_skill_body_changed(self):
        if self._skill_updating:
            return
        row = self.skill_list_widget.currentRow()
        if not (0 <= row < len(self._skill_records)):
            return
        raw_text = self.skill_body_edit.toPlainText().replace('\r\n', '\n').replace('\r', '\n')
        enabled = self._skill_records[row].get('enabled', True)
        normalized = normalize_skill_record({'raw_text': raw_text, 'enabled': enabled}, row + 1)
        if normalized is None:
            return
        self._skill_records[row] = normalized
        self._refresh_skill_item(row)
        self._mark_dirty_if_needed()

    def _on_skill_item_changed(self, item: QListWidgetItem):
        if self._skill_updating or item is None:
            return
        row = self.skill_list_widget.row(item)
        if 0 <= row < len(self._skill_records):
            self._skill_records[row]['enabled'] = item.checkState() == Qt.CheckState.Checked
            self._refresh_skill_item(row)
            self._mark_dirty_if_needed()

    def _add_skill_record(self):
        self._skill_updating = True
        existing = {
            str(record.get('name', '') or '').strip().lower()
            for record in self._skill_records
        }
        index = len(self._skill_records) + 1
        name = f'new-skill-{index}'
        suffix = index
        while name.lower() in existing:
            suffix += 1
            name = f'new-skill-{suffix}'
        raw_text = DEFAULT_SKILL_TEMPLATE.replace('new-skill', name, 1)
        record = normalize_skill_record({'raw_text': raw_text, 'enabled': True}, index)
        self._skill_records.append(record)
        item = QListWidgetItem(self._skill_item_text(record))
        item.setFlags(item.flags() | Qt.ItemFlag.ItemIsUserCheckable | Qt.ItemFlag.ItemIsEnabled | Qt.ItemFlag.ItemIsSelectable)
        item.setCheckState(Qt.CheckState.Checked)
        self.skill_list_widget.addItem(item)
        self.skill_list_widget.setCurrentItem(item)
        self.skill_body_edit.setPlainText(raw_text)
        self.skill_body_edit.setEnabled(True)
        self.skill_delete_button.setEnabled(True)
        self._skill_updating = False
        self._mark_dirty_if_needed()

    def _delete_skill_record(self):
        row = self.skill_list_widget.currentRow()
        if not (0 <= row < len(self._skill_records)):
            return
        self._skill_updating = True
        del self._skill_records[row]
        self.skill_list_widget.takeItem(row)
        if self._skill_records:
            next_row = min(row, len(self._skill_records) - 1)
            self.skill_list_widget.setCurrentRow(next_row)
            self.skill_body_edit.setPlainText(self._skill_records[next_row].get('raw_text', ''))
            self.skill_body_edit.setEnabled(True)
            self.skill_delete_button.setEnabled(True)
        else:
            self.skill_body_edit.clear()
            self.skill_body_edit.setEnabled(False)
            self.skill_delete_button.setEnabled(False)
        self._skill_updating = False
        self._mark_dirty_if_needed()

    def _set_userscript_records(self, records):
        self._userscript_records = [r for r in (records or []) if isinstance(r, dict)]
        self.userscript_list_widget.clear()
        for record in self._userscript_records:
            item = QListWidgetItem(str(record.get('name', '')))
            item.setData(Qt.ItemDataRole.UserRole, record)
            self.userscript_list_widget.addItem(item)
        self.userscript_delete_button.setEnabled(False)

    def _current_userscripts(self):
        return list(self._userscript_records)

    def _on_userscript_selection_changed(self, current, _previous):
        self.userscript_delete_button.setEnabled(current is not None)

    def _add_userscript(self):
        home_dir = str(Path.home())
        path, _ = QFileDialog.getOpenFileName(self, _tr('Select userscript'), home_dir, _tr('JavaScript files (*.js);;All files (*)'))
        if not path:
            return
        os.makedirs(USERSCRIPTS_DIR, exist_ok=True)
        name = os.path.basename(path)
        dest = os.path.join(USERSCRIPTS_DIR, name)
        counter = 1
        base, ext = os.path.splitext(name)
        while os.path.exists(dest):
            dest = os.path.join(USERSCRIPTS_DIR, f'{base}_{counter}{ext}')
            counter += 1
        try:
            import shutil
            shutil.copy2(path, dest)
        except Exception as exc:
            show_broccoli_message(self, _tr('Error'), _tr('Could not copy file: {exc}').format(exc=exc))
            return
        stored_name = os.path.basename(dest)
        record = {'name': stored_name, 'path': dest}
        self._userscript_records.append(record)
        item = QListWidgetItem(stored_name)
        item.setData(Qt.ItemDataRole.UserRole, record)
        self.userscript_list_widget.addItem(item)
        self.userscript_list_widget.setCurrentItem(item)
        self._mark_dirty_if_needed()

    def _delete_userscript(self):
        row = self.userscript_list_widget.currentRow()
        if not (0 <= row < len(self._userscript_records)):
            return
        record = self._userscript_records[row]
        stored_path = str(record.get('path', '')).strip()
        if stored_path and os.path.isfile(stored_path):
            try:
                os.remove(stored_path)
            except Exception:
                pass
        del self._userscript_records[row]
        self.userscript_list_widget.takeItem(row)
        if self._userscript_records:
            self.userscript_list_widget.setCurrentRow(min(row, len(self._userscript_records) - 1))
        else:
            self.userscript_delete_button.setEnabled(False)
        self._mark_dirty_if_needed()

    def _external_context_item_text(self, record: dict) -> str:
        source_type = str(record.get('type', 'local_path') or 'local_path')
        type_label = {
            'local_path': _tr('Local path'),
            'mcp_stdio': 'MCP stdio',
            'mcp_http': 'MCP HTTP',
        }.get(source_type, source_type)
        detail = str(record.get('path') or record.get('command') or record.get('endpoint') or '').strip()
        if source_type == 'mcp_http':
            flags = []
            transport = normalize_mcp_transport(record.get('transport', 'auto'))
            flags.append({'auto': _tr('auto'), 'streamable_http': 'streamable HTTP', 'sse': 'SSE'}.get(transport, transport))
            if record.get('read_only', True):
                flags.append(_tr('readonly'))
            toolsets = str(record.get('toolsets', '') or '').strip()
            if toolsets:
                flags.append(toolsets)
            tool_count = len(record.get('discovered_tools', []) or [])
            resource_count = len(record.get('discovered_resources', []) or [])
            prompt_count = len(record.get('discovered_prompts', []) or [])
            if tool_count or resource_count or prompt_count:
                flags.append(_tr('{tools} tools/{resources} resources/{prompts} prompts').format(
                    tools=tool_count, resources=resource_count, prompts=prompt_count))
            elif record.get('discovery_error'):
                flags.append(_tr('discovery failed'))
            if flags:
                detail = f'{detail} · {", ".join(flags)}'
        name = str(record.get('name', '') or type_label).strip()
        return f'{name} · {type_label}\n{detail}'

    def _set_external_context_sources(self, records):
        self._external_context_updating = True
        self._external_context_source_records = normalize_external_context_sources(records)
        self.external_context_list_widget.clear()
