    def _add_external_local_folder(self):
        chosen = QFileDialog.getExistingDirectory(self, _tr('Select external context folder'), str(Path.home()))
        if not chosen:
            return
        self._append_external_context_source(
            {
                'id': _new_external_context_source_id('local'),
                'type': 'local_path',
                'name': os.path.basename(chosen.rstrip(os.sep)) or 'Local context',
                'path': chosen,
                'enabled': True,
                'auto_context': True,
                'include_patterns': DEFAULT_EXTERNAL_CONTEXT_INCLUDE_PATTERNS,
                'exclude_patterns': DEFAULT_EXTERNAL_CONTEXT_EXCLUDE_PATTERNS,
                'max_chars': normalize_external_context_max_chars(self.external_context_limit_input.text()),
                'use_embedding': True,
            }
        )

    def _add_external_local_file(self):
        path, _ = QFileDialog.getOpenFileName(self, _tr('Select external context file'), str(Path.home()), _tr('Context files (*);;All files (*)'))
        if not path:
            return
        self._append_external_context_source(
            {
                'id': _new_external_context_source_id('local'),
                'type': 'local_path',
                'name': os.path.basename(path),
                'path': path,
                'enabled': True,
                'auto_context': True,
                'include_patterns': DEFAULT_EXTERNAL_CONTEXT_INCLUDE_PATTERNS,
                'exclude_patterns': '',
                'max_chars': normalize_external_context_max_chars(self.external_context_limit_input.text()),
                'use_embedding': True,
            }
        )

    def _add_external_mcp_stdio(self):
        dialog = ExternalMcpStdioDialog(self)
        self._center_child_dialog(dialog)
        if dialog.exec() != QDialog.DialogCode.Accepted:
            return
        record = dialog.record()
        record['max_chars'] = normalize_external_context_max_chars(self.external_context_limit_input.text())
        self._append_external_context_source(record)

    def _add_external_mcp_http(self):
        dialog = ExternalMcpHttpDialog(self)
        self._center_child_dialog(dialog)
        if dialog.exec() != QDialog.DialogCode.Accepted:
            return
        record = dialog.record()
        record['max_chars'] = normalize_external_context_max_chars(self.external_context_limit_input.text())
        self._append_external_context_source(record)

    def _replace_external_context_item(self, item: QListWidgetItem, record: dict):
        row = self.external_context_list_widget.row(item)
        normalized = normalize_external_context_source_record(record, row + 1)
        if normalized is None:
            return
        normalized['enabled'] = item.checkState() == Qt.CheckState.Checked
        self._external_context_updating = True
        item.setData(Qt.ItemDataRole.UserRole, normalized)
        item.setText(self._external_context_item_text(normalized))
        self._external_context_updating = False
        self._mark_dirty_if_needed()

    def _edit_external_context_source(self):
        item = self.external_context_list_widget.currentItem()
        if item is None:
            return
        row = self.external_context_list_widget.row(item)
        record = normalize_external_context_source_record(item.data(Qt.ItemDataRole.UserRole), row + 1)
        if record is None:
            return
        if record.get('type') == 'mcp_http':
            dialog = ExternalMcpHttpDialog(self, record)
            self._center_child_dialog(dialog)
            if dialog.exec() != QDialog.DialogCode.Accepted:
                return
            updated = dialog.record()
            updated['max_chars'] = normalize_external_context_max_chars(self.external_context_limit_input.text())
            self._replace_external_context_item(item, updated)
            return
        if record.get('type') == 'mcp_stdio':
            dialog = ExternalMcpStdioDialog(self, record)
            self._center_child_dialog(dialog)
            if dialog.exec() != QDialog.DialogCode.Accepted:
                return
            updated = dialog.record()
            updated['max_chars'] = normalize_external_context_max_chars(self.external_context_limit_input.text())
            self._replace_external_context_item(item, updated)
            return
        name, ok = ask_broccoli_text(self, _tr('Edit local context source'), _tr('Name:'), record.get('name', 'Local context'),
                                     force_dark=bool(getattr(self, '_force_dark', False)))
        if not ok or not name.strip():
            return
        record['name'] = name.strip()
        self._replace_external_context_item(item, record)

    def _show_external_context_new_menu(self):
        menu = style_broccoli_context_menu(QMenu(self))
        folder_action = menu.addAction(_tr('Local folder'))
        file_action = menu.addAction(_tr('Local file'))
        menu.addSeparator()
        stdio_action = menu.addAction(_tr('MCP stdio server'))
        http_action = menu.addAction(_tr('MCP HTTP endpoint'))
        chosen = menu.exec(QCursor.pos())
        if chosen == folder_action:
            self._add_external_local_folder()
        elif chosen == file_action:
            self._add_external_local_file()
        elif chosen == stdio_action:
            self._add_external_mcp_stdio()
        elif chosen == http_action:
            self._add_external_mcp_http()

    def _delete_external_context_source(self):
        row = self.external_context_list_widget.currentRow()
        if row < 0:
            return
        self.external_context_list_widget.takeItem(row)
        if self.external_context_list_widget.count() > 0:
            self.external_context_list_widget.setCurrentRow(min(row, self.external_context_list_widget.count() - 1))
        else:
            self.external_context_delete_button.setEnabled(False)
            if hasattr(self, 'external_context_edit_button'):
                self.external_context_edit_button.setEnabled(False)
        self._mark_dirty_if_needed()

    def _code_runner_item_text(self, record: dict) -> str:
        language = normalize_code_runner_language(record.get('language', ''), 'runner')
        command = str(record.get('command', '') or '').strip()
        status = _tr('enabled') if record.get('enabled', True) else _tr('disabled')
        available = _tr('available') if command and _resolve_runner_command(command) else _tr('missing')
        return f'{language} · {status} · {available}\n{command or _tr("No executable set")}'

    def _set_code_runner_records(self, records):
        self._code_runner_updating = True
        self._code_runner_records = normalize_code_runner_records(records)
        self.code_runner_list_widget.clear()
        for record in self._code_runner_records:
            item = QListWidgetItem(self._code_runner_item_text(record))
            item.setFlags(item.flags() | Qt.ItemFlag.ItemIsUserCheckable | Qt.ItemFlag.ItemIsEnabled | Qt.ItemFlag.ItemIsSelectable)
            item.setCheckState(Qt.CheckState.Checked if record.get('enabled', True) else Qt.CheckState.Unchecked)
            self.code_runner_list_widget.addItem(item)
        if self._code_runner_records:
            self.code_runner_list_widget.setCurrentRow(0)
        else:
            self.code_runner_delete_button.setEnabled(False)
        self._code_runner_updating = False
        self._load_code_runner_fields_for_row(self.code_runner_list_widget.currentRow())

    def _current_code_runner_records(self) -> list[dict]:
        records = []
        for index, record in enumerate(self._code_runner_records):
            current = dict(record)
            item = self.code_runner_list_widget.item(index)
            if item is not None:
                current['enabled'] = item.checkState() == Qt.CheckState.Checked
            records.append(normalize_code_runner_record(current, index + 1))
        return [record for record in records if record is not None]

    def _load_code_runner_fields_for_row(self, row: int):
        previous = self._code_runner_updating
        self._code_runner_updating = True
        enabled = 0 <= row < len(self._code_runner_records)
        for widget in (self.code_runner_language_input, self.code_runner_command_input, self.code_runner_args_input,
                       self.code_runner_browse_button, self.code_runner_autodetect_button):
            widget.setEnabled(enabled)
        self.code_runner_delete_button.setEnabled(enabled)
        if enabled:
            record = self._code_runner_records[row]
            self.code_runner_language_input.setText(str(record.get('language', '') or ''))
            self.code_runner_command_input.setText(str(record.get('command', '') or ''))
            self.code_runner_args_input.setText(str(record.get('args', '') or default_code_runner_args(record.get('language', ''))))
        else:
            self.code_runner_language_input.clear()
            self.code_runner_command_input.clear()
            self.code_runner_args_input.clear()
        self._code_runner_updating = previous

    def _refresh_code_runner_item(self, row: int):
        if not (0 <= row < len(self._code_runner_records)):
            return
        item = self.code_runner_list_widget.item(row)
        if item is None:
            return
        previous = self._code_runner_updating
        self._code_runner_updating = True
        item.setText(self._code_runner_item_text(self._code_runner_records[row]))
        item.setCheckState(Qt.CheckState.Checked if self._code_runner_records[row].get('enabled', True) else Qt.CheckState.Unchecked)
        self._code_runner_updating = previous

    def _on_code_runner_selection_changed(self, current, _previous):
        if self._code_runner_updating:
            return
        self._load_code_runner_fields_for_row(self.code_runner_list_widget.currentRow())
        self._mark_dirty_if_needed()

    def _on_code_runner_item_changed(self, item: QListWidgetItem):
        if self._code_runner_updating or item is None:
            return
        row = self.code_runner_list_widget.row(item)
        if 0 <= row < len(self._code_runner_records):
            self._code_runner_records[row]['enabled'] = item.checkState() == Qt.CheckState.Checked
            self._refresh_code_runner_item(row)
            self._mark_dirty_if_needed()

    def _on_code_runner_field_changed(self):
        if self._code_runner_updating:
            return
        row = self.code_runner_list_widget.currentRow()
        if not (0 <= row < len(self._code_runner_records)):
            return
        language = normalize_code_runner_language(self.code_runner_language_input.text(), f'runner{row + 1}')
        self._code_runner_records[row] = {
            'language': language,
            'command': self.code_runner_command_input.text().strip(),
            'args': self.code_runner_args_input.text().strip() or default_code_runner_args(language),
            'enabled': self._code_runner_records[row].get('enabled', True),
        }
        self._refresh_code_runner_item(row)
        self._mark_dirty_if_needed()

    def _add_code_runner_record(self):
        existing = {record.get('language', '') for record in self._code_runner_records}
        base = 'runner'
        index = len(self._code_runner_records) + 1
        language = f'{base}{index}'
        while language in existing:
            index += 1
            language = f'{base}{index}'
        record = {
            'language': language,
            'command': '',
            'args': '{code}',
            'enabled': True,
        }
        self._code_runner_records.append(record)
        previous = self._code_runner_updating
        self._code_runner_updating = True
        item = QListWidgetItem(self._code_runner_item_text(record))
        item.setFlags(item.flags() | Qt.ItemFlag.ItemIsUserCheckable | Qt.ItemFlag.ItemIsEnabled | Qt.ItemFlag.ItemIsSelectable)
        item.setCheckState(Qt.CheckState.Checked)
        self.code_runner_list_widget.addItem(item)
        self.code_runner_list_widget.setCurrentItem(item)
        self._code_runner_updating = previous
        self._load_code_runner_fields_for_row(self.code_runner_list_widget.currentRow())
        self._mark_dirty_if_needed()

    def _delete_code_runner_record(self):
        row = self.code_runner_list_widget.currentRow()
        if not (0 <= row < len(self._code_runner_records)):
            return
        del self._code_runner_records[row]
        self.code_runner_list_widget.takeItem(row)
        if self._code_runner_records:
            self.code_runner_list_widget.setCurrentRow(min(row, len(self._code_runner_records) - 1))
        self._load_code_runner_fields_for_row(self.code_runner_list_widget.currentRow())
        self._mark_dirty_if_needed()

    def _browse_code_runner_command(self):
        path, _ = QFileDialog.getOpenFileName(self, _tr('Select code runner executable'), str(Path.home()), _tr('Executables (*);;All files (*)'))
        if path:
            self.code_runner_command_input.setText(path)

    def _auto_detect_code_runner_command(self):
        language = normalize_code_runner_language(self.code_runner_language_input.text(), '')
        detected = auto_detect_code_runner_command(language)
        if detected:
            self.code_runner_command_input.setText(detected)
            if not self.code_runner_args_input.text().strip():
                self.code_runner_args_input.setText(default_code_runner_args(language))
        else:
            show_broccoli_message(self, _tr('Auto-detect'), _tr('No executable was found for language: {lang}').format(lang=language or 'unknown'))

    def _browse_webfetch_download_path(self):
        home_dir = str(Path.home())
        chosen = QFileDialog.getExistingDirectory(
            self,
            _tr('Select browser download folder'),
            self.webfetch_download_input.text().strip() or home_dir,
        )
        if chosen:
            self.webfetch_download_input.setText(chosen)
            self._mark_dirty_if_needed()

    def _choose_annotation_pen_color(self):
        current = QColor(self.annotation_pen_color_input.text().strip() or '#FF3B30')
        if not current.isValid():
            current = QColor('#FF3B30')
        color = QColorDialog.getColor(current, self, _tr('Annotation pen color'))
        if color.isValid():
            self.annotation_pen_color_input.setText(color.name().upper())
            self._mark_dirty_if_needed()

    def _browse_browser_use_chrome_executable(self):
        start_path = self.browser_use_chrome_executable_input.text().strip() or DEFAULT_BROWSER_USE_CHROME_EXECUTABLE
        chosen, _ = QFileDialog.getOpenFileName(
            self,
            _tr('Select Google Chrome executable'),
            start_path,
        )
        if chosen:
            self.browser_use_chrome_executable_input.setText(chosen)
            self._mark_dirty_if_needed()

    def _browse_browser_use_user_data_dir(self):
        chosen = QFileDialog.getExistingDirectory(
            self,
            _tr('Select Browser Use Chrome profile folder'),
            self.browser_use_user_data_dir_input.text().strip() or DEFAULT_BROWSER_USE_USER_DATA_DIR,
        )
        if chosen:
            self.browser_use_user_data_dir_input.setText(chosen)
            self._mark_dirty_if_needed()

    def launch_browser_use_chrome_from_settings(self):
        launch_browser_use_chrome_with_feedback(self, self._current_browser_use_settings())

    def _set_general_page(self, index: int):
        if not hasattr(self, 'general_pages'):
            return
        index = max(0, min(self.general_pages.count() - 1, int(index)))
        self.general_pages.setCurrentIndex(index)
        self._update_general_page_controls()

    def _set_models_page(self, index: int):
        if not hasattr(self, 'models_pages'):
            return
        index = max(0, min(self.models_pages.count() - 1, int(index)))
        self.models_pages.setCurrentIndex(index)
        if index == 1:
            self._populate_model_quality_table()
            # 停留在本页期间轮询刷新自动评价列（agent 复核会随时落档案）。
            timer = getattr(self, '_model_quality_refresh_timer', None)
            if timer is None:
                timer = QTimer(self)
                timer.setInterval(2500)
                timer.timeout.connect(self._refresh_model_quality_auto_column)
                self._model_quality_refresh_timer = timer
            timer.start()
        else:
            timer = getattr(self, '_model_quality_refresh_timer', None)
            if timer is not None:
                timer.stop()
        if hasattr(self, 'models_page_label'):
            self.models_page_label.setText(f'{index + 1} / {max(1, self.models_pages.count())} ▾')

    def _refresh_model_quality_auto_column(self):
        """只重写自动评价列（不重建行，不打断正在编辑的 Notes）；档案里
        出现表格没有的新模型才全量重建。页面/面板不可见时自停。"""
        table = getattr(self, 'model_quality_table', None)
        if table is None:
            return
        if not self.isVisible() or self.models_pages.currentIndex() != 1:
            timer = getattr(self, '_model_quality_refresh_timer', None)
            if timer is not None:
                timer.stop()
            return
        existing_names = set()
        for row in range(table.rowCount()):
            name_item = table.item(row, 0)
            if name_item is not None:
                existing_names.add(str(name_item.text() or '').strip())
        if any(
            name not in existing_names
            for name in _load_model_quality_cache().keys()
            if not name.startswith('@') and not name.startswith(CUSTOM_SERVICE_PREFIX)
        ):
            self._populate_model_quality_table()
            return
        self._model_quality_table_loading = True
        try:
            for row in range(table.rowCount()):
                name_item = table.item(row, 0)
                auto_item = table.item(row, 1)
                if name_item is None or auto_item is None:
                    continue
                summary = model_quality_auto_summary(str(name_item.text() or '').strip(), min_records=1, localize=True) or '—'
                if auto_item.text() != summary:
                    auto_item.setText(summary)
        finally:
            self._model_quality_table_loading = False

    def _populate_model_quality_table(self):
        table = getattr(self, 'model_quality_table', None)
        if table is None:
            return
        self._model_quality_table_loading = True
        try:
            names = [
                str(profile.get('name', '') or '').strip()
                for profile in self._profiles_sorted_by_name()
                if str(profile.get('name', '') or '').strip()
            ]
            # @target 全量列出（活跃 ∪ URL 配置推导，不按打开状态联动；
            # 配置里新增/删除 URL 后重建表格自然跟上）。自动评价列对
            # @/& 恒为空，属预期。
            window = self.window()
            if hasattr(window, '_collect_all_external_target_names'):
                try:
                    for name in window._collect_all_external_target_names():
                        if name not in names:
                            names.append(name)
                except Exception:
                    pass
            for service in get_custom_services_from_store(self.settings_store):
                service_ref = CUSTOM_SERVICE_PREFIX + str(service.get('name', '') or '').strip()
                if len(service_ref) > 1 and service_ref not in names:
                    names.append(service_ref)
            # 档案遗留键：普通 profile 保留（改名/删除后历史评价仍有参考
            # 价值）；@/& 的幽灵名（当前目录/配置里不存在的）不列——
            # 它们指不到任何真实目标。
            for extra in sorted(_load_model_quality_cache().keys()):
                if extra.startswith('@') or extra.startswith(CUSTOM_SERVICE_PREFIX):
                    continue
                if extra not in names:
                    names.append(extra)
            table.setRowCount(0)
            for name in names:
                row = table.rowCount()
                table.insertRow(row)
                name_item = QTableWidgetItem(name)
                name_item.setFlags(name_item.flags() & ~Qt.ItemFlag.ItemIsEditable)
                # 表格展示不设样本门槛（门槛只约束 planner 提示词）。
                auto_item = QTableWidgetItem(model_quality_auto_summary(name, min_records=1, localize=True) or '—')
                auto_item.setFlags(auto_item.flags() & ~Qt.ItemFlag.ItemIsEditable)
                notes_item = QTableWidgetItem(get_model_quality_entry(name).get('user_notes', ''))
                table.setItem(row, 0, name_item)
                table.setItem(row, 1, auto_item)
                table.setItem(row, 2, notes_item)
        finally:
            self._model_quality_table_loading = False

    def _on_model_quality_note_edited(self, item):
        if getattr(self, '_model_quality_table_loading', False):
            return
        if item is None or item.column() != 2:
            return
        table = self.model_quality_table
        name_item = table.item(item.row(), 0)
        name = str(name_item.text() if name_item is not None else '').strip()
        if name:
            set_model_user_notes(name, item.text())

    def _update_general_page_controls(self):
        if not hasattr(self, 'general_pages'):
            return
        index = self.general_pages.currentIndex()
        count = max(1, self.general_pages.count())
        if hasattr(self, 'general_page_label'):
            self.general_page_label.setText(f'{index + 1} / {count} ▾')
        if hasattr(self, 'general_prev_button'):
            self.general_prev_button.setEnabled(index > 0)
        if hasattr(self, 'general_next_button'):
            self.general_next_button.setEnabled(index < count - 1)

    # ── 设置页：页标题 / 页码目录 / 设置搜索（2026-10-16）──────────
    def _register_settings_page(self, category: int, page: QWidget, title: str, hint: str,
                                *, scrollable: bool = True, top_margin: int = 0) -> QWidget:
        """Wrap one settings page in its header (title + one-line hint) and a
        scroll area, and record it for the page list and the settings search.

        The header stays put; only the content scrolls, so a page taller than
        the fixed 500×760 panel scrolls instead of being squeezed."""
        if not hasattr(self, '_settings_pages_meta'):
            self._settings_pages_meta = {}
        frame = QWidget()
        frame_layout = QVBoxLayout(frame)
        frame_layout.setContentsMargins(0, int(top_margin), 0, 0)
        frame_layout.setSpacing(8)
        header = QWidget(frame)
        header_layout = QVBoxLayout(header)
        header_layout.setContentsMargins(0, 0, 0, 0)
        header_layout.setSpacing(2)
        title_label = QLabel(title, header)
        title_label.setStyleSheet(SETTINGS_PAGE_TITLE_STYLE)
        header_layout.addWidget(title_label)
        hint_label = None
        if hint:
            hint_label = QLabel(hint, header)
            hint_label.setWordWrap(True)
            hint_label.setStyleSheet(SETTINGS_PAGE_HINT_STYLE)
            header_layout.addWidget(hint_label)
        frame_layout.addWidget(header)
        scroll = None
        if scrollable:
            # 页宽恒等于可视宽度（第 1 页内容的最小宽度提示 636px > 可视 444px，
            # 默认滚动区会撑宽并裁掉右侧），页高取该宽度下的最小高度，见
            # SettingsPageScrollArea。
            scroll = SettingsPageScrollArea(frame)
            scroll.setFrameShape(QFrame.Shape.NoFrame)
            scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
            scroll.setStyleSheet(SETTINGS_SCROLL_AREA_STYLE)
            scroll.viewport().setAutoFillBackground(False)
            page.setAutoFillBackground(False)
            scroll.setWidget(page)
            frame_layout.addWidget(scroll, 1)
            # 只在真的出现滚动条时给内容右侧让出 12px，滚动条不压住输入框右边框；
            # 不滚动的页面布局不变。
            page_layout = page.layout()
            if page_layout is not None:
                base_margins = page_layout.contentsMargins()

                def reserve_scrollbar_gutter(_minimum, maximum, layout=page_layout, base=base_margins):
                    right = base.right() + (12 if maximum > 0 else 0)
                    if layout.contentsMargins().right() != right:
                        layout.setContentsMargins(base.left(), base.top(), right, base.bottom())

                scroll.verticalScrollBar().rangeChanged.connect(reserve_scrollbar_gutter)
        else:
            frame_layout.addWidget(page, 1)
        self._settings_pages_meta.setdefault(int(category), []).append({
            'category': int(category),
            'title': title,
            'hint': hint,
            'frame': frame,
            'page': page,
            'scroll': scroll,
            'title_label': title_label,
            'hint_label': hint_label,
        })
        return frame

    def showEvent(self, event):
        super().showEvent(event)
        QTimer.singleShot(0, self._relayout_visible_settings_lists)

    def _relayout_visible_settings_lists(self, *_args):
        """A QListWidget keeps the row positions of its first item layout. When
        that ran before the card stylesheet (10px padding + 6px gap) was polished,
        42px rows sit 16px apart and overlap (seen on Prompts / userscripts /
        Languages). Re-run the item layout of the lists now on screen."""
        for list_widget in self.findChildren(QListWidget):
            if list_widget.isVisible():
                list_widget.doItemsLayout()

    def _settings_category_names(self) -> list:
        return [_tr('General'), _tr('Models'), _tr('Memory'), _tr('Languages'), _tr('Prompts')]

    def _settings_category_stack(self, category: int):
        return {
            0: getattr(self, 'general_pages', None),
            1: getattr(self, 'models_pages', None),
            2: getattr(self, 'memory_pages', None),
            4: getattr(self, 'prompt_pages', None),
        }.get(int(category))

    def _settings_page_setter(self, category: int):
        return {
            0: self._set_general_page,
            1: self._set_models_page,
            2: self._set_memory_page,
            4: self._set_prompt_page,
        }.get(int(category))

    def _go_to_settings_page(self, category: int, index: int, *, animate: bool = False):
        """Show one settings page. animate=True slides within the current
        category (page list); the settings search jumps instantly because it
        then scrolls to and highlights the target."""
        category = int(category)
        setter = self._settings_page_setter(category)
        stack = self._settings_category_stack(category)
        if animate and setter is not None and stack is not None \
                and self.settings_pages.currentIndex() == category \
                and int(index) != stack.currentIndex():
            direction = 1 if int(index) > stack.currentIndex() else -1
            self._slide_settings_stack(stack, lambda: setter(int(index)), direction)
            return
        if self.settings_pages.currentIndex() != category:
            self.settings_nav.select(category)
        if self.settings_pages.currentIndex() != category:
            self.settings_pages.setCurrentIndex(category)
        if setter is not None:
            setter(int(index))

    def _turn_settings_page(self, category: int, step: int):
        """‹ › buttons: one page back or forward with a horizontal slide."""
        stack = self._settings_category_stack(category)
        setter = self._settings_page_setter(category)
        if stack is None or setter is None:
            return
        target = max(0, min(stack.count() - 1, stack.currentIndex() + int(step)))
        if target == stack.currentIndex():
            return
        self._slide_settings_stack(stack, lambda: setter(target), 1 if step > 0 else -1)

    def _finish_settings_slide(self):
        running = getattr(self, '_settings_slide', None)
        self._settings_slide = None
        if not running:
            return
        overlay, animation = running
        animation.stop()
        overlay.hide()
        overlay.deleteLater()

    def _slide_settings_stack(self, stack: QStackedWidget, change, direction: int):
        """Switch the page at once (index, pager label and data refresh behave
        exactly as without animation), then slide snapshots of the outgoing and
        incoming page over it for SETTINGS_PAGE_SLIDE_MS."""
        self._finish_settings_slide()
        if not stack.isVisible() or stack.width() <= 1 or stack.height() <= 1:
            change()
            return
        old_pixmap = _settings_transparent_snapshot(stack)
        change()
        # 新页的列表行位置与滚动区尺寸先落定，快照才与动画结束后的真实页面一致。
        self._relayout_visible_settings_lists()
        current = stack.currentWidget()
        if current is not None and current.layout() is not None:
            current.layout().activate()
        for scroller in (current.findChildren(SettingsPageScrollArea) if current is not None else []):
            scroller._fit_page()
        new_pixmap = _settings_transparent_snapshot(stack)
        overlay = SettingsSlideOverlay(
            stack, old_pixmap, new_pixmap, direction,
            QColor(getattr(self, '_settings_panel_background', '#FFFFFF')),
        )
        overlay.show()
        overlay.raise_()
        animation = QVariantAnimation(overlay)
        animation.setStartValue(0.0)
        animation.setEndValue(1.0)
        animation.setDuration(SETTINGS_PAGE_SLIDE_MS)
        animation.setEasingCurve(QEasingCurve.Type.OutCubic)
        animation.valueChanged.connect(overlay.set_progress)
        animation.finished.connect(self._finish_settings_slide)
        self._settings_slide = (overlay, animation)
        animation.start()

    def _show_settings_page_menu(self, category: int, anchor: QWidget):
        pages = (getattr(self, '_settings_pages_meta', {}) or {}).get(int(category)) or []
        if len(pages) < 2:
            return
        stack = self._settings_category_stack(category)
        current = stack.currentIndex() if stack is not None else 0
        previous = getattr(self, '_settings_page_menu', None)
        if previous is not None:
            try:
                previous.deleteLater()
            except RuntimeError:
                pass
        menu = style_broccoli_context_menu(QMenu(self))
        current_action = None
        for index, meta in enumerate(pages):
            # QMenu 把单个 & 当快捷键标记吞掉（“Add & manage profiles”→“Add _manage”），须写成 &&。
            title = meta['title'].replace('&', '&&')
            action = menu.addAction(f'{index + 1}. {title}')
            # 当前页打勾：系统菜单在左边的勾选栏画 ✓，和单选下拉一样。
            action.setCheckable(True)
            action.setChecked(index == current)
            if index == current:
                current_action = action
            action.triggered.connect(
                lambda _checked=False, cat=int(category), page_index=index:
                self._go_to_settings_page(cat, page_index, animate=True)
            )
        self._settings_page_menu = menu
        # 系统弹出菜单，当前页那一行压在页码上（像弹出按钮），靠近屏幕边缘时系统自己挪。
        # 以前用 popup()：原生菜单只接管 exec()，于是它一直是 Qt 自己画的白卡片。
        text_left = (anchor.width() - anchor.fontMetrics().horizontalAdvance(anchor.text())) // 2
        handled, _chosen = exec_native_qmenu(
            menu, anchor.mapToGlobal(QPoint(text_left - GLASS_LIST_TEXT_X, (anchor.height() - GLASS_LIST_ROW_H) // 2)),
            presentation='dropdown', positioning_action=current_action)
        if not handled:
            # Qt 菜单（离屏、关掉原生菜单时）：页码在面板底部，目录向上展开，水平居中于页码。
            size = menu.sizeHint()
            menu.exec(anchor.mapToGlobal(QPoint((anchor.width() - size.width()) // 2, -size.height() - 6)))

    @staticmethod
    def _settings_search_widget_texts(widget: QWidget) -> list:
        """Visible setting names a widget shows. Values the user typed or picked
        (line-edit text, dropdown selections) are data, not setting names."""
        if isinstance(widget, DropdownButton):
            return []
        if isinstance(widget, (QLineEdit, QTextEdit, QPlainTextEdit)):
            raw = widget.placeholderText()
        elif isinstance(widget, QLabel):
            raw = re.sub(r'<[^>]+>', ' ', widget.text())
        elif isinstance(widget, (QCheckBox, QPushButton)):
            raw = re.sub(r'&(?=\S)', '', widget.text()).replace('&&', '&')
        else:
            return []
        text = ' '.join(str(raw or '').split())
        if len(text) < 2 or not re.search(r'\w', text):
            return []
        # 示例/默认路径与网址（输入框占位符、路径说明）是数据，不是设置名称。
        if re.match(r'^(~?/|[A-Za-z]:\\)', text) or re.match(r'^[A-Za-z][\w+.-]*://\S+$', text):
            return []
        return [text]

    def _settings_search_index(self) -> list:
        entries = []
        category_names = self._settings_category_names()
        for category, pages in sorted((getattr(self, '_settings_pages_meta', {}) or {}).items()):
            for index, meta in enumerate(pages):
                entries.append({
                    'category': category, 'page': index, 'widget': None, 'kind': 'page',
                    'text': meta['title'], 'context': category_names[category],
                    'hint': meta.get('hint') or '',
                })
                seen = set()
                page = meta['page']
                for widget in page.findChildren(QWidget):
                    if not widget.isVisibleTo(page):
                        continue
                    for text in self._settings_search_widget_texts(widget):
                        key = text.casefold()
                        if key in seen:
                            continue
                        seen.add(key)
                        entries.append({
                            'category': category, 'page': index, 'widget': widget, 'kind': 'control',
                            'text': text, 'context': meta['title'], 'hint': '',
                        })
        return entries

    def _settings_search_results(self, query: str, limit: int = 12) -> list:
        """Every query word must appear. Pages match on title, hint and
        category; a control must contain at least one word itself (its page
        title may supply the rest), so a page-name query lists the page once
        instead of every control on it."""
        terms = [term for term in str(query or '').casefold().split() if term]
        if not terms:
            return []
        ranked = []
        for entry in self._settings_search_index():
            own = entry['text'].casefold()
            if entry['kind'] == 'page':
                pool = ' '.join((own, entry['hint'].casefold(), entry['context'].casefold()))
                if not all(term in pool for term in terms):
                    continue
                rank = 0 if all(term in own for term in terms) else 3
            else:
                pool = own + ' ' + entry['context'].casefold()
                if not all(term in pool for term in terms) or not any(term in own for term in terms):
                    continue
                if all(term in own for term in terms):
                    rank = 1 if own.startswith(terms[0]) else 2
                else:
                    rank = 4
            ranked.append((rank, len(own), entry))
        ranked.sort(key=lambda item: (item[0], item[1]))
        return [entry for _rank, _length, entry in ranked[:max(1, int(limit))]]

    @staticmethod
    def _settings_search_label(entry: dict) -> str:
        text = entry['text'] if len(entry['text']) <= 80 else entry['text'][:79] + '…'
        return f'{entry["context"]} › {text}'

    def _on_settings_search_text(self, text: str):
        model = self._settings_search_model
        model.clear()
        query = str(text or '')
        hits = self._settings_search_results(query) if query.strip() else []
        self._settings_search_hits = hits
        popup = self._settings_search_completer.popup()
        if not query.strip():
            popup.hide()
            return
        if not hits:
            item = QStandardItem(_tr('No matching settings'))
            item.setEnabled(False)
            item.setData(query, SETTINGS_SEARCH_QUERY_ROLE)
            model.appendRow(item)
        for position, entry in enumerate(hits):
            item = QStandardItem(self._settings_search_label(entry))
            item.setEditable(False)
            item.setData(query, SETTINGS_SEARCH_QUERY_ROLE)
            item.setData(position, SETTINGS_SEARCH_ENTRY_ROLE)
            model.appendRow(item)
        self._settings_search_completer.complete(self.settings_search_input.rect())
        # QCompleter 按约 3px 的默认边框估算弹出高度；本列表边框 + 内边距是 5px，
        # 每次少 4px，3 行结果也冒出滚动条。按实际行高补足（超过可见行数才滚动）。
        visible_rows = min(model.rowCount(), self._settings_search_completer.maxVisibleItems())
        needed = sum(popup.sizeHintForRow(row) for row in range(visible_rows)) + 2 * popup.frameWidth()
        if visible_rows and popup.height() < needed:
            popup.resize(popup.width(), needed)

    def _on_settings_search_activated(self, index):
        position = index.data(SETTINGS_SEARCH_ENTRY_ROLE) if index is not None else None
        hits = getattr(self, '_settings_search_hits', []) or []
        if position is None or not (0 <= int(position) < len(hits)):
            return
        self._jump_to_settings_entry(hits[int(position)])

    def _on_settings_search_return(self):
        popup = self._settings_search_completer.popup()
        if popup.isVisible() and popup.currentIndex().isValid():
            return  # the completer's own Enter handling activates the highlighted row
        hits = getattr(self, '_settings_search_hits', []) or []
        if hits:
            popup.hide()
            self._jump_to_settings_entry(hits[0])

    def _jump_to_settings_entry(self, entry: dict):
        self._go_to_settings_page(entry['category'], entry['page'])
        meta = self._settings_pages_meta[entry['category']][entry['page']]
        target = entry.get('widget') or meta['title_label']
        # 等分类/页切换后的布局落定，再滚动到目标并闪一下。
        QTimer.singleShot(0, lambda: self._reveal_settings_target(meta, target))

    def _reveal_settings_target(self, meta: dict, target: QWidget):
        if target is None:
            return
        area = target.parentWidget()
        while area is not None and not isinstance(area, QScrollArea) and area is not meta['frame']:
            area = area.parentWidget()
        if isinstance(area, QScrollArea):
            area.ensureWidgetVisible(target, 0, 24)
        self._flash_settings_widget(target)

    def _flash_settings_widget(self, widget: QWidget):
        host = widget.parentWidget() if widget is not None else None
        if host is None:
            return
        overlay = QWidget(host)
        overlay.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents, True)
        overlay.setAttribute(Qt.WidgetAttribute.WA_StyledBackground, True)
        overlay.setStyleSheet('background-color: rgba(255, 196, 0, 0.32); border-radius: 6px;')
        overlay.setGeometry(widget.geometry().adjusted(-4, -2, 4, 2))
        overlay.show()
        overlay.raise_()
        self._settings_flash_overlay = overlay
        QTimer.singleShot(1500, overlay.deleteLater)

    # ── General 第 9 页：Web / Localhost URL 历史管理 ──────────
    def _create_url_history_table(self) -> QTableWidget:
        table = QTableWidget(0, 2, self)
        # 竖向网格线不画（最右列的竖线会贴着外框形成双线）；行分隔线
        # 由 QSS 的 item border-bottom 画，列分隔感留在表头中缝。
        table.setShowGrid(False)
        table.setHorizontalHeaderLabels([_tr('Name'), _tr('URL')])
        header = table.horizontalHeader()
        header.setSectionResizeMode(0, QHeaderView.ResizeMode.Interactive)
        header.setSectionResizeMode(1, QHeaderView.ResizeMode.Stretch)
        table.setColumnWidth(0, 150)
        table.verticalHeader().setVisible(False)
        table.setSelectionBehavior(QAbstractItemView.SelectionBehavior.SelectRows)
        table.setSelectionMode(QAbstractItemView.SelectionMode.SingleSelection)
        table.itemChanged.connect(lambda _item: self._mark_dirty_if_needed())
        return table

    def _url_history_table_entries(self, table) -> list:
        entries = []
        for row in range(table.rowCount()):
            name_item = table.item(row, 0)
            url_item = table.item(row, 1)
            url = str(url_item.text() if url_item is not None else '').strip()
            name = str(name_item.text() if name_item is not None else '').strip()
            if not url:
                continue
            entries.append({'url': url, 'label': name})
        return entries

    def _set_url_history_table_entries(self, table, entries):
        table.setRowCount(0)
        for entry in list(entries or []):
            if not isinstance(entry, dict):
                continue
            row = table.rowCount()
            table.insertRow(row)
            table.setItem(row, 0, QTableWidgetItem(str(entry.get('label', '') or '')))
            table.setItem(row, 1, QTableWidgetItem(str(entry.get('url', '') or '')))

    # ---------------- Computer Use experience rules (Settings > General) ----

    def _experience_rules_refresh(self):
        table = getattr(self, 'experience_rules_table', None)
        if table is None:
            return
        store = cu_experience.load_store(BROCCOLI_APP_DATA_DIR)
        self._experience_rule_ids = []
        table.blockSignals(True)
        try:
            table.setRowCount(0)
            for rule in store.get('rules') or []:
                row = table.rowCount()
                table.insertRow(row)
                provenance = {'builtin': _tr('Builtin'), 'auto': _tr('Learned'), 'user': _tr('Manual')}.get(
                    str(rule.get('provenance', '') or ''), '?'
                )
                status = str(((rule.get('compiled') or {}).get('status', '')) or '')
                name_text = f"[{provenance}] {rule.get('name', '')}"
                if not rule.get('enabled', True):
                    name_text += ' ' + _tr('(disabled)')
                elif status and status != cu_experience.STATUS_ACTIVE:
                    # status code stays English in the store; only the shown copy is translated
                    name_text += ' (%s)' % {
                        'pending': _tr('pending'), 'compiling': _tr('compiling'), 'failed': _tr('failed'),
                    }.get(status, status)
                for column, text in (
                        (0, name_text),
                        (1, str(rule.get('steps_nl', '') or '')),
                        (2, str(rule.get('rule_nl', '') or '')),
                ):
                    item = QTableWidgetItem(text)
                    item.setFlags(item.flags() & ~Qt.ItemFlag.ItemIsEditable)
                    table.setItem(row, column, item)
                self._experience_rule_ids.append(str(rule.get('id', '') or ''))
        finally:
            table.blockSignals(False)

    def _experience_open_rule_row(self, row: int):
        rule_ids = getattr(self, '_experience_rule_ids', [])
        if not (0 <= row < len(rule_ids)):
            return
        rule_id = rule_ids[row]
        store = cu_experience.load_store(BROCCOLI_APP_DATA_DIR)
        rule = cu_experience.find_rule(store, rule_id)
        if rule is None:
            return
        dialog = ExperienceRuleDialog(rule, self)
        dialog.exec()
        action = dialog.result_action
        if not action:
            return
        if action == 'delete' and rule.get('provenance') != cu_experience.PROVENANCE_BUILTIN:
            store['rules'] = [
                item for item in store.get('rules') or []
                if str(item.get('id')) != rule_id
            ]
            cu_experience.save_store(BROCCOLI_APP_DATA_DIR, store)
            self._experience_rules_refresh()
            return
        if action == 'restore':
            if cu_experience.restore_builtin(store, rule_id):
                cu_experience.save_store(BROCCOLI_APP_DATA_DIR, store)
            self._experience_rules_refresh()
            return
        fields = dialog.edited_fields()
        rule['name'] = fields['name']
        rule['applies_to'] = {
            'app': fields['app'],
            'task_shape': str((rule.get('applies_to') or {}).get('task_shape', 'any') or 'any'),
        }
        rule['steps_nl'] = fields['steps_nl']
        rule['rule_nl'] = fields['rule_nl']
        rule['enabled'] = fields['enabled']
        rule['updated_at'] = time.strftime('%Y-%m-%dT%H:%M:%S')
        compiled = rule.setdefault('compiled', {})
        new_hash = cu_experience.nl_hash(rule)
        if str(compiled.get('nl_hash', '') or '') != new_hash:
            # Natural language changed: the operational form must be regenerated
            # by the background compiler before the rule becomes active again.
            compiled['status'] = cu_experience.STATUS_COMPILING
            compiled['error'] = ''
            cu_experience.save_store(BROCCOLI_APP_DATA_DIR, store)
            self._experience_rules_refresh()
            self._experience_compile_rule(rule_id)
        else:
            cu_experience.save_store(BROCCOLI_APP_DATA_DIR, store)
            self._experience_rules_refresh()

    def _experience_add_rule(self):
        store = cu_experience.load_store(BROCCOLI_APP_DATA_DIR)
        rule_id = f'user-{int(time.time() * 1000)}'
        rule = {
            'id': rule_id,
            'name': 'New experience rule',
            'provenance': cu_experience.PROVENANCE_USER,
            'enabled': True,
            'applies_to': {'app': 'any', 'task_shape': 'any'},
            'steps_nl': '',
            'rule_nl': '',
            'compiled': {
                'kind': '', 'payload': {}, 'nl_hash': '', 'compiled_at': '',
                'status': cu_experience.STATUS_PENDING, 'error': '',
            },
            'evidence': 'Created manually',
            'created_at': time.strftime('%Y-%m-%dT%H:%M:%S'),
            'updated_at': time.strftime('%Y-%m-%dT%H:%M:%S'),
        }
        store.setdefault('rules', []).append(rule)
        cu_experience.save_store(BROCCOLI_APP_DATA_DIR, store)
        self._experience_rules_refresh()
        try:
            self._experience_open_rule_row(len(getattr(self, '_experience_rule_ids', [])) - 1)
        except Exception:
            pass

    def _experience_compile_rule(self, rule_id: str):
        """Background AI compile: NL -> data-only operational form (non-blocking)."""
        generations = getattr(self, '_experience_compile_generation', None)
        if generations is None:
            generations = {}
            self._experience_compile_generation = generations
        generation = generations.get(rule_id, 0) + 1
        generations[rule_id] = generation
        store = cu_experience.load_store(BROCCOLI_APP_DATA_DIR)
        rule = cu_experience.find_rule(store, rule_id)
        if rule is None:
            return
        messages = cu_experience.build_compile_messages(rule)

        def apply_result(kind: str, payload: dict, error: str):
            if generations.get(rule_id) != generation:
                return  # superseded by a newer edit
            fresh_store = cu_experience.load_store(BROCCOLI_APP_DATA_DIR)
            fresh_rule = cu_experience.find_rule(fresh_store, rule_id)
            if fresh_rule is None:
                return
            compiled = fresh_rule.setdefault('compiled', {})
            if error:
                compiled['status'] = cu_experience.STATUS_FAILED
                compiled['error'] = error[:300]
            else:
                compiled.update({
                    'kind': kind,
                    'payload': payload,
                    'nl_hash': cu_experience.nl_hash(fresh_rule),
                    'compiled_at': time.strftime('%Y-%m-%dT%H:%M:%S'),
                    'status': cu_experience.STATUS_ACTIVE,
                    'error': '',
                })
            cu_experience.save_store(BROCCOLI_APP_DATA_DIR, fresh_store)
            self._experience_rules_refresh()

        def on_finished(text: str):
            kind, payload, error = cu_experience.parse_compiled_response(text)
            apply_result(kind, payload, error)

        def on_failed(error: str):
            apply_result('', {}, f'compile request failed: {error}')

        try:
            editor_llm_request(messages, None, on_finished, on_failed)
        except Exception as exc:
            apply_result('', {}, f'compile request could not start: {exc}')

    def _url_history_panel(self, kind: str):
        window = self.window()
        panel = getattr(window, 'ai_web_panel' if kind == 'web' else 'localhost_panel', None)
        return panel if panel is not None and hasattr(panel, 'url_history_entries') else None

    def _url_history_tables(self):
        return (
            ('web', getattr(self, 'web_url_history_table', None)),
            ('localhost', getattr(self, 'localhost_url_history_table', None)),
        )

    def _populate_url_history_tables(self):
        for kind, table in self._url_history_tables():
            if table is None:
                continue
            panel = self._url_history_panel(kind)
            self._set_url_history_table_entries(table, panel.url_history_entries() if panel is not None else [])

    def _apply_url_history_tables(self):
        for kind, table in self._url_history_tables():
            if table is None:
                continue
            panel = self._url_history_panel(kind)
            if panel is not None and hasattr(panel, 'replace_url_history'):
                panel.replace_url_history(self._url_history_table_entries(table))

    def _url_history_add_row(self, table):
        row = table.rowCount()
        table.insertRow(row)
        table.setItem(row, 0, QTableWidgetItem(''))
        table.setItem(row, 1, QTableWidgetItem(''))
        table.setCurrentCell(row, 1)
        item = table.item(row, 1)
        if item is not None:
            table.editItem(item)
        self._mark_dirty_if_needed()

    def _url_history_delete_row(self, table):
        row = table.currentRow()
        if row >= 0:
            table.removeRow(row)
            self._mark_dirty_if_needed()

    def _url_history_move_row(self, table, delta: int):
        row = table.currentRow()
        target = row + int(delta)
        if row < 0 or not (0 <= target < table.rowCount()):
            return
        for col in range(table.columnCount()):
            item_a = table.takeItem(row, col)
            item_b = table.takeItem(target, col)
            table.setItem(row, col, item_b)
            table.setItem(target, col, item_a)
        table.setCurrentCell(target, max(0, table.currentColumn()))
        self._mark_dirty_if_needed()

    def _set_prompt_page(self, index: int):
        if not hasattr(self, 'prompt_pages'):
            return
        index = max(0, min(self.prompt_pages.count() - 1, int(index)))
        self.prompt_pages.setCurrentIndex(index)
        self._update_prompt_page_controls()

    def _update_prompt_page_controls(self):
        if not hasattr(self, 'prompt_pages'):
            return
        index = self.prompt_pages.currentIndex()
        count = max(1, self.prompt_pages.count())
        if hasattr(self, 'prompt_page_label'):
            self.prompt_page_label.setText(f'{index + 1} / {count} ▾')
        if hasattr(self, 'prompt_prev_button'):
            self.prompt_prev_button.setEnabled(index > 0)
        if hasattr(self, 'prompt_next_button'):
            self.prompt_next_button.setEnabled(index < count - 1)

