        self.webfetch_context_embedding_checkbox.toggled.connect(self._mark_dirty_if_needed)
        self.generated_output_context_embedding_checkbox.toggled.connect(self._mark_dirty_if_needed)
        self.external_context_enabled_checkbox.toggled.connect(self._mark_dirty_if_needed)
        self.external_context_embedding_checkbox.toggled.connect(self._mark_dirty_if_needed)
        self.mcp_tool_runtime_checkbox.toggled.connect(self._mark_dirty_if_needed)
        self.code_execution_enabled_checkbox.toggled.connect(self._mark_dirty_if_needed)
        self.external_context_list_widget.currentItemChanged.connect(self._mark_dirty_if_needed)
        self.external_context_list_widget.itemChanged.connect(self._mark_dirty_if_needed)
        self.code_runner_list_widget.currentItemChanged.connect(self._mark_dirty_if_needed)
        self.code_runner_list_widget.itemChanged.connect(self._mark_dirty_if_needed)
        self.background_vision_enabled_checkbox.toggled.connect(self._mark_dirty_if_needed)
        self.background_vision_enabled_checkbox.toggled.connect(self._update_background_vision_controls)
        self.background_vision_show_overlay_checkbox.toggled.connect(self._mark_dirty_if_needed)
