# ---- M1: window shell, session, file bar, action bar, editor page ----

EDITOR_DATA_DIR = os.path.join(BROCCOLI_APP_DATA_DIR, 'Editor')

EDITOR_TEXT_EXTS = {
    '.py', '.txt', '.md', '.markdown', '.json', '.js', '.ts', '.jsx', '.tsx',
    '.html', '.htm', '.css', '.scss', '.sh', '.zsh', '.bash', '.c', '.cpp',
    '.cc', '.h', '.hpp', '.m', '.mm', '.java', '.kt', '.rb', '.go', '.rs',
    '.swift', '.php', '.pl', '.lua', '.sql', '.yaml', '.yml', '.toml', '.ini',
    '.cfg', '.conf', '.log', '.csv', '.tsv', '.xml', '.svg', '.tex', '.rst',
    '.applescript', '.plist',
}


def editor_supported_file(path):
    # A file the editor can open: an existing plain-text-ish file on disk.
    try:
        if not path or not os.path.isfile(path):
            return False
        ext = os.path.splitext(path)[1].lower()
        if ext in EDITOR_TEXT_EXTS:
            return True
        with open(path, 'rb') as f:
            chunk = f.read(8192)
        if b'\x00' in chunk:
            return False
        return True
    except Exception:
        return False


# ---- M8: article mode, generated output entry, cross-card links ----

def editor_output_record_path(output):
    output = output if isinstance(output, dict) else {}
    kind = str(output.get('kind', 'text') or 'text').strip().lower()
    path = str(output.get('path', '') or '').strip()
    if path and os.path.exists(path) and editor_supported_file(path):
        return os.path.abspath(path)
    if kind in {'image', 'audio', 'video'}:
        return ''
    content = str(output.get('content', '') or '')
    if not content.strip():
        return ''
    out_dir = os.path.join(EDITOR_DATA_DIR, 'outputs')
    try:
        os.makedirs(out_dir, exist_ok=True)
    except Exception:
        return ''
    default_name = default_output_filename(output)
    stem = sanitize_conversation_filename(Path(default_name).stem, max_len=60)
    if not stem:
        stem = sanitize_conversation_filename(str(output.get('title', '') or 'broccoli-output'), max_len=60) or 'broccoli-output'
    # extension drives editor kind detection — .md on python code made the
    # Logic Map parse it as article paragraphs
    ext = Path(default_name).suffix.lower()
    if kind == 'code':
        if ext in ('', '.txt', '.md', '.markdown'):
            try:
                _editor_ast.parse(content)  # module-level alias, bound at call time
                ext = '.py'
            except Exception:
                ext = ext or '.txt'
    elif ext not in EDITOR_TEXT_EXTS or not ext:
        ext = '.md'
    seed = str(output.get('id', '') or '').strip() or content
    suffix = int(hashlib.sha1(seed.encode('utf-8', 'replace')).hexdigest()[:8], 16) % 100000000
    target = os.path.join(out_dir, '%s-%d%s' % (stem, suffix, ext))
    try:
        if not os.path.exists(target):
            write_text_file(target, content)
        return target
    except Exception:
        return ''


# ---- FIX-3 round: conversation-bound editor file sets ----
# Each conversation remembers its own open-file set; switching conversations
# swaps the editor's pills. The unsaved conversation ('' cid) lives only in
# memory and migrates to the real cid on first save.
EDITOR_CONVERSATION_BINDINGS_PATH = os.path.join(EDITOR_DATA_DIR, 'conversations.json')


def editor_load_conversation_bindings():
    try:
        with open(EDITOR_CONVERSATION_BINDINGS_PATH, 'r', encoding='utf-8') as f:
            data = json.load(f)
        if not isinstance(data, dict):
            return {}
        if ICLOUD_M2_CONVERSATION_RESOLVER_ENABLED and isinstance(data.get('bindings'), dict):
            data = data.get('bindings') or {}
        if ICLOUD_M2_CONVERSATION_RESOLVER_ENABLED:
            normalized = {}
            for reference, binding in data.items():
                conversation_id = conversation_id_for_reference(str(reference or ''))
                if conversation_id and isinstance(binding, dict):
                    normalized[conversation_id] = binding
            return normalized
        return data
    except Exception:
        return {}


def editor_save_conversation_bindings(bindings):
    try:
        os.makedirs(EDITOR_DATA_DIR, exist_ok=True)
        payload = bindings if isinstance(bindings, dict) else {}
        if ICLOUD_M2_CONVERSATION_RESOLVER_ENABLED:
            payload = {
                'schema_version': 1,
                'key_kind': 'conversation_id',
                'bindings': {
                    conversation_id_for_reference(str(reference or '')): binding
                    for reference, binding in payload.items()
                    if conversation_id_for_reference(str(reference or '')) and isinstance(binding, dict)
                },
            }
        tmp = EDITOR_CONVERSATION_BINDINGS_PATH + '.tmp'
        with open(tmp, 'w', encoding='utf-8') as f:
            json.dump(payload, f, ensure_ascii=False, indent=1)
        os.replace(tmp, EDITOR_CONVERSATION_BINDINGS_PATH)
        return True
    except Exception:
        return False


_EDITOR_CODE_EXTS = {
    ext for ext in EDITOR_TEXT_EXTS
    if ext not in {'', '.txt', '.md', '.markdown', '.log', '.rst', '.csv', '.tsv'}
}
_EDITOR_AMBIGUOUS_EXTS = {'', '.txt', '.md', '.markdown', '.log', '.rst'}
EDITOR_KIND_CLASSIFIER = None
_EDITOR_KIND_CLASSIFY_ATTEMPTED = set()
_EDITOR_KIND_CLASSIFY_IN_FLIGHT = set()
_EDITOR_KIND_CLASSIFY_WORKERS = []
_EDITOR_KIND_CHANGE_CALLBACKS = []


def _editor_master_index_path():
    return os.path.join(EDITOR_DATA_DIR, 'index.json')


def _editor_load_master_index():
    try:
        with open(_editor_master_index_path(), 'r', encoding='utf-8') as f:
            data = json.load(f)
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}


def _editor_save_master_index(data):
    try:
        os.makedirs(EDITOR_DATA_DIR, exist_ok=True)
        with open(_editor_master_index_path(), 'w', encoding='utf-8') as f:
            json.dump(data if isinstance(data, dict) else {}, f, ensure_ascii=False, indent=2)
    except Exception:
        pass


def editor_kind_override_for_key(file_key):
    entry = _editor_load_master_index().get(str(file_key or ''))
    override = str((entry or {}).get('kind_override', '') or '').strip()
    return override if override in {'code', 'text-article'} else ''


def editor_set_kind_override(store, override):
    if store is None:
        return
    override = str(override or '').strip()
    data = _editor_load_master_index()
    entry = data.get(store.file_key) if isinstance(data.get(store.file_key), dict) else {}
    entry.update({
        'path': store.path,
        'name': os.path.basename(store.path),
        'kind': override if override in {'code', 'text-article'} else editor_sniff_file_kind(store.path, store.read_disk()) or 'text-article',
        'opened_at': datetime.datetime.now().isoformat(timespec='seconds'),
    })
    if override in {'code', 'text-article'}:
        entry['kind_override'] = override
    else:
        entry.pop('kind_override', None)
    data[store.file_key] = entry
    _editor_save_master_index(data)


def editor_file_text_sample(path, max_chars=24000):
    try:
        with open(path, 'r', encoding='utf-8', errors='replace') as f:
            return f.read(int(max_chars))
    except Exception:
        return ''


def editor_sniff_file_kind(path, text):
    ext = os.path.splitext(str(path or ''))[1].lower()
    if ext == '.py':
        return 'code-python'
    text = str(text or '')
    if ext in _EDITOR_CODE_EXTS and ext not in _EDITOR_AMBIGUOUS_EXTS:
        return 'code'
    lines = [line.rstrip() for line in text.splitlines()[:220]]
    nonblank = [line for line in lines if line.strip()]
    if not nonblank:
        return 'text-article'
    code_hits = 0
    prose_hits = 0
    code_re = re.compile(
        r'^\s*(def|class|import|from|if|elif|else:|for|while|try:|except|finally:|with|return|yield|await|async\s+def|'
        r'function|const|let|var|export|package|public|private|protected|static|#include)\b'
    )
    in_fence = False
    for line in nonblank:
        s = line.strip()
        if ext in {'.md', '.markdown', '.rst'} and re.match(r'^(```|~~~)', s):
            in_fence = not in_fence
            prose_hits += 1
            continue
        if in_fence:
            if code_re.search(line) or s.endswith((';', '{', '}')) or '=>' in s or ':=' in s:
                code_hits += 1
            continue
        if code_re.search(line) or s.endswith((';', '{', '}')) or '=>' in s or ':=' in s:
            code_hits += 1
        elif ext not in {'.md', '.markdown', '.rst'} and re.search(r'[{}();]\s*$', s) and not re.search(r'[。！？.!?]$', s):
            code_hits += 1
        if len(s) >= 28 and re.search(r'[。！？.!?]$', s) and len(s.split()) >= 5:
            prose_hits += 1
        elif ext in {'.md', '.markdown', '.rst'} and re.match(r'^\s{0,3}(#{1,6}\s+|\*\s+|-\s+|\d+\.\s+)', line):
            prose_hits += 1
    total = max(1, len(nonblank))
    code_ratio = code_hits / total
    prose_ratio = prose_hits / total
    if prose_ratio >= 0.42 and code_ratio < 0.50:
        return 'text-article'
    if code_ratio >= 0.42 or (code_hits >= 8 and code_ratio >= 0.30):
        return 'code'
    if ext in _EDITOR_AMBIGUOUS_EXTS and prose_ratio >= 0.35 and code_ratio < 0.18:
        return 'text-article'
    if ext in _EDITOR_AMBIGUOUS_EXTS and code_ratio < 0.10 and prose_hits:
        return 'text-article'
    return None


class _EditorKindClassifierWorker(QThread):
    finished_kind = pyqtSignal(str, str)

    def __init__(self, file_key, path, text, parent=None):
        super().__init__(parent)
        self._file_key = str(file_key or '')
        self._path = str(path or '')
        self._text = str(text or '')[:12000]
        self._stopped = False

    def stop(self):
        # The blocking network call cannot be interrupted; this only suppresses
        # the result emission so quit-time teardown never signals into a
        # half-destroyed app.
        self._stopped = True

    def run(self):
        kind = ''
        try:
            api_key, endpoint = load_runtime_openai_client_config()
            if api_key:
                client = create_openai_client(api_key, endpoint, min(20, int(load_saved_timeout() or 20)))
                model = str(read_text_file(BasePath + 'modelnow.txt', DEFAULT_MODEL) or '').strip() or DEFAULT_MODEL
                messages = [
                    {'role': 'system', 'content': 'Classify a file. Return ONLY JSON {"kind":"code"} or {"kind":"text-article"}.'},
                    {'role': 'user', 'content': 'File: %s\n\nSample:\n```\n%s\n```' % (os.path.basename(self._path), self._text)},
                ]
                # instructions ride in the user message — relay endpoints may
                # silently drop system items (see _EditorLLMWorker.run)
                messages = _merge_leading_system_messages_into_user(messages)
                response = create_chat_completion(client, endpoint=endpoint, model=model, messages=messages, temperature=0)
                content = str(getattr(response.choices[0].message, 'content', '') or '')
                raw = _editor_extract_json_object(content) if '_editor_extract_json_object' in globals() else content
                data = json.loads(raw)
                candidate = str(data.get('kind', '') or '').strip()
                if candidate in {'code', 'text-article'}:
                    kind = candidate
        except Exception:
            kind = ''
        if not self._stopped:
            self.finished_kind.emit(self._file_key, kind)


def _editor_kind_worker_finished(file_key, kind):
    _EDITOR_KIND_CLASSIFY_IN_FLIGHT.discard(str(file_key or ''))
    for worker in list(_EDITOR_KIND_CLASSIFY_WORKERS):
        try:
            if getattr(worker, '_file_key', '') == str(file_key or '') and not worker.isRunning():
                _EDITOR_KIND_CLASSIFY_WORKERS.remove(worker)
        except Exception:
            pass
    if kind not in {'code', 'text-article'}:
        return
    store = _EDITOR_STORES.get(str(file_key or ''))
    if store is None:
        return
    old_kind = store.file_kind()
    editor_set_kind_override(store, kind)
    if old_kind != kind:
        for callback in list(_EDITOR_KIND_CHANGE_CALLBACKS):
            try:
                callback(store.path, kind)
            except Exception:
                pass


def editor_start_async_kind_classification(store, text):
    if store is None or store.file_key in _EDITOR_KIND_CLASSIFY_IN_FLIGHT or store.file_key in _EDITOR_KIND_CLASSIFY_ATTEMPTED:
        return
    try:
        api_key, _endpoint = load_runtime_openai_client_config()
    except Exception:
        api_key = ''
    if not api_key:
        return
    _EDITOR_KIND_CLASSIFY_ATTEMPTED.add(store.file_key)
    _EDITOR_KIND_CLASSIFY_IN_FLIGHT.add(store.file_key)
    worker = _EditorKindClassifierWorker(store.file_key, store.path, text)
    worker.finished_kind.connect(_editor_kind_worker_finished, Qt.ConnectionType.QueuedConnection)
    worker.finished.connect(worker.deleteLater)
    _EDITOR_KIND_CLASSIFY_WORKERS.append(worker)
    worker.start()


def editor_classify_ambiguous_file_kind(store, text):
    if store is None:
        return 'text-article'
    classifier = globals().get('EDITOR_KIND_CLASSIFIER')
    try:
        if callable(classifier):
            kind = str(classifier(store.path, str(text or '')[:12000]) or '').strip()
            if kind in {'code', 'text-article'}:
                editor_set_kind_override(store, kind)
                return kind
    except Exception:
        pass
    editor_start_async_kind_classification(store, text)
    return 'text-article'


# ---- M2: persistent data layer (EditorStore) + full editor page ----

_EDITOR_STORES = {}


# ── writing an edited file back (2026-10-26, Ryan) ───────────────────────────────────────────
# The editor edits the file where it is (its history copies live under EDITOR_DATA_DIR). It used
# to write a temporary file in Broccoli's folder and move it over the original: the original's
# permissions (a script lost its executable bit), Finder tags and other extended attributes went
# with it, a symlinked path became a plain file (the real file unchanged), and every file was
# read and written as UTF-8 with LF line ends — one save ruined a Shift_JIS / GBK file and turned
# Windows line ends into LF. Now the bytes go INTO the original file, in its own encoding (with
# its BOM) and line ending.
_EDITOR_FILE_BOMS = ((b'\xef\xbb\xbf', 'utf-8'), (b'\xff\xfe', 'utf-16-le'), (b'\xfe\xff', 'utf-16-be'))
_EDITOR_LANGUAGE_ENCODINGS = {'Chinese': ('gb18030', 'big5'), 'Japanese': ('cp932', 'euc_jp'), 'Korean': ('euc_kr',)}
_EDITOR_ENCODING_LANGUAGE = {
    'cp932': 'Japanese', 'shift_jis': 'Japanese', 'shift_jis_2004': 'Japanese', 'euc_jp': 'Japanese',
    'euc_jis_2004': 'Japanese', 'gb18030': 'Chinese', 'gbk': 'Chinese', 'gb2312': 'Chinese', 'big5': 'Chinese',
    'big5hkscs': 'Chinese', 'euc_kr': 'Korean', 'cp949': 'Korean', 'johab': 'Korean'}
EDITOR_DEFAULT_FILE_FORMAT = {'encoding': 'utf-8', 'bom': b'', 'newline': '\n'}


def _editor_encoding_language_order():
    """The user's languages first (Settings → Languages, then the UI language), then Chinese,
    Japanese, Korean: a short CJK file fits several encodings equally well (a GBK file read
    as Korean cp949), and the user's own languages decide."""
    order = []
    try:
        for item in load_language_items() or []:
            key = str(language_alias_key(str(item)) or '').strip()
            if key:
                order.append(key.capitalize())
    except Exception:
        pass
    ui = {'zh_CN': 'Chinese', 'ja_JP': 'Japanese'}.get(read_ui_language_setting())
    for name in ([ui] if ui else []) + ['Chinese', 'Japanese', 'Korean', 'English']:
        if name not in order:
            order.append(name)
    return order


@functools.lru_cache(maxsize=8192)
def _editor_common_han(ch):
    """A Han character in everyday use: in GB2312, Big5's frequent level or JIS level 1."""
    try:
        ch.encode('gb2312')
        return True
    except UnicodeEncodeError:
        pass
    for codec, low, high in (('big5', b'\xa4\x40', b'\xc6\x7e'), ('cp932', b'\x88\x9f', b'\x98\x72')):
        try:
            if low <= ch.encode(codec) <= high:
                return True
        except UnicodeEncodeError:
            pass
    return False


def _editor_text_oddities(text, language):
    """How implausible a decoding looks (0 = nothing odd): control characters, private-use and
    presentation-form symbols, a word mixing Latin with another alphabet, kana in "Chinese",
    Han without Hangul in "Korean". Detectors tie on short files; this breaks most ties."""
    import unicodedata
    odd = kana = hangul = han = 0
    previous = None
    for ch in text[:20000]:
        code = ord(ch)
        if ch in '\t\n\r':
            previous = None
            continue
        if code < 32 or 0x7F <= code < 0xA0 or 0xE000 <= code <= 0xF8FF or 0xFB50 <= code <= 0xFDFF \
                or 0xFE70 <= code <= 0xFEFF or code == 0xFFFD or 0xFF61 <= code <= 0xFF9F:
            odd += 1
        if 0x3040 <= code <= 0x30FF:
            kana += 1
        elif 0xAC00 <= code <= 0xD7A3:
            hangul += 1
            try:
                ch.encode('euc_kr')   # the 2,350 everyday syllables
            except UnicodeEncodeError:
                odd += 1
        elif 0x4E00 <= code <= 0x9FFF or 0x3400 <= code <= 0x4DBF:
            han += 1
            if not _editor_common_han(ch):
                odd += 1   # a wrong decoding turns text into rare characters
        if ch.isalpha():
            script = unicodedata.name(ch, '').split(' ')[0]
            pair = {script, previous}
            if previous and script != previous and 'LATIN' in pair and not pair & {'CJK', 'HIRAGANA', 'KATAKANA', 'HANGUL'}:
                odd += 1
            previous = script
        else:
            previous = None
    if language == 'Chinese':
        odd += kana
    elif language == 'Korean' and han and not hangul:
        odd += han
    elif language == 'Japanese' and han >= 4 and not kana:
        odd += 1
    return odd


def editor_decode_file_bytes(data):
    """(text with \\n line ends, format) for a file's bytes; format = {'encoding', 'bom', 'newline'}.
    The encoding is one that gives back the very same bytes when the text is saved unchanged."""
    data = bytes(data or b'')
    bom, encoding, text = b'', None, None
    for mark, name in _EDITOR_FILE_BOMS:
        if data.startswith(mark):
            try:
                text, bom, encoding = data[len(mark):].decode(name), mark, name
            except UnicodeDecodeError:
                pass
            break
    if text is None:
        try:
            text, encoding = data.decode('utf-8'), 'utf-8'
        except UnicodeDecodeError:
            pass
    if text is None:
        languages = _editor_encoding_language_order()
        chaos = {}
        try:
            from charset_normalizer import from_bytes
            for match in from_bytes(data):
                if match.encoding and match.encoding not in chaos:
                    chaos[str(match.encoding)] = float(match.chaos)
        except Exception:
            pass
        names = list(chaos)
        for language in languages:
            names.extend(_EDITOR_LANGUAGE_ENCODINGS.get(language, ()))
        names.append('cp1252')
        scored = []
        preferred = [name for language in languages for name in _EDITOR_LANGUAGE_ENCODINGS.get(language, ())]
        for position, name in enumerate(dict.fromkeys(names)):
            # among equals: the language's usual encoding (gb18030 before big5 …), then the detector's
            order = preferred.index(name) if name in preferred else len(preferred) + position
            try:
                decoded = data.decode(name)
                if decoded.encode(name) != data:   # must give the same bytes back when saved
                    continue
            except (UnicodeError, LookupError):
                continue
            language = _EDITOR_ENCODING_LANGUAGE.get(name.lower().replace('-', '_'), 'English' if name == 'cp1252' else '')
            preference = languages.index(language) if language in languages else len(languages)
            scored.append([_editor_text_oddities(decoded, language), chaos.get(name, 0.5), preference, order, name, decoded])
        # the single-byte Western pages all look alike to the detector ("crème" as cp1250 "crčme"):
        # the common one, cp1252, is as good as the best of them
        western = [entry[1] for entry in scored
                   if entry[4] != 'cp1252' and _EDITOR_ENCODING_LANGUAGE.get(entry[4].lower().replace('-', '_')) is None]
        for entry in scored:
            if entry[4] == 'cp1252' and western:
                entry[1] = min([entry[1]] + western)
        for entry in scored:
            entry[1] = round(entry[1] / 0.05)
        scored = [tuple(entry) for entry in scored]
        if scored:
            _odd, _chaos, _preference, _order, encoding, text = min(scored)
    if text is None:
        text, encoding = data.decode('latin-1'), 'latin-1'   # nothing fits: every byte kept as it is
    crlf = text.count('\r\n')
    lone_cr = text.count('\r') - crlf
    lone_lf = text.count('\n') - crlf
    newline = '\r\n' if crlf > max(lone_lf, lone_cr) else ('\r' if lone_cr > max(lone_lf, crlf) else '\n')
    return text.replace('\r\n', '\n').replace('\r', '\n'), {'encoding': encoding, 'bom': bom, 'newline': newline}


def editor_encode_file_text(text, file_format):
    """The bytes for `text` in a file's own format. Raises UnicodeEncodeError when its encoding
    cannot hold some of the characters."""
    file_format = file_format or EDITOR_DEFAULT_FILE_FORMAT
    text = str(text or '').replace('\r\n', '\n').replace('\r', '\n')
    newline = file_format.get('newline') or '\n'
    if newline != '\n':
        text = text.replace('\n', newline)
    return bytes(file_format.get('bom') or b'') + text.encode(file_format.get('encoding') or 'utf-8')


def editor_unencodable_chars(text, encoding, limit=5):
    found = []
    for ch in dict.fromkeys(str(text or '')):
        try:
            ch.encode(encoding)
        except (UnicodeEncodeError, LookupError):
            found.append(ch)
            if len(found) >= limit:
                break
    return found


def editor_write_file(parent, store, text) -> bool:
    """Save an edited file (Cmd+S, an approved model edit, a revert). When it cannot be written,
    say why — and when only its encoding cannot hold the new text, offer UTF-8 instead."""
    if store.write_disk(text):
        return True
    error = getattr(store, 'last_write_error', None)
    if not error:
        return False
    name = os.path.basename(store.path)
    if error[0] == 'encoding':
        save_utf8 = _tr('Save as UTF-8')
        choice = ask_broccoli_message(
            parent, _tr('Save'),
            _tr('“{name}” is saved as {encoding}, which cannot hold some of the new characters ({chars}). '
                'Save it as UTF-8 instead?').format(name=name, encoding=error[1], chars=' '.join(error[2] or [])),
            [save_utf8, _tr('Cancel')], default_button_text=save_utf8, escape_button_text=_tr('Cancel'))
        if choice != save_utf8:
            return False
        if store.write_disk(text, encoding='utf-8'):
            return True
        error = getattr(store, 'last_write_error', None) or ('failed', '')
    if error[0] == 'read_only':
        message = _tr('“{name}” is read-only, so it was not saved.').format(name=name)
    else:
        message = _tr('“{name}” could not be saved: {reason}').format(name=name, reason=error[1] or '?')
    show_broccoli_message(parent, _tr('Not saved'), message)
    return False


class EditorStore:
    """Per-file persistent data under EDITOR_DATA_DIR/<file_key>/ (versions, lexicon, flows, cards)."""

    VALID_TRIGGERS = ('ai_edit', 'manual_save', 'pre_revert_backup', 'import')

    def __init__(self, abs_path):
        # Use EditorStore.for_path() — this ctor assumes an already-normalized abspath.
        self.path = abs_path
        self.file_key = hashlib.sha1(abs_path.encode('utf-8')).hexdigest()[:12]
        self.root = os.path.join(EDITOR_DATA_DIR, self.file_key)
        self.versions_dir = os.path.join(self.root, 'versions')
        self._last_own_mtime = None
        self._format = None          # the file's encoding / BOM / line ending as last read or written
        self._read_cache = None      # ((mtime_ns, size), text, format)
        self.last_write_error = None  # ('encoding', name, chars) / ('read_only', why) / ('failed', why)
        try:
            os.makedirs(self.versions_dir, exist_ok=True)
        except Exception:
            pass
        self._register_in_master_index()

    @classmethod
    def for_path(cls, abs_path):
        try:
            abs_path = os.path.abspath(str(abs_path))
        except Exception:
            return None
        if not abs_path:
            return None
        key = hashlib.sha1(abs_path.encode('utf-8')).hexdigest()[:12]
        store = _EDITOR_STORES.get(key)
        if store is None:
            store = cls(abs_path)
            _EDITOR_STORES[key] = store
        return store

    # ── tolerant json plumbing (corrupt file → .bad sidecar + fresh skeleton) ──
    def _write_json(self, path, data):
        try:
            tmp = path + '.tmp'
            with open(tmp, 'w', encoding='utf-8') as f:
                json.dump(data, f, ensure_ascii=False, indent=2)
            os.replace(tmp, path)
        except Exception:
            pass

    def _load_json(self, path, skeleton_factory):
        if os.path.exists(path):
            try:
                with open(path, 'r', encoding='utf-8') as f:
                    return json.load(f)
            except Exception:
                try:
                    os.replace(path, path + '.bad')
                except Exception:
                    pass
        data = skeleton_factory()
        self._write_json(path, data)
        return data

    def file_kind(self):
        override = editor_kind_override_for_key(self.file_key)
        if override:
            return override
        ext = os.path.splitext(self.path)[1].lower()
        sample = editor_file_text_sample(self.path)
        sniffed = editor_sniff_file_kind(self.path, sample)
        if sniffed:
            return sniffed
        if ext in _EDITOR_AMBIGUOUS_EXTS or ext not in EDITOR_TEXT_EXTS:
            return editor_classify_ambiguous_file_kind(self, sample)
        return 'code'

    def _register_in_master_index(self):
        idx_path = os.path.join(EDITOR_DATA_DIR, 'index.json')
        kind = self.file_kind()
        data = self._load_json(idx_path, dict)
        if not isinstance(data, dict):
            data = {}
        previous = data.get(self.file_key) if isinstance(data.get(self.file_key), dict) else {}
        entry = dict(previous)
        entry.update({
            'path': self.path,
            'name': os.path.basename(self.path),
            'kind': kind,
            'opened_at': datetime.datetime.now().isoformat(timespec='seconds'),
        })
        override = str(entry.get('kind_override', '') or '').strip()
        if override in {'code', 'text-article'}:
            entry['kind_override'] = override
        data[self.file_key] = entry
        self._write_json(idx_path, data)

    # ── versions ─────────────────────────────────────────────
    def _versions_index_path(self):
        return os.path.join(self.versions_dir, 'index.json')

    def _load_versions_index(self):
        data = self._load_json(self._versions_index_path(), lambda: {'versions': []})
        if not isinstance(data, dict) or not isinstance(data.get('versions'), list):
            try:
                os.replace(self._versions_index_path(), self._versions_index_path() + '.bad')
            except Exception:
                pass
            data = {'versions': []}
            self._write_json(self._versions_index_path(), data)
        return data

    def save_version(self, content, trigger, conversation_id='', turn=-1, note=''):
        if trigger not in self.VALID_TRIGGERS:
            trigger = 'manual_save'
        try:
            os.makedirs(self.versions_dir, exist_ok=True)
        except Exception:
            pass
        data = self._load_versions_index()
        versions = data.get('versions') or []
        ns = []
        for v in versions:
            try:
                ns.append(int(v.get('n', 0)))
            except Exception:
                continue
        n = 1 + max(ns or [0])
        while os.path.exists(os.path.join(self.versions_dir, 'v%04d.txt' % n)):
            n += 1
        try:
            with open(os.path.join(self.versions_dir, 'v%04d.txt' % n), 'w', encoding='utf-8') as f:
                f.write('' if content is None else str(content))
        except Exception:
            return -1
        try:
            turn = int(turn)
        except Exception:
            turn = -1
        versions.append({
            'n': n,
            'at': datetime.datetime.now().isoformat(timespec='seconds'),
            'trigger': trigger,
            'conversation_id': str(conversation_id or ''),
            'turn': turn,
            'note': str(note or ''),
            'reverted': False,
        })
        data['versions'] = versions
        self._write_json(self._versions_index_path(), data)
        return n

    def list_versions(self):
        # chronological — newest LAST
        data = self._load_versions_index()
        out = []
        for v in data.get('versions') or []:
            if isinstance(v, dict) and 'n' in v:
                out.append(dict(v))
        try:
            out.sort(key=lambda v: int(v.get('n', 0)))
        except Exception:
            pass
        return out

    def read_version(self, n):
        try:
            p = os.path.join(self.versions_dir, 'v%04d.txt' % int(n))
        except Exception:
            return None
        if not os.path.isfile(p):
            return None
        try:
            with open(p, 'r', encoding='utf-8', errors='replace') as f:
                return f.read()
        except Exception:
            return None

    def mark_reverted(self, ns, flag=True):
        wanted = set()
        for x in (ns if ns is not None else []):
            try:
                wanted.add(int(x))
            except Exception:
                continue
        if not wanted:
            return
        data = self._load_versions_index()
        changed = False
        for v in data.get('versions') or []:
            try:
                hit = isinstance(v, dict) and int(v.get('n', -1)) in wanted
            except Exception:
                hit = False
            if hit:
                v['reverted'] = bool(flag)
                changed = True
        if changed:
            self._write_json(self._versions_index_path(), data)

    def mark_turn_reverted(self, conversation_id, turn, flag=True):
        conversation_id = str(conversation_id or '')
        try:
            turn = int(turn)
        except Exception:
            return
        data = self._load_versions_index()
        changed = False
        for v in data.get('versions') or []:
            if not isinstance(v, dict):
                continue
            try:
                hit = (str(v.get('conversation_id', '')) == conversation_id
                       and int(v.get('turn', -2)) == turn)
            except Exception:
                hit = False
            if hit:
                v['reverted'] = bool(flag)
                changed = True
        if changed:
            self._write_json(self._versions_index_path(), data)

    # ── disk ─────────────────────────────────────────────────
    def _decoded(self, data, key):
        cached = self._read_cache
        if cached is not None and key is not None and cached[0] == key:
            return cached[1], cached[2]
        text, file_format = editor_decode_file_bytes(data)
        self._read_cache = (key, text, file_format) if key is not None else None
        return text, file_format

    def read_disk(self):
        """The file's text (line ends as \\n), decoded from its own encoding."""
        try:
            stat = os.stat(self.path)
            key = (stat.st_mtime_ns, stat.st_size)
            cached = self._read_cache
            if cached is not None and cached[0] == key:
                self._format = cached[2]
                return cached[1]
            with open(self.path, 'rb') as f:
                data = f.read()
            text, self._format = self._decoded(data, key)
            return text
        except Exception:
            return ''

    def file_format(self):
        """The encoding / BOM / line ending the file was last read or written with (None: not yet)."""
        return dict(self._format) if self._format else None

    def write_disk(self, text, encoding=None):
        """Write INTO the original file (the same file: its permissions, Finder tags and other
        extended attributes, hard links and a symlink's target all stay), in the encoding and line
        ending it has on disk. encoding: save in this one instead (the user chose UTF-8 when the
        file's own cannot hold new characters). False, with last_write_error, when it fails."""
        self.last_write_error = None
        payload = '' if text is None else str(text)
        old = None
        try:
            stat = os.stat(self.path)
            with open(self.path, 'rb') as f:
                old = f.read()
            file_format = self._decoded(old, (stat.st_mtime_ns, stat.st_size))[1]
        except FileNotFoundError:
            file_format = dict(self._format or EDITOR_DEFAULT_FILE_FORMAT)
        except Exception as exc:
            self.last_write_error = ('read_only' if isinstance(exc, PermissionError) else 'failed', str(exc))
            return False
        if encoding:
            file_format = dict(file_format, encoding=encoding,
                               bom=file_format.get('bom') if file_format.get('encoding') == encoding else b'')
        try:
            data = editor_encode_file_text(payload, file_format)
        except (UnicodeEncodeError, LookupError):
            self.last_write_error = ('encoding', str(file_format.get('encoding') or ''),
                                     editor_unencodable_chars(payload, file_format.get('encoding') or 'utf-8'))
            return False
        try:
            with open(self.path, 'r+b' if old is not None else 'wb') as f:
                f.seek(0)
                f.write(data)
                f.truncate()
                f.flush()
                try:
                    os.fsync(f.fileno())
                except OSError:
                    pass
        except Exception as exc:
            if old is not None:   # put back what was there: a half-written file is worse
                try:
                    with open(self.path, 'r+b') as f:
                        f.seek(0)
                        f.write(old)
                        f.truncate()
                except Exception:
                    pass
            self.last_write_error = ('read_only' if isinstance(exc, PermissionError) else 'failed', str(exc))
            return False
        self._format = file_format
        self._read_cache = None
        self._last_own_mtime = self.disk_mtime()
        return True

    def disk_mtime(self):
        try:
            return os.path.getmtime(self.path)
        except Exception:
            return None

    # ── lexicon / flows / cards cache ────────────────────────
    def lexicon_language(self):
        lang = ''
        try:
            items = load_language_items()
            if items:
                lang = str(items[0]).strip()
        except Exception:
            lang = ''
        return lang or 'English'

    def _lexicon_skeleton(self):
        kind = self.file_kind()
        if kind == 'text-article':
            categories = ['Paragraph', 'Person', 'Concept']
        else:
            categories = ['Variable', 'Function', 'Class', 'Signal', 'Other']
        return {'file': self.path, 'language': self.lexicon_language(),
                'kind': kind, 'categories': categories, 'entries': []}

    def _lexicon_path(self):
        return os.path.join(self.root, 'lexicon.%s.json' % self.lexicon_language())

    def load_lexicon(self):
        return self._load_json(self._lexicon_path(), self._lexicon_skeleton)

    def save_lexicon(self, d):
        self._write_json(self._lexicon_path(), d if isinstance(d, dict) else self._lexicon_skeleton())

    def _flows_path(self):
        return os.path.join(self.root, 'flows.%s.json' % self.lexicon_language())

    def load_flows(self):
        return self._load_json(self._flows_path(), lambda: {'flows': []})

    def save_flows(self, d):
        self._write_json(self._flows_path(), d if isinstance(d, dict) else {'flows': []})

    def load_cards_cache(self):
        return self._load_json(os.path.join(self.root, 'cards_cache.json'), dict)

    def save_cards_cache(self, d):
        self._write_json(os.path.join(self.root, 'cards_cache.json'), d if isinstance(d, dict) else {})

    # ---- FIX-38: Debug tab bug ledger ----
    @staticmethod
    def _debug_skeleton():
        return {'bugs': [], 'last_scan': {}}

    def load_debug(self):
        data = self._load_json(os.path.join(self.root, 'debug.json'), self._debug_skeleton)
        if not isinstance(data, dict) or not isinstance(data.get('bugs'), list):
            data = self._debug_skeleton()
        return data

    def save_debug(self, d):
        self._write_json(os.path.join(self.root, 'debug.json'),
                         d if isinstance(d, dict) else self._debug_skeleton())


class EditorSession(QObject):
    file_selected = pyqtSignal(str)
    files_changed = pyqtSignal()
    file_content_reloaded = pyqtSignal(str)

    def __init__(self, parent=None):
        super().__init__(parent)
        self.open_files = []
        self.current_path = None
        self.edit_target = None  # user-designated modification target for AI edits

    def set_edit_target(self, path):
        path = str(path) if path else None
        if path is not None and path not in self.open_files:
            return
        if path == self.edit_target:
            return
        self.edit_target = path
        self.files_changed.emit()

    def add_file(self, path):
        try:
            path = os.path.abspath(str(path))
        except Exception:
            return False
        if not editor_supported_file(path):
            return False
        if path not in self.open_files:
            self.open_files.append(path)
            self.files_changed.emit()
        return True

    def remove_file(self, path):
        if path not in self.open_files:
            return
        idx = self.open_files.index(path)
        self.open_files.remove(path)
        if self.edit_target == path:
            self.edit_target = None
        self.files_changed.emit()
        if self.current_path == path:
            if self.open_files:
                neighbor = self.open_files[min(idx, len(self.open_files) - 1)]
                self.select_file(neighbor)
            else:
                self.current_path = None
                self.file_selected.emit('')

    def select_file(self, path):
        if not path or path not in self.open_files:
            return
        if path == self.current_path:
            return
        self.current_path = path
        self.file_selected.emit(path)

    def store(self, path=None):
        # ---- M2 ----
        target = path or self.current_path
        if not target:
            return None
        return EditorStore.for_path(target)


class _EditorPlaceholderPage(QWidget):
    """Simple stand-in page until the real page arrives (Snapshots/Compare M3, Logic Map M6)."""

    def __init__(self, title, parent=None):
        super().__init__(parent)
        self._label = QLabel(_tr('{title} — coming in a later update').format(title=title), self)
        self._label.setAlignment(Qt.AlignmentFlag.AlignCenter)
        lay = QVBoxLayout(self)
        lay.setContentsMargins(0, 0, 0, 0)
        lay.addStretch(1)
        lay.addWidget(self._label)
        lay.addStretch(1)
        try:
            self.set_theme(is_dark_theme(app))
        except Exception:
            pass

    def set_theme(self, dark_mode):
        color = '#8E8E93' if dark_mode else '#A0A0A6'
        self._label.setStyleSheet(f'color: {color}; font-size: 13px; background: transparent;')


class EditorFilePill(QWidget):
    """One open-file pill inside EditorFileBar — icon-less NavSitePill look."""
    clicked_sig = pyqtSignal()
    close_requested = pyqtSignal()
    compare_requested = pyqtSignal()
    edit_target_requested = pyqtSignal()
    HEIGHT = 34
    MIN_ACTIVE_W = 190

    def __init__(self, path, active=False, parent=None):
        super().__init__(parent)
        self._path = path
        self._active = bool(active)
        self._dirty = False
        self._stale = False
        self._edit_target = False
        self._hovered = False
        w = self.MIN_ACTIVE_W if active else self.compact_width()
        self._cur_w = w
        self.setFixedSize(w, self.HEIGHT)
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground)
        # NavSitePill-style ease-out-cubic width animation
        self._t0 = w
        self._t1 = w
        self._prog = 1.0
        self._timer = QTimer(self)
        self._timer.setInterval(14)
        self._timer.timeout.connect(self._tick)
        # FIX-36: position animates on the SAME clock/progress as width
        self._x0 = 0
        self._x1 = 0
        self._y = 0
        self._has_pos = False

    def compact_width(self):
        try:
            fm = self.fontMetrics()
            w = fm.horizontalAdvance(os.path.basename(self._path)) + 28
        except Exception:
            w = 90
        return max(46, min(132, w))

    def set_target_width(self, target, animated=False):
        target = max(24, int(target or 24))
        if animated and target != self._cur_w:
            self._t0 = self._cur_w
            self._t1 = target
            self._x0 = self._x1 = self.x()   # width-only path keeps position still
            self._prog = 0.0
            self._timer.start()
            return
        self._timer.stop()
        self._cur_w = target
        self._t0 = target
        self._t1 = target
        self._x0 = self._x1 = self.x()
        self._prog = 1.0
        self.setFixedWidth(target)
        self.update()

    def set_target_geometry(self, x, y, target_w, animated=False):
        """FIX-36: position + width animate on ONE clock (shared _prog/easing) —
        the bar-computed slot is glided to, never teleported (see NavSitePill)."""
        x = int(x)
        y = int(y)
        target_w = max(24, int(target_w or 24))
        self._y = y
        if not animated or not self._has_pos:
            first_layout = not self._has_pos
            self._has_pos = True
            self._x0 = self._x1 = x
            self.move(x, y)
            if animated and first_layout and self._cur_w != target_w:
                # first layout of a NEW pill: position snaps into its slot (no
                # (0,0) fly-in) but the WIDTH keeps the pre-FIX36 grow ease
                self._t0 = self._cur_w
                self._t1 = target_w
                self._prog = 0.0
                self._timer.start()
                return
            self._timer.stop()
            self._prog = 1.0
            self._cur_w = target_w
            self._t0 = self._t1 = target_w
            self.setFixedWidth(target_w)
            self.update()
            return
        if self._timer.isActive() and self._x1 == x and self._t1 == target_w:
            return  # same targets — let the running animation finish
        if not self._timer.isActive() and self._cur_w == target_w and self.x() == x and self.y() == y:
            return  # already at rest on target
        # retarget: rebase to CURRENT values (value-continuous) + fresh ease
        self._x0 = self.x()
        self._t0 = self._cur_w
        self._x1 = x
        self._t1 = target_w
        self._prog = 0.0
        self._timer.start()

    def _tick(self):
        self._prog = min(1.0, self._prog + 0.08)
        t = 1.0 - (1.0 - self._prog) ** 3
        self._cur_w = int(self._t0 + (self._t1 - self._t0) * t)
        self.setFixedWidth(max(24, self._cur_w))
        if self._has_pos and self._x0 != self._x1:
            self.move(int(round(self._x0 + (self._x1 - self._x0) * t)), self._y)
        p = self.parentWidget()
        if p:
            p.update()
        if self._prog >= 1.0:
            self._timer.stop()

    def enterEvent(self, event):
        self._hovered = True
        self.update()
        super().enterEvent(event)

    def leaveEvent(self, event):
        self._hovered = False
        self.update()
        super().leaveEvent(event)

    def mousePressEvent(self, event):
        if event.button() == Qt.MouseButton.LeftButton:
            self.clicked_sig.emit()

    def contextMenuEvent(self, event):
        menu = style_broccoli_context_menu(QMenu(self))
        close_act = menu.addAction(_tr('Close'))
        reveal_act = menu.addAction(_tr('Reveal in Finder'))
        menu.addSeparator()
        compare_act = menu.addAction(_tr('Add to Compare'))  # M3: live
        target_act = menu.addAction(_tr('Unset Edit Target') if self._edit_target else _tr('Set as Edit Target'))
        act = menu.exec(event.globalPos())
        if act == close_act:
            self.close_requested.emit()
        elif act == reveal_act:
            try:
                subprocess.Popen(['open', '-R', self._path])
            except Exception:
                pass
        elif act == compare_act:
            self.compare_requested.emit()
        elif act == target_act:
            self.edit_target_requested.emit()

    def paintEvent(self, event):
        painter = QPainter(self)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)
        dark = is_dark_theme(app)
        r = self.height() / 2.0
        painter.setPen(Qt.PenStyle.NoPen)
        # FIX-36: the active gray fill is now painted by EditorFileBar as a LERPED
        # highlight rect (glides old→new, no hard flip). The pill keeps hover only.
        if self._hovered and not self._active:
            painter.setBrush(QBrush(QColor(255, 255, 255, 24) if dark else QColor(0, 0, 0, 18)))
            painter.drawRoundedRect(QRectF(0, 0, self.width(), self.height()), r, r)
        if self._edit_target:
            # accent ring = this file is the designated modification target
            painter.setBrush(Qt.BrushStyle.NoBrush)
            pen = QPen(QColor('#0A84FF'))
            pen.setWidthF(1.6)
            painter.setPen(pen)
            ring = QRectF(1.0, 1.0, self.width() - 2.0, self.height() - 2.0)
            painter.drawRoundedRect(ring, r - 1.0, r - 1.0)
            painter.setPen(Qt.PenStyle.NoPen)
        if self._active:
            text_color = QColor('#F2F2F7' if dark else '#111111')
        else:
            text_color = QColor('#B8B8B8' if dark else '#777777')
        name = os.path.basename(self._path)
        right_pad = 12 + (10 if (self._dirty or self._stale) else 0)
        text_rect = QRect(12, 0, max(0, self.width() - 12 - right_pad), self.height())
        painter.setPen(QPen(text_color))
        f = painter.font()
        f.setPixelSize(12)
        painter.setFont(f)
        fm = painter.fontMetrics()
        elided = fm.elidedText(name, Qt.TextElideMode.ElideMiddle, max(10, text_rect.width()))
        painter.drawText(text_rect, Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft, elided)
        # dirty = small filled dot; stale (disk changed) = orange dot above it
        dot_x = self.width() - 14
        if self._dirty:
            painter.setPen(Qt.PenStyle.NoPen)
            painter.setBrush(QBrush(text_color))
            painter.drawEllipse(QPoint(dot_x, self.height() // 2), 3, 3)
        if self._stale:
            painter.setPen(Qt.PenStyle.NoPen)
            painter.setBrush(QBrush(QColor('#FF9F0A')))
            painter.drawEllipse(QPoint(dot_x, 8), 3, 3)
        painter.end()


class EditorFileBar(QWidget):
    """40px pill strip of open files — mimics WebNavBar's look (not its web coupling)."""
    file_selected = pyqtSignal(str)
    file_close_requested = pyqtSignal(str)
    files_add_requested = pyqtSignal(list)
    compare_requested = pyqtSignal(str)
    edit_target_requested = pyqtSignal(str)

    def __init__(self, parent=None):
        super().__init__(parent)
        self._paths = []
        self._current = None
        self._pills = []
        self._dirty = {}
        self._stale = {}
        self._edit_target_path = None
        self._scroll_offset = 0
        self._max_scroll_offset = 0
        self._layout_margin = 3
        self._layout_spacing = 4
        self._ensure_active_visible = False
        # FIX-36: lerped highlight rect (same mechanism as WebNavBar); the active
        # gray fill moved here from EditorFilePill.paintEvent so it can glide.
        self._hl_rect = QRect()
        self._hl_start = QRect()
        self._hl_end = QRect()
        self._hl_prog = 1.0
        self._hl_timer = QTimer(self)
        self._hl_timer.setInterval(14)
        self._hl_timer.timeout.connect(self._hl_tick)
        self.setFixedHeight(40)
        shadow = QGraphicsDropShadowEffect(self)
        shadow.setBlurRadius(40)
        shadow.setXOffset(0)
        shadow.setYOffset(0)
        shadow.setColor(QColor(0, 0, 0, 40))
        self.setGraphicsEffect(shadow)
        plus_icon = resource_path('plus2.png')
        self._plus_btn = AssistantFixedCircleButton(
            '+', self, icon_path=plus_icon if os.path.exists(plus_icon) else '')
        self._plus_btn.clicked.connect(self._on_add_clicked)

    def set_files(self, paths, current):
        paths = [str(p) for p in (paths or [])]
        # M3 (defect 4a): closed files must not keep ghost dirty/stale badges
        keep = set(paths)
        for d in (self._dirty, self._stale):
            for k in list(d.keys()):
                if k not in keep:
                    d.pop(k, None)
        if paths == self._paths and self._pills:
            changed = current != self._current
            self._current = current
            for pill in self._pills:
                pill._active = (pill._path == current)
                pill.update()
            self._ensure_active_visible = True
            self._relayout_pills(animated=changed)
            return
        for pill in self._pills:
            try:
                pill.hide()
                pill.deleteLater()
            except Exception:
                pass
        self._pills = []
        self._paths = paths
        self._current = current
        for path in self._paths:
            pill = EditorFilePill(path, active=(path == current), parent=self)
            pill._dirty = bool(self._dirty.get(path))
            pill._stale = bool(self._stale.get(path))
            pill._edit_target = (path == self._edit_target_path)
            pill.clicked_sig.connect(lambda p=path: self.file_selected.emit(p))
            pill.close_requested.connect(lambda p=path: self.file_close_requested.emit(p))
            pill.compare_requested.connect(lambda p=path: self.compare_requested.emit(p))
            pill.edit_target_requested.connect(lambda p=path: self.edit_target_requested.emit(p))
            pill.show()
            self._pills.append(pill)
        self._ensure_active_visible = True
        self._relayout_pills(animated=False)

    # ── FIX-36: highlight rect animation (clone of WebNavBar's) ─────
    def _hl_tick(self):
        self._hl_prog = min(1.0, self._hl_prog + 0.08)
        t = 1.0 - (1.0 - self._hl_prog) ** 3
        self._hl_rect = _pill_lerp_rect(self._hl_start, self._hl_end, t)
        self.update()
        if self._hl_prog >= 1.0:
            self._hl_timer.stop()

    def _set_highlight_target(self, rect, animated):
        rect = QRect(rect) if rect is not None else QRect()
        if not rect.isValid():
            self._hl_timer.stop()
            self._hl_rect = QRect()
            self._hl_start = QRect()
            self._hl_end = QRect()
            self._hl_prog = 1.0
            self.update()
            return
        if not animated or not self._hl_rect.isValid():
            self._hl_timer.stop()
            self._hl_rect = QRect(rect)
            self._hl_start = QRect(rect)
            self._hl_end = QRect(rect)
            self._hl_prog = 1.0
            self.update()
            return
        if self._hl_timer.isActive() and self._hl_end == rect:
            return
        if not self._hl_timer.isActive() and self._hl_rect == rect:
            self._hl_end = QRect(rect)
            return
        self._hl_start = QRect(self._hl_rect)
        self._hl_end = QRect(rect)
        self._hl_prog = 0.0
        self._hl_timer.start()

    def set_dirty(self, path, dirty):
        self._dirty[path] = bool(dirty)
        for pill in self._pills:
            if pill._path == path:
                pill._dirty = bool(dirty)
                pill.update()

    def set_stale(self, path, stale):
        self._stale[path] = bool(stale)
        for pill in self._pills:
            if pill._path == path:
                pill._stale = bool(stale)
                pill.update()

    def set_edit_target(self, path):
        self._edit_target_path = str(path) if path else None
        for pill in self._pills:
            flag = (pill._path == self._edit_target_path)
            if pill._edit_target != flag:
                pill._edit_target = flag
                pill.update()

    # ---- M2 ----
    def is_dirty(self, path):
        return bool(self._dirty.get(path))

    def is_stale(self, path):
        return bool(self._stale.get(path))

    def set_theme(self, dark_mode):
        for pill in self._pills:
            pill.update()
        self._plus_btn.update()
        self.update()

    def _on_add_clicked(self):
        try:
            files, _ = QFileDialog.getOpenFileNames(self, _tr('Open Files'))
        except Exception:
            files = []
        if files:
            self.files_add_requested.emit(list(files))

    def _relayout_pills(self, animated=False):
        if not hasattr(self, '_plus_btn'):
            return
        margin = self._layout_margin
        spacing = self._layout_spacing
        ph = EditorFilePill.HEIGHT
        y = max(0, (self.height() - ph) // 2)
        plus_w = self._plus_btn.width()
        plus_x = max(margin, self.width() - margin - plus_w)
        self._plus_btn.move(plus_x, y)
        left = margin
        right = max(left, plus_x - spacing)
        available = max(0, right - left)
        count = len(self._pills)
        if count == 0:
            self._set_highlight_target(QRect(), False)
            self._plus_btn.raise_()
            self.update()
            return
        widths = []
        active_idx = -1
        for i, pill in enumerate(self._pills):
            if pill._active:
                active_idx = i
                widths.append(0)
            else:
                widths.append(pill.compact_width())
        gaps = spacing * max(0, count - 1)
        if active_idx >= 0:
            inactive_total = sum(w for i, w in enumerate(widths) if i != active_idx)
            expand = available - inactive_total - gaps
            w_active = max(EditorFilePill.MIN_ACTIVE_W, expand)
            if available >= EditorFilePill.MIN_ACTIVE_W:
                w_active = min(w_active, available)
            widths[active_idx] = w_active
        logical = []
        x = 0
        for i, w in enumerate(widths):
            logical.append(x)
            x += w + (spacing if i < count - 1 else 0)
        content = x
        self._max_scroll_offset = max(0, content - available)
        self._scroll_offset = max(0, min(int(self._scroll_offset), self._max_scroll_offset))
        if self._ensure_active_visible and active_idx >= 0:
            item_l = logical[active_idx]
            item_r = item_l + widths[active_idx]
            if item_l < self._scroll_offset:
                self._scroll_offset = item_l
            elif item_r > self._scroll_offset + available:
                self._scroll_offset = item_r - available
            self._scroll_offset = max(0, min(int(self._scroll_offset), self._max_scroll_offset))
            self._ensure_active_visible = False
        for i, pill in enumerate(self._pills):
            # FIX-36: position + width on one animation clock (no more teleport-move)
            pill.set_target_geometry(int(left + logical[i] - self._scroll_offset), y,
                                     widths[i], animated=animated)
        # FIX-36: highlight glides to the freshly computed active slot on every pass
        if 0 <= active_idx < count:
            self._set_highlight_target(
                QRect(int(left + logical[active_idx] - self._scroll_offset), y,
                      int(widths[active_idx]), EditorFilePill.HEIGHT),
                animated)
        else:
            self._set_highlight_target(QRect(), False)
        if 0 <= active_idx < count:
            self._pills[active_idx].raise_()
        self._plus_btn.raise_()
        self.update()

    def resizeEvent(self, event):
        super().resizeEvent(event)
        self._relayout_pills(animated=False)

    def wheelEvent(self, event):
        if self._max_scroll_offset <= 0:
            event.ignore()
            return
        delta = 0
        try:
            pixel = event.pixelDelta()
            if not pixel.isNull():
                delta = pixel.x() or pixel.y()
            else:
                ang = event.angleDelta()
                delta = (ang.x() or ang.y()) / 3
        except Exception:
            delta = 0
        if delta:
            self._scroll_offset = max(0, min(int(self._scroll_offset - delta), self._max_scroll_offset))
            self._relayout_pills(animated=False)
        event.accept()

    def paintEvent(self, event):
        painter = QPainter(self)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)
        h = self.height()
        r = h / 2.0
        painter.setPen(Qt.PenStyle.NoPen)
        dark = is_dark_theme(app)
        glass = getattr(self, '_liquid_glass_active', False)   # the bar itself is the glass then
        if not glass:
            painter.setBrush(QBrush(QColor('#2D2D2D' if dark else '#FFFFFF')))
            painter.drawRoundedRect(0, 0, self.width(), h, r, r)
        # FIX-36: lerped active highlight (moved from EditorFilePill so it glides
        # old→new instead of hard-flipping with the _active boolean). Pills paint
        # on top of this (children are painted after the parent).
        if self._hl_rect.isValid() and self._hl_end.isValid():
            pr = self._hl_rect.height() / 2.0
            if glass:
                painter.setBrush(QBrush(QColor(255, 255, 255, 34) if dark else QColor(0, 0, 0, 20)))
            else:
                painter.setBrush(QBrush(QColor('#3A3A3A' if dark else '#DEDEDE')))
            painter.drawRoundedRect(QRectF(self._hl_rect), pr, pr)
        painter.end()


class EditorCapsuleButton(QPushButton):
    """Text capsule inside EditorActionBar — AssistantBar-style hover treatment."""

    def __init__(self, text, parent=None):
        super().__init__(text, parent)
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.setFocusPolicy(Qt.FocusPolicy.NoFocus)
        self.setFixedHeight(28)
        try:
            self.apply_capsule_theme(is_dark_theme(app))
        except Exception:
            self.apply_capsule_theme(False)

    def apply_capsule_theme(self, dark_mode):
        fg = '#F2F2F7' if dark_mode else '#333333'
        disabled = '#8E8E93' if dark_mode else '#A0A0A6'
        hover = 'rgba(255,255,255,34)' if dark_mode else 'rgba(0,0,0,26)'
        pressed = 'rgba(255,255,255,52)' if dark_mode else 'rgba(0,0,0,38)'
        self.setStyleSheet(
            "QPushButton { background: transparent; border: none; border-radius: 14px;"
            f" padding: 4px 14px; color: {fg}; font-size: 12px; }}"
            f" QPushButton:hover {{ background: {hover}; }}"
            f" QPushButton:pressed {{ background: {pressed}; }}"
            f" QPushButton:disabled {{ color: {disabled}; }}"
        )


class EditorActionBar(QWidget):
    """Bottom capsule bar (Open In / Reveal in Finder / Save / Re-dock / Re-parse)."""
    save_requested = pyqtSignal()
    reparse_requested = pyqtSignal()

    def __init__(self, window, parent=None):
        super().__init__(parent)
        self._win = window
        self.setFixedHeight(40)
        shadow = QGraphicsDropShadowEffect(self)
        shadow.setBlurRadius(40)
        shadow.setXOffset(0)
        shadow.setYOffset(0)
        shadow.setColor(QColor(0, 0, 0, 40))
        self.setGraphicsEffect(shadow)
        hbox = QHBoxLayout(self)
        hbox.setContentsMargins(10, 3, 10, 3)
        hbox.setSpacing(6)
        self.open_in_btn = EditorCapsuleButton(_tr('Open In'), self)
        self.open_in_btn.clicked.connect(self._show_open_in_menu)
        self.reveal_btn = EditorCapsuleButton(_tr('Reveal in Finder'), self)
        self.reveal_btn.clicked.connect(self._reveal_in_finder)
        self.save_btn = EditorCapsuleButton(_tr('Save'), self)
        self.save_btn.clicked.connect(self.save_requested)
        self.type_btn = EditorCapsuleButton(_tr('Type'), self)
        self.type_btn.clicked.connect(self._show_type_menu)
        self.redock_btn = EditorCapsuleButton(_tr('Re-dock'), self)
        self.redock_btn.clicked.connect(self._redock)
        self.reparse_btn = EditorCapsuleButton(_tr('Re-parse'), self)
        self.reparse_btn.setEnabled(False)  # functional in M6
        self.reparse_btn.clicked.connect(self.reparse_requested)
        hbox.addWidget(self.open_in_btn)
        hbox.addWidget(self.reveal_btn)
        hbox.addWidget(self.save_btn)
        hbox.addWidget(self.type_btn)
        hbox.addStretch(1)
        hbox.addWidget(self.redock_btn)
        hbox.addWidget(self.reparse_btn)

    def _current_path(self):
        try:
            return self._win.session.current_path
        except Exception:
            return None

    def _launch_open(self, args):
        try:
            subprocess.Popen(args)
        except Exception:
            pass

    def _show_open_in_menu(self):
        path = self._current_path()
        menu = style_broccoli_context_menu(QMenu(self))
        default_act = menu.addAction(_tr('Default App'))
        vscode_act = menu.addAction(_tr('VS Code'))
        textedit_act = menu.addAction(_tr('TextEdit'))
        menu.addSeparator()
        choose_act = menu.addAction(_tr('Choose Application…'))
        if not path:
            for a in (default_act, vscode_act, textedit_act, choose_act):
                a.setEnabled(False)
        pos = self.open_in_btn.mapToGlobal(QPoint(0, self.open_in_btn.height() + 4))
        act = menu.exec(pos)
        if act is None or not path:
            return
        if act == default_act:
            self._launch_open(['open', path])
        elif act == vscode_act:
            self._launch_open(['open', '-a', 'Visual Studio Code', path])
        elif act == textedit_act:
            self._launch_open(['open', '-a', 'TextEdit', path])
        elif act == choose_act:
            try:
                app_path, _ = QFileDialog.getOpenFileName(
                    self, _tr('Choose Application'), '/Applications', _tr('Applications (*.app)'))
            except Exception:
                app_path = ''
            if app_path:
                self._launch_open(['open', '-a', app_path, path])

    def _reveal_in_finder(self):
        path = self._current_path()
        if path:
            self._launch_open(['open', '-R', path])

    def _show_type_menu(self):
        path = self._current_path()
        store = self._win.session.store(path) if path else None
        menu = style_broccoli_context_menu(QMenu(self))
        auto_act = menu.addAction(_tr('Auto'))
        code_act = menu.addAction(_tr('Code'))
        article_act = menu.addAction(_tr('Article'))
        for act in (auto_act, code_act, article_act):
            act.setCheckable(True)
        override = editor_kind_override_for_key(store.file_key) if store is not None else ''
        if override == 'code':
            code_act.setChecked(True)
        elif override == 'text-article':
            article_act.setChecked(True)
        else:
            auto_act.setChecked(True)
        if store is None:
            for act in (auto_act, code_act, article_act):
                act.setEnabled(False)
        pos = self.type_btn.mapToGlobal(QPoint(0, self.type_btn.height() + 4))
        act = menu.exec(pos)
        if store is None or act is None:
            return
        if act is auto_act:
            self._win.set_file_kind_override('')
        elif act is code_act:
            self._win.set_file_kind_override('code')
        elif act is article_act:
            self._win.set_file_kind_override('text-article')

    def _redock(self):
        try:
            self._win.position_beside_main(animated=True)
        except Exception:
            pass

    def set_theme(self, dark_mode):
        for btn in (self.open_in_btn, self.reveal_btn, self.save_btn,
                    self.type_btn, self.redock_btn, self.reparse_btn):
            btn.apply_capsule_theme(dark_mode)
        self.update()

    def paintEvent(self, event):
        if getattr(self, '_liquid_glass_active', False):
            return   # the bar itself is the glass (install_inwindow_bar_glass), like AssistantBar
        painter = QPainter(self)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)
        h = self.height()
        r = h / 2.0
        painter.setPen(Qt.PenStyle.NoPen)
        dark = is_dark_theme(app)
        painter.setBrush(QBrush(QColor('#2D2D2D' if dark else '#FFFFFF')))
        painter.drawRoundedRect(0, 0, self.width(), h, r, r)
        painter.end()


class _EditorLineNumberArea(QWidget):
    def __init__(self, editor):
        super().__init__(editor)
        self._editor = editor

    def sizeHint(self):
        return QSize(self._editor.line_number_area_width(), 0)

    def paintEvent(self, event):
        self._editor.line_number_area_paint_event(event)


class EditorCodeEdit(QPlainTextEdit):
    """QPlainTextEdit with a left line-number gutter (standard Qt recipe)."""

    def __init__(self, parent=None):
        super().__init__(parent)
        try:
            f = QFont('Menlo')
            f.setPixelSize(12)  # match the 12px stylesheet so the gutter aligns
            self.setFont(f)
        except Exception:
            pass
        self._ln_area = _EditorLineNumberArea(self)
        self._ln_bg = '#F5F6F8'
        self._ln_fg = '#A0A0A6'
        self.blockCountChanged.connect(self._update_ln_width)
        self.updateRequest.connect(self._on_ln_update)
        self._update_ln_width(0)

    def line_number_area_width(self):
        digits = max(2, len(str(max(1, self.blockCount()))))
        return 16 + self.fontMetrics().horizontalAdvance('9') * digits

    def _update_ln_width(self, _count):
        self.setViewportMargins(self.line_number_area_width(), 0, 0, 0)

    def _on_ln_update(self, rect, dy):
        if dy:
            self._ln_area.scroll(0, dy)
        else:
            self._ln_area.update(0, rect.y(), self._ln_area.width(), rect.height())
        if rect.contains(self.viewport().rect()):
            self._update_ln_width(0)

    def resizeEvent(self, event):
        super().resizeEvent(event)
        cr = self.contentsRect()
        self._ln_area.setGeometry(cr.left(), cr.top(), self.line_number_area_width(), cr.height())

    def set_line_number_colors(self, bg, fg):
        self._ln_bg = str(bg or self._ln_bg)
        self._ln_fg = str(fg or self._ln_fg)
        self._ln_area.update()

    def line_number_area_paint_event(self, event):
        painter = QPainter(self._ln_area)
        painter.fillRect(event.rect(), QColor(self._ln_bg))
        block = self.firstVisibleBlock()
        block_num = block.blockNumber()
        offset = self.contentOffset()
        top = round(self.blockBoundingGeometry(block).translated(offset).top())
        bottom = top + round(self.blockBoundingRect(block).height())
        painter.setPen(QColor(self._ln_fg))
        h = self.fontMetrics().height()
        w = self._ln_area.width() - 8
        while block.isValid() and top <= event.rect().bottom():
            if block.isVisible() and bottom >= event.rect().top():
                painter.drawText(0, top, w, h, Qt.AlignmentFlag.AlignRight, str(block_num + 1))
            block = block.next()
            top = bottom
            bottom = top + round(self.blockBoundingRect(block).height())
            block_num += 1


class EditorPage(QWidget):
    """Plain text editing surface (M1 skeleton — M2 adds versions/search/save)."""
    card_request = pyqtSignal(str, dict)

    def __init__(self, window, parent=None):
        super().__init__(parent)
        self._win = window
        self._path = None
        self._buffers = {}  # path -> unsaved text kept across file switches
        # ---- M2 state ----
        self._dirty_paths = set()
        self._loading = False          # guards programmatic setPlainText
        self._previewing = None        # version number shown read-only, else None
        self._live_stash = None        # live buffer parked while previewing
        self._live_stash_modified = False
        self._search_matches = []
        self._search_index = -1
        self._search_text = ''
        self._search_dark = False
        lay = QVBoxLayout(self)
        lay.setContentsMargins(4, 2, 4, 2)
        lay.setSpacing(6)

        # ---- M2: tool row (version dropdown · search) ----
        tool_row = QHBoxLayout()
        tool_row.setContentsMargins(2, 0, 2, 0)
        tool_row.setSpacing(8)
        self.version_combo = DropdownButton(self, compact_light=True)
        self.version_combo.setFixedWidth(230)
        self.version_combo.setPopupMaxWidth(320)
        self.version_combo.addItem(_tr('Current'), None)
        self.version_combo.currentIndexChanged.connect(self._on_version_selected)
        self.search_field = add_search_glyph(QLineEdit(self))
        self.search_field.setPlaceholderText(_tr('Search'))
        self.search_field.setFixedWidth(220)
        self.search_field.setFixedHeight(self.version_combo.height())   # as tall as the drop-down beside it (22)
        self.search_field.setClearButtonEnabled(True)
        self.search_field.textChanged.connect(self._on_search_text_changed)
        self.search_field.installEventFilter(self)
        self.search_count_lbl = QLabel('0/0', self)
        tool_row.addWidget(self.version_combo)
        tool_row.addStretch(1)
        tool_row.addWidget(self.search_field)
        tool_row.addWidget(self.search_count_lbl)
        lay.addLayout(tool_row)

        # ---- M2: version-preview banner ----
        self._preview_banner = QWidget(self)
        self._preview_banner.setObjectName('editorPreviewBanner')
        self._preview_banner.setAttribute(Qt.WidgetAttribute.WA_StyledBackground, True)
        pb_lay = QHBoxLayout(self._preview_banner)
        pb_lay.setContentsMargins(10, 3, 10, 3)
        pb_lay.setSpacing(8)
        self._preview_lbl = QLabel('', self._preview_banner)
        self._back_to_current_btn = QPushButton(_tr('Back to Current'), self._preview_banner)
        self._back_to_current_btn.setCursor(Qt.CursorShape.PointingHandCursor)
        self._back_to_current_btn.clicked.connect(self._back_to_current)
        pb_lay.addWidget(self._preview_lbl)
        pb_lay.addStretch(1)
        pb_lay.addWidget(self._back_to_current_btn)
        self._preview_banner.hide()
        lay.addWidget(self._preview_banner)

        # ---- M2: disk-change banner ----
        self._stale_banner = QWidget(self)
        self._stale_banner.setObjectName('editorStaleBanner')
        self._stale_banner.setAttribute(Qt.WidgetAttribute.WA_StyledBackground, True)
        sb_lay = QHBoxLayout(self._stale_banner)
        sb_lay.setContentsMargins(10, 3, 10, 3)
        sb_lay.setSpacing(8)
        self._stale_lbl = QLabel(_tr('File changed on disk'), self._stale_banner)
        self._reload_btn = QPushButton(_tr('Reload'), self._stale_banner)
        self._reload_btn.setCursor(Qt.CursorShape.PointingHandCursor)
        self._reload_btn.clicked.connect(self.reload_from_disk)
        sb_lay.addWidget(self._stale_lbl)
        sb_lay.addStretch(1)
        sb_lay.addWidget(self._reload_btn)
        self._stale_banner.hide()
        lay.addWidget(self._stale_banner)

        self.editor = EditorCodeEdit(self)
        self.editor.setFrameShape(QFrame.Shape.NoFrame)
        self.editor.setContextMenuPolicy(Qt.ContextMenuPolicy.CustomContextMenu)
        self.editor.customContextMenuRequested.connect(self._show_editor_menu)
        self.editor.textChanged.connect(self._on_text_changed)
        lay.addWidget(self.editor)
        # re-run the active search when the text changes (debounced for big files)
        self._search_retimer = QTimer(self)
        self._search_retimer.setSingleShot(True)
        self._search_retimer.setInterval(180)
        self._search_retimer.timeout.connect(self._refresh_search)
        try:
            self.set_theme(is_dark_theme(app))
        except Exception:
            self.set_theme(False)

    def _window(self):
        return self._win

    def set_theme(self, dark_mode):
        color = '#F2F2F7' if dark_mode else '#20242B'
        selection = '#264F78' if dark_mode else '#B5D5FF'
        self.editor.setStyleSheet(
            "QPlainTextEdit { border: none; background: transparent;"
            f" color: {color}; selection-background-color: {selection};"
            " font-family: Menlo, Monaco, 'Courier New', monospace; font-size: 12px; }"
        )
        try:
            self.editor.set_line_number_colors(
                '#26262A' if dark_mode else '#F5F6F8',
                '#7C828C' if dark_mode else '#A8ABB2')
        except Exception:
            pass
        # ---- M2: tool row + banners ----
        self._search_dark = bool(dark_mode)
        field_bg = '#404145' if dark_mode else '#E7E7E7'
        field_fg = '#FFFFFF' if dark_mode else '#111111'
        self.search_field.setStyleSheet(_settings_lineedit_stylesheet(bool(dark_mode)))   # the plain input style
        dim = '#8E8E93' if dark_mode else '#A0A0A6'
        self.search_count_lbl.setStyleSheet(
            f'color: {dim}; font-size: 11px; background: transparent;')
        link = '#0A84FF' if dark_mode else '#007AFF'
        fg = '#F2F2F7' if dark_mode else '#333333'
        banner_css = (
            "#%s { background: %s; border-radius: 8px; }"
            " QLabel { color: %s; font-size: 11px; background: transparent; }"
            " QPushButton { border: none; background: transparent;"
            " color: %s; font-size: 11px; padding: 1px 6px; }"
            " QPushButton:hover { text-decoration: underline; }"
        )
        pv_bg = 'rgba(10,132,255,36)' if dark_mode else 'rgba(0,122,255,26)'
        st_bg = 'rgba(255,159,10,46)' if dark_mode else 'rgba(255,159,10,36)'
        self._preview_banner.setStyleSheet(banner_css % ('editorPreviewBanner', pv_bg, fg, link))
        self._stale_banner.setStyleSheet(banner_css % ('editorStaleBanner', st_bg, fg, link))
        try:
            self.version_combo._update_style()
        except Exception:
            pass
        self._update_search_highlights()

    def load_path(self, path):
        win = self._window()
        # Leaving a version preview: the parked live buffer is what travels on.
        if self._previewing is not None:
            live = self._live_stash if self._live_stash is not None else ''
            live_modified = bool(self._live_stash_modified)
            self._previewing = None
            self._live_stash = None
            self._live_stash_modified = False
            self.editor.setReadOnly(False)
            self._preview_banner.hide()
            # M3 (defect 4a): a just-closed file must not resurrect its buffer
            if self._path and live_modified and self._path in win.session.open_files:
                self._buffers[self._path] = live
        else:
            # Stash unsaved edits of the outgoing file so switching pills never loses them
            # (M3 defect 4a: unless that file was just closed — closing drops its edits).
            try:
                if (self._path and self.editor.document().isModified()
                        and self._path in win.session.open_files):
                    self._buffers[self._path] = self.editor.toPlainText()
            except Exception:
                pass
        self._path = path or None
        self._loading = True
        try:
            if not self._path:
                self.editor.setPlainText('')
                self.editor.document().setModified(False)
            elif self._path in self._buffers:
                self.editor.setPlainText(self._buffers[self._path])
                self.editor.document().setModified(True)
            else:
                store = self._store()
                text = store.read_disk() if store is not None else ''
                if store is not None and not store.list_versions():
                    # first open ever → baseline version
                    store.save_version(text, 'import', note='initial import')
                    # ---- FIX-38: the import baseline is a new version too ----
                    try:
                        win.note_version_saved(self._path, 'import')
                    except Exception:
                        pass
                self.editor.setPlainText(text)
                self.editor.document().setModified(False)
                try:
                    win.note_disk_seen(self._path)
                except Exception:
                    pass
                try:
                    cursor = self.editor.textCursor()
                    cursor.movePosition(QTextCursor.MoveOperation.Start)
                    self.editor.setTextCursor(cursor)
                except Exception:
                    pass
        finally:
            self._loading = False
        self.refresh_versions()
        self._refresh_search()
        # dirty / stale surfaces for the incoming file
        dirty = bool(self._path) and self._path in self._dirty_paths
        try:
            win.action_bar.save_btn.setEnabled(dirty)
        except Exception:
            pass
        stale = False
        try:
            stale = bool(self._path) and win.file_bar.is_stale(self._path)
        except Exception:
            stale = False
        self._stale_banner.setVisible(stale)

    def selection_info(self):
        cur = self.editor.textCursor()
        text = cur.selectedText().replace('\u2029', '\n')
        doc = self.editor.document()
        try:
            line_start = doc.findBlock(cur.selectionStart()).blockNumber() + 1
            line_end = doc.findBlock(cur.selectionEnd()).blockNumber() + 1
        except Exception:
            line_start = 0
            line_end = 0
        return {'text': text, 'line_start': line_start, 'line_end': line_end, 'path': self._path}

    # ---- M2: store access ----
    def _store(self):
        if not self._path:
            return None
        try:
            return self._win.session.store(self._path)
        except Exception:
            return None

    # ---- M2: version dropdown + read-only preview ----
    def _format_version_label(self, v):
        try:
            n = int(v.get('n', 0))
        except Exception:
            n = 0
        raw_trigger = str(v.get('trigger', ''))
        # stored trigger codes stay English; only the shown label is translated
        trigger = {
            'ai_edit': _tr('ai edit'), 'manual_save': _tr('manual save'),
            'pre_revert_backup': _tr('pre revert backup'), 'import': _tr('import'),
        }.get(raw_trigger, raw_trigger.replace('_', ' '))
        at = str(v.get('at', ''))
        try:
            stamp = datetime.datetime.fromisoformat(at).strftime('%m-%d %H:%M')
        except Exception:
            stamp = at[:16]
        label = 'v%04d · %s · %s' % (n, trigger, stamp)
        if v.get('reverted'):
            label += ' · ' + _tr('reverted')
        return label

    def refresh_versions(self):
        combo = self.version_combo
        combo.blockSignals(True)
        try:
            combo.clear()
            combo.addItem(_tr('Current'), None)
            store = self._store()
            versions = store.list_versions() if store is not None else []
            for v in reversed(versions):  # newest first
                try:
                    combo.addItem(self._format_version_label(v), int(v.get('n', 0)))
                except Exception:
                    continue
            if self._previewing is not None:
                idx = combo.findData(self._previewing)
                combo.setCurrentIndex(idx if idx > 0 else 0)
            else:
                combo.setCurrentIndex(0)
        finally:
            combo.blockSignals(False)

    def _on_version_selected(self, index):
        try:
            n = self.version_combo.itemData(int(index))
        except Exception:
            n = None
        if n is None:
            self._exit_preview()
        else:
            self._enter_preview(int(n))

    def _enter_preview(self, n):
        store = self._store()
        text = store.read_version(n) if store is not None else None
        if text is None or not self._path:
            self._reset_combo_to_current()
            self._exit_preview()
            return
        if self._previewing is None:
            # park the live buffer — it must survive the preview round-trip
            self._live_stash = self.editor.toPlainText()
            self._live_stash_modified = self.editor.document().isModified()
        self._previewing = int(n)
        self._loading = True
        try:
            self.editor.setPlainText(text)
        finally:
            self._loading = False
        self.editor.setReadOnly(True)
        self._preview_lbl.setText(_tr('Viewing v%d (read-only)') % int(n))
        self._preview_banner.show()
        self._refresh_search()

    def _exit_preview(self):
        if self._previewing is None:
            return
        self._previewing = None
        live = self._live_stash if self._live_stash is not None else ''
        modified = bool(self._live_stash_modified)
        self._live_stash = None
        self._live_stash_modified = False
        self.editor.setReadOnly(False)
        self._preview_banner.hide()
        self._loading = True
        try:
            self.editor.setPlainText(live)
            self.editor.document().setModified(modified)
        finally:
            self._loading = False
        self._refresh_search()

    def _back_to_current(self):
        if self.version_combo.currentIndex() != 0:
            self.version_combo.setCurrentIndex(0)  # emits → _exit_preview
        else:
            self._exit_preview()

    def _reset_combo_to_current(self):
        combo = self.version_combo
        combo.blockSignals(True)
        try:
            combo.setCurrentIndex(0)
        finally:
            combo.blockSignals(False)

    # ---- M2: dirty tracking / save / reload ----
    def _on_text_changed(self):
        if self._loading or self._previewing is not None:
            return
        if self._search_text:
            self._search_retimer.start()
        if not self._path:
            return
        self._dirty_paths.add(self._path)
        win = self._window()
        try:
            win.file_bar.set_dirty(self._path, True)
        except Exception:
            pass
        try:
            win.action_bar.save_btn.setEnabled(True)
        except Exception:
            pass

    def save_current(self):
        if self._previewing is not None:
            return
        path = self._path
        store = self._store()
        if not path or store is None:
            return
        text = self.editor.toPlainText()
        if not editor_write_file(self, store, text):
            return
        store.save_version(text, 'manual_save')
        self.editor.document().setModified(False)
        self._buffers.pop(path, None)
        self._dirty_paths.discard(path)
        win = self._window()
        try:
            win.file_bar.set_dirty(path, False)
            win.file_bar.set_stale(path, False)
            win.action_bar.save_btn.setEnabled(False)
            win.note_disk_seen(path)
        except Exception:
            pass
        self._stale_banner.hide()
        self.refresh_versions()
        # ---- M3: a save adds a version — keep the snapshots page in step ----
        try:
            win.snapshot_page.refresh_lists()
        except Exception:
            pass
        # ---- FIX-38: a new version triggers the debug scan (debounced) ----
        try:
            win.note_version_saved(path, 'manual_save')
        except Exception:
            pass

    def reload_from_disk(self):
        # 'Reload' takes the disk state — deliberately drops preview/dirty/buffer.
        path = self._path
        store = self._store()
        if not path or store is None:
            return
        if self._previewing is not None:
            self._previewing = None
            self._live_stash = None
            self._live_stash_modified = False
            self.editor.setReadOnly(False)
            self._preview_banner.hide()
            self._reset_combo_to_current()
        text = store.read_disk()
        self._loading = True
        try:
            self.editor.setPlainText(text)
            self.editor.document().setModified(False)
        finally:
            self._loading = False
        self._buffers.pop(path, None)
        self._dirty_paths.discard(path)
        win = self._window()
        try:
            win.file_bar.set_dirty(path, False)
            win.file_bar.set_stale(path, False)
            win.action_bar.save_btn.setEnabled(False)
            win.note_disk_seen(path)
        except Exception:
            pass
        self._stale_banner.hide()
        self.refresh_versions()
        self._refresh_search()
        try:
            self._win.session.file_content_reloaded.emit(path)
        except Exception:
            pass

    def show_stale_banner(self):
        self._stale_banner.show()

    def prune_closed(self, open_paths):
        keep = set(open_paths or [])
        for p in list(self._buffers.keys()):
            if p not in keep:
                self._buffers.pop(p, None)
        self._dirty_paths &= keep

    # ---- M2: live search ----
    def _on_search_text_changed(self, text):
        self._apply_search(text, reset_index=True)

    def _refresh_search(self):
        self._apply_search(self.search_field.text(), reset_index=True)

    def _apply_search(self, text, reset_index=False):
        # M3 (defect 4b): match positions come straight from QTextDocument.find,
        # so they are UTF-16 document offsets — Python code-point indices drift
        # after astral-plane characters (emoji) and select the wrong span.
        self._search_text = str(text or '')
        matches = []  # list of (sel_start, sel_end) document positions
        if self._search_text:
            doc = self.editor.document()
            cur = doc.find(self._search_text, 0)  # default find = case-insensitive
            while not cur.isNull():
                matches.append((cur.selectionStart(), cur.selectionEnd()))
                cur = doc.find(self._search_text, cur)
        self._search_matches = matches
        if reset_index or self._search_index >= len(matches):
            self._search_index = -1
        self._update_search_highlights()
        self._update_search_count()

    def _goto_match(self, direction):
        n = len(self._search_matches)
        if n == 0:
            return
        if self._search_index < 0:
            # start from the caret, wrapping around either way
            pos = self.editor.textCursor().position()
            if direction > 0:
                idx = next((i for i, m in enumerate(self._search_matches) if m[0] >= pos), 0)
            else:
                idx = next((i for i in range(n - 1, -1, -1)
                            if self._search_matches[i][0] < pos), n - 1)
        else:
            idx = (self._search_index + (1 if direction > 0 else -1)) % n
        self._search_index = idx
        start, end = self._search_matches[idx]
        cur = self.editor.textCursor()
        cur.setPosition(start)
        cur.setPosition(end, QTextCursor.MoveMode.KeepAnchor)
        self.editor.setTextCursor(cur)
        self.editor.ensureCursorVisible()
        self._update_search_highlights()
        self._update_search_count()

    def _update_search_highlights(self):
        n = len(self._search_matches)
        sels = []
        if self._search_text and 0 < n <= 2000:
            # highlight-all is skipped above 2000 matches (Enter-cycling still works)
            base_fmt = QTextCharFormat()
            base_fmt.setBackground(QBrush(
                QColor(10, 132, 255, 70) if self._search_dark else QColor(0, 122, 255, 50)))
            doc = self.editor.document()
            for start, end in self._search_matches:
                cur = QTextCursor(doc)
                cur.setPosition(start)
                cur.setPosition(end, QTextCursor.MoveMode.KeepAnchor)
                sel = QTextEdit.ExtraSelection()
                sel.cursor = cur
                sel.format = base_fmt
                sels.append(sel)
            if 0 <= self._search_index < n:
                strong_fmt = QTextCharFormat()
                strong_fmt.setBackground(QBrush(QColor(255, 159, 10, 120)))
                start, end = self._search_matches[self._search_index]
                cur = QTextCursor(doc)
                cur.setPosition(start)
                cur.setPosition(end, QTextCursor.MoveMode.KeepAnchor)
                sel = QTextEdit.ExtraSelection()
                sel.cursor = cur
                sel.format = strong_fmt
                sels.append(sel)
        self.editor.setExtraSelections(sels)

    def _update_search_count(self):
        n = len(self._search_matches)
        if not self._search_text:
            label = '0/0'
        elif n > 2000:
            label = '%d/2000+' % (self._search_index + 1) if self._search_index >= 0 else '2000+'
        else:
            label = '%d/%d' % (self._search_index + 1 if self._search_index >= 0 else 0, n)
        self.search_count_lbl.setText(label)

    def eventFilter(self, obj, event):
        if obj is self.search_field and event.type() == QEvent.Type.KeyPress:
            key = event.key()
            if key in (Qt.Key.Key_Return, Qt.Key.Key_Enter):
                if event.modifiers() & Qt.KeyboardModifier.ShiftModifier:
                    self._goto_match(-1)
                else:
                    self._goto_match(1)
                return True
            if key == Qt.Key.Key_Escape:
                self.search_field.clear()
                self.editor.setFocus()
                return True
        return super().eventFilter(obj, event)

    def _show_editor_menu(self, pos):
        info = self.selection_info()
        has_sel = bool(info['text'].strip())
        menu = style_broccoli_context_menu(QMenu(self.editor))
        explain_act = menu.addAction(_tr('Explain This Code'))
        flow_act = menu.addAction(_tr('Explain Flow'))
        explain_act.setEnabled(has_sel)  # M4: explain cards are live
        flow_act.setEnabled(has_sel)     # M5: flow cards are live
        menu.addSeparator()
        append_act = menu.addAction(_tr('Append to current chat'))
        web_act = menu.addAction(_tr('Ask Web'))
        local_act = menu.addAction(_tr('Ask Localhost'))
        menu.addSeparator()
        copy_act = menu.addAction(_tr('Copy'))
        for a in (append_act, web_act, local_act, copy_act):
            a.setEnabled(has_sel)
        act = menu.exec(self.editor.viewport().mapToGlobal(pos))
        if act is None:
            return
        if act == copy_act:
            self.editor.copy()
            return
        if act == explain_act:
            self.card_request.emit('explain', info)
            return
        if act == flow_act:
            self.card_request.emit('flow', info)
            return
        key = None
        if act == append_act:
            key = 'append_current'
        elif act == web_act:
            key = 'ask_web'
        elif act == local_act:
            key = 'ask_localhost'
        if key:
            try:
                self._window()._main._execute_selection_ask_action(key, info['text'])
            except Exception:
                pass


# ---- M3: snapshots page (version history / revert / compare slots) + compare page (diff) ----

EDITOR_SNAP_ROLE_SOURCE = Qt.ItemDataRole.UserRole.value
EDITOR_SNAP_ROLE_BASE = Qt.ItemDataRole.UserRole.value + 1


def editor_live_text_for(window, path):
    # The freshest text we have for an open file: live editor text when it is on
    # screen (the parked stash while previewing a version), else its unsaved
    # buffer, else the disk content.
    page = getattr(window, 'editor_page', None)
    session = getattr(window, 'session', None)
    if page is not None and session is not None and path == session.current_path:
        try:
            if page._previewing is not None:
                return page._live_stash if page._live_stash is not None else ''
            return page.editor.toPlainText()
        except Exception:
            pass
    if page is not None:
        try:
            if path in page._buffers:
                return page._buffers[path]
        except Exception:
            pass
    store = EditorStore.for_path(path)
    return store.read_disk() if store is not None else ''


def editor_compute_diff(left_text, right_text):
    # Line-aligned diff: returns (left_lines, right_lines, row_marks) where the
    # two line lists are None-padded to equal length and row_marks[i] is one of
    # 'equal' | 'delete' | 'insert' | 'replace'.
    left_lines = ('' if left_text is None else str(left_text)).splitlines()
    right_lines = ('' if right_text is None else str(right_text)).splitlines()
    out_l = []
    out_r = []
    marks = []
    matcher = difflib.SequenceMatcher(None, left_lines, right_lines)
    for tag, i1, i2, j1, j2 in matcher.get_opcodes():
        if tag == 'equal':
            for k in range(i2 - i1):
                out_l.append(left_lines[i1 + k])
                out_r.append(right_lines[j1 + k])
                marks.append('equal')
        elif tag == 'delete':
            for k in range(i1, i2):
                out_l.append(left_lines[k])
                out_r.append(None)
                marks.append('delete')
        elif tag == 'insert':
            for k in range(j1, j2):
                out_l.append(None)
                out_r.append(right_lines[k])
                marks.append('insert')
        else:  # replace — pad the shorter block so both sides stay aligned
            ln = i2 - i1
            rn = j2 - j1
            for k in range(max(ln, rn)):
                out_l.append(left_lines[i1 + k] if k < ln else None)
                out_r.append(right_lines[j1 + k] if k < rn else None)
                marks.append('replace')
    return out_l, out_r, marks


class EditorDebugPage(QWidget):
    """FIX-38: Debug tab — a background AI bug scan runs after every new version;
    open bugs sit in a severity-sorted list (settings-table style), the right pane
    explains the selected bug in natural language, and right-click can hand the fix
    to the main chat (now, or via the task queue). Fixed/feature-marked bugs move
    to the Resolved list below."""

    SEVERITY_GLYPHS = {'critical': '‼', 'high': '!', 'medium': '•', 'low': '◦'}
    SEVERITY_COLORS = {'critical': '#FF453A', 'high': '#FF9F0A', 'medium': '#D8B60A', 'low': '#8E8E93'}
    DEBOUNCE_MS = 1200
    MAX_CONCURRENT_SCANS = 2   # round 2: save-all across many files must not burst the LLM

    def __init__(self, window, parent=None):
        super().__init__(parent)
        self._win = window
        self._dark = False
        self._scan_workers = {}    # path -> live _EditorLLMWorker
        self._scan_pending = {}    # path -> trigger of a scan requested mid-scan
        self._scan_timers = {}     # path -> debounce QTimer
        self._scan_queue = {}      # path -> (trigger, version): parked while at the cap
        self._open_rows = []       # bug dicts currently shown, row-aligned
        self._resolved_rows = []
        self._selected_id = None
        self._syncing_selection = False

        lay = QVBoxLayout(self)
        lay.setContentsMargins(4, 2, 4, 2)
        lay.setSpacing(8)

        top = QHBoxLayout()
        top.setSpacing(8)
        self.file_lbl = QLabel('')
        self.status_lbl = QLabel('')
        self.scan_btn = EditorCapsuleButton(_tr('Scan Now'))
        self.scan_btn.clicked.connect(self._on_scan_now)
        top.addWidget(self.file_lbl)
        top.addStretch(1)
        top.addWidget(self.status_lbl)
        top.addWidget(self.scan_btn)
        lay.addLayout(top)

        body = QHBoxLayout()
        body.setSpacing(10)
        left_wrap = QWidget(self)
        left_wrap.setFixedWidth(290)
        left = QVBoxLayout(left_wrap)
        left.setContentsMargins(0, 0, 0, 0)
        left.setSpacing(6)
        self.bug_table = self._make_table(['!', _tr('Bug')])
        self.bug_table.itemSelectionChanged.connect(lambda: self._on_selection(False))
        self.bug_table.customContextMenuRequested.connect(self._show_bug_menu)
        self.bug_table.cellDoubleClicked.connect(self._on_bug_double_clicked)
        self.resolved_lbl = QLabel(_tr('Resolved'))
        self.resolved_table = self._make_table(['', _tr('Bug')])
        self.resolved_table.itemSelectionChanged.connect(lambda: self._on_selection(True))
        self.resolved_table.customContextMenuRequested.connect(self._show_resolved_menu)
        left.addWidget(self.bug_table, 3)
        left.addWidget(self.resolved_lbl)
        left.addWidget(self.resolved_table, 1)
        right = QVBoxLayout()
        right.setSpacing(6)
        self.detail_header = QLabel('')
        self.detail_header.setWordWrap(True)
        self.detail_browser = QTextBrowser(self)
        self.detail_browser.setFrameShape(QFrame.Shape.NoFrame)
        self.detail_browser.setOpenLinks(False)
        right.addWidget(self.detail_header)
        right.addWidget(self.detail_browser, 1)
        body.addWidget(left_wrap)
        body.addLayout(right, 1)
        lay.addLayout(body, 1)
        self._show_placeholder_detail()

    # ---- UI plumbing ----
    def _make_table(self, headers):
        t = QTableWidget(0, 2, self)
        t.setHorizontalHeaderLabels(list(headers))
        t.verticalHeader().setVisible(False)
        t.setEditTriggers(QAbstractItemView.EditTrigger.NoEditTriggers)
        t.setSelectionBehavior(QAbstractItemView.SelectionBehavior.SelectRows)
        t.setSelectionMode(QAbstractItemView.SelectionMode.SingleSelection)
        t.setShowGrid(False)
        t.setFrameShape(QFrame.Shape.NoFrame)
        t.setContextMenuPolicy(Qt.ContextMenuPolicy.CustomContextMenu)
        t.horizontalHeader().setStretchLastSection(True)
        t.setColumnWidth(0, 34)
        t.setWordWrap(False)
        return t

    def set_theme(self, dark_mode):
        self._dark = bool(dark_mode)
        css = _settings_table_stylesheet(self._dark)
        self.bug_table.setStyleSheet(css)
        self.resolved_table.setStyleSheet(css)
        fg = '#F2F2F7' if self._dark else '#20242B'
        muted = '#A7AEB8' if self._dark else '#6A717C'
        self.file_lbl.setStyleSheet('color: %s; font-size: 13px; font-weight: 600; background: transparent;' % fg)
        self.status_lbl.setStyleSheet('color: %s; font-size: 12px; background: transparent;' % muted)
        self.resolved_lbl.setStyleSheet('color: %s; font-size: 11px; font-weight: 600; background: transparent;' % muted)
        self.detail_header.setStyleSheet('color: %s; font-size: 13px; font-weight: 600; background: transparent;' % fg)
        self.detail_browser.setStyleSheet(
            'QTextBrowser { border: none; background: transparent; color: %s; font-size: 13px; }' % fg)
        try:
            self.scan_btn.apply_capsule_theme(self._dark)
        except Exception:
            pass

    def _store(self, path=None):
        try:
            return self._win.session.store(path or self._win.session.current_path)
        except Exception:
            return None

    def _set_status(self, text):
        self.status_lbl.setText(str(text or ''))

    # ---- list building ----
    def refresh_lists(self):
        path = self._win.session.current_path
        if not path:
            self._open_rows = []
            self._resolved_rows = []
            self.bug_table.setRowCount(0)
            self.resolved_table.setRowCount(0)
            self.file_lbl.setText(_tr('No file open'))
            self._set_status('')
            self._show_placeholder_detail()
            return
        self.file_lbl.setText(os.path.basename(path))
        store = self._store(path)
        data = store.load_debug() if store is not None else {'bugs': [], 'last_scan': {}}
        bugs = [b for b in (data.get('bugs') or []) if isinstance(b, dict)]
        open_bugs = [b for b in bugs if b.get('status') == 'open']
        open_bugs.sort(key=lambda b: str(b.get('created_at') or ''), reverse=True)
        open_bugs.sort(key=lambda b: editor_debug_severity_rank(b.get('severity')))
        resolved = [b for b in bugs if b.get('status') in ('fixed', 'feature')]
        resolved.sort(key=lambda b: str(b.get('resolved_at') or b.get('created_at') or ''), reverse=True)
        self._open_rows = open_bugs
        self._resolved_rows = resolved
        self._fill_table(self.bug_table, open_bugs, resolved_list=False)
        self._fill_table(self.resolved_table, resolved, resolved_list=True)
        if path in self._scan_workers:
            self._set_status(_tr('Scanning…'))
        else:
            last = data.get('last_scan') or {}
            if last.get('at'):
                if last.get('ok', True):
                    self._set_status(_tr('Last scan v%s · %d open') % (last.get('version', '?'), len(open_bugs)))
                else:
                    self._set_status(_tr('Scan failed: %s') % str(last.get('error', '') or '')[:80])
            else:
                self._set_status(_tr('No scan yet — save a version or press Scan Now'))
        self._restore_selection()

    def _fill_table(self, table, bug_list, resolved_list):
        self._syncing_selection = True
        try:
            table.clearSelection()  # review fix: a moved bug must not leave a stale row highlight
            table.setRowCount(len(bug_list))
            for row, bug in enumerate(bug_list):
                severity = str(bug.get('severity', 'medium') or 'medium')
                if resolved_list:
                    tag = 'F' if bug.get('status') == 'feature' else '✓'
                    first = QTableWidgetItem(tag)
                    first.setForeground(QColor('#8E8E93'))
                else:
                    first = QTableWidgetItem(self.SEVERITY_GLYPHS.get(severity, '•'))
                    first.setForeground(QColor(self.SEVERITY_COLORS.get(severity, '#8E8E93')))
                first.setToolTip(editor_debug_display_label(severity) if not resolved_list
                                 else editor_debug_display_label(bug.get('status', '')))
                first.setTextAlignment(Qt.AlignmentFlag.AlignCenter)
                title_item = QTableWidgetItem(str(bug.get('title', '') or ''))
                title_item.setToolTip(str(bug.get('title', '') or ''))
                if resolved_list:
                    title_item.setForeground(QColor('#8E8E93'))
                for item in (first, title_item):
                    item.setData(Qt.ItemDataRole.UserRole, str(bug.get('id', '') or ''))
                table.setItem(row, 0, first)
                table.setItem(row, 1, title_item)
        finally:
            self._syncing_selection = False

    def _restore_selection(self):
        if not self._selected_id:
            self._show_placeholder_detail()
            return
        for table, rows, resolved in ((self.bug_table, self._open_rows, False),
                                      (self.resolved_table, self._resolved_rows, True)):
            for row, bug in enumerate(rows):
                if str(bug.get('id', '')) == self._selected_id:
                    self._syncing_selection = True
                    try:
                        table.selectRow(row)
                    finally:
                        self._syncing_selection = False
                    self._show_detail(bug)
                    return
        self._selected_id = None
        self._show_placeholder_detail()

    def _on_selection(self, resolved):
        if self._syncing_selection:
            return
        table = self.resolved_table if resolved else self.bug_table
        other = self.bug_table if resolved else self.resolved_table
        rows = self._resolved_rows if resolved else self._open_rows
        idxs = table.selectionModel().selectedRows() if table.selectionModel() else []
        if not idxs:
            return
        row = idxs[0].row()
        if not (0 <= row < len(rows)):
            return
        self._syncing_selection = True
        try:
            other.clearSelection()
        finally:
            self._syncing_selection = False
        bug = rows[row]
        self._selected_id = str(bug.get('id', '') or '')
        self._show_detail(bug)

    # ---- detail pane ----
    def _show_placeholder_detail(self):
        self.detail_header.setText('')
        muted = '#A7AEB8' if self._dark else '#6A717C'
        self.detail_browser.setHtml(
            '<div style="color:%s; font-size:13px;">%s</div>'
            % (muted, _tr('Select a bug to see the detailed explanation.')))

    def _show_detail(self, bug):
        severity = str(bug.get('severity', 'medium') or 'medium')
        parts = [str(bug.get('id', '') or ''), editor_debug_display_label(severity).upper(),
                 str(bug.get('category', '') or '')]
        line_start = int(bug.get('line_start', 0) or 0)
        line_end = int(bug.get('line_end', 0) or 0)
        if line_start:
            parts.append('L%d–%d' % (line_start, line_end or line_start))
        if bug.get('created_version') is not None:
            parts.append(_tr('found v%s') % bug.get('created_version'))
        parts.append(editor_debug_display_label(bug.get('status', '')))
        self.detail_header.setText(' · '.join(p for p in parts if p))
        explanation = str(bug.get('explanation', '') or '').strip() or _tr('(no explanation provided)')
        try:
            self.detail_browser.setHtml(render_markdown_fragment(explanation))
        except Exception:
            self.detail_browser.setPlainText(explanation)

    def _on_bug_double_clicked(self, row, _col):
        if 0 <= row < len(self._open_rows):
            line = int(self._open_rows[row].get('line_start', 0) or 0)
            if line > 0:
                try:
                    self._win.jump_editor_to_line(line)
                except Exception:
                    pass

    # ---- session plumbing ----
    def on_session_file_selected(self, _path):
        # review fix: a remembered bug id must not auto-select the same-numbered
        # bug of the file we just switched to
        self._selected_id = None
        self.refresh_lists()

    def maybe_first_scan(self):
        """Tab entered: files opened before this feature exists get one initial scan."""
        path = self._win.session.current_path
        store = self._store(path)
        if not path or store is None or path in self._scan_workers:
            return
        data = store.load_debug()
        if not (data.get('last_scan') or {}).get('at') and not data.get('bugs'):
            self.note_version_saved(path, 'first_view')

    # ---- scan pipeline ----
    def note_version_saved(self, path, trigger, version=None):
        """Debounced entry point — called after import / manual_save / ai_edit /
        revert. Collapses rapid saves; a scan already streaming for the path sets
        a pending flag and reruns once with the newest content. `version` pins
        the ledger stamp when the newest index entry is NOT what got scanned
        (revert: the newest version is the pre_revert_backup, disk is vN)."""
        path = str(path or '').strip()
        if not path:
            return
        timer = self._scan_timers.get(path)
        if timer is None:
            timer = QTimer(self)
            timer.setSingleShot(True)
            timer.setInterval(self.DEBOUNCE_MS)
            self._scan_timers[path] = timer
        try:
            timer.timeout.disconnect()
        except Exception:
            pass
        timer.timeout.connect(
            lambda p=path, t=str(trigger or ''), v=version: self._start_scan(p, t, v))
        timer.start()
        if path == self._win.session.current_path:
            self._set_status(_tr('Scan queued…'))

    def _on_scan_now(self):
        path = self._win.session.current_path
        if path:
            self._start_scan(path, 'manual')

    def _start_scan(self, path, trigger, version=None):
        # a manual/immediate scan supersedes a pending debounce for the same path
        # (both would read identical live text — never pay for two LLM calls)
        timer = self._scan_timers.get(path)
        if timer is not None and timer.isActive():
            timer.stop()
        if path in self._scan_workers:
            self._scan_pending[path] = (trigger, version)
            return
        if len(self._scan_workers) >= self.MAX_CONCURRENT_SCANS:
            # round 2: park behind the cap; drained one-at-a-time as scans finish
            self._scan_queue[path] = (trigger, version)
            if path == self._win.session.current_path:
                self._set_status(_tr('Scan queued (%d ahead)…') % max(0, len(self._scan_queue) - 1))
            return
        self._scan_queue.pop(path, None)
        win = self._win
        # review fix: every abort below consumed a drain opportunity — hand the
        # freed slot to the next queued path or the queue strands forever
        if path not in list(win.session.open_files):
            self._drain_scan_queue()
            return
        store = win.session.store(path)
        if store is None:
            self._drain_scan_queue()
            return
        content = editor_live_text_for(win, path)
        if not str(content or '').strip():
            if path == win.session.current_path:
                self._set_status(_tr('File is empty — nothing to scan'))
            self._drain_scan_queue()
            return
        try:
            lang = store.lexicon_language() or 'English'
        except Exception:
            lang = 'English'
        data = store.load_debug()
        bugs = data.get('bugs') or []
        messages = editor_debug_scan_messages(store, content, bugs, lang)
        verifiable = editor_debug_verifiable_ids(bugs, content)
        self._launch_scan_worker(path, store, messages, trigger, retried=False,
                                 version=version, verifiable_ids=verifiable)

    def _launch_scan_worker(self, path, store, messages, trigger, retried,
                            version=None, verifiable_ids=None):
        chunks = []

        def on_delta(piece):
            chunks.append(piece)  # accumulate only — never rendered mid-stream

        def on_finished(text):
            self._scan_workers.pop(path, None)
            parsed = editor_parse_debug_json(text)
            if parsed is None and not retried:
                retry_messages = list(messages) + [
                    {'role': 'user', 'content': 'Return ONLY the JSON object, nothing else.'}]
                self._launch_scan_worker(path, store, retry_messages, trigger, retried=True,
                                         version=version, verifiable_ids=verifiable_ids)
                return
            if parsed is None:
                self._finish_scan_error(path, store, trigger, _tr('The model did not return valid JSON.'))
                return
            stamp = version
            if stamp is None:
                try:
                    versions = store.list_versions()
                    stamp = versions[-1].get('n', 0) if versions else 0
                except Exception:
                    stamp = 0
            data = store.load_debug()
            editor_debug_merge_scan(data, parsed, stamp, trigger, verifiable_ids=verifiable_ids)
            store.save_debug(data)
            self._after_scan(path)

        def on_failed(msg):
            self._scan_workers.pop(path, None)
            self._finish_scan_error(path, store, trigger, str(msg))

        worker = editor_llm_request(messages, on_delta, on_finished, on_failed)
        self._scan_workers[path] = worker
        if path == self._win.session.current_path:
            self._set_status(_tr('Scanning…'))

    def _finish_scan_error(self, path, store, trigger, message):
        try:
            data = store.load_debug()
            data['last_scan'] = {'version': (data.get('last_scan') or {}).get('version', 0),
                                 'at': _editor_now_iso(), 'trigger': str(trigger or ''),
                                 'ok': False, 'error': str(message or '')[:300]}
            store.save_debug(data)
        except Exception:
            pass
        self._after_scan(path)

    def _after_scan(self, path):
        if path == self._win.session.current_path:
            self.refresh_lists()
        pending = self._scan_pending.pop(path, None)
        if pending is not None:
            trigger, version = pending if isinstance(pending, tuple) else (pending, None)
            QTimer.singleShot(0, lambda p=path, t=trigger, v=version: self._start_scan(p, t, v))
            return
        self._drain_scan_queue()

    def _drain_scan_queue(self):
        # round 2 review fix: ONE drain step, shared by scan completion AND every
        # _start_scan abort path — a dead drained entry (file closed meanwhile,
        # empty content) hands its slot onward instead of stranding the queue
        if self._scan_queue and len(self._scan_workers) < self.MAX_CONCURRENT_SCANS:
            queued_path = next(iter(self._scan_queue))
            trigger, version = self._scan_queue.pop(queued_path)
            QTimer.singleShot(0, lambda p=queued_path, t=trigger, v=version: self._start_scan(p, t, v))

    # ---- context menus / actions ----
    def _bug_for_pos(self, table, rows, pos):
        row = table.rowAt(pos.y())
        if 0 <= row < len(rows):
            return rows[row]
        return None

    def _show_bug_menu(self, pos):
        bug = self._bug_for_pos(self.bug_table, self._open_rows, pos)
        # review fix: capture the file path at menu-OPEN time — a file switch
        # while the menu is up must not write the verdict into the new file
        path = self._win.session.current_path
        if bug is None or not path:
            return
        menu = style_broccoli_context_menu(QMenu(self))
        feature_act = menu.addAction(_tr('Mark as Feature (not a bug)'))
        menu.addSeparator()
        fix_act = menu.addAction(_tr('Fix in Main Chat'))
        queue_act = menu.addAction(_tr('Add to Task Queue'))
        menu.addSeparator()
        copy_act = menu.addAction(_tr('Copy Bug Summary'))
        act = menu.exec(self.bug_table.viewport().mapToGlobal(pos))
        if act == feature_act:
            self._set_bug_status(bug.get('id'), 'feature', path=path)
        elif act == fix_act:
            self._dispatch_fix(bug, queue=False, file_path=path)
        elif act == queue_act:
            self._dispatch_fix(bug, queue=True, file_path=path)
        elif act == copy_act:
            try:
                QApplication.clipboard().setText(self._fix_prompt(path, bug))
            except Exception:
                pass

    def _show_resolved_menu(self, pos):
        bug = self._bug_for_pos(self.resolved_table, self._resolved_rows, pos)
        path = self._win.session.current_path
        if bug is None or not path:
            return
        menu = style_broccoli_context_menu(QMenu(self))
        reopen_act = menu.addAction(_tr('Reopen'))
        delete_act = menu.addAction(_tr('Delete'))
        act = menu.exec(self.resolved_table.viewport().mapToGlobal(pos))
        if act == reopen_act:
            self._set_bug_status(bug.get('id'), 'open', path=path)
        elif act == delete_act:
            self._delete_bug(bug.get('id'), path=path)

    def _set_bug_status(self, bug_id, status, path=None):
        store = self._store(path)
        if store is None:
            return
        data = store.load_debug()
        now = _editor_now_iso()
        for bug in data.get('bugs') or []:
            if isinstance(bug, dict) and str(bug.get('id', '')) == str(bug_id or ''):
                bug['status'] = status
                if status == 'open':
                    bug.pop('resolved_at', None)
                    bug.pop('resolved_version', None)
                else:
                    bug['resolved_at'] = now
                break
        store.save_debug(data)
        self.refresh_lists()

    def _delete_bug(self, bug_id, path=None):
        store = self._store(path)
        if store is None:
            return
        data = store.load_debug()
        data['bugs'] = [b for b in (data.get('bugs') or [])
                        if not (isinstance(b, dict) and str(b.get('id', '')) == str(bug_id or ''))]
        store.save_debug(data)
        if self._selected_id == str(bug_id or ''):
            self._selected_id = None
        self.refresh_lists()

    # ---- main-chat dispatch (Fix now / Task queue — distinct semantics) ----
    def _fix_prompt(self, path, bug):
        line_start = int(bug.get('line_start', 0) or 0)
        line_end = int(bug.get('line_end', 0) or 0)
        lines = ('lines %d–%d' % (line_start, line_end or line_start)) if line_start else 'location unknown'
        return (
            'Please fix this bug found by the Broccoli editor Debug scan.\n'
            'File: %s (the file is open in the Broccoli editor — propose the change '
            'through the editor edit flow)\n'
            'Bug %s · severity %s · %s · %s\n'
            'Title: %s\n\n'
            'Details:\n%s\n' % (
                str(path or ''), str(bug.get('id', '') or ''),
                str(bug.get('severity', '') or ''), str(bug.get('category', '') or ''),
                lines, str(bug.get('title', '') or ''),
                str(bug.get('explanation', '') or ''))
        )

    def _dispatch_fix(self, bug, queue, file_path=None):
        main = getattr(self._win, '_main', None)
        file_path = file_path or self._win.session.current_path
        if main is None or not file_path:
            self._set_status(_tr('Main window unavailable'))
            return
        prompt = self._fix_prompt(file_path, bug)
        convo = str(getattr(main, '_active_conversation_path', '') or '').strip()
        if not convo:
            try:
                title = sanitize_conversation_title('Fix bug: %s' % str(bug.get('title', '') or ''), max_len=60)
                record = main._create_empty_agent_conversation_record(title, source='editor_debug', metadata={})
                convo = str(record.get('path', '') or '').strip()
                main._refresh_history_panel()
            except Exception:
                convo = ''
            if not convo:
                self._set_status(_tr('Could not create a conversation'))
                return
        run_active = False
        try:
            run_active = main._agent_run_for_path(convo) is not None
        except Exception:
            run_active = False
        if run_active:
            # a run is live — both actions defer through the queue, but 'Fix now'
            # jumps the line while 'Add to Task Queue' waits its turn
            item = {'id': main._next_agent_queue_id(), 'prompt': prompt, 'status': 'waiting',
                    'created_at': datetime.datetime.now().isoformat(timespec='seconds')}
            items = main._agent_queue_for_path(convo)
            if queue:
                items.append(item)
                self._set_status(_tr('Added to the task queue'))
            else:
                items.insert(0, item)
                self._set_status(_tr('Will run right after the current turn'))
            try:
                main._refresh_agent_queue_panel(convo)
            except Exception:
                pass
            return
        if queue:
            item = {'id': main._next_agent_queue_id(), 'prompt': prompt, 'status': 'waiting',
                    'created_at': datetime.datetime.now().isoformat(timespec='seconds')}
            main._agent_queue_for_path(convo).append(item)
            try:
                main._refresh_agent_queue_panel(convo)
            except Exception:
                pass
            started = False
            try:
                started = bool(main._run_next_agent_queue_item(convo))
            except Exception:
                started = False
            if started:
                self._set_status(_tr('Task queue running'))
            else:
                # review fix: the queue only drains after a run finishes — if the
                # kick failed while idle, nothing would ever run this item. Take
                # it back out and say so honestly.
                items = main._agent_queue_for_path(convo)
                items[:] = [it for it in items if str(it.get('id', '')) != str(item['id'])]
                try:
                    main._refresh_agent_queue_panel(convo)
                except Exception:
                    pass
                self._set_status(_tr('Could not start (check API settings)'))
            return
        started = False
        try:
            started = bool(main._start_agent_prompt_for_conversation(convo, prompt, source='editor_debug'))
        except Exception:
            started = False
        self._set_status(_tr('Sent to main chat') if started else _tr('Could not start (check API settings)'))


class EditorSnapshotPage(QWidget):
    """Version history: open files on the left, snapshots of the selected file on the right."""

    def __init__(self, window, parent=None):
        super().__init__(parent)
        self._win = window
        self._selected_path = None
        self._dark = False
        self.compare_a = None   # ('current', path) | ('version', path, n) | None
        self.compare_b = None
        lay = QHBoxLayout(self)
        lay.setContentsMargins(4, 2, 4, 2)
        lay.setSpacing(10)
        self.file_list = QListWidget(self)
        self.file_list.setFixedWidth(200)
        self.file_list.setFrameShape(QFrame.Shape.NoFrame)
        self.file_list.setSelectionMode(QAbstractItemView.SelectionMode.SingleSelection)
        self.file_list.setVerticalScrollMode(QAbstractItemView.ScrollMode.ScrollPerPixel)
        self.file_list.currentRowChanged.connect(self._on_file_row_changed)
        self.right_list = QListWidget(self)
        self.right_list.setFrameShape(QFrame.Shape.NoFrame)
        self.right_list.setSelectionMode(QAbstractItemView.SelectionMode.ExtendedSelection)
        self.right_list.setVerticalScrollMode(QAbstractItemView.ScrollMode.ScrollPerPixel)
        self.right_list.setContextMenuPolicy(Qt.ContextMenuPolicy.CustomContextMenu)
        self.right_list.customContextMenuRequested.connect(self._show_version_menu)
        self.right_list.itemDoubleClicked.connect(self._on_item_double_clicked)
        lay.addWidget(self.file_list)
        lay.addWidget(self.right_list, 1)
        try:
            self.set_theme(is_dark_theme(app))
        except Exception:
            self.set_theme(False)

    def set_theme(self, dark_mode):
        self._dark = bool(dark_mode)
        fg = '#F2F2F7' if dark_mode else '#20242B'
        hover = 'rgba(255,255,255,16)' if dark_mode else 'rgba(0,0,0,10)'
        sel = 'rgba(255,255,255,34)' if dark_mode else 'rgba(0,0,0,22)'
        css = (
            "QListWidget { border: none; background: transparent; color: %s; font-size: 12px; }"
            " QListWidget::item { padding: 4px 8px; border-radius: 8px; }"
            " QListWidget::item:hover { background: %s; }"
            " QListWidget::item:selected { background: %s; color: %s; }"
        ) % (fg, hover, sel, fg)
        self.file_list.setStyleSheet(css)
        self.right_list.setStyleSheet(css)
        self.refresh_lists()

    def _dim_color(self):
        return QColor('#8E8E93' if self._dark else '#A0A0A6')

    def _accent_color(self):
        return QColor('#0A84FF' if self._dark else '#007AFF')

    # ── list building ────────────────────────────────────────
    def on_session_file_selected(self, path):
        self.refresh_lists()

    def refresh_lists(self):
        session = self._win.session
        files = list(session.open_files)
        prev = self._selected_path
        if prev not in files:
            if session.current_path in files:
                prev = session.current_path
            else:
                prev = files[0] if files else None
        fl = self.file_list
        fl.blockSignals(True)
        try:
            fl.clear()
            current_row = -1
            for i, p in enumerate(files):
                it = QListWidgetItem(os.path.basename(p))
                it.setData(EDITOR_SNAP_ROLE_SOURCE, ('file', p))
                it.setToolTip(p)
                if p == session.current_path:
                    f = it.font()
                    f.setBold(True)
                    it.setFont(f)
                fl.addItem(it)
                if p == prev:
                    current_row = i
            if current_row >= 0:
                fl.setCurrentRow(current_row)
        finally:
            fl.blockSignals(False)
        self._selected_path = prev
        self._refresh_versions_list()

    def _on_file_row_changed(self, row):
        it = self.file_list.item(row) if row >= 0 else None
        data = it.data(EDITOR_SNAP_ROLE_SOURCE) if it is not None else None
        self._selected_path = data[1] if isinstance(data, tuple) and len(data) > 1 else None
        self._refresh_versions_list()

    def _refresh_versions_list(self):
        rl = self.right_list
        scroll = rl.verticalScrollBar().value()
        rl.clear()
        try:
            _EDITOR_CONVERSATION_TITLE_CACHE.clear()
        except Exception:
            pass
        path = self._selected_path
        if not path:
            return
        store = EditorStore.for_path(path)
        versions = store.list_versions() if store is not None else []
        dim = self._dim_color()
        cur_src = ('current', path)
        cur_item = QListWidgetItem(_tr('Current state') + self._slot_badge(cur_src))
        cur_item.setData(EDITOR_SNAP_ROLE_SOURCE, cur_src)
        cur_item.setData(EDITOR_SNAP_ROLE_BASE, _tr('Current state'))
        f = cur_item.font()
        f.setBold(True)
        cur_item.setFont(f)
        cur_item.setForeground(QBrush(self._accent_color()))
        rl.addItem(cur_item)
        try:
            fmt = self._win.editor_page._format_version_label
        except Exception:
            fmt = None
        last_key = None
        have_key = False
        for v in reversed(versions):  # newest first
            if not isinstance(v, dict):
                continue
            cid = str(v.get('conversation_id', '') or '')
            try:
                turn = int(v.get('turn', -1))
            except Exception:
                turn = -1
            key = (cid, turn) if cid else ('manual',)
            if not have_key or key != last_key:
                last_key = key
                have_key = True
                htext = (_tr('%s · turn %d') % (editor_conversation_title(cid), turn)) if cid else _tr('Manual / other')
                h = QListWidgetItem(htext)
                h.setData(EDITOR_SNAP_ROLE_SOURCE, ('header', cid, turn))
                h.setFlags(Qt.ItemFlag.NoItemFlags)  # visible but not selectable
                hf = h.font()
                hf.setPixelSize(10)
                h.setFont(hf)
                h.setForeground(QBrush(dim))
                rl.addItem(h)
            try:
                n = int(v.get('n', 0))
            except Exception:
                continue
            base = fmt(v) if fmt is not None else ('v%04d' % n)
            src = ('version', path, n)
            it = QListWidgetItem(base + self._slot_badge(src))
            it.setData(EDITOR_SNAP_ROLE_SOURCE, src)
            it.setData(EDITOR_SNAP_ROLE_BASE, base)
            if v.get('reverted'):
                it.setForeground(QBrush(dim))
            rl.addItem(it)
        rl.verticalScrollBar().setValue(scroll)

    # ── compare slots ────────────────────────────────────────
    def _slot_badge(self, source):
        if source is not None and source == self.compare_a:
            return ' [A]'
        if source is not None and source == self.compare_b:
            return ' [B]'
        return ''

    def _refresh_compare_badges(self):
        for i in range(self.right_list.count()):
            it = self.right_list.item(i)
            src = it.data(EDITOR_SNAP_ROLE_SOURCE)
            if not isinstance(src, tuple) or not src or src[0] not in ('current', 'version'):
                continue
            base = it.data(EDITOR_SNAP_ROLE_BASE)
            it.setText(str(base if base is not None else it.text()) + self._slot_badge(src))

    def set_compare_slot(self, source):
        if not isinstance(source, (tuple, list)) or not source:
            return
        source = tuple(source)
        if source != self.compare_a and source != self.compare_b:
            if self.compare_a is None:
                self.compare_a = source
            elif self.compare_b is None:
                self.compare_b = source
            else:
                self.compare_b = source  # both full → replace B
        self._refresh_compare_badges()
        if self.compare_a is not None and self.compare_b is not None:
            try:
                self._win.diff_page.set_sources(self.compare_a, self.compare_b)
                self._win.nav.select(4)   # FIX-38: Compare moved 3→4 (Debug tab at 2)
            except Exception:
                pass

    def _remove_compare_slot(self, source):
        if self.compare_a == source:
            self.compare_a = None
        if self.compare_b == source:
            self.compare_b = None
        self._refresh_compare_badges()

    # ── context menu ─────────────────────────────────────────
    def _show_version_menu(self, pos):
        item = self.right_list.itemAt(pos)
        if item is None:
            return
        data = item.data(EDITOR_SNAP_ROLE_SOURCE)
        if not isinstance(data, tuple) or not data:
            return
        global_pos = self.right_list.viewport().mapToGlobal(pos)
        sel_versions = []
        for it in self.right_list.selectedItems():
            src = it.data(EDITOR_SNAP_ROLE_SOURCE)
            if isinstance(src, tuple) and src and src[0] == 'version':
                sel_versions.append(it)
        menu = style_broccoli_context_menu(QMenu(self))
        if len(sel_versions) == 2:
            cmp_act = menu.addAction(_tr('Compare these two'))
            act = menu.exec(global_pos)
            if act == cmp_act:
                ordered = sorted(sel_versions, key=lambda it: self.right_list.row(it))
                self.compare_a = ordered[0].data(EDITOR_SNAP_ROLE_SOURCE)
                self.compare_b = ordered[1].data(EDITOR_SNAP_ROLE_SOURCE)
                self._refresh_compare_badges()
                try:
                    self._win.diff_page.set_sources(self.compare_a, self.compare_b)
                    self._win.nav.select(4)   # FIX-38: Compare moved 3→4
                except Exception:
                    pass
            return
        kind = data[0]
        if kind == 'header':
            revert_all_act = menu.addAction(_tr('Revert ALL open files to before this turn'))
            if not data[1]:
                revert_all_act.setEnabled(False)  # 'Manual / other' has no turn boundary
            act = menu.exec(global_pos)
            if act == revert_all_act:
                self._revert_turn_group(data[1], data[2])
            return
        if kind not in ('current', 'version'):
            return
        add_act = menu.addAction(_tr('Add to Compare'))
        remove_act = None
        if data in (self.compare_a, self.compare_b):
            remove_act = menu.addAction(_tr('Remove from Compare'))
        revert_act = None
        if kind == 'version':
            menu.addSeparator()
            revert_act = menu.addAction(_tr('Revert to this version'))
        act = menu.exec(global_pos)
        if act is None:
            return
        if act == add_act:
            self.set_compare_slot(data)
        elif remove_act is not None and act == remove_act:
            self._remove_compare_slot(data)
        elif revert_act is not None and act == revert_act:
            self._revert_file_to(data[1], data[2], refresh=True)

    # ── revert flows ─────────────────────────────────────────
    def _on_item_double_clicked(self, item):
        data = item.data(EDITOR_SNAP_ROLE_SOURCE)
        if isinstance(data, tuple) and len(data) == 3 and data[0] == 'version':
            self._revert_file_to(data[1], data[2], refresh=True)

    def _revert_file_to(self, path, n, refresh=True):
        win = self._win
        store = EditorStore.for_path(path)
        if store is None:
            return False
        try:
            n = int(n)
        except Exception:
            return False
        target_text = store.read_version(n)
        if target_text is None:
            return False  # snapshot file missing — abort before touching anything
        live = editor_live_text_for(win, path)
        backup_n = store.save_version(live, 'pre_revert_backup', note='before revert to v%d' % n)
        if not editor_write_file(win if isinstance(win, QWidget) else None, store, target_text):
            return False
        newer = []
        for v in store.list_versions():
            try:
                vn = int(v.get('n', 0))
            except Exception:
                continue
            if vn > n and vn != backup_n:
                newer.append(vn)
        if newer:
            store.mark_reverted(newer, True)
        target_version = None
        for v in store.list_versions():
            try:
                if int(v.get('n', 0)) == n:
                    target_version = v
                    break
            except Exception:
                continue
        trigger = str((target_version or {}).get('trigger', '') or '')
        if trigger == 'ai_edit' and str((target_version or {}).get('conversation_id', '') or ''):
            store.mark_reverted([n], True)
        elif trigger == 'pre_revert_backup':
            restore_ns = []
            for v in store.list_versions():
                try:
                    vn = int(v.get('n', 0))
                except Exception:
                    continue
                if vn < n and str(v.get('trigger', '') or '') == 'ai_edit' and v.get('reverted'):
                    # Un-flag only turns whose edit is plausibly back: if the
                    # restored text still equals that turn's pre-image, the edit
                    # is still absent — the reverted note must keep firing.
                    if store.read_version(vn) != target_text:
                        restore_ns.append(vn)
            if restore_ns:
                store.mark_reverted(restore_ns, False)
            store.mark_reverted([n], False)
        else:
            # M4 (M3 defect c): vN is the live state again — clear its own gray flag
            store.mark_reverted([n], False)
        if path == win.session.current_path:
            try:
                win.editor_page.reload_from_disk()  # reload + drop dirty/buffer/badges
            except Exception:
                pass
        else:
            # the reverted disk state must be what reopening shows — drop stale buffer/badges
            try:
                win.editor_page._buffers.pop(path, None)
                win.editor_page._dirty_paths.discard(path)
            except Exception:
                pass
            try:
                win.file_bar.set_dirty(path, False)
                win.file_bar.set_stale(path, False)
            except Exception:
                pass
            try:
                win.note_disk_seen(path)
            except Exception:
                pass
        if refresh:
            self.refresh_lists()
            try:
                win.editor_page.refresh_versions()
            except Exception:
                pass
        # ---- FIX-38: the file content just changed to an older state — rescan
        # (covers both single revert and each file of a turn-group revert).
        # version=n pins the ledger stamp: the NEWEST index entry after a revert
        # is the pre_revert_backup, whose content is not what got scanned ----
        try:
            win.note_version_saved(path, 'revert', version=n)
        except Exception:
            pass
        return True

    def _revert_turn_group(self, conversation_id, turn):
        win = self._win
        conversation_id = str(conversation_id or '')
        if not conversation_id:
            return
        try:
            turn = int(turn)
        except Exception:
            return
        for path in list(win.session.open_files):
            store = EditorStore.for_path(path)
            if store is None:
                continue
            versions = store.list_versions()
            turn_ns = []
            for v in versions:
                try:
                    if (str(v.get('conversation_id', '')) == conversation_id
                            and int(v.get('turn', -2)) == turn):
                        turn_ns.append(int(v.get('n', 0)))
                except Exception:
                    continue
            if not turn_ns:
                continue  # this turn never touched the file — leave it as-is
            first_n = min(turn_ns)
            older = []
            for v in versions:
                try:
                    vn = int(v.get('n', 0))
                except Exception:
                    continue
                if vn < first_n:
                    older.append(vn)
            if not older:
                continue  # nothing predates the turn — skip this file
            self._revert_file_to(path, max(older), refresh=False)
        self.refresh_lists()
        try:
            win.editor_page.refresh_versions()
        except Exception:
            pass


class _EditorDiffRibbon(QWidget):
    """Thin clickable overview strip between the diff panes."""

    def __init__(self, page, parent=None):
        super().__init__(parent)
        self._page = page
        self._marks = []
        self._bands = []  # (frac0, frac1, mark), bucketized
        self._dark = False
        self.setFixedWidth(14)
        self.setCursor(Qt.CursorShape.PointingHandCursor)

    def set_theme(self, dark_mode):
        self._dark = bool(dark_mode)
        self.update()

    def set_marks(self, marks):
        self._marks = list(marks or [])
        self._bands = []
        total = len(self._marks)
        if total:
            buckets = 600
            agg = [None] * buckets
            for i, m in enumerate(self._marks):
                if m == 'equal':
                    continue
                b = min(buckets - 1, (i * buckets) // total)
                if agg[b] is None:
                    agg[b] = m
            i = 0
            while i < buckets:
                m = agg[i]
                if m is None:
                    i += 1
                    continue
                j = i
                while j < buckets and agg[j] == m:
                    j += 1
                self._bands.append((i / buckets, j / buckets, m))
                i = j
        self.update()

    def paintEvent(self, event):
        painter = QPainter(self)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)
        painter.setPen(Qt.PenStyle.NoPen)
        h = self.height()
        track = QColor(255, 255, 255, 16) if self._dark else QColor(0, 0, 0, 12)
        painter.setBrush(QBrush(track))
        painter.drawRoundedRect(QRectF(3, 0, 8, h), 4, 4)
        colors = {
            'delete': QColor(255, 69, 58, 175),
            'insert': QColor(48, 209, 88, 175),
            'replace': QColor(255, 214, 10, 175),
        }
        for f0, f1, m in self._bands:
            y0 = f0 * h
            y1 = max(y0 + 2.0, f1 * h)
            painter.fillRect(QRectF(2, y0, 10, y1 - y0), colors.get(m, track))
        painter.end()

    def mousePressEvent(self, event):
        total = len(self._marks)
        if total <= 0 or self.height() <= 0:
            return
        frac = event.position().y() / self.height()
        row = max(0, min(total - 1, int(frac * total)))
        try:
            self._page._jump_to_row(row)
        except Exception:
            pass


class EditorDiffPage(QWidget):
    """Side-by-side compare of two sources (live buffer / saved version / external file)."""

    def __init__(self, window, parent=None):
        super().__init__(parent)
        self._win = window
        self._sources = [None, None]
        self._externals = [[], []]       # Browse…-picked paths per side
        self._last_file_index = [0, 0]
        self._combo_guard = False
        self._sync_guard = False
        self._cache = {}                 # source tuple -> text (versions/external only)
        self._pending = False
        self._marks = []
        lay = QVBoxLayout(self)
        lay.setContentsMargins(4, 2, 4, 2)
        lay.setSpacing(6)
        top = QHBoxLayout()
        top.setContentsMargins(2, 0, 2, 0)
        top.setSpacing(8)
        self._file_combos = []
        self._ver_combos = []
        for side in (0, 1):
            # FIX-42: the four fixed-width combos alone demanded 756px, which
            # made the whole editor window unable to reach its golden dock width.
            # They now shrink (popup still shows the full text).
            fc = DropdownButton(self, compact_light=True)
            fc.setMinimumWidth(76)
            fc.setMaximumWidth(150)
            fc.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed)
            fc.setPopupMaxWidth(320)
            fc.currentIndexChanged.connect(lambda _i, s=side: self._on_file_combo_changed(s))
            vc = DropdownButton(self, compact_light=True)
            vc.setMinimumWidth(96)
            vc.setMaximumWidth(210)
            vc.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed)
            vc.setPopupMaxWidth(320)
            vc.currentIndexChanged.connect(lambda _i, s=side: self._on_version_combo_changed(s))
            self._file_combos.append(fc)
            self._ver_combos.append(vc)
        self.note_lbl = QLabel(_tr('Large diff — highlighting truncated'), self)
        self.note_lbl.hide()
        top.addWidget(self._file_combos[0])
        top.addWidget(self._ver_combos[0])
        top.addStretch(1)
        top.addWidget(self.note_lbl)
        top.addStretch(1)
        top.addWidget(self._file_combos[1])
        top.addWidget(self._ver_combos[1])
        lay.addLayout(top)
        panes = QHBoxLayout()
        panes.setSpacing(4)
        self.left_pane = self._make_pane()
        self.right_pane = self._make_pane()
        self.ribbon = _EditorDiffRibbon(self, self)
        panes.addWidget(self.left_pane, 1)
        panes.addWidget(self.ribbon)
        panes.addWidget(self.right_pane, 1)
        lay.addLayout(panes, 1)
        # synchronized scrolling, both axes (guarded against recursion)
        lv = self.left_pane.verticalScrollBar()
        rv = self.right_pane.verticalScrollBar()
        lh = self.left_pane.horizontalScrollBar()
        rh = self.right_pane.horizontalScrollBar()
        lv.valueChanged.connect(lambda v, o=rv: self._sync_scroll(o, v))
        rv.valueChanged.connect(lambda v, o=lv: self._sync_scroll(o, v))
        lh.valueChanged.connect(lambda v, o=rh: self._sync_scroll(o, v))
        rh.valueChanged.connect(lambda v, o=lh: self._sync_scroll(o, v))
        # live refresh (300ms debounce on editor edits)
        self._live_timer = QTimer(self)
        self._live_timer.setSingleShot(True)
        self._live_timer.setInterval(300)
        self._live_timer.timeout.connect(self.recompute)
        try:
            window.editor_page.editor.textChanged.connect(self._on_editor_text_changed)
            window.session.files_changed.connect(self.refresh_files)
            window.session.file_content_reloaded.connect(self._on_file_reloaded)
        except Exception:
            pass
        for side in (0, 1):
            self._fill_file_combo(side, ('none',))
            self._rebuild_version_combo(side, preserve=False)
        try:
            self.set_theme(is_dark_theme(app))
        except Exception:
            self.set_theme(False)

    def _make_pane(self):
        pane = QPlainTextEdit(self)
        pane.setReadOnly(True)
        pane.setFrameShape(QFrame.Shape.NoFrame)
        pane.setLineWrapMode(QPlainTextEdit.LineWrapMode.NoWrap)
        pane.setPlaceholderText(_tr('Choose a source to compare'))
        return pane

    def set_theme(self, dark_mode):
        color = '#F2F2F7' if dark_mode else '#20242B'
        selection = '#264F78' if dark_mode else '#B5D5FF'
        css = (
            "QPlainTextEdit { border: none; background: transparent; color: %s;"
            " selection-background-color: %s;"
            " font-family: Menlo, Monaco, 'Courier New', monospace; font-size: 12px; }"
        ) % (color, selection)
        self.left_pane.setStyleSheet(css)
        self.right_pane.setStyleSheet(css)
        dim = '#8E8E93' if dark_mode else '#A0A0A6'
        self.note_lbl.setStyleSheet('color: %s; font-size: 11px; background: transparent;' % dim)
        for c in self._file_combos + self._ver_combos:
            try:
                c._update_style()
            except Exception:
                pass
        self.ribbon.set_theme(dark_mode)

    # ── source selectors ─────────────────────────────────────
    def _fill_file_combo(self, side, select_data=None):
        combo = self._file_combos[side]
        open_files = list(getattr(self._win.session, 'open_files', []))
        externals = [p for p in self._externals[side] if p not in open_files]
        combo.blockSignals(True)
        try:
            combo.clear()
            combo.addItem(_tr('Choose file…'), ('none',))
            for p in open_files:
                combo.addItem(os.path.basename(p), ('open', p))
            for p in externals:
                combo.addItem(os.path.basename(p), ('external', p))
            if (isinstance(select_data, tuple) and len(select_data) > 1
                    and select_data[0] in ('open', 'external')
                    and combo.findData(select_data) < 0):
                # keep an active source alive even if its file just closed
                combo.addItem(os.path.basename(select_data[1]), select_data)
            combo.addItem(_tr('Browse…'), ('browse',))
            idx = combo.findData(select_data) if select_data is not None else -1
            combo.setCurrentIndex(idx if idx >= 0 else 0)
        finally:
            combo.blockSignals(False)
        self._last_file_index[side] = combo.currentIndex()

    def _rebuild_version_combo(self, side, preserve=True):
        combo = self._ver_combos[side]
        prev = combo.currentData() if preserve else None
        fd = self._file_combos[side].currentData()
        combo.blockSignals(True)
        try:
            combo.clear()
            if isinstance(fd, tuple) and fd and fd[0] == 'open':
                combo.addItem(_tr('Current'), None)
                store = EditorStore.for_path(fd[1])
                versions = store.list_versions() if store is not None else []
                try:
                    fmt = self._win.editor_page._format_version_label
                except Exception:
                    fmt = None
                for v in reversed(versions):  # newest first
                    try:
                        n = int(v.get('n', 0))
                    except Exception:
                        continue
                    label = fmt(v) if fmt is not None else ('v%04d' % n)
                    combo.addItem(label, n)
                combo.setEnabled(True)
                idx = combo.findData(prev) if prev is not None else -1
                combo.setCurrentIndex(idx if idx >= 0 else 0)
            elif isinstance(fd, tuple) and fd and fd[0] == 'external':
                combo.addItem(_tr('Current'), None)
                combo.setCurrentIndex(0)
                combo.setEnabled(False)
            else:
                combo.addItem('—', None)
                combo.setCurrentIndex(0)
                combo.setEnabled(False)
        finally:
            combo.blockSignals(False)

    def _on_file_combo_changed(self, side):
        if self._combo_guard:
            return
        combo = self._file_combos[side]
        fd = combo.currentData()
        if isinstance(fd, tuple) and fd and fd[0] == 'browse':
            try:
                path, _ = QFileDialog.getOpenFileName(self, _tr('Choose File to Compare'))
            except Exception:
                path = ''
            self._combo_guard = True
            try:
                if path:
                    path = os.path.abspath(path)
                    if path not in self._externals[side]:
                        self._externals[side].append(path)
                    self._fill_file_combo(side, ('external', path))
                else:
                    # canceled — put the previous selection back, nothing changed
                    combo.blockSignals(True)
                    try:
                        combo.setCurrentIndex(self._last_file_index[side])
                    finally:
                        combo.blockSignals(False)
                    return
            finally:
                self._combo_guard = False
        self._last_file_index[side] = combo.currentIndex()
        self._rebuild_version_combo(side, preserve=False)
        self._cache.clear()
        self.recompute()

    def _on_version_combo_changed(self, side):
        if self._combo_guard:
            return
        self._cache.clear()
        self.recompute()

    def refresh_files(self):
        open_files = list(getattr(self._win.session, 'open_files', []))
        for side in (0, 1):
            fd = self._file_combos[side].currentData()
            # M4 (M3 defect b): a compared file just closed — remap its 'Current'
            # side to an external DISK read synchronously, so the recompute below
            # never paints the dropped unsaved buffer (no stale frame)
            if (isinstance(fd, tuple) and len(fd) > 1 and fd[0] == 'open'
                    and fd[1] not in open_files
                    and self._ver_combos[side].currentData() is None):
                if fd[1] not in self._externals[side]:
                    self._externals[side].append(fd[1])
                self._cache.pop(('external', fd[1]), None)   # force a fresh disk read
                fd = ('external', fd[1])
                self._fill_file_combo(side, fd)
                self._rebuild_version_combo(side, preserve=False)
                continue
            # (a pinned version of a closed file keeps resolving from its store)
            self._fill_file_combo(side, fd)
            self._rebuild_version_combo(side, preserve=True)
        self._drop_current_disk_cache()
        self.recompute()

    def _drop_current_disk_cache(self):
        # invalidate the non-shown-'current' disk cache (M3 defect a)
        for k in list(self._cache.keys()):
            if isinstance(k, tuple) and len(k) == 3 and k[0] == 'current-disk':
                self._cache.pop(k, None)

    def set_sources(self, a, b):
        self._apply_source(0, a)
        self._apply_source(1, b)
        self._cache.clear()
        self.recompute()

    def _apply_source(self, side, source):
        if not isinstance(source, (tuple, list)) or not source:
            self._fill_file_combo(side, ('none',))
            self._rebuild_version_combo(side, preserve=False)
            return
        source = tuple(source)
        kind = source[0]
        path = source[1] if len(source) > 1 else ''
        try:
            path = os.path.abspath(str(path))
        except Exception:
            path = str(path or '')
        if not path or kind not in ('current', 'version', 'external'):
            self._fill_file_combo(side, ('none',))
            self._rebuild_version_combo(side, preserve=False)
            return
        open_files = list(getattr(self._win.session, 'open_files', []))
        as_open = (path in open_files) or kind == 'version'
        if not as_open:
            # external pick, or 'current' of a file that is not open → read from disk
            if path not in self._externals[side]:
                self._externals[side].append(path)
            self._fill_file_combo(side, ('external', path))
            self._rebuild_version_combo(side, preserve=False)
            return
        self._fill_file_combo(side, ('open', path))
        self._rebuild_version_combo(side, preserve=False)
        if kind == 'version':
            combo = self._ver_combos[side]
            try:
                idx = combo.findData(int(source[2]))
            except Exception:
                idx = -1
            if idx >= 0:
                combo.blockSignals(True)
                try:
                    combo.setCurrentIndex(idx)
                finally:
                    combo.blockSignals(False)

    def _source_from_combos(self, side):
        fd = self._file_combos[side].currentData()
        if not isinstance(fd, tuple) or not fd or fd[0] in ('none', 'browse'):
            return None
        if fd[0] == 'external':
            return ('external', fd[1])
        vd = self._ver_combos[side].currentData()
        if vd is None:
            return ('current', fd[1])
        try:
            return ('version', fd[1], int(vd))
        except Exception:
            return ('current', fd[1])

    def _update_sources(self):
        self._sources = [self._source_from_combos(0), self._source_from_combos(1)]

    # ── text resolution / recompute ──────────────────────────
    def _resolve_text(self, side):
        src = self._sources[side]
        if src is None:
            return None
        kind = src[0]
        if kind == 'current':
            path = src[1]
            try:
                shown = (path == self._win.session.current_path)
            except Exception:
                shown = True
            if shown:
                # the file on screen — always live, never cached
                return editor_live_text_for(self._win, path)
            page = getattr(self._win, 'editor_page', None)
            try:
                if page is not None and path in page._buffers:
                    return page._buffers[path]   # in-memory unsaved buffer — cheap
            except Exception:
                pass
            # M4 (M3 defect a): non-shown 'current' side with no unsaved buffer —
            # cache the disk text keyed by mtime so per-keystroke recomputes of the
            # SHOWN file do not re-read this one from disk every 300ms tick
            store = EditorStore.for_path(path)
            mtime = store.disk_mtime() if store is not None else None
            key = ('current-disk', path, mtime)
            cached = self._cache.get(key)
            if cached is not None:
                return cached
            for k in list(self._cache.keys()):
                if (isinstance(k, tuple) and len(k) == 3
                        and k[0] == 'current-disk' and k[1] == path):
                    self._cache.pop(k, None)   # drop stale-mtime leftovers
            text = store.read_disk() if store is not None else ''
            self._cache[key] = text
            return text
        cached = self._cache.get(src)
        if cached is not None:
            return cached
        text = ''
        if kind == 'version':
            store = EditorStore.for_path(src[1])
            t = store.read_version(src[2]) if store is not None else None
            text = t if t is not None else ''
        elif kind == 'external':
            try:
                with open(src[1], 'r', encoding='utf-8', errors='replace') as f:
                    text = f.read()
            except Exception:
                text = ''
        self._cache[src] = text
        return text

    def recompute(self):
        self._update_sources()
        if not self.isVisible():
            self._pending = True  # recomputed on next showEvent
            return
        self._pending = False
        self._recompute_now()

    def _recompute_now(self):
        lt = self._resolve_text(0)
        rt = self._resolve_text(1)
        lv = self.left_pane.verticalScrollBar().value()
        lh = self.left_pane.horizontalScrollBar().value()
        self._sync_guard = True
        try:
            if lt is None or rt is None:
                # a side without a source: plain text (or placeholder), no diff
                self.left_pane.setPlainText(lt or '')
                self.right_pane.setPlainText(rt or '')
                self.left_pane.setExtraSelections([])
                self.right_pane.setExtraSelections([])
                self._marks = []
                self.ribbon.set_marks([])
                self.note_lbl.hide()
            else:
                left_lines, right_lines, marks = editor_compute_diff(lt, rt)
                self._marks = marks
                self.left_pane.setPlainText('\n'.join('' if x is None else x for x in left_lines))
                self.right_pane.setPlainText('\n'.join('' if x is None else x for x in right_lines))
                truncated = self._apply_diff_colors(left_lines, right_lines, marks)
                self.ribbon.set_marks(marks)
                self.note_lbl.setVisible(truncated)
            self.left_pane.verticalScrollBar().setValue(lv)
            self.right_pane.verticalScrollBar().setValue(lv)
            self.left_pane.horizontalScrollBar().setValue(lh)
            self.right_pane.horizontalScrollBar().setValue(lh)
        finally:
            self._sync_guard = False

    def _apply_diff_colors(self, left_lines, right_lines, marks):
        def fmt_for(color):
            f = QTextCharFormat()
            f.setBackground(QBrush(color))
            try:
                f.setProperty(PyQt6.QtGui.QTextFormat.Property.FullWidthSelection, True)
            except Exception:
                pass
            return f
        fmt_del = fmt_for(QColor(255, 69, 58, 46))
        fmt_del_ghost = fmt_for(QColor(255, 69, 58, 18))
        fmt_ins = fmt_for(QColor(48, 209, 88, 46))
        fmt_ins_ghost = fmt_for(QColor(48, 209, 88, 18))
        fmt_rep = fmt_for(QColor(255, 214, 10, 40))
        fmt_rep_ghost = fmt_for(QColor(255, 214, 10, 16))
        ldoc = self.left_pane.document()
        rdoc = self.right_pane.document()
        l_sels = []
        r_sels = []
        colored = 0
        truncated = False
        for i, mark in enumerate(marks):
            if mark == 'equal':
                continue
            if colored >= 4000:
                truncated = True
                break
            colored += 1
            if mark == 'delete':
                lf, rf = fmt_del, fmt_del_ghost
            elif mark == 'insert':
                lf, rf = fmt_ins_ghost, fmt_ins
            else:
                lf = fmt_rep if left_lines[i] is not None else fmt_rep_ghost
                rf = fmt_rep if right_lines[i] is not None else fmt_rep_ghost
            lb = ldoc.findBlockByNumber(i)
            if lb.isValid():
                sel = QTextEdit.ExtraSelection()
                sel.cursor = QTextCursor(lb)
                sel.format = lf
                l_sels.append(sel)
            rb = rdoc.findBlockByNumber(i)
            if rb.isValid():
                sel = QTextEdit.ExtraSelection()
                sel.cursor = QTextCursor(rb)
                sel.format = rf
                r_sels.append(sel)
        self.left_pane.setExtraSelections(l_sels)
        self.right_pane.setExtraSelections(r_sels)
        return truncated

    # ── live refresh / sync / jump ───────────────────────────
    def _on_editor_text_changed(self):
        try:
            cur = self._win.session.current_path
        except Exception:
            cur = None
        if not cur:
            return
        if ('current', cur) in (self._sources[0], self._sources[1]):
            if self.isVisible():
                self._live_timer.start()
            else:
                self._pending = True

    def _on_file_reloaded(self, path):
        if ('current', path) in (self._sources[0], self._sources[1]):
            self._drop_current_disk_cache()
            self.recompute()

    def _sync_scroll(self, other_bar, value):
        if self._sync_guard:
            return
        self._sync_guard = True
        try:
            other_bar.setValue(value)
        finally:
            self._sync_guard = False

    def _jump_to_row(self, row):
        self._sync_guard = True
        try:
            for pane in (self.left_pane, self.right_pane):
                try:
                    line_h = max(1, pane.fontMetrics().lineSpacing())
                    visible = max(1, pane.viewport().height() // line_h)
                except Exception:
                    visible = 10
                pane.verticalScrollBar().setValue(max(0, int(row) - int(visible // 2)))
        finally:
            self._sync_guard = False

    def showEvent(self, event):
        super().showEvent(event)
        # combos may be stale (new saves, files opened/closed) — refresh, then recompute
        self.refresh_files()


# ---- M4: card dock (explain cards) + streaming LLM helper ----

from PyQt6.QtWidgets import QTextBrowser

_EDITOR_LLM_WORKERS = []          # in-flight workers — keeps the QThreads from being GC'd
_EDITOR_LLM_QUIT_HOOKED = [False]


def _editor_llm_forget(worker):
    try:
        _EDITOR_LLM_WORKERS.remove(worker)
    except ValueError:
        pass


def _editor_llm_stop_all():
    # app quit with streams mid-flight: cooperative stop, then a short bounded wait
    for worker in list(_EDITOR_LLM_WORKERS) + list(_EDITOR_KIND_CLASSIFY_WORKERS):
        try:
            worker.stop()
        except Exception:
            pass
    for worker in list(_EDITOR_LLM_WORKERS) + list(_EDITOR_KIND_CLASSIFY_WORKERS):
        try:
            worker.wait(2000)
        except Exception:
            pass


class _EditorLLMWorker(QThread):
    """Streaming chat completion for editor cards (AsyncChatThread._stream_completion essentials)."""
    delta = pyqtSignal(str)
    finished_text = pyqtSignal(str)
    failed = pyqtSignal(str)

    def __init__(self, messages, parent=None):
        super().__init__(parent)
        self._messages = [dict(m) for m in (messages or []) if isinstance(m, dict)]
        self._stop_event = threading.Event()

    def stop(self):
        # cooperative cancel — after this no further signals are emitted
        self._stop_event.set()

    def _emit_failed(self, message):
        if not self._stop_event.is_set():
            self.failed.emit(str(message))

    def run(self):
        try:
            # config resolved exactly like the main chat send path:
            # load_runtime_openai_client_config() + modelnow.txt + load_saved_timeout()
            api_key, endpoint = load_runtime_openai_client_config()
            model = str(read_text_file(BasePath + 'modelnow.txt', DEFAULT_MODEL) or '').strip() or DEFAULT_MODEL
            if not api_key:
                self._emit_failed(_tr('No API account configured — set one in Settings.'))
                return
            client = create_openai_client(api_key, endpoint, load_saved_timeout())
            chunks = []
            # Some relay endpoints silently drop {"role":"system"} items without
            # erroring (the create_chat_completion retry only fires on errors), so
            # editor instructions ride inside the user message — same technique as
            # the main send path's OUTPUT_CAPTURE_INSTRUCTIONS.
            send_messages = _merge_leading_system_messages_into_user(self._messages)
            stream = create_chat_completion(
                client,
                endpoint=endpoint,
                model=model,
                messages=send_messages,
                stream=True,
            )
            for response in stream:
                if self._stop_event.is_set():
                    return
                if not getattr(response, 'choices', None):
                    continue
                piece = getattr(response.choices[0].delta, 'content', None)
                if piece:
                    chunks.append(piece)
                    if self._stop_event.is_set():
                        return
                    self.delta.emit(piece)
            if self._stop_event.is_set():
                return
            text = ''.join(chunks)
            if text.strip():
                self.finished_text.emit(text)
            else:
                self._emit_failed(_tr('The model returned an empty answer.'))
        except Exception as exc:
            msg = str(exc).strip() or exc.__class__.__name__
            if len(msg) > 300:
                msg = msg[:300] + '…'
            self._emit_failed(_tr('Request failed: %s') % msg)


def editor_llm_request(messages, on_delta, on_finished, on_failed, parent=None):
    """Start a streaming editor LLM request; returns the started worker (caller keeps the ref)."""
    worker = _EditorLLMWorker(messages, parent)
    # explicit QueuedConnection (house pattern): delivery lands on the GUI thread
    # even for plain callables/lambdas connected from it
    if callable(on_delta):
        worker.delta.connect(on_delta, Qt.ConnectionType.QueuedConnection)
    if callable(on_finished):
        worker.finished_text.connect(on_finished, Qt.ConnectionType.QueuedConnection)
    if callable(on_failed):
        worker.failed.connect(on_failed, Qt.ConnectionType.QueuedConnection)
    _EDITOR_LLM_WORKERS.append(worker)
    worker.finished.connect(lambda w=worker: _editor_llm_forget(w),
                            Qt.ConnectionType.QueuedConnection)
    if not _EDITOR_LLM_QUIT_HOOKED[0]:
        _EDITOR_LLM_QUIT_HOOKED[0] = True
        try:
            app.aboutToQuit.connect(_editor_llm_stop_all)
        except Exception:
            pass
    worker.start()
    return worker


def editor_explain_glossary(store, selected_text, cap=40):
    """Lexicon entries whose code_name appears in the selection — confirmed first, then auto."""
    try:
        entries = (store.load_lexicon() or {}).get('entries') or []
    except Exception:
        entries = []
    selected_text = str(selected_text or '')
    picked = {'confirmed': [], 'auto': []}
    for e in entries:
        if not isinstance(e, dict) or e.get('gone'):
            continue
        status = str(e.get('status', '') or '')
        if status not in picked:
            continue  # 'missing' entries have no natural name yet
        code_name = str(e.get('code_name', '') or '')
        natural = str(e.get('natural_name', '') or '').strip()
        if not code_name or not natural or code_name not in selected_text:
            continue
        picked[status].append(e)
    lines = []
    for e in picked['confirmed'] + picked['auto']:
        if len(lines) >= cap:
            break
        line = '- %s (%s): %s' % (
            str(e.get('code_name', '')),
            str(e.get('category', '') or 'Other'),
            str(e.get('natural_name', '') or '').strip(),
        )
        desc = str(e.get('description', '') or '').strip()
        if desc:
            line += ' — ' + desc
        lines.append(line)
    return lines


def editor_explain_messages(store, payload, lang):
    """System + user messages for an Explain card."""
    payload = payload if isinstance(payload, dict) else {}
    text = str(payload.get('text', '') or '')
    path = str(payload.get('path', '') or '')
    try:
        ls = int(payload.get('line_start', 0) or 0)
        le = int(payload.get('line_end', 0) or 0)
    except Exception:
        ls = le = 0
    kind = 'code'
    try:
        if store is not None:
            kind = store.file_kind()
    except Exception:
        pass
    if kind == 'text-article':
        system = (
            'You explain an article passage concisely. Describe the main claim, local role, '
            'important concepts, and implicit assumptions. Respond in %s.' % lang
        )
    else:
        system = (
            "You are a code explainer. Explain the selected code's meaning and usage concisely. "
            'Respond in %s. Refer to code objects by the natural-language names from the '
            'provided glossary when available.' % lang
        )
    fence = '```' if '```' not in text else '````'
    line_part = ('Line %d' % ls) if ls == le else ('Lines %d–%d' % (ls, le))
    parts = [
        'File: %s (%s)' % (os.path.basename(path) or 'untitled', kind),
        line_part,
        '',
        'Selected text:' if kind == 'text-article' else 'Selected code:',
        fence,
        text,
        fence,
    ]
    glossary = editor_explain_glossary(store, text) if store is not None else []
    if glossary:
        parts += ['', 'Glossary (code name → natural name):'] + glossary
    return [
        {'role': 'system', 'content': system},
        {'role': 'user', 'content': '\n'.join(parts)},
    ]


# ---- M5: mermaid renderer + flow cards + share ----

def _editor_js_string(value):
    return json.dumps(str(value or ''), ensure_ascii=False)


def _editor_mermaid_node_id(value):
    s = re.sub(r'[^0-9A-Za-z_]', '_', str(value or '').strip())
    if not s:
        s = 'n'
    if s[0].isdigit():
        s = 'n_' + s
    return s


def _editor_mermaid_label(value):
    s = str(value or '').replace('\r\n', '\n').replace('\r', '\n').strip()
    s = html.escape(s, quote=True)
    s = s.replace('[', '#91;').replace(']', '#93;').replace('|', '#124;')
    return s.replace('\n', '<br/>')


def _editor_flow_is_tree(nodes, edges):
    ids = [str(n.get('id', '') or '') for n in nodes if isinstance(n, dict)]
    if not ids:
        return None
    id_set = set(ids)
    children = {i: [] for i in ids}
    indeg = {i: 0 for i in ids}
    if len(edges) != max(0, len(ids) - 1):
        return None
    for edge in edges:
        if not isinstance(edge, (list, tuple)) or len(edge) < 2:
            return None
        a, b = str(edge[0] or ''), str(edge[1] or '')
        if a not in id_set or b not in id_set:
            return None
        children[a].append(b)
        indeg[b] += 1
        if indeg[b] > 1:
            return None
    roots = [i for i in ids if indeg.get(i, 0) == 0]
    if len(roots) != 1:
        return None
    seen = set()

    def walk(i):
        if i in seen:
            return False
        seen.add(i)
        for child in children.get(i, []):
            if not walk(child):
                return False
        return True

    if not walk(roots[0]) or len(seen) != len(id_set):
        return None
    return roots[0], children


def editor_flow_to_mermaid(flow, mark=None, diagram='flowchart'):
    flow = flow if isinstance(flow, dict) else {}
    nodes = flow.get('nodes') if isinstance(flow.get('nodes'), list) else []
    edges = flow.get('edges') if isinstance(flow.get('edges'), list) else []
    mark = mark if isinstance(mark, dict) else {}
    if str(diagram or '') == 'mindmap':
        tree = _editor_flow_is_tree(nodes, edges)
        if tree:
            root, children = tree
            by_id = {str(n.get('id', '') or ''): n for n in nodes if isinstance(n, dict)}
            lines = ['mindmap']

            def add_node(node_id, level):
                n = by_id.get(node_id, {})
                label = str(n.get('desc', '') or node_id).replace('\n', ' ').strip()
                label = label.replace('(', '&#40;').replace(')', '&#41;')
                if level == 1:
                    lines.append('  root((%s))' % label)
                else:
                    lines.append('%s%s' % ('  ' * level, label))
                for child_id in children.get(node_id, []):
                    add_node(child_id, level + 1)

            add_node(root, 1)
            return '\n'.join(lines)
    id_map = {}
    out = ['flowchart TD']
    for n in nodes:
        if not isinstance(n, dict):
            continue
        raw_id = str(n.get('id', '') or '')
        if not raw_id:
            continue
        mid = _editor_mermaid_node_id(raw_id)
        id_map[raw_id] = mid
        out.append('    %s["%s"]' % (mid, _editor_mermaid_label(n.get('desc', raw_id))))
    for edge in edges:
        if not isinstance(edge, (list, tuple)) or len(edge) < 2:
            continue
        a, b = str(edge[0] or ''), str(edge[1] or '')
        if a not in id_map or b not in id_map:
            continue
        if len(edge) >= 3 and str(edge[2] or '').strip():
            out.append('    %s -->|%s| %s' % (
                id_map[a], _editor_mermaid_label(edge[2]), id_map[b]))
        else:
            out.append('    %s --> %s' % (id_map[a], id_map[b]))
    if mark:
        defs = {
            'added': 'fill:#DFF6E5,stroke:#2EAD67,color:#20242B',
            'removed': 'fill:#FFE5E5,stroke:#D84A4A,color:#20242B',
            'changed': 'fill:#FFF3BF,stroke:#C58B00,color:#20242B',
        }
        for name, style in defs.items():
            out.append('    classDef %s %s' % (name, style))
        for raw_id, cls in sorted(mark.items()):
            if raw_id in id_map and cls in defs:
                out.append('    class %s %s' % (id_map[raw_id], cls))
    return '\n'.join(out)


def editor_flow_messages(store, payload, lang):
    payload = payload if isinstance(payload, dict) else {}
    text = str(payload.get('text', '') or '')
    fence = '````' if '```' in text else '```'
    try:
        glossary = editor_explain_glossary(store, text, cap=40)
    except Exception:
        glossary = []
    try:
        base = os.path.basename(str(payload.get('path', '') or getattr(store, 'path', '') or 'untitled'))
    except Exception:
        base = 'untitled'
    try:
        ls = int(payload.get('line_start', 0) or 0)
        le = int(payload.get('line_end', 0) or 0)
    except Exception:
        ls = le = 0
    line_part = 'Line %d' % ls if ls == le else 'Lines %d-%d' % (ls, le)
    lang = str(lang or 'English')
    try:
        is_article = store is not None and store.file_kind() == 'text-article'
    except Exception:
        is_article = False
    if is_article:
        system = (
            'You analyze an article passage and output ONLY a JSON object, no prose, no code fences. '
            'Schema: {"title": str, "nodes": [{"id": "n1", "desc": str, '
            '"code_ref": {"symbol": str, "lines": [a, b]}}], "edges": [["n1","n2"], ...]}. '
            'Model the logical or argument structure: claim, reasons, evidence, assumptions, '
            'objections, and implications. Node descs are short natural-language idea labels in '
            + lang + ', 3-12 nodes. Prefer a tree when the passage has a hierarchy.'
        )
    else:
        system = (
            'You analyze code and output ONLY a JSON object, no prose, no code fences. '
            'Schema: {"title": str, "nodes": [{"id": "n1", "desc": str, '
            '"code_ref": {"symbol": str, "lines": [a, b]}}], '
            '"edges": [["n1","n2"], ...]}. Node descs are natural-language steps in '
            + lang +
            ', one short sentence each, 3-12 nodes. When a glossary is provided, '
            'refer to code objects ONLY by their glossary natural names.'
        )
    parts = [
        'File: %s' % base,
        'Kind: %s' % str(payload.get('kind', 'flow') or 'flow'),
        'Selection: %s' % line_part,
        ('Selected article text:' if is_article else 'Selected code:') + '\n%s\n%s\n%s' % (fence, text, fence),
    ]
    if glossary:
        parts.append('Glossary:\n' + '\n'.join(glossary))
    return [
        {'role': 'system', 'content': system},
        {'role': 'user', 'content': '\n\n'.join(parts)},
    ]


def _editor_extract_json_object(text):
    s = str(text or '').strip()
    if s.startswith('```'):
        s = re.sub(r'^```[A-Za-z0-9_-]*\s*', '', s)
        s = re.sub(r'\s*```$', '', s).strip()
    start = s.find('{')
    if start < 0:
        return ''
    depth = 0
    in_str = False
    esc = False
    for i in range(start, len(s)):
        ch = s[i]
        if in_str:
            if esc:
                esc = False
            elif ch == '\\':
                esc = True
            elif ch == '"':
                in_str = False
            continue
        if ch == '"':
            in_str = True
        elif ch == '{':
            depth += 1
        elif ch == '}':
            depth -= 1
            if depth == 0:
                return s[start:i + 1]
    return ''


def editor_parse_flow_json(text):
    raw = _editor_extract_json_object(text)
    if not raw:
        return None
    try:
        data = json.loads(raw)
    except Exception:
        return None
    if not isinstance(data, dict):
        return None
    title = str(data.get('title', '') or '').strip() or 'Flow'
    raw_nodes = data.get('nodes')
    if not isinstance(raw_nodes, list):
        return None
    nodes = []
    seen = set()
    for n in raw_nodes[:24]:
        if not isinstance(n, dict):
            continue
        nid = str(n.get('id', '') or '').strip()
        desc = str(n.get('desc', '') or '').strip()
        if not nid or not desc or nid in seen:
            continue
        seen.add(nid)
        node = {'id': nid, 'desc': desc}
        cref = n.get('code_ref')
        if isinstance(cref, dict):
            lines = cref.get('lines')
            if isinstance(lines, (list, tuple)) and len(lines) >= 2:
                try:
                    a = max(1, int(lines[0]))
                    b = max(a, int(lines[1]))
                    node['code_ref'] = {
                        'symbol': str(cref.get('symbol', '') or ''),
                        'lines': [a, b],
                    }
                except Exception:
                    pass
        nodes.append(node)
    if not nodes:
        return None
    valid = {n['id'] for n in nodes}
    edges = []
    edge_source = data.get('edges')
    for e in edge_source if isinstance(edge_source, list) else []:
        if not isinstance(e, (list, tuple)) or len(e) < 2:
            continue
        a, b = str(e[0] or '').strip(), str(e[1] or '').strip()
        if a not in valid or b not in valid:
            continue
        edge = [a, b]
        if len(e) >= 3 and str(e[2] or '').strip():
            edge.append(str(e[2] or '').strip())
        edges.append(edge)
    return {'title': title, 'nodes': nodes, 'edges': edges}


class EditorMermaidRenderer(QObject):
    def __init__(self, window):
        super().__init__(window)
        self._window = window
        self._queue = []
        self._busy = False
        self._ready = False
        self._dark = None
        self._pending_dark = None
        self._active = None
        self._deadline = 0
        self._missing_error = ''
        base_dir = os.path.dirname(os.path.abspath(__file__))
        self._base_url = QUrl.fromLocalFile(base_dir + os.sep)
        self._vendor_path = os.path.join(base_dir, 'vendor', 'mermaid.min.js')
        if not os.path.exists(self._vendor_path):
            self._missing_error = _tr('Mermaid renderer is missing vendor/mermaid.min.js.')
        # Plain CHILD widget of the editor window (never a top-level window). A
        # child parked off-viewport at (-4000,0) is clipped by the parent, never
        # becomes a standalone OS window, and always hides/destroys with the
        # editor. (An earlier FIX-5 round made it a top-level tool window "for
        # occlusion resilience" — that was an unproven benefit and it regressed
        # into a standalone diagram window that survived closing the editor;
        # reverted here. Child rendering + view.grab() are verified working.)
        self.view = QWebEngineView(window)
        self.view.setGeometry(-4000, 0, 1000, 800)
        self.view.show()
        self.view.loadFinished.connect(self._on_loaded)
        self._poll_timer = QTimer(self)
        self._poll_timer.setInterval(90)
        self._poll_timer.timeout.connect(self._poll_status)

    def render(self, mermaid_code, callback, dark_mode=None, scale=2.0):
        if self._missing_error:
            QTimer.singleShot(0, lambda: callback(None, None, self._missing_error))
            return
        if dark_mode is None:
            try:
                dark_mode = is_dark_theme(app)
            except Exception:
                dark_mode = False
        self._queue.append({
            'code': str(mermaid_code or ''),
            'callback': callback,
            'dark': bool(dark_mode),
            'scale': max(1.0, min(3.0, float(scale or 1.0))),
        })
        self._pump()

    def _shell(self, dark):
        theme = 'dark' if dark else 'default'
        bg = '#2D2D2D' if dark else '#FFFFFF'
        fg = '#F2F2F7' if dark else '#20242B'
        return """
<!doctype html>
<html>
<head>
  <meta charset="utf-8">
  <script src="vendor/mermaid.min.js"></script>
  <style>
    html, body { margin:0; padding:0; background:%s; color:%s; overflow:hidden; }
    #host { display:inline-block; padding:0; margin:0; }
    svg { display:block; background:%s; }
  </style>
</head>
<body>
  <div id="host"></div>
  <script>
    window.__flowStatus = {state:'idle'};
    mermaid.initialize({startOnLoad:false, securityLevel:'loose', theme:%s});
    window.__render = async function(code) {
      const host = document.getElementById('host');
      window.__flowStatus = {state:'running'};
      try {
        host.innerHTML = '';
        const id = 'broccoli_flow_' + Date.now();
        const result = await mermaid.render(id, code);
        host.innerHTML = result.svg || '';
        await new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(resolve)));
        const svg = host.querySelector('svg');
        if (!svg) throw new Error('Mermaid did not produce an SVG.');
        const rect = svg.getBoundingClientRect();
        const box = svg.viewBox && svg.viewBox.baseVal ? svg.viewBox.baseVal : null;
        const w = Math.ceil(rect.width || (box ? box.width : 0) || 800);
        const h = Math.ceil(rect.height || (box ? box.height : 0) || 600);
        window.__flowStatus = {state:'ok', w:w, h:h, svg:svg.outerHTML};
      } catch (err) {
        window.__flowStatus = {state:'err', err:String((err && err.message) || err || 'Render failed')};
      }
    };
  </script>
</body>
</html>
""" % (bg, fg, bg, json.dumps(theme))

    def _load_shell(self, dark):
        self._ready = False
        self._pending_dark = bool(dark)
        self.view.setHtml(self._shell(bool(dark)), self._base_url)

    def _on_loaded(self, ok):
        self._ready = bool(ok)
        if ok:
            self._dark = self._pending_dark
        self._pending_dark = None
        self._pump()

    def _pump(self):
        if self._busy or not self._queue:
            return
        req = self._queue[0]
        if not self._ready or self._dark != req['dark']:
            if self._pending_dark is None:
                self._load_shell(req['dark'])
            return
        self._queue.pop(0)
        self._busy = True
        self._active = req
        self._deadline = time.time() + 8.0
        try:
            self.view.setZoomFactor(req['scale'])
            self.view.resize(1000, 800)
            self.view.move(-4000, 0)
            self.view.show()
            self.view.page().runJavaScript('window.__render(%s);' % _editor_js_string(req['code']))
            self._poll_timer.start()
        except Exception as exc:
            self._finish(None, None, _tr('Mermaid render failed: %s') % exc)

    def _poll_status(self):
        if time.time() > self._deadline:
            self._finish(None, None, _tr('Mermaid render timed out.'))
            return
        try:
            self.view.page().runJavaScript('window.__flowStatus || {state:"missing"};', self._on_status)
        except Exception as exc:
            self._finish(None, None, _tr('Mermaid render failed: %s') % exc)

    def _on_status(self, status):
        if not self._busy:
            return
        if not isinstance(status, dict):
            return
        state = str(status.get('state', '') or '')
        if state == 'err':
            err_text = str(status.get('err', '') or '')
            # the shell page's own fallbacks are English codes; translate the shown copy
            if err_text in ('Mermaid did not produce an SVG.', 'Render failed'):
                err_text = _tr(err_text)
            self._finish(None, None, err_text or _tr('Mermaid render failed.'))
            return
        if state != 'ok':
            return
        try:
            scale = float((self._active or {}).get('scale', 2.0) or 2.0)
            w = min(4096, max(120, int(float(status.get('w', 1000) or 1000) * scale)))
            h = min(4096, max(120, int(float(status.get('h', 800) or 800) * scale)))
            svg_text = str(status.get('svg', '') or '')
            self.view.resize(w, h)
            self.view.move(-4000, 0)
            self.view.show()
            self._poll_timer.stop()
            QTimer.singleShot(140, lambda s=svg_text, sc=scale: self._grab_result(s, sc))
        except Exception as exc:
            self._finish(None, None, _tr('Mermaid capture failed: %s') % exc)

    @staticmethod
    def _autocrop(pm, margin=16):
        """Crop the grabbed page to the diagram's content bounds (the reported
        SVG size can be much larger than the drawing, leaving a huge empty
        canvas around a tiny diagram)."""
        try:
            img = pm.toImage()
            w, h = img.width(), img.height()
            if w < 8 or h < 8:
                return pm
            bg = img.pixel(0, 0)
            step = 2 if max(w, h) > 1600 else 1

            def row_has_content(y):
                for x in range(0, w, step):
                    if img.pixel(x, y) != bg:
                        return True
                return False

            def col_has_content(x, y0, y1):
                for y in range(y0, y1, step):
                    if img.pixel(x, y) != bg:
                        return True
                return False

            top = 0
            while top < h and not row_has_content(top):
                top += step
            if top >= h:
                return pm  # blank image — leave untouched, caller shows it as-is
            bottom = h - 1
            while bottom > top and not row_has_content(bottom):
                bottom -= step
            left = 0
            while left < w and not col_has_content(left, top, bottom + 1):
                left += step
            right = w - 1
            while right > left and not col_has_content(right, top, bottom + 1):
                right -= step
            left = max(0, left - margin)
            top = max(0, top - margin)
            right = min(w - 1, right + margin)
            bottom = min(h - 1, bottom + margin)
            if right - left < 24 or bottom - top < 24:
                return pm
            cropped = QPixmap.fromImage(img.copy(left, top, right - left + 1, bottom - top + 1))
            return cropped if not cropped.isNull() else pm
        except Exception:
            return pm

    def _grab_result(self, svg_text, scale):
        if not self._busy:
            return
        try:
            pm = self.view.grab()
            if pm.isNull():
                self._finish(None, None, _tr('Mermaid capture returned an empty image.'))
                return
            pm = self._autocrop(pm, margin=int(12 * max(1.0, float(scale or 1.0))))
            pm.setDevicePixelRatio(max(1.0, float(scale or 1.0)))
            self._finish(pm, svg_text, None)
        except Exception as exc:
            self._finish(None, None, _tr('Mermaid capture failed: %s') % exc)

    def _finish(self, pixmap, svg_text, err):
        self._poll_timer.stop()
        req = self._active
        self._active = None
        self._busy = False
        cb = req.get('callback') if isinstance(req, dict) else None
        if callable(cb):
            try:
                cb(pixmap, svg_text, err)
            except Exception:
                pass
        self._pump()


class EditorDiagramView(QGraphicsView):
    def __init__(self, parent=None):
        super().__init__(parent)
        self._scene = QGraphicsScene(self)
        self.setScene(self._scene)
        self._pixmap_item = None
        self._zoom = 1.0
        self._min_zoom = 0.4
        self._user_zoomed = False
        self._pixmap = QPixmap()
        self.setFrameShape(QFrame.Shape.NoFrame)
        self.setRenderHints(QPainter.RenderHint.Antialiasing | QPainter.RenderHint.SmoothPixmapTransform)
        self.setTransformationAnchor(QGraphicsView.ViewportAnchor.AnchorUnderMouse)
        self.setResizeAnchor(QGraphicsView.ViewportAnchor.AnchorViewCenter)
        self.setDragMode(QGraphicsView.DragMode.ScrollHandDrag)
        self.setCursor(Qt.CursorShape.OpenHandCursor)
        self.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAsNeeded)
        self.setVerticalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAsNeeded)

    def set_theme(self, dark_mode):
        self._dark = bool(dark_mode)
        bg = '#1F1F21' if dark_mode else '#F7F8FA'
        self.setStyleSheet('QGraphicsView { border: none; background: %s; border-radius: 10px; }' % bg)
        self.setBackgroundBrush(QBrush(QColor(bg)))

    def set_pixmap(self, pm):
        self._pixmap = pm if isinstance(pm, QPixmap) else QPixmap()
        self._scene.clear()
        self._pixmap_item = None
        self._user_zoomed = False
        if not self._pixmap.isNull():
            self._pixmap_item = self._scene.addPixmap(self._pixmap)
            self._scene.setSceneRect(self._pixmap_item.boundingRect())
        self.reset_view()

    def set_placeholder(self, text):
        # Shown instead of a blank canvas when there is no diagram or the render
        # failed — an honest empty-state beats a silent void.
        self._scene.clear()
        self._pixmap_item = None
        self._pixmap = QPixmap()
        self._user_zoomed = False
        try:
            self.resetTransform()
            self._zoom = 1.0
            item = self._scene.addText(str(text or ''))
            col = QColor('#8E8E93' if getattr(self, '_dark', False) else '#A0A0A6')
            item.setDefaultTextColor(col)
            self._scene.setSceneRect(item.boundingRect())
            self.centerOn(item)
        except Exception:
            pass

    def reset_view(self):
        # Fit the diagram to the CURRENT viewport. Cards call set_pixmap while
        # the dock is still animating/laying out, so resizeEvent re-fits until
        # the user zooms manually.
        self.resetTransform()
        self._zoom = 1.0
        self._min_zoom = 0.4
        if self._pixmap_item is None:
            return
        try:
            br = self._pixmap_item.boundingRect()
            vp = self.viewport().rect()
            if br.width() > 1 and br.height() > 1 and vp.width() > 24 and vp.height() > 24:
                fit = min(vp.width() / br.width(), vp.height() / br.height()) * 0.94
                applied = fit if fit < 1.0 else min(fit, 2.0)
                if applied > 0:
                    self.scale(applied, applied)
                    self._zoom = applied
                    self._min_zoom = min(0.4, applied)
            self.centerOn(self._pixmap_item)
        except Exception:
            pass

    def resizeEvent(self, event):
        super().resizeEvent(event)
        if not getattr(self, '_user_zoomed', False):
            self.reset_view()

    def wheelEvent(self, event):
        delta = event.angleDelta().y()
        if delta == 0:
            event.ignore()
            return
        self._user_zoomed = True
        factor = 1.15 if delta > 0 else 1.0 / 1.15
        new_zoom = max(getattr(self, '_min_zoom', 0.4), min(3.0, self._zoom * factor))
        real = new_zoom / max(0.001, self._zoom)
        self._zoom = new_zoom
        self.scale(real, real)
        event.accept()

    def mousePressEvent(self, event):
        if event.button() == Qt.MouseButton.LeftButton:
            self.setCursor(Qt.CursorShape.ClosedHandCursor)
        super().mousePressEvent(event)

    def mouseReleaseEvent(self, event):
        self.setCursor(Qt.CursorShape.OpenHandCursor)
        super().mouseReleaseEvent(event)


# ---- M6: lexicon page + parser + object/function cards ----

import ast as _editor_ast
from PyQt6.QtCore import QAbstractTableModel, QSortFilterProxyModel, QModelIndex
from PyQt6.QtWidgets import QTableView, QStyledItemDelegate
from PyQt6.QtGui import QFont


def _editor_now_iso():
    return datetime.datetime.now().isoformat(timespec='seconds')


def _editor_is_pyqtsignal_call(value):
    if not isinstance(value, _editor_ast.Call):
        return False
    func = value.func
    if isinstance(func, _editor_ast.Name):
        return func.id == 'pyqtSignal'
    if isinstance(func, _editor_ast.Attribute):
        return func.attr == 'pyqtSignal'
    return False


def _editor_target_names(target):
    out = []
    if isinstance(target, _editor_ast.Name):
        out.append(target.id)
    elif isinstance(target, _editor_ast.Attribute):
        if isinstance(target.value, _editor_ast.Name) and target.value.id == 'self':
            out.append('self.' + target.attr)
    elif isinstance(target, (_editor_ast.Tuple, _editor_ast.List)):
        for child in target.elts:
            out.extend(_editor_target_names(child))
    elif isinstance(target, _editor_ast.Starred):
        out.extend(_editor_target_names(target.value))
    return out


class _EditorIdentifierVisitor(_editor_ast.NodeVisitor):
    def __init__(self):
        self.items = []
        self.seen = set()
        self.class_stack = []
        self.func_stack = []

    def _add(self, name, category, line):
        if not name or name in self.seen:
            return
        self.seen.add(name)
        self.items.append({'code_name': str(name), 'category': category, 'line': int(line or 1)})

    def visit_ClassDef(self, node):
        self._add(node.name, 'Class', getattr(node, 'lineno', 1))
        self.class_stack.append(node.name)
        old_funcs = list(self.func_stack)
        self.func_stack = []
        for child in node.body:
            self.visit(child)
        self.func_stack = old_funcs
        self.class_stack.pop()

    def visit_FunctionDef(self, node):
        self._visit_function(node)

    def visit_AsyncFunctionDef(self, node):
        self._visit_function(node)

    def _visit_function(self, node):
        if self.class_stack and not self.func_stack:
            name = self.class_stack[-1] + '.' + node.name
        elif self.func_stack:
            name = '.'.join(self.func_stack + [node.name])
        else:
            name = node.name
        self._add(name, 'Function', getattr(node, 'lineno', 1))
        self.func_stack.append(name)
        for child in node.body:
            self.visit(child)
        self.func_stack.pop()

    def visit_Assign(self, node):
        category = 'Signal' if _editor_is_pyqtsignal_call(getattr(node, 'value', None)) else 'Variable'
        for target in getattr(node, 'targets', []) or []:
            for name in _editor_target_names(target):
                self._add(name, category, getattr(node, 'lineno', 1))
        self.generic_visit(node)

    def visit_AnnAssign(self, node):
        category = 'Signal' if _editor_is_pyqtsignal_call(getattr(node, 'value', None)) else 'Variable'
        for name in _editor_target_names(getattr(node, 'target', None)):
            self._add(name, category, getattr(node, 'lineno', 1))
        self.generic_visit(node)


def editor_extract_identifiers(text, kind):
    text = str(text or '')
    kind = str(kind or '')
    if kind == 'code-python':
        try:
            tree = _editor_ast.parse(text)
        except SyntaxError:
            return None
        visitor = _EditorIdentifierVisitor()
        visitor.visit(tree)
        return visitor.items
    if kind == 'text-article':
        out = []
        seen = set()
        lines = text.splitlines()
        for i, line in enumerate(lines, 1):
            m = re.match(r'^\s{0,3}#{1,6}\s+(.+?)\s*#*\s*$', line)
            if m:
                name = m.group(1).strip()
                if name and name not in seen:
                    seen.add(name)
                    out.append({'code_name': name, 'category': 'Concept', 'line': i})
        start = 1
        buf = []
        for i, line in enumerate(lines + [''], 1):
            if line.strip():
                if not buf:
                    start = i
                buf.append(line.strip())
                continue
            para = ' '.join(buf).strip()
            if len(para) > 40:
                name = para[:30] + '…'
                if name not in seen:
                    seen.add(name)
                    out.append({'code_name': name, 'category': 'Paragraph', 'line': start})
            buf = []
        return out
    # generic 'code': .md/.txt files holding real Python are common (generated
    # outputs) — a successful ast parse beats the coarse regex sweep
    try:
        tree = _editor_ast.parse(text)
        visitor = _EditorIdentifierVisitor()
        visitor.visit(tree)
        if visitor.items:
            return visitor.items
    except Exception:
        pass
    out = []
    seen = set()

    def add(name, category, line):
        if name and name not in seen:
            seen.add(name)
            out.append({'code_name': name, 'category': category, 'line': line})

    patterns = [
        (r'\bclass\s+([A-Za-z_$][\w$]*)', 'Class'),
        (r'\b(?:function\s+|def\s+)([A-Za-z_$][\w$]*)\s*\(', 'Function'),
        (r'\b(?:const|let|var)\s+([A-Za-z_$][\w$]*)', 'Variable'),
    ]
    for line_no, line in enumerate(text.splitlines(), 1):
        for pat, cat in patterns:
            for m in re.finditer(pat, line):
                add(m.group(1), cat, line_no)
    return out


def editor_merge_lexicon(store, parsed):
    if store is None or parsed is None:
        return False
    try:
        lex = store.load_lexicon()
    except Exception:
        return False
    if not isinstance(lex, dict):
        return False
    entries = lex.get('entries')
    if not isinstance(entries, list):
        entries = []
        lex['entries'] = entries
    by_name = {}
    max_id = 0
    for e in entries:
        if not isinstance(e, dict):
            continue
        by_name[str(e.get('code_name', '') or '')] = e
        m = re.match(r'^e(\d+)$', str(e.get('id', '') or ''))
        if m:
            max_id = max(max_id, int(m.group(1)))
    changed = False
    seen = set()
    now = _editor_now_iso()
    for item in parsed:
        if not isinstance(item, dict):
            continue
        code_name = str(item.get('code_name', '') or '').strip()
        if not code_name:
            continue
        seen.add(code_name)
        category = str(item.get('category', '') or 'Other')
        try:
            line = max(1, int(item.get('line', 1) or 1))
        except Exception:
            line = 1
        existing = by_name.get(code_name)
        if existing is None:
            max_id += 1
            entries.append({
                'id': 'e%04d' % max_id,
                'code_name': code_name,
                'category': category,
                'natural_name': '',
                'description': '',
                'status': 'missing',
                'source': 'parser',
                'gone': False,
                'anchors': [{'line': line}],
                'updated_at': now,
            })
            changed = True
            continue
        anchors = existing.get('anchors')
        old_line = None
        try:
            old_line = int((anchors or [{}])[0].get('line', 0))
        except Exception:
            old_line = None
        if old_line != line:
            existing['anchors'] = [{'line': line}]
            changed = True
        if bool(existing.get('gone')):
            existing['gone'] = False
            changed = True
        if str(existing.get('source', '') or '') == 'parser' and str(existing.get('category', '') or '') != category:
            existing['category'] = category
            changed = True
    for e in entries:
        if not isinstance(e, dict):
            continue
        name = str(e.get('code_name', '') or '')
        if name and name not in seen and not bool(e.get('gone')):
            e['gone'] = True
            changed = True
    if changed:
        store.save_lexicon(lex)
    return changed


class _EditorParseWorker(QThread):
    parsed = pyqtSignal(object, int, object)

    def __init__(self, text, kind, serial, parent=None):
        super().__init__(parent)
        self._text = str(text or '')
        self._kind = str(kind or '')
        self._serial = int(serial)

    def run(self):
        result = None
        err = None
        try:
            result = editor_extract_identifiers(self._text, self._kind)
            if result is None and self._kind == 'code-python':
                try:
                    _editor_ast.parse(self._text)
                except SyntaxError as exc:
                    err = _tr('Parse error at line %s') % str(getattr(exc, 'lineno', '') or '?')
        except Exception as exc:
            err = str(exc)
        self.parsed.emit(result, self._serial, err)


class EditorLexiconModel(QAbstractTableModel):
    HEADERS = [_tr('Code Name'), _tr('Category'), _tr('Natural Name'), _tr('Description'), _tr('Status')]

    def __init__(self, page):
        super().__init__(page)
        self._page = page
        self.entries = []

    def set_entries(self, entries):
        self.beginResetModel()
        self.entries = [e for e in (entries or []) if isinstance(e, dict)]
        self.endResetModel()

    def rowCount(self, parent=QModelIndex()):
        return 0 if parent.isValid() else len(self.entries)

    def columnCount(self, parent=QModelIndex()):
        return 0 if parent.isValid() else len(self.HEADERS)

    def headerData(self, section, orientation, role=Qt.ItemDataRole.DisplayRole):
        if role == Qt.ItemDataRole.DisplayRole and orientation == Qt.Orientation.Horizontal:
            if 0 <= section < len(self.HEADERS):
                return self.HEADERS[section]
        return None

    def data(self, index, role=Qt.ItemDataRole.DisplayRole):
        if not index.isValid():
            return None
        row = index.row()
        col = index.column()
        if not (0 <= row < len(self.entries)):
            return None
        e = self.entries[row]
        keys = ['code_name', 'category', 'natural_name', 'description', 'status']
        key = keys[col] if 0 <= col < len(keys) else ''
        if role in (Qt.ItemDataRole.DisplayRole, Qt.ItemDataRole.EditRole):
            return str(e.get(key, '') or '')
        if role == Qt.ItemDataRole.UserRole:
            return e
        if role == Qt.ItemDataRole.ForegroundRole:
            if e.get('gone'):
                return QBrush(QColor('#8E8E93'))
            if str(e.get('status', '') or '') in ('missing', 'auto'):
                return QBrush(QColor('#8E8E93' if self._page._dark else '#6E6E73'))
        if role == Qt.ItemDataRole.FontRole:
            f = QFont()
            if str(e.get('status', '') or '') == 'auto' and col in (2, 3):
                f.setItalic(True)
            if e.get('gone') and col == 0:
                f.setStrikeOut(True)
            return f
        return None

    def flags(self, index):
        if not index.isValid():
            return Qt.ItemFlag.NoItemFlags
        flags = Qt.ItemFlag.ItemIsSelectable | Qt.ItemFlag.ItemIsEnabled
        if index.column() in (1, 2, 3):
            flags |= Qt.ItemFlag.ItemIsEditable
        return flags

    def setData(self, index, value, role=Qt.ItemDataRole.EditRole):
        if role != Qt.ItemDataRole.EditRole or not index.isValid():
            return False
        row = index.row()
        col = index.column()
        if not (0 <= row < len(self.entries)):
            return False
        e = self.entries[row]
        value = str(value or '').strip()
        if col == 1:
            e['category'] = value or str(e.get('category', '') or 'Other')
        elif col == 2:
            e['natural_name'] = value
            e['status'] = 'confirmed'
            e['source'] = 'user'
        elif col == 3:
            e['description'] = value
            e['status'] = 'confirmed'
            e['source'] = 'user'
        else:
            return False
        e['updated_at'] = _editor_now_iso()
        self.dataChanged.emit(index, index, [Qt.ItemDataRole.DisplayRole, Qt.ItemDataRole.EditRole])
        self._page.persist_lexicon()
        return True


class EditorLexiconProxy(QSortFilterProxyModel):
    def __init__(self, parent=None):
        super().__init__(parent)
        self.query = ''
        self.category = 'All'
        self.setDynamicSortFilter(True)

    def set_query(self, text):
        self.query = str(text or '').lower().strip()
        self.invalidateFilter()

    def set_category(self, category):
        self.category = str(category or 'All')
        self.invalidateFilter()

    def filterAcceptsRow(self, source_row, source_parent):
        model = self.sourceModel()
        if model is None:
            return True
        idx = model.index(source_row, 0, source_parent)
        entry = model.data(idx, Qt.ItemDataRole.UserRole)
        if not isinstance(entry, dict):
            return False
        if self.category and self.category != 'All':
            if str(entry.get('category', '') or '') != self.category:
                return False
        q = self.query
        if q:
            blob = ' '.join([
                str(entry.get('code_name', '') or ''),
                str(entry.get('natural_name', '') or ''),
                str(entry.get('description', '') or ''),
            ]).lower()
            if q not in blob:
                return False
        return True


class NativePopupComboBox(QComboBox):
    """A combo box whose list is the system pop-up menu (Liquid Glass, ✓ on the current
    item, which sits on the box like a pop-up button's). Qt's macOS style never asks for
    the native pop-up, so a plain QComboBox draws its own list. Qt's list stays the
    fallback (off macOS, BROCCOLI_NATIVE_DROPDOWNS=0)."""

    def showPopup(self):
        if not NATIVE_DROPDOWNS_ENABLED or self.count() == 0:
            super().showPopup()
            return
        menu = QMenu(self)
        actions = []
        for index in range(self.count()):
            action = menu.addAction(self.itemText(index).replace('&', '&&'))
            action.setCheckable(True)
            action.setChecked(index == self.currentIndex())
            actions.append(action)
        current = actions[self.currentIndex()] if 0 <= self.currentIndex() < len(actions) else None
        anchor = self.mapToGlobal(QPoint(0, 0)) if current is not None else self.mapToGlobal(QPoint(0, self.height() + 4))
        try:
            handled, chosen = exec_native_qmenu(menu, anchor, presentation='dropdown', positioning_action=current,
                                                min_width=self.width())
        finally:
            menu.deleteLater()
        if not handled:
            super().showPopup()
            return
        if chosen is not None and chosen in actions:
            index = actions.index(chosen)
            self.setCurrentIndex(index)
            self.activated.emit(index)
            self.textActivated.emit(self.itemText(index))


class EditorCategoryDelegate(QStyledItemDelegate):
    def __init__(self, page):
        super().__init__(page)
        self._page = page

    def createEditor(self, parent, option, index):
        combo = NativePopupComboBox(parent)
        try:
            combo.addItems(self._page.categories())
        except Exception:
            combo.addItems(['Variable', 'Function', 'Class', 'Signal', 'Other'])
        return combo

    def setEditorData(self, editor, index):
        value = str(index.data(Qt.ItemDataRole.EditRole) or '')
        i = editor.findText(value)
        editor.setCurrentIndex(i if i >= 0 else 0)

    def setModelData(self, editor, model, index):
        model.setData(index, editor.currentText(), Qt.ItemDataRole.EditRole)


def editor_entry_text(entry):
    entry = entry if isinstance(entry, dict) else {}
    name = str(entry.get('code_name', '') or '')
    natural = str(entry.get('natural_name', '') or '').strip()
    desc = str(entry.get('description', '') or '').strip()
    text = name
    if natural:
        text += ' — ' + natural
    if desc:
        text += ': ' + desc
    return text


def editor_find_entry(store, entry_id):
    if store is None:
        return None
    try:
        for e in (store.load_lexicon() or {}).get('entries') or []:
            if isinstance(e, dict) and str(e.get('id', '') or '') == str(entry_id or ''):
                return e
    except Exception:
        pass
    return None


def editor_entry_for_flow_node(store, node):
    if store is None or not isinstance(node, dict):
        return None
    cref = node.get('code_ref') if isinstance(node.get('code_ref'), dict) else {}
    symbol = str(cref.get('symbol', '') or '').strip()
    desc = str(node.get('desc', '') or '').strip().lower()
    try:
        entries = (store.load_lexicon() or {}).get('entries') or []
    except Exception:
        entries = []
    for e in entries:
        if not isinstance(e, dict) or e.get('gone'):
            continue
        code_name = str(e.get('code_name', '') or '').strip()
        if symbol and code_name == symbol:
            return e
    for e in entries:
        if not isinstance(e, dict) or e.get('gone'):
            continue
        for key in ('natural_name', 'code_name'):
            term = str(e.get(key, '') or '').strip().lower()
            if term and term in desc:
                return e
    return None


def editor_linkify_lexicon_terms(html_text, store):
    if store is None:
        return html_text
    try:
        entries = (store.load_lexicon() or {}).get('entries') or []
    except Exception:
        entries = []
    terms = []
    seen = set()
    for e in entries:
        if not isinstance(e, dict) or e.get('gone'):
            continue
        if str(e.get('status', '') or '') not in {'confirmed', 'auto'}:
            continue
        entry_id = str(e.get('id', '') or '').strip()
        natural = str(e.get('natural_name', '') or '').strip()
        if not entry_id or not natural:
            continue
        for key in ('code_name', 'natural_name'):
            term = str(e.get(key, '') or '').strip()
            if not term:
                continue
            dedupe = (term.lower(), entry_id)
            if dedupe in seen:
                continue
            seen.add(dedupe)
            terms.append((term, entry_id, key == 'code_name'))
    # Terms containing private-use chars could forge the placeholder tokens below.
    terms = [t for t in terms if not any(0xE000 <= ord(ch) <= 0xF8FF for ch in t[0])]
    if not terms:
        return html_text
    terms.sort(key=lambda item: len(item[0]), reverse=True)

    def _pua_token(kind_char, index):
        # Token body is pure private-use chars: no lexicon term (plain text,
        # PUA-filtered above) can ever match inside it.
        digits = ''.join(chr(0xE010 + int(d)) for d in str(int(index)))
        return chr(0xE000) + kind_char + digits + chr(0xE001)

    protected = []

    def protect(match):
        token = _pua_token(chr(0xE004), len(protected))
        protected.append((token, match.group(0)))
        return token

    html_text = re.sub(r'(?is)<(?:a|code|pre)\b[^>]*>.*?</(?:a|code|pre)>', protect, str(html_text or ''))

    def linkify_text_segment(segment):
        replacements = []
        protected_entities = []

        def protect_entity(match):
            token = _pua_token(chr(0xE003), len(protected_entities))
            protected_entities.append((token, match.group(0)))
            return token

        segment = re.sub(r'&(?:amp|lt|gt|quot|#\d+|#x[0-9A-Fa-f]+);', protect_entity, segment)
        for term, entry_id, word_boundary in terms[:120]:
            escaped = html.escape(term, quote=False)
            if not escaped:
                continue
            pattern = re.escape(escaped)
            if word_boundary:
                pattern = r'(?<![0-9A-Za-z_])' + pattern + r'(?![0-9A-Za-z_])'

            def repl(match, eid=entry_id):
                token = _pua_token(chr(0xE002), len(replacements))
                label = match.group(0)
                href = 'broccoli-lex://%s' % html.escape(eid, quote=True)
                # Qt rich text ignores border-bottom on inline anchors; a plain
                # underline is the only link affordance its engine renders.
                replacements.append((token, '<a href="%s" style="color:#0A84FF;text-decoration:underline;">%s</a>' % (href, label)))
                return token

            segment = re.sub(pattern, repl, segment)
        for token, value in replacements:
            segment = segment.replace(token, value)
        for token, value in protected_entities:
            segment = segment.replace(token, value)
        return segment

    chunks = re.split(r'(<[^>]+>)', html_text)
    for i, chunk in enumerate(chunks):
        if i % 2 == 0 and chunk:
            chunks[i] = linkify_text_segment(chunk)
    html_text = ''.join(chunks)
    for token, value in protected:
        html_text = html_text.replace(token, value)
    return html_text


def editor_code_context_for_entry(store, entry, radius=60):
    text = store.read_disk() if store is not None else ''
    lines = text.splitlines()
    try:
        anchor = int(((entry.get('anchors') or [{}])[0]).get('line', 1))
    except Exception:
        anchor = 1
    start = max(1, anchor - int(radius))
    end = min(len(lines), anchor + int(radius))
    if store is not None and store.file_kind() == 'code-python':
        try:
            tree = _editor_ast.parse(text)
            target = str(entry.get('code_name', '') or '')
            for node in _editor_ast.walk(tree):
                if isinstance(node, (_editor_ast.FunctionDef, _editor_ast.AsyncFunctionDef, _editor_ast.ClassDef)):
                    if getattr(node, 'lineno', 0) == anchor or getattr(node, 'name', '') == target.split('.')[-1]:
                        if abs(int(getattr(node, 'lineno', anchor)) - anchor) <= 2:
                            start = max(1, int(getattr(node, 'lineno', anchor)))
                            end = min(len(lines), int(getattr(node, 'end_lineno', end) or end))
                            break
        except Exception:
            pass
    snippet = '\n'.join(lines[start - 1:end])
    return snippet, start, end


def editor_parse_name_json(text):
    raw = _editor_extract_json_object(text)
    if not raw:
        return None
    try:
        data = json.loads(raw)
    except Exception:
        return None
    if not isinstance(data, dict):
        return None
    natural = str(data.get('natural_name', '') or '').strip()
    desc = str(data.get('description', '') or '').strip()
    if not natural:
        return None
    return {'natural_name': natural, 'description': desc}


def editor_name_messages(store, entry, lang):
    snippet, start, end = editor_code_context_for_entry(store, entry, radius=30)
    return [
        {'role': 'system',
         'content': 'Name one code object. Return ONLY JSON {"natural_name": str, "description": str}. Respond in %s.' % str(lang or 'English')},
        {'role': 'user',
         'content': 'Entry: %s (%s)\nLines %d-%d:\n```\n%s\n```' % (
             str(entry.get('code_name', '') or ''),
             str(entry.get('category', '') or 'Other'),
             start, end, snippet,
        )},
    ]


# ---- FIX-38: Debug tab — AI bug scan prompt/parse ----
EDITOR_DEBUG_MAX_CHARS = 30000
EDITOR_DEBUG_SEVERITIES = ('critical', 'high', 'medium', 'low')


def editor_debug_severity_rank(severity):
    try:
        return EDITOR_DEBUG_SEVERITIES.index(str(severity or '').strip().lower())
    except ValueError:
        return 2  # unknown → medium


def editor_debug_display_label(code):
    """Shown label for a bug severity/status code (the stored code stays English)."""
    code = str(code or '').strip()
    labels = {
        'critical': _tr('critical'), 'high': _tr('high'), 'medium': _tr('medium'), 'low': _tr('low'),
        'open': _tr('open'), 'fixed': _tr('fixed'), 'feature': _tr('feature'),
    }
    return labels.get(code.lower(), code)


def editor_debug_verifiable_ids(bugs, content):
    """Open-bug ids the scan can actually judge: when the content is truncated to
    EDITOR_DEBUG_MAX_CHARS, a bug past the included window must NOT receive a
    still_present verdict (the model would 'resolve' it just because it cannot
    see it). Unknown-line bugs (line_start 0) stay verifiable."""
    content = str(content or '')
    open_ids = set()
    if len(content) <= EDITOR_DEBUG_MAX_CHARS:
        for b in bugs or []:
            if isinstance(b, dict) and b.get('status') == 'open':
                open_ids.add(str(b.get('id', '') or ''))
        return open_ids
    window_lines = content[:EDITOR_DEBUG_MAX_CHARS].count('\n')
    for b in bugs or []:
        if not isinstance(b, dict) or b.get('status') != 'open':
            continue
        try:
            line_start = int(b.get('line_start', 0) or 0)
        except (TypeError, ValueError):
            line_start = 0
        if line_start <= window_lines:
            open_ids.add(str(b.get('id', '') or ''))
    return open_ids


def editor_debug_scan_messages(store, content, bugs, lang):
    """One user-role message (the relay silently drops system role): full file
    (capped), the known OPEN bugs for cross-checking, and the user's 'this is a
    feature, not a bug' verdicts as do-not-re-report ids. Open bugs beyond a
    truncated window are NOT listed (no verdict can be honest for them)."""
    bugs = [b for b in (bugs or []) if isinstance(b, dict)]
    verifiable = editor_debug_verifiable_ids(bugs, content)
    known = [
        {'id': str(b.get('id', '') or ''), 'title': str(b.get('title', '') or ''),
         'line_start': int(b.get('line_start', 0) or 0), 'line_end': int(b.get('line_end', 0) or 0)}
        for b in bugs
        if b.get('status') == 'open' and str(b.get('id', '') or '') in verifiable
    ]
    not_bug_titles = [
        {'id': str(b.get('id', '') or ''), 'title': str(b.get('title', '') or '')}
        for b in bugs if b.get('status') == 'feature'
    ]
    content = str(content or '')
    truncated = len(content) > EDITOR_DEBUG_MAX_CHARS
    body = content[:EDITOR_DEBUG_MAX_CHARS]
    fence = '```' if '```' not in body else '````'
    name = 'file'
    kind = 'code'
    try:
        name = os.path.basename(store.path)
        kind = store.file_kind()
    except Exception:
        pass
    parts = [
        'You are a meticulous code reviewer hunting REAL defects in one file.',
        'Report only genuine bugs: logic errors, crashes, data corruption/loss, races,',
        'security holes, resource leaks, off-by-one/boundary mistakes. Never report',
        'style, naming, or preference issues.',
        'Write every explanation in %s, detailed natural language: what goes wrong,' % str(lang or 'English'),
        'under which conditions, and by what mechanism (a few sentences each).',
        '',
        'Return ONLY a JSON object, exactly this shape:',
        '{"existing": [{"id": str, "still_present": bool}],',
        ' "new_bugs": [{"title": str, "severity": "critical|high|medium|low",',
        '               "category": str, "line_start": int, "line_end": int,',
        '               "explanation": str}]}',
        '"existing" MUST contain one entry for EVERY known open bug id listed below,',
        'stating whether that bug still exists in the current code.',
        '"new_bugs" lists only defects NOT already covered by a known open bug.',
        '',
        'Known open bugs (cross-check these): %s' % json.dumps(known, ensure_ascii=False),
        'User-confirmed NOT bugs (never re-report anything equivalent): %s'
        % json.dumps(not_bug_titles, ensure_ascii=False),
        '',
        'File: %s (kind: %s)%s' % (name, kind, ' — content truncated to first %d chars'
                                   % EDITOR_DEBUG_MAX_CHARS if truncated else ''),
        fence,
        body,
        fence,
    ]
    return [{'role': 'user', 'content': '\n'.join(parts)}]


def editor_parse_debug_json(text):
    """Tolerant parse of the scan answer → {'existing': [...], 'new_bugs': [...]} or None."""
    raw = _editor_extract_json_object(text)
    if not raw:
        return None
    try:
        data = json.loads(raw)
    except Exception:
        return None
    if not isinstance(data, dict):
        return None
    existing_in = data.get('existing')
    new_in = data.get('new_bugs')
    if not isinstance(existing_in, list) and not isinstance(new_in, list):
        return None
    existing = []
    for item in existing_in if isinstance(existing_in, list) else []:
        if not isinstance(item, dict):
            continue
        bug_id = str(item.get('id', '') or '').strip()
        if not bug_id or not isinstance(item.get('still_present'), bool):
            continue
        existing.append({'id': bug_id, 'still_present': item['still_present']})
    new_bugs = []
    for item in new_in if isinstance(new_in, list) else []:
        if not isinstance(item, dict):
            continue
        title = str(item.get('title', '') or '').strip()
        if not title:
            continue
        severity = str(item.get('severity', '') or '').strip().lower()
        if severity not in EDITOR_DEBUG_SEVERITIES:
            severity = 'medium'
        try:
            line_start = max(0, int(item.get('line_start', 0) or 0))
        except (TypeError, ValueError):
            line_start = 0
        try:
            line_end = max(line_start, int(item.get('line_end', 0) or 0))
        except (TypeError, ValueError):
            line_end = line_start
        new_bugs.append({
            'title': title,
            'severity': severity,
            'category': (str(item.get('category', '') or '').strip() or 'logic')[:40],
            'line_start': line_start,
            'line_end': line_end,
            'explanation': str(item.get('explanation', '') or '').strip(),
        })
    return {'existing': existing, 'new_bugs': new_bugs}


def editor_debug_merge_scan(data, parsed, version, trigger, verifiable_ids=None):
    """Merge a parsed scan into the ledger dict IN PLACE (pure, no I/O).
    Open bugs the model says are gone → status 'fixed'. New bugs get b%03d ids.
    'feature'/'fixed' verdicts are never resurrected by a scan. When
    verifiable_ids is given (truncated-content scans), verdicts for ids outside
    it are DROPPED — a bug the model could not see must never be auto-resolved."""
    bugs = data.setdefault('bugs', [])
    now = _editor_now_iso()
    by_id = {str(b.get('id', '') or ''): b for b in bugs if isinstance(b, dict)}
    for verdict in (parsed.get('existing') or []):
        bug_id = str(verdict.get('id', '') or '')
        if verifiable_ids is not None and bug_id not in verifiable_ids:
            continue
        bug = by_id.get(bug_id)
        if not isinstance(bug, dict) or bug.get('status') != 'open':
            continue
        bug['last_seen_version'] = version
        if verdict.get('still_present') is False:
            bug['status'] = 'fixed'
            bug['resolved_at'] = now
            bug['resolved_version'] = version
    max_n = 0
    for b in bugs:
        m = re.match(r'b(\d+)$', str(b.get('id', '') or ''))
        if m:
            max_n = max(max_n, int(m.group(1)))
    open_titles = {str(b.get('title', '') or '').strip().casefold()
                   for b in bugs if isinstance(b, dict) and b.get('status') == 'open'}
    feature_titles = {str(b.get('title', '') or '').strip().casefold()
                      for b in bugs if isinstance(b, dict) and b.get('status') == 'feature'}
    for nb in (parsed.get('new_bugs') or []):
        title_key = str(nb.get('title', '') or '').strip().casefold()
        if not title_key or title_key in open_titles or title_key in feature_titles:
            continue  # dedupe against live entries + user 'not a bug' verdicts
        max_n += 1
        bug = dict(nb)
        bug['id'] = 'b%03d' % max_n
        bug['status'] = 'open'
        bug['created_at'] = now
        bug['created_version'] = version
        bug['last_seen_version'] = version
        bugs.append(bug)
        open_titles.add(title_key)
    data['last_scan'] = {'version': version, 'at': now, 'trigger': str(trigger or ''),
                         'ok': True, 'error': ''}
    return data


def editor_flow_from_entry_messages(store, entry, kind, lang):
    snippet, start, end = editor_code_context_for_entry(store, entry, radius=60)
    glossary = ''
    try:
        glossary = '\n'.join(editor_explain_glossary(store, snippet, cap=60))
    except Exception:
        glossary = ''
    try:
        is_article = store is not None and store.file_kind() == 'text-article'
    except Exception:
        is_article = False
    if kind == 'object':
        if is_article:
            system = (
                'You build a concept-relation graph for one article entry. Output ONLY JSON '
                '{"title": str, "nodes": [{"id": "n1", "desc": str}], '
                '"edges": [["n1","n2","label"], ...]}. Describe how the concept, person, '
                'or paragraph relates to claims, evidence, assumptions, causes, effects, '
                'contrasts, and implications. Use short node descriptions in %s.'
                % str(lang or 'English')
            )
        else:
            system = (
                'You analyze relations around one code object. Output ONLY JSON '
                '{"title": str, "nodes": [{"id": "n1", "desc": str}], '
                '"edges": [["n1","n2","label"], ...]}. Describe what this object relates to: '
                'parents, children, neighbors, assignments, effects, and coupled state. '
                'Use short natural-language node descriptions in %s.' % str(lang or 'English')
            )
    else:
        system = (
            'You analyze information flow through one code symbol. Output ONLY JSON '
            '{"title": str, "nodes": [{"id": "n1", "desc": str, '
            '"code_ref": {"symbol": str, "lines": [a,b]}}], "edges": [["n1","n2"], ...]}. '
            'Explain how an input/event moves through steps and reaches an output. '
            'Use 3-12 short natural-language steps in %s.' % str(lang or 'English')
        )
    parts = [
        'Entry: %s (%s)' % (str(entry.get('code_name', '') or ''), str(entry.get('category', '') or 'Other')),
        'Known name: %s' % str(entry.get('natural_name', '') or ''),
        'Description: %s' % str(entry.get('description', '') or ''),
        'Lines %d-%d:\n```\n%s\n```' % (start, end, snippet),
    ]
    if glossary:
        parts.append('Glossary:\n' + glossary)
    return [{'role': 'system', 'content': system}, {'role': 'user', 'content': '\n\n'.join(parts)}]


def editor_refine_messages(store, parent_flow, node, lang):
    node = node if isinstance(node, dict) else {}
    cref = node.get('code_ref') if isinstance(node.get('code_ref'), dict) else {}
    lines = cref.get('lines') if isinstance(cref.get('lines'), list) else []
    text = store.read_disk() if store is not None else ''
    all_lines = text.splitlines()
    try:
        a = max(1, int(lines[0]))
        b = max(a, int(lines[1]))
    except Exception:
        a, b = 1, min(len(all_lines), 80)
    snippet = '\n'.join(all_lines[a - 1:b])
    system = (
        'Refine one step of a code flow. Output ONLY JSON '
        '{"title": str, "nodes": [{"id": "n1", "desc": str, '
        '"code_ref": {"symbol": str, "lines": [a,b]}}], "edges": [["n1","n2"], ...]}. '
        'Use short natural-language steps in %s.' % str(lang or 'English')
    )
    user = 'Parent flow: %s\nStep: %s\nLines %d-%d:\n```\n%s\n```' % (
        str((parent_flow or {}).get('title', '') or ''),
        str(node.get('desc', '') or ''),
        a, b, snippet,
    )
    return [{'role': 'system', 'content': system}, {'role': 'user', 'content': user}]


def editor_revise_messages(store, flow, current_code, lang):
    system = (
        'Revise an existing code-flow graph against the current code. Output ONLY JSON '
        '{"title": str, "nodes": [{"id": "n1", "desc": str, '
        '"code_ref": {"symbol": str, "lines": [a,b]}}], "edges": [["n1","n2"], ...]}. '
        'Keep node ids stable where steps are unchanged. Use short natural-language descriptions in %s.'
        % str(lang or 'English')
    )
    old = json.dumps({
        'title': str((flow or {}).get('title', '') or ''),
        'nodes': (flow or {}).get('nodes') or [],
        'edges': (flow or {}).get('edges') or [],
    }, ensure_ascii=False)
    user = 'Existing flow:\n%s\n\nCurrent code:\n```\n%s\n```' % (old, str(current_code or ''))
    return [{'role': 'system', 'content': system}, {'role': 'user', 'content': user}]


def editor_edit_flow_regions(current_text, proposed_text, ctx=25, max_chars=5000):
    """The BEFORE/AFTER code the edit-flow generator reasons about. Small files
    are sent whole (full context); large files are windowed to the changed region
    ± ctx lines so the model focuses on the change and the prompt stays bounded."""
    cur = str(current_text or '')
    prop = str(proposed_text or '')
    if len(cur) <= max_chars and len(prop) <= max_chars:
        return cur, prop
    old_lines = cur.split('\n')
    new_lines = prop.split('\n')
    sm = difflib.SequenceMatcher(None, old_lines, new_lines)
    olo = ohi = nlo = nhi = None
    for tag, i1, i2, j1, j2 in sm.get_opcodes():
        if tag == 'equal':
            continue
        olo = i1 if olo is None else min(olo, i1)
        ohi = i2 if ohi is None else max(ohi, i2)
        nlo = j1 if nlo is None else min(nlo, j1)
        nhi = j2 if nhi is None else max(nhi, j2)
    if olo is None:
        return cur[:max_chars], prop[:max_chars]
    before = '\n'.join(old_lines[max(0, olo - ctx):ohi + ctx])[:max_chars]
    after = '\n'.join(new_lines[max(0, nlo - ctx):nhi + ctx])[:max_chars]
    return before, after


def editor_edit_flow_messages(before_region, after_region, summary, lang):
    """One-shot prompt to author two FOCUSED control-flow diagrams for a code
    change: 'current' (before) and 'revised' (after, with per-node add/remove/
    change tags). Everything in a single user message — this user's relay drops
    system-role messages (see memory), and the editor worker does not merge."""
    lang = str(lang or 'English')
    fence = '````' if '```' in (str(before_region) + str(after_region)) else '```'
    body = (
        'You author focused control-flow diagrams for ONE code change. Output ONLY a JSON object, no prose.\n'
        'Zoom into the LOGIC AFFECTED BY THIS CHANGE — do NOT diagram the whole file. Keep each flow small '
        'and focused (usually 3-8 steps). Write step descriptions in ' + lang + '.\n'
        'Schema:\n'
        '{"current":{"nodes":[{"id":"c1","desc":"..."}],"edges":[["c1","c2"]]},'
        '"revised":{"nodes":[{"id":"r1","desc":"...","change":"unchanged|added|removed|changed"}],'
        '"edges":[["r1","r2"]]}}\n'
        '"current" = how this part of the code works BEFORE the edit.\n'
        '"revised" = how it works AFTER: tag EVERY revised node with "change" — "added" for a NEW step the '
        'edit introduces, "removed" for a step the edit deletes (KEEP it in the node list so it can be shown '
        'struck), "changed" for a step whose behavior/details changed, "unchanged" otherwise. Node ids are '
        'your own short strings.\n\n'
        'Change summary: ' + str(summary or '') + '\n\n'
        'BEFORE:\n' + fence + '\n' + str(before_region or '') + '\n' + fence + '\n\n'
        'AFTER:\n' + fence + '\n' + str(after_region or '') + '\n' + fence
    )
    return [{'role': 'user', 'content': body}]


def _editor_parse_one_flow(d):
    if not isinstance(d, dict):
        return None
    nodes = []
    for n in d.get('nodes') or []:
        if not isinstance(n, dict):
            continue
        nid = str(n.get('id', '') or '').strip()
        desc = str(n.get('desc', '') or '').strip()
        if not nid or not desc:
            continue
        node = {'id': nid, 'desc': desc}
        ch = str(n.get('change', '') or '').strip().lower()
        if ch in ('added', 'removed', 'changed', 'unchanged'):
            node['change'] = ch
        nodes.append(node)
        if len(nodes) >= 24:
            break
    if not nodes:
        return None
    ids = {n['id'] for n in nodes}
    edges = []
    for e in d.get('edges') or []:
        if isinstance(e, (list, tuple)) and len(e) >= 2 and str(e[0]) in ids and str(e[1]) in ids:
            edges.append([str(e[0]), str(e[1])])
    return {'nodes': nodes, 'edges': edges}


def editor_parse_edit_flows(text):
    """Parse the two-flow response -> (current_flow, revised_flow, mark) or None.
    mark maps revised node id -> added/removed/changed for the diff coloring."""
    raw = _editor_extract_json_object(text)
    if not raw:
        return None
    try:
        data = json.loads(raw)
    except Exception:
        return None
    if not isinstance(data, dict):
        return None
    current = _editor_parse_one_flow(data.get('current'))
    revised = _editor_parse_one_flow(data.get('revised'))
    if current is None and revised is None:
        return None
    mark = {}
    if revised:
        for n in revised['nodes']:
            ch = n.get('change')
            if ch in ('added', 'removed', 'changed'):
                mark[n['id']] = ch
    return current, revised, mark


def editor_revision_marked_flow(old_flow, new_flow):
    old_nodes = {str(n.get('id', '') or ''): n for n in (old_flow or {}).get('nodes', []) if isinstance(n, dict)}
    new_nodes = {str(n.get('id', '') or ''): n for n in (new_flow or {}).get('nodes', []) if isinstance(n, dict)}
    mark = {}
    merged_nodes = copy.deepcopy((new_flow or {}).get('nodes') or [])
    present = {str(n.get('id', '') or '') for n in merged_nodes if isinstance(n, dict)}
    for nid, node in old_nodes.items():
        if nid not in new_nodes:
            removed = copy.deepcopy(node)
            removed['desc'] = _tr('[Removed]') + ' ' + str(removed.get('desc', '') or '')
            merged_nodes.append(removed)
            mark[nid] = 'removed'
        elif str(node.get('desc', '') or '') != str(new_nodes[nid].get('desc', '') or ''):
            mark[nid] = 'changed'
    for nid in new_nodes:
        if nid not in old_nodes:
            mark[nid] = 'added'
    merged_edges = copy.deepcopy((new_flow or {}).get('edges') or [])
    for edge in (old_flow or {}).get('edges') or []:
        if not isinstance(edge, list) or len(edge) < 2:
            continue
        if str(edge[0]) in old_nodes and str(edge[1]) in old_nodes:
            if edge not in merged_edges:
                merged_edges.append(copy.deepcopy(edge))
    result = copy.deepcopy(new_flow or {})
    result['nodes'] = merged_nodes
    result['edges'] = merged_edges
    return result, mark


class EditorLexiconPage(QWidget):
    def __init__(self, window, parent=None):
        super().__init__(parent)
        self._win = window
        self._path = None
        self._lexicon = None
        self._dark = False
        self._parse_serial = 0
        self._parse_worker = None
        self._parsed_once = set()
        self._parse_timer = QTimer(self)
        self._parse_timer.setSingleShot(True)
        self._parse_timer.setInterval(1000)
        self._parse_timer.timeout.connect(lambda: self.request_parse(self._win.session.current_path))
        root = QVBoxLayout(self)
        root.setContentsMargins(8, 6, 8, 6)
        root.setSpacing(8)
        top = QHBoxLayout()
        top.setContentsMargins(0, 0, 0, 0)
        top.setSpacing(8)
        self.category_btn = DropdownButton(self, compact_light=True)
        self.category_btn.setFixedWidth(150)
        self.category_btn.currentIndexChanged.connect(self._on_filter_changed)
        self.search = add_search_glyph(QLineEdit(self))
        self.search.setPlaceholderText(_tr('Search'))
        self.search.setFixedHeight(self.category_btn.height())   # as tall as the drop-down beside it (it was 19 next to 22)
        self.search.setClearButtonEnabled(True)
        self.search.textChanged.connect(self._on_filter_changed)
        self.status_lbl = QLabel('', self)
        top.addWidget(self.category_btn)
        top.addWidget(self.search, 1)
        top.addWidget(self.status_lbl)
        root.addLayout(top)
        self.model = EditorLexiconModel(self)
        self.proxy = EditorLexiconProxy(self)
        self.proxy.setSourceModel(self.model)
        self.table = QTableView(self)
        self.table.setModel(self.proxy)
        self.table.setSelectionBehavior(QAbstractItemView.SelectionBehavior.SelectRows)
        self.table.setSelectionMode(QAbstractItemView.SelectionMode.SingleSelection)
        self.table.setAlternatingRowColors(False)
        self.table.setWordWrap(False)
        self.table.setSortingEnabled(True)
        self.table.setContextMenuPolicy(Qt.ContextMenuPolicy.CustomContextMenu)
        self.table.customContextMenuRequested.connect(self._show_row_menu)
        self.table.clicked.connect(self._on_row_clicked)
        self.table.setItemDelegateForColumn(1, EditorCategoryDelegate(self))
        # settings-table card look: hide the row-number gutter and the grid so
        # the reused stylesheet's rounded border + row separators read cleanly
        self.table.verticalHeader().setVisible(False)
        self.table.setShowGrid(False)
        try:
            self.table.horizontalHeader().setStretchLastSection(True)
            self.table.horizontalHeader().setSectionResizeMode(0, QHeaderView.ResizeMode.ResizeToContents)
            self.table.horizontalHeader().setSectionResizeMode(1, QHeaderView.ResizeMode.ResizeToContents)
            self.table.horizontalHeader().setSectionResizeMode(2, QHeaderView.ResizeMode.Stretch)
            self.table.horizontalHeader().setSectionResizeMode(3, QHeaderView.ResizeMode.Stretch)
            self.table.horizontalHeader().setSectionResizeMode(4, QHeaderView.ResizeMode.ResizeToContents)
        except Exception:
            pass
        root.addWidget(self.table, 1)
        try:
            self.set_theme(is_dark_theme(app))
        except Exception:
            self.set_theme(False)

    def set_theme(self, dark_mode):
        self._dark = bool(dark_mode)
        fg = '#F2F2F7' if self._dark else '#20242B'
        dim = '#8E8E93' if self._dark else '#A0A0A6'
        bg = '#2D2D2D' if self._dark else '#FFFFFF'
        field_bg = '#404145' if self._dark else '#E7E7E7'
        self.search.setStyleSheet(_settings_lineedit_stylesheet(bool(self._dark)))   # the plain input style
        self.status_lbl.setStyleSheet('color: %s; font-size: 11px; background: transparent;' % dim)
        # Reuse the app's settings-table card look (QTableView-targeted).
        self.table.setStyleSheet(_settings_tableview_stylesheet(self._dark))
        try:
            self.category_btn._update_style()
        except Exception:
            pass
        self.model.dataChanged.emit(
            self.model.index(0, 0),
            self.model.index(max(0, self.model.rowCount() - 1), max(0, self.model.columnCount() - 1)),
        )

    def categories(self):
        lex = self._lexicon if isinstance(self._lexicon, dict) else {}
        cats = lex.get('categories')
        if isinstance(cats, list) and cats:
            return [str(c) for c in cats]
        store = self._store()
        if store is not None and store.file_kind() == 'text-article':
            return ['Paragraph', 'Person', 'Concept']
        return ['Variable', 'Function', 'Class', 'Signal', 'Other']

    def _store(self, path=None):
        # Follow the session's current file — NOT the page's sticky self._path,
        # which latched onto the first-shown file and made switching files (or
        # closing them all) never update the table.
        p = path or self._win.session.current_path
        return self._win.session.store(p) if p else None

    def refresh_table(self):
        store = self._store()
        if store is None:
            self._path = None
            self._lexicon = None
            self.model.set_entries([])
            self._fill_categories([])
            self.status_lbl.setText(_tr('No file'))
            return
        self._path = store.path
        self._lexicon = store.load_lexicon()
        entries = (self._lexicon or {}).get('entries') or []
        self.model.set_entries(entries)
        self._fill_categories(self.categories())
        self._on_filter_changed()
        self._update_status()

    def _fill_categories(self, categories):
        current = self.category_btn.currentText() or 'All'
        self.category_btn.blockSignals(True)
        try:
            self.category_btn.clear()
            self.category_btn.addItem('All', 'All')
            for cat in categories:
                self.category_btn.addItem(str(cat), str(cat))
            idx = self.category_btn.findData(current)
            self.category_btn.setCurrentIndex(idx if idx >= 0 else 0)
        finally:
            self.category_btn.blockSignals(False)

    def _on_filter_changed(self, *args):
        self.proxy.set_query(self.search.text())
        self.proxy.set_category(self.category_btn.currentData() or 'All')
        self._update_status()

    def _update_status(self, extra=''):
        if extra:
            self.status_lbl.setText(extra)
            return
        total = self.model.rowCount()
        shown = self.proxy.rowCount()
        self.status_lbl.setText(_tr('%d/%d entries') % (shown, total))

    def persist_lexicon(self):
        store = self._store()
        if store is None:
            return
        if not isinstance(self._lexicon, dict):
            self._lexicon = store.load_lexicon()
        self._lexicon['entries'] = self.model.entries
        store.save_lexicon(self._lexicon)
        self.refresh_table()

    def request_parse(self, path):
        path = str(path or '')
        if not path:
            self.refresh_table()
            return
        store = self._win.session.store(path)
        if store is None:
            return
        if path == self._win.session.current_path:
            text = editor_live_text_for(self._win, path)
        else:
            text = store.read_disk()
        kind = store.file_kind()
        self._parse_serial += 1
        serial = self._parse_serial
        worker = _EditorParseWorker(text, kind, serial, self)
        self._parse_worker = worker
        worker.parsed.connect(lambda parsed, s, err, p=path: self._on_parse_done(p, parsed, s, err),
                              Qt.ConnectionType.QueuedConnection)
        worker.finished.connect(worker.deleteLater)
        worker.start()
        self._update_status(_tr('Parsing…'))

    def _on_parse_done(self, path, parsed, serial, err):
        if serial != self._parse_serial:
            return
        store = self._win.session.store(path)
        if parsed is None:
            self.refresh_table()
            self._update_status(str(err or _tr('Parse error')))
            return
        editor_merge_lexicon(store, parsed)
        self._parsed_once.add(path)
        self.refresh_table()

    def schedule_parse(self):
        self._parse_timer.start()

    def focus_entry(self, entry_id):
        self.search.clear()
        idx = self.category_btn.findData('All')
        if idx >= 0:
            self.category_btn.setCurrentIndex(idx)
        for row, e in enumerate(self.model.entries):
            if str(e.get('id', '') or '') == str(entry_id or ''):
                src = self.model.index(row, 0)
                proxy_idx = self.proxy.mapFromSource(src)
                if proxy_idx.isValid():
                    self.table.selectRow(proxy_idx.row())
                    self.table.scrollTo(proxy_idx, QAbstractItemView.ScrollHint.PositionAtCenter)
                break

    def _entry_from_proxy_index(self, index):
        if not index.isValid():
            return None
        source = self.proxy.mapToSource(index)
        if not source.isValid():
            return None
        return self.model.data(self.model.index(source.row(), 0), Qt.ItemDataRole.UserRole)

    def _current_entry(self, pos=None):
        idx = self.table.indexAt(pos) if pos is not None else self.table.currentIndex()
        return self._entry_from_proxy_index(idx)

    def _show_row_menu(self, pos):
        entry = self._current_entry(pos)
        if not isinstance(entry, dict):
            return
        menu = style_broccoli_context_menu(QMenu(self.table))
        obj_act = menu.addAction(_tr('Object Card'))
        fn_act = menu.addAction(_tr('Function Card'))
        menu.addSeparator()
        append_act = menu.addAction(_tr('Append to current chat'))
        web_act = menu.addAction(_tr('Ask Web'))
        local_act = menu.addAction(_tr('Ask Localhost'))
        menu.addSeparator()
        ai_act = menu.addAction(_tr('AI Name This'))
        if str(entry.get('status', '') or '') == 'confirmed':
            ai_act.setEnabled(False)
        menu.addSeparator()
        copy_act = menu.addAction(_tr('Copy Code Name'))
        act = menu.exec(self.table.viewport().mapToGlobal(pos))
        if act is None:
            return
        if act is obj_act:
            self._win._on_card_request('object', {'entry_id': entry.get('id'), 'path': self._path})
            return
        if act is fn_act:
            self._win._on_card_request('function', {'entry_id': entry.get('id'), 'path': self._path})
            return
        if act is copy_act:
            QApplication.clipboard().setText(str(entry.get('code_name', '') or ''))
            return
        if act is ai_act:
            self._ai_name_entry(entry)
            return
        key = None
        if act is append_act:
            key = 'append_current'
        elif act is web_act:
            key = 'ask_web'
        elif act is local_act:
            key = 'ask_localhost'
        if key:
            try:
                self._win._main._execute_selection_ask_action(key, editor_entry_text(entry))
            except Exception:
                pass

    def _on_row_clicked(self, index):
        # Left click on a row jumps the editor to its anchor. This is also useful
        # before M8 adds cross-card links.
        entry = self._entry_from_proxy_index(index)
        if isinstance(entry, dict):
            self._jump_to_entry(entry)

    def _jump_to_entry(self, entry):
        try:
            line = int(((entry.get('anchors') or [{}])[0]).get('line', 1))
        except Exception:
            return
        self._win.jump_editor_to_line(line)

    def _ai_name_entry(self, entry):
        store = self._store()
        if store is None or not isinstance(entry, dict):
            return
        entry_id = str(entry.get('id', '') or '')
        for candidate in self.model.entries:
            if isinstance(candidate, dict) and str(candidate.get('id', '') or '') == entry_id:
                entry = candidate
                break
        if str(entry.get('status', '') or '') == 'confirmed':
            return
        previous = dict(entry)

        def restore_previous(e=entry, prev=previous):
            e.clear()
            e.update(copy.deepcopy(prev))
            self.persist_lexicon()

        entry['status'] = 'naming'
        self.model.dataChanged.emit(self.model.index(0, 0), self.model.index(max(0, self.model.rowCount() - 1), 4))
        try:
            lang = store.lexicon_language()
        except Exception:
            lang = 'English'
        messages = editor_name_messages(store, entry, lang)
        acc = []

        def on_delta(piece):
            acc.append(str(piece or ''))

        def on_finished(text, e=entry):
            data = editor_parse_name_json(text or ''.join(acc))
            if data is None:
                restore_previous(e)
            else:
                e['natural_name'] = data.get('natural_name', '')
                e['description'] = data.get('description', '')
                e['status'] = 'auto'
                e['source'] = 'ai'
                e['updated_at'] = _editor_now_iso()
                self.persist_lexicon()

        def on_failed(message, e=entry):
            restore_previous(e)

        editor_llm_request(messages, on_delta, on_finished, on_failed)


class _EditorCardDots(QWidget):
    """Dot page indicator — filled current / hollow rest; 'n/N' text when > 12 cards."""
    MAX_DOTS = 12

    def __init__(self, parent=None):
        super().__init__(parent)
        self._count = 0
        self._current = -1
        self._dark = False
        self.setFixedHeight(18)
        self.setFixedWidth(24)

    def set_state(self, count, current):
        self._count = max(0, int(count))
        self._current = int(current)
        if 0 < self._count <= self.MAX_DOTS:
            w = self._count * 12
        else:
            w = 44
        self.setFixedWidth(max(24, w))
        self.update()

    def set_theme(self, dark_mode):
        self._dark = bool(dark_mode)
        self.update()

    def paintEvent(self, event):
        if self._count <= 0:
            return
        painter = QPainter(self)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)
        color = QColor('#F2F2F7' if self._dark else '#20242B')
        dim = QColor(color)
        dim.setAlpha(90)
        if self._count > self.MAX_DOTS:
            painter.setPen(QPen(color))
            f = painter.font()
            f.setPixelSize(11)
            painter.setFont(f)
            painter.drawText(self.rect(), Qt.AlignmentFlag.AlignCenter,
                             '%d/%d' % (self._current + 1, self._count))
            painter.end()
            return
        cy = self.height() / 2.0
        for i in range(self._count):
            cx = 6 + i * 12
            if i == self._current:
                painter.setPen(Qt.PenStyle.NoPen)
                painter.setBrush(QBrush(color))
            else:
                painter.setPen(QPen(dim, 1.2))
                painter.setBrush(Qt.BrushStyle.NoBrush)
            painter.drawEllipse(QPointF(cx, cy), 3.0, 3.0)
        painter.end()


class EditorCardBody(SmoothPanelWidget):
    """A card's panel: frosted system glass when its window can host it (installed with the
    other glass classes at the end of the file) — its solid fill and shadow give way and the
    title, text and diagram are rendered into the glass. Cards slide inside the dock, which
    clips them, so only the part the dock shows is glass."""

    def _glass_occluding_rect(self):
        visible = glass_visible_part(self)
        return QRect(self.mapTo(self.window(), visible.topLeft()), visible.size()) if not visible.isEmpty() else QRect()


class EditorCardDockBar(QWidget):
    """The dock's bottom row (‹ dots › title): a glass capsule like the editor's bars."""

    def _apply_theme(self):
        dock = self.parentWidget()
        if isinstance(dock, EditorCardDock):
            dock._style_bottom()   # under the glass its own capsule fill turns see-through

    def _glass_occluding_rect(self):
        visible = glass_visible_part(self)
        return QRect(self.mapTo(self.window(), visible.topLeft()), visible.size()) if not visible.isEmpty() else QRect()


class EditorCard(QWidget):
    """One floating card in EditorCardDock. M4 fills 'explain'; 'flow'/'object'/'function' land M5/M6."""
    close_requested = pyqtSignal()
    regenerate_requested = pyqtSignal()
    # room below the panel for its drop shadow (see-through) — = the dock's CARD_GAP, so the card
    # ends right where the pager starts: overlapping it, every card move repainted the pager and
    # its glass re-rendered each frame
    SHADOW_BOTTOM = 10

    def __init__(self, kind, title, payload, parent=None, display_title=None):
        super().__init__(parent)
        self.kind = str(kind or '')
        self.title = str(title or '')  # English: also sent to the model (_editor_visible_card_text)
        self.display_title = str(display_title or self.title)
        self.payload = dict(payload) if isinstance(payload, dict) else {}
        self.worker = None          # in-flight _EditorLLMWorker; the dock stops it on close
        self.result_text = ''
        self.from_cache = False
        self._alive = True          # cleared right before deletion — guards late signals
        self._state = 'loading'
        self._dark = False
        self.svg_text = ''
        self.flow_id = ''
        self._diagram_pixmap = QPixmap()

        self._body = EditorCardBody(self)
        shadow = QGraphicsDropShadowEffect(self._body)
        shadow.setBlurRadius(34)
        shadow.setXOffset(0)
        shadow.setYOffset(10)
        shadow.setColor(QColor(0, 0, 0, 45))
        self._body.setGraphicsEffect(shadow)
        root = QVBoxLayout(self)
        root.setContentsMargins(0, 0, 0, self.SHADOW_BOTTOM)   # room below the panel for the drop shadow
        root.addWidget(self._body)

        lay = QVBoxLayout(self._body)
        lay.setContentsMargins(16, 12, 16, 14)
        lay.setSpacing(8)
        head = QHBoxLayout()
        head.setContentsMargins(0, 0, 0, 0)
        head.setSpacing(8)
        self.title_lbl = QLabel(self._body)
        self.close_btn = glass_disc_in_clip(QPushButton('✕', self._body), alive_for=lambda _b, me=self: me._alive)
        self.close_btn.setFixedSize(22, 22)
        self.close_btn.setCursor(Qt.CursorShape.PointingHandCursor)
        self.close_btn.setFocusPolicy(Qt.FocusPolicy.NoFocus)
        self.close_btn.clicked.connect(self.close_requested)
        head.addWidget(self.title_lbl, 1)
        head.addWidget(self.close_btn, 0, Qt.AlignmentFlag.AlignTop)
        lay.addLayout(head)

        self.status_lbl = QLabel(_tr('Thinking…'), self._body)   # loading / error / placeholder surface
        self.status_lbl.setWordWrap(True)
        self.status_lbl.setAlignment(Qt.AlignmentFlag.AlignHCenter | Qt.AlignmentFlag.AlignVCenter)
        lay.addWidget(self.status_lbl, 1)

        self.browser = QTextBrowser(self._body)
        self.browser.setFrameShape(QFrame.Shape.NoFrame)
        self.browser.setOpenExternalLinks(False)
        try:
            self.browser.setOpenLinks(False)
        except Exception:
            pass
        self.browser.anchorClicked.connect(self._on_anchor_clicked)
        self.browser.setContextMenuPolicy(Qt.ContextMenuPolicy.CustomContextMenu)
        self.browser.customContextMenuRequested.connect(self._show_content_menu)
        self.browser.hide()
        lay.addWidget(self.browser, 1)

        self.diagram_view = None
        self.diagram_toolbar = None
        self.node_list = None
        self.old_btn = None
        self.new_btn = None
        self.adopt_btn = None
        self.discard_btn = None
        self.revise_btn = None
        if self.kind in ('flow', 'object', 'function'):
            self.diagram_toolbar = QWidget(self._body)
            tb = QHBoxLayout(self.diagram_toolbar)
            tb.setContentsMargins(0, 0, 0, 0)
            tb.setSpacing(6)
            self.revise_btn = QPushButton(_tr('Revise'), self.diagram_toolbar)
            self.old_btn = QPushButton(_tr('Old'), self.diagram_toolbar)
            self.new_btn = QPushButton(_tr('New'), self.diagram_toolbar)
            self.adopt_btn = QPushButton(_tr('Adopt & Save'), self.diagram_toolbar)
            self.discard_btn = QPushButton(_tr('Discard'), self.diagram_toolbar)
            for btn in (self.revise_btn, self.old_btn, self.new_btn, self.adopt_btn, self.discard_btn):
                btn.setCursor(Qt.CursorShape.PointingHandCursor)
                btn.setFocusPolicy(Qt.FocusPolicy.NoFocus)
                btn.setFixedHeight(22)
            tb.addWidget(self.revise_btn)
            tb.addStretch(1)
            tb.addWidget(self.old_btn)
            tb.addWidget(self.new_btn)
            tb.addWidget(self.adopt_btn)
            tb.addWidget(self.discard_btn)
            self.revise_btn.clicked.connect(self._request_revise)
            self.old_btn.clicked.connect(lambda: self._request_revision_view('old'))
            self.new_btn.clicked.connect(lambda: self._request_revision_view('new'))
            self.adopt_btn.clicked.connect(self._request_adopt_revision)
            self.discard_btn.clicked.connect(self._request_discard_revision)
            self.diagram_toolbar.hide()
            lay.addWidget(self.diagram_toolbar, 0)
            self.diagram_view = EditorDiagramView(self._body)
            self.diagram_view.setContextMenuPolicy(Qt.ContextMenuPolicy.CustomContextMenu)
            self.diagram_view.customContextMenuRequested.connect(self._show_diagram_menu)
            self.diagram_view.hide()
            lay.addWidget(self.diagram_view, 1)
            self.node_list = QListWidget(self._body)
            self.node_list.setFrameShape(QFrame.Shape.NoFrame)
            self.node_list.setContextMenuPolicy(Qt.ContextMenuPolicy.CustomContextMenu)
            self.node_list.customContextMenuRequested.connect(self._show_node_menu)
            self.node_list.itemClicked.connect(self._on_node_clicked)
            self.node_list.setMaximumHeight(132)
            self.node_list.hide()
            lay.addWidget(self.node_list, 0)

        if self.kind != 'explain':
            if self.kind in ('flow', 'object', 'function'):
                self.status_lbl.setText(_tr('Generating diagram…'))
            else:
                self._state = 'placeholder'
                self.status_lbl.setText(_tr('Available after the diagram milestone'))
        try:
            self.set_theme(is_dark_theme(app))
        except Exception:
            self.set_theme(False)

    # ── theme / chrome ───────────────────────────────────────
    def set_theme(self, dark_mode):
        dark = bool(dark_mode)
        self._dark = dark
        self._body.set_smooth_panel_background(
            QColor('#2D2D2D' if dark else '#FFFFFF'), QColor(0, 0, 0, 24), EDITOR_CARD_SMOOTH_RADIUS)
        fg = '#F2F2F7' if dark else '#20242B'
        dim = '#8E8E93' if dark else '#A0A0A6'
        hover = 'rgba(255,255,255,34)' if dark else 'rgba(0,0,0,26)'
        self.title_lbl.setStyleSheet(
            'color: %s; font-size: 13px; font-weight: 600; background: transparent;'
            ' font-family: "Helvetica Neue", Helvetica, Arial, sans-serif;' % fg)
        self.close_btn.setStyleSheet(
            'QPushButton { border: none; border-radius: 11px; background: transparent;'
            ' color: %s; font-size: 12px; }'
            ' QPushButton:hover { background: %s; color: %s; }' % (dim, hover, fg))
        selection = '#264F78' if dark else '#B5D5FF'
        self.browser.setStyleSheet(
            'QTextBrowser { border: none; background: transparent; color: %s;'
            ' selection-background-color: %s;'
            ' font-family: "Helvetica Neue", Helvetica, Arial, sans-serif;'
            ' font-size: 13px; }' % (fg, selection))
        if self.diagram_view is not None:
            self.diagram_view.set_theme(dark)
        if self.diagram_toolbar is not None:
            btn_bg = '#404145' if dark else '#E7E7E7'
            btn_hover = '#4A4B4F' if dark else '#EEEEEE'
            self.diagram_toolbar.setStyleSheet(
                'QWidget { background: transparent; }'
                'QPushButton { border: none; border-radius: 6px; padding: 2px 8px;'
                ' background: %s; color: %s; font-size: 11px; }'
                'QPushButton:hover { background: %s; }'
                'QPushButton:disabled { color: %s; }'
                % (btn_bg, fg, btn_hover, dim))
        if self.node_list is not None:
            self.node_list.setStyleSheet(
                'QListWidget { border: none; border-radius: 8px; background: %s; color: %s;'
                ' font-size: 11px; padding: 4px; }'
                'QListWidget::item { padding: 4px 6px; border-radius: 5px; }'
                'QListWidget::item:selected { background: %s; }'
                % ('#242426' if dark else '#F7F8FA', fg, '#264F78' if dark else '#D8EAFE'))
        self._apply_status_style()
        self._refresh_title()

    def _apply_status_style(self):
        if self._state == 'error':
            color = '#FF6B63' if self._dark else '#C0392B'   # dim red-ish
        else:
            color = '#8E8E93' if self._dark else '#A0A0A6'
        self.status_lbl.setStyleSheet(
            'color: %s; font-size: 12px; background: transparent;' % color)

    def _refresh_title(self):
        try:
            fm = self.title_lbl.fontMetrics()
            avail = max(40, self.title_lbl.width() - 4)
            self.title_lbl.setText(fm.elidedText(self.display_title, Qt.TextElideMode.ElideRight, avail))
        except Exception:
            self.title_lbl.setText(self.display_title)

    def resizeEvent(self, event):
        super().resizeEvent(event)
        self._refresh_title()

    # ── streaming states ─────────────────────────────────────
    def _at_bottom(self):
        try:
            bar = self.browser.verticalScrollBar()
            return bar.value() >= bar.maximum() - 4
        except Exception:
            return True

    def append_delta(self, text):
        if not self._alive or self._state not in ('loading', 'streaming'):
            return
        if self._state == 'loading':
            self._state = 'streaming'
            self.status_lbl.hide()
            if self.diagram_view is not None:
                self.diagram_view.hide()
            if self.diagram_toolbar is not None:
                self.diagram_toolbar.hide()
            if self.node_list is not None:
                self.node_list.hide()
            self.browser.show()
        follow = self._at_bottom()   # autoscroll only while the user hasn't scrolled up
        cur = QTextCursor(self.browser.document())
        cur.movePosition(QTextCursor.MoveOperation.End)
        cur.insertText(str(text or ''))
        if follow:
            bar = self.browser.verticalScrollBar()
            bar.setValue(bar.maximum())

    def finish(self, full_text):
        if not self._alive:
            return
        self.result_text = str(full_text or '')
        self._state = 'done'
        self.status_lbl.hide()
        if self.diagram_view is not None:
            self.diagram_view.hide()
        if self.diagram_toolbar is not None:
            self.diagram_toolbar.hide()
        if self.node_list is not None:
            self.node_list.hide()
        self.browser.show()
        rendered = False
        try:
            # the chat area's own markdown→HTML converter
            html_text = render_markdown_fragment(self.result_text)
            if html_text:
                if self.kind == 'explain':
                    try:
                        html_text = editor_linkify_lexicon_terms(html_text, self.window()._store_for_card(self))
                    except Exception:
                        pass
                self.browser.setHtml(html_text)
                rendered = True
        except Exception:
            rendered = False
        if not rendered:
            self.browser.setPlainText(self.result_text)

    def _on_anchor_clicked(self, url):
        try:
            if str(url.scheme()) == 'broccoli-lex':
                entry_id = str(url.host() or url.path()).strip('/ ')
                if entry_id:
                    self.window().focus_lexicon_entry(entry_id)
                return
            from PyQt6.QtGui import QDesktopServices
            QDesktopServices.openUrl(url)
        except Exception:
            pass

    def set_error(self, message):
        if not self._alive:
            return
        self._state = 'error'
        if self.diagram_view is not None:
            self.diagram_view.hide()
        if self.diagram_toolbar is not None:
            self.diagram_toolbar.hide()
        if self.node_list is not None:
            self.node_list.hide()
        self.browser.hide()
        self.status_lbl.setText(str(message or _tr('Request failed.')))
        self._apply_status_style()
        self.status_lbl.show()

    def mark_cached(self, flag=True):
        self.from_cache = bool(flag)   # 'Regenerate' shows in the content menu

    def reset_to_loading(self):
        # Regenerate: the same card goes back to a fresh stream
        self.result_text = ''
        self.from_cache = False
        self._state = 'loading'
        self.svg_text = ''
        self.flow_id = ''
        self._diagram_pixmap = QPixmap()
        if self.diagram_view is not None:
            self.diagram_view.hide()
            self.diagram_view.set_pixmap(QPixmap())
        if self.diagram_toolbar is not None:
            self.diagram_toolbar.hide()
        if self.node_list is not None:
            self.node_list.clear()
            self.node_list.hide()
        self.browser.hide()
        self.browser.clear()
        self.status_lbl.setText(_tr('Generating diagram…') if self.kind in ('flow', 'object', 'function') else _tr('Thinking…'))
        self._apply_status_style()
        self.status_lbl.show()

    def show_debug_text(self, text):
        self.browser.setPlainText(str(text or ''))
        self.browser.show()

    def show_diagram(self, pixmap, svg_text, flow_id):
        if not self._alive:
            return
        self.svg_text = str(svg_text or '')
        self.flow_id = str(flow_id or '')
        self._diagram_pixmap = pixmap if isinstance(pixmap, QPixmap) else QPixmap()
        if self.diagram_view is not None:
            self.diagram_view.set_pixmap(self._diagram_pixmap)
            self.diagram_view.show()
        self._populate_node_list()
        if isinstance(self.payload, dict) and isinstance(self.payload.get('_revision'), dict):
            self._set_revision_mode(True, show_new=(self.payload.get('_revision_view') != 'old'))
        else:
            self._set_revision_mode(False)
        self.browser.hide()
        self.status_lbl.hide()
        self._state = 'done'
        self.result_text = self._diagram_plain_text()

    def _populate_node_list(self):
        if self.node_list is None:
            return
        self.node_list.clear()
        flow = self.payload.get('flow') if isinstance(self.payload, dict) else None
        flow = flow if isinstance(flow, dict) else {}
        nodes = flow.get('nodes') if isinstance(flow.get('nodes'), list) else []
        for node in nodes:
            if not isinstance(node, dict):
                continue
            nid = str(node.get('id', '') or '')
            desc = str(node.get('desc', '') or '').strip()
            if not nid and not desc:
                continue
            label = '%s · %s' % (nid, desc)
            if node.get('refine_flow'):
                label += '  ' + _tr('↳ detail')
            item = QListWidgetItem(label)
            item.setData(Qt.ItemDataRole.UserRole, nid)
            self.node_list.addItem(item)
        self.node_list.setVisible(bool(nodes))

    def _set_revision_mode(self, active, show_new=True):
        if self.diagram_toolbar is None:
            return
        can_revise = self.kind in ('flow', 'function')
        self.revise_btn.setVisible(can_revise and not active)
        for btn in (self.old_btn, self.new_btn, self.adopt_btn, self.discard_btn):
            btn.setVisible(bool(active))
        self.old_btn.setEnabled(bool(active and show_new))
        self.new_btn.setEnabled(bool(active and not show_new))
        self.diagram_toolbar.setVisible(can_revise or bool(active))

    def _diagram_plain_text(self):
        flow = self.payload.get('flow') if isinstance(self.payload, dict) else None
        flow = flow if isinstance(flow, dict) else {}
        title = str(flow.get('title', '') or self.title or 'Flow')
        lines = [title]
        nodes = flow.get('nodes') if isinstance(flow.get('nodes'), list) else []
        for idx, node in enumerate(nodes, 1):
            if isinstance(node, dict):
                desc = str(node.get('desc', '') or '').strip()
                if desc:
                    lines.append('%d. %s' % (idx, desc))
        return '\n'.join(lines).strip()

    def _node_by_id(self, node_id):
        flow = self.payload.get('flow') if isinstance(self.payload, dict) else None
        flow = flow if isinstance(flow, dict) else {}
        for node in flow.get('nodes') if isinstance(flow.get('nodes'), list) else []:
            if isinstance(node, dict) and str(node.get('id', '') or '') == str(node_id or ''):
                return node
        return None

    def _show_node_menu(self, pos):
        if self.node_list is None:
            return
        item = self.node_list.itemAt(pos)
        if item is None:
            return
        node_id = item.data(Qt.ItemDataRole.UserRole)
        node = self._node_by_id(node_id)
        if not isinstance(node, dict):
            return
        menu = style_broccoli_context_menu(QMenu(self.node_list))
        detail_id = str(node.get('refine_flow', '') or '')
        if detail_id:
            open_act = menu.addAction(_tr('Open Detail'))
            refine_act = None
        else:
            open_act = None
            refine_act = menu.addAction(_tr('Refine This Step'))
        win = self.window()
        logic_act = None
        mapped_entry = None
        try:
            mapped_entry = editor_entry_for_flow_node(win._store_for_card(self), node) if win is not None else None
        except Exception:
            mapped_entry = None
        if mapped_entry is not None:
            logic_act = menu.addAction(_tr('Show in Logic Map'))
        jump_act = menu.addAction(_tr('Jump to Code'))
        act = menu.exec(self.node_list.viewport().mapToGlobal(pos))
        if act is None or win is None:
            return
        if open_act is not None and act is open_act:
            try:
                win.open_refined_flow_card(self, node_id)
            except Exception:
                pass
            return
        if refine_act is not None and act is refine_act:
            try:
                win.refine_flow_node(self, node_id)
            except Exception:
                pass
            return
        if logic_act is not None and act is logic_act:
            try:
                win.focus_lexicon_entry(str(mapped_entry.get('id', '') or ''))
            except Exception:
                pass
            return
        if act is jump_act:
            try:
                win.jump_to_flow_node(self, node)
            except Exception:
                pass

    def _on_node_clicked(self, item):
        if item is None:
            return
        node = self._node_by_id(item.data(Qt.ItemDataRole.UserRole))
        if isinstance(node, dict):
            try:
                self.window().jump_to_flow_node(self, node)
            except Exception:
                pass

    def _request_revise(self):
        try:
            self.window().revise_flow_card(self)
        except Exception:
            pass

    def _request_revision_view(self, which):
        try:
            self.window().set_card_revision_view(self, which)
        except Exception:
            pass

    def _request_adopt_revision(self):
        try:
            self.window().adopt_card_revision(self)
        except Exception:
            pass

    def _request_discard_revision(self):
        try:
            self.window().discard_card_revision(self)
        except Exception:
            pass

    # ── content context menu ─────────────────────────────────
    def _selected_or_full_text(self):
        try:
            sel = self.browser.textCursor().selectedText().replace('\u2029', '\n').strip()
        except Exception:
            sel = ''
        return sel or str(self.result_text or '').strip()

    def _main_widget(self):
        return getattr(self.window(), '_main', None)

    def _show_diagram_menu(self, pos):
        self._show_content_menu(pos, source='diagram')

    def _show_content_menu(self, pos, source='browser'):
        parent = self.diagram_view if source == 'diagram' and self.diagram_view is not None else self.browser
        menu = style_broccoli_context_menu(QMenu(parent))
        append_act = menu.addAction(_tr('Append to current chat'))
        web_act = menu.addAction(_tr('Ask Web'))
        local_act = menu.addAction(_tr('Ask Localhost'))
        menu.addSeparator()
        copy_act = menu.addAction(_tr('Copy'))
        share_act = None
        if self.kind in ('flow', 'object', 'function') and self.svg_text:
            menu.addSeparator()
            share_act = menu.addAction(_tr('Share as Image'))
        regen_act = None
        if self.from_cache and self.kind == 'explain':
            menu.addSeparator()
            regen_act = menu.addAction(_tr('Regenerate'))
        text = self._selected_or_full_text()
        for a in (append_act, web_act, local_act, copy_act):
            a.setEnabled(bool(text))
        if source == 'diagram' and self.diagram_view is not None:
            global_pos = self.diagram_view.mapToGlobal(pos)
        else:
            global_pos = self.browser.viewport().mapToGlobal(pos)
        act = menu.exec(global_pos)
        if act is None:
            return
        if share_act is not None and act is share_act:
            self._share_diagram_as_image()
            return
        if act is copy_act:
            if source != 'diagram' and self.browser.textCursor().hasSelection():
                self.browser.copy()
            else:
                try:
                    QApplication.clipboard().setText(text)
                except Exception:
                    pass
            return
        if regen_act is not None and act is regen_act:
            self.regenerate_requested.emit()
            return
        key = None
        if act is append_act:
            key = 'append_current'
        elif act is web_act:
            key = 'ask_web'
        elif act is local_act:
            key = 'ask_localhost'
        if key and text:
            main = self._main_widget()
            if main is not None:
                try:
                    main._execute_selection_ask_action(key, text)
                except Exception:
                    pass

    def _share_diagram_as_image(self):
        if not self.svg_text:
            return
        main = self._main_widget()
        dark = bool(self._dark)
        bg = '#2D2D2D' if dark else '#FFFFFF'
        fg = '#F2F2F7' if dark else '#20242B'
        body = (
            '<!doctype html><html><head><meta charset="utf-8"><style>'
            'html,body{margin:0;padding:0;background:%s;color:%s;}'
            'body{padding:28px;font-family:"Helvetica Neue",Helvetica,Arial,sans-serif;}'
            '.share-capture{display:inline-block;}'
            'svg{display:block;background:%s;}'
            '</style></head><body><div class="share-capture">%s</div></body></html>'
        ) % (bg, fg, bg, self.svg_text)
        if main is not None and hasattr(main, '_capture_html_document_as_share_image'):
            try:
                width = 900
                if not self._diagram_pixmap.isNull():
                    width = max(360, min(1400, int(self._diagram_pixmap.width())))
                main._capture_html_document_as_share_image(body, width, '')
                return
            except Exception:
                pass
        if main is not None and hasattr(main, 'show_share_panel') and not self._diagram_pixmap.isNull():
            try:
                pad = 36
                bgc = QColor(bg)
                img = QImage(
                    self._diagram_pixmap.width() + pad * 2,
                    self._diagram_pixmap.height() + pad * 2,
                    QImage.Format.Format_ARGB32,
                )
                img.fill(bgc)
                painter = QPainter(img)
                painter.drawPixmap(pad, pad, self._diagram_pixmap)
                painter.end()
                fin = finalize_share_image_worker(img, bgc)
                main.show_share_panel(QPixmap.fromImage(fin))
            except Exception:
                pass


class EditorCardDock(QWidget):
    """Right-side floating overlay owning the cards. Plain child of the pages area —
    sized to its own rect, so it never steals clicks outside itself."""
    MARGIN = 14
    BOTTOM_H = 26
    # the card's visible bottom edge → the pager: 10, like the panels above the Agent tab's
    # bottom bar (it was 22: an 8 px gap + the card's see-through shadow room)
    CARD_GAP = 10

    def __init__(self, window, parent):
        super().__init__(parent)
        self._win = window
        self.cards = []
        self._index = -1
        self._shown = False        # logically slid in
        self._suppressed = False   # slid out for Snapshots/Compare — cards kept
        self._dark = False
        self._slide_anim = None
        self._switch_anim = None
        self._close_anim = None
        self._closing_card = None
        self._minimized = False    # slid out by the user; a small pill brings the cards back
        self._tab_hidden = False   # Snapshots / Compare: no dock, no pill

        self._bottom = EditorCardDockBar(self)
        self._bottom.setObjectName('editorCardDockBar')
        self._bottom.setAttribute(Qt.WidgetAttribute.WA_StyledBackground, True)
        bar_shadow = QGraphicsDropShadowEffect(self._bottom)
        bar_shadow.setBlurRadius(18)
        bar_shadow.setXOffset(0)
        bar_shadow.setYOffset(0)
        bar_shadow.setColor(QColor(0, 0, 0, 40))
        self._bottom.setGraphicsEffect(bar_shadow)
        bl = QHBoxLayout(self._bottom)
        bl.setContentsMargins(10, 2, 12, 2)
        bl.setSpacing(6)
        self.prev_btn = glass_disc_in_clip(QPushButton('‹', self._bottom))
        self.next_btn = glass_disc_in_clip(QPushButton('›', self._bottom))
        for b in (self.prev_btn, self.next_btn):
            b.setFixedSize(22, 22)
            b.setCursor(Qt.CursorShape.PointingHandCursor)
            b.setFocusPolicy(Qt.FocusPolicy.NoFocus)
        self.prev_btn.clicked.connect(lambda: self.go_to(self._index - 1))
        self.next_btn.clicked.connect(lambda: self.go_to(self._index + 1))
        self.dots = _EditorCardDots(self._bottom)
        self.title_lbl = QLabel('', self._bottom)
        bl.addWidget(self.prev_btn)
        bl.addWidget(self.dots)
        bl.addWidget(self.next_btn)
        bl.addSpacing(2)
        bl.addWidget(self.title_lbl, 1)
        self.min_btn = glass_disc_in_clip(QPushButton('−', self._bottom))   # out of the way without closing them
        self.min_btn.setFixedSize(22, 22)
        self.min_btn.setCursor(Qt.CursorShape.PointingHandCursor)
        self.min_btn.setFocusPolicy(Qt.FocusPolicy.NoFocus)
        self.min_btn.setToolTip(_tr('Minimize cards'))
        self.min_btn.clicked.connect(self.minimize)
        bl.addWidget(self.min_btn)
        # the minimized dock: one small glass pill where the pager was
        self.restore_btn = glass_button(QPushButton('', parent))
        self.restore_btn.setFixedHeight(self.BOTTOM_H)
        self.restore_btn.setCursor(Qt.CursorShape.PointingHandCursor)
        self.restore_btn.setFocusPolicy(Qt.FocusPolicy.NoFocus)
        self.restore_btn.setToolTip(_tr('Show the cards again'))
        self.restore_btn.clicked.connect(self.restore)
        self.restore_btn.hide()
        try:
            parent.installEventFilter(self)   # track the pages area size directly
        except Exception:
            pass
        self.hide()
        try:
            self.set_theme(is_dark_theme(app))
        except Exception:
            self.set_theme(False)

    def eventFilter(self, obj, event):
        if obj is self.parentWidget() and event.type() == QEvent.Type.Resize:
            self.relayout()
        return super().eventFilter(obj, event)

    # ── geometry ─────────────────────────────────────────────
    def _dock_width(self):
        parent = self.parentWidget()
        pw = parent.width() if parent is not None else 720
        w = max(300, int(pw * 0.42))
        return min(w, max(120, pw - 24))

    def _shown_rect(self):
        parent = self.parentWidget()
        pw = parent.width() if parent is not None else 720
        ph = parent.height() if parent is not None else 480
        w = self._dock_width()
        h = max(120, ph - 12)   # down to the bottom of the pages: the pager sits 10 above the bottom bar
        return QRect(pw - 12 - w, 12, w, h)

    def _hidden_rect(self):
        r = self._shown_rect()
        parent = self.parentWidget()
        pw = parent.width() if parent is not None else 720
        return QRect(pw + 24, r.y(), r.width(), r.height())

    def _slot_rect(self):
        # card slot in dock-local coordinates (bottom row lives below it)
        m = self.MARGIN
        # the card's see-through shadow room fills the gap; it never reaches under the pager
        return QRect(m, m, max(40, self.width() - 2 * m),
                     max(40, self.height() - m - self.BOTTOM_H - max(0, self.CARD_GAP - EditorCard.SHADOW_BOTTOM)))

    def relayout(self):
        self._settle_animations()
        self.setGeometry(self._shown_rect() if self._shown else self._hidden_rect())
        self._bottom.setGeometry(self.MARGIN, self.height() - self.BOTTOM_H,
                                 max(40, self.width() - 2 * self.MARGIN), self.BOTTOM_H)
        self._normalize_card_positions()
        self._update_restore_button()
        if self._shown and self.isVisible():
            self.raise_()

    # ── animation bookkeeping (jump-to-end pattern) ──────────
    def _settle_animations(self):
        anim = self._switch_anim
        self._switch_anim = None
        if anim is not None:
            try:
                anim.stop()
            except Exception:
                pass
        anim = self._close_anim
        self._close_anim = None
        if anim is not None:
            try:
                anim.stop()
            except Exception:
                pass
        # no-op unless a close was mid-flight; animate=False so settling never
        # starts a new animation (a reveal here would race the caller's next one)
        self._finalize_close(animate=False)
        anim = self._slide_anim
        self._slide_anim = None
        if anim is not None:
            try:
                anim.stop()
            except Exception:
                pass
            if self._shown:
                self.setGeometry(self._shown_rect())
                self.show()
            else:
                self.setGeometry(self._hidden_rect())
                self.hide()
        self._normalize_card_positions()

    def _normalize_card_positions(self):
        slot = self._slot_rect()
        for i, card in enumerate(self.cards):
            try:
                card.setGeometry(slot)
                if i == self._index:
                    card.show()
                    card.raise_()
                else:
                    card.hide()
            except Exception:
                continue
        self._bottom.raise_()
        self._update_bottom_row()

    # ── dock slide in / out ──────────────────────────────────
    def _slide_in(self):
        self._suppressed = False
        start = QRect(self.geometry()) if self.isVisible() else self._hidden_rect()
        if not self.isVisible():
            self.setGeometry(start)
        self._shown = True
        self.show()
        self.raise_()
        anim = QPropertyAnimation(self, b'geometry', self)
        anim.setDuration(260)
        anim.setStartValue(start)
        anim.setEndValue(self._shown_rect())
        anim.setEasingCurve(QEasingCurve.Type.OutCubic)
        self._slide_anim = anim
        anim.start()

    def _slide_out(self):
        self._shown = False
        if not self.isVisible():
            return
        anim = QPropertyAnimation(self, b'geometry', self)
        anim.setDuration(220)
        anim.setStartValue(QRect(self.geometry()))
        anim.setEndValue(self._hidden_rect())
        anim.setEasingCurve(QEasingCurve.Type.InCubic)
        anim.finished.connect(self._finish_slide_out)
        self._slide_anim = anim
        anim.start()

    def _finish_slide_out(self):
        if not self._shown:
            self.hide()

    # ── minimize ─────────────────────────────────────────────
    def minimize(self):
        """Slide the cards out (kept, unlike ✕); the pill left behind brings them back."""
        if not self.cards:
            return
        self._settle_animations()
        self._minimized = True
        self._slide_out()
        anim = self._slide_anim
        if anim is not None and anim.state() == QPropertyAnimation.State.Running:
            # the pill once the cards are out: shown at once (raised above the dock), the dock
            # sliding under it repainted it — and re-rendered its glass — every frame
            anim.finished.connect(self._update_restore_button)
        else:
            self._update_restore_button()

    def restore(self):
        if not self._minimized:
            return
        self._minimized = False
        self._update_restore_button()
        if self.cards and not self._tab_hidden:
            self._settle_animations()
            self._normalize_card_positions()
            self._slide_in()

    def _update_restore_button(self):
        button = getattr(self, 'restore_btn', None)
        parent = self.parentWidget()
        if button is None or parent is None:
            return
        wanted = bool(self._minimized and self.cards and not self._tab_hidden)
        if wanted:
            button.setText('‹  ' + _tr('Cards') + f'  {len(self.cards)}')
            width = button.fontMetrics().horizontalAdvance(button.text()) + 30
            # where the pager's right end was: 10 above the bottom bar, at the dock's right edge
            button.setGeometry(parent.width() - 12 - self.MARGIN - width, parent.height() - self.BOTTOM_H,
                               width, self.BOTTOM_H)
            button.show()
            button.raise_()
        elif button.isVisible():
            button.hide()

    # ── binding API ──────────────────────────────────────────
    def open_card(self, kind, title, payload, display_title=None):
        if self._minimized:   # a new card brings the dock back
            self._minimized = False
            self._update_restore_button()
        self._settle_animations()
        card = EditorCard(kind, title, payload, self, display_title=display_title)
        card.set_theme(self._dark)
        card.close_requested.connect(lambda c=card: self._close_card(c))
        self.cards.append(card)
        old_index = self._index
        self._index = len(self.cards) - 1
        card.setGeometry(self._slot_rect())
        if not (self._shown and self.isVisible()):
            self._normalize_card_positions()
            self._slide_in()
        else:
            self._animate_switch(old_index, self._index, 1)
        self._update_bottom_row()
        return card

    def close_current(self):
        # settle FIRST — finalizing an in-flight close pops self.cards and
        # moves _index, so pick the card from the settled state
        self._settle_animations()
        if 0 <= self._index < len(self.cards):
            self._close_card(self.cards[self._index])

    def current_card(self):
        if 0 <= self._index < len(self.cards):
            return self.cards[self._index]
        return None

    def go_to(self, index):
        try:
            index = int(index)
        except Exception:
            return
        # settle FIRST — finalizing an in-flight close pops self.cards and
        # moves _index; validity must be judged against the settled state
        self._settle_animations()
        if not (0 <= index < len(self.cards)) or index == self._index:
            return
        old = self._index
        self._index = index
        if self._shown and self.isVisible():
            self._animate_switch(old, index, 1 if index > old else -1)
        else:
            self._normalize_card_positions()
        self._update_bottom_row()

    # ── card switching (tile-slide) ──────────────────────────
    def _animate_switch(self, old_index, new_index, direction):
        slot = self._slot_rect()
        w = slot.width() + self.MARGIN
        new_card = self.cards[new_index]
        old_card = self.cards[old_index] if 0 <= old_index < len(self.cards) else None
        if old_card is new_card:
            old_card = None
        new_start = QRect(slot)
        new_start.translate(direction * w, 0)
        new_card.setGeometry(new_start)
        new_card.show()
        new_card.raise_()
        group = QParallelAnimationGroup(self)
        a_new = QPropertyAnimation(new_card, b'geometry')
        a_new.setDuration(260)
        a_new.setStartValue(new_start)
        a_new.setEndValue(slot)
        a_new.setEasingCurve(QEasingCurve.Type.OutCubic)
        group.addAnimation(a_new)
        if old_card is not None:
            old_end = QRect(slot)
            old_end.translate(-direction * w, 0)
            a_old = QPropertyAnimation(old_card, b'geometry')
            a_old.setDuration(260)
            a_old.setStartValue(QRect(old_card.geometry()))
            a_old.setEndValue(old_end)
            a_old.setEasingCurve(QEasingCurve.Type.OutCubic)
            group.addAnimation(a_old)
        group.finished.connect(self._on_switch_finished)
        self._switch_anim = group
        self._bottom.raise_()
        group.start()

    def _on_switch_finished(self):
        self._switch_anim = None
        self._normalize_card_positions()

    def _reveal_current(self, direction):
        # single-card slide-in after a close (direction: -1 = enters from the left)
        if not (0 <= self._index < len(self.cards)):
            return
        slot = self._slot_rect()
        card = self.cards[self._index]
        start = QRect(slot)
        start.translate(direction * (slot.width() + self.MARGIN), 0)
        card.setGeometry(start)
        card.show()
        card.raise_()
        self._bottom.raise_()
        anim = QPropertyAnimation(card, b'geometry', self)
        anim.setDuration(260)
        anim.setStartValue(start)
        anim.setEndValue(slot)
        anim.setEasingCurve(QEasingCurve.Type.OutCubic)
        anim.finished.connect(self._on_switch_finished)
        self._switch_anim = anim
        anim.start()

    # ── card closing ─────────────────────────────────────────
    def _stop_card_worker(self, card):
        worker = getattr(card, 'worker', None)
        try:
            card.worker = None
        except Exception:
            pass
        if worker is None:
            return
        try:
            worker.stop()
        except Exception:
            pass
        for sig_name in ('delta', 'finished_text', 'failed'):
            try:
                getattr(worker, sig_name).disconnect()
            except Exception:
                pass

    def _close_card(self, card):
        # settle FIRST — it may finalize an in-flight close (pops self.cards),
        # e.g. a double-clicked ✕; only then judge whether card still exists
        self._settle_animations()
        if card is None or card not in self.cards:
            return
        idx = self.cards.index(card)
        if idx != self._index:
            self._index = idx
            self._normalize_card_positions()
        card._alive = False
        for glassy in (card._body, card.close_btn):
            helper = getattr(glassy, '_broccoli_inwindow_glass', None)
            if helper is not None:
                helper.sync()   # back to its Qt look, which the fade below can animate
        self._stop_card_worker(card)
        self._closing_card = card
        # shrink toward the center + fade (child widgets can't animate windowOpacity)
        g = QRect(card.geometry())
        target = QRect(g)
        target.setSize(QSize(max(40, int(g.width() * 0.72)), max(40, int(g.height() * 0.72))))
        target.moveCenter(g.center())
        effect = QGraphicsOpacityEffect(card)
        card.setGraphicsEffect(effect)
        effect.setOpacity(1.0)
        group = QParallelAnimationGroup(self)
        a_geo = QPropertyAnimation(card, b'geometry')
        a_geo.setDuration(200)
        a_geo.setStartValue(g)
        a_geo.setEndValue(target)
        a_geo.setEasingCurve(QEasingCurve.Type.InCubic)
        a_fade = QPropertyAnimation(effect, b'opacity')
        a_fade.setDuration(200)
        a_fade.setStartValue(1.0)
        a_fade.setEndValue(0.0)
        a_fade.setEasingCurve(QEasingCurve.Type.InCubic)
        group.addAnimation(a_geo)
        group.addAnimation(a_fade)
        group.finished.connect(self._finalize_close)
        self._close_anim = group
        group.start()

    def _finalize_close(self, animate=True):
        card = self._closing_card
        if card is None:
            return
        self._closing_card = None
        anim = self._close_anim
        self._close_anim = None
        if anim is not None:
            try:
                anim.stop()
            except Exception:
                pass
        idx = self.cards.index(card) if card in self.cards else -1
        if idx >= 0:
            self.cards.pop(idx)
        try:
            card.hide()
            card.deleteLater()
        except Exception:
            pass
        if not self.cards:
            self._index = -1
            self._update_bottom_row()
            self._minimized = False
            self._update_restore_button()
            if animate:
                self._slide_out()
            else:
                # settling context: hide instantly, start nothing
                self._shown = False
                self.setGeometry(self._hidden_rect())
                self.hide()
            return
        # prefer the left neighbor; it enters from the side it lives on
        self._index = idx - 1 if idx > 0 else 0
        if animate:
            self._reveal_current(-1 if idx > 0 else 1)
        else:
            self._normalize_card_positions()
        self._update_bottom_row()

    # ── tab behavior (dock hides on Snapshots/Compare) ───────
    def suppress_for_tab(self):
        self._tab_hidden = True
        self._update_restore_button()
        if self._shown and self.isVisible():
            self._settle_animations()
            if not self._shown:
                return   # settling a last-card close already hid the dock
            self._suppressed = True
            self._slide_out()

    def restore_after_tab(self):
        self._tab_hidden = False
        if self._minimized:   # it stays minimized; only its pill comes back
            self._update_restore_button()
            return
        if self._suppressed and self.cards:
            self._settle_animations()
            if not self.cards:
                return   # settling an in-flight close emptied the dock
            self._normalize_card_positions()
            self._slide_in()   # clears _suppressed
        elif self._shown and self.isVisible():
            # tab switches raise the incoming page above us (QStackedLayout) —
            # e.g. Editor ↔ Logic Map with the dock out: stay on top
            self.raise_()

    # ── bottom row / theme ───────────────────────────────────
    def _update_bottom_row(self):
        n = len(self.cards)
        self.prev_btn.setEnabled(self._index > 0)
        self.next_btn.setEnabled(self._index < n - 1)
        self.dots.set_state(n, self._index)
        cur = self.current_card()
        title = getattr(cur, 'display_title', cur.title) if cur is not None else ''
        try:
            fm = self.title_lbl.fontMetrics()
            avail = max(24, self.title_lbl.width() - 4)
            self.title_lbl.setText(fm.elidedText(title, Qt.TextElideMode.ElideRight, avail))
        except Exception:
            self.title_lbl.setText(title)

    def _style_bottom(self):
        dark = self._dark
        if getattr(self._bottom, '_liquid_glass_active', False):
            bg = 'transparent'   # the glass is the capsule
        else:
            bg = '#2D2D2D' if dark else '#FFFFFF'
        fg = '#F2F2F7' if dark else '#333333'
        dim = '#8E8E93' if dark else '#A0A0A6'
        hover = 'rgba(255,255,255,34)' if dark else 'rgba(0,0,0,26)'
        self._bottom.setStyleSheet(
            '#editorCardDockBar { background: %s; border-radius: 13px; }'
            ' QLabel { color: %s; font-size: 11px; background: transparent; }' % (bg, dim))
        for button in (self.prev_btn, self.next_btn, self.min_btn):   # their own: the glass skin strips the fills
            button.setStyleSheet(
                'QPushButton { border: none; border-radius: 11px; background: transparent;'
                ' color: %s; font-size: 14px; }'
                ' QPushButton:hover { background: %s; }'
                ' QPushButton:disabled { color: %s; }' % (fg, hover, dim))
        if getattr(self, 'restore_btn', None) is not None:
            self.restore_btn.setStyleSheet(
                'QPushButton { border: none; border-radius: %dpx; padding: 0 12px; background: %s;'
                ' color: %s; font-size: 11px; }' % (self.BOTTOM_H // 2, '#2D2D2D' if dark else '#FFFFFF', fg))

    def set_theme(self, dark_mode):
        dark = bool(dark_mode)
        self._dark = dark
        self._style_bottom()
        self.dots.set_theme(dark)
        for card in self.cards:
            try:
                card.set_theme(dark)
            except Exception:
                continue


# ---- M7: main-chat integration ----

_EDITOR_CONVERSATION_TITLE_CACHE = {}


def _editor_one_line(text, cap=120):
    text = re.sub(r'\s+', ' ', str(text or '')).strip()
    if len(text) > cap:
        text = text[:max(0, cap - 1)].rstrip() + '…'
    return text


def _editor_cap_text(text, cap):
    text = str(text or '')
    cap = max(120, int(cap or 120))
    if len(text) <= cap:
        return text
    return text[:cap].rstrip() + '\n[truncated]'


def _editor_fenced_block(text, max_lines=120, max_chars=8000):
    lines = str(text or '').splitlines()
    suffix = ''
    if len(lines) > max_lines:
        lines = lines[:max_lines]
        suffix = '\n[selection truncated]'
    body = '\n'.join(lines)
    body = _editor_cap_text(body, max_chars)
    fence = '````' if '```' in body else '```'
    return fence + '\n' + body + suffix + '\n' + fence


def _editor_line_span_overlaps(a, b, c, d):
    try:
        a = int(a)
        b = int(b)
        c = int(c)
        d = int(d)
    except Exception:
        return False
    if a <= 0 or b <= 0 or c <= 0 or d <= 0:
        return False
    return max(a, c) <= min(b, d)


def _editor_changed_line_span(old_text, new_text):
    old_lines = str(old_text or '').splitlines()
    new_lines = str(new_text or '').splitlines()
    matcher = difflib.SequenceMatcher(None, old_lines, new_lines)
    starts = []
    ends = []
    for tag, i1, i2, _j1, _j2 in matcher.get_opcodes():
        if tag == 'equal':
            continue
        starts.append(i1 + 1)
        ends.append(max(i1 + 1, i2))
    if not starts:
        return None
    return [max(1, min(starts)), max(starts[0], max(ends))]


def _editor_changed_region_text(old_text, new_text):
    """The concatenated text of the lines that differ between old and new
    (both sides of every non-equal opcode). Used for symbol-name relevance
    matching, which survives the line-number drift that edits cause."""
    old_lines = str(old_text or '').splitlines()
    new_lines = str(new_text or '').splitlines()
    matcher = difflib.SequenceMatcher(None, old_lines, new_lines)
    chunks = []
    for tag, i1, i2, j1, j2 in matcher.get_opcodes():
        if tag == 'equal':
            continue
        chunks.extend(old_lines[i1:i2])
        chunks.extend(new_lines[j1:j2])
    return '\n'.join(chunks)


def editor_conversation_title(conversation_id):
    cid = str(conversation_id or '').strip()
    if not cid:
        return ''
    if cid in _EDITOR_CONVERSATION_TITLE_CACHE:
        return _EDITOR_CONVERSATION_TITLE_CACHE.get(cid, '')
    title = ''
    try:
        for path in Path(CONVERSATIONS_DIR).glob('*.json'):
            if str(path).endswith(CONVERSATION_RETRIEVAL_SUFFIX):
                continue
            stem = path.stem
            if stem != cid and not stem.startswith(cid + '_'):
                continue
            record = load_conversation_record(str(path), include_retrieval=False)
            if isinstance(record, dict) and str(record.get('id', '') or '') == cid:
                title = str(record.get('title', '') or '').strip()
                break
    except Exception:
        title = ''
    if not title:
        title = cid[:8]
    title = _editor_one_line(title, 34)
    _EDITOR_CONVERSATION_TITLE_CACHE[cid] = title
    return title


def _editor_visible_window(main_window):
    try:
        editor = main_window.editor_window_if_open()
    except Exception:
        editor = None
    if editor is None:
        return None
    try:
        if not editor.isVisible():
            return None
    except Exception:
        return None
    return editor


def _editor_related_flows_text(store, line_start, line_end, cap=5):
    if store is None:
        return ''
    hits = []
    try:
        flows = store.load_flows()
        for flow in flows.get('flows', []) if isinstance(flows, dict) else []:
            if not isinstance(flow, dict):
                continue
            origin = flow.get('origin') if isinstance(flow.get('origin'), dict) else {}
            lines = origin.get('lines')
            matched = False
            if isinstance(lines, (list, tuple)) and len(lines) >= 2:
                matched = _editor_line_span_overlaps(line_start, line_end, lines[0], lines[1])
            if not matched:
                for node in flow.get('nodes') or []:
                    cref = node.get('code_ref') if isinstance(node, dict) else None
                    nlines = cref.get('lines') if isinstance(cref, dict) else None
                    if isinstance(nlines, (list, tuple)) and len(nlines) >= 2:
                        if _editor_line_span_overlaps(line_start, line_end, nlines[0], nlines[1]):
                            matched = True
                            break
            if not matched:
                continue
            hits.append(_editor_flow_context_line(flow))
            if len(hits) >= cap:
                break
    except Exception:
        return ''
    return '\n'.join('- ' + h for h in hits)


def _editor_flow_context_line(flow):
    """One-line flow summary that INCLUDES node ids, so the model can return an
    id-aligned flow_revision (reusing ids for unchanged steps)."""
    node_bits = []
    for node in flow.get('nodes') or []:
        if not isinstance(node, dict):
            continue
        nid = str(node.get('id', '') or '').strip()
        desc = _editor_one_line(node.get('desc', ''), 34)
        if nid and desc:
            node_bits.append('%s=%s' % (nid, desc))
        if len(node_bits) >= 6:
            break
    return '%s "%s" [nodes: %s]' % (
        str(flow.get('id', '') or ''),
        _editor_one_line(flow.get('title', '') or 'Flow', 54),
        '; '.join(node_bits) if node_bits else 'none',
    )


def _editor_file_flows_text(store, cap=6):
    """All of a file's persisted flows (id + title + node ids), for the
    no-selection case so the model knows which flow to revise when editing."""
    if store is None:
        return ''
    try:
        flows = store.load_flows()
        flow_list = [f for f in (flows.get('flows', []) if isinstance(flows, dict) else []) if isinstance(f, dict)]
    except Exception:
        return ''
    if not flow_list:
        return ''
    return '\n'.join('- ' + _editor_flow_context_line(f) for f in flow_list[:cap])


def _editor_file_outline_text(store, live_text=None, cap=60):
    """A bounded structural map: symbols/sections with their CURRENT line numbers,
    so the model can navigate a large file and target line ranges WITHOUT the file
    body ever being injected. Capped (a note marks truncation).

    Line numbers MUST reflect the editor's current text. When live_text is given,
    parse it SYNCHRONOUSLY (the persisted lexicon anchors lag behind — they only
    update via the async 1s-debounce parse worker, so a send right after typing or
    right after an approved edit would otherwise serialize stale line numbers).
    Falls back to persisted anchors only when a fresh parse is unavailable."""
    rows = []
    if store is not None and live_text is not None:
        try:
            kind = store.file_kind()
            parsed = editor_extract_identifiers(str(live_text), kind)
        except Exception:
            parsed = None
        if parsed:
            for item in parsed:
                try:
                    line = int(item.get('line', 0) or 0)
                except Exception:
                    line = 0
                if line <= 0:
                    continue
                rows.append((line, '%s (%s) @ line %d' % (
                    _editor_one_line(item.get('code_name', ''), 48),
                    str(item.get('category', '') or 'Other'),
                    line,
                )))
    if not rows:
        # fallback: persisted anchors (may lag the live text)
        if store is None:
            return ''
        try:
            lex = store.load_lexicon() if store is not None else {}
            entries = [e for e in (lex.get('entries') or []) if isinstance(e, dict) and not e.get('gone')]
        except Exception:
            return ''
        for e in entries:
            anchors = e.get('anchors') if isinstance(e.get('anchors'), list) else []
            line = None
            if anchors and isinstance(anchors[0], dict):
                try:
                    line = int(anchors[0].get('line', 0) or 0)
                except Exception:
                    line = None
            if not line:
                continue
            rows.append((line, '%s (%s) @ line %d' % (
                _editor_one_line(e.get('code_name', ''), 48),
                str(e.get('category', '') or 'Other'),
                line,
            )))
    if not rows:
        return ''
    rows.sort(key=lambda r: r[0])
    truncated = len(rows) > cap
    body = '\n'.join('- ' + r[1] for r in rows[:cap])
    if truncated:
        body += '\n- … (%d more symbols; ask for a specific range)' % (len(rows) - cap)
    return body


def _editor_visible_card_text(editor):
    try:
        dock = getattr(editor, 'card_dock', None)
        card = dock.current_card() if dock is not None else None
    except Exception:
        card = None
    if card is None:
        return ''
    try:
        if card.kind in ('flow', 'object', 'function'):
            flow = card.payload.get('flow') if isinstance(card.payload, dict) else None
            title = str((flow or {}).get('title', '') or card.title or card.kind)
            return "%s · '%s' · %s" % (card.kind, _editor_one_line(card.title, 64), _editor_one_line(title, 180))
        result = str(getattr(card, 'result_text', '') or '')
        return "%s · '%s' · %s" % (card.kind, _editor_one_line(card.title, 64), _editor_one_line(result, 200))
    except Exception:
        return ''


def editor_open_file_paths(main_window):
    """Absolute paths of files currently open in the visible editor, plus the
    active edit target. Returns (paths:list, target:str). Must be called on the
    GUI thread (reads editor widgets)."""
    editor = _editor_visible_window(main_window)
    if editor is None:
        return [], ''
    try:
        paths = [str(p) for p in (getattr(editor.session, 'open_files', []) or [])]
    except Exception:
        paths = []
    try:
        target = str(getattr(editor.session, 'edit_target', None) or '') or (paths[0] if paths else '')
    except Exception:
        target = paths[0] if paths else ''
    return paths, target


def editor_read_snapshot(main_window):
    """Point-in-time LIVE text of each open editor file, for the native editor
    read tool. GUI-thread only. This is NOT prompt injection — the content is
    parked in the request config and the model only ever receives the exact
    line ranges it explicitly asks for via the broccoli_editor_read tool."""
    editor = _editor_visible_window(main_window)
    if editor is None:
        return {}, ''
    paths, target = editor_open_file_paths(main_window)
    files = {}
    for p in paths:
        try:
            files[p] = editor_live_text_for(editor, p)
        except Exception:
            pass
    return files, target


def editor_planner_note(main_window):
    """Compact note for the specialized-step PLANNER so it does NOT route edits
    of editor-open files to terminal_command/browser_use. GUI-thread only.
    Kept short (no outline/flows — the planner only needs the file list)."""
    paths, target = editor_open_file_paths(main_window)
    if not paths:
        return ''
    rows = []
    for p in paths[:12]:
        rows.append('- %s%s' % (p, '  [active edit target]' if p == target else ''))
    return (
        'Editor status: the Broccoli Editor window is OPEN. Files open in it (absolute paths):\n'
        + '\n'.join(rows)
        + '\nRULE: changes the user wants to any of these open files MUST be delivered by the default '
        'answer as an editor_edit permission block — NEVER plan terminal_command or browser_use to create, '
        'edit, or write them. For such an edit request, plan NO steps (or only genuinely needed research '
        'steps); the default answer performs the edit through the editor permission flow.'
    )


def editor_build_context_block(main_window):
    editor = _editor_visible_window(main_window)
    if editor is None:
        return ''
    try:
        state = editor.current_editor_state()
    except Exception:
        state = {}
    open_files = list(state.get('open_files') or getattr(editor.session, 'open_files', []) or [])
    current_path = str(state.get('current_path', '') or getattr(editor.session, 'current_path', '') or '')
    lines = ['=== Editor window (user\'s code editor) ===']
    # All open files are editable via editor_edit; list each with its ABSOLUTE
    # path so any file read is a path-scoped read, never a whole-disk search.
    file_bits = []
    for path in open_files[:12]:
        store = EditorStore.for_path(path)
        kind = ''
        try:
            kind = store.file_kind() if store is not None else ''
        except Exception:
            kind = ''
        file_bits.append('  - %s%s  [%s]' % (
            os.path.basename(path) or path, (' (%s)' % kind) if kind else '', path))
    if file_bits:
        lines.append('Open files (all editable via editor_edit):')
        lines.append('\n'.join(file_bits))
    else:
        lines.append('Open files: none')
    # Active edit target = the user-designated primary (blue pill) if set, else
    # the current file. Editability of a file does NOT by itself mean the user
    # wants it edited — the edit-vs-new decision is made from the request below.
    target_path = str(getattr(editor.session, 'edit_target', None) or '') or current_path
    if current_path:
        lines.append('Current file: %s  [%s]' % (os.path.basename(current_path) or current_path, current_path))
    if target_path:
        designated = bool(str(getattr(editor.session, 'edit_target', None) or ''))
        lines.append('Active edit target (edits default here): %s  [%s]%s' % (
            os.path.basename(target_path) or target_path, target_path,
            '' if designated else ' — inferred from the current file; not explicitly pinned'))
    store = editor.session.store(current_path) if current_path else None
    target_store = editor.session.store(target_path) if target_path else None
    selection = state.get('selection') if isinstance(state.get('selection'), dict) else {}
    selected_text = str(selection.get('text', '') or '')
    if selected_text.strip():
        try:
            ls = int(selection.get('line_start', 0) or 0)
            le = int(selection.get('line_end', 0) or 0)
        except Exception:
            ls = le = 0
        lines.append('Selected lines %d-%d:' % (ls, le if le else ls))
        lines.append(_editor_fenced_block(selected_text, max_lines=120, max_chars=6000))
        try:
            glossary = editor_explain_glossary(store, selected_text, cap=40)
        except Exception:
            glossary = ''
        if glossary:
            lines.append('Glossary for the selection (call these objects by their natural names):')
            lines.append(glossary)
        related = _editor_related_flows_text(store, ls, le)
        if related:
            lines.append('Flows for the edit target (reuse these node ids in flow_revision):')
            lines.append(related)
    else:
        # Flows FIRST (before the long natural-name directory) so the 4000-char
        # cap's mid-block truncation eats directory rows, not the flow node ids
        # the model needs to emit a flow_revision.
        file_flows = _editor_file_flows_text(target_store)
        if file_flows:
            lines.append('Flows for the edit target (reuse these node ids in flow_revision):')
            lines.append(file_flows)
        lines.append('Natural-name directory for %s (user may refer to code by these names; resolve via this table):'
                     % (os.path.basename(current_path) or 'current file'))
        rows = []
        try:
            lex = store.load_lexicon() if store is not None else {}
            entries = [e for e in (lex.get('entries') or []) if isinstance(e, dict)]
            entries = [
                e for e in entries
                if not e.get('gone') and str(e.get('natural_name', '') or '').strip()
                and str(e.get('status', '') or '') in ('confirmed', 'auto')
            ]
            entries.sort(key=lambda e: (0 if e.get('status') == 'confirmed' else 1, str(e.get('natural_name', '') or '')))
            for e in entries[:80]:
                rows.append('- %s -> %s [%s]' % (
                    _editor_one_line(e.get('natural_name', ''), 52),
                    _editor_one_line(e.get('code_name', ''), 52),
                    str(e.get('status', '') or 'auto'),
                ))
        except Exception:
            rows = []
        lines.append('\n'.join(rows) if rows else '- No confirmed or auto natural names yet.')
        # Bounded structural map of the edit-target file (symbol -> current line
        # numbers) so the model can target a precise line range for edits
        # without the file body ever being injected. Capped for huge files.
        # Parse the target's CURRENT live text synchronously so the outline line
        # numbers are always fresh (never the lagging persisted anchors).
        target_live = None
        try:
            if target_path:
                target_live = editor_live_text_for(editor, target_path)
        except Exception:
            target_live = None
        outline = _editor_file_outline_text(target_store, live_text=target_live)
        if outline:
            lines.append('Outline of %s (symbol -> current line; use line ranges to edit precisely):'
                         % (os.path.basename(target_path) or 'edit target'))
            lines.append(outline)
    card_text = _editor_visible_card_text(editor)
    if card_text:
        lines.append('Visible card: ' + card_text)
    rules_text = (
        'RULES:\n'
        '1. NEW vs EDIT (decide by the MEANING of the request, in any language — do not pattern-match keywords): '
        'if the user wants a brand-new, separate file (or content unrelated to the open files), emit a '
        '<broccoli-output type="code"> or type="text" deliverable block and do NOT edit any open file. '
        'If the user wants to change/fix/refine an existing open file, emit an editor_edit block for it '
        '(named file, or the active edit target above). If the request is ambiguous but an active edit '
        'target is set, prefer editing it; if ambiguous with no clear target, prefer a new deliverable or '
        'ask one short question. A file being open/editable does NOT by itself mean the user wants it edited. '
        'While the editor is open, never emit a deliverable block for changes to an open file (that '
        'duplicates the editor_edit) — deliverables are only for genuinely new/standalone content.\n'
        '2. EDITING PRECISELY: to see a file\'s current text, call the broccoli_editor_read tool for the '
        'exact lines you need (use the Outline above to pick the range) — do NOT run a terminal/shell '
        'command to read an editor file, and never dump the whole file. Prefer editor_edit mode '
        '"line_replace" (replace a line range you identified from the Outline) over "find_replace"; use '
        '"find_replace" only for a short snippet you have confirmed is unique in the CURRENT text; use '
        '"full" only for a genuine whole-file rewrite. If a find_replace is rejected for a non-unique/zero '
        'match, the current text around your target is returned — use it to correct the edit.\n'
        '3. NATURAL NAMES: resolve any name the user uses via the directory above. If a name is NOT there, '
        'do NOT guess — propose the mapping through the editor_edit entries block for the user to confirm. '
        'A confirmed natural name may only be renamed through an editor_edit (the user decides in the popup).\n'
        '4. FLOW DIAGRAMS: when a "Flows for the edit target" section is listed above, a flow_revision is '
        'REQUIRED in the editor_edit (a JSON object, never a string) unless the edit truly does not change '
        'the flow — REUSE the listed node ids for unchanged steps so the popup can color added/removed/changed steps.'
    )
    lines.append(rules_text)
    text = '\n'.join(str(x) for x in lines if str(x or '').strip()).strip()
    if len(text) <= 4000:
        return text
    body = '\n'.join(str(x) for x in lines[:-1] if str(x or '').strip()).strip()
    suffix = '\n' + rules_text
    keep = max(0, 4000 - len(suffix))
    if len(body) > keep:
        marker = '\n[truncated]'
        body = body[:max(0, keep - len(marker))].rstrip() + marker
    out = (body + suffix).strip()
    if len(out) > 4000:
        out = (body[:max(0, keep)].rstrip() + suffix).strip()
    return out


# External @targets (web / localhost / terminal CLIs) cannot call the native
# broccoli_editor_read tool. They still edit the SAME way as the main agent —
# by emitting an editor_edit JSON block in their answer, which Broccoli parses
# and routes through the same preview + approval + snapshot flow. This tail tells
# them how, per their disk access:
#   - terminal CLIs (codex/claude): have real disk access → read the listed file
#     paths themselves, then propose the edit; they must NOT write the file.
#   - web/localhost: no disk → the active target's current text is inlined (bounded);
#     large files degrade to outline-only (line_replace by the listed ranges).
EDITOR_EXTERNAL_WEB_CONTENT_MAX_CHARS = 8000


def editor_external_edit_tail(main_window, target_kind: str = 'web') -> str:
    editor = _editor_visible_window(main_window)
    if editor is None:
        return ''
    kind = str(target_kind or '').strip().lower()
    try:
        state = editor.current_editor_state()
    except Exception:
        state = {}
    open_files = list(state.get('open_files') or getattr(editor.session, 'open_files', []) or [])
    current_path = str(state.get('current_path', '') or getattr(editor.session, 'current_path', '') or '')
    target_path = str(getattr(editor.session, 'edit_target', None) or '') or current_path
    if not open_files and not current_path:
        return ''

    lines = ['=== Broccoli editor is open — you may propose code edits ===']
    lines.append('Open files (edit ONLY these; each shown with its absolute path):')
    for path in open_files or ([current_path] if current_path else []):
        lines.append('  - %s  [%s]' % (os.path.basename(path) or path, path))
    if target_path:
        lines.append('Preferred edit target (edits default here unless the request names another): [%s]' % target_path)

    if kind == 'terminal':
        lines.append(
            'You are a terminal CLI with disk access. LIVE snapshots of the open files '
            '(including unsaved edits) ride along as attachment files — when the '
            'attachment notice lists a snapshot path, READ THAT for the exact current '
            'text; only read the original absolute path above when no snapshot is '
            'listed (the disk copy may lag the editor buffer). In the editor_edit '
            'block (below), name the ORIGINAL file (basename or absolute path from '
            'the list), never the snapshot path. CRITICAL: do NOT write, move, or '
            'patch the file yourself — Broccoli shows the user a preview and applies '
            'the edit only after they approve, and keeps a revert snapshot. Writing '
            'the file directly bypasses that and is wrong.'
        )
    else:
        lines.append(
            'You have NO disk access. The current text of the edit target is provided '
            'below; base your edit on it. Do NOT ask to open files or run commands — '
            'just return an editor_edit block and Broccoli applies it after user approval.'
        )
        lines.append(
            'DELIVERY, in order of preference: (1) BEST — if you can create downloadable '
            'files (a code/file tool), SAVE the editor_edit JSON as a file named exactly '
            '"editor_edit.json" and give me its download link in your reply; Broccoli '
            'auto-detects and ingests the download, bypassing the chat page entirely. '
            '(2) Otherwise include the <broccoli-output type="editor_edit"> block in your '
            'reply INSIDE a fenced code block (``` on its own lines around it), so the '
            'chat page cannot swallow the tag when rendering.'
        )
        if target_path:
            try:
                content = str(editor_live_text_for(editor, target_path) or '')
            except Exception:
                content = ''
            if content and len(content) <= EDITOR_EXTERNAL_WEB_CONTENT_MAX_CHARS:
                lines.append('Current text of %s:' % (os.path.basename(target_path) or target_path))
                lines.append(_editor_fenced_block(content, max_lines=400, max_chars=EDITOR_EXTERNAL_WEB_CONTENT_MAX_CHARS))
            else:
                lines.append(
                    'The edit target is too large to inline here. Prefer editor_edit mode '
                    '"line_replace" using line ranges, and if you cannot be certain of the '
                    'exact text, ask the user one short question instead of guessing.'
                )

    lines.append(
        'EDIT FORMAT — include EXACTLY this block in your answer, wrapped in the '
        '<broccoli-output type="editor_edit"> tag (Broccoli parses the JSON out of the '
        'tag; the rest of your answer is shown normally). A bare JSON object WITHOUT the '
        'tag is ignored, so the tag is required:\n'
        '<broccoli-output type="editor_edit">\n'
        '{"type":"editor_edit","file":"<basename or absolute path from the list>",'
        '"mode":"find_replace","edits":[{"find":"<exact current snippet, unique>","replace":"<new text>"}],'
        '"summary":"<one line, what changes>","understanding":"<one line, why>"}\n'
        '</broccoli-output>\n'
        'Modes: "find_replace" (edits=[{find,replace}], find must match EXACTLY ONCE); '
        '"line_replace" (edits=[{start,end,replace}], 1-based inclusive line ranges); '
        '"full" (new_content=<whole new file>, only for a genuine full rewrite). '
        # FIX-45: summary/understanding are printed verbatim in the edit-approval
        # popup — they must be in the user's primary language, like the diagrams.
        'Write "summary" and "understanding" in %s. '
        'Only edit a file that is open above. If the request is really about brand-new, '
        'standalone content, use a normal deliverable block instead, not editor_edit. '
        'MANDATORY: any change to a file that is open above MUST be delivered as an '
        'editor_edit (download or block) — never as a prose description or a plain '
        'code block; those cannot be applied.' % preferred_ui_language()
    )
    return '\n'.join(str(x) for x in lines if str(x or '').strip()).strip()


# ============================================================
# === TEMP-DIAG(dom-skeleton) BEGIN — 临时诊断,测试后整段注释掉 ===
# Dumps the LAST assistant turn's DOM outline (tags/classes/text sizes + short
# heads for pre/code/a/button) so a wrong web capture can be diagnosed from the
# real structure instead of guesswork. Consumed by the finish handler's pre-step
# (same TEMP marker there); written into the debug snapshot on every web run.
_EXTERNAL_DOM_SKELETON_JS = """
(function() {
    const articles = Array.from(document.querySelectorAll('article, [data-message-author-role]'));
    let node = null;
    for (let i = articles.length - 1; i >= 0; i--) {
        const el = articles[i];
        const turn = String(el.getAttribute('data-turn') || '').toLowerCase();
        const role = String(el.getAttribute('data-message-author-role') || '').toLowerCase();
        if (turn === 'assistant' || role === 'assistant' || (!turn && !role)) { node = el; break; }
    }
    if (!node) return 'no-assistant-node';
    const lines = [];
    Array.from(node.querySelectorAll('.markdown')).forEach((block, idx) => {
        const allPres = Array.from(block.querySelectorAll('pre'));
        const outerPres = allPres.filter((pre) => !(pre.parentElement && pre.parentElement.closest('pre')));
        const broadComposerMatches = Array.from(block.querySelectorAll('[class*="composer"]'))
            .filter((item) => String(item.textContent || '').length > 0);
        lines.push('[capture-probe ' + idx + '] pre-all=' + allPres.length
            + ' pre-outer=' + outerPres.length
            + ' broad-composer-text-nodes=' + broadComposerMatches.length
            + ' live-code-lengths=' + outerPres.map((pre) => {
                const code = pre.querySelector('code');
                return String((code || pre).innerText || (code || pre).textContent || '').length;
            }).join(','));
    });
    const walk = (el, depth) => {
        if (!el || depth > 7 || lines.length > 400) return;
        if (el.nodeType !== Node.ELEMENT_NODE) return;
        const tag = String(el.tagName || '').toLowerCase();
        const cls = String(el.className || '').slice(0, 80);
        const text = String(el.innerText || '');
        let head = '';
        if (tag === 'pre' || tag === 'code' || tag === 'a' || tag === 'button') {
            head = ' :: ' + text.slice(0, 80).replace(/\\n/g, '<NL>');
        }
        lines.push('  '.repeat(depth) + tag + (cls ? '.' + cls : '') + ' [tl=' + text.length + ', kids=' + el.children.length + ']' + head);
        Array.from(el.children).forEach((child) => walk(child, depth + 1));
    };
    walk(node, 0);
    return lines.join('\\n');
})()
"""
# === TEMP-DIAG(dom-skeleton) END ===
# ============================================================

EXTERNAL_MOUNT_DIR = os.path.join(BROCCOLI_APP_DATA_DIR, 'external_mounts')

# Hard cap for a @target-downloaded edit file. An editor_edit JSON is small (even a
# "full"-mode rewrite tops out near the size of the file it replaces), so 32 MB is
# generous. Enforced three times: declared size at accept (disk), received bytes
# mid-transfer (disk), and landed-file size before the ingest read (memory).
EXTERNAL_EDIT_DOWNLOAD_MAX_BYTES = 32 * 1024 * 1024


def editor_external_mount_files(main_window, max_files: int = 4) -> list:
    """LIVE-TEXT snapshots of the editor's edit target (+ other open files, capped)
    written to temp files, for @web/@localhost upload and @terminal path mounting.
    We snapshot the LIVE buffer (not the on-disk file) so unsaved edits send CURRENT
    content — matching the native read tool's live-text contract; a stale disk upload
    would make the target propose an edit that the apply-time drift guard then rejects.
    The snapshot keeps the original basename so the returned editor_edit's `file`
    resolves to the open file. Returns [{name, path, mime, size, origin}]. GUI-thread
    only (reads editor widgets)."""
    editor = _editor_visible_window(main_window)
    if editor is None:
        return []
    try:
        paths, target = editor_open_file_paths(main_window)
    except Exception:
        return []
    ordered = []
    if str(target or '').strip():
        ordered.append(os.path.abspath(str(target)))
    for p in paths or []:
        ap = os.path.abspath(str(p))
        if ap not in ordered:
            ordered.append(ap)
    ordered = ordered[:max(1, int(max_files))]
    if not ordered:
        return []
    try:
        os.makedirs(EXTERNAL_MOUNT_DIR, exist_ok=True)
        cutoff = time.time() - 1800  # prune snapshot subdirs older than 30 min (best effort;
        # long enough that a still-pending upload from an overlapping request won't be reaped)
        for entry in os.listdir(EXTERNAL_MOUNT_DIR):
            full = os.path.join(EXTERNAL_MOUNT_DIR, entry)
            try:
                if os.path.isdir(full) and os.path.getmtime(full) < cutoff:
                    shutil.rmtree(full, ignore_errors=True)
            except Exception:
                pass
        sub = os.path.join(EXTERNAL_MOUNT_DIR, 'snap-%d' % int(time.time() * 1000))
        os.makedirs(sub, exist_ok=True)
    except Exception:
        return []
    out = []
    name_counts = {}
    for origin in ordered:
        try:
            text = str(editor_live_text_for(editor, origin) or '')
        except Exception:
            text = ''
        # Skip 0-byte buffers ONLY: an empty upload creates no attachment chip on most
        # web chat sites, so the presence check would time out and FAIL the whole run.
        # (Whitespace-only buffers are real bytes and upload fine — do not skip them.)
        if not text:
            continue
        base = os.path.basename(origin) or 'file.txt'
        # Same basename from another directory: KEEP the original basename (the
        # returned editor_edit's `file` must resolve to an open file — a renamed
        # <name>_N snapshot would not) and disambiguate with a nested subdir instead.
        count = name_counts.get(base.lower(), 0)
        name_counts[base.lower()] = count + 1
        if count:
            dup_dir = os.path.join(sub, 'dup-%d' % count)
            try:
                os.makedirs(dup_dir, exist_ok=True)
            except Exception:
                continue
            snap_path = os.path.join(dup_dir, base)
        else:
            snap_path = os.path.join(sub, base)
        try:
            with open(snap_path, 'w', encoding='utf-8') as fh:
                fh.write(text)
            size = int(os.path.getsize(snap_path))
        except Exception:
            continue
        out.append({
            'name': base,
            'path': os.path.abspath(snap_path),
            'mime': mimetypes.guess_type(base)[0] or 'text/plain',
            'size': size,
            'origin': origin,
        })
    return out


def editor_reverted_turns_note(main_window):
    editor = _editor_visible_window(main_window)
    if editor is None:
        return ''
    try:
        cid, _turn = main_window._editor_conversation_identity()
    except Exception:
        cid = ''
    cid = str(cid or '').strip()
    if not cid:
        return ''
    turns = set()
    for path in list(getattr(editor.session, 'open_files', []) or []):
        store = EditorStore.for_path(path)
        if store is None:
            continue
        try:
            for version in store.list_versions():
                if not isinstance(version, dict) or not version.get('reverted'):
                    continue
                if str(version.get('conversation_id', '') or '') != cid:
                    continue
                try:
                    turn = int(version.get('turn', -1))
                except Exception:
                    turn = -1
                if turn >= 0:
                    turns.add(turn)
        except Exception:
            continue
    if not turns:
        return ''
    joined = ', '.join(str(t) for t in sorted(turns))
    return (
        'NOTE: your file edits from turn(s) %s of this conversation were REVERTED by the user. '
        'That code is NOT in the current files. Treat those historical messages as record only; '
        'trust the file content provided now.'
    ) % joined


def editor_normalize_editor_edit_record(record):
    if not isinstance(record, dict):
        return None
    out = dict(record)
    out['type'] = 'editor_edit'
    mode = str(out.get('mode', '') or '').strip().lower()
    if mode not in ('full', 'find_replace', 'line_replace'):
        return None
    out['mode'] = mode
    if mode == 'full' and not str(out.get('new_content', '') or '').strip():
        return None
    out['file'] = str(out.get('file', '') or '').strip()
    out['summary'] = str(out.get('summary', '') or '').strip()
    out['understanding'] = str(out.get('understanding', '') or '').strip()
    entries = []
    for item in out.get('entries') or []:
        if not isinstance(item, dict):
            continue
        code_name = str(item.get('code_name', '') or '').strip()
        if not code_name:
            continue
        entries.append({
            'code_name': code_name,
            'category': str(item.get('category', '') or 'Other').strip() or 'Other',
            'natural_name': str(item.get('natural_name', '') or '').strip(),
            'description': str(item.get('description', '') or '').strip(),
        })
    out['entries'] = entries
    fr = out.get('flow_revision')
    if isinstance(fr, str) and fr.strip():
        # Models often double-encode flow_revision as a JSON string — parse it
        # back to an object instead of silently discarding it.
        parsed_fr = parse_json_object_from_text(fr)
        fr = parsed_fr if isinstance(parsed_fr, dict) else None
    if not isinstance(fr, dict):
        fr = None
    out['flow_revision'] = fr
    return out


def _editor_match_context(text, find, max_hits=5, ctx=2):
    """Bounded, actionable feedback when a find string isn't uniquely matched:
    the line numbers of each occurrence with a few lines of context (for >1),
    or the closest anchor for a 0-match. File-size-independent (capped)."""
    lines = str(text or '').split('\n')
    find = str(find or '')
    first = find.split('\n', 1)[0].strip()
    hits = []
    if find and find in text:
        # locate occurrences by the full find's first line
        for i, ln in enumerate(lines):
            if first and first in ln:
                hits.append(i)
    elif first:
        for i, ln in enumerate(lines):
            if first in ln:
                hits.append(i)
    if not hits:
        return ('The find text does not appear in the current file. Use the Outline to pick a line '
                'range and edit with mode "line_replace", or read the exact range from the file path first.')
    out = []
    for idx in hits[:max_hits]:
        lo = max(0, idx - ctx)
        hi = min(len(lines), idx + ctx + 1)
        snippet = '\n'.join('%d: %s' % (j + 1, lines[j]) for j in range(lo, hi))
        out.append(snippet)
    more = '' if len(hits) <= max_hits else '\n(+%d more occurrences)' % (len(hits) - max_hits)
    return 'Current text around the %d candidate location(s):\n%s%s' % (len(hits), '\n---\n'.join(out), more)


def editor_apply_find_replace_record(record, base_text):
    proposed_text = str(base_text or '')
    edits = record.get('edits') if isinstance(record.get('edits'), list) else []
    if not edits:
        return None, 'editor_edit rejected: no find_replace edits provided'
    for item in edits:
        if not isinstance(item, dict):
            return None, 'editor_edit rejected: malformed find_replace edit'
        find = str(item.get('find', '') or '')
        replace = str(item.get('replace', '') or '')
        if not find:
            return None, 'editor_edit rejected: empty find text'
        count = proposed_text.count(find)
        if count != 1:
            noun = 'matched %d times' % count if count else 'was not found'
            return None, (
                'editor_edit rejected: the find text %s (it must match exactly once). '
                '%s\nExtend the find text to be unique, or use mode "line_replace" with a line range.'
                % (noun, _editor_match_context(proposed_text, find))
            )
        proposed_text = proposed_text.replace(find, replace, 1)
    return proposed_text, ''


def editor_apply_line_replace_record(record, base_text):
    """Replace 1-based inclusive line ranges — no exact-substring reproduction,
    so it cannot fail on 'not unique'. Line numbers align with the Outline."""
    lines = str(base_text or '').split('\n')
    n = len(lines)
    edits = record.get('edits') if isinstance(record.get('edits'), list) else []
    if not edits:
        return None, 'editor_edit rejected: no line_replace edits provided'
    norm = []
    for item in edits:
        if not isinstance(item, dict):
            return None, 'editor_edit rejected: malformed line_replace edit'
        try:
            start = int(item.get('start'))
            end = int(item.get('end', item.get('start')))
        except Exception:
            return None, 'editor_edit rejected: line_replace start/end must be integers'
        if start < 1 or end < start or end > n:
            return None, ('editor_edit rejected: line_replace range %s-%s is out of bounds '
                          '(the file has %d lines)' % (item.get('start'), item.get('end'), n))
        norm.append((start, end, str(item.get('replace', '') or '')))
    norm.sort()
    for i in range(1, len(norm)):
        if norm[i][0] <= norm[i - 1][1]:
            return None, 'editor_edit rejected: line_replace ranges overlap'
    for start, end, replace in sorted(norm, reverse=True):
        repl_lines = replace.split('\n') if replace != '' else []
        lines[start - 1:end] = repl_lines
    return '\n'.join(lines), ''


def editor_invalidate_flow_cache(store, flow_id):
    if store is None or not flow_id:
        return
    try:
        cache = store.load_cards_cache()
        if not isinstance(cache, dict):
            return
        fid = str(flow_id or '')
        changed = False
        for key, value in list(cache.items()):
            if isinstance(value, dict) and str(value.get('flow_id', '') or '') == fid:
                cache.pop(key, None)
                changed = True
        if changed:
            store.save_cards_cache(cache)
    except Exception:
        pass


def editor_adopt_flow_revision_for_edit(editor, store, revision, current_flow=None, summary=''):
    if store is None or not isinstance(revision, dict):
        return False
    parsed = editor_parse_flow_json(json.dumps(revision, ensure_ascii=False))
    if parsed is None:
        return False
    if isinstance(current_flow, dict) and str(current_flow.get('id', '') or ''):
        old = copy.deepcopy(current_flow)
        parsed['id'] = old.get('id')
        parsed['created_at'] = old.get('created_at')
        parsed['origin'] = old.get('origin')
        history = list(old.get('history') or [])
        history.append({
            'rev': len(history) + 1,
            'at': _editor_now_iso(),
            'reason': 'editor_edit' + ((': ' + summary[:80]) if summary else ''),
            'nodes': copy.deepcopy(old.get('nodes') or []),
            'edges': copy.deepcopy(old.get('edges') or []),
        })
        parsed['history'] = history
        for node in parsed.get('nodes') or []:
            if isinstance(node, dict) and 'refine_flow' not in node:
                node['refine_flow'] = None
        ok = False
        try:
            ok = bool(editor._save_flow_record(store, parsed))
        except Exception:
            ok = False
        if ok:
            editor_invalidate_flow_cache(store, parsed.get('id'))
        return ok
    try:
        persisted = editor._persist_flow(
            store,
            parsed,
            {'path': store.path},
            origin={'kind': 'editor_edit', 'summary': str(summary or '')[:120]},
        )
        return persisted is not None
    except Exception:
        return False


class EditorEditPermissionPanel(SmoothPanelWidget):
    approved = pyqtSignal(dict)
    rejected = pyqtSignal(str)

    def __init__(self, main_window, proposal, parent=None):
        # Modal DIALOG parented to the main window — the exact mechanism the
        # terminal-command approval dialog (AgentTerminalCommandApprovalDialog)
        # uses to sit ABOVE the main window. A parented Dialog is its own OS
        # window (so it is NOT clipped like a plain child was), and application
        # modality keeps it forward instead of fighting the main window's many
        # raise_() calls (which is why the earlier parent=None + StaysOnTop +
        # NSWindow-level approach kept losing to the main window). Parenting is
        # safe here because — unlike the removed raise_native_level hack — we do
        # NO winId()/native-window ops on it (that was the poison case).
        super().__init__(parent)
        self._main = main_window
        self.proposal = proposal if isinstance(proposal, dict) else {}
        self._alive = True
        self.setObjectName('EditorEditPermissionPanel')
        self.setWindowFlags(
            Qt.WindowType.Dialog |
            Qt.WindowType.FramelessWindowHint
        )
        self.setWindowModality(Qt.WindowModality.ApplicationModal)
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground, True)
        self.setAttribute(Qt.WidgetAttribute.WA_StyledBackground, True)
        self.setMinimumSize(420, 460)   # the approval width (was 620: wider than the main window)

        # FIX-45: the frame speaks the user's PRIMARY language, like the rest of
        # the approval surfaces (the model-written understanding/summary and the
        # diagram nodes are asked for in that language at generation time).
        title = ui_text('editor.title',
                        name=os.path.basename(str(self.proposal.get('path', '') or '')) or 'file')
        self.title_lbl = QLabel(title, self)
        self.title_lbl.setWordWrap(True)
        self.understanding_lbl = QLabel(
            str(self.proposal.get('understanding', '') or ui_text('editor.no_understanding')), self)
        self.understanding_lbl.setWordWrap(True)
        self.summary_lbl = QLabel(self._summary_text(), self)
        self.summary_lbl.setWordWrap(True)
        self.warning_lbl = QLabel(
            ui_text('editor.warn_dirty') if self.proposal.get('dirty') else '',
            self,
        )
        self.warning_lbl.setWordWrap(True)

        self.entries_table = QTableWidget(self)
        self.entries_table.setColumnCount(4)
        self.entries_table.setHorizontalHeaderLabels([
            ui_text('editor.col_mapping'), ui_text('editor.col_code'),
            ui_text('editor.col_natural'), ui_text('editor.col_desc')])
        self.entries_table.verticalHeader().hide()
        self.entries_table.setEditTriggers(QAbstractItemView.EditTrigger.NoEditTriggers)
        self.entries_table.setSelectionMode(QAbstractItemView.SelectionMode.NoSelection)
        self.entries_table.horizontalHeader().setStretchLastSection(True)
        self.entries_table.setShowGrid(False)  # settings-table card look uses row separators, not a grid
        self.entries_table.setFrameShape(QFrame.Shape.NoFrame)
        self.entries_table.setMaximumHeight(126)
        self._populate_entries()

        self.diagram_box = QWidget(self)
        diagram_layout = QHBoxLayout(self.diagram_box)
        diagram_layout.setContentsMargins(0, 0, 0, 0)
        diagram_layout.setSpacing(10)
        self.current_diagram = EditorDiagramView(self.diagram_box)
        self.proposed_diagram = EditorDiagramView(self.diagram_box)
        self.current_diagram.setMinimumHeight(150)
        self.proposed_diagram.setMinimumHeight(150)
        # Two FOCUSED diagrams, generated on show by the model from the code diff:
        # left = current logic around the change; right = after, with added/removed/
        # changed steps colored. Both start on a "generating" placeholder.
        self._current_panel = self._diagram_panel(ui_text('editor.flow_current'), self.current_diagram)
        self._proposed_panel = self._diagram_panel(ui_text('editor.flow_after'), self.proposed_diagram)
        diagram_layout.addWidget(self._current_panel, 1)
        diagram_layout.addWidget(self._proposed_panel, 1)
        self._edit_flow_worker = None
        self._edit_flows_started = False

        self.reason_edit = QLineEdit(self)
        self.reason_edit.setPlaceholderText(ui_text('editor.reason_placeholder'))
        # normal buttons, like the terminal / computer-use approvals (no capsules in approval boxes)
        self.approve_btn = MacNormalButton(ui_text('editor.approve'), self)
        self.reject_btn = MacNormalButton(ui_text('editor.reject'), self)
        self.approve_btn.clicked.connect(lambda: self.approved.emit(dict(self.proposal)))
        self.reject_btn.clicked.connect(lambda: self.rejected.emit(self.reason_edit.text()))
        row = QHBoxLayout()
        row.setContentsMargins(0, 0, 0, 0)
        row.setSpacing(10)
        row.addWidget(self.reason_edit, 1)
        row.addWidget(self.reject_btn)
        row.addWidget(self.approve_btn)

        lay = QVBoxLayout(self)
        lay.setContentsMargins(24, 22, 24, 22)
        lay.setSpacing(12)
        lay.addWidget(self.title_lbl)
        lay.addWidget(self.understanding_lbl)
        lay.addWidget(self.summary_lbl)
        if self.warning_lbl.text().strip():
            lay.addWidget(self.warning_lbl)
        lay.addWidget(self.entries_table)
        lay.addWidget(self.diagram_box, 1)
        lay.addLayout(row)
        self._render_diagrams()
        self.set_theme(False)

    def _summary_text(self):
        changed = self.proposal.get('changed_lines')
        if changed is None:
            changed_text = ui_text('editor.changed_unknown')
        else:
            changed_text = ui_text('editor.changed_rows', count=int(changed or 0))
        summary = str(self.proposal.get('summary', '') or ui_text('editor.default_summary'))
        return summary + ' · ' + changed_text

    def _diagram_panel(self, title, view):
        box = QWidget(self.diagram_box)
        lay = QVBoxLayout(box)
        lay.setContentsMargins(0, 0, 0, 0)
        lay.setSpacing(6)
        # one line with "…" at the approval width (the long "After this edit · added green /
        # removed red / changed yellow" was cut off mid-word); the whole title on hover
        lbl = _ElidingLabel(title, box, tooltip_on_elide=True)
        lbl.setObjectName('editorEditDiagramTitle')
        lay.addWidget(lbl)
        lay.addWidget(view, 1)
        return box

    def _populate_entries(self):
        entries = list(self.proposal.get('entries') or [])
        self.entries_table.setRowCount(max(1, len(entries)))
        if not entries:
            self.entries_table.setItem(0, 0, QTableWidgetItem(ui_text('editor.no_mapping')))
            for col in range(1, 4):
                self.entries_table.setItem(0, col, QTableWidgetItem(''))
            return
        existing = self.proposal.get('existing_entries') if isinstance(self.proposal.get('existing_entries'), dict) else {}
        for row, entry in enumerate(entries):
            code_name = str(entry.get('code_name', '') or '')
            old = existing.get(code_name)
            marker = ui_text('editor.new_mapping')
            if isinstance(old, dict) and str(old.get('status', '') or '') == 'confirmed':
                old_name = str(old.get('natural_name', '') or '')
                new_name = str(entry.get('natural_name', '') or '')
                marker = (ui_text('editor.rename_confirmed')
                          if old_name and new_name and old_name != new_name
                          else ui_text('editor.confirmed_mapping'))
            elif isinstance(old, dict):
                marker = ui_text('editor.confirm_mapping')
            values = [
                marker,
                code_name,
                str(entry.get('natural_name', '') or ''),
                str(entry.get('description', '') or ''),
            ]
            for col, value in enumerate(values):
                self.entries_table.setItem(row, col, QTableWidgetItem(value))
        self.entries_table.resizeColumnsToContents()

    def _render_diagrams(self):
        try:
            self.current_diagram.set_theme(is_dark_theme(app))
            self.proposed_diagram.set_theme(is_dark_theme(app))
        except Exception:
            pass
        self.current_diagram.set_placeholder(ui_text('editor.flow_generating'))
        self.proposed_diagram.set_placeholder(ui_text('editor.flow_generating'))

    def _renderer(self):
        editor = self.proposal.get('editor')
        try:
            if editor is not None and editor.isVisible():
                return editor._mermaid()
        except Exception:
            return None
        return None

    def _render_flow_into(self, view, flow, mark=None):
        if not self._alive or not isinstance(flow, dict):
            return
        renderer = self._renderer()
        if renderer is None:
            view.set_placeholder(ui_text('editor.flow_no_renderer'))
            return
        def cb(pm, _svg, _err, v=view):
            if not self._alive:
                return
            if isinstance(pm, QPixmap) and not pm.isNull():
                v.set_pixmap(pm)
            else:
                v.set_placeholder(ui_text('editor.flow_render_failed'))
        try:
            renderer.render(editor_flow_to_mermaid(flow, mark=mark), cb)
        except Exception:
            view.set_placeholder(ui_text('editor.flow_render_failed'))

    def showEvent(self, event):
        super().showEvent(event)
        if not self._edit_flows_started:
            self._edit_flows_started = True
            QTimer.singleShot(0, self._start_edit_flow_generation)

    def hideEvent(self, event):
        # panel closing: stop the generation so a late callback can't touch a
        # deleted pane
        self._alive = False
        try:
            if self._edit_flow_worker is not None:
                self._edit_flow_worker.stop()
        except Exception:
            pass
        super().hideEvent(event)

    def _start_edit_flow_generation(self):
        if not self._alive:
            return
        current_text = str(self.proposal.get('current_text', '') or '')
        proposed_text = str(self.proposal.get('proposed_text', '') or '')
        if not current_text and not proposed_text:
            self.current_diagram.set_placeholder(ui_text('editor.flow_no_change'))
            self.proposed_diagram.set_placeholder('')
            return
        try:
            store = self.proposal.get('store')
            lang = store.lexicon_language() if store is not None else 'English'
        except Exception:
            lang = 'English'
        before, after = editor_edit_flow_regions(current_text, proposed_text)
        messages = editor_edit_flow_messages(before, after, self.proposal.get('summary', ''), lang)

        def on_finished(text):
            if not self._alive:
                return
            self._edit_flow_worker = None
            parsed = editor_parse_edit_flows(text)
            if not parsed:
                self.current_diagram.set_placeholder(ui_text('editor.flow_gen_failed'))
                self.proposed_diagram.set_placeholder(ui_text('editor.flow_gen_failed'))
                return
            current_flow, revised_flow, mark = parsed
            if isinstance(current_flow, dict):
                self._render_flow_into(self.current_diagram, current_flow, None)
            else:
                self.current_diagram.set_placeholder(_tr('No current flow'))
            if isinstance(revised_flow, dict):
                self._render_flow_into(self.proposed_diagram, revised_flow, mark)
            else:
                self.proposed_diagram.set_placeholder(_tr('No revised flow'))

        def on_failed(msg):
            if not self._alive:
                return
            self._edit_flow_worker = None
            self.current_diagram.set_placeholder(ui_text('editor.flow_gen_failed'))
            self.proposed_diagram.set_placeholder(str(msg or _tr('Generation failed')))

        try:
            self._edit_flow_worker = editor_llm_request(messages, None, on_finished, on_failed)
        except Exception:
            self.current_diagram.set_placeholder(ui_text('editor.flow_gen_failed'))
            self.proposed_diagram.set_placeholder(ui_text('editor.flow_gen_failed'))

    def set_theme(self, dark_mode):
        dark = bool(dark_mode)
        bg = '#2D2D2D' if dark else '#FFFFFF'
        border = '#3A3A3A' if dark else '#ECECEC'
        fg = '#F2F2F7' if dark else '#20242B'
        muted = '#A7AEB8' if dark else '#7A8391'
        warn = '#FFD60A' if dark else '#A15C00'
        # An approval: the approval / edit dialogs' corner (T3, glass 16).
        self.set_smooth_panel_background(bg, '#2D2D2D' if dark else '#ECECEC', APPROVAL_DIALOG_SMOOTH_RADIUS)
        self.setStyleSheet(
            'QWidget#EditorEditPermissionPanel { border: none; background: transparent; }'
            ' QLabel { color: %s; font-family: "Helvetica Neue", Helvetica, Arial, sans-serif; }'
            ' QLabel#editorEditDiagramTitle { color: %s; font-size: 11px; font-weight: 600; }'
            % (fg, muted)
        )
        # the plain input style of Settings (its search box included) and the prompts: a 1 pt
        # grey border, corner 6 — this one had an almost invisible border and corner 8
        self.reason_edit.setStyleSheet(_settings_lineedit_stylesheet(dark))
        self.reason_edit.setFixedHeight(self.approve_btn.height())   # level with Reject / Approve (22)
        # Entries table reuses the app's ready-made settings-table card look.
        try:
            self.entries_table.setStyleSheet(_settings_table_stylesheet(dark))
        except Exception:
            pass
        self.title_lbl.setStyleSheet('font-size: 18px; font-weight: 700; color: %s;' % fg)
        self.understanding_lbl.setStyleSheet('font-size: 12px; color: %s;' % fg)
        self.summary_lbl.setStyleSheet('font-size: 12px; color: %s;' % muted)
        self.warning_lbl.setStyleSheet('font-size: 12px; color: %s; font-weight: 600;' % warn)
        # normal buttons (their own grey look, 22 high) like the other approval dialogs
        for btn in (self.approve_btn, self.reject_btn):
            btn.setMinimumWidth(96)
            btn.setCursor(Qt.CursorShape.PointingHandCursor)
            try:
                btn.update_theme()
            except Exception:
                pass


BROCCOLI_DOCK_GOLDEN = 1.618
BROCCOLI_DOCK_GAP = 16
# 2026-10-26 (Ryan): a docked window whose width gives way stops this far short of the screen
# edge (never flush against it: too cramped)
BROCCOLI_DOCK_SCREEN_MARGIN = 60
# measured content minimum of the editor (layout min 554x443) — shared by the
# reader so the two companion windows always dock to the SAME size
BROCCOLI_DOCK_MIN_W = 560
BROCCOLI_DOCK_MIN_H = 460


def _broccoli_main_body_rect(main_window) -> QRect:
    """The main window's own panel on screen, without the blue strip above it (the pin
    row): what a docked Editor / Reader lines up with."""
    try:
        panel = getattr(main_window, 'qw3', None)
        if isinstance(panel, QWidget) and panel.height() > 0:
            return QRect(panel.mapToGlobal(QPoint(0, 0)), panel.size())
    except Exception:
        pass
    try:
        return QRect(main_window.frameGeometry())
    except Exception:
        return QRect(100, 100, 800, 600)


def broccoli_companion_dock_rect(window, main_window, avoid_rect=None):
    """Docked geometry shared by the Editor and the Reader (2026-10-26, Ryan): as tall as the
    main window's own panel — the blue strip above it not counted — and level with it, left or
    right of it with a gap that clears the tag column beside the main window. The preferred
    width is a landscape golden one (height * 1.618); when the screen has less room the width
    gives way, never the height (it used to scale the height down with the ratio), and stops
    60 pt short of the screen edge (the minimum width may go into that margin on a small screen). Left first,
    else right; with avoid_rect (the VISIBLE sibling companion's frame — the Editor and the
    Reader must not bury each other) the other side is tried first, then beside the sibling,
    else a visible 48 px cascade. Only when the screen is too narrow for the minimum width is
    the main window pushed aside. Returns (target_rect, main_slide_rect_or_None); the caller
    animates. Never resizes below the window's own minimum."""
    try:
        mg = QRect(main_window.frameGeometry())
    except Exception:
        mg = QRect(100, 100, 800, 600)
    scr = None
    try:
        scr = main_window.screen()
    except Exception:
        scr = None
    if scr is None:
        try:
            scr = window.screen()
        except Exception:
            scr = None
    if scr is None:
        scr = QGuiApplication.primaryScreen()
    avail = scr.availableGeometry()

    # 2026-10-26 (Ryan): as tall as the main window's own panel (the blue strip above it not
    # counted) and level with it; the height stays, only the width gives way. Left or right of
    # it, far enough that the tag column beside the main window (48 wide) never covers it.
    body = _broccoli_main_body_rect(main_window)
    gap = BROCCOLI_DOCK_GAP + int(getattr(AgentConversationBadge, 'COLLAPSED_W', 48))
    h = max(window.minimumHeight(), min(body.height(), avail.height()))
    margin = BROCCOLI_DOCK_SCREEN_MARGIN
    want_w = max(window.minimumWidth(), min(int(round(h * BROCCOLI_DOCK_GOLDEN)), avail.width() - 2 * margin))
    y = min(max(avail.top(), body.top()), avail.bottom() + 1 - h)
    # room on each side up to 60 pt short of the screen edge, never more than the screen
    # (a main window partly off it)
    room = {'left': min(avail.width() - 2 * margin, body.left() - gap - (avail.left() + margin)),
            'right': min(avail.width() - 2 * margin, (avail.right() + 1 - margin) - (body.right() + 1) - gap)}
    # without the margin: only to still fit the minimum width on a small screen
    room_flush = {'left': body.left() - gap - avail.left(), 'right': avail.right() + 1 - (body.right() + 1) - gap}

    def place(side, width):
        x = body.left() - gap - width if side == 'left' else body.right() + 1 + gap
        x = max(avail.left(), min(x, avail.right() + 1 - width))   # on the screen
        return QRect(int(x), int(y), int(width), int(h))

    order = ['left', 'right']
    if avoid_rect is not None and avoid_rect.isValid():
        # the sibling companion's side goes last: the other side first
        taken = 'left' if avoid_rect.center().x() < body.center().x() else 'right'
        order = [side for side in order if side != taken] + [taken]
    main_target = None
    target = None
    for side in order:                       # a side where the whole width fits
        if room[side] >= want_w:
            target = place(side, want_w)
            break
    if target is None:                       # else the roomier side, narrower (the height stays)
        side = max(order, key=lambda k: room[k])
        if room[side] >= window.minimumWidth():
            target = place(side, room[side])
    if target is None:                       # a small screen: the minimum width, into the margin
        for side in sorted(order, key=lambda k: -room_flush[k]):
            if room_flush[side] >= window.minimumWidth():
                target = place(side, window.minimumWidth())
                break
    if target is None:
        # the screen is too narrow even for the minimum width: pin the companion left and
        # push the main window right (as before), keeping its right edge on the screen
        w = window.minimumWidth()
        new_main_left = avail.left() + w + gap
        if new_main_left + mg.width() > avail.right() + 1:
            new_main_left = avail.right() + 1 - mg.width()
        main_target = QRect(new_main_left, mg.top(), mg.width(), mg.height())
        target = QRect(int(avail.left()), int(y), int(w), int(h))
    if avoid_rect is not None and avoid_rect.isValid() and target.intersects(avoid_rect):
        beside = avoid_rect.left() - BROCCOLI_DOCK_GAP - target.width()
        if beside >= avail.left():
            target.moveLeft(int(beside))
        else:
            # no room for both: cascade 48 px (toward wherever the screen has room) so an
            # edge of each stays visible, still on the screen; one that fills the screen's
            # width gives way 48 px of it for that
            w = target.width()
            if w + 48 > avail.width():
                w = max(window.minimumWidth(), avail.width() - 48)
            x = target.left() + 48 if target.left() + 48 + w <= avail.right() + 1 else target.left() - 48
            y = target.top() + 48 if target.bottom() + 48 <= avail.bottom() else target.top() - 48
            target = QRect(int(max(avail.left(), min(x, avail.right() + 1 - w))),
                           int(max(avail.top(), min(y, avail.bottom() + 1 - target.height()))),
                           int(w), int(target.height()))
    x, y, w, h = target.x(), target.y(), target.width(), target.height()
    return QRect(int(x), int(y), int(w), int(h)), main_target


class EditorWindow(QWidget):
    """Companion editor window docked left of the main window. Top-level (parent=None)."""

    def __init__(self, main_window):
        super().__init__(None)  # NEVER parent to the main window (contract 0.5)
        self._main = main_window
        self.radius = 36
        self.drag_pos = None
        self._resize_active = False
        self._resize_origin = None
        self._resize_start_geo = None
        self._open_anim = None
        self._close_anim = None
        self._dock_anim = None
        self._main_move_anim = None
        self.card_dock = None  # real dock assigned in _build_ui (M4)
        self._mermaid_renderer = None
        try:
            self._dark_mode = bool(is_dark_theme(QApplication.instance()))
        except Exception:
            self._dark_mode = False
        # ---- FIX-3 round: conversation-bound file sets ----
        self._bound_cid = None          # conversation this window currently mirrors
        self._unsaved_binding = None    # in-memory set for the unsaved ('' cid) conversation
        self._binding_syncing = False   # reentrancy guard while swapping sets
        self._cid_cache = ('', '')      # (_active_conversation_path, resolved cid)
        # ---- M2 ----
        self._dock_target_rect = None  # last docked rest rect (snap-back after canceled close)
        self._disk_mtimes = {}         # path -> last seen disk mtime (stale detection)
        self._stale_timer = QTimer(self)
        self._stale_timer.setInterval(2000)
        self._stale_timer.timeout.connect(self._check_disk_changes)
        try:
            self._editor_always_on_top = bool(
                load_settings_store().get('globals', {}).get('editor_always_on_top', True))
        except Exception:
            self._editor_always_on_top = True
        self.setWindowFlags(self._editor_window_flags())
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground)
        self.setAttribute(Qt.WidgetAttribute.WA_NoSystemBackground)
        # FIX-42: min width lowered so the golden-ratio dock width (height/1.618)
        # is actually reachable — 720 forced the window wide on every screen.
        # 560x460 is the measured content minimum (layout min 554x443) and is
        # shared with the Reader so both windows always dock to the same size.
        self.setMinimumSize(BROCCOLI_DOCK_MIN_W, BROCCOLI_DOCK_MIN_H)
        self.resize(920, 570)   # landscape golden default
        self.setWindowTitle(_tr('Broccoli Editor'))
        self.setMouseTracking(True)
        self.session = EditorSession(self)
        self._build_ui()
        self._wire_session()
        _EDITOR_KIND_CHANGE_CALLBACKS.append(self._on_async_file_kind_classified)

    def _build_ui(self):
        self.close_button = MacWindowButton('#FF605C', 'x', self)
        self.close_button.move(10, 10)
        self.close_button.clicked.connect(self.animate_close)

        self.nav = PillNavBar([_tr('Editor'), _tr('Logic Map'), _tr('Debug'), _tr('Snapshots'), _tr('Compare')])
        self.file_bar = EditorFileBar(self)
        self.action_bar = EditorActionBar(self)
        self.editor_page = EditorPage(self)
        self.lexicon_page = EditorLexiconPage(self)
        self.debug_page = EditorDebugPage(self)         # FIX-38
        self.snapshot_page = EditorSnapshotPage(self)   # M3
        self.diff_page = EditorDiffPage(self)           # M3
        self.pages = QStackedWidget()
        self.pages.addWidget(self.editor_page)    # 0 Editor
        self.pages.addWidget(self.lexicon_page)   # 1 Logic Map
        self.pages.addWidget(self.debug_page)     # 2 Debug (FIX-38)
        self.pages.addWidget(self.snapshot_page)  # 3 Snapshots
        self.pages.addWidget(self.diff_page)      # 4 Compare
        self.nav.tab_changed.connect(self.pages.setCurrentIndex)
        # ---- M4: floating card dock overlays the pages area (child of the
        # container, sized to its own rect — never a top-level window) ----
        self.card_dock = EditorCardDock(self, self.pages)

        root = QVBoxLayout(self)
        root.setContentsMargins(18, 40, 18, 14)
        root.setSpacing(10)
        root.addWidget(self.nav)
        root.addWidget(self.file_bar)
        root.addWidget(self.pages, 1)
        root.addWidget(self.action_bar)
        self.close_button.raise_()

    def _wire_session(self):
        self.session.files_changed.connect(self._refresh_file_bar)
        self.session.file_selected.connect(self._on_file_selected)
        self.file_bar.file_selected.connect(self.session.select_file)
        self.file_bar.file_close_requested.connect(self.session.remove_file)
        self.file_bar.files_add_requested.connect(self._add_files)
        # ---- M3: snapshots + compare ----
        self.file_bar.compare_requested.connect(self._on_compare_requested)
        # ---- FIX-3 round: user-designated modification target ----
        self.file_bar.edit_target_requested.connect(self._on_edit_target_requested)
        self.nav.tab_changed.connect(self._on_tab_changed)
        self.session.files_changed.connect(self.snapshot_page.refresh_lists)
        self.session.file_selected.connect(self.snapshot_page.on_session_file_selected)
        # ---- M4: explain cards ----
        self.editor_page.card_request.connect(self._on_card_request)
        # ---- FIX-38: debug tab follows the current file ----
        self.session.file_selected.connect(self.debug_page.on_session_file_selected)
        self.session.files_changed.connect(self.debug_page.refresh_lists)
        # ---- M6: live logic-map parsing ----
        self.session.file_selected.connect(self.lexicon_page.request_parse)
        self.session.file_selected.connect(lambda _p: self.lexicon_page.refresh_table())
        self.session.file_content_reloaded.connect(self.lexicon_page.request_parse)
        self.editor_page.editor.textChanged.connect(self.lexicon_page.schedule_parse)
        self.action_bar.reparse_requested.connect(lambda: self.lexicon_page.request_parse(self.session.current_path))
        self.action_bar.reparse_btn.setEnabled(True)
        # ---- FIX-3 round: keep the active conversation's binding fresh ----
        self.session.files_changed.connect(self._record_conversation_binding)
        # ---- M2: save + state pruning ----
        self.session.files_changed.connect(self._prune_page_state)
        self.action_bar.save_requested.connect(self._on_save_requested)
        self.action_bar.save_btn.setEnabled(False)
        self._save_shortcut = QShortcut(QKeySequence(QKeySequence.StandardKey.Save), self)
        self._save_shortcut.activated.connect(self._on_save_requested)

    def _refresh_file_bar(self):
        self.file_bar.set_edit_target(self.session.edit_target)
        self.file_bar.set_files(self.session.open_files, self.session.current_path)

    def _on_edit_target_requested(self, path):
        # pill menu toggles: same file again → unset
        self.session.set_edit_target(None if self.session.edit_target == path else path)

    def _on_file_selected(self, path):
        self.editor_page.load_path(path or None)
        self._refresh_file_bar()

    def _add_files(self, paths):
        first_new = None
        for p in paths or []:
            try:
                ap = os.path.abspath(str(p))
            except Exception:
                continue
            already = ap in self.session.open_files
            if self.session.add_file(ap) and not already and first_new is None:
                first_new = ap
        if first_new:
            self.session.select_file(first_new)

    def set_file_kind_override(self, override):
        path = self.session.current_path
        store = self.session.store(path) if path else None
        if store is None:
            return
        editor_set_kind_override(store, override)
        try:
            lex = store.load_lexicon()
            if not isinstance(lex, dict):
                lex = store._lexicon_skeleton()
            skeleton = store._lexicon_skeleton()
            lex['kind'] = skeleton.get('kind')
            lex['categories'] = skeleton.get('categories')
            store.save_lexicon(lex)
        except Exception:
            pass
        try:
            self.lexicon_page._parsed_once.discard(path)
            self.lexicon_page.request_parse(path)
            self.lexicon_page.refresh_table()
        except Exception:
            pass

    def _on_async_file_kind_classified(self, path, kind):
        if path not in list(self.session.open_files):
            return
        store = self.session.store(path)
        if store is None:
            return
        try:
            lex = store.load_lexicon()
            skeleton = store._lexicon_skeleton()
            if isinstance(lex, dict):
                lex['kind'] = skeleton.get('kind')
                lex['categories'] = skeleton.get('categories')
                store.save_lexicon(lex)
        except Exception:
            pass
        try:
            self.lexicon_page._parsed_once.discard(path)
            self.lexicon_page.request_parse(path)
            if path == self.session.current_path:
                self.lexicon_page.refresh_table()
        except Exception:
            pass

    # ---- M3: snapshots / compare plumbing ----
    def _on_compare_requested(self, path):
        try:
            self.snapshot_page.set_compare_slot(('current', path))
        except Exception:
            pass

    def _on_tab_changed(self, index):
        if index == 3:
            # snapshots refresh lazily on entry (never per keystroke)
            # (FIX-38: Snapshots moved 2→3 — Debug now sits at index 2)
            try:
                self.snapshot_page.refresh_lists()
            except Exception:
                pass
        if index == 2:
            # ---- FIX-38: Debug tab entry — refresh + one-time initial scan ----
            try:
                self.debug_page.refresh_lists()
                self.debug_page.maybe_first_scan()
            except Exception:
                pass
        if index == 1:
            try:
                path = self.session.current_path
                self.lexicon_page.refresh_table()
                # Re-parse on entry if never parsed OR the file is flagged stale
                # (external change), so clicking over to Logic Map recovers.
                if path and (path not in self.lexicon_page._parsed_once
                             or self.file_bar.is_stale(path)):
                    self.lexicon_page.request_parse(path)
            except Exception:
                pass
        # ---- M4: dock slides away over Debug/Snapshots/Compare (they own their
        # right side), returns on Editor/Logic Map ----
        if self.card_dock is not None:
            try:
                if index in (2, 3, 4):
                    self.card_dock.suppress_for_tab()
                else:
                    self.card_dock.restore_after_tab()
            except Exception:
                pass

    # ---- M4/M5: explain + flow cards (cache check + LLM/render into the dock) ----
    def _on_card_request(self, kind, payload):
        if self.card_dock is None:
            return
        kind = str(kind or '')
        payload = dict(payload) if isinstance(payload, dict) else {}
        if kind == 'flow':
            self._open_flow_card(payload)
            return
        if kind in ('object', 'function'):
            self._open_entry_diagram_card(kind, payload)
            return
        if kind != 'explain':
            self.card_dock.open_card(kind, kind.capitalize() or 'Card', payload,
                                    display_title=kind.capitalize() or _tr('Card'))
            return
        path = str(payload.get('path', '') or '') or (self.session.current_path or '')
        store = self.session.store(path) if path else None
        try:
            lang = store.lexicon_language() if store is not None else 'English'
        except Exception:
            lang = 'English'
        try:
            ls = int(payload.get('line_start', 0) or 0)
            le = int(payload.get('line_end', 0) or 0)
        except Exception:
            ls = le = 0
        line_part = ('L%d' % ls) if ls == le else ('L%d–%d' % (ls, le))
        title = 'Explain · %s · %s' % (os.path.basename(path) or 'untitled', line_part)
        display_title = _tr('Explain · %s · %s') % (os.path.basename(path) or _tr('untitled'), line_part)
        card = self.card_dock.open_card('explain', title, payload, display_title=display_title)
        card.regenerate_requested.connect(
            lambda c=card: self._start_explain_stream(c))
        cached_text = ''
        if store is not None:
            try:
                key = self._explain_cache_key(payload.get('text', ''), lang)
                entry = (store.load_cards_cache() or {}).get(key)
                if isinstance(entry, dict):
                    cached_text = str(entry.get('text', '') or '')
            except Exception:
                cached_text = ''
        if cached_text:
            # instant fill — no LLM call; 'Regenerate' appears in the card menu
            card.finish(cached_text)
            card.mark_cached(True)
        else:
            self._start_explain_stream(card)

    def _editor_cards_cache_key(self, kind, text, lang):
        raw = str(kind or '') + '\n' + str(text or '') + '\n' + str(lang or '')
        return hashlib.sha1(raw.encode('utf-8', 'replace')).hexdigest()[:16]

    def _explain_cache_key(self, text, lang):
        return self._editor_cards_cache_key('explain', text, lang)

    def _line_title_part(self, payload):
        try:
            ls = int(payload.get('line_start', 0) or 0)
            le = int(payload.get('line_end', 0) or 0)
        except Exception:
            ls = le = 0
        return ('L%d' % ls) if ls == le else ('L%d–%d' % (ls, le))

    def _mermaid(self):
        if self._mermaid_renderer is None:
            self._mermaid_renderer = EditorMermaidRenderer(self)
        return self._mermaid_renderer

    def _find_flow(self, store, flow_id):
        if store is None or not flow_id:
            return None
        try:
            flows = store.load_flows()
            for f in flows.get('flows', []) if isinstance(flows, dict) else []:
                if isinstance(f, dict) and str(f.get('id', '') or '') == str(flow_id):
                    return f
        except Exception:
            return None
        return None

    def _find_flow_by_origin(self, store, kind, entry_id=None, parent_flow=None, parent_node=None):
        if store is None:
            return None
        try:
            flows = store.load_flows()
            for f in flows.get('flows', []) if isinstance(flows, dict) else []:
                if not isinstance(f, dict):
                    continue
                origin = f.get('origin') if isinstance(f.get('origin'), dict) else {}
                if str(origin.get('kind', '') or '') != str(kind or ''):
                    continue
                if entry_id is not None and str(origin.get('entry_id', '') or '') != str(entry_id or ''):
                    continue
                if parent_flow is not None and str(origin.get('parent_flow', '') or '') != str(parent_flow or ''):
                    continue
                if parent_node is not None and str(origin.get('parent_node', '') or '') != str(parent_node or ''):
                    continue
                return f
        except Exception:
            return None
        return None

    def _open_entry_diagram_card(self, kind, payload):
        path = str(payload.get('path', '') or '') or (self.session.current_path or '')
        store = self.session.store(path) if path else None
        entry_id = str(payload.get('entry_id', '') or '')
        entry = editor_find_entry(store, entry_id)
        title_name = str((entry or {}).get('natural_name', '') or (entry or {}).get('code_name', '') or kind.capitalize())
        title = ('Object · ' if kind == 'object' else 'Function · ') + title_name
        display_title = (_tr('Object · {name}') if kind == 'object' else _tr('Function · {name}')).format(name=title_name)
        card = self.card_dock.open_card(kind, title, {'entry_id': entry_id, 'path': path}, display_title=display_title)
        if store is None or entry is None:
            card.set_error(_tr('Lexicon entry is not available.'))
            return
        try:
            lang = store.lexicon_language()
        except Exception:
            lang = 'English'
        key = self._editor_cards_cache_key(kind, entry_id, lang)
        flow = self._find_flow_by_origin(store, kind, entry_id=entry_id)
        if flow is None:
            try:
                cache_entry = (store.load_cards_cache() or {}).get(key)
                if isinstance(cache_entry, dict):
                    flow = self._find_flow(store, str(cache_entry.get('flow_id', '') or ''))
            except Exception:
                flow = None
        if flow is not None:
            self._render_flow_card(card, flow, from_cache=True)
            return
        self._start_entry_diagram_generation(card, store, entry, kind, lang, key)

    def _start_entry_diagram_generation(self, card, store, entry, kind, lang, cache_key, retry=False, previous_text=''):
        if card is None or not getattr(card, '_alive', False):
            return
        if not retry:
            card.reset_to_loading()
        messages = editor_flow_from_entry_messages(store, entry, kind, lang)
        if retry:
            messages = list(messages)
            messages.append({'role': 'user', 'content': 'Return ONLY the JSON object, nothing else.'})
        acc = []

        def on_delta(piece):
            acc.append(str(piece or ''))

        def on_finished(text, c=card, s=store, e=entry, k=kind, ck=cache_key, was_retry=retry):
            if getattr(c, '_alive', False):
                c.worker = None
            raw = str(text or ''.join(acc) or '')
            flow = editor_parse_flow_json(raw)
            if flow is None and not was_retry:
                self._start_entry_diagram_generation(c, s, e, k, lang, ck, retry=True, previous_text=raw)
                return
            if flow is None:
                if getattr(c, '_alive', False):
                    c.set_error(_tr('Model did not return a valid flow. Raw answer below.'))
                    c.show_debug_text(raw or previous_text)
                return
            persisted = self._persist_flow(s, flow, c.payload, origin={'kind': k, 'entry_id': str(e.get('id', '') or '')})
            if persisted is None:
                if getattr(c, '_alive', False):
                    c.set_error(_tr('Could not save the diagram.'))
                return
            try:
                cache = s.load_cards_cache()
                if not isinstance(cache, dict):
                    cache = {}
                cache[ck] = {'kind': k, 'flow_id': persisted.get('id', ''), 'at': _editor_now_iso()}
                s.save_cards_cache(cache)
            except Exception:
                pass
            self._render_flow_card(c, persisted, from_cache=False)

        def on_failed(message, c=card):
            if getattr(c, '_alive', False):
                c.worker = None
                c.set_error(message)

        card.worker = editor_llm_request(messages, on_delta, on_finished, on_failed)

    def _open_flow_card(self, payload):
        path = str(payload.get('path', '') or '') or (self.session.current_path or '')
        store = self.session.store(path) if path else None
        try:
            lang = store.lexicon_language() if store is not None else 'English'
        except Exception:
            lang = 'English'
        title = 'Flow · %s · %s' % (
            os.path.basename(path) or 'untitled',
            self._line_title_part(payload),
        )
        display_title = _tr('Flow · %s · %s') % (
            os.path.basename(path) or _tr('untitled'),
            self._line_title_part(payload),
        )
        card = self.card_dock.open_card('flow', title, payload, display_title=display_title)
        if store is None:
            card.set_error(_tr('No editor store is available for this file.'))
            return
        key = self._editor_cards_cache_key('flow', payload.get('text', ''), lang)
        flow = None
        try:
            entry = (store.load_cards_cache() or {}).get(key)
            if isinstance(entry, dict):
                flow = self._find_flow(store, str(entry.get('flow_id', '') or ''))
        except Exception:
            flow = None
        if flow is not None:
            self._render_flow_card(card, flow, from_cache=True)
            return
        self._start_flow_generation(card, store, lang, key, retry=False)

    def _start_flow_generation(self, card, store, lang, cache_key, retry=False, previous_text=''):
        if card is None or not getattr(card, '_alive', False):
            return
        payload = card.payload if isinstance(card.payload, dict) else {}
        old = getattr(card, 'worker', None)
        if old is not None:
            try:
                old.stop()
            except Exception:
                pass
        if not retry:
            card.reset_to_loading()
        messages = editor_flow_messages(store, payload, lang)
        if retry:
            messages = list(messages)
            messages.append({
                'role': 'user',
                'content': 'Return ONLY the JSON object, nothing else.',
            })
        acc = []

        def on_delta(piece):
            acc.append(str(piece or ''))

        def on_finished(text, c=card, s=store, k=cache_key, was_retry=retry):
            if getattr(c, '_alive', False):
                c.worker = None
            raw = str(text or ''.join(acc) or '')
            flow = editor_parse_flow_json(raw)
            if flow is None and not was_retry:
                self._start_flow_generation(c, s, lang, k, retry=True, previous_text=raw)
                return
            if flow is None:
                if getattr(c, '_alive', False):
                    c.set_error(_tr('Model did not return a valid flow. Raw answer below.'))
                    c.show_debug_text(raw or previous_text)
                return
            persisted = self._persist_flow(s, flow, c.payload)
            if persisted is None:
                if getattr(c, '_alive', False):
                    c.set_error(_tr('Could not save the flow.'))
                return
            try:
                cache = s.load_cards_cache()
                if not isinstance(cache, dict):
                    cache = {}
                cache[k] = {
                    'kind': 'flow',
                    'flow_id': str(persisted.get('id', '') or ''),
                    'at': datetime.datetime.now().isoformat(timespec='seconds'),
                }
                s.save_cards_cache(cache)
            except Exception:
                pass
            self._render_flow_card(c, persisted, from_cache=False)

        def on_failed(message, c=card):
            if getattr(c, '_alive', False):
                c.worker = None
                c.set_error(message)

        card.worker = editor_llm_request(messages, on_delta, on_finished, on_failed)

    def _persist_flow(self, store, flow, payload, origin=None):
        try:
            flows = store.load_flows()
            if not isinstance(flows, dict):
                flows = {'flows': []}
            arr = flows.get('flows')
            if not isinstance(arr, list):
                arr = []
                flows['flows'] = arr
            max_n = 0
            for f in arr:
                if isinstance(f, dict):
                    m = re.match(r'^f(\d+)$', str(f.get('id', '') or ''))
                    if m:
                        max_n = max(max_n, int(m.group(1)))
            fid = 'f%03d' % (max_n + 1)
            nodes = copy.deepcopy(flow.get('nodes') or [])
            for n in nodes:
                if isinstance(n, dict):
                    n['refine_flow'] = None
            edges = copy.deepcopy(flow.get('edges') or [])
            try:
                ls = int(payload.get('line_start', 0) or 0)
                le = int(payload.get('line_end', 0) or 0)
            except Exception:
                ls = le = 0
            if not isinstance(origin, dict):
                origin = {'kind': 'explain_flow', 'lines': [ls, le]}
            now = datetime.datetime.now().isoformat(timespec='seconds')
            record = {
                'id': fid,
                'title': str(flow.get('title', '') or 'Flow'),
                'created_at': now,
                'nodes': nodes,
                'edges': edges,
                'history': [{
                    'rev': 1,
                    'at': now,
                    'reason': 'initial',
                    'nodes': copy.deepcopy(nodes),
                    'edges': copy.deepcopy(edges),
                }],
                'origin': dict(origin),
            }
            arr.append(record)
            store.save_flows(flows)
            return record
        except Exception:
            return None

    def _render_flow_card(self, card, flow, from_cache=False, mark=None):
        if card is None or not getattr(card, '_alive', False):
            return
        if isinstance(card.payload, dict):
            card.payload['flow'] = flow
        diagram = 'flowchart'
        try:
            store = self._store_for_card(card)
            nodes = flow.get('nodes') if isinstance(flow, dict) and isinstance(flow.get('nodes'), list) else []
            edges = flow.get('edges') if isinstance(flow, dict) and isinstance(flow.get('edges'), list) else []
            if store is not None and store.file_kind() == 'text-article' and _editor_flow_is_tree(nodes, edges):
                diagram = 'mindmap'
        except Exception:
            diagram = 'flowchart'
        mermaid_code = editor_flow_to_mermaid(flow, mark=mark, diagram=diagram)

        def rendered(pixmap, svg_text, err, c=card, f=flow, code=mermaid_code, d=diagram):
            if not getattr(c, '_alive', False):
                return
            if err and d == 'mindmap':
                fallback_code = editor_flow_to_mermaid(f, mark=mark, diagram='flowchart')

                def fallback_rendered(pm, svg, fallback_err, cc=c, ff=f, fc=fallback_code):
                    if not getattr(cc, '_alive', False):
                        return
                    if fallback_err:
                        cc.set_error(fallback_err)
                        cc.show_debug_text(fc)
                        return
                    cc.show_diagram(pm, svg, str(ff.get('id', '') or ''))
                    cc.mark_cached(bool(from_cache))

                self._mermaid().render(fallback_code, fallback_rendered)
                return
            if err:
                c.set_error(err)
                c.show_debug_text(code)
                return
            c.show_diagram(pixmap, svg_text, str(f.get('id', '') or ''))
            c.mark_cached(bool(from_cache))

        try:
            self._mermaid().render(mermaid_code, rendered)
        except Exception as exc:
            card.set_error(_tr('Mermaid render failed: %s') % exc)
            card.show_debug_text(mermaid_code)

    def _store_for_card(self, card):
        payload = card.payload if card is not None and isinstance(card.payload, dict) else {}
        path = str(payload.get('path', '') or '') or self.session.current_path
        return self.session.store(path) if path else None

    def _save_flow_record(self, store, flow):
        if store is None or not isinstance(flow, dict):
            return False
        fid = str(flow.get('id', '') or '')
        try:
            data = store.load_flows()
            arr = data.get('flows') if isinstance(data, dict) else []
            if not isinstance(arr, list):
                arr = []
                data['flows'] = arr
            for i, f in enumerate(arr):
                if isinstance(f, dict) and str(f.get('id', '') or '') == fid:
                    arr[i] = flow
                    store.save_flows(data)
                    return True
        except Exception:
            return False
        return False

    def jump_editor_to_line(self, line):
        try:
            line = max(1, int(line))
        except Exception:
            return
        try:
            self.nav.select(0)
        except Exception:
            pass
        doc = self.editor_page.editor.document()
        block = doc.findBlockByNumber(line - 1)
        if not block.isValid():
            return
        cursor = QTextCursor(block)
        self.editor_page.editor.setTextCursor(cursor)
        self.editor_page.editor.centerCursor()
        self.editor_page.editor.setFocus()

    def focus_lexicon_entry(self, entry_id):
        entry_id = str(entry_id or '').strip()
        if not entry_id:
            return
        try:
            self.nav.select(1)
        except Exception:
            pass
        try:
            self.pages.setCurrentIndex(1)
        except Exception:
            pass
        try:
            self.lexicon_page.refresh_table()
            self.lexicon_page.focus_entry(entry_id)
        except Exception:
            pass

    def jump_to_flow_node(self, card, node=None):
        if node is None and isinstance(card, dict):
            node = card
        node = node if isinstance(node, dict) else {}
        cref = node.get('code_ref') if isinstance(node.get('code_ref'), dict) else {}
        lines = cref.get('lines') if isinstance(cref.get('lines'), list) else []
        try:
            self.jump_editor_to_line(int(lines[0]))
        except Exception:
            pass

    def open_refined_flow_card(self, card, node_id):
        store = self._store_for_card(card)
        flow = card.payload.get('flow') if isinstance(card.payload, dict) else None
        node = card._node_by_id(node_id) if card is not None else None
        child_id = str((node or {}).get('refine_flow', '') or '')
        child = self._find_flow(store, child_id)
        if child is None:
            return
        title = 'Detail · ' + str((node or {}).get('desc', '') or '')[:24]
        display_title = _tr('Detail · {desc}').format(desc=str((node or {}).get('desc', '') or '')[:24])
        new_card = self.card_dock.open_card('flow', title, {'path': (card.payload or {}).get('path'), 'flow': child},
                                            display_title=display_title)
        self._render_flow_card(new_card, child, from_cache=True)

    def refine_flow_node(self, card, node_id):
        store = self._store_for_card(card)
        parent = card.payload.get('flow') if isinstance(card.payload, dict) else None
        node = card._node_by_id(node_id) if card is not None else None
        if store is None or not isinstance(parent, dict) or not isinstance(node, dict):
            return
        try:
            lang = store.lexicon_language()
        except Exception:
            lang = 'English'
        messages = editor_refine_messages(store, parent, node, lang)
        detail_title = 'Detail · ' + str(node.get('desc', '') or '')[:24]
        detail_display = _tr('Detail · {desc}').format(desc=str(node.get('desc', '') or '')[:24])
        detail_card = self.card_dock.open_card('flow', detail_title, {'path': (card.payload or {}).get('path')},
                                               display_title=detail_display)
        acc = []

        def on_delta(piece):
            acc.append(str(piece or ''))

        def on_finished(text, c=detail_card, s=store, p=parent, n=node):
            if getattr(c, '_alive', False):
                c.worker = None
            flow = editor_parse_flow_json(str(text or ''.join(acc) or ''))
            if flow is None:
                if getattr(c, '_alive', False):
                    c.set_error(_tr('Model did not return a valid flow.'))
                return
            child = self._persist_flow(
                s, flow, c.payload,
                origin={'kind': 'refine', 'parent_flow': str(p.get('id', '') or ''), 'parent_node': str(n.get('id', '') or '')},
            )
            if child is None:
                c.set_error(_tr('Could not save the refined flow.'))
                return
            n['refine_flow'] = child.get('id')
            self._save_flow_record(s, p)
            if getattr(card, '_alive', False) and isinstance(card.payload, dict):
                card.payload['flow'] = p
                card._populate_node_list()
            c.payload['flow'] = child
            self._render_flow_card(c, child, from_cache=False)

        def on_failed(message, c=detail_card):
            if getattr(c, '_alive', False):
                c.worker = None
                c.set_error(message)

        detail_card.worker = editor_llm_request(messages, on_delta, on_finished, on_failed)

    def _code_for_flow_revision(self, store, flow, card):
        origin = flow.get('origin') if isinstance(flow.get('origin'), dict) else {}
        kind = str(origin.get('kind', '') or '')
        if kind in ('function', 'object'):
            entry = editor_find_entry(store, origin.get('entry_id'))
            if entry is not None:
                return editor_code_context_for_entry(store, entry, radius=80)[0]
        lines = origin.get('lines') if isinstance(origin.get('lines'), list) else []
        text = editor_live_text_for(self, store.path) if store is not None else ''
        all_lines = text.splitlines()
        try:
            a = max(1, int(lines[0]))
            b = max(a, int(lines[1]))
            return '\n'.join(all_lines[a - 1:b])
        except Exception:
            pass
        payload = card.payload if card is not None and isinstance(card.payload, dict) else {}
        return str(payload.get('text', '') or text[:8000])

    def revise_flow_card(self, card):
        store = self._store_for_card(card)
        flow = card.payload.get('flow') if card is not None and isinstance(card.payload, dict) else None
        if store is None or not isinstance(flow, dict):
            return
        try:
            lang = store.lexicon_language()
        except Exception:
            lang = 'English'
        current_code = self._code_for_flow_revision(store, flow, card)
        card.reset_to_loading()
        messages = editor_revise_messages(store, flow, current_code, lang)
        acc = []

        def on_delta(piece):
            acc.append(str(piece or ''))

        def on_finished(text, c=card, old=copy.deepcopy(flow)):
            if getattr(c, '_alive', False):
                c.worker = None
            new_flow = editor_parse_flow_json(str(text or ''.join(acc) or ''))
            if new_flow is None:
                if getattr(c, '_alive', False):
                    c.set_error(_tr('Model did not return a valid revision.'))
                return
            new_flow['id'] = old.get('id')
            new_flow['created_at'] = old.get('created_at')
            new_flow['origin'] = old.get('origin')
            new_flow['history'] = old.get('history') or []
            for n in new_flow.get('nodes') or []:
                if isinstance(n, dict) and 'refine_flow' not in n:
                    n['refine_flow'] = None
            marked, mark = editor_revision_marked_flow(old, new_flow)
            c.payload['_revision'] = {'old': old, 'new': new_flow, 'marked': marked, 'mark': mark}
            self.set_card_revision_view(c, 'new')

        def on_failed(message, c=card):
            if getattr(c, '_alive', False):
                c.worker = None
                c.set_error(message)

        card.worker = editor_llm_request(messages, on_delta, on_finished, on_failed)

    def set_card_revision_view(self, card, which):
        rev = card.payload.get('_revision') if card is not None and isinstance(card.payload, dict) else None
        if not isinstance(rev, dict):
            return
        if which == 'old':
            card.payload['_revision_view'] = 'old'
            card._set_revision_mode(True, show_new=False)
            self._render_flow_card(card, rev.get('old'), from_cache=False)
        else:
            card.payload['_revision_view'] = 'new'
            card._set_revision_mode(True, show_new=True)
            self._render_flow_card(card, rev.get('marked'), from_cache=False, mark=rev.get('mark'))

    def adopt_card_revision(self, card):
        store = self._store_for_card(card)
        rev = card.payload.get('_revision') if card is not None and isinstance(card.payload, dict) else None
        if store is None or not isinstance(rev, dict):
            return
        old = rev.get('old') if isinstance(rev.get('old'), dict) else {}
        new = rev.get('new') if isinstance(rev.get('new'), dict) else {}
        history = list(old.get('history') or [])
        history.append({
            'rev': len(history) + 1,
            'at': _editor_now_iso(),
            'reason': 'revision',
            'nodes': copy.deepcopy(old.get('nodes') or []),
            'edges': copy.deepcopy(old.get('edges') or []),
        })
        new['history'] = history
        if self._save_flow_record(store, new):
            try:
                cache = store.load_cards_cache()
                fid = str(new.get('id', '') or '')
                for key, value in list(cache.items()):
                    if isinstance(value, dict) and str(value.get('flow_id', '') or '') == fid:
                        cache.pop(key, None)
                store.save_cards_cache(cache)
            except Exception:
                pass
            card.payload.pop('_revision', None)
            card.payload.pop('_revision_view', None)
            card.payload['flow'] = new
            card._set_revision_mode(False)
            self._render_flow_card(card, new, from_cache=False)

    def discard_card_revision(self, card):
        rev = card.payload.get('_revision') if card is not None and isinstance(card.payload, dict) else None
        if not isinstance(rev, dict):
            return
        old = rev.get('old')
        card.payload.pop('_revision', None)
        card.payload.pop('_revision_view', None)
        card._set_revision_mode(False)
        self._render_flow_card(card, old, from_cache=False)

    def _start_explain_stream(self, card):
        # fresh stream into the card (first fill, or Regenerate bypassing the cache)
        if card is None or not getattr(card, '_alive', False):
            return
        payload = card.payload if isinstance(card.payload, dict) else {}
        path = str(payload.get('path', '') or '') or (self.session.current_path or '')
        store = self.session.store(path) if path else None
        try:
            lang = store.lexicon_language() if store is not None else 'English'
        except Exception:
            lang = 'English'
        old = getattr(card, 'worker', None)
        if old is not None:
            try:
                old.stop()
            except Exception:
                pass
        card.reset_to_loading()
        key = self._explain_cache_key(payload.get('text', ''), lang)

        def on_delta(piece, c=card):
            if getattr(c, '_alive', False):
                c.append_delta(piece)

        def on_finished(text, c=card, s=store, k=key, p=dict(payload)):
            if getattr(c, '_alive', False):
                c.worker = None
                c.finish(text)
            if s is None:
                return
            try:  # the answer is valid even if the card closed a beat ago — cache it
                cache = s.load_cards_cache()
                if not isinstance(cache, dict):
                    cache = {}
                try:
                    ls = int(p.get('line_start', 0) or 0)
                    le = int(p.get('line_end', 0) or 0)
                except Exception:
                    ls = le = 0
                cache[k] = {
                    'kind': 'explain',
                    'text': str(text or ''),
                    'at': datetime.datetime.now().isoformat(timespec='seconds'),
                    'line_start': ls,
                    'line_end': le,
                }
                s.save_cards_cache(cache)
            except Exception:
                pass

        def on_failed(message, c=card):
            if getattr(c, '_alive', False):
                c.worker = None
                c.set_error(message)

        messages = editor_explain_messages(store, payload, lang)
        card.worker = editor_llm_request(messages, on_delta, on_finished, on_failed)

    # ---- M2: save / stale detection ----
    def _on_save_requested(self):
        self.editor_page.save_current()
        try:
            self.lexicon_page.request_parse(self.session.current_path)
        except Exception:
            pass

    def note_disk_seen(self, path):
        store = EditorStore.for_path(path)
        if store is not None:
            self._disk_mtimes[path] = store.disk_mtime()

    def _prune_page_state(self):
        open_files = list(self.session.open_files)
        try:
            self.editor_page.prune_closed(open_files)
        except Exception:
            pass
        for p in list(self._disk_mtimes.keys()):
            if p not in open_files:
                self._disk_mtimes.pop(p, None)

    # ---- FIX-3 round: conversation-bound file sets ----
    def _conversation_cid(self):
        try:
            path = str(getattr(self._main, '_active_conversation_path', '') or '').strip()
        except Exception:
            path = ''
        if not path:
            return ''
        if self._cid_cache[0] == path:
            return self._cid_cache[1]
        cid = ''
        try:
            record = load_conversation_record(path)
            if isinstance(record, dict):
                cid = str(record.get('id', '') or '').strip()
        except Exception:
            cid = ''
        if not cid:
            # id-less record: the full stem is unique per file (the M7 short
            # form collides for same-second conversations)
            try:
                cid = Path(path).stem
            except Exception:
                cid = ''
        self._cid_cache = (path, cid)
        return cid

    def _binding_snapshot(self):
        return {
            'files': list(self.session.open_files),
            'current': str(self.session.current_path or ''),
            'edit_target': str(self.session.edit_target or ''),
            'at': datetime.datetime.now().isoformat(timespec='seconds'),
        }

    def _record_conversation_binding(self):
        if self._binding_syncing or self._bound_cid is None:
            return
        if self._bound_cid == '':
            self._unsaved_binding = self._binding_snapshot()
            return
        bindings = editor_load_conversation_bindings()
        bindings[self._bound_cid] = self._binding_snapshot()
        editor_save_conversation_bindings(bindings)

    def sync_conversation_binding(self):
        cid = self._conversation_cid()
        if self._bound_cid is None:
            # First sync after a new EditorWindow/app launch: restore an existing
            # per-conversation binding BEFORE recording. The old order recorded the
            # fresh empty EditorSession here and erased files/current/edit_target
            # from disk, so the user had to Set as Edit Target again after restart.
            self._bound_cid = cid
            if cid:
                bindings = editor_load_conversation_bindings()
                desired = bindings.get(cid)
                if isinstance(desired, dict):
                    self._binding_syncing = True
                    try:
                        files = [p for p in (desired.get('files') or []) if editor_supported_file(p)]
                        current = str(desired.get('current', '') or '')
                        if current not in files:
                            current = files[0] if files else ''
                        target = str(desired.get('edit_target', '') or '')
                        self.session.open_files = list(files)
                        self.session.current_path = current or None
                        self.session.edit_target = target if target in files else None
                        self.session.files_changed.emit()
                        self.session.file_selected.emit(current or '')
                    finally:
                        self._binding_syncing = False
            self._record_conversation_binding()
            return
        if cid == self._bound_cid:
            return
        self._binding_syncing = True
        try:
            bindings = editor_load_conversation_bindings()
            outgoing = self._binding_snapshot()
            if self._bound_cid == '':
                self._unsaved_binding = outgoing
            else:
                bindings[self._bound_cid] = outgoing
            if cid and cid not in bindings and self._bound_cid == '' and self.session.open_files:
                # first save of a fresh conversation: the open set follows it, no swap
                bindings[cid] = self._unsaved_binding or outgoing
                self._unsaved_binding = None
                self._bound_cid = cid
                editor_save_conversation_bindings(bindings)
                return
            desired = bindings.get(cid) if cid else None
            desired = desired if isinstance(desired, dict) else {}
            files = [p for p in (desired.get('files') or []) if editor_supported_file(p)]
            # unsaved edits survive the switch: dirty files stay open
            try:
                dirty = [p for p in self.session.open_files if p in self.editor_page._dirty_paths]
            except Exception:
                dirty = []
            for p in dirty:
                if p not in files:
                    files.append(p)
            current = str(desired.get('current', '') or '')
            if current not in files:
                current = files[0] if files else ''
            target = str(desired.get('edit_target', '') or '')
            self.session.open_files = list(files)
            self.session.edit_target = target if target in files else None
            self.session.current_path = current or None
            self._bound_cid = cid
            editor_save_conversation_bindings(bindings)
            self.session.files_changed.emit()
            self.session.file_selected.emit(current or '')
        finally:
            self._binding_syncing = False
        self._record_conversation_binding()

    def _check_disk_changes(self):
        self.sync_conversation_binding()
        for path in list(self.session.open_files):
            store = EditorStore.for_path(path)
            if store is None:
                continue
            mtime = store.disk_mtime()
            if mtime is None:
                continue
            last = self._disk_mtimes.get(path)
            if last is None:
                self._disk_mtimes[path] = mtime
                continue
            if mtime == last:
                continue
            self._disk_mtimes[path] = mtime
            own = getattr(store, '_last_own_mtime', None)
            if own is not None and mtime == own:
                continue  # our own write_disk — not an external change
            self.refresh_for_external_change(path)

    def refresh_for_external_change(self, path):
        # Badge the pill; banner too when it's the file on screen.
        try:
            self.file_bar.set_stale(path, True)
        except Exception:
            pass
        has_unsaved = False
        try:
            has_unsaved = path in getattr(self.editor_page, '_dirty_paths', set())
        except Exception:
            has_unsaved = False
        is_current = (path == self.session.current_path)
        if has_unsaved:
            # Don't clobber the user's in-app edits — let them resolve via Reload.
            if is_current:
                try:
                    self.editor_page.show_stale_banner()
                except Exception:
                    pass
            return
        # No unsaved edits: an external change (AI edit, regenerated output,
        # external editor) must reach the Logic Map live — not only after a
        # manual Reload or an app restart. Re-parse now.
        try:
            self.lexicon_page._parsed_once.discard(path)
        except Exception:
            pass
        if is_current:
            try:
                self.editor_page.reload_from_disk()  # emits file_content_reloaded → re-parse
            except Exception:
                pass
        else:
            try:
                self.lexicon_page.request_parse(path)
            except Exception:
                pass

    def showEvent(self, event):
        super().showEvent(event)
        try:
            self._stale_timer.start()
        except Exception:
            pass
        try:
            self.sync_conversation_binding()
        except Exception:
            pass

    def hideEvent(self, event):
        super().hideEvent(event)
        try:
            self._stale_timer.stop()
        except Exception:
            pass

    # ── open / close / placement ─────────────────────────────
    def _editor_window_flags(self):
        flags = Qt.WindowType.FramelessWindowHint | Qt.WindowType.Window
        if getattr(self, '_editor_always_on_top', True):
            flags |= Qt.WindowType.WindowStaysOnTopHint
        return flags

    def set_editor_always_on_top(self, enabled):
        # Settings toggle: when off, the editor behaves like a normal window
        # (can go behind others) instead of always floating on top.
        enabled = bool(enabled)
        if enabled == getattr(self, '_editor_always_on_top', True):
            return
        self._editor_always_on_top = enabled
        was_visible = self.isVisible()
        geom = self.geometry()
        self.setWindowFlags(self._editor_window_flags())  # requires re-show to take effect
        if was_visible:
            self.show()
            self.setGeometry(geom)
            self.raise_()

    def open_with_files(self, paths):
        try:
            self.sync_conversation_binding()  # adopt the active conversation first
        except Exception:
            pass
        paths = list(paths or [])
        first_new = None
        first_valid = None
        for p in paths:
            try:
                ap = os.path.abspath(str(p))
            except Exception:
                continue
            already = ap in self.session.open_files
            if self.session.add_file(ap):
                if first_valid is None:
                    first_valid = ap
                if not already and first_new is None:
                    first_new = ap
        target = first_new or first_valid
        if target:
            self.session.select_file(target)
        if self.isVisible():
            self.bring_to_front()
        else:
            self.position_beside_main(animated=False)
            self.animate_open()

    def bring_to_front(self):
        try:
            if self._close_anim is not None:
                self._close_anim.stop()
                self._close_anim = None
                # the canceled slide displaced us — snap back to the rest rect (M2)
                if self._dock_target_rect is not None:
                    self.setGeometry(QRect(self._dock_target_rect))
        except Exception:
            pass
        self.setWindowOpacity(1.0)
        self.show()
        self.raise_()
        self.activateWindow()

    def _main_frame_geometry(self):
        try:
            return self._main.frameGeometry()
        except Exception:
            return QRect(100, 100, 800, 600)

    def _screen_available_geometry(self):
        scr = None
        try:
            scr = self._main.screen()
        except Exception:
            scr = None
        if scr is None:
            scr = self.screen() or QGuiApplication.primaryScreen()
        return scr.availableGeometry()

    def position_beside_main(self, animated=False):
        # Re-dock = SIZE + POSITION: the shared helper returns the golden-ratio
        # companion rect (as tall as the main window's panel, a golden width or what fits).
        # A visible Reader is passed as avoid_rect so the two companions never
        # bury each other on the identical slot.
        avoid = None
        try:
            sibling_getter = getattr(self._main, 'reader_window_if_open', None)
            sibling = sibling_getter() if callable(sibling_getter) else None
            if sibling is not None and sibling is not self:
                avoid = QRect(sibling.frameGeometry())
        except Exception:
            avoid = None
        target, main_target = broccoli_companion_dock_rect(self, self._main, avoid_rect=avoid)
        if main_target is not None:
            mg = self._main_frame_geometry()
            try:
                self._main_move_anim = QPropertyAnimation(self._main, b'geometry', self)
                self._main_move_anim.setDuration(260)
                self._main_move_anim.setStartValue(QRect(mg))
                self._main_move_anim.setEndValue(main_target)
                self._main_move_anim.setEasingCurve(QEasingCurve.Type.OutCubic)
                self._main_move_anim.start()
            except Exception:
                try:
                    self._main.move(main_target.left(), main_target.top())
                except Exception:
                    pass
        self._dock_target_rect = QRect(target)  # M2: snap-back anchor
        if animated and self.isVisible():
            self._dock_anim = QPropertyAnimation(self, b'geometry', self)
            self._dock_anim.setDuration(260)
            self._dock_anim.setStartValue(QRect(self.geometry()))
            self._dock_anim.setEndValue(target)
            self._dock_anim.setEasingCurve(QEasingCurve.Type.OutCubic)
            self._dock_anim.start()
        else:
            self.setGeometry(target)

    def animate_open(self):
        try:
            if self._close_anim is not None:
                self._close_anim.stop()
                self._close_anim = None
        except Exception:
            pass
        final = QRect(self.geometry())
        self._dock_target_rect = QRect(final)  # M2: snap-back anchor
        start = QRect(final)
        start.translate(24, 0)
        self.setWindowOpacity(0.0)
        self.setGeometry(start)
        self.show()
        self.raise_()
        self.activateWindow()
        group = QParallelAnimationGroup(self)
        geo = QPropertyAnimation(self, b'geometry')
        geo.setDuration(260)
        geo.setStartValue(start)
        geo.setEndValue(final)
        geo.setEasingCurve(QEasingCurve.Type.OutCubic)
        fade = QPropertyAnimation(self, b'windowOpacity')
        fade.setDuration(260)
        fade.setStartValue(0.0)
        fade.setEndValue(1.0)
        fade.setEasingCurve(QEasingCurve.Type.OutCubic)
        group.addAnimation(geo)
        group.addAnimation(fade)
        group.finished.connect(lambda: self.setWindowOpacity(1.0))
        self._open_anim = group
        group.start()

    def animate_close(self):
        if not self.isVisible():
            return
        if self._close_anim is not None:
            return
        try:
            if self._open_anim is not None:
                self._open_anim.stop()
                self._open_anim = None
        except Exception:
            pass
        cur = QRect(self.geometry())
        # M2: remember the resting rect so a canceled close restores exactly it
        self._dock_target_rect = QRect(cur)
        end = QRect(cur)
        end.translate(24, 0)
        group = QParallelAnimationGroup(self)
        geo = QPropertyAnimation(self, b'geometry')
        geo.setDuration(220)
        geo.setStartValue(cur)
        geo.setEndValue(end)
        geo.setEasingCurve(QEasingCurve.Type.InCubic)
        fade = QPropertyAnimation(self, b'windowOpacity')
        fade.setDuration(220)
        fade.setStartValue(self.windowOpacity())
        fade.setEndValue(0.0)
        fade.setEasingCurve(QEasingCurve.Type.InCubic)
        group.addAnimation(geo)
        group.addAnimation(fade)
        group.finished.connect(self._finish_close)
        self._close_anim = group
        group.start()

    def _finish_close(self):
        self._close_anim = None
        self.hide()
        self.setWindowOpacity(1.0)

    # ── state / theme ────────────────────────────────────────
    def current_editor_state(self):
        try:
            selection = self.editor_page.selection_info()
        except Exception:
            selection = {'text': '', 'line_start': 0, 'line_end': 0,
                         'path': self.session.current_path}
        return {
            'current_path': self.session.current_path,
            'open_files': list(self.session.open_files),
            'selection': selection,
        }

    def apply_editor_theme(self, dark_mode):
        dark = bool(dark_mode)
        self._dark_mode = dark
        self.update()  # repaint the window background with the new theme color
        try:
            self.nav.set_theme('dark' if dark else 'light')
        except Exception:
            pass
        for child in (self.editor_page, self.file_bar, self.action_bar,
                      self.lexicon_page, self.debug_page, self.snapshot_page,
                      self.diff_page, self.card_dock):
            try:
                if child is not None:
                    child.set_theme(dark)
            except Exception:
                pass
        self.update()

    # ---- FIX-38: version hook — every save site funnels through here ----
    def note_version_saved(self, path, trigger, version=None):
        try:
            self.debug_page.note_version_saved(path, trigger, version=version)
        except Exception:
            pass

    # ── window chrome (paint / drag / resize) ────────────────
    def paintEvent(self, event):
        painter = QPainter(self)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)
        painter.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform)
        rect = QRectF(self.rect())
        path = smooth_round_rect_path(rect, self.radius)
        painter.setClipPath(path)
        # Match the MAIN window interior (white in light mode), not the palette's
        # #ECECEC window gray — the editor must read as the same surface.
        bg_color = QColor('#2D2D2D') if getattr(self, '_dark_mode', False) else QColor('#FFFFFF')
        painter.fillPath(path, bg_color)

    def resizeEvent(self, event):
        super().resizeEvent(event)
        # ---- M4: the card dock tracks the pages area (42% width, 12px insets);
        # its event filter on the pages widget covers layout-driven resizes too
        if self.card_dock is not None:
            try:
                self.card_dock.relayout()
            except Exception:
                pass

    def _in_resize_corner(self, pos):
        return pos.x() >= self.width() - 22 and pos.y() >= self.height() - 22

    def mousePressEvent(self, event):
        if event.button() == Qt.MouseButton.LeftButton:
            pos = event.position().toPoint()
            if self._in_resize_corner(pos):
                self._resize_active = True
                self._resize_origin = event.globalPosition().toPoint()
                self._resize_start_geo = QRect(self.geometry())
                event.accept()
                return
            # drag ONLY from the top bar strip or bare window background,
            # so it never steals clicks meant for editor content
            if pos.y() < 44 or self.childAt(pos) is None:
                self.drag_pos = event.globalPosition().toPoint() - self.frameGeometry().topLeft()
                event.accept()

    def mouseMoveEvent(self, event):
        pos = event.position().toPoint()
        if self._resize_active and (event.buttons() & Qt.MouseButton.LeftButton):
            delta = event.globalPosition().toPoint() - self._resize_origin
            g = self._resize_start_geo
            w = max(self.minimumWidth(), g.width() + delta.x())
            h = max(self.minimumHeight(), g.height() + delta.y())
            self.setGeometry(g.x(), g.y(), w, h)
            event.accept()
            return
        if event.buttons() == Qt.MouseButton.LeftButton and self.drag_pos is not None:
            self.move(event.globalPosition().toPoint() - self.drag_pos)
            event.accept()
            return
        try:
            if self._in_resize_corner(pos):
                self.setCursor(Qt.CursorShape.SizeFDiagCursor)
            else:
                self.unsetCursor()
        except Exception:
            pass

    def mouseReleaseEvent(self, event):
        self.drag_pos = None
        self._resize_active = False
        self._resize_origin = None
        self._resize_start_geo = None
        try:
            self.unsetCursor()
        except Exception:
            pass
        super().mouseReleaseEvent(event)

# ===== Broccoli Editor Window — module END ======================


# ===== Broccoli Reader Window (阅读器窗口) — module BEGIN ======================
# FIX-39: read-only document reader. Opened from attachment cards ('Open in
# Reader'). Renders text / PDF / Word / PowerPoint / Excel; horizontal paging is
# the default for page-based documents (vertical available per right-click, PPT
# defaults vertical); a translation side panel translates the CURRENT page into
# the target language (text first, existing Apple-Vision OCR next, page image as
# a vision attachment last), caches per page + target on disk, and can
# auto-translate on page flips. THREADING DISCIPLINE (plan review): the loader
# thread does parsing + ALL text extraction and never touches Qt widgets; fitz
# documents are used by exactly one thread at a time (loader until 'loaded',
# then GUI only); QTextDocument pagination/painting happens ONLY on the GUI
# thread (the worker returns the textutil HTML string).

from PyQt6.QtCore import QBuffer, QIODevice, QSizeF  # region-local (M4 precedent)

READER_DATA_DIR = os.path.join(BROCCOLI_APP_DATA_DIR, 'Reader')
READER_DOC_EXTS = {'.pdf', '.docx', '.doc', '.pptx', '.xlsx', '.xlsm', '.xls', '.csv'}
# round 2: images are readable AND translatable (OCR → vision attachment ladder)
READER_IMAGE_EXTS = {'.png', '.jpg', '.jpeg', '.gif', '.bmp', '.webp', '.tif', '.tiff', '.heic'}
READER_IMAGE_ATTACH_MAX_BYTES = 4 * 1024 * 1024  # original file rides as-is below this
READER_PAGE_KINDS = ('pixmap', 'table', 'stream')
READER_SHEET_MAX_ROWS = 200
READER_SHEET_MAX_COLS = 50
READER_TRANSLATE_TABLE_ROWS = 40
READER_TRANSLATE_TABLE_COLS = 20
READER_TRANSLATE_TEXT_CHARS = 12000   # review fix: one page/stream prompt cap
READER_DOCX_PAGE_SIZE = (794.0, 1123.0)  # ~A4 @ 96dpi


def reader_supported_file(path):
    try:
        if not os.path.isfile(path):
            return False
        ext = os.path.splitext(path)[1].lower()
        if ext in READER_DOC_EXTS or ext in READER_IMAGE_EXTS:
            return True
        return editor_supported_file(path)
    except Exception:
        return False


def _reader_prefs_path():
    return os.path.join(READER_DATA_DIR, 'prefs.json')


def reader_prefs_load():
    try:
        with open(_reader_prefs_path(), 'r', encoding='utf-8') as f:
            data = json.load(f)
        if isinstance(data, dict):
            return data
    except Exception:
        pass
    return {'orientation': {}, 'auto_translate': False}


def reader_prefs_save(prefs):
    try:
        os.makedirs(READER_DATA_DIR, exist_ok=True)
        tmp_path = _reader_prefs_path() + '.tmp'
        with open(tmp_path, 'w', encoding='utf-8') as f:
            json.dump(prefs if isinstance(prefs, dict) else {}, f, ensure_ascii=False, indent=2)
        os.replace(tmp_path, _reader_prefs_path())
    except Exception:
        pass


def reader_default_orientation(kind, prefs=None):
    """User preference first; built-in defaults: page documents flip HORIZONTALLY
    (the user's explicit ask — vertical readers are bad for PDFs), PPT vertical."""
    prefs = prefs if isinstance(prefs, dict) else reader_prefs_load()
    stored = (prefs.get('orientation') or {}).get(kind)
    if stored in ('horizontal', 'vertical'):
        return stored
    return 'vertical' if kind == 'pptx' else 'horizontal'


class ReaderPage:
    """One page of a loaded document. plain_text feeds translation; 'pixmap'
    pages render lazily ON THE GUI THREAD via their document's renderer."""

    def __init__(self, index, kind, label='', plain_text='', rows=None,
                 size=(794.0, 1123.0), note=''):
        self.index = int(index)
        self.kind = kind if kind in READER_PAGE_KINDS else 'stream'
        self.label = str(label or '')
        self.plain_text = str(plain_text or '')
        self.rows = rows if isinstance(rows, list) else None
        self.size = (float(size[0]) or 1.0, float(size[1]) or 1.0)
        self.note = str(note or '')
        self.doc = None            # backref, set by ReaderDocument
        self._pixmap = None        # (bucket_width, QPixmap)

    def aspect(self):
        w, h = self.size
        return (h / w) if w else 1.4

    def render_pixmap(self, target_width):
        """GUI-thread only. Cached per width bucket (one entry per page)."""
        target_width = max(64, int(target_width))
        bucket = (target_width + 63) // 64 * 64
        if self._pixmap is not None and self._pixmap[0] == bucket:
            return self._pixmap[1]
        pm = None
        try:
            if self.doc is not None:
                pm = self.doc.render_page_pixmap(self, bucket)
        except Exception:
            pm = None
        if pm is not None:
            self._pixmap = (bucket, pm)
        return pm

    def drop_pixmap(self):
        self._pixmap = None


class ReaderDocument:
    """Loaded document handle. Built by the loader worker (parse + text only);
    finalize_on_gui() completes anything that needs Qt paint objects."""

    def __init__(self, path, kind):
        self.path = str(path or '')
        self.kind = kind  # 'pdf' | 'docx' | 'pptx' | 'sheet' | 'text' | 'error'
        self.pages = []
        self.error = ''
        self.note = ''
        self._fitz_doc = None      # pdf: owned here; GUI-only after 'loaded'
        self._docx_html = ''       # docx: worker output; QTextDocument built on GUI
        self._qt_doc = None
        self._pptx_slides = None   # pptx: plain paint-plan dicts from the worker

    def add_page(self, page):
        page.doc = self
        page.index = len(self.pages)
        self.pages.append(page)
        return page

    def close(self):
        try:
            if self._fitz_doc is not None:
                self._fitz_doc.close()
        except Exception:
            pass
        self._fitz_doc = None
        self._qt_doc = None
        for page in self.pages:
            page.drop_pixmap()

    # ---- GUI-side finalize (QTextDocument pagination for docx) ----
    def finalize_on_gui(self):
        if self.kind != 'docx' or not self._docx_html or self.pages:
            return
        try:
            from PyQt6.QtGui import QTextDocument
            doc = QTextDocument()
            doc.setDocumentMargin(28)
            doc.setHtml(self._docx_html)
            page_w, page_h = READER_DOCX_PAGE_SIZE
            doc.setTextWidth(page_w - 2 * doc.documentMargin())
            doc.setPageSize(QSizeF(page_w, page_h))
            count = max(1, doc.pageCount())
            self._qt_doc = doc
            # per-page plain text: assign each block to the page containing its
            # layout START (a block spanning a boundary counts to the earlier
            # page — accepted approximation, documented in the plan)
            texts = [[] for _ in range(count)]
            layout = doc.documentLayout()
            block = doc.begin()
            while block.isValid():
                try:
                    rect = layout.blockBoundingRect(block)
                    page_idx = min(count - 1, max(0, int(rect.y() // page_h)))
                    txt = block.text()
                    if txt:
                        texts[page_idx].append(txt)
                except Exception:
                    pass
                block = block.next()
            for i in range(count):
                self.add_page(ReaderPage(i, 'pixmap', label=_tr('Page %d') % (i + 1),
                                         plain_text='\n'.join(texts[i]),
                                         size=(page_w, page_h)))
        except Exception as exc:
            self.kind = 'error'
            self.error = _tr('Could not paginate this document: %s') % exc

    # ---- GUI-side page rendering ----
    def render_page_pixmap(self, page, width_px):
        if self.kind == 'pdf':
            return self._render_pdf_page(page, width_px)
        if self.kind == 'docx':
            return self._render_docx_page(page, width_px)
        if self.kind == 'pptx':
            return self._render_pptx_page(page, width_px)
        if self.kind == 'image':
            return self._render_image_page(page, width_px)
        return None

    def _render_image_page(self, page, width_px):
        try:
            img = QImage(self.path)
            if img.isNull():
                return None
            if img.width() > width_px:
                img = img.scaledToWidth(int(width_px), Qt.TransformationMode.SmoothTransformation)
            return QPixmap.fromImage(img)
        except Exception:
            return None

    def _render_pdf_page(self, page, width_px):
        if self._fitz_doc is None:
            return None
        try:
            fpage = self._fitz_doc.load_page(page.index)
            zoom = max(0.1, float(width_px) / max(1.0, page.size[0]))
            import fitz as _fitz
            pix = fpage.get_pixmap(matrix=_fitz.Matrix(zoom, zoom), alpha=False)
            fmt = QImage.Format.Format_RGB888
            img = QImage(pix.samples, pix.width, pix.height, pix.stride, fmt)
            return QPixmap.fromImage(img.copy())  # copy: detach from fitz buffer
        except Exception:
            return None

    def _render_docx_page(self, page, width_px):
        if self._qt_doc is None:
            return None
        try:
            page_w, page_h = READER_DOCX_PAGE_SIZE
            scale = float(width_px) / page_w
            img = QImage(int(page_w * scale), int(page_h * scale),
                         QImage.Format.Format_ARGB32_Premultiplied)
            img.fill(QColor('#FFFFFF'))
            painter = QPainter(img)
            painter.setRenderHint(QPainter.RenderHint.Antialiasing)
            painter.setRenderHint(QPainter.RenderHint.TextAntialiasing)
            painter.scale(scale, scale)
            painter.translate(0, -page.index * page_h)
            clip = QRectF(0, page.index * page_h, page_w, page_h)
            self._qt_doc.drawContents(painter, clip)
            painter.end()
            return QPixmap.fromImage(img)
        except Exception:
            return None

    def _render_pptx_page(self, page, width_px):
        slides = self._pptx_slides or []
        if not (0 <= page.index < len(slides)):
            return None
        plan = slides[page.index]
        try:
            slide_w = max(1.0, float(plan.get('width', 960.0)))
            slide_h = max(1.0, float(plan.get('height', 540.0)))
            scale = float(width_px) / slide_w
            img = QImage(int(slide_w * scale), int(slide_h * scale),
                         QImage.Format.Format_ARGB32_Premultiplied)
            img.fill(QColor(str(plan.get('bg', '#FFFFFF'))))
            painter = QPainter(img)
            painter.setRenderHint(QPainter.RenderHint.Antialiasing)
            painter.setRenderHint(QPainter.RenderHint.TextAntialiasing)
            painter.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform)
            painter.scale(scale, scale)
            from PyQt6.QtGui import QTextDocument
            for shape in plan.get('shapes') or []:
                skind = shape.get('kind')
                rect = shape.get('rect') or (0, 0, 10, 10)
                x, y, w, h = (float(v) for v in rect)
                if skind == 'image':
                    blob = shape.get('blob') or b''
                    simg = QImage.fromData(blob)
                    if not simg.isNull():
                        painter.drawImage(QRectF(x, y, w, h), simg,
                                          QRectF(0, 0, simg.width(), simg.height()))
                elif skind == 'text':
                    tdoc = QTextDocument()
                    tdoc.setDocumentMargin(2)
                    tdoc.setHtml(shape.get('html', ''))
                    tdoc.setTextWidth(w)
                    painter.save()
                    painter.translate(x, y)
                    painter.setClipRect(QRectF(0, 0, w, max(h, tdoc.size().height())))
                    tdoc.drawContents(painter)
                    painter.restore()
                elif skind == 'table':
                    rows = shape.get('rows') or []
                    n_rows = max(1, len(rows))
                    n_cols = max(1, max((len(r) for r in rows), default=1))
                    cell_h = h / n_rows
                    cell_w = w / n_cols
                    pen = QPen(QColor(0, 0, 0, 70))
                    pen.setWidthF(1.0)
                    painter.setPen(pen)
                    font = painter.font()
                    font.setPixelSize(max(8, int(cell_h * 0.5)))
                    painter.setFont(font)
                    for ri, row in enumerate(rows):
                        for ci in range(n_cols):
                            cell = QRectF(x + ci * cell_w, y + ri * cell_h, cell_w, cell_h)
                            painter.drawRect(cell)
                            text = str(row[ci]) if ci < len(row) else ''
                            if text:
                                painter.drawText(cell.adjusted(3, 0, -3, 0),
                                                 Qt.AlignmentFlag.AlignVCenter
                                                 | Qt.AlignmentFlag.AlignLeft,
                                                 text)
            painter.end()
            return QPixmap.fromImage(img)
        except Exception:
            return None


# ---- loaders (worker-thread safe: parsing + text extraction only) ----

def _reader_error_document(path, message):
    doc = ReaderDocument(path, 'error')
    doc.error = str(message or _tr('Could not open this file.'))
    doc.add_page(ReaderPage(0, 'stream', label=_tr('Error'), plain_text=doc.error))
    return doc


def _reader_load_image(path):
    """Single pixmap page; NO text layer, so the translation ladder goes straight
    to OCR-then-vision-attachment. QImage is thread-safe (unlike QPixmap)."""
    try:
        img = QImage(path)
        if img.isNull():
            return _reader_error_document(path, _tr('Could not decode the image.'))
        w = max(1.0, float(img.width()))
        h = max(1.0, float(img.height()))
    except Exception as exc:
        return _reader_error_document(path, _tr('Could not open the image: %s') % exc)
    doc = ReaderDocument(path, 'image')
    doc.add_page(ReaderPage(0, 'pixmap', label=os.path.basename(path), size=(w, h)))
    return doc


def _reader_load_text(path):
    try:
        with open(path, 'r', encoding='utf-8', errors='replace') as f:
            text = f.read()
    except Exception as exc:
        return _reader_error_document(path, _tr('Could not read the file: %s') % exc)
    doc = ReaderDocument(path, 'text')
    doc.add_page(ReaderPage(0, 'stream', label=os.path.basename(path), plain_text=text))
    return doc


def _reader_load_pdf(path):
    try:
        import fitz
    except Exception:
        return _reader_error_document(path, _tr('PDF support unavailable (PyMuPDF missing).'))
    try:
        fdoc = fitz.open(path)
    except Exception as exc:
        return _reader_error_document(path, _tr('Could not open the PDF: %s') % exc)
    doc = ReaderDocument(path, 'pdf')
    doc._fitz_doc = fdoc
    try:
        for i in range(fdoc.page_count):
            try:
                if QThread.currentThread().isInterruptionRequested():
                    doc.close()
                    return _reader_error_document(path, _tr('Loading canceled.'))
            except Exception:
                pass
            fpage = fdoc.load_page(i)
            rect = fpage.rect
            try:
                text = fpage.get_text('text') or ''
            except Exception:
                text = ''
            doc.add_page(ReaderPage(i, 'pixmap', label=_tr('Page %d') % (i + 1),
                                    plain_text=text.strip(),
                                    size=(float(rect.width), float(rect.height))))
    except Exception as exc:
        doc.close()
        return _reader_error_document(path, _tr('Could not read the PDF pages: %s') % exc)
    if not doc.pages:
        doc.close()
        return _reader_error_document(path, _tr('The PDF has no pages.'))
    return doc


def _reader_load_docx(path):
    """textutil (macOS, handles .doc AND .docx) → HTML string; pagination happens
    on the GUI thread (finalize_on_gui). Fallback: python-docx plain text as ONE
    stream page (known degradation: loses horizontal paging — noted in the UI)."""
    html = ''
    try:
        proc = subprocess.run(
            ['textutil', '-convert', 'html', '-stdout', os.path.abspath(path)],
            capture_output=True, timeout=45)
        if proc.returncode == 0 and proc.stdout:
            html = proc.stdout.decode('utf-8', errors='replace')
    except Exception:
        html = ''
    if html.strip():
        doc = ReaderDocument(path, 'docx')
        doc._docx_html = html
        return doc
    try:
        import docx as _docx
        parsed = _docx.Document(path)
        parts = [p.text for p in parsed.paragraphs]
        for table in getattr(parsed, 'tables', []) or []:
            for row in table.rows:
                parts.append('\t'.join(cell.text for cell in row.cells))
        text = '\n'.join(parts).strip()
    except Exception as exc:
        return _reader_error_document(path, _tr('Could not read the document: %s') % exc)
    doc = ReaderDocument(path, 'text')
    doc.note = _tr('Rendered as plain text (textutil unavailable) — pagination lost.')
    doc.add_page(ReaderPage(0, 'stream', label=os.path.basename(path), plain_text=text))
    return doc


def _reader_pptx_run_html(run, scale):
    try:
        text = str(run.text or '')
    except Exception:
        text = ''
    if not text:
        return ''
    esc = (text.replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;')
           .replace('\n', '<br>'))
    styles = []
    try:
        size = run.font.size
        if size is not None:
            styles.append('font-size:%dpx' % max(6, int(size.pt * scale)))
    except Exception:
        pass
    try:
        if run.font.bold:
            styles.append('font-weight:bold')
        if run.font.italic:
            styles.append('font-style:italic')
    except Exception:
        pass
    try:
        color = run.font.color
        if color is not None and color.type is not None and getattr(color, 'rgb', None):
            styles.append('color:#%s' % str(color.rgb))
    except Exception:
        pass
    return '<span style="%s">%s</span>' % (';'.join(styles), esc)


def _reader_load_pptx(path):
    try:
        from pptx import Presentation
        from pptx.util import Emu
    except Exception:
        return _reader_error_document(path, _tr('PowerPoint support unavailable (python-pptx missing).'))
    try:
        prs = Presentation(path)
    except Exception as exc:
        return _reader_error_document(path, _tr('Could not open the presentation: %s') % exc)
    emu_to_px = 1.0 / 9525.0
    slide_w = float(prs.slide_width or Emu(9144000)) * emu_to_px
    slide_h = float(prs.slide_height or Emu(6858000)) * emu_to_px
    font_scale = 96.0 / 72.0
    doc = ReaderDocument(path, 'pptx')
    slides = []
    for si, slide in enumerate(prs.slides):
        shapes = []
        texts = []
        for shape in slide.shapes:
            try:
                rect = (float(shape.left or 0) * emu_to_px, float(shape.top or 0) * emu_to_px,
                        max(1.0, float(shape.width or 0) * emu_to_px),
                        max(1.0, float(shape.height or 0) * emu_to_px))
            except Exception:
                rect = (0.0, 0.0, 10.0, 10.0)
            try:
                if shape.shape_type == 13 and hasattr(shape, 'image'):  # PICTURE
                    shapes.append({'kind': 'image', 'rect': rect, 'blob': shape.image.blob})
                    continue
            except Exception:
                pass
            try:
                if getattr(shape, 'has_table', False):
                    rows = [[str(cell.text or '') for cell in row.cells]
                            for row in shape.table.rows]
                    shapes.append({'kind': 'table', 'rect': rect, 'rows': rows})
                    texts.extend('\t'.join(r) for r in rows)
                    continue
            except Exception:
                pass
            try:
                if getattr(shape, 'has_text_frame', False):
                    paras = []
                    for para in shape.text_frame.paragraphs:
                        runs = ''.join(_reader_pptx_run_html(r, font_scale) for r in para.runs)
                        align = ''
                        try:
                            if para.alignment is not None and 'CENTER' in str(para.alignment):
                                align = ' align="center"'
                            elif para.alignment is not None and 'RIGHT' in str(para.alignment):
                                align = ' align="right"'
                        except Exception:
                            align = ''
                        paras.append('<p style="margin:0"%s>%s</p>' % (align, runs or '&nbsp;'))
                    html = ''.join(paras)
                    shapes.append({'kind': 'text', 'rect': rect, 'html': html})
                    frame_text = str(shape.text_frame.text or '').strip()
                    if frame_text:
                        texts.append(frame_text)
            except Exception:
                pass
        slides.append({'width': slide_w, 'height': slide_h, 'bg': '#FFFFFF', 'shapes': shapes})
        doc.add_page(ReaderPage(si, 'pixmap', label=_tr('Slide %d') % (si + 1),
                                plain_text='\n'.join(texts).strip(),
                                size=(slide_w, slide_h)))
    doc._pptx_slides = slides
    if not doc.pages:
        return _reader_error_document(path, _tr('The presentation has no slides.'))
    return doc


def _reader_rows_to_text(rows, cap_chars=20000):
    lines = ['\t'.join(str(c) for c in row) for row in rows]
    text = '\n'.join(lines)
    return text[:cap_chars]


def _reader_sheet_page(doc, index, name, rows, truncated):
    note = _tr('showing first %dx%d cells') % (READER_SHEET_MAX_ROWS, READER_SHEET_MAX_COLS) if truncated else ''
    doc.add_page(ReaderPage(index, 'table', label=str(name or _tr('Sheet %d') % (index + 1)),
                            plain_text=_reader_rows_to_text(rows), rows=rows, note=note))


def _reader_load_sheet(path):
    ext = os.path.splitext(path)[1].lower()
    doc = ReaderDocument(path, 'sheet')
    try:
        if ext == '.csv':
            import csv as _csv
            rows = []
            truncated = False
            with open(path, 'r', encoding='utf-8', errors='replace', newline='') as f:
                for ri, row in enumerate(_csv.reader(f)):
                    if ri >= READER_SHEET_MAX_ROWS:
                        truncated = True
                        break
                    rows.append([str(c) for c in row[:READER_SHEET_MAX_COLS]])
            _reader_sheet_page(doc, 0, os.path.basename(path), rows, truncated)
        elif ext == '.xls':
            import xlrd
            book = xlrd.open_workbook(path)
            for si in range(book.nsheets):
                sheet = book.sheet_by_index(si)
                truncated = sheet.nrows > READER_SHEET_MAX_ROWS or sheet.ncols > READER_SHEET_MAX_COLS
                rows = [[str(sheet.cell_value(r, c))
                         for c in range(min(sheet.ncols, READER_SHEET_MAX_COLS))]
                        for r in range(min(sheet.nrows, READER_SHEET_MAX_ROWS))]
                _reader_sheet_page(doc, si, sheet.name, rows, truncated)
        else:
            import openpyxl
            book = openpyxl.load_workbook(path, read_only=True, data_only=True)
            for si, name in enumerate(book.sheetnames):
                sheet = book[name]
                rows = []
                truncated = False
                for ri, row in enumerate(sheet.iter_rows(values_only=True)):
                    if ri >= READER_SHEET_MAX_ROWS:
                        truncated = True
                        break
                    if len(row) > READER_SHEET_MAX_COLS:
                        truncated = True
                    rows.append(['' if v is None else str(v)
                                 for v in row[:READER_SHEET_MAX_COLS]])
                _reader_sheet_page(doc, si, name, rows, truncated)
            try:
                book.close()
            except Exception:
                pass
    except Exception as exc:
        return _reader_error_document(path, _tr('Could not read the spreadsheet: %s') % exc)
    if not doc.pages:
        return _reader_error_document(path, _tr('The spreadsheet has no sheets.'))
    return doc


def reader_load_document(path):
    """Dispatch by extension. Worker-thread safe."""
    path = os.path.abspath(str(path or ''))
    if not os.path.isfile(path):
        return _reader_error_document(path, _tr('The file does not exist.'))
    ext = os.path.splitext(path)[1].lower()
    if ext == '.pdf':
        return _reader_load_pdf(path)
    if ext in ('.docx', '.doc'):
        return _reader_load_docx(path)
    if ext == '.pptx':
        return _reader_load_pptx(path)
    if ext in ('.xlsx', '.xlsm', '.xls', '.csv'):
        return _reader_load_sheet(path)
    if ext in READER_IMAGE_EXTS:
        return _reader_load_image(path)
    if reader_supported_file(path):
        return _reader_load_text(path)
    return _reader_error_document(
        path, _tr('Unsupported file type: %s') % (ext or _tr('(no extension)')))


# review fix: root every reader QThread (a GC'd running QThread aborts Qt) and
# stop them at quit — mirror of the editor LLM worker registry.
_READER_WORKERS = []
_READER_QUIT_HOOKED = [False]


def _reader_forget_worker(worker):
    try:
        _READER_WORKERS.remove(worker)
    except ValueError:
        pass


def _reader_stop_all_workers():
    for worker in list(_READER_WORKERS):
        try:
            worker.requestInterruption()
        except Exception:
            pass
    for worker in list(_READER_WORKERS):
        try:
            worker.wait(2000)
        except Exception:
            pass


def _reader_register_worker(worker):
    _READER_WORKERS.append(worker)
    try:
        worker.finished.connect(lambda w=worker: _reader_forget_worker(w),
                                Qt.ConnectionType.QueuedConnection)
    except Exception:
        pass
    if not _READER_QUIT_HOOKED[0]:
        _READER_QUIT_HOOKED[0] = True
        try:
            app.aboutToQuit.connect(_reader_stop_all_workers)
        except Exception:
            pass


class _ReaderLoadWorker(QThread):
    loaded = pyqtSignal(object)   # ReaderDocument
    failed = pyqtSignal(str)

    def __init__(self, path, parent=None):
        super().__init__(parent)
        self._path = str(path)

    def run(self):
        try:
            doc = reader_load_document(self._path)
            self.loaded.emit(doc)
        except Exception as exc:
            self.failed.emit(str(exc) or exc.__class__.__name__)


class _ReaderOcrWorker(QThread):
    """OCR an image file off-GUI (Apple Vision via the existing helper — a plain
    file path means no fitz/Qt objects cross threads). delete_after is for OUR
    temporary page rasters only — never the user's original image."""
    done = pyqtSignal(str)

    def __init__(self, image_path, parent=None, delete_after=True):
        super().__init__(parent)
        self._image_path = str(image_path)
        self._delete_after = bool(delete_after)

    def run(self):
        text = ''
        try:
            text = _vision_ocr_image_file(self._image_path) or ''
        except Exception:
            text = ''
        if self._delete_after:
            try:
                os.remove(self._image_path)
            except Exception:
                pass
        self.done.emit(text)


# ---- per-file translation cache (page number + target language → result) ----

def _reader_cache_dir(path):
    key = hashlib.sha1(os.path.abspath(str(path)).encode('utf-8', 'replace')).hexdigest()[:12]
    return os.path.join(READER_DATA_DIR, key)


def reader_translations_load(path):
    """{'mtime': …, 'size': …, 'targets': {lang: {page_key: {'text':…}|{'rows':…}}}}
    — dropped whole when the file changed on disk (mtime+size mismatch). The
    load-time identity RIDES IN THE DICT so a later save stamps the content the
    translations were actually computed from (review fix: re-statting at save
    time would bless stale translations under the file's NEW identity)."""
    try:
        stat = os.stat(path)
    except Exception:
        return {'targets': {}}
    identity = {'mtime': int(stat.st_mtime), 'size': int(stat.st_size)}
    cache_path = os.path.join(_reader_cache_dir(path), 'translations.json')
    try:
        with open(cache_path, 'r', encoding='utf-8') as f:
            data = json.load(f)
        if (isinstance(data, dict)
                and data.get('mtime') == identity['mtime']
                and data.get('size') == identity['size']
                and isinstance(data.get('targets'), dict)):
            return data
    except Exception:
        pass
    return {'mtime': identity['mtime'], 'size': identity['size'], 'targets': {}}


def reader_translations_save(path, data):
    if not isinstance(data, dict) or 'mtime' not in data or 'size' not in data:
        return  # no load-time identity → refuse to bless unknown content
    payload = {
        'file': os.path.abspath(str(path)),
        'mtime': int(data['mtime']),
        'size': int(data['size']),
        'targets': data.get('targets') if isinstance(data.get('targets'), dict) else {},
    }
    try:
        cache_dir = _reader_cache_dir(path)
        os.makedirs(cache_dir, exist_ok=True)
        cache_path = os.path.join(cache_dir, 'translations.json')
        tmp_path = cache_path + '.tmp'
        with open(tmp_path, 'w', encoding='utf-8') as f:
            json.dump(payload, f, ensure_ascii=False)
        os.replace(tmp_path, cache_path)
    except Exception:
        pass


def reader_translate_messages(source_lang, target_lang, page_text=None, image_b64=None,
                              table_rows=None, refine_selection=None, context_text='',
                              image_mime='image/png'):
    """One user-role message (relay drops system role). Exactly one of page_text /
    image_b64 / table_rows / refine_selection drives the request shape."""
    source_lang = str(source_lang or 'the source language')
    target_lang = str(target_lang or 'English')
    if refine_selection is not None:
        ctx = str(context_text or '')
        frag = str(refine_selection)
        fence = '````' if '```' in (ctx + frag) else '```'
        content = (
            'You are improving one sentence of an existing translation (%s → %s).\n'
            'Full source text of the page:\n%s\n%s\n%s\n'
            'The current translation of the page contains this fragment:\n%s\n%s\n%s\n'
            'Return ONLY the improved translation of that fragment — no explanations, '
            'no quotes around it.' % (source_lang, target_lang,
                                      fence, ctx, fence, fence, frag, fence))
        return [{'role': 'user', 'content': content}]
    if table_rows is not None:
        content = (
            'Translate every cell of this table from %s to %s. Keep numbers, codes and '
            'empty cells unchanged. Return ONLY JSON of exactly this shape (same row and '
            'column counts): {"rows": [["…", …], …]}\n%s'
            % (source_lang, target_lang, json.dumps(table_rows, ensure_ascii=False)))
        return [{'role': 'user', 'content': content}]
    if image_b64:
        instr = ('Translate all text visible in this page image from %s to %s. Output ONLY '
                 'the translation as plain text, keeping the reading order.'
                 % (source_lang, target_lang))
        mime = str(image_mime or 'image/png')
        return [{'role': 'user', 'content': [
            {'type': 'text', 'text': instr},
            {'type': 'image_url', 'image_url': {'url': 'data:%s;base64,%s' % (mime, image_b64)}},
        ]}]
    body = str(page_text or '')
    fence = '````' if '```' in body else '```'
    content = (
        'Translate the following text from %s to %s. Output ONLY the translation, '
        'no explanations.\n%s\n%s\n%s' % (source_lang, target_lang, fence, body, fence))
    return [{'role': 'user', 'content': content}]


def reader_parse_table_translation(text, expected_rows):
    """{'rows': [[…]]} tolerant parse; pads/clips to the expected shape."""
    raw = _editor_extract_json_object(text)
    if not raw:
        return None
    try:
        data = json.loads(raw)
    except Exception:
        return None
    rows = data.get('rows') if isinstance(data, dict) else None
    if not isinstance(rows, list):
        return None
    fixed = []
    for ri, expected in enumerate(expected_rows):
        got = rows[ri] if ri < len(rows) and isinstance(rows[ri], list) else []
        # null/missing cells fall back to the SOURCE cell (never the literal 'None')
        fixed.append([str(got[ci]) if ci < len(got) and got[ci] is not None
                      else str(expected[ci])
                      for ci in range(len(expected))])
    return fixed


from PyQt6.QtWidgets import QScrollArea as _ReaderQScrollArea


class _ReaderPageCanvas(QWidget):
    """Horizontal mode surface: ONE page, fit-to-view, short slide on flips
    (14ms/ease-out-cubic — the house animation family)."""
    page_flip_requested = pyqtSignal(int)

    def __init__(self, parent=None):
        super().__init__(parent)
        self._page = None
        self._prev_pixmap = None
        self._prev_rect = None
        self._slide_dir = 0
        self._slide_prog = 1.0
        self._dark = False
        self._wheel_acc = 0
        self._wheel_gesture_flipped = False
        self._timer = QTimer(self)
        self._timer.setInterval(14)
        self._timer.timeout.connect(self._tick)
        self.setMinimumSize(120, 120)

    def set_theme(self, dark):
        self._dark = bool(dark)
        self.update()

    def show_page(self, page, direction=0):
        if direction and self._page is not None and self._page is not page:
            self._prev_pixmap = self._page.render_pixmap(self._render_width())
            self._prev_rect = self._fit_rect(self._page)
            self._slide_dir = 1 if direction > 0 else -1
            self._slide_prog = 0.0
            self._timer.start()
        else:
            self._prev_pixmap = None
            self._slide_prog = 1.0
            self._timer.stop()
        self._page = page
        self.update()

    def _tick(self):
        self._slide_prog = min(1.0, self._slide_prog + 0.09)
        self.update()
        if self._slide_prog >= 1.0:
            self._prev_pixmap = None
            self._timer.stop()

    def _render_width(self):
        rect = self._fit_rect(self._page) if self._page else None
        return int(rect.width() * 2) if rect else 800

    def _fit_rect(self, page):
        if page is None:
            return QRectF(0, 0, 10, 10)
        avail_w = max(40.0, self.width() - 28.0)
        avail_h = max(40.0, self.height() - 28.0)
        aspect = page.aspect()
        w = min(avail_w, avail_h / aspect)
        h = w * aspect
        return QRectF((self.width() - w) / 2.0, (self.height() - h) / 2.0, w, h)

    def paintEvent(self, event):
        painter = QPainter(self)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)
        painter.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform)
        if self._page is None:
            painter.end()
            return
        rect = self._fit_rect(self._page)
        t = 1.0 - (1.0 - self._slide_prog) ** 3
        offset = 0.0
        if self._slide_prog < 1.0 and self._slide_dir:
            offset = self.width() * (1.0 - t) * self._slide_dir
            if self._prev_pixmap is not None and self._prev_rect is not None:
                prev_rect = QRectF(self._prev_rect)
                prev_rect.moveLeft(self._prev_rect.x() - self.width() * t * self._slide_dir)
                painter.drawPixmap(prev_rect, self._prev_pixmap,
                                   QRectF(self._prev_pixmap.rect()))
        draw_rect = QRectF(rect)
        draw_rect.moveLeft(rect.x() + offset)
        pm = self._page.render_pixmap(self._render_width())
        shadow = QColor(0, 0, 0, 40)
        painter.setPen(Qt.PenStyle.NoPen)
        painter.setBrush(QBrush(shadow))
        painter.drawRoundedRect(draw_rect.adjusted(-2, -1, 4, 5), 6, 6)
        if pm is not None:
            painter.drawPixmap(draw_rect, pm, QRectF(pm.rect()))
        else:
            painter.setBrush(QBrush(QColor('#3A3A3A' if self._dark else '#F2F2F7')))
            painter.drawRoundedRect(draw_rect, 6, 6)
            painter.setPen(QPen(QColor('#A7AEB8' if self._dark else '#6A717C')))
            painter.drawText(draw_rect, Qt.AlignmentFlag.AlignCenter, self._page.label)
        painter.end()

    def resizeEvent(self, event):
        super().resizeEvent(event)
        self.update()

    def wheelEvent(self, event):
        # review fix: macOS trackpad swipes carry a momentum tail — one gesture
        # must flip ONE page, and a direction change resets the accumulator
        try:
            phase = event.phase()
            if phase == Qt.ScrollPhase.ScrollBegin:
                self._wheel_acc = 0
                self._wheel_gesture_flipped = False
            elif phase == Qt.ScrollPhase.ScrollMomentum and self._wheel_gesture_flipped:
                event.accept()
                return
        except Exception:
            pass
        try:
            pixel = event.pixelDelta()
            angle = event.angleDelta()
            delta = pixel.x() if not pixel.isNull() and pixel.x() else (
                angle.x() or (pixel.y() if not pixel.isNull() else angle.y()))
        except Exception:
            delta = 0
        if not delta:
            super().wheelEvent(event)
            return
        if self._wheel_acc and (delta > 0) != (self._wheel_acc > 0):
            self._wheel_acc = 0
        self._wheel_acc += delta
        if abs(self._wheel_acc) >= 120:
            self.page_flip_requested.emit(-1 if self._wheel_acc > 0 else 1)
            self._wheel_acc = 0
            self._wheel_gesture_flipped = True
        event.accept()


class _ReaderPageSlot(QWidget):
    """Vertical mode: one fixed-size slot per page; renders lazily when the view
    marks it near the viewport (exact sizes are known up front, so realization
    never shifts the scroll position)."""

    def __init__(self, page, parent=None):
        super().__init__(parent)
        self.page = page
        self.render_enabled = False
        self._dark = False

    def set_theme(self, dark):
        self._dark = bool(dark)
        self.update()

    def paintEvent(self, event):
        painter = QPainter(self)
        painter.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform)
        rect = QRectF(4, 3, self.width() - 8, self.height() - 6)
        pm = self.page.render_pixmap(int(rect.width() * 2)) if self.render_enabled else None
        if pm is not None:
            painter.drawPixmap(rect, pm, QRectF(pm.rect()))
        else:
            painter.setPen(Qt.PenStyle.NoPen)
            painter.setBrush(QBrush(QColor('#3A3A3A' if self._dark else '#F2F2F7')))
            painter.drawRoundedRect(rect, 6, 6)
            painter.setPen(QPen(QColor('#A7AEB8' if self._dark else '#6A717C')))
            painter.drawText(rect, Qt.AlignmentFlag.AlignCenter, self.page.label)
        painter.end()


class ReaderView(QWidget):
    """Document surface: horizontal canvas / vertical scroll column for page
    documents; single read-only text view for plain text; one sheet at a time
    for spreadsheets. All right-clicks funnel into the window's reader menu."""
    current_page_changed = pyqtSignal(int)
    menu_requested = pyqtSignal(object)   # global QPoint

    def __init__(self, window, parent=None):
        super().__init__(parent)
        self._win = window
        self._doc = None
        self._orientation = 'horizontal'
        self._current = 0
        self._dark = False
        self._slots = []
        self._scroll_sync = False
        self._text_mono = False

        lay = QVBoxLayout(self)
        lay.setContentsMargins(0, 0, 0, 0)
        lay.setSpacing(0)
        self.stack = QStackedWidget(self)
        lay.addWidget(self.stack)

        self.message_lbl = QLabel('', self.stack)
        self.message_lbl.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self.message_lbl.setWordWrap(True)

        self.canvas = _ReaderPageCanvas(self.stack)
        self.canvas.page_flip_requested.connect(self.flip)

        self.scroll = _ReaderQScrollArea(self.stack)
        self.scroll.setFrameShape(QFrame.Shape.NoFrame)
        self.scroll.setWidgetResizable(False)
        self._scroll_body = QWidget()
        self._scroll_layout = QVBoxLayout(self._scroll_body)
        self._scroll_layout.setContentsMargins(10, 8, 10, 8)
        self._scroll_layout.setSpacing(10)
        self.scroll.setWidget(self._scroll_body)
        self.scroll.verticalScrollBar().valueChanged.connect(self._on_scrolled)

        self.text_view = QPlainTextEdit(self.stack)
        self.text_view.setReadOnly(True)
        self.text_view.setFrameShape(QFrame.Shape.NoFrame)

        self.table_view = QTableWidget(0, 0, self.stack)
        self.table_view.setEditTriggers(QAbstractItemView.EditTrigger.NoEditTriggers)
        self.table_view.verticalHeader().setVisible(False)
        self.table_view.setFrameShape(QFrame.Shape.NoFrame)

        for w in (self.message_lbl, self.canvas, self.scroll, self.text_view, self.table_view):
            self.stack.addWidget(w)
            w.setContextMenuPolicy(Qt.ContextMenuPolicy.CustomContextMenu)
        self.message_lbl.customContextMenuRequested.connect(self._forward_menu_from(self.message_lbl))
        self.canvas.customContextMenuRequested.connect(self._forward_menu_from(self.canvas))
        self.text_view.customContextMenuRequested.connect(self._forward_menu_from(self.text_view))
        self.table_view.customContextMenuRequested.connect(self._forward_menu_from(self.table_view))
        self.scroll.viewport().setContextMenuPolicy(Qt.ContextMenuPolicy.CustomContextMenu)
        self.scroll.viewport().customContextMenuRequested.connect(
            self._forward_menu_from(self.scroll.viewport()))
        self.show_message(_tr('Open a file from an attachment card: right-click → Open in Reader.'))

    def _forward_menu_from(self, widget):
        return lambda pos, w=widget: self.menu_requested.emit(w.mapToGlobal(pos))

    # ---- state ----
    def document(self):
        return self._doc

    def current_page(self):
        if self._doc and 0 <= self._current < len(self._doc.pages):
            return self._doc.pages[self._current]
        return None

    def orientation(self):
        return self._orientation

    def show_message(self, text):
        self.stack.setCurrentWidget(self.message_lbl)
        self.message_lbl.setText(str(text or ''))

    def set_document(self, doc, orientation):
        self._doc = doc
        self._current = 0
        self._orientation = orientation if orientation in ('horizontal', 'vertical') else 'horizontal'
        self._rebuild()
        self.current_page_changed.emit(self._current)

    def set_orientation(self, mode):
        mode = mode if mode in ('horizontal', 'vertical') else 'horizontal'
        if self._orientation == mode:
            return
        self._orientation = mode
        self._rebuild(preserve_page=True)

    def _clear_slots(self):
        for slot in self._slots:
            try:
                self._scroll_layout.removeWidget(slot)
                slot.deleteLater()
            except Exception:
                pass
        self._slots = []

    def _rebuild(self, preserve_page=False):
        doc = self._doc
        current = self._current if preserve_page else 0
        self._clear_slots()
        if doc is None:
            self.show_message('')
            return
        if doc.kind in ('text', 'error') or (doc.pages and doc.pages[0].kind == 'stream'):
            page = doc.pages[0] if doc.pages else None
            body = (page.plain_text if page else '') or doc.error
            self.text_view.setPlainText(body)
            self._text_mono = os.path.splitext(doc.path)[1].lower() in {
                '.py', '.js', '.ts', '.json', '.sh', '.c', '.h', '.cpp', '.rs', '.go', '.java', '.css'}
            self.text_view.setStyleSheet(self._text_css(self._text_mono))
            self.stack.setCurrentWidget(self.text_view)
            self._current = 0
            return
        if doc.kind == 'sheet':
            self._current = max(0, min(current, len(doc.pages) - 1))
            self._fill_table(self.table_view, doc.pages[self._current].rows or [])
            self.stack.setCurrentWidget(self.table_view)
            return
        # pixmap document
        self._current = max(0, min(current, len(doc.pages) - 1))
        if self._orientation == 'horizontal':
            self.stack.setCurrentWidget(self.canvas)
            self.canvas.show_page(doc.pages[self._current])
        else:
            for page in doc.pages:
                slot = _ReaderPageSlot(page, self._scroll_body)
                slot.set_theme(self._dark)
                self._slots.append(slot)
                self._scroll_layout.addWidget(slot)
            self.stack.setCurrentWidget(self.scroll)
            self._relayout_slots()
            self._scroll_to_page(self._current)
            self._update_visible_slots()

    def _fill_table(self, table, rows):
        table.clearContents()
        n_rows = len(rows)
        n_cols = max((len(r) for r in rows), default=0)
        table.setRowCount(n_rows)
        table.setColumnCount(n_cols)
        table.setHorizontalHeaderLabels([_reader_col_name(i) for i in range(n_cols)])
        for ri, row in enumerate(rows):
            for ci in range(n_cols):
                table.setItem(ri, ci, QTableWidgetItem(str(row[ci]) if ci < len(row) else ''))
        # review fix: a sheet flip must not inherit the previous sheet's scroll
        table.scrollToTop()
        try:
            table.horizontalScrollBar().setValue(0)
        except Exception:
            pass

    # ---- paging ----
    def flip(self, delta):
        if not self._doc or not self._doc.pages:
            return
        self.go_to(self._current + int(delta), direction=int(delta))

    def go_to(self, index, direction=0):
        doc = self._doc
        if not doc or not doc.pages:
            return
        index = max(0, min(int(index), len(doc.pages) - 1))
        if index == self._current and direction != 0:
            return
        self._current = index
        if doc.kind == 'sheet':
            self._fill_table(self.table_view, doc.pages[index].rows or [])
        elif doc.kind in ('text', 'error'):
            pass
        elif self._orientation == 'horizontal':
            self.canvas.show_page(doc.pages[index], direction)
        else:
            self._scroll_to_page(index)
            self._update_visible_slots()
        self.current_page_changed.emit(index)

    # ---- vertical machinery ----
    def _relayout_slots(self):
        width = max(160, self.scroll.viewport().width() - 20)
        for slot in self._slots:
            h = int(width * slot.page.aspect())
            slot.setFixedSize(width, h)
        # widgetResizable is False (the column must NOT track the viewport
        # height) — the body has to adopt the layout's total size itself
        self._scroll_layout.activate()
        self._scroll_body.adjustSize()

    def _scroll_to_page(self, index):
        if not (0 <= index < len(self._slots)):
            return
        self._scroll_sync = True
        try:
            self.scroll.verticalScrollBar().setValue(self._slots[index].y() - 8)
        finally:
            self._scroll_sync = False
        self._update_visible_slots()

    def _update_visible_slots(self):
        viewport = self.scroll.viewport()
        top = self.scroll.verticalScrollBar().value()
        bottom = top + viewport.height()
        for slot in self._slots:
            near = slot.y() + slot.height() >= top - viewport.height() and \
                slot.y() <= bottom + viewport.height()
            if near and not slot.render_enabled:
                slot.render_enabled = True
                slot.update()
            elif not near and slot.render_enabled:
                slot.render_enabled = False
                slot.page.drop_pixmap()

    def _on_scrolled(self, value):
        if self._scroll_sync or not self._slots:
            return
        self._update_visible_slots()
        bar = self.scroll.verticalScrollBar()
        # scrollbar extremes clamp to first/last page (a short last page can
        # never reach the viewport center — plan-review fix)
        if value <= 0:
            idx = 0
        elif value >= bar.maximum():
            idx = len(self._slots) - 1
        else:
            center = value + self.scroll.viewport().height() // 2
            idx = self._current
            for i, slot in enumerate(self._slots):
                if slot.y() <= center <= slot.y() + slot.height():
                    idx = i
                    break
        if idx != self._current:
            self._current = idx
            self.current_page_changed.emit(idx)

    def resizeEvent(self, event):
        super().resizeEvent(event)
        if self._slots:
            self._relayout_slots()
            self._update_visible_slots()

    # ---- theme ----
    def _text_css(self, mono):
        fg = '#F2F2F7' if self._dark else '#20242B'
        font = "font-family: Menlo, monospace; font-size: 12px;" if mono else "font-size: 14px;"
        return ('QPlainTextEdit { border: none; background: transparent; color: %s; %s '
                'padding: 8px; }' % (fg, font))

    def set_theme(self, dark):
        self._dark = bool(dark)
        self.canvas.set_theme(self._dark)
        for slot in self._slots:
            slot.set_theme(self._dark)
        muted = '#A7AEB8' if self._dark else '#6A717C'
        self.message_lbl.setStyleSheet(
            'color: %s; font-size: 15px; background: transparent; padding: 24px;' % muted)
        # review fix: a theme flip must not silently drop the mono styling
        self.text_view.setStyleSheet(self._text_css(getattr(self, '_text_mono', False)))
        try:
            self.table_view.setStyleSheet(_settings_tableview_stylesheet(self._dark))
        except Exception:
            pass
        self.scroll.setStyleSheet('QScrollArea { border: none; background: transparent; }')
        self._scroll_body.setStyleSheet('background: transparent;')


def _reader_col_name(index):
    name = ''
    index = int(index)
    while True:
        name = chr(ord('A') + index % 26) + name
        index = index // 26 - 1
        if index < 0:
            return name


class ReaderTranslatePanel(QWidget):
    """Right-side translation pane. Translates the CURRENT left page into the
    target language; remembers translated pages per file+target on disk; can
    auto-translate on page flips (debounced); selecting text in the result can
    re-translate just that sentence."""

    def __init__(self, window, parent=None):
        super().__init__(parent)
        self._win = window
        self._dark = False
        self._doc_path = ''
        self._mem = {}
        self._disk = {'targets': {}}
        self._workers = []
        self._inflight_key = None
        self._pending_request = None   # round 2: ONE parked request, latest wins
        self._refine_selecting = None
        self.auto_translate = False
        self._auto_timer = QTimer(self)
        self._auto_timer.setSingleShot(True)
        self._auto_timer.setInterval(400)
        self._auto_timer.timeout.connect(self._auto_fire)

        lay = QVBoxLayout(self)
        lay.setContentsMargins(8, 0, 0, 0)
        lay.setSpacing(6)
        top = QHBoxLayout()
        top.setSpacing(6)
        items = load_language_items()
        self.src_combo = DropdownButton(self, compact_light=True)
        self.tgt_combo = DropdownButton(self, compact_light=True)
        for item in items:
            self.src_combo.addItem(item)
            self.tgt_combo.addItem(item)
        for combo in (self.src_combo, self.tgt_combo):
            combo.setFitToCurrentText(True)   # the whole language name, not "C…"
        self.src_combo.setCurrentIndex(0 if items else -1)
        tgt_idx = preferred_runtime_translate_target_index(items)
        if tgt_idx < 0:
            # guaranteed-empty first-launch state (plan review): preselect the
            # first list item that differs from the source so Translate just works
            tgt_idx = next((i for i, it in enumerate(items)
                            if it != self.src_combo.currentText()), -1)
        self.tgt_combo.setCurrentIndex(tgt_idx)

        def _on_target_changed(_i):
            remember_runtime_translate_target_language(self.tgt_combo.currentText())
            # review fix: the pane must not keep showing the OLD target's text
            # under the new target — refresh to the new target's cache state
            self.on_page_changed(None)

        self.tgt_combo.currentIndexChanged.connect(_on_target_changed)
        arrow = QLabel('→')
        self._arrow_lbl = arrow
        self.translate_btn = EditorCapsuleButton(_tr('Translate'))
        self.translate_btn.clicked.connect(lambda: self.translate_current(force=True))
        self.status_lbl = QLabel('')
        top.addWidget(self.src_combo)
        top.addWidget(arrow)
        top.addWidget(self.tgt_combo)
        top.addWidget(self.translate_btn)
        top.addStretch(1)
        lay.addLayout(top)
        lay.addWidget(self.status_lbl)

        self.body = QStackedWidget(self)
        self.browser = QTextBrowser(self.body)
        self.browser.setFrameShape(QFrame.Shape.NoFrame)
        self.browser.setOpenLinks(False)
        self.browser.setContextMenuPolicy(Qt.ContextMenuPolicy.CustomContextMenu)
        self.browser.customContextMenuRequested.connect(self._show_browser_menu)
        self.table = QTableWidget(0, 0, self.body)
        self.table.setEditTriggers(QAbstractItemView.EditTrigger.NoEditTriggers)
        self.table.verticalHeader().setVisible(False)
        self.table.setFrameShape(QFrame.Shape.NoFrame)
        self.body.addWidget(self.browser)
        self.body.addWidget(self.table)
        lay.addWidget(self.body, 1)

    # ---- lifecycle ----
    def attach_document(self, path):
        self.stop_workers()
        self._doc_path = str(path or '')
        self._mem = {}
        self._disk = reader_translations_load(self._doc_path) if self._doc_path else {'targets': {}}
        self._inflight_key = None
        self.browser.setPlainText('')
        self.table.setRowCount(0)
        self.body.setCurrentWidget(self.browser)
        self._set_status('')
        self._update_controls()

    def stop_workers(self):
        for worker in self._workers:
            try:
                worker.stop()
            except Exception:
                pass
        self._workers = []
        self._inflight_key = None
        self._pending_request = None
        self._update_controls()

    # ---- round 2: strict serialization — ONE request in flight, ONE parked ----
    def _update_controls(self):
        """Manual Translate is unavailable while auto-translate handles paging or
        while a request is streaming — the queue can never pile up."""
        try:
            busy = self._inflight_key is not None
            self.translate_btn.setEnabled(not busy and not self.auto_translate)
            if self.auto_translate:
                self.translate_btn.setToolTip(_tr('Auto-translate is on — pages translate on flip'))
            elif busy:
                self.translate_btn.setToolTip(_tr('A translation is already running'))
            else:
                self.translate_btn.setToolTip('')
        except Exception:
            pass

    def _drain_pending(self):
        pending = self._pending_request
        self._pending_request = None
        if pending is None or not self.isVisible() or self._inflight_key is not None:
            return
        QTimer.singleShot(0, lambda f=bool(pending.get('force')): self.translate_current(force=f))

    def _set_status(self, text):
        self.status_lbl.setText(str(text or ''))

    def _target(self):
        return str(self.tgt_combo.currentText() or '').strip()

    def _source(self):
        return str(self.src_combo.currentText() or '').strip() or 'the source language'

    @staticmethod
    def page_key(page):
        return 'p%d' % page.index

    def cached_result(self, page, target):
        key = (self.page_key(page), target)
        if key in self._mem:
            return self._mem[key]
        disk = ((self._disk.get('targets') or {}).get(target) or {}).get(self.page_key(page))
        if isinstance(disk, dict):
            self._mem[key] = disk
            return disk
        return None

    @staticmethod
    def _partial_suffix(cached):
        if isinstance(cached, dict) and cached.get('partial'):
            return ' ' + str(cached['partial'])
        return ''

    def _store_result(self, page, target, value):
        key = (self.page_key(page), target)
        self._mem[key] = value
        targets = self._disk.setdefault('targets', {})
        targets.setdefault(target, {})[self.page_key(page)] = value
        if self._doc_path:
            reader_translations_save(self._doc_path, self._disk)

    # ---- display ----
    def _show_result(self, page, value):
        if isinstance(value, dict) and isinstance(value.get('rows'), list):
            rows = value['rows']
            self.table.clearContents()
            self.table.setRowCount(len(rows))
            n_cols = max((len(r) for r in rows), default=0)
            self.table.setColumnCount(n_cols)
            self.table.setHorizontalHeaderLabels([_reader_col_name(i) for i in range(n_cols)])
            for ri, row in enumerate(rows):
                for ci in range(n_cols):
                    self.table.setItem(ri, ci, QTableWidgetItem(str(row[ci]) if ci < len(row) else ''))
            self.table.scrollToTop()
            try:
                self.table.horizontalScrollBar().setValue(0)
            except Exception:
                pass
            self.body.setCurrentWidget(self.table)
        else:
            self.browser.setPlainText(str((value or {}).get('text', '') if isinstance(value, dict) else value or ''))
            self.body.setCurrentWidget(self.browser)

    # ---- entry points ----
    def on_page_changed(self, _index):
        page = self._win.view.current_page()
        target = self._target()
        if page is None or not self.isVisible():
            return
        cached = self.cached_result(page, target) if target else None
        if cached is not None:
            self._show_result(page, cached)
            self._set_status(_tr('Page %d — translated (cached)%s')
                             % (page.index + 1, self._partial_suffix(cached)))
            return
        self.browser.setPlainText('')
        self.table.setRowCount(0)
        self.body.setCurrentWidget(self.browser)
        if self.auto_translate and target:
            self._set_status(_tr('Auto-translate queued…'))
            self._auto_timer.start()   # debounced: momentum scrolling settles first
        else:
            self._set_status(_tr('Page %d — not translated yet') % (page.index + 1))

    def _auto_fire(self):
        if self.auto_translate and self.isVisible():
            self.translate_current(force=False)

    def translate_current(self, force=False):
        page = self._win.view.current_page()
        if page is None:
            self._set_status(_tr('Nothing to translate'))
            return
        target = self._target()
        if not target:
            self._set_status(_tr('Choose a target language first'))
            return
        key = (self.page_key(page), target)
        cached = self.cached_result(page, target)
        if cached is not None and not force:
            self._show_result(page, cached)
            self._set_status(_tr('Page %d — translated (cached)%s')
                             % (page.index + 1, self._partial_suffix(cached)))
            return
        if self._inflight_key is not None:
            if self._inflight_key == key:
                return  # this exact page+target is already streaming
            # round 2: NEVER stack concurrent requests — park exactly one, the
            # latest wish wins (re-resolves the CURRENT page when it runs)
            self._pending_request = {'force': bool(force)}
            self._set_status(_tr('Queued — one translation at a time'))
            return
        if page.kind == 'table':
            rows = [r[:READER_TRANSLATE_TABLE_COLS]
                    for r in (page.rows or [])[:READER_TRANSLATE_TABLE_ROWS]]
            clipped = (len(page.rows or []) > READER_TRANSLATE_TABLE_ROWS
                       or any(len(r) > READER_TRANSLATE_TABLE_COLS for r in (page.rows or [])))
            messages = reader_translate_messages(self._source(), target, table_rows=rows)
            self._send(page, target, messages, table_rows=rows,
                       note=_tr('(first %dx%d cells)') % (READER_TRANSLATE_TABLE_ROWS,
                                                     READER_TRANSLATE_TABLE_COLS) if clipped else '')
            return
        text = str(page.plain_text or '').strip()
        if text:
            # review fix: a stream document is ONE page — never ship a multi-MB
            # file as a single prompt
            clipped = len(text) > READER_TRANSLATE_TEXT_CHARS
            messages = reader_translate_messages(
                self._source(), target, page_text=text[:READER_TRANSLATE_TEXT_CHARS])
            self._send(page, target, messages,
                       note=(_tr('(first %d characters)') % READER_TRANSLATE_TEXT_CHARS) if clipped else '',
                       partial=clipped)
            return
        # no text layer: OCR the page (existing Apple-Vision helper) — image
        # documents OCR their ORIGINAL file for best quality — and only if OCR
        # finds nothing send the image itself to the model
        doc = page.doc
        is_image_doc = doc is not None and doc.kind == 'image'
        pm = page.render_pixmap(1400)
        if pm is None and not is_image_doc:
            self._set_status(_tr('This page has nothing to translate'))
            return
        if is_image_doc:
            ocr_path = doc.path
            delete_after = False
        else:
            try:
                os.makedirs(READER_DATA_DIR, exist_ok=True)
                ocr_path = os.path.join(READER_DATA_DIR, 'ocr_tmp_%d.png' % int(time.time() * 1000))
                pm.save(ocr_path, 'PNG')
                delete_after = True
            except Exception:
                self._set_status(_tr('Could not rasterize the page'))
                return
        self._set_status(_tr('Recognizing text on the page…'))
        ocr = _ReaderOcrWorker(ocr_path, delete_after=delete_after)
        self._workers.append(ocr)
        doc_path_at_dispatch = self._doc_path
        # review fix: the OCR leg is part of the translation — mark it in-flight
        # so a second click cannot dispatch duplicate OCR + LLM work
        self._inflight_key = key
        self._update_controls()

        def on_ocr(text_found, page=page, target=target, pm=pm,
                   doc_path=doc_path_at_dispatch, key=key):
            # review fix (major): the OCR thread cannot be stopped — membership
            # in _workers is the cancellation token. stop_workers() rebuilt the
            # list, so a stale OCR completing later must NOT re-dispatch an LLM
            # stream next to a newer one (it would break the one-in-flight
            # invariant and stomp the pending slot).
            if ocr not in self._workers:
                return
            self._workers.remove(ocr)
            if not self.isVisible() or self._doc_path != doc_path:
                if self._inflight_key == key:
                    self._inflight_key = None
                self._update_controls()
                self._drain_pending()
                return
            text_found = str(text_found or '').strip()
            if text_found:
                messages = reader_translate_messages(self._source(), target, page_text=text_found)
                self._send(page, target, messages)
                return
            b64, mime = self._image_attachment_b64(page, pm)
            if not b64:
                if self._inflight_key == key:
                    self._inflight_key = None
                self._set_status(_tr('This page has nothing to translate'))
                self._update_controls()
                self._drain_pending()
                return
            messages = reader_translate_messages(self._source(), target,
                                                 image_b64=b64, image_mime=mime)
            self._send(page, target, messages, note=_tr('(from page image)'))

        ocr.done.connect(on_ocr, Qt.ConnectionType.QueuedConnection)
        _reader_register_worker(ocr)
        ocr.start()

    def _image_attachment_b64(self, page, pm):
        """Original file bytes for small standard-format image documents (best
        fidelity), else the rendered pixmap as PNG. Returns (b64, mime)."""
        doc = page.doc
        if doc is not None and doc.kind == 'image':
            try:
                ext = os.path.splitext(doc.path)[1].lower()
                if (ext in ('.png', '.jpg', '.jpeg', '.webp', '.gif')
                        and os.path.getsize(doc.path) <= READER_IMAGE_ATTACH_MAX_BYTES):
                    mime = 'image/jpeg' if ext in ('.jpg', '.jpeg') else 'image/' + ext.lstrip('.')
                    with open(doc.path, 'rb') as f:
                        return base64.b64encode(f.read()).decode('ascii'), mime
            except Exception:
                pass
        if pm is None:
            return None, None
        try:
            buffer = QBuffer()
            buffer.open(QIODevice.OpenModeFlag.WriteOnly)
            pm.scaledToWidth(min(1100, pm.width()),
                             Qt.TransformationMode.SmoothTransformation).save(buffer, 'PNG')
            return base64.b64encode(bytes(buffer.data())).decode('ascii'), 'image/png'
        except Exception:
            return None, None

    def _send(self, page, target, messages, table_rows=None, note='', partial=False):
        key = (self.page_key(page), target)
        doc_path_at_send = self._doc_path
        self._inflight_key = key
        self._update_controls()
        self._set_status(_tr('Translating page %d…%s') % (page.index + 1, (' ' + note) if note else ''))
        if table_rows is None:
            self.browser.setPlainText('')
            self.body.setCurrentWidget(self.browser)
        chunks = []

        def on_delta(piece, key=key, page=page):
            if self._inflight_key != key or table_rows is not None:
                return
            chunks.append(piece)   # ALWAYS accumulate — repaint resumes on flip-back
            # review fix: never paint another page's stream over the page on
            # screen (flipping shows a cached translation; the old stream must
            # not overwrite it)
            current = self._win.view.current_page()
            if current is not None and current.index == page.index:
                self.browser.setPlainText(''.join(chunks))

        def on_finished(text, key=key, page=page, target=target,
                        doc_path=doc_path_at_send):
            if self._inflight_key == key:
                self._inflight_key = None
            self._update_controls()
            if self._doc_path != doc_path:
                self._drain_pending()
                return  # belt: never store a result under another document
            if table_rows is not None:
                rows = reader_parse_table_translation(text, table_rows)
                if rows is None:
                    self._set_status(_tr('The model did not return a valid table'))
                    self._drain_pending()
                    return
                value = {'rows': rows}
                if note:
                    # review fix: a clipped table must not present as complete
                    # on later cache hits
                    value['partial'] = note
            else:
                value = {'text': str(text or '').strip()}
                if note and partial:  # explicit flag: the note text is translated
                    value['partial'] = note
            self._store_result(page, target, value)
            current = self._win.view.current_page()
            if current is not None and current.index == page.index:
                self._show_result(page, value)
                self._set_status(_tr('Page %d — translated%s') % (page.index + 1,
                                                             (' ' + note) if note else ''))
            self._drain_pending()

        def on_failed(message, key=key):
            if self._inflight_key == key:
                self._inflight_key = None
            self._update_controls()
            self._set_status(_tr('Translation failed: %s') % str(message or '')[:120])
            self._drain_pending()

        worker = editor_llm_request(messages, on_delta, on_finished, on_failed)
        self._workers.append(worker)

    # ---- selection re-translate ----
    def _show_browser_menu(self, pos):
        menu = style_broccoli_context_menu(QMenu(self))
        cursor = self.browser.textCursor()
        has_sel = bool(cursor.selectedText().strip())
        retr_act = menu.addAction(_tr('Re-translate This Sentence'))
        retr_act.setEnabled(has_sel and self._inflight_key is None)
        copy_act = menu.addAction(_tr('Copy'))
        copy_act.setEnabled(has_sel)
        act = menu.exec(self.browser.mapToGlobal(pos))
        if act == copy_act:
            try:
                QApplication.clipboard().setText(cursor.selectedText().replace(' ', '\n'))
            except Exception:
                pass
        elif act == retr_act:
            self._retranslate_selection(cursor)

    def _retranslate_selection(self, cursor):
        page = self._win.view.current_page()
        target = self._target()
        fragment = cursor.selectedText().replace(' ', '\n').strip()
        if page is None or not target or not fragment:
            return
        if self._inflight_key is not None:
            return  # a translation/refine is already streaming
        key = (self.page_key(page), target)
        messages = reader_translate_messages(
            self._source(), target, refine_selection=fragment,
            context_text=str(page.plain_text or '')[:8000])
        self._set_status(_tr('Re-translating the selection…'))
        sel_start, sel_end = cursor.selectionStart(), cursor.selectionEnd()
        # review fix (critical): capture the dispatch context — the reply must be
        # DISCARDED if the document, the page, or the browser content changed,
        # or the splice would corrupt another page's translation and persist the
        # corruption under the old page's cache key.
        doc_path_at_send = self._doc_path
        base_text = self.browser.toPlainText()
        self._inflight_key = key
        self._update_controls()

        def on_finished(text, page=page, target=target, key=key,
                        doc_path=doc_path_at_send, base_text=base_text):
            if self._inflight_key == key:
                self._inflight_key = None
            self._update_controls()
            self._drain_pending()
            improved = str(text or '').strip().strip('"“”')
            if not improved:
                self._set_status(_tr('Empty answer — selection kept'))
                return
            current = self._win.view.current_page()
            if (self._doc_path != doc_path or current is None
                    or current.index != page.index
                    or self.browser.toPlainText() != base_text):
                self._set_status(_tr('Content changed — re-translation discarded'))
                return
            replace_cursor = self.browser.textCursor()
            replace_cursor.setPosition(sel_start)
            replace_cursor.setPosition(sel_end, QTextCursor.MoveMode.KeepAnchor)
            replace_cursor.insertText(improved)
            self._store_result(page, target, {'text': self.browser.toPlainText()})
            self._set_status(_tr('Selection re-translated'))

        def on_failed(message, key=key):
            if self._inflight_key == key:
                self._inflight_key = None
            self._update_controls()
            self._drain_pending()
            self._set_status(_tr('Re-translate failed: %s') % str(message or '')[:120])

        worker = editor_llm_request(messages, lambda _d: None, on_finished, on_failed)
        self._workers.append(worker)

    # ---- theme ----
    def set_theme(self, dark):
        self._dark = bool(dark)
        fg = '#F2F2F7' if self._dark else '#20242B'
        muted = '#A7AEB8' if self._dark else '#6A717C'
        self.status_lbl.setStyleSheet('color: %s; font-size: 11px; background: transparent;' % muted)
        self._arrow_lbl.setStyleSheet('color: %s; background: transparent;' % muted)
        self.browser.setStyleSheet(
            'QTextBrowser { border: none; background: transparent; color: %s; font-size: 14px; }' % fg)
        try:
            self.table.setStyleSheet(_settings_tableview_stylesheet(self._dark))
        except Exception:
            pass
        try:
            self.translate_btn.apply_capsule_theme(self._dark)
            self.src_combo._update_style()
            self.tgt_combo._update_style()
        except Exception:
            pass


class ReaderWindow(QWidget):
    """FIX-39: single read-only reader window (lazy singleton on MyWidget, same
    frameless chrome family as EditorWindow; never parented to the main window)."""

    def __init__(self, main_window):
        super().__init__(None)
        self._main = main_window
        self.radius = 36
        self.drag_pos = None
        self._resize_active = False
        self._resize_origin = None
        self._resize_start_geo = None
        self._doc = None
        self._load_generation = 0
        self._load_workers = []
        self._prefs = reader_prefs_load()
        self._orientation_before_translate = None
        self._dock_anim = None
        self._main_move_anim = None
        try:
            self._dark_mode = bool(is_dark_theme(QApplication.instance()))
        except Exception:
            self._dark_mode = False
        try:
            always_on_top = bool(load_settings_store().get('globals', {}).get('editor_always_on_top', True))
        except Exception:
            always_on_top = True
        flags = Qt.WindowType.FramelessWindowHint | Qt.WindowType.Window
        if always_on_top:
            flags |= Qt.WindowType.WindowStaysOnTopHint
        self.setWindowFlags(flags)
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground)
        self.setAttribute(Qt.WidgetAttribute.WA_NoSystemBackground)
        # same size family as the editor: golden-ratio companion of the main
        # window's height, docked to its left (identical minimums → identical
        # docked geometry)
        self.setMinimumSize(BROCCOLI_DOCK_MIN_W, BROCCOLI_DOCK_MIN_H)
        self.resize(920, 570)   # landscape golden default
        self.setWindowTitle(_tr('Broccoli Reader'))
        self.setMouseTracking(True)
        self._build_ui()

    def _build_ui(self):
        self.close_button = MacWindowButton('#FF605C', 'x', self)
        self.close_button.move(10, 10)
        self.close_button.clicked.connect(self.hide)

        root = QVBoxLayout(self)
        root.setContentsMargins(18, 40, 18, 14)
        root.setSpacing(8)
        top = QHBoxLayout()
        top.setSpacing(8)
        # review fix: at the 560px docked width a long filename hard-clipped
        # mid-glyph — the eliding label shows '…' instead. tooltip stays managed
        # by _adopt_document (full path — a superset of the name).
        self.title_lbl = _ElidingLabel(_tr('Reader'))
        self.page_lbl = QLabel('')
        self.prev_btn = EditorCapsuleButton('‹')
        self.next_btn = EditorCapsuleButton('›')
        self.prev_btn.clicked.connect(lambda: self.view.flip(-1))
        self.next_btn.clicked.connect(lambda: self.view.flip(1))
        self.translate_toggle = EditorCapsuleButton(_tr('Translate'))
        self.translate_toggle.clicked.connect(lambda: self.toggle_translate())
        self.redock_btn = EditorCapsuleButton(_tr('Re-dock'))   # size + position
        self.redock_btn.clicked.connect(lambda: self.position_beside_main(animated=True))
        # stretch 1 on the title: _ElidingLabel's width policy is Ignored, so
        # without stretch it would collapse next to an addStretch spacer
        top.addWidget(self.title_lbl, 1)
        top.addWidget(self.page_lbl)
        top.addWidget(self.prev_btn)
        top.addWidget(self.next_btn)
        top.addWidget(self.translate_toggle)
        top.addWidget(self.redock_btn)
        root.addLayout(top)

        content = QHBoxLayout()
        content.setSpacing(0)
        self.view = ReaderView(self)
        self.panel = ReaderTranslatePanel(self)
        self.panel.setVisible(False)
        content.addWidget(self.view, 1)
        content.addWidget(self.panel, 1)
        root.addLayout(content, 1)

        self.view.current_page_changed.connect(self._on_page_changed)
        self.view.menu_requested.connect(self._show_reader_menu)
        self.panel.auto_translate = bool(self._prefs.get('auto_translate'))
        self.panel._update_controls()
        self.close_button.raise_()

    # ---- open / load (generation token: a newer open supersedes the load) ----
    def open_path(self, path):
        path = os.path.abspath(str(path or ''))
        self._load_generation += 1
        generation = self._load_generation
        self.panel.stop_workers()
        self.title_lbl.setText(os.path.basename(path))
        self.page_lbl.setText('')
        self.view.show_message(_tr('Loading %s…') % os.path.basename(path))
        worker = _ReaderLoadWorker(path)
        self._load_workers.append(worker)

        def on_loaded(doc, generation=generation, worker=worker):
            if worker in self._load_workers:
                self._load_workers.remove(worker)
            if generation != self._load_generation:
                try:
                    doc.close()
                except Exception:
                    pass
                return
            self._adopt_document(doc)

        def on_failed(message, generation=generation, worker=worker):
            if worker in self._load_workers:
                self._load_workers.remove(worker)
            if generation != self._load_generation:
                return
            self.view.show_message(_tr('Could not open the file: %s') % message)

        worker.loaded.connect(on_loaded, Qt.ConnectionType.QueuedConnection)
        worker.failed.connect(on_failed, Qt.ConnectionType.QueuedConnection)
        _reader_register_worker(worker)
        worker.start()
        if not self.isVisible():
            self.position_beside_main()   # same dock as the editor
            self.show()
        self.raise_()
        self.activateWindow()

    def position_beside_main(self, animated=False):
        """Re-dock (SIZE + POSITION) — the same dock as the editor: as tall as the main
        window's panel, a golden width or what fits, left (else right) of it."""
        if self._main is None:
            self._position_initial()
            return
        # a visible Editor is the sibling to avoid (mirror of the editor's logic)
        avoid = None
        try:
            sibling_getter = getattr(self._main, 'editor_window_if_open', None)
            sibling = sibling_getter() if callable(sibling_getter) else None
            if sibling is not None and sibling is not self:
                avoid = QRect(sibling.frameGeometry())
        except Exception:
            avoid = None
        target, main_target = broccoli_companion_dock_rect(self, self._main, avoid_rect=avoid)
        if main_target is not None:
            try:
                self._main_move_anim = QPropertyAnimation(self._main, b'geometry', self)
                self._main_move_anim.setDuration(260)
                self._main_move_anim.setStartValue(QRect(self._main.frameGeometry()))
                self._main_move_anim.setEndValue(main_target)
                self._main_move_anim.setEasingCurve(QEasingCurve.Type.OutCubic)
                self._main_move_anim.start()
            except Exception:
                try:
                    self._main.move(main_target.left(), main_target.top())
                except Exception:
                    pass
        if animated and self.isVisible():
            self._dock_anim = QPropertyAnimation(self, b'geometry', self)
            self._dock_anim.setDuration(260)
            self._dock_anim.setStartValue(QRect(self.geometry()))
            self._dock_anim.setEndValue(target)
            self._dock_anim.setEasingCurve(QEasingCurve.Type.OutCubic)
            self._dock_anim.start()
        else:
            self.setGeometry(target)

    def _adopt_document(self, doc):
        old = self._doc
        doc.finalize_on_gui()
        self._doc = doc
        if old is not None:
            try:
                old.close()
            except Exception:
                pass
        orientation = reader_default_orientation(self._prefs_kind(doc), self._prefs)
        if self.panel.isVisible() and doc.kind not in ('text', 'error', 'sheet'):
            self._orientation_before_translate = orientation
            orientation = 'vertical'
        self.view.set_document(doc, orientation)
        self.panel.attach_document(doc.path)
        self.title_lbl.setText(os.path.basename(doc.path))
        note = doc.note or (doc.pages[0].note if doc.pages else '')
        self.title_lbl.setToolTip((doc.path + ('\n' + note if note else '')))
        self._on_page_changed(0)
        self.apply_reader_theme(self._dark_mode)

    def _position_initial(self):
        try:
            screen = QApplication.primaryScreen().availableGeometry()
            self.move(screen.center().x() - self.width() // 2,
                      screen.center().y() - self.height() // 2)
        except Exception:
            pass

    @staticmethod
    def _prefs_kind(doc):
        return doc.kind if doc.kind in ('pdf', 'docx', 'pptx', 'sheet', 'text') else 'text'

    # ---- paging / translate plumbing ----
    def _on_page_changed(self, index):
        doc = self._doc
        total = len(doc.pages) if doc else 0
        label = doc.pages[index].label if doc and 0 <= index < total else ''
        self.page_lbl.setText('%d / %d' % (index + 1, total) if total > 1 else label)
        self.page_lbl.setToolTip(label)
        self.prev_btn.setEnabled(index > 0)
        self.next_btn.setEnabled(index < total - 1)
        self.panel.on_page_changed(index)

    def toggle_translate(self, show=None):
        show = (not self.panel.isVisible()) if show is None else bool(show)
        if show == self.panel.isVisible():
            return
        if show:
            self.panel.setVisible(True)
            doc = self._doc
            if doc is not None and doc.kind in ('pdf', 'docx', 'pptx'):
                # translation forces VERTICAL paging on the left (per spec)
                self._orientation_before_translate = self.view.orientation()
                self.view.set_orientation('vertical')
            self.panel.on_page_changed(self.view._current)
        else:
            self.panel.stop_workers()
            self.panel.setVisible(False)
            if self._orientation_before_translate is not None:
                self.view.set_orientation(self._orientation_before_translate)
                self._orientation_before_translate = None

    # ---- context menu ----
    def _show_reader_menu(self, global_pos):
        doc = self._doc
        menu = style_broccoli_context_menu(QMenu(self))
        pageable = doc is not None and doc.kind in ('pdf', 'docx', 'pptx')
        horiz_act = menu.addAction(_tr('Horizontal Paging'))
        vert_act = menu.addAction(_tr('Vertical Paging'))
        for act in (horiz_act, vert_act):
            act.setCheckable(True)
        horiz_act.setChecked(self.view.orientation() == 'horizontal')
        vert_act.setChecked(self.view.orientation() == 'vertical')
        translating = self.panel.isVisible()
        horiz_act.setEnabled(pageable and not translating)
        vert_act.setEnabled(pageable and not translating)
        default_act = menu.addAction(_tr('Set as Default for This File Type'))
        default_act.setEnabled(pageable)
        menu.addSeparator()
        panel_act = menu.addAction(_tr('Show Translation Panel'))
        panel_act.setCheckable(True)
        panel_act.setChecked(translating)
        auto_act = menu.addAction(_tr('Auto-translate New Pages'))
        auto_act.setCheckable(True)
        auto_act.setChecked(bool(self.panel.auto_translate))
        menu.addSeparator()
        reveal_act = menu.addAction(_tr('Reveal in Finder'))
        reveal_act.setEnabled(doc is not None and bool(doc.path))
        act = menu.exec(global_pos)
        if act == horiz_act:
            self.view.set_orientation('horizontal')
        elif act == vert_act:
            self.view.set_orientation('vertical')
        elif act == default_act:
            kind = self._prefs_kind(doc)
            # review fix: while the translation panel forces vertical, persist
            # the user's REAL orientation, not the forced one
            self._prefs.setdefault('orientation', {})[kind] = (
                self._orientation_before_translate or self.view.orientation())
            reader_prefs_save(self._prefs)
        elif act == panel_act:
            self.toggle_translate()
        elif act == auto_act:
            self.panel.auto_translate = not self.panel.auto_translate
            self._prefs['auto_translate'] = bool(self.panel.auto_translate)
            reader_prefs_save(self._prefs)
            # round 2: auto mode owns the pipeline — the manual button locks
            self.panel._update_controls()
            if self.panel.auto_translate and self.panel.isVisible():
                self.panel.on_page_changed(self.view._current)
        elif act == reveal_act:
            try:
                subprocess.Popen(['open', '-R', doc.path])
            except Exception:
                pass

    # ---- keys ----
    def keyPressEvent(self, event):
        if event.key() in (Qt.Key.Key_Left, Qt.Key.Key_PageUp):
            self.view.flip(-1)
            event.accept()
            return
        if event.key() in (Qt.Key.Key_Right, Qt.Key.Key_PageDown, Qt.Key.Key_Space):
            self.view.flip(1)
            event.accept()
            return
        super().keyPressEvent(event)

    def hideEvent(self, event):
        self.panel.stop_workers()
        super().hideEvent(event)

    # ---- theme ----
    def apply_reader_theme(self, dark_mode):
        self._dark_mode = bool(dark_mode)
        fg = '#F2F2F7' if self._dark_mode else '#20242B'
        muted = '#A7AEB8' if self._dark_mode else '#6A717C'
        self.title_lbl.setStyleSheet('color: %s; font-size: 14px; font-weight: 600; background: transparent;' % fg)
        self.page_lbl.setStyleSheet('color: %s; font-size: 12px; background: transparent;' % muted)
        for btn in (self.prev_btn, self.next_btn, self.translate_toggle, self.redock_btn):
            try:
                btn.apply_capsule_theme(self._dark_mode)
            except Exception:
                pass
        self.view.set_theme(self._dark_mode)
        self.panel.set_theme(self._dark_mode)
        self.update()

    # ---- window chrome (EditorWindow family) ----
    def paintEvent(self, event):
        painter = QPainter(self)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)
        rect = QRectF(self.rect())
        path = smooth_round_rect_path(rect, self.radius)
        painter.setClipPath(path)
        painter.fillPath(path, QColor('#2D2D2D') if self._dark_mode else QColor('#FFFFFF'))

    def _in_resize_corner(self, pos):
        return pos.x() >= self.width() - 22 and pos.y() >= self.height() - 22

    def mousePressEvent(self, event):
        if event.button() == Qt.MouseButton.LeftButton:
            pos = event.position().toPoint()
            if self._in_resize_corner(pos):
                self._resize_active = True
                self._resize_origin = event.globalPosition().toPoint()
                self._resize_start_geo = QRect(self.geometry())
                event.accept()
                return
            if pos.y() < 44 or self.childAt(pos) is None:
                self.drag_pos = event.globalPosition().toPoint() - self.frameGeometry().topLeft()
                event.accept()

    def mouseMoveEvent(self, event):
        pos = event.position().toPoint()
        if self._resize_active and (event.buttons() & Qt.MouseButton.LeftButton):
            delta = event.globalPosition().toPoint() - self._resize_origin
            geo = self._resize_start_geo
            self.setGeometry(geo.x(), geo.y(),
                             max(self.minimumWidth(), geo.width() + delta.x()),
                             max(self.minimumHeight(), geo.height() + delta.y()))
            event.accept()
            return
        if event.buttons() == Qt.MouseButton.LeftButton and self.drag_pos is not None:
            self.move(event.globalPosition().toPoint() - self.drag_pos)
            event.accept()
            return
        try:
            if self._in_resize_corner(pos):
                self.setCursor(Qt.CursorShape.SizeFDiagCursor)
            else:
                self.unsetCursor()
        except Exception:
            pass

    def mouseReleaseEvent(self, event):
        self.drag_pos = None
        self._resize_active = False
        self._resize_origin = None
        self._resize_start_geo = None
        try:
            self.unsetCursor()
        except Exception:
            pass
        super().mouseReleaseEvent(event)

# ===== Broccoli Reader Window — module END ======================


def _apply_window_palette(window, dark_mode):
    if window is None:
        return
    palette = window.palette()
    palette.setColor(window.backgroundRole(), QColor('#2D2D2D' if dark_mode else '#ECECEC'))
    window.setPalette(palette)


def apply_theme(app_obj):
    dark_mode = is_dark_theme(app_obj)
    if dark_mode:
        set_dark_palette(app_obj)
        app_obj.setStyleSheet(style_sheet_dark)
    else:
        set_light_palette(app_obj)
        app_obj.setStyleSheet(style_sheet_ori)

    target = globals().get('w3')
    if target is not None:
        _apply_window_palette(target, dark_mode)
        try:
            target.apply_theme(dark_mode)
        except Exception:
            pass
        ed = getattr(target, '_editor_window', None)
        if ed is not None:
            _apply_window_palette(ed, dark_mode)
            try:
                ed.apply_editor_theme(dark_mode)
            except Exception:
                pass
        reader = getattr(target, '_reader_window', None)   # FIX-39
        if reader is not None:
            _apply_window_palette(reader, dark_mode)
            try:
                reader.apply_reader_theme(dark_mode)
            except Exception:
                pass

    _apply_mac_button_theme()
    for widget in app_obj.topLevelWidgets():
        try:
            widget.update()
        except Exception:
            pass


theme_observer = install_theme_observer(app)


def _install_liquid_glass_surfaces():
    """Tier 1 windows get system Liquid Glass the first time they are shown (see
    install_window_liquid_glass): the frameless dialogs, the pop-up lists, the selection
    "ask" menu and the editor edit-permission panel. Badges, toast cards and translation
    buttons attach their own child glass."""
    def dialog_radius(widget):   # 59 → 26 like the system alert, 36 → 16 like a system panel
        return glass_corner_radius(getattr(widget, '_panel_radius', APPROVAL_DIALOG_SMOOTH_RADIUS), smooth=True)

    def dialog_inset(widget):
        return float(getattr(widget, '_panel_margin', 16))

    for cls in (BroccoliMessageDialog, AgentTerminalCommandApprovalDialog, ExperienceRuleDialog, MemoryEditDialog,
                ExternalMcpHttpDialog, ExternalMcpStdioDialog, ComputerUseApprovalDialog, TerminalFavoriteEditDialog,
                AppleNotesPickerDialog, CustomServicesDialog, ShareTextDialog, OnlineMemoryStatusDialog,
                MoveAndSendDeviceDialog):
        install_window_liquid_glass(cls, dialog_radius, dialog_inset)

    def opener_forces_dark(button):
        return bool(getattr(button, '_always_dark', False)) or bool(getattr(button, '_force_dark', False))

    for list_cls, opener_attr in ((DropdownPopup, 'parent_button'), (TargetSelectorPopup, 'parent_button'),
                                  (RankedSelectPopup, '_button')):
        # The system menu's own material: regular glass, untinted, system window shadow,
        # drawn active like the menu window's.
        install_window_liquid_glass(
            list_cls, GLASS_LIST_RADIUS, 0,
            dark_for=lambda w, a=opener_attr: opener_forces_dark(getattr(w, a, None)),
            keep_shadow=True, menu_look=True)
    # The selection "ask" menu: the same material as the system menu (it is one, summoned
    # from another app, so it stays a Broccoli window drawn with the menu's measurements).
    install_window_liquid_glass(SelectionAskMenuWindow, GLASS_LIST_RADIUS, 0, dark_attrs=(),
                                keep_shadow=True, menu_look=True)
    # About / Check for Updates / the thank-you (donation) cards: floating windows like the
    # dialogs, so the same window glass; they have no shadow margin, so the system window
    # shadow follows the rounded corners (menu_look sets the window's corner radius).
    for cls in (window_about, window_update, _DonationDialog):
        install_window_liquid_glass(cls, lambda w: glass_corner_radius(getattr(w, 'radius', 36), smooth=True), 0,
                                    keep_shadow=True, menu_look=True)
    # an approval: the dialogs' 16. Its glass fills the window (no margin for a soft shadow), so
    # like About it keeps the system shadow and gives the window itself the rounded corner —
    # whatever turns that shadow on, it follows the card (a square one showed at the corners).
    install_window_liquid_glass(EditorEditPermissionPanel,
                                lambda w: glass_corner_radius(getattr(w, '_smooth_panel_radius', APPROVAL_DIALOG_SMOOTH_RADIUS),
                                                              smooth=True), 0,
                                dark_attrs=('_force_dark',), keep_shadow=True, menu_look=True)


_install_liquid_glass_surfaces()


def install_plus_button_glass(bar_cls):
    """The round "+" (a plain QPushButton) of a site / session bar: a glass disc too."""
    original_show = bar_cls.showEvent

    def showEvent(self, event, _original=original_show):
        _original(self, event)
        button = getattr(self, '_plus_btn', None)
        if not isinstance(button, QPushButton) or getattr(button, '_broccoli_inwindow_glass', None) is not None:
            return
        base_qss = button.styleSheet()

        def on_glass_changed(active, b=button):
            if active:
                if not getattr(b, '_glass_plain_qss', None):
                    b._glass_plain_qss = b.styleSheet()
                b.setStyleSheet('QPushButton { background: transparent; border: none; }')
            elif getattr(b, '_glass_plain_qss', None):
                b.setStyleSheet(b._glass_plain_qss)
        button._on_inwindow_glass_changed = on_glass_changed
        button._glass_plain_qss = base_qss
        QTimer.singleShot(150, lambda b=button: install_inwindow_circle_glass(
            b, lambda w: QRect(QPoint(0, 0), w.size()), dark_for=lambda w: is_dark_theme(app)))
    bar_cls.showEvent = showEvent


install_plus_button_glass(WebNavBar)
install_plus_button_glass(TerminalSessionBar)
install_inwindow_bar_glass(AssistantBar, lambda w: is_dark_theme(app))
install_inwindow_bar_glass(TerminalInputBar, lambda w: True)
install_inwindow_bar_glass(TerminalSessionBar, lambda w: w._bar_bg.lightness() < 128)
# 2026-10-25: the same treatment everywhere else (it used to stop at the main window's bars).
install_inwindow_bar_glass(EditorActionBar, lambda w: is_dark_theme(app))
install_inwindow_bar_glass(EditorFileBar, lambda w: is_dark_theme(app))
install_inwindow_panel_glass(AgentPlanPanel, lambda w: w._panel_bg.lightness() < 128)
install_inwindow_panel_glass(AgentQueuePanel, lambda w: w._panel_bg.lightness() < 128)
install_inwindow_panel_glass(AssistantPromptPopup, lambda w: w._panel_bg.lightness() < 128)
# The tray is never hidden: its wrapper animates to height 0 and clips it. Its glass must
# cover only the part the wrapper lets show, or the full-size glass sat over (and below) the
# bottom bar while no file was attached.
install_inwindow_panel_glass(AttachmentTray, lambda w: bool(w._force_dark) or is_dark_theme(app),
                             radius_for=lambda w: glass_corner_radius(BAR_ACCESSORY_SMOOTH_RADIUS),   # 16 (was 14)
                             rect_for=glass_visible_part,
                             wanted_for=lambda w: not glass_visible_part(w).isEmpty())
# The editor's floating cards and their pager capsule. They slide inside the dock, which clips
# them, so (like the tray) only the part the dock shows is glass; a closing card fades out
# as its old self (glass cannot fade with a Qt opacity effect).
install_inwindow_panel_glass(EditorCardBody, lambda w: bool(getattr(w.parentWidget(), '_dark', False)),
                             radius_for=lambda w: glass_corner_radius(w._smooth_panel_radius, smooth=True),
                             rect_for=glass_visible_part,
                             wanted_for=lambda w: (not glass_visible_part(w).isEmpty()
                                                   and bool(getattr(w.parentWidget(), '_alive', True))))
install_inwindow_panel_glass(EditorCardDockBar, lambda w: bool(getattr(w.parentWidget(), '_dark', False)),
                             radius_for=lambda w: w.height() / 2.0,
                             rect_for=glass_visible_part,
                             wanted_for=lambda w: not glass_visible_part(w).isEmpty())
# Only the white-capsule family becomes Liquid Glass (the bottom bar's glass capsules were
# made from it): WhiteButton, and the drop-down / target buttons drawn as that capsule.
# The grey normal buttons (MacNormalButton, compact grey drop-downs) stay grey.
install_glass_button_class(WhiteButton)
install_glass_button_class(DropdownButton, when=lambda b: not b._compact_light and not b._always_dark)
install_glass_button_class(TargetSelectorButton, when=lambda b: not b._always_dark)


if __name__ == '__main__':
    if ICLOUD_M1A_SINGLE_INSTANCE_LOCK_ENABLED:
        _BROCCOLI_SINGLE_INSTANCE_LOCK = acquire_broccoli_single_instance_lock()
        if _BROCCOLI_SINGLE_INSTANCE_LOCK is None:
            logging.error('Another Broccoli instance already owns the local task and conversation store.')
            raise SystemExit(0)
        atexit.register(release_broccoli_single_instance_lock, _BROCCOLI_SINGLE_INSTANCE_LOCK)
    w1 = window_about()  # about
    w2 = window_update()  # update
    w3 = MyWidget()
    hotkey_manager = GlobalHotkeyManager()
    app.hotkey_manager = hotkey_manager
    w3.set_hotkey_manager(hotkey_manager)
    w3.setAutoFillBackground(True)
    action1.triggered.connect(w1.activate)
    action2.triggered.connect(w2.activate)
    action3.triggered.connect(w3.show_main_window_from_tray)
    action4.triggered.connect(w3.show_settings_panel)
    action7.triggered.connect(w3.toggle_show_on_all_spaces)
    action11.toggled.connect(w3.toggle_external_target_debug_page)
    action8.triggered.connect(w3.showhidedock)
    action10.triggered.connect(w3.toggle_start_on_login)
    w3.apply_show_on_all_spaces_settings(action7.isChecked())
    set_dock_icon_visible(action8.isChecked())
    btna4.triggered.connect(w3.pin_a_tab)
    btna_same_position_screenshot.triggered.connect(w3.capture_same_position_screenshot_and_send)
    hotkey_manager.ui_hotkey_pressed.connect(w3.pin_a_tab)
    hotkey_manager.same_position_screenshot_pressed.connect(w3.capture_same_position_screenshot_and_send)
    # FIX-45: the Screenshot shortcut = exactly what the 📸 Shot button does —
    # wake the capture overlay (which, per FIX-44/45, also revives a parked view)
    hotkey_manager.region_screenshot_pressed.connect(w3.start_region_capture)
    hotkey_manager.edge_toggle_pressed.connect(w3._toggle_edge_hide)
    app.aboutToQuit.connect(hotkey_manager.stop)
    hotkey_manager.start()
    # w3.btn0_2.clicked.connect(w3.transferview)
    quit.triggered.connect(w3.totalquit)
    apply_theme(app)
    # one-click update: drop the previous bundle / installers the last update left
    threading.Thread(target=broccoli_cleanup_update_leftovers, daemon=True,
                     name='broccoli-update-cleanup').start()
    app.exec()
    # one-click update: the bundles are swapped only now, after Qt has shut down
    # (no-op unless window_update staged an install right before quitting)
    broccoli_apply_pending_update_install()
